// Hyperrealist Watercolour & Charcoal Study:
// Oxblood Silk Pocket Square on Black Marquina Marble

const PAPER_HEX = "#fbf6ef";

// Domain curve tables & precomputed geometry
let marbleOuterCurve = [];
let d3Curves = [];
let d2Curves = [];
let d1Curves = [];
let foldUnits = [];
let hemStrips = [];

// Batched watercolor glaze queues for optimal p5.brush fill caching
let glazeBatches = {
  siennaBlush: [],    // #e05a28 - warm sunlit grazing glow
  siennaRich: [],     // #bd3410 - deep burnt sienna silk undertone
  alizarinVivid: [],  // #d90d2e - saturated ruby alizarin crimson
  alizarinDeep: [],   // #9e061f - classic deep alizarin
  oxbloodCore: [],    // #690313 - rich oxblood body shadow
  wineDark: [],       // #3d010a - hair's-width ridge shadow & deep creases
  ultramarine: [],    // #1b2870 - cool whisper of ultramarine in troughs
  violetTrough: []    // #2a134d - bruised plum-indigo trough transition
};

let charcoalPockets = [];
let ridgeContours = [];
let secondaryCreases = [];

// Smooth Catmull-Rom spline evaluator on control points
function evalSpline(pts, t) {
  t = constrain(t, 0, 1);
  let n = pts.length - 1;
  let f = t * n;
  let i = Math.min(Math.floor(f), n - 1);
  let lt = f - i;

  let p0 = pts[Math.max(0, i - 1)];
  let p1 = pts[i];
  let p2 = pts[Math.min(n, i + 1)];
  let p3 = pts[Math.min(n, i + 2)];

  let lt2 = lt * lt;
  let lt3 = lt2 * lt;

  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * lt +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * lt2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * lt3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * lt +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * lt2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * lt3
  );
  return [x, y];
}

function lerpPt(a, b, u) {
  return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u];
}

function distPt(a, b) {
  return Math.hypot(b[0] - a[0], b[1] - a[1]);
}

function normalPt(a, b) {
  let dx = b[0] - a[0];
  let dy = b[1] - a[1];
  let len = Math.hypot(dx, dy) || 1;
  return [-dy / len, dx / len];
}

