      index: i,
      ridgeBase: 0.44 + (i % 2 === 0 ? 0.06 : -0.05),
      crumpleAmp: 0.09,
      crumpleFreq: 2.1 + (i % 2) * 0.5,
      phase: i * 1.45 + 0.7,
