}

// Construct a parameterized Fold Unit between Trough A(t) and Trough B(t)
// Reserves bare paper along the ridge crest and batches watercolor glazes on both slopes
function createFoldUnit(curveA, curveB, opts) {
  let N = 28; // longitudinal resolution
  let samples = [];

  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let pA = evalSpline(curveA, t);
    let pB = evalSpline(curveB, t);
    let w = distPt(pA, pB);

    // Crumple wave & localized dog-leg buckle along the ridge
    let wave1 = Math.sin(t * Math.PI * 2 * opts.crumpleFreq + opts.phase);
    let wave2 = Math.cos(t * Math.PI * 4.2 + opts.phase * 1.7) * 0.45;
    let dogLeg = Math.sin(t * Math.PI * 3.0 + opts.index) * Math.exp(-Math.pow((t - 0.52) / 0.22, 2)) * 0.6;
    let sCrest = constrain(opts.ridgeBase + (wave1 * 0.7 + wave2 + dogLeg) * opts.crumpleAmp, 0.20, 0.78);

    // Transverse buckle pinch (where a cross-crease cuts across the ridge or narrows the highlight)
    let buckleMod = 0.55 + 0.45 * Math.sin(t * Math.PI * (2.5 + (opts.index % 2)) + opts.phase * 0.8);
    let endTaper = Math.pow(Math.sin(t * Math.PI), 0.45);
    if (opts.domain === 2 && t > 0.7) endTaper = 0.92; // stay open as folds spill off canvas edges
    if (opts.domain === 3 && t > 0.75) endTaper = 0.88;

    // Bare-paper highlight width in normalized u-coordinates (approx 3px to 12px in canvas space)
    let targetPx = (3.2 + 7.5 * buckleMod * opts.hiWidthScale) * endTaper;
    // Occasional complete pinch across a sharp transverse buckle in the central basin
    if (buckleMod < 0.24 && t > 0.22 && t < 0.78) {
      targetPx = 0.8;
    }

    let uHalf = constrain(targetPx / Math.max(w, 28), 0.012, 0.095);
    // Asymmetric silk sheen: wider on sunlit side (uL), razor-thin on shadow-drop side (uR)
    let uL = constrain(sCrest - uHalf * 1.25, 0.08, sCrest - 0.008);
    let uR = constrain(sCrest + uHalf * 0.55, sCrest + 0.006, 0.92);

    // Vertical silk billowing displacement perpendicular to fold chord
    let nrm = normalPt(pA, pB);
    let billow = Math.sin(t * Math.PI * 2.0 + opts.phase) * Math.min(w * 0.08, 9);

    function ptAt(u) {
      let base = lerpPt(pA, pB, u);
      let arch = Math.sin(u * Math.PI) * billow;
      return [base[0] + nrm[0] * arch, base[1] + nrm[1] * arch];
    }

    samples.push({
      t,
      pA,
      pB,
      w,
      sCrest,
      uL,
      uR,
      buckleMod,
      ptAt,
      pCrest: ptAt(sCrest),
      pHiL: ptAt(uL),
      pHiR: ptAt(uR)
    });
  }

  foldUnits.push({ samples, opts });

  // Store ridge contour data for razor-sharp wine-dark shadow edges & silk shimmer
  ridgeContours.push({ samples, opts });

  // Slice into longitudinal glaze segments (each spanning 4 sample steps for smooth polygons)
  let segStep = 4;
  for (let i = 0; i < N; i += segStep) {
    let iEnd = Math.min(N, i + segStep);
    let tMid = ((i + iEnd) * 0.5) / N;
    let sMid = samples[Math.floor((i + iEnd) * 0.5)];
    let isDeepBasin = sMid.buckleMod < 0.52;
    let isRootShadow = (opts.hasTopOverhangShadow && tMid < 0.16) ||
                       (opts.hasRootOverhangShadow && tMid < 0.20);

    // Helper to build a smooth closed polygon strip between fractional u0(s) and u1(s)
    // where u0Fn and u1Fn map sample s -> u in [0, 1]
    function makeStripPoly(u0Fn, u1Fn) {
      let poly = [];
      for (let k = i; k <= iEnd; k++) {
        poly.push(samples[k].ptAt(u0Fn(samples[k])));
      }
      for (let k = iEnd; k >= i; k--) {
        poly.push(samples[k].ptAt(u1Fn(samples[k])));
      }
      return poly;
    }

    // --- LEFT SLOPE (u from 0 up to uL: Trough A rising to sunlit edge of Bare-Paper Highlight) ---
    // 1. Trough A cool ultramarine + oxblood base (u: 0 -> 0.42 * uL)
    glazeBatches.oxbloodCore.push(makeStripPoly(s => 0, s => s.uL * 0.48));
    if (isDeepBasin || (opts.index + i) % 2 === 0) {
      glazeBatches.ultramarine.push(makeStripPoly(s => 0, s => s.uL * 0.36));
    } else {
      glazeBatches.violetTrough.push(makeStripPoly(s => 0, s => s.uL * 0.32));
    }

    // 2. Mid-slope vivid Alizarin Crimson (u: 0.18 * uL -> 0.86 * uL)
    glazeBatches.alizarinDeep.push(makeStripPoly(s => s.uL * 0.15, s => s.uL * 0.72));
    glazeBatches.alizarinVivid.push(makeStripPoly(s => s.uL * 0.32, s => s.uL * 0.90));

    // 3. Sunlit grazing slope Burnt Sienna right up to bare-paper highlight (u: 0.55 * uL -> 0.985 * uL)
    glazeBatches.siennaRich.push(makeStripPoly(s => s.uL * 0.52, s => s.uL * 0.93));
    glazeBatches.siennaBlush.push(makeStripPoly(s => s.uL * 0.74, s => s.uL * 0.985));

    // Extra woven border band warm glaze if applicable
    if ((opts.hasBorderBand && tMid > 0.1) || (opts.hasEndBorderBand && tMid > 0.78 && tMid < 0.92)) {
      glazeBatches.siennaRich.push(makeStripPoly(s => s.uL * 0.25, s => s.uL * 0.96));
    }

    // --- RIGHT SLOPE (u from uR to 1: Hair's-Width drop from Bare-Paper Highlight into Wine-Dark Shadow & Trough B) ---
    //Notice: u in [uL, uR] is 100% UNTOUCHED BARE PAPER!
    // 1. Immediate hair's-width wine-dark core shadow hugging uR (u: uR + 0.004 -> uR + 0.34*(1 - uR))
    glazeBatches.wineDark.push(makeStripPoly(
      s => s.uR + 0.004,
      s => s.uR + (1 - s.uR) * 0.36
    ));

    // 2. Steep shadow wall Oxblood & Deep Alizarin (u: uR + 0.02 -> uR + 0.78*(1 - uR))
    glazeBatches.oxbloodCore.push(makeStripPoly(
      s => s.uR + 0.015,
      s => s.uR + (1 - s.uR) * 0.72
    ));
    glazeBatches.alizarinDeep.push(makeStripPoly(
      s => s.uR + (1 - s.uR) * 0.22,
      s => s.uR + (1 - s.uR) * 0.88
    ));
    if (!isDeepBasin) {
      glazeBatches.alizarinVivid.push(makeStripPoly(
        s => s.uR + (1 - s.uR) * 0.35,
        s => s.uR + (1 - s.uR) * 0.75
      ));
    }

    // 3. Trough B whisper of Ultramarine & deep fold interior (u: uR + 0.58*(1 - uR) -> 1.0)
    glazeBatches.ultramarine.push(makeStripPoly(
      s => s.uR + (1 - s.uR) * 0.60,
      s => 1.0
    ));
    glazeBatches.wineDark.push(makeStripPoly(
      s => s.uR + (1 - s.uR) * 0.74,
      s => 1.0
    ));

    // Overhang cast shadow at the root of Domain 1 or Domain 2
    if (isRootShadow) {
      glazeBatches.wineDark.push(makeStripPoly(s => 0, s => s.uL * 0.92));
      glazeBatches.wineDark.push(makeStripPoly(s => s.uR + 0.005, s => 1.0));
    }

    // 4. Deep fold interior pockets for velvety dry charcoal mass
    if ((isDeepBasin && tMid > 0.12 && tMid < 0.88) || isRootShadow) {
      charcoalPockets.push({
        poly: makeStripPoly(
          s => s.uR + (1 - s.uR) * 0.68,
          s => 1.0
        ),
        isDeepest: isRootShadow || (sMid.buckleMod < 0.35)
      });
    }

    // 5. Secondary diagonal crumple creases (crow's-feet shooting off the ridge at buckles)
    if (i > 0 && i < N - segStep && (i / segStep + opts.index) % 2 === 0) {
      let s0 = samples[i];
      let s1 = samples[Math.min(N, i + 3)];
      secondaryCreases.push({
        pStart: s0.ptAt(s0.uR + 0.02),
        pMid: samples[i + 1].ptAt(samples[i + 1].uR + (1 - samples[i + 1].uR) * 0.45),
        pEnd: s1.ptAt(s1.uR + (1 - s1.uR) * 0.88),
        side: "right"
      });
      secondaryCreases.push({
        pStart: s0.ptAt(s0.uL * 0.92),
        pMid: samples[i + 1].ptAt(samples[i + 1].uL * 0.52),
        pEnd: s1.ptAt(s1.uL * 0.12),
        side: "left"
      });
    }
  }
}

// Helper to draw a closed polygon with p5.brush beginShape/vertex/endShape
function drawBrushPoly(pts, curvature = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(CLOSE);
}

// Point-in-Marble check: tests whether (x, y) is outside the silk pocket square silhouette
function isPointInMarble(x, y, margin = 3) {
  if (x < -30 || x > 1230 || y < -30 || y > 1230) return false;
  // Find closest point on marbleOuterCurve and check signed normal side
  let minD2 = Infinity;
  let bestIdx = 0;
  for (let i = 0; i < marbleOuterCurve.length; i++) {
    let dx = x - marbleOuterCurve[i][0];
    let dy = y - marbleOuterCurve[i][1];
    let d2 = dx * dx + dy * dy;
    if (d2 < minD2) {
      minD2 = d2;
      bestIdx = i;
    }
  }
  if (Math.sqrt(minD2) < margin) return false;

  // Reference point deep inside the silk is (950, 950)
  let p = marbleOuterCurve[bestIdx];
  let pNext = marbleOuterCurve[Math.min(marbleOuterCurve.length - 1, bestIdx + 1)];
  let pPrev = marbleOuterCurve[Math.max(0, bestIdx - 1)];
  let tx = pNext[0] - pPrev[0];
  let ty = pNext[1] - pPrev[1];
  // Cross product comparison against interior reference (950, 950)
  let crossPt = tx * (y - p[1]) - ty * (x - p[0]);
  let crossRef = tx * (950 - p[1]) - ty * (950 - p[0]);
  return (crossPt * crossRef) < 0;
}

function distToSilkEdge(x, y) {
  let minD2 = Infinity;
  for (let i = 0; i < marbleOuterCurve.length; i++) {
    let dx = x - marbleOuterCurve[i][0];
    let dy = y - marbleOuterCurve[i][1];
    let d2 = dx * dx + dy * dy;
    if (d2 < minD2) minD2 = d2;
  }
  return Math.sqrt(minD2);
}

// STAGE 1: Render Cool Matte Black Marquina Marble Slab & Pencil Veins
function renderMarquinaMarble() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Project marbleOuterCurve points outward to the top and left canvas borders
  let N = marbleOuterCurve.length - 1;
  let outerBorderPts = [];
  for (let i = 0; i <= N; i++) {
    let f = i / N;
    let p = marbleOuterCurve[i];
    // Smoothly map along top edge (1230, -30) -> (-30, -30) -> (-30, 1230) -> (356, 1230)
    let bx, by;
    if (f < 0.36) {
      let u = f / 0.36;
      bx = lerp(1230, -30, u);
      by = -30;
    } else if (f < 0.90) {
      let u = (f - 0.36) / 0.54;
      bx = -30;
      by = lerp(-30, 1230, u);
    } else {
      let u = (f - 0.90) / 0.10;
      bx = lerp(-30, p[0] - 12, u);
      by = 1230;
    }
    outerBorderPts.push([bx, by]);
  }

  // 1A. Solid matte dark slate-charcoal wash across the marble region in clean quad slices
  let step = 4;
  brush.wash("#13161c", 242);
  for (let i = 0; i < N; i += step) {
    let j = Math.min(N, i + step);
    let poly = [];
    for (let k = i; k <= j; k++) poly.push(marbleOuterCurve[k]);
    for (let k = j; k >= i; k--) poly.push(outerBorderPts[k]);
    drawBrushPoly(poly, 0.05);
  }
  brush.noWash();

  // 1B. Layered cool matte watercolor washes for subtle mineral depth
  brush.fillBleed(0.04, "in");
  brush.fillTexture(0.45, 0.18);

  let marbleTones = [
    { col: "#181d25", op: 110, r0: 0.0, r1: 0.55 },
    { col: "#0e1116", op: 125, r0: 0.25, r1: 1.0 },
    { col: "#1c222b", op: 85,  r0: 0.1, r1: 0.85 }
  ];

  for (let tone of marbleTones) {
    brush.fill(tone.col, tone.op);
    for (let i = 0; i < N; i += 8) {
      let j = Math.min(N, i + 8);
      let poly = [];
      for (let k = i; k <= j; k++) {
        poly.push(lerpPt(marbleOuterCurve[k], outerBorderPts[k], tone.r0));
      }
      for (let k = j; k >= i; k--) {
        poly.push(lerpPt(marbleOuterCurve[k], outerBorderPts[k], tone.r1));
      }
      drawBrushPoly(poly, 0.15);
    }
  }

  // 1C. Hushed Cast Shadow of the Silk Pocket Square onto the Marble Slab
  // Wider under the lifted corners, tighter where the hem rests flat
  function shadowWidthFactor(idx) {
    let p = marbleOuterCurve[idx];
    let dCorner1 = Math.hypot(p[0] - 192, p[1] - 326);
    let dCorner2 = Math.hypot(p[0] - 138, p[1] - 652);
    let dTopPeak = Math.hypot(p[0] - 470, p[1] - 147);
    let lift = Math.exp(-dCorner1 / 95) * 0.09 +
               Math.exp(-dCorner2 / 110) * 0.11 +
               Math.exp(-dTopPeak / 85) * 0.06;
    return 0.045 + lift;
  }

  // Warm oxblood subsurface glow right at the contact edge (0 -> 35% of shadow width)
  brush.fill("#26050c", 130);
  for (let i = 0; i < N; i += 6) {
    let j = Math.min(N, i + 6);
    let poly = [];
    for (let k = i; k <= j; k++) poly.push(marbleOuterCurve[k]);
    for (let k = j; k >= i; k--) {
      poly.push(lerpPt(marbleOuterCurve[k], outerBorderPts[k], shadowWidthFactor(k) * 0.42));
    }
    drawBrushPoly(poly, 0.12);
  }

  // Deep cool charcoal-indigo cast shadow (0 -> 100% of shadow width)
  brush.fill("#07090d", 165);
  for (let i = 0; i < N; i += 6) {
    let j = Math.min(N, i + 6);
    let poly = [];
    for (let k = i; k <= j; k++) poly.push(marbleOuterCurve[k]);
    for (let k = j; k >= i; k--) {
      poly.push(lerpPt(marbleOuterCurve[k], outerBorderPts[k], shadowWidthFactor(k)));
    }
    drawBrushPoly(poly, 0.15);
  }
  brush.noFill();

  // 1D. Matte honed stone grain (fine pencil & charcoal cross-strokes strictly in marble)
  for (let m = 0; m < 420; m++) {
    let x = random(-10, 1180);
    let y = random(-10, 1180);
    if (!isPointInMarble(x, y, 16)) continue;
    let ang = -28 + random(-12, 12);
    let len = random(18, 55);
    let x2 = x + cos(ang) * len;
    let y2 = y + sin(ang) * len;
    if (!isPointInMarble(x2, y2, 16)) continue;

    let col = m % 3 === 0 ? "#212630" : (m % 3 === 1 ? "#0c0e12" : "#181c24");
    brush.set("2H", col, random(0.45, 0.85));
    brush.line(x, y, x2, y2);
  }

  // 1E. Fine Grey Pencil Calcite Veins (characteristic of Nero Marquina marble)
  let mainVeins = [
    [[-20, 115], [140, 155], [295, 195], [445, 168], [520, 130], [640, 65], [760, -20]],
    [[-20, 445], [85, 410], [185, 365], [240, 320]],
    [[95, -20], [135, 120], [168, 255], [132, 395], [75, 535], [-20, 680]],
    [[-20, 815], [75, 775], [155, 735], [225, 765], [185, 895], [115, 1045], [45, 1225]],
    [[340, -20], [415, 62], [485, 118], [595, 142], [745, 112], [925, 148], [1095, 95], [1225, 45]],
    [[-20, 995], [95, 965], [195, 945], [245, 1020], [295, 1135], [325, 1225]],
    [[790, -20], [845, 65], [925, 115], [1035, 152], [1155, 162]]
  ];

  for (let vIdx = 0; vIdx < mainVeins.length; vIdx++) {
    let vPts = mainVeins[vIdx];
    drawMarbleVeinSystem(vPts, 1.0);

    // Secondary branching capillaries off each main vein
    for (let b = 0; b < 4; b++) {
      let tStart = random(0.15, 0.82);
      let p0 = evalSpline(vPts, tStart);
      let branchPts = [p0];
      let cur = [p0[0], p0[1]];
      let dir = random(-65, 75) + (vIdx % 2 === 0 ? 25 : -35);
      for (let s = 0; s < 5; s++) {
        dir += random(-28, 28);
        let stepLen = random(28, 68);
        cur = [cur[0] + cos(dir) * stepLen, cur[1] + sin(dir) * stepLen];
        branchPts.push(cur);
      }
      drawMarbleVeinSystem(branchPts, 0.52);
    }
  }
}

function drawMarbleVeinSystem(ctrlPts, scaleWeight) {
  let steps = 68;
  let prev = null;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let base = evalSpline(ctrlPts, t);
    // Geological micro-stepping (calcite fracture jitter)
    let jx = (noise(base[0] * 0.025, base[1] * 0.025) - 0.5) * 14 * scaleWeight;
    let jy = (noise(base[0] * 0.025 + 99, base[1] * 0.025 + 99) - 0.5) * 14 * scaleWeight;
    let cur = [base[0] + jx, base[1] + jy];

    if (prev && isPointInMarble(prev[0], prev[1], 3.5) && isPointInMarble(cur[0], cur[1], 3.5)) {
      let dEdge = distToSilkEdge(cur[0], cur[1]);
      let inShadow = dEdge < 42;

      // Primary grey pencil vein core
      let coreCol = inShadow ? "#383e47" : (scaleWeight > 0.7 ? "#9aa3b2" : "#6c7482");
      let w = (0.45 + 0.55 * sin(t * 180)) * scaleWeight;
      brush.set("2H", coreCol, w);
      brush.line(prev[0], prev[1], cur[0], cur[1]);

      // Braided parallel crystalline pencil thread & subtle dark border fissure
      if (scaleWeight > 0.65 && i % 2 === 0) {
        let offX = random(-3.2, 3.2);
        let offY = random(-3.2, 3.2);
        let highlightCol = inShadow ? "#4c5360" : "#c0c8d6";
        brush.set("cpencil", highlightCol, w * 0.55);
        brush.line(prev[0] + offX, prev[1] + offY, cur[0] + offX, cur[1] + offY);
      }
    }
    prev = cur;
  }
}

// STAGE 2: Execute Batched Transparent Watercolour Glazes on the Silk
function renderSilkWatercolourGlazes() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Controlled inward bleed keeps every bare-paper ridge highlight razor-sharp
  brush.fillBleed(0.032, "in");
  brush.fillTexture(0.52, 0.34);

  // Layer 1: Warm Burnt Sienna under-glazes on sunlit slopes
  brush.fill("#e05a28", 62);
  for (let poly of glazeBatches.siennaBlush) drawBrushPoly(poly, 0.22);

  brush.fill("#bd3410", 78);
  for (let poly of glazeBatches.siennaRich) drawBrushPoly(poly, 0.22);

  // Layer 2: Vivid & Deep Alizarin Crimson body glazes
  brush.fill("#d90d2e", 82);
  for (let poly of glazeBatches.alizarinVivid) drawBrushPoly(poly, 0.22);

  brush.fill("#a10620", 88);
  for (let poly of glazeBatches.alizarinDeep) drawBrushPoly(poly, 0.22);

  // Layer 3: Second pass of Vivid Alizarin on mid-slopes for jewel-like saturation
  brush.fill("#e31235", 58);
  for (let k = 0; k < glazeBatches.alizarinVivid.length; k += 2) {
    drawBrushPoly(glazeBatches.alizarinVivid[k], 0.2);
  }

  // Layer 4: Rich Oxblood shadow glazes
  brush.fill("#660313", 92);
  for (let poly of glazeBatches.oxbloodCore) drawBrushPoly(poly, 0.2);

  // Layer 5: Whisper of Ultramarine & Bruised Violet in the Troughs
  brush.fill("#2a134d", 64);
  for (let poly of glazeBatches.violetTrough) drawBrushPoly(poly, 0.22);

  brush.fill("#192873", 58);
  for (let poly of glazeBatches.ultramarine) drawBrushPoly(poly, 0.22);

  // Layer 6: Wine-Dark Core Shadow (sits within a hair's width of the bare-paper highlights)
  brush.fill("#3b010a", 102);
  for (let poly of glazeBatches.wineDark) drawBrushPoly(poly, 0.18);

  brush.noFill();
}

// STAGE 3: Velvety Charcoal Mass in Deep Fold Interiors
function renderDeepCharcoalInteriors() {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();

  // Pass 1: Deep wine-black charcoal mass across recessed fold interiors
  brush.mass("charcoal", "#170207", {
    precision: 0.72,
    strength: 0.78,
    gradient: 0.65,
    outline: false
  });
  for (let item of charcoalPockets) {
    drawBrushPoly(item.poly, 0.2);
  }
  brush.noMass();

  // Pass 2: Pure velvety charcoal-black core in the deepest pinched crevices
  brush.mass("charcoal", "#0a0104", {
    precision: 0.68,
    strength: 0.92,
    gradient: 0.55,
    outline: false
  });
  for (let item of charcoalPockets) {
    if (item.isDeepest) {
      drawBrushPoly(item.poly, 0.18);
    }
  }
  brush.noMass();
}

// STAGE 4: Hair's-Width Highlight-to-Shadow Transitions, Secondary Crumples & Silk Sheen
function renderSilkRidgesAndMicroSheen() {
  brush.noFill();
  brush.noHatch();
  brush.noMass();

  for (let r of ridgeContours) {
    let samples = r.samples;
    let N = samples.length - 1;

    // 4A. The Hair's-Width Drop: Razor-sharp wine-dark shadow edge immediately bordering pHiR
    let shadowEdgePts = [];
    let shadowMidPts = [];
    let sunlitEdgePts = [];
    let troughLinePts = [];

    for (let i = 0; i <= N; i++) {
      let s = samples[i];
      // Offset by a hair's width (uR + 0.004) so the bare paper highlight [uL, uR] stays pure
      let pRazor = s.ptAt(s.uR + 0.004);
      let pSub = s.ptAt(s.uR + (1 - s.uR) * 0.08);
      let pSun = s.ptAt(s.uL * 0.96);
      let pTrough = s.ptAt(s.uR + (1 - s.uR) * 0.86);

      shadowEdgePts.push([pRazor[0], pRazor[1], 0.55 + 0.45 * s.buckleMod]);
      shadowMidPts.push([pSub[0], pSub[1], 0.4 + 0.5 * s.buckleMod]);
      sunlitEdgePts.push([pSun[0], pSun[1], 0.35 + 0.45 * s.buckleMod]);
      troughLinePts.push([pTrough[0], pTrough[1], 0.85 - 0.35 * s.buckleMod]);
    }

    // Soft oxblood glaze cushion just behind the razor edge
    brush.set("silk_glaze", "#6e0415", 0.95);
    brush.spline(shadowMidPts, 0.35);

    // Intense wine-dark razor edge within a hair's width of the bare-paper highlight
    brush.set("razor_wine", "#360109", 0.92);
    brush.spline(shadowEdgePts, 0.35);

    brush.set("rotring", "#240006", 0.58);
    brush.spline(shadowEdgePts, 0.35);

    // Warm Burnt Sienna & Alizarin blush along the sunlit side of the highlight
    brush.set("silk_glaze", "#d94318", 0.65);
    brush.spline(sunlitEdgePts, 0.35);

    brush.set("cpencil", "#c70d2b", 0.55);
    brush.spline(sunlitEdgePts, 0.35);

    // Cool ultramarine + velvety charcoal shading in the deep trough line
    brush.set("silk_glaze", "#192466", 0.72);
    brush.spline(troughLinePts, 0.35);

    brush.set("velvet_charcoal", "#120206", 0.68);
    brush.spline(troughLinePts, 0.35);

    // 4B. Fine Anisotropic Silk Weave Micro-Filaments & Shimmer along the Ridge
    for (let i = 1; i < N; i++) {
      let s0 = samples[i - 1];
      let s1 = samples[i];
      let sNext = samples[i + 1];

      // Tiny cross-fiber catchlights on the steep shadow border (gives woven silk texture)
      if (i % 2 === 0) {
        let pA = s0.ptAt(s0.uR + 0.003);
        let pB = s1.ptAt(s1.uR + (1 - s1.uR) * 0.14);
        brush.set("silk_sheen", "#590312", 0.52);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }

      // Delicate pale sienna-rose silk thread glints inside pinched highlight transitions
      if (s1.buckleMod < 0.42 || i % 3 === 0) {
        let pH0 = s0.ptAt(lerp(s0.uL, s0.uR, 0.22));
        let pH1 = s1.ptAt(lerp(s1.uL, s1.uR, 0.28));
        brush.set("silk_sheen", "#f2b8ad", 0.32);
        brush.line(pH0[0], pH0[1], pH1[0], pH1[1]);
      }

      // Rich tonal contour modeling across the belly of the fold
      for (let m = 1; m <= 3; m++) {
        let frac = m / 4;
        // Left sunlit slope modeling
        let uLeft = s1.uL * (0.22 + frac * 0.65);
        let q0 = s0.ptAt(uLeft);
        let q1 = sNext.ptAt(sNext.uL * (0.22 + frac * 0.65));
        let colL = m === 1 ? "#8a061c" : (m === 2 ? "#c70e2c" : "#cf3d15");
        brush.set("cpencil", colL, 0.42);
        brush.line(q0[0], q0[1], q1[0], q1[1]);

        // Right shadow wall modeling
        let uRight = s1.uR + (1 - s1.uR) * (0.12 + frac * 0.68);
        let r0 = s0.ptAt(uRight);
        let r1 = sNext.ptAt(sNext.uR + (1 - sNext.uR) * (0.12 + frac * 0.68));
        let colR = m === 1 ? "#4a020d" : (m === 2 ? "#6e0516" : "#1c1f54");
        brush.set("cpencil", colR, 0.45);
        brush.line(r0[0], r0[1], r1[0], r1[1]);
      }
    }
  }

  // 4C. Render Secondary Diagonal Crumple Creases (Pinch Diamonds & Crow's-Feet)
  for (let sc of secondaryCreases) {
    let colCore = sc.side === "right" ? "#300108" : "#780518";
    let colGlow = sc.side === "right" ? "#6b0415" : "#c93814";

    brush.set("silk_glaze", colGlow, 0.55);
    brush.spline([
      [sc.pStart[0], sc.pStart[1], 0.3],
      [sc.pMid[0], sc.pMid[1], 0.85],
      [sc.pEnd[0], sc.pEnd[1], 0.25]
    ], 0.4);

    brush.set("razor_wine", colCore, 0.52);
    brush.spline([
      [sc.pStart[0], sc.pStart[1], 0.4],
      [sc.pMid[0], sc.pMid[1], 0.9],
      [sc.pEnd[0], sc.pEnd[1], 0.2]
    ], 0.4);
  }
}

// STAGE 5: Render Plump Hand-Rolled Hems (*Roulotté*) with Stitch Puckers & Bare-Paper Puffs
function renderRolledHems() {
  for (let hem of hemStrips) {
    let M = hem.steps;
    let ptsOuter = [];
    let ptsCrestL = [];
    let ptsCrestR = [];
    let ptsInner = [];

    for (let i = 0; i <= M; i++) {
      let t = i / M;
      let pOut = evalSpline(hem.outer, t);
      let pIn = evalSpline(hem.inner, t);

      // Subtle hand-stitched pucker wave every 2 steps along the rolled edge
      let pucker = Math.sin(i * Math.PI * 0.85) * 1.4;
      let nrm = normalPt(pOut, pIn);
      pOut = [pOut[0] + nrm[0] * pucker, pOut[1] + nrm[1] * pucker];

      ptsOuter.push(pOut);
      // Reserve bare-paper highlight ribbon along [0.20, 0.42] of the tubular hem
      ptsCrestL.push(lerpPt(pOut, pIn, 0.20));
      ptsCrestR.push(lerpPt(pOut, pIn, 0.44));
      ptsInner.push(pIn);
    }

    // Glaze the outer lip (0 -> 0.20) in warm Burnt Sienna + Alizarin
    brush.noStroke();
    brush.fillBleed(0.02, "in");
    brush.fill("#b82914", 88);
    for (let i = 0; i < M; i += 4) {
      let j = Math.min(M, i + 4);
      let poly = [];
      for (let k = i; k <= j; k++) poly.push(ptsOuter[k]);
      for (let k = j; k >= i; k--) poly.push(ptsCrestL[k]);
      drawBrushPoly(poly, 0.15);
    }

    // Glaze the underside of the roll (0.44 -> 1.0) in deep Wine-Dark shadow
    brush.fill("#3d010b", 112);
    for (let i = 0; i < M; i += 4) {
      let j = Math.min(M, i + 4);
      let poly = [];
      for (let k = i; k <= j; k++) poly.push(ptsCrestR[k]);
      for (let k = j; k >= i; k--) poly.push(ptsInner[k]);
      drawBrushPoly(poly, 0.15);
    }
    brush.noFill();

    // Draw the razor-sharp wine-dark shadow line right under the bare-paper hem puffs,
    // plus tiny diagonal hand-stitch dimples every 2 segments
    for (let i = 0; i < M; i++) {
      // Outer crisp contour against the marble or underlying silk
      brush.set("razor_wine", "#2b0107", 0.68);
      brush.line(ptsOuter[i][0], ptsOuter[i][1], ptsOuter[i + 1][0], ptsOuter[i + 1][1]);

      // Hair's-width wine-dark drop right below the bare-paper highlight puff on the hem
      brush.set("razor_wine", "#38010a", 0.78);
      brush.line(ptsCrestR[i][0], ptsCrestR[i][1], ptsCrestR[i + 1][0], ptsCrestR[i + 1][1]);

      // Deep inner seam crease (and overhang cast shadow if interior hem)
      brush.set("velvet_charcoal", "#120105", hem.isInterior ? 0.95 : 0.62);
      brush.line(ptsInner[i][0], ptsInner[i][1], ptsInner[i + 1][0], ptsInner[i + 1][1]);

      // Hand-rolled stitch dimples bridging across the roll every 2 steps
      if (i % 2 === 0) {
        let pDimple0 = lerpPt(ptsOuter[i], ptsInner[i], 0.18);
        let pDimple1 = lerpPt(ptsOuter[i + 1], ptsInner[i + 1], 0.85);
        brush.set("rotring", "#4f020e", 0.48);
        brush.line(pDimple0[0], pDimple0[1], pDimple1[0], pDimple1[1]);
      }
    }
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm archival cotton watercolour paper ground (left bare on all silk ridge highlights)
  background(PAPER_HEX);

  // 1. Cool matte Black Marquina marble slab & fine grey pencil veins
  renderMarquinaMarble();

  // 2. Multi-layered transparent watercolour glazes (Alizarin, Burnt Sienna, Ultramarine troughs)
  renderSilkWatercolourGlazes();

  // 3. Soft charcoal-like mass in the deep fold interiors for velvety black depth
  renderDeepCharcoalInteriors();

  // 4. Hair's-width bare-paper-to-wine-dark ridge transitions, secondary crumples & silk sheen
  renderSilkRidgesAndMicroSheen();

  // 5. Hand-rolled hems (*roulotté*) with stitch puckers and overhanging seam shadows
  renderRolledHems();

  noLoop();
}

const RAD = Math.PI / 180;

