// ============================================================================
// GEOMETRY & PROJECTION HELPERS
// ============================================================================

function ellipsePts(cx, cy, rx, ry, n = 72, rotDeg = 0, wobble = 0) {
  let pts = [];
  let cr = Math.cos(rotDeg * RAD);
  let sr = Math.sin(rotDeg * RAD);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let rMod = wobble > 0 ? 1 + (noise(cx * 0.01 + Math.cos(a) * 1.7, cy * 0.01 + Math.sin(a) * 1.7) - 0.5) * wobble : 1;
    let lx = Math.cos(a) * rx * rMod;
    let ly = Math.sin(a) * ry * rMod;
    pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
  }
  return pts;
}

function arcPts(cx, cy, rx, ry, startDeg, endDeg, n = 40, rotDeg = 0) {
  let pts = [];
  let cr = Math.cos(rotDeg * RAD);
  let sr = Math.sin(rotDeg * RAD);
  for (let i = 0; i <= n; i++) {
    let a = (startDeg + (endDeg - startDeg) * (i / n)) * RAD;
    let lx = Math.cos(a) * rx;
    let ly = Math.sin(a) * ry;
    pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
  }
  return pts;
}

function polyWash(pts, col, op = 220) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.wash(col, op);
}

function polyFill(pts, col, op = 140, bleed = 0.12, tex = 0.25) {
  if (!pts || pts.length < 3) return;
  let p = new brush.Polygon(pts);
  p.fill(col, op, bleed, tex);
}

function polyHatch(pts, bName, col, weight, dist, angle, opts = { rand: 0.04 }) {
  if (!pts || pts.length < 3) return;
  brush.hatchStyle(bName, col, weight);
  let p = new brush.Polygon(pts);
  p.hatch(dist, angle, opts);
  brush.noHatch();
}

function drawSpline(pts, bName, col, weight = 1, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(bName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curv);
  }
}

// 3D Spherical-Turned Profile of the Khokhloma Bowl
// uDeg: azimuth angle around front of bowl (-95 to +95, 0 = front center)
// v: normalized vertical profile from outer lip (0.0) to foot ring base (1.0)
function bowlProfile(v) {
  let vc = constrain(v, 0, 1.12);
  let rx, ry, yOff;
  if (vc <= 1.0) {
    // Bulbous traditional Russian wooden bowl profile
    let swell = Math.sin(vc * Math.PI) * 34 * Math.pow(1 - vc * 0.55, 0.8);
    let taper = Math.pow(vc, 1.78);
    rx = RIM_RX * (1 - 0.535 * taper) + swell;
    ry = RIM_RY * (1 - 0.635 * taper) + swell * 0.52;
    yOff = 296 * Math.pow(vc, 0.92) + 28 * Math.sin(vc * Math.PI * 0.88);
  } else {
    // Turned wooden foot ring (v in 1.0 .. 1.12)
    let fv = (vc - 1.0) / 0.12;
    rx = RIM_RX * 0.465 + fv * 6;
    ry = RIM_RY * 0.365 + fv * 4;
    yOff = 312 + fv * 22;
  }
  return { rx, ry, cy: CY + yOff };
}

function bowlPt(uDeg, v) {
  let prof = bowlProfile(v);
  let uRad = uDeg * RAD;
  return [
    CX + prof.rx * Math.sin(uRad),
    prof.cy + prof.ry * Math.cos(uRad)
  ];
}

// Local tangent basis on the bowl surface for accurate perspective foreshortening
function bowlLocalPt(uDeg, v, duDeg, dv) {
  return bowlPt(uDeg + duDeg, v + dv);
}

// ============================================================================
// MAIN DRAW
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background("#050203");
  brush.noField();

  // 1. Deep Wintry Ground & Black Lacquered Tray
  drawLacquerTray();

  // 2. Submerged Bowl Reflection & Shadow on the Tray
  drawBowlTrayReflection();

  // 3. Khokhloma Bowl Exterior: Black Lacquer Ground, Gold Bands & Scrollwork
  drawBowlExteriorBase();
  drawKhokhlomaOrnament();

  // 4. Deep Liquid Lacquer Reflections & Stretched White-Marker Window Highlight
  drawBowlLacquerReflections();

  // 5. Inner Bowl Lip & Rim
  drawBowlInnerRim();

  // 6. Hyperreal Beet-Crimson Borscht, Submerged Chunks & Shimmering Oil Droplets
  drawBorschtSoup();

  // 7. Glossy Spoonful of Sour Cream Swirling into Pink
  drawSourCreamSwirl();

  // 8. Shimmering Oil Droplets & Specular Meniscus Glints (Top Soup Layer)
  drawOilDropletsAndGlints();

  // 9. Dark Rye Crumbs & Sprig of Dill on the Black Lacquered Tray
  drawRyeCrumbsOnTray();
  drawDillSprigOnTray();

  // 10. Final Ceremonial Polish & Rim Speculars
  drawFinalHighlights();

  noLoop();
}

// ============================================================================
// 1. BLACK LACQUERED TRAY
// ============================================================================

function drawRoundedTrayPts(cx, cy, w, h, r, rotDeg) {
  let pts = [];
  let cr = Math.cos(rotDeg * RAD);
  let sr = Math.sin(rotDeg * RAD);
  let corners = [
    [w / 2 - r, h / 2 - r, 0, 90],
    [-w / 2 + r, h / 2 - r, 90, 180],
    [-w / 2 + r, -h / 2 + r, 180, 270],
    [w / 2 - r, -h / 2 + r, 270, 360]
  ];
  for (let c of corners) {
    for (let i = 0; i <= 14; i++) {
      let a = (c[2] + (c[3] - c[2]) * (i / 14)) * RAD;
      let lx = c[0] + Math.cos(a) * r;
      let ly = c[1] + Math.sin(a) * r;
      pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
    }
  }
  return pts;
}

function drawLacquerTray() {
  // Outer wintry table abyss
  polyWash([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], "#040102", 255);

  let trayCX = 595, trayCY = 635, trayRot = -9;

  // Tray outer drop shadow
  let outerShadow = drawRoundedTrayPts(trayCX + 8, trayCY + 18, 1240, 1060, 175, trayRot);
  polyWash(outerShadow, "#020001", 240);

  // Tray raised outer rim (warm dark lacquer bevel)
  let trayOuter = drawRoundedTrayPts(trayCX, trayCY, 1210, 1030, 165, trayRot);
  polyWash(trayOuter, "#160607", 255);
  polyWash(trayOuter, "#0b0304", 210);

  // Rim bevel highlight catching warm crimson/gold ambient light
  let trayBevel = drawRoundedTrayPts(trayCX - 3, trayCY - 4, 1186, 1008, 158, trayRot);
  drawSpline([...trayBevel, trayBevel[0]], "oil_glaze", "#3d0d10", 2.4, 0.4);
  drawSpline([...trayBevel, trayBevel[0]], "gold_pen", "#6e440b", 0.9, 0.4);

  // Inner recessed mirror plane of the black lacquered tray
  let trayInner = drawRoundedTrayPts(trayCX, trayCY + 4, 1126, 948, 142, trayRot);
  polyWash(trayInner, "#070304", 255);
  polyWash(trayInner, "#090405", 240);

  // Subtle liquid sheen sweeps across the black tray
  for (let i = 0; i < 9; i++) {
    let t = i / 8;
    let sheenPts = ellipsePts(
      430 + t * 310,
      360 + t * 480,
      540 - i * 32,
      190 - i * 10,
      48,
      -26
    );
    polyWash(sheenPts, i % 2 === 0 ? "#120608" : "#0d0406", 45);
  }

  // Ghostly stretched reflection of wintry window on the black tray surface (upper-left & lower-left)
  let ghostPanes = [
    [[75, 420], [225, 375], [260, 520], [105, 575]],
    [[245, 368], [390, 325], [420, 465], [278, 512]],
    [[115, 600], [270, 545], [310, 710], [150, 770]],
    [[290, 538], [435, 488], [470, 645], [328, 700]]
  ];
  for (let gp of ghostPanes) {
    polyWash(gp, "#1f1417", 36);
    polyWash(gp, "#2e1c20", 22);
    // Faint marker streaks across the tray reflection
    for (let s = 0; s <= 1; s += 0.14) {
      let x1 = lerp(gp[0][0], gp[3][0], s);
      let y1 = lerp(gp[0][1], gp[3][1], s);
      let x2 = lerp(gp[1][0], gp[2][0], s);
      let y2 = lerp(gp[1][1], gp[2][1], s);
      drawSpline([[x1, y1], [x2, y2]], "white_marker", "#3d292d", 0.7, 0.2);
    }
  }

  // Ceremonial Khokhloma double-gold & vermilion pinstripe inside tray bezel
  let goldBorderOuter = drawRoundedTrayPts(trayCX, trayCY + 4, 1118, 940, 140, trayRot);
  let goldBorderInner = drawRoundedTrayPts(trayCX, trayCY + 4, 1094, 916, 132, trayRot);
  drawSpline([...goldBorderOuter, goldBorderOuter[0]], "rotring", "#a81808", 1.1, 0.4);
  drawSpline([...goldBorderOuter, goldBorderOuter[0]], "gold_pen", "#d49b27", 1.2, 0.4);
  drawSpline([...goldBorderInner, goldBorderInner[0]], "gold_pen", "#8c5e12", 0.85, 0.4);

  // Delicate golden travka corner flourishes on the visible lower-left and lower-right tray borders
  drawTrayCornerFlourish(185, 955, -28, 1.0);
  drawTrayCornerFlourish(985, 830, -115, 0.9);
  drawTrayCornerFlourish(1010, 260, 155, 0.85);
}

function drawTrayCornerFlourish(x, y, baseAng, sc) {
  for (let i = -3; i <= 3; i++) {
    let a = (baseAng + i * 16) * RAD;
    let len = (42 - Math.abs(i) * 6) * sc;
    let p0 = [x, y];
    let p1 = [x + Math.cos(a) * len * 0.5, y + Math.sin(a) * len * 0.5];
    let p2 = [x + Math.cos(a + 0.28 * Math.sign(i || 1)) * len, y + Math.sin(a + 0.28 * Math.sign(i || 1)) * len];
    drawSpline([p0, p1, p2], "travka_flick", "#c48b1f", 0.75 * sc, 0.6);
  }
  brush.noStroke();
  let berry = ellipsePts(x, y, 7 * sc, 5 * sc, 16);
  polyWash(berry, "#d9220b", 190);
}

// ============================================================================
// 2. BOWL REFLECTION & CONTACT SHADOW ON THE BLACK LACQUER TRAY
// ============================================================================

function drawBowlTrayReflection() {
  // Warm crimson & gold reflection pool beneath the bowl on the mirror-black tray
  for (let i = 6; i >= 0; i--) {
    let t = i / 6;
    let rx = 250 + t * 185;
    let ry = 115 + t * 88;
    let rcy = CY + 365 + t * 58;
    let pts = ellipsePts(CX + 12, rcy, rx, ry, 60);
    let col = i > 3 ? "#170506" : i > 1 ? "#240809" : "#120405";
    polyWash(pts, col, 65);
  }

  // Reflected blurry Khokhloma berries and gold tendrils upside-down in the lacquer tray
  for (let u = -68; u <= 68; u += 17) {
    let rad = u * RAD;
    let rx = CX + Math.sin(rad) * 310;
    let ry = CY + 355 + Math.cos(rad) * 145;
    let blob = ellipsePts(rx, ry, 34, 18, 20, u * 0.4);
    polyWash(blob, "#470c07", 55);
    let goldBlob = ellipsePts(rx + 14, ry - 8, 26, 12, 18, -u * 0.3);
    polyWash(goldBlob, "#452c07", 50);
    drawSpline(
      [[rx - 18, ry - 6], [rx, ry + 12], [rx + 22, ry + 4]],
      "oil_glaze",
      "#70480c",
      1.1,
      0.5
    );
    drawSpline(
      [[rx - 10, ry], [rx + 8, ry + 8]],
      "oil_glaze",
      "#801508",
      1.3,
      0.4
    );
  }

  // Deep abyssal contact shadow directly beneath the bowl's turned foot ring
  for (let i = 4; i >= 0; i--) {
    let sPts = ellipsePts(CX + 4, CY + 332 + i * 5, 195 + i * 16, 102 + i * 9, 56);
    polyWash(sPts, "#020001", 150 - i * 22);
  }
}

// ============================================================================
// 3. KHOKHLOMA BOWL EXTERIOR: BASE & GILDED/VERMILION ORNAMENT
// ============================================================================

function getBowlExteriorSilhouette() {
  let pts = [];
  // Top rim front arc from left (-92 deg) to right (+92 deg)
  for (let u = -92; u <= 92; u += 4) {
    pts.push(bowlPt(u, 0));
  }
  // Right side profile from v = 0 down to v = 1.0
  for (let v = 0.04; v <= 1.0; v += 0.04) {
    pts.push(bowlPt(92, v));
  }
  // Bottom of bowl belly / foot ring (v = 1.08) from right (+90) to left (-90)
  for (let u = 90; u >= -90; u -= 4) {
    pts.push(bowlPt(u, 1.08));
  }
  // Left side profile from v = 1.0 up to v = 0
  for (let v = 1.0; v >= 0.04; v -= 0.04) {
    pts.push(bowlPt(-92, v));
  }
  return pts;
}

function drawBowlExteriorBase() {
  let bodySil = getBowlExteriorSilhouette();

  // Solid jet-black lacquer foundation
  polyWash(bodySil, "#060304", 255);
  polyWash(bodySil, "#080305", 255);

  // Subtle warm dark undertint in the middle-lower belly
  let midBand = [];
  for (let u = -86; u <= 86; u += 5) midBand.push(bowlPt(u, 0.35));
  for (let u = 86; u >= -86; u -= 5) midBand.push(bowlPt(u, 0.92));
  polyWash(midBand, "#140507", 95);

  // Warm crimson-gold bounce light along the very bottom curve of the belly (v = 0.78..0.98)
  let bounceBand = [];
  for (let u = -78; u <= 78; u += 5) bounceBand.push(bowlPt(u, 0.78));
  for (let u = 78; u >= -78; u -= 5) bounceBand.push(bowlPt(u, 0.98));
  polyWash(bounceBand, "#260809", 85);

  // Turned Foot Ring at base of bowl (v = 0.97 .. 1.10)
  let footBand = [];
  for (let u = -88; u <= 88; u += 4) footBand.push(bowlPt(u, 0.97));
  for (let u = 88; u >= -88; u -= 4) footBand.push(bowlPt(u, 1.10));
  polyWash(footBand, "#0b0405", 250);

  // Gilded & Cinnabar bands on the Foot Ring
  let footGoldBand = [];
  for (let u = -86; u <= 86; u += 4) footGoldBand.push(bowlPt(u, 0.99));
  for (let u = 86; u >= -86; u -= 4) footGoldBand.push(bowlPt(u, 1.05));
  polyWash(footGoldBand, "#8f5f10", 210);

  let footLineTop = [], footLineMid = [], footLineBot = [];
  for (let u = -86; u <= 86; u += 3) {
    footLineTop.push(bowlPt(u, 0.985));
    footLineMid.push(bowlPt(u, 1.02));
    footLineBot.push(bowlPt(u, 1.065));
  }
  drawSpline(footLineTop, "rotring", "#d9220b", 1.1, 0.5);
  drawSpline(footLineMid, "gold_pen", "#f2bd38", 1.4, 0.5);
  drawSpline(footLineBot, "gold_pen", "#754c0b", 1.0, 0.5);

  // Tiny rhythmic vermilion & gold dots along the foot ring
  for (let u = -78; u <= 78; u += 6) {
    let p = bowlPt(u, 1.025);
    let foreshorten = Math.max(0.25, Math.cos(u * RAD));
    let dotPts = ellipsePts(p[0], p[1], 3.2 * foreshorten, 2.2, 10);
    polyWash(dotPts, u % 12 === 0 ? "#ff4514" : "#ffe270", 220);
  }

  // Upper Outer Rim Gilded Border (v = 0.01 .. 0.09)
  let rimGoldBand = [];
  for (let u = -90; u <= 90; u += 3) rimGoldBand.push(bowlPt(u, 0.015));
  for (let u = 90; u >= -90; u -= 3) rimGoldBand.push(bowlPt(u, 0.082));
  polyWash(rimGoldBand, "#9e6b14", 225);

  // Highlight center of upper gold band
  let rimGoldBright = [];
  for (let u = -72; u <= 45; u += 3) rimGoldBright.push(bowlPt(u, 0.025));
  for (let u = 45; u >= -72; u -= 3) rimGoldBright.push(bowlPt(u, 0.068));
  polyWash(rimGoldBright, "#eab434", 190);

  let rimCinnabarLine = [], rimGoldLine1 = [], rimGoldLine2 = [];
  for (let u = -90; u <= 90; u += 3) {
    rimGoldLine1.push(bowlPt(u, 0.015));
    rimGoldLine2.push(bowlPt(u, 0.085));
    rimCinnabarLine.push(bowlPt(u, 0.102));
  }
  drawSpline(rimGoldLine1, "gold_pen", "#ffe373", 1.3, 0.5);
  drawSpline(rimGoldLine2, "gold_pen", "#d99f26", 1.1, 0.5);
  drawSpline(rimCinnabarLine, "rotring", "#e6240c", 1.2, 0.5);

  // Scalloped black-and-vermilion folk arches inside the upper gold rim band
  for (let u = -84; u <= 84; u += 5) {
    let p1 = bowlPt(u - 2, 0.082);
    let p2 = bowlPt(u, 0.032);
    let p3 = bowlPt(u + 2, 0.082);
    drawSpline([p1, p2, p3], "rotring", "#140607", 0.85, 0.5);
    let dotP = bowlPt(u, 0.056);
    let fs = Math.max(0.25, Math.cos(u * RAD));
    polyWash(ellipsePts(dotP[0], dotP[1], 2.5 * fs, 1.9, 8), "#f5280c", 230);
  }
}

