function drawKhokhlomaTrifoliateLeaf(u0, v0, rotDeg, sc) {
  let lobes = [
    { dAng: -32, lenU: 9.5 * sc, lenV: 0.11 * sc, wid: 0.38 },
    { dAng: 0, lenU: 12.5 * sc, lenV: 0.145 * sc, wid: 0.42 },
    { dAng: 32, lenU: 9.5 * sc, lenV: 0.11 * sc, wid: 0.38 }
  ];
  for (let lb of lobes) {
    let a = (rotDeg + lb.dAng) * RAD;
    let ca = Math.cos(a), sa = Math.sin(a);
    let poly = [];
    let steps = 16;
    for (let i = 0; i <= steps; i++) {
      let t = (i / steps) * Math.PI * 2;
      // Pointed leaf profile
      let along = (1 - Math.cos(t)) * 0.5;
      let across = Math.sin(t) * Math.sin(along * Math.PI) * lb.wid;
      // Slight serration along leaf edge
      let serrate = 1 + 0.08 * Math.sin(along * Math.PI * 6);
      let du = (along * sa + across * ca * serrate) * lb.lenU;
      let dv = (along * ca - across * sa * serrate) * lb.lenV;
      poly.push(bowlLocalPt(u0, v0, du, dv));
    }
    // Deep antique gold base + bright metallic gold inner highlight
    polyWash(poly, "#9c6811", 235);
    polyWash(poly, "#e0a626", 200);

    // Bright gold highlight half of leaf
    let hiPoly = poly.slice(0, Math.floor(steps * 0.55));
    if (hiPoly.length >= 3) polyWash(hiPoly, "#f7ca44", 180);

    // Crisp black & cinnabar feathering veins (razzhivka) inside the gold leaf
    let tipPt = bowlLocalPt(u0, v0, sa * lb.lenU * 0.88, ca * lb.lenV * 0.88);
    let midPt = bowlLocalPt(u0, v0, sa * lb.lenU * 0.45, ca * lb.lenV * 0.45);
    let basePt = bowlPt(u0, v0);
    drawSpline([basePt, midPt, tipPt], "rotring", "#120506", 0.85 * sc, 0.4);

    // Tiny lateral black vein ticks
    for (let k = 1; k <= 3; k++) {
      let kt = k * 0.22;
      let vp = bowlLocalPt(u0, v0, sa * lb.lenU * kt, ca * lb.lenV * kt);
      let vpL = bowlLocalPt(u0, v0, (sa * kt + ca * 0.14) * lb.lenU, (ca * kt - sa * 0.14) * lb.lenV);
      let vpR = bowlLocalPt(u0, v0, (sa * kt - ca * 0.14) * lb.lenU, (ca * kt + sa * 0.14) * lb.lenV);
      drawSpline([vp, vpL], "rotring", "#b51806", 0.65 * sc, 0.3);
      drawSpline([vp, vpR], "rotring", "#120506", 0.65 * sc, 0.3);
    }
  }
}

function drawTravkaFanOnBowl(u0, v0, baseAng, dir, count, sc) {
  for (let i = 0; i < count; i++) {
    let f = i / Math.max(1, count - 1);
    let ang = baseAng + dir * (i * 15 - 12);
    let bladeLen = (0.12 - Math.abs(f - 0.35) * 0.05) * sc;
    let pts = [];
    let steps = 10;
    for (let s = 0; s <= steps; s++) {
      let t = s / steps;
      // Classic Khokhloma S-curving grass flick
      let curAng = (ang + dir * Math.pow(t, 1.5) * 58) * RAD;
      let dist = t * bladeLen;
      let du = Math.sin(curAng) * dist * 85;
      let dv = Math.cos(curAng) * dist;
      pts.push(bowlLocalPt(u0, v0, du, dv));
    }
    let isRedGrass = i % 3 === 1;
    let col = isRedGrass ? "#f53814" : (i % 2 === 0 ? "#f7c942" : "#d99b21");
    let w = (isRedGrass ? 0.9 : 1.15) * sc * (1 - f * 0.25);
    drawSpline(pts, "travka_flick", col, w, 0.6);

    // Specular gold tip glint on primary blades
    if (!isRedGrass && i < 3) {
      drawSpline(pts.slice(0, 5), "gold_pen", "#ffeb8a", 0.75 * sc, 0.5);
    }
  }
}

function drawGoldSpiralOnBowl(u0, v0, startAng, dir, sc) {
  let pts = [];
  let steps = 22;
  let u = u0, v = v0;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = (startAng + dir * t * 310) * RAD;
    let stepR = (1 - t * 0.72) * 0.011 * sc;
    u += Math.sin(a) * stepR * 82;
    v += Math.cos(a) * stepR;
    pts.push(bowlPt(u, v));
  }
  drawSpline(pts, "gold_pen", "#eab331", 0.95 * sc, 0.6);
  // Tiny golden berry dots hugging the spiral
  for (let d = 0; d < 3; d++) {
    let dp = pts[Math.min(pts.length - 1, 4 + d * 5)];
    polyWash(ellipsePts(dp[0] + dir * 4, dp[1] - 3, 2.2 * sc, 1.8 * sc, 8), "#ffe375", 220);
  }
}

function drawKhokhlomaStrawberry(u0, v0, rotDeg, sc) {
  let fs = Math.max(0.28, Math.cos(u0 * RAD));
  let center = bowlPt(u0, v0);
  let rx = 22 * sc * fs;
  let ry = 25 * sc;

  // Deep cinnabar base & vivid vermilion body
  let bodyPts = ellipsePts(center[0], center[1], rx, ry, 28, rotDeg * fs);
  polyWash(bodyPts, "#8f0e04", 245);
  let midPts = ellipsePts(center[0] - 2 * fs, center[1] - 2, rx * 0.88, ry * 0.88, 26, rotDeg * fs);
  polyWash(midPts, "#e6230a", 240);
  let hiPts = ellipsePts(center[0] - 4 * fs, center[1] - 5, rx * 0.62, ry * 0.62, 22, rotDeg * fs);
  polyWash(hiPts, "#ff4f19", 215);
  let hotPts = ellipsePts(center[0] - 6 * fs, center[1] - 7, rx * 0.35, ry * 0.35, 16, rotDeg * fs);
  polyWash(hotPts, "#ff7b33", 180);

  // Golden seed dots & delicate gold feathering ribs on the strawberry
  for (let row = -1; row <= 1; row++) {
    for (let col = -1; col <= 1; col++) {
      let sx = center[0] + (col * 6.5 + (row % 2) * 2.5) * sc * fs;
      let sy = center[1] + row * 6.5 * sc;
      polyWash(ellipsePts(sx, sy, 2.1 * sc * fs, 1.7 * sc, 8), "#ffe478", 235);
    }
  }

  // Golden calyx crown at base of berry
  for (let k = -2; k <= 2; k++) {
    let a = (rotDeg - 90 + k * 24) * RAD;
    let p0 = [center[0], center[1] - ry * 0.78];
    let p1 = [p0[0] + Math.cos(a) * 11 * sc * fs, p0[1] + Math.sin(a) * 9 * sc];
    drawSpline([p0, p1], "gold_pen", "#f7ca44", 1.0 * sc, 0.4);
  }
}

function drawRowanBerryCluster(u0, v0, count, sc) {
  let goldenStemCenter = bowlLocalPt(u0, v0, 0, -0.045 * sc);
  for (let i = 0; i < count; i++) {
    let ring = i < 3 ? 0.45 : 1.0;
    let a = (i * (360 / Math.max(1, count - 2)) + (i < 3 ? 30 : 0)) * RAD;
    let du = Math.cos(a) * 5.2 * ring * sc;
    let dv = Math.sin(a) * 0.052 * ring * sc;
    let bPt = bowlLocalPt(u0, v0, du, dv);

    // Fine gold pedicel stem connecting berry to cluster
    drawSpline([goldenStemCenter, bPt], "gold_pen", "#c48a1b", 0.7 * sc, 0.3);

    let fs = Math.max(0.28, Math.cos((u0 + du) * RAD));
    let r = (6.8 + (i % 3) * 1.1) * sc;
    drawBerrySphere(bPt[0], bPt[1], r * fs, r * 0.92, i % 2 === 0);
  }
}

function drawSingleBerryOnBowl(u, v, r, baseCol, hiCol) {
  let p = bowlPt(u, v);
  let fs = Math.max(0.25, Math.cos(u * RAD));
  drawBerrySphere(p[0], p[1], r * fs, r * 0.9, true, baseCol, hiCol);
}

function drawBerrySphere(x, y, rx, ry, withGoldDot = true, baseCol = "#d91c07", hiCol = "#ff591c") {
  polyWash(ellipsePts(x, y, rx, ry, 16), "#7a0b03", 240);
  polyWash(ellipsePts(x - rx * 0.08, y - ry * 0.08, rx * 0.88, ry * 0.88, 16), baseCol, 240);
  polyWash(ellipsePts(x - rx * 0.24, y - ry * 0.24, rx * 0.52, ry * 0.48, 14), hiCol, 220);
  polyWash(ellipsePts(x - rx * 0.32, y - ry * 0.32, rx * 0.24, ry * 0.22, 10), "#ff944d", 200);
  if (withGoldDot) {
    // Traditional Khokhloma black/gold blossom dot at bottom-right of berry
    polyWash(ellipsePts(x + rx * 0.28, y + ry * 0.28, rx * 0.22, ry * 0.22, 8), "#120405", 240);
    polyWash(ellipsePts(x + rx * 0.24, y + ry * 0.24, rx * 0.14, ry * 0.14, 8), "#ffe680", 245);
  }
}

// ============================================================================
// 4. DEEP LIQUID LACQUER REFLECTIONS & STRETCHED WHITE-MARKER WINDOW HIGHLIGHT
// ============================================================================

function drawBowlLacquerReflections() {
  // 1. Deep liquid shadow core on the lower-right & right-center curve of the bowl
  // This glazes over the Khokhloma gold & berries so they sit *inside* the clear lacquer depth
  let shadowCore = [];
  for (let u = 8; u <= 72; u += 5) shadowCore.push(bowlPt(u, 0.28));
  for (let u = 72; u >= 8; u -= 5) shadowCore.push(bowlPt(u, 0.92));
  polyWash(shadowCore, "#070204", 105);

  let deepShadowCore = [];
  for (let u = 22; u <= 62; u += 5) deepShadowCore.push(bowlPt(u, 0.42));
  for (let u = 62; u >= 22; u -= 5) deepShadowCore.push(bowlPt(u, 0.84));
  polyWash(deepShadowCore, "#050103", 95);

  // Far-left silhouette edge darkening for spherical roll-off
  let leftEdgeRoll = [];
  for (let v = 0.08; v <= 0.95; v += 0.06) leftEdgeRoll.push(bowlPt(-92, v));
  for (let v = 0.95; v >= 0.08; v -= 0.06) leftEdgeRoll.push(bowlPt(-76, v));
  polyWash(leftEdgeRoll, "#050203", 125);

  // Warm crimson/vermilion ambient lacquer reflection along the right rim curve
  for (let v = 0.12; v <= 0.82; v += 0.05) {
    let p1 = bowlPt(68, v);
    let p2 = bowlPt(82, v + 0.04);
    drawSpline([p1, p2], "oil_glaze", "#59110c", 1.8, 0.3);
  }

  // 2. THE WINDOW HIGHLIGHT STRETCHED ACROSS THE BOWL'S CURVE IN THIN WHITE MARKER
  // A 2x2 mullioned casement window warped across the bulbous left-front hemisphere
  let panes = [
    // Top-left pane (brightest specular zone)
    { u1: -62, u2: -37, v1: 0.16, v2: 0.41, op: 1.0 },
    // Top-right pane
    { u1: -32, u2: -9, v1: 0.17, v2: 0.42, op: 0.82 },
    // Bottom-left pane (stretching down the lower curve)
    { u1: -60, u2: -36, v1: 0.47, v2: 0.74, op: 0.72 },
    // Bottom-right pane
    { u1: -31, u2: -10, v1: 0.48, v2: 0.73, op: 0.52 }
  ];

  for (let pane of panes) {
    // Soft warm-white lacquer glow halo behind each window pane
    let haloPoly = [];
    for (let u = pane.u1 - 2; u <= pane.u2 + 2; u += 4) haloPoly.push(bowlPt(u, pane.v1 - 0.015));
    for (let v = pane.v1; v <= pane.v2; v += 0.05) haloPoly.push(bowlPt(pane.u2 + 2, v));
    for (let u = pane.u2 + 2; u >= pane.u1 - 2; u -= 4) haloPoly.push(bowlPt(u, pane.v2 + 0.015));
    for (let v = pane.v2; v >= pane.v1; v -= 0.05) haloPoly.push(bowlPt(pane.u1 - 2, v));
    polyWash(haloPoly, "#ffcfc2", Math.round(38 * pane.op));

    // Stretched thin white marker strokes following the horizontal curvature of the bowl
    let numStrokes = 19;
    for (let i = 0; i <= numStrokes; i++) {
      let vt = i / numStrokes;
      let v = lerp(pane.v1, pane.v2, vt);
      // Slight arched distortion of the window reflection over the spherical belly
      let rowPts = [];
      let steps = 10;
      for (let s = 0; s <= steps; s++) {
        let ut = s / steps;
        let u = lerp(pane.u1, pane.u2, ut);
        let vWarp = v - 0.014 * Math.sin(ut * Math.PI);
        rowPts.push(bowlPt(u, vWarp));
      }

      // Edge falloff & marker streaky realism
      let edgeFade = Math.sin(vt * Math.PI);
      let streakMod = 0.7 + 0.3 * noise(v * 25, pane.u1 * 0.2);
      let w = (0.75 + 0.55 * edgeFade) * pane.op * streakMod;
      let col = vt < 0.25 ? "#ffffff" : vt < 0.7 ? "#fff6f0" : "#ffdcd0";
      drawSpline(rowPts, "white_marker", col, w, 0.5);

      // Extra crisp white core on the upper panes
      if (pane.op > 0.75 && i % 2 === 0 && vt > 0.12 && vt < 0.85) {
        drawSpline(rowPts.slice(1, -1), "pen", "#ffffff", 0.9 * pane.op, 0.5);
      }
    }

    // Crisp vertical marker border streaks along left/right edges of each warped pane
    let leftEdge = [], rightEdge = [];
    for (let v = pane.v1; v <= pane.v2; v += 0.04) {
      leftEdge.push(bowlPt(pane.u1, v));
      rightEdge.push(bowlPt(pane.u2, v));
    }
    drawSpline(leftEdge, "white_marker", "#fff5ee", 0.8 * pane.op, 0.4);
    drawSpline(rightEdge, "white_marker", "#ffe6dc", 0.65 * pane.op, 0.4);
  }

  // Long liquid secondary reflection streak curving along the lower-left belly
  let lowerStreak = [];
  for (let u = -66; u <= -18; u += 4) {
    lowerStreak.push(bowlPt(u, 0.84 + 0.02 * Math.sin((u + 40) * 3 * RAD)));
  }
  drawSpline(lowerStreak, "white_marker", "#ffd8c8", 0.75, 0.5);
}

// ============================================================================
// 5. INNER BOWL LIP & RIM (STEEP THREE-QUARTER PERSPECTIVE)
// ============================================================================

function drawBowlInnerRim() {
  // Outer rim ring and inner wall visible above the recessed borscht surface
  let outerRimPts = ellipsePts(CX, CY, RIM_RX, RIM_RY, 84);
  let innerRimPts = ellipsePts(CX, CY + 5, INNER_RX, INNER_RY, 84);

  // Upper wooden lip thickness (between outerRim and innerRim)
  // Build ring segments to shade the rounded lip in 3D
  let lipFull = [...outerRimPts, ...innerRimPts.slice().reverse()];
  polyWash(lipFull, "#140506", 250);

  // Inner bowl wall between the lip (CY + 5) and the soup surface (SOUP_CY = CY + 16)
  // Seen prominently along the top/back arc (from 175 deg to 365 deg)
  let wallPts = [
    ...arcPts(CX, CY + 5, INNER_RX, INNER_RY, 175, 365, 56),
    ...arcPts(CX, SOUP_CY + 4, SOUP_RX + 4, SOUP_RY + 4, 365, 175, 56)
  ];
  polyWash(wallPts, "#1a0406", 255);

  // Rich Khokhloma cinnabar-vermilion inner wall band just above the soup
  let wallVermilion = [
    ...arcPts(CX, CY + 10, INNER_RX - 3, INNER_RY - 2, 185, 355, 50),
    ...arcPts(CX, SOUP_CY + 4, SOUP_RX + 2, SOUP_RY + 2, 355, 185, 50)
  ];
  polyWash(wallVermilion, "#780c06", 230);

  // Warm sunlit vermilion glow on the top-right inner wall
  let wallGlow = [
    ...arcPts(CX, CY + 9, INNER_RX - 3, INNER_RY - 2, 235, 335, 36),
    ...arcPts(CX, SOUP_CY + 3, SOUP_RX + 2, SOUP_RY + 2, 335, 235, 36)
  ];
  polyWash(wallGlow, "#c91d0b", 200);

  // Gilded Khokhloma band running along the inside upper wall
  let innerGoldArc1 = arcPts(CX, CY + 7, INNER_RX - 1, INNER_RY - 1, 182, 358, 52);
  let innerGoldArc2 = arcPts(CX, CY + 11, INNER_RX - 4, INNER_RY - 3, 185, 355, 52);
  drawSpline(innerGoldArc1, "gold_pen", "#eab331", 1.5, 0.5);
  drawSpline(innerGoldArc2, "gold_pen", "#b87f16", 1.1, 0.5);

  // Tiny golden travka curls along the inner back rim wall
  for (let deg = 198; deg <= 342; deg += 9) {
    let a1 = deg * RAD;
    let a2 = (deg + 4.5) * RAD;
    let p1 = [CX + Math.cos(a1) * (INNER_RX - 2), CY + 8 + Math.sin(a1) * (INNER_RY - 2)];
    let p2 = [CX + Math.cos(a2) * (INNER_RX - 8), CY + 15 + Math.sin(a2) * (INNER_RY - 6)];
    drawSpline([p1, p2], "gold_pen", deg > 240 && deg < 320 ? "#ffe375" : "#c78d1c", 0.9, 0.4);
  }

  // Rounded wooden lip bevel shading & golden outer rim line
  drawSpline([...outerRimPts, outerRimPts[0]], "gold_pen", "#c48a1b", 1.3, 0.5);
  drawSpline([...innerRimPts, innerRimPts[0]], "rotring", "#2b0708", 1.2, 0.5);

  // Stretched white marker highlight along the glossy rounded lip of the bowl (top-left & bottom-right arcs)
  let lipHiTopLeft = arcPts(CX, CY + 2, (RIM_RX + INNER_RX) * 0.5, (RIM_RY + INNER_RY) * 0.5, 192, 252, 32);
  drawSpline(lipHiTopLeft, "white_marker", "#fff5ee", 1.25, 0.5);
  let lipHiCore = arcPts(CX, CY + 2, (RIM_RX + INNER_RX) * 0.5, (RIM_RY + INNER_RY) * 0.5, 206, 236, 20);
  drawSpline(lipHiCore, "pen", "#ffffff", 1.2, 0.5);

  let lipHiFrontLeft = arcPts(CX, CY + 2, (RIM_RX + INNER_RX) * 0.5, (RIM_RY + INNER_RY) * 0.5, 112, 164, 28);
  drawSpline(lipHiFrontLeft, "white_marker", "#fff8f4", 1.35, 0.5);
  let lipHiFrontCore = arcPts(CX, CY + 2, (RIM_RX + INNER_RX) * 0.5, (RIM_RY + INNER_RY) * 0.5, 124, 152, 18);
  drawSpline(lipHiFrontCore, "pen", "#ffffff", 1.3, 0.5);

  let lipHiRight = arcPts(CX, CY + 2, (RIM_RX + INNER_RX) * 0.5, (RIM_RY + INNER_RY) * 0.5, 330, 385, 24);
  drawSpline(lipHiRight, "gold_pen", "#ffe275", 1.15, 0.5);
}

// ============================================================================
// 6. HYPERREAL BEET-CRIMSON BORSCHT SOUP & SUBMERGED CHUNKS
// ============================================================================

function drawBorschtSoup() {
  // 1. Deepest beet-oxblood base of the soup
  let soupBase = ellipsePts(CX, SOUP_CY, SOUP_RX, SOUP_RY, 84);
  polyWash(soupBase, "#290208", 255);
  polyWash(soupBase, "#3d030d", 245);

  // 2. Luminous translucent beet-crimson & ruby depth zones (batched watercolor fills + washes)
  let rubyMain = ellipsePts(CX - 18, SOUP_CY - 8, SOUP_RX * 0.88, SOUP_RY * 0.86, 68, -6, 0.04);
  polyWash(rubyMain, "#6e0518", 220);

  let crimsonGlow1 = ellipsePts(CX - 42, SOUP_CY - 16, SOUP_RX * 0.72, SOUP_RY * 0.68, 60, -10, 0.06);
  polyFill(crimsonGlow1, "#9e0824", 165, 0.18, 0.25);

  let crimsonGlow2 = ellipsePts(CX + 55, SOUP_CY + 18, SOUP_RX * 0.62, SOUP_RY * 0.58, 56, 12, 0.06);
  polyFill(crimsonGlow2, "#b80b2c", 155, 0.18, 0.25);

  // Vivid saturated beet-crimson & cinnabar broth translucency
  let vividBeet1 = ellipsePts(CX - 75, SOUP_CY - 35, 165, 108, 48, -14, 0.08);
  polyFill(vividBeet1, "#db1237", 150, 0.22, 0.22);

  let vividBeet2 = ellipsePts(CX + 85, SOUP_CY - 12, 155, 102, 48, 18, 0.08);
  polyFill(vividBeet2, "#e61938", 145, 0.22, 0.22);

  let cinnabarBrothPool = ellipsePts(CX + 25, SOUP_CY + 68, 175, 92, 48, -5, 0.08);
  polyFill(cinnabarBrothPool, "#d91f14", 135, 0.2, 0.2);

  // Deep oxblood shadow crescent along the top-left & bottom-right rim overhang
  let rimShadowArc = [
    ...arcPts(CX, SOUP_CY, SOUP_RX, SOUP_RY, 195, 295, 40),
    ...arcPts(CX, SOUP_CY + 14, SOUP_RX * 0.92, SOUP_RY * 0.88, 295, 195, 40)
  ];
  polyWash(rimShadowArc, "#1f0106", 185);

  // Fiery cinnabar-red translucent meniscus glow where soup meets the bowl wall
  let meniscusArc1 = arcPts(CX, SOUP_CY, SOUP_RX - 2, SOUP_RY - 2, 0, 185, 56);
  drawSpline(meniscusArc1, "oil_glaze", "#f23013", 2.4, 0.5);
  let meniscusArc2 = arcPts(CX, SOUP_CY, SOUP_RX - 4, SOUP_RY - 4, 285, 360, 32);
  drawSpline(meniscusArc2, "oil_glaze", "#e6200e", 2.0, 0.5);

  // 3. Submerged & Surface-Breaking Chunks (Julienned Beetroot, Crimson Cabbage, Tender Potato/Carrot)
  let chunks = [
    // Julienned beet strips
    { x: CX - 165, y: SOUP_CY - 45, w: 62, h: 16, rot: -22, type: "beet" },
    { x: CX - 125, y: SOUP_CY + 65, w: 68, h: 18, rot: 18, type: "beet" },
    { x: CX + 135, y: SOUP_CY - 55, w: 58, h: 15, rot: 28, type: "beet" },
    { x: CX + 160, y: SOUP_CY + 32, w: 64, h: 17, rot: -16, type: "beet" },
    { x: CX + 42, y: SOUP_CY - 108, w: 54, h: 14, rot: 8, type: "beet" },
    { x: CX - 35, y: SOUP_CY + 118, w: 66, h: 17, rot: -9, type: "beet" },
    // Translucent beet-stained cabbage ribbons
    { x: CX + 95, y: SOUP_CY - 82, w: 72, h: 24, rot: -25, type: "cabbage" },
    { x: CX - 195, y: SOUP_CY + 12, w: 68, h: 22, rot: 32, type: "cabbage" },
    { x: CX + 82, y: SOUP_CY + 88, w: 74, h: 24, rot: -14, type: "cabbage" },
    // Warm cinnabar-glazed carrot/potato chunks peeking through broth
    { x: CX + 120, y: SOUP_CY - 8, w: 44, h: 28, rot: 14, type: "carrot" },
    { x: CX - 95, y: SOUP_CY - 98, w: 42, h: 26, rot: -19, type: "carrot" },
    { x: CX + 18, y: SOUP_CY + 92, w: 40, h: 25, rot: 22, type: "carrot" }
  ];

  for (let ch of chunks) {
    drawSoupChunk(ch.x, ch.y, ch.w, ch.h, ch.rot, ch.type);
  }

  // Fluid convective swirls in the crimson broth around the chunks
  for (let i = 0; i < 24; i++) {
    let a = (i / 24) * 360 * RAD;
    let rFrac = 0.38 + 0.48 * noise(i * 1.3);
    let sx = CX + Math.cos(a) * SOUP_RX * rFrac;
    let sy = SOUP_CY + Math.sin(a) * SOUP_RY * rFrac;
    let swPts = [];
    for (let s = 0; s < 5; s++) {
      let sa = a + 1.4 + s * 0.25;
      swPts.push([sx + Math.cos(sa) * s * 16, sy + Math.sin(sa) * s * 11]);
    }
    let col = i % 3 === 0 ? "#ff2b4a" : i % 3 === 1 ? "#8c051d" : "#eb2f15";
    drawSpline(swPts, "oil_glaze", col, 1.3, 0.6);
  }
}

function drawSoupChunk(x, y, w, h, rotDeg, type) {
  // Deep shadow halo under chunk in broth
  let halo = ellipsePts(x + 2, y + 4, w * 0.62, h * 0.72, 24, rotDeg, 0.12);
  polyWash(halo, "#2e0209", 170);

  let body = ellipsePts(x, y, w * 0.5, h * 0.52, 24, rotDeg, 0.15);
  if (type === "beet") {
    polyWash(body, "#590313", 235);
    let top = ellipsePts(x - 2, y - 2, w * 0.38, h * 0.36, 20, rotDeg, 0.1);
    polyWash(top, "#b80b28", 220);
    let hi = ellipsePts(x - 4, y - 3, w * 0.24, h * 0.2, 16, rotDeg);
    polyWash(hi, "#ff2949", 210);
  } else if (type === "cabbage") {
    polyWash(body, "#7a071d", 215);
    let mid = ellipsePts(x - 2, y - 1, w * 0.42, h * 0.38, 22, rotDeg, 0.14);
    polyWash(mid, "#d9183b", 200);
    let rib = ellipsePts(x - 3, y - 2, w * 0.32, h * 0.18, 18, rotDeg);
    polyWash(rib, "#ff5c77", 185);
  } else {
    // Carrot / potato glazed in fiery cinnabar-gold broth
    polyWash(body, "#8f1206", 225);
    let mid = ellipsePts(x - 2, y - 2, w * 0.38, h * 0.36, 20, rotDeg, 0.1);
    polyWash(mid, "#e32b0e", 215);
    let hi = ellipsePts(x - 4, y - 3, w * 0.24, h * 0.22, 16, rotDeg);
    polyWash(hi, "#ff7829", 200);
  }

  // Wet liquid meniscus ring & crisp specular glint where the chunk breaks the soup surface
  let menArc = arcPts(x, y, w * 0.52, h * 0.54, 195, 340, 16, rotDeg);
  drawSpline(menArc, "gold_pen", "#ff6a2b", 0.95, 0.5);
  let specArc = arcPts(x - 2, y - 2, w * 0.36, h * 0.34, 210, 295, 12, rotDeg);
  drawSpline(specArc, "pen", "#fff2e6", 0.9, 0.5);
}

// ============================================================================
// 7. GLOSSY SPOONFUL OF SOUR CREAM SWIRLING INTO PINK
// ============================================================================

function drawSourCreamSwirl() {
  let scX = CX - 38;
  let scY = SOUP_CY - 12;

  // 1. Outer Pink Diffusion Halo & Swirling Marble Ribbons in the Beet Broth
  // Build spiral ribbons radiating out from the sour cream dollop and curling into the crimson soup
  let spiralArms = [
    { startA: -20, sweep: 235, r0: 38, r1: 185, w0: 36, w1: 6, col1: "#d61f56", col2: "#f26b97" },
    { startA: 85, sweep: 210, r0: 32, r1: 165, w0: 32, w1: 5, col1: "#b81143", col2: "#eb4d80" },
    { startA: 195, sweep: 250, r0: 35, r1: 195, w0: 38, w1: 7, col1: "#cf1b52", col2: "#f78db0" },
    { startA: 290, sweep: 185, r0: 28, r1: 145, w0: 28, w1: 5, col1: "#a60d3b", col2: "#e63e73" }
  ];

  // Batch pink watercolor diffusion halos first
  for (let arm of spiralArms) {
    let leftEdge = [], rightEdge = [];
    let steps = 28;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = (arm.startA + t * arm.sweep) * RAD;
      let r = lerp(arm.r0, arm.r1, Math.pow(t, 0.88));
      let w = lerp(arm.w0, arm.w1, t) * (1 + 0.25 * Math.sin(t * Math.PI * 3));
      let cx = scX + Math.cos(a) * r * 1.15;
      let cy = scY + Math.sin(a) * r * 0.76;
      let nx = Math.cos(a);
      let ny = Math.sin(a) * 0.68;
      leftEdge.push([cx - nx * w, cy - ny * w]);
      rightEdge.push([cx + nx * w, cy + ny * w]);
    }
    let ribbonPoly = [...leftEdge, ...rightEdge.reverse()];
    polyFill(ribbonPoly, arm.col1, 145, 0.22, 0.22);
    polyWash(ribbonPoly, arm.col2, 115);
  }

  // Secondary tighter rose-pink & blush-cream marble veins inside the swirl
  for (let arm of spiralArms) {
    let veinPts1 = [], veinPts2 = [], veinPts3 = [];
    let steps = 26;
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let a = (arm.startA + t * arm.sweep + Math.sin(t * 9) * 8) * RAD;
      let r = lerp(arm.r0 * 0.75, arm.r1 * 0.92, Math.pow(t, 0.85));
      let px = scX + Math.cos(a) * r * 1.15;
      let py = scY + Math.sin(a) * r * 0.76;
      veinPts1.push([px, py]);
      veinPts2.push([px + Math.cos(a + 0.5) * 9 * (1 - t), py + Math.sin(a + 0.5) * 6 * (1 - t)]);
      if (t < 0.72) {
        veinPts3.push([px - Math.cos(a) * 5 * (1 - t), py - Math.sin(a) * 4 * (1 - t)]);
      }
    }
    drawSpline(veinPts1, "oil_glaze", "#f79ebc", 2.1, 0.6);
    drawSpline(veinPts2, "oil_glaze", "#db2962", 1.6, 0.6);
    drawSpline(veinPts3, "pen", "#ffd6e4", 1.25, 0.6);
  }

  // Delicate fluid-dynamic eddies & crimson-into-pink marbling filaments
  for (let k = 0; k < 28; k++) {
    let baseA = (k * 137.5) % 360;
    let dist = 48 + (k / 28) * 128;
    let pts = [];
    for (let s = 0; s <= 8; s++) {
      let st = s / 8;
      let a = (baseA + st * 68 + Math.sin(st * Math.PI * 2) * 14) * RAD;
      let r = dist + st * 26;
      pts.push([scX + Math.cos(a) * r * 1.14, scY + Math.sin(a) * r * 0.75]);
    }
    let isPink = k % 2 === 0;
    let col = isPink ? (k % 4 === 0 ? "#ffc2d6" : "#f06e9b") : "#b30c38";
    drawSpline(pts, isPink ? "gold_pen" : "oil_glaze", col, isPink ? 0.95 : 1.35, 0.65);
  }

  // 2. The Thick, Sculpted Spoonful of Sour Cream (Smetana) at the Core
  // Outer blush-pink base where the hot beet soup warms the edges of the cream
  let creamOuter = ellipsePts(scX, scY, 82, 56, 48, -14, 0.18);
  polyFill(creamOuter, "#f2a7c0", 190, 0.15, 0.18);
  polyWash(creamOuter, "#f7c6d7", 215);

  // Mid-layer sculpted cream body
  let creamMid = ellipsePts(scX - 3, scY - 2, 68, 46, 44, -12, 0.15);
  polyWash(creamMid, "#fce3ec", 240);

  // Rich warm-ivory & pure cream upper mound
  let creamCore = ellipsePts(scX - 6, scY - 4, 54, 37, 40, -10, 0.12);
  polyWash(creamCore, "#fff5f7", 250);
  polyWash(creamCore, "#fffaf8", 245);

  // Sculpted spoon-hollow and velvety folds inside the sour cream dollop
  let spoonHollow = [
    ...arcPts(scX - 2, scY + 2, 42, 26, 15, 175, 22, -12),
    ...arcPts(scX - 2, scY - 5, 34, 18, 175, 15, 22, -12)
  ];
  polyWash(spoonHollow, "#f5cad8", 210);

  let shadowFold2 = [
    ...arcPts(scX + 10, scY - 8, 36, 22, 250, 380, 18, -8),
    ...arcPts(scX + 4, scY - 8, 24, 15, 380, 250, 18, -8)
  ];
  polyWash(shadowFold2, "#edb4c7", 195);

  // Magenta-crimson broth ribbon folding right over the edge of the sour cream spoonful
  let foldOverPts = [
    [scX + 26, scY - 32],
    [scX + 12, scY - 14],
    [scX + 22, scY + 6],
    [scX + 48, scY + 18],
    [scX + 66, scY + 8]
  ];
  drawSpline(foldOverPts, "oil_glaze", "#d9184b", 2.2, 0.55);
  drawSpline(foldOverPts.slice(0, 4), "gold_pen", "#ff6694", 1.1, 0.55);

  // Dazzling wet glossy specular peaks on the sour cream ridges
  let creamRidges = [
    arcPts(scX - 8, scY - 7, 38, 24, 188, 305, 20, -12),
    arcPts(scX - 4, scY + 5, 26, 16, 165, 265, 16, -8),
    arcPts(scX + 12, scY - 4, 22, 14, 210, 320, 14, 10)
  ];
  for (let cr of creamRidges) {
    drawSpline(cr, "white_marker", "#ffffff", 1.6, 0.5);
    drawSpline(cr.slice(2, -2), "pen", "#ffffff", 1.4, 0.5);
  }

  // Tiny glistening droplets of ruby broth and finely minced dill flecks on top of the sour cream
  let creamDroplets = [
    { x: scX - 18, y: scY - 6, r: 3.5 },
    { x: scX + 8, y: scY + 10, r: 2.8 },
    { x: scX + 16, y: scY - 12, r: 2.2 },
    { x: scX - 6, y: scY + 16, r: 3.0 }
  ];
  for (let cd of creamDroplets) {
    polyWash(ellipsePts(cd.x, cd.y, cd.r * 1.2, cd.r * 0.85, 12), "#c90e36", 230);
    polyWash(ellipsePts(cd.x - 0.8, cd.y - 0.8, cd.r * 0.5, cd.r * 0.4, 8), "#ffffff", 245);
  }

  // Aromatic dark-gold dill flecks on the sour cream
  for (let f = 0; f < 14; f++) {
    let fa = f * 26 * RAD;
    let fr = 8 + (f % 4) * 11;
    let fx = scX - 4 + Math.cos(fa) * fr * 1.1;
    let fy = scY - 2 + Math.sin(fa) * fr * 0.72;
    let flen = 4.5 + (f % 3) * 2;
    drawSpline(
      [[fx, fy], [fx + Math.cos(fa + 0.8) * flen, fy + Math.sin(fa + 0.8) * flen * 0.7]],
      "rotring",
      f % 2 === 0 ? "#243010" : "#5e691a",
      0.85,
      0.2
    );
  }
}

// ============================================================================
// 8. SHIMMERING OILY DROPLETS & MENISCUS GLINTS ON THE SOUP
// ============================================================================

function drawOilDropletsAndGlints() {
  // Strategically & organically distributed oil droplets across the beet-crimson surface
  let droplets = [
    // Large & medium glistening oil lenses
    { x: CX - 185, y: SOUP_CY - 18, r: 19 },
    { x: CX - 158, y: SOUP_CY - 34, r: 11 },
    { x: CX - 142, y: SOUP_CY + 28, r: 15 },
    { x: CX - 115, y: SOUP_CY - 78, r: 16 },
    { x: CX - 92, y: SOUP_CY - 68, r: 9 },
    { x: CX - 85, y: SOUP_CY + 95, r: 18 },
    { x: CX - 60, y: SOUP_CY + 108, r: 10 },
    { x: CX + 58, y: SOUP_CY - 88, r: 17 },
    { x: CX + 82, y: SOUP_CY - 76, r: 11 },
    { x: CX + 115, y: SOUP_CY - 42, r: 21 },
    { x: CX + 142, y: SOUP_CY - 28, r: 12 },
    { x: CX + 152, y: SOUP_CY + 8, r: 16 },
    { x: CX + 98, y: SOUP_CY + 58, r: 22 },
    { x: CX + 126, y: SOUP_CY + 68, r: 13 },
    { x: CX + 68, y: SOUP_CY + 72, r: 10 },
    { x: CX + 15, y: SOUP_CY + 115, r: 15 },
    { x: CX - 15, y: SOUP_CY - 112, r: 14 },
    { x: CX + 195, y: SOUP_CY - 12, r: 14 },
    { x: CX - 225, y: SOUP_CY + 5, r: 13 }
  ];

  // Add chains of smaller satellite oil droplets around the soup
  for (let i = 0; i < 68; i++) {
    let a = (i * 53.7) * RAD;
    let distFrac = 0.28 + 0.64 * ((i * 0.173) % 1);
    let dx = CX + Math.cos(a) * SOUP_RX * distFrac;
    let dy = SOUP_CY + Math.sin(a) * SOUP_RY * distFrac;
    // Avoid placing right over the thick sour cream center
    if (Math.hypot((dx - (CX - 38)) * 0.8, dy - (SOUP_CY - 12)) > 56) {
      let r = 2.5 + (i % 5) * 1.4;
      droplets.push({ x: dx, y: dy, r });
    }
  }

  for (let d of droplets) {
    let rx = d.r * 1.12;
    let ry = d.r * 0.76; // Perspective foreshortening matching the soup plane

    // 1. Dark crimson surface-tension outer ring
    let outerPts = ellipsePts(d.x, d.y, rx * 1.08, ry * 1.08, 20);
    polyWash(outerPts, "#36020a", 190);

    // 2. Refracted fiery cinnabar-gold interior of the oil droplet
    let innerPts = ellipsePts(d.x, d.y, rx * 0.92, ry * 0.92, 20);
    polyWash(innerPts, d.r > 8 ? "#e3240b" : "#ff4517", 215);

    // 3. Luminous golden-amber internal caustic crescent (bottom-right of droplet)
    if (d.r >= 5) {
      let causticPts = ellipsePts(d.x + rx * 0.16, d.y + ry * 0.16, rx * 0.62, ry * 0.58, 16);
      polyWash(causticPts, "#ff8826", 205);
      let goldCore = ellipsePts(d.x + rx * 0.22, d.y + ry * 0.22, rx * 0.35, ry * 0.32, 12);
      polyWash(goldCore, "#ffd447", 215);
    }

    // 4. Razor-sharp golden rim outline & brilliant white-gold window reflection glint (upper-left)
    if (d.r >= 7) {
      drawSpline([...innerPts, innerPts[0]], "gold_pen", "#ff9d3b", 0.75, 0.5);
      let glintArc = arcPts(d.x, d.y, rx * 0.78, ry * 0.78, 195, 285, 10);
      drawSpline(glintArc, "pen", "#ffffff", 1.0, 0.5);
    } else {
      let dotGlint = ellipsePts(d.x - rx * 0.3, d.y - ry * 0.3, Math.max(1.2, rx * 0.35), Math.max(1.0, ry * 0.35), 8);
      polyWash(dotGlint, "#fffdf5", 245);
    }
  }

  // Crisp specular meniscus sparkles along the soup's outer edge where broth meets the bowl wall
  for (let deg = 190; deg <= 350; deg += 11) {
    if (deg % 22 === 0) continue;
    let arcG = arcPts(CX, SOUP_CY + 2, SOUP_RX - 2, SOUP_RY - 2, deg, deg + 4.5, 8);
    drawSpline(arcG, "pen", "#fff0d4", 0.95, 0.4);
  }
}

