// 9. DARK RYE CRUMBS & SPRIG OF DILL ON THE BLACK LACQUERED TRAY
// ============================================================================

function drawRyeCrumbsOnTray() {
  // Cluster of dark Borodinsky rye bread morsels and scattered crumbs on the lower-left black tray
  let majorCrumbs = [
    // Larger crusty dark rye morsels
    { x: 265, y: 895, rx: 28, ry: 20, rot: -18, hasCrust: true },
    { x: 332, y: 938, rx: 22, ry: 15, rot: 24, hasCrust: true },
    { x: 218, y: 948, rx: 18, ry: 13, rot: -32, hasCrust: false },
    { x: 388, y: 912, rx: 16, ry: 12, rot: 12, hasCrust: true },
    { x: 295, y: 978, rx: 15, ry: 11, rot: -8, hasCrust: false },
    { x: 438, y: 962, rx: 14, ry: 10, rot: 35, hasCrust: false },
    { x: 182, y: 882, rx: 13, ry: 9, rot: 15, hasCrust: true },
    { x: 485, y: 988, rx: 11, ry: 8, rot: -22, hasCrust: false },
    { x: 358, y: 1005, rx: 12, ry: 9, rot: 8, hasCrust: false }
  ];

  // 1. Glossy reflections & contact shadows of the rye morsels on the black lacquer tray
  for (let mc of majorCrumbs) {
    // Reflection below crumb
    let reflPts = ellipsePts(mc.x + 2, mc.y + mc.ry * 1.15, mc.rx * 0.92, mc.ry * 0.7, 20, mc.rot, 0.25);
    polyWash(reflPts, "#1c0b07", 95);
    // Sharp abyssal contact shadow
    let shadPts = ellipsePts(mc.x + 3, mc.y + mc.ry * 0.48, mc.rx * 1.06, mc.ry * 0.85, 22, mc.rot, 0.22);
    polyWash(shadPts, "#020001", 230);
  }

  // 2. Render each 3D porous dark rye bread morsel
  for (let mc of majorCrumbs) {
    // Jagged organic crumb silhouette
    let basePts = ellipsePts(mc.x, mc.y, mc.rx, mc.ry, 26, mc.rot, 0.32);
    polyWash(basePts, "#140806", 250);

    // Midtone dark roasted rye interior
    let midPts = ellipsePts(mc.x - 2, mc.y - 2, mc.rx * 0.85, mc.ry * 0.82, 24, mc.rot, 0.3);
    polyWash(midPts, "#2e140c", 235);

    // Warm mahogany-cinnabar toasted crumb top catching ceremonial light
    let topPts = ellipsePts(mc.x - 4, mc.y - 4, mc.rx * 0.65, mc.ry * 0.6, 20, mc.rot, 0.28);
    polyWash(topPts, "#592614", 215);

    if (mc.hasCrust) {
      // Charred dark-black Borodinsky top crust edge with golden coriander seeds
      let crustPts = ellipsePts(mc.x + mc.rx * 0.22, mc.y - mc.ry * 0.18, mc.rx * 0.58, mc.ry * 0.45, 18, mc.rot + 15, 0.2);
      polyWash(crustPts, "#0d0504", 240);
      // Coriander seed halves on the crust
      for (let s = 0; s < 3; s++) {
        let sx = mc.x + (s - 1) * 6;
        let sy = mc.y - 3 + (s % 2) * 4;
        polyWash(ellipsePts(sx, sy, 2.6, 1.8, 10, s * 40), "#b87928", 230);
        polyWash(ellipsePts(sx - 0.6, sy - 0.6, 1.2, 0.9, 8), "#ffe07d", 220);
      }
    }

    // Porous rye crumb air pockets & golden-amber edge highlights
    for (let p = 0; p < 12; p++) {
      let pa = p * 30 * RAD;
      let pr = (0.2 + 0.65 * ((p * 0.37) % 1));
      let px = mc.x + Math.cos(pa) * mc.rx * pr;
      let py = mc.y + Math.sin(pa) * mc.ry * pr;
      // Dark pore
      polyWash(ellipsePts(px, py, 2.2, 1.6, 8), "#0a0302", 235);
      // Warm golden-cinnabar ridge next to pore
      if (p % 2 === 0) {
        polyWash(ellipsePts(px - 1.8, py - 1.5, 2.0, 1.4, 8), p % 4 === 0 ? "#d4832a" : "#8c3d19", 210);
      }
    }
  }

  // 3. Scatter of 95 fine dark rye crumbs & golden-lit grains trailing across the black lacquer
  for (let i = 0; i < 95; i++) {
    let t = i / 95;
    let ang = (i * 137.5) * RAD;
    // Spread across lower-left to bottom-center of tray
    let cx = 315 + Math.cos(ang) * (35 + t * 235) + t * 95;
    let cy = 935 + Math.sin(ang) * (22 + t * 115) + t * 25;
    if (cy > 1135 || cx < 95) continue;

    let r = 1.6 + (1 - t) * 4.2 * ((i % 4) * 0.25 + 0.35);
    // Tiny shadow on tray
    polyWash(ellipsePts(cx + 1, cy + r * 0.7, r * 1.1, r * 0.75, 8), "#020001", 220);
    // Dark rye base
    polyWash(ellipsePts(cx, cy, r, r * 0.78, 10, i * 25, 0.25), i % 3 === 0 ? "#1a0a07" : "#36160d", 240);
    // Golden or cinnabar highlight speck on upper-left of crumb
    let hiCol = i % 5 === 0 ? "#f2b844" : i % 3 === 0 ? "#b85d21" : "#753114";
    polyWash(ellipsePts(cx - r * 0.28, cy - r * 0.28, r * 0.52, r * 0.42, 8), hiCol, 220);
  }
}

function drawDillSprigOnTray() {
  // Aromatic feathery sprig of dill resting on the lower-right black lacquered tray
  // Harmonized in deep pine-black, warm bronze-olive, and ceremonial golden-amber highlights
  let stemMain = [
    [665, 1015],
    [745, 972],
    [835, 922],
    [925, 875],
    [1010, 832]
  ];

  // 1. Soft dark reflection of the dill sprig on the mirror-black lacquer tray below it
  let reflStem = stemMain.map(p => [p[0] + 3, p[1] + 16]);
  drawSpline(reflStem, "oil_glaze", "#171c0a", 2.2, 0.5);

  let branches = [
    { base: [725, 982], tip: [685, 912], side: -1, sc: 0.95 },
    { base: [755, 966], tip: [825, 995], side: 1, sc: 1.0 },
    { base: [805, 938], tip: [772, 858], side: -1, sc: 1.1 },
    { base: [845, 916], tip: [935, 945], side: 1, sc: 1.08 },
    { base: [895, 890], tip: [872, 808], side: -1, sc: 1.02 },
    { base: [935, 870], tip: [1025, 892], side: 1, sc: 0.95 },
    { base: [968, 852], tip: [965, 785], side: -1, sc: 0.85 },
    { base: [990, 842], tip: [1055, 815], side: 1, sc: 0.8 }
  ];

  // Reflections & contact shadows of fronds on the black tray
  for (let br of branches) {
    drawSpline([[br.base[0], br.base[1] + 14], [br.tip[0], br.tip[1] + 16]], "oil_glaze", "#141a09", 1.5, 0.4);
    drawSpline([[br.base[0], br.base[1] + 5], [br.tip[0], br.tip[1] + 6]], "rotring", "#020001", 1.4, 0.4);
  }
  drawSpline(stemMain.map(p => [p[0] + 2, p[1] + 6]), "rotring", "#020001", 2.2, 0.5);

  // 2. Feathery pinnate dill needles radiating from every branchlet
  for (let br of branches) {
    let mid = [
      (br.base[0] + br.tip[0]) * 0.5 + br.side * 8,
      (br.base[1] + br.tip[1]) * 0.5 - 6
    ];

    // Sub-twigs & delicate feathery needles
    let numNeedles = 26;
    for (let i = 0; i <= numNeedles; i++) {
      let t = i / numNeedles;
      let bx = lerp(br.base[0], br.tip[0], t) + Math.sin(t * Math.PI) * br.side * 6;
      let by = lerp(br.base[1], br.tip[1], t) - Math.sin(t * Math.PI) * 5;

      let dirAng = Math.atan2(br.tip[1] - br.base[1], br.tip[0] - br.base[0]);
      for (let side of [-1, 1]) {
        let nAng = dirAng + side * (0.42 + 0.35 * (1 - t)) + (noise(bx * 0.05, by * 0.05) - 0.5) * 0.25;
        let nLen = (14 + 18 * Math.sin(t * Math.PI)) * br.sc * (0.75 + 0.35 * ((i * 7) % 3) / 2);

        let nx1 = bx + Math.cos(nAng) * nLen * 0.52;
        let ny1 = by + Math.sin(nAng) * nLen * 0.52;
        let nx2 = bx + Math.cos(nAng + side * 0.16) * nLen;
        let ny2 = by + Math.sin(nAng + side * 0.16) * nLen;

        // Shadow needle pass
        drawSpline([[bx, by + 2], [nx1, ny1 + 2], [nx2, ny2 + 2]], "rotring", "#090f05", 0.9, 0.4);

        // Deep forest-bronze & olive-gold needle body
        let midCol = (i + side) % 3 === 0 ? "#243010" : "#3f4d16";
        drawSpline([[bx, by], [nx1, ny1], [nx2, ny2]], "rotring", midCol, 0.85, 0.5);

        // Ceremonial warm gold & chartreuse-amber rim light on upper-facing needles
        if (side === -1 || i % 2 === 0) {
          let hiCol = t > 0.6 ? "#d4b535" : "#878c22";
          drawSpline([[nx1, ny1], [nx2, ny2]], "gold_pen", hiCol, 0.7, 0.4);
        }

        // Bifurcated feathery fork at needle tip
        if (i % 2 === 0 && t > 0.15 && t < 0.9) {
          let fx = nx1 + Math.cos(nAng - side * 0.28) * nLen * 0.48;
          let fy = ny1 + Math.sin(nAng - side * 0.28) * nLen * 0.48;
          drawSpline([[nx1, ny1], [fx, fy]], "gold_pen", "#b8a32c", 0.65, 0.3);
        }
      }
    }

    // Secondary branch stem
    drawSpline([br.base, mid, br.tip], "rotring", "#2b3610", 1.15 * br.sc, 0.5);
    drawSpline([br.base, mid, br.tip], "gold_pen", "#7d7a1e", 0.75 * br.sc, 0.5);
  }

  // 3. Main central dill stem with warm golden specular ridge
  drawSpline(stemMain, "pen", "#1e260b", 2.1, 0.5);
  drawSpline(stemMain, "rotring", "#495418", 1.5, 0.5);
  let stemHi = stemMain.map(p => [p[0] - 1, p[1] - 1.2]);
  drawSpline(stemHi, "gold_pen", "#c4ad31", 0.95, 0.5);

  // Tiny dewy golden glints on the dill tips
  let dewPts = [[695, 902], [778, 848], [875, 802], [945, 938], [1028, 882]];
  for (let dp of dewPts) {
    polyWash(ellipsePts(dp[0], dp[1], 2.2, 1.6, 8), "#fff2a6", 230);
  }
}

// ============================================================================
// 10. FINAL CEREMONIAL HIGHLIGHTS & WINTRY ATMOSPHERE
