function drawFinalHighlights() {
  // Subtle, gossamer wisps of warm rose-gold steam rising above the hot borscht
  for (let w = 0; w < 5; w++) {
    let wx = CX - 90 + w * 52;
    let wy = CY - 95 - (w % 2) * 35;
    let wispPts = [];
    for (let s = 0; s <= 8; s++) {
      let st = s / 8;
      wispPts.push([
        wx + Math.sin(st * Math.PI * 2 + w) * 28,
        wy - st * 185
      ]);
    }
    drawSpline(wispPts, "oil_glaze", w % 2 === 0 ? "#4a1c24" : "#3d2419", 1.6, 0.65);
  }

  // Final razor-sharp white specular pinpoints on the window highlight hotspot, sour cream peak, and rim
  let hotspots = [
    bowlPt(-46, 0.24),
    bowlPt(-39, 0.28),
    bowlPt(-24, 0.25),
    [CX - 48, SOUP_CY - 22],
    [CX - 32, SOUP_CY - 28],
    [CX - 285, CY + 165]
  ];
  for (let hp of hotspots) {
    polyWash(ellipsePts(hp[0], hp[1], 3.2, 2.2, 10), "#ffffff", 250);
  }
}

