async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Custom Kistka (wax stylus) brushes — slightly beaded start/end from heated brass reservoir
  brush.add("kistka", {
    type: "default",
    weight: 0.42,
    scatter: 0.03,
    sharpness: 0.94,
    grain: 16,
    opacity: 245,
    spacing: 0.2,
    pressure: [1.35, 0.85, 1.3],
    noise: 0.22
  });

  brush.add("kistka_hair", {
    type: "default",
    weight: 0.26,
    scatter: 0.02,
    sharpness: 0.96,
    grain: 12,
    opacity: 240,
    spacing: 0.16,
    pressure: [1.3, 0.8, 0.15],
    noise: 0.15
  });

  brush.add("kistka_bead", {
    type: "default",
    weight: 0.55,
    scatter: 0.06,
