    spacing: 0.25,
    pressure: [0.6, 1.1, 0.6],
    markerTip: false,
    noise: 0.1
  });
}

// Safe helper to guarantee brush.set() is active and fills are cleared before strokes
function useKistka(name, col, w = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set(name, col, w);
}

// Draw a filled polygon using wash (lacquered dye-bath layer)
function drawDyePolygon(pts, col, opacity = 220) {
  brush.noStroke();
  brush.noFill();
  brush.wash(col, opacity);
  brush.beginShape(0.15);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

// Draw a beaded wax line (simulates kistka stylus rhythm)
function waxLine(x1, y1, x2, y2, col, w = 1, beaded = false) {
  useKistka(beaded ? "kistka_bead" : "kistka", col, w);
  brush.line(x1, y1, x2, y2);
}

// Draw a smooth wax spline
function waxSpline(pts, col, w = 1, curv = 0.5, brushName = "kistka") {
  if (pts.length < 2) return;
  useKistka(brushName, col, w);
  brush.spline(pts, curv);
}

// Draw a tiny wax drop / kistka tear-drop bead (classic pysanky mark)
function waxDrop(x, y, ang, len, col, w = 1) {
  useKistka("kistka", col, w * 1.3);
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  let xm = x + cos(ang) * (len * 0.35);
  let ym = y + sin(ang) * (len * 0.35);
  brush.spline([[x, y, 1.6], [xm, ym, 1.1], [x2, y2, 0.2]], 0.3);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.abyssBlack);

  // 1. LACQUERED EGGSHELL GROUND & SUBTLE PYSANKY MERIDIAN LINES
  renderLacqueredGround();

  // 2. DRIED THISTLE STEM, SPINY LEAVES & SECONDARY BUD
  renderThistleStemAndLeaves();

  // 3. MAIN THISTLE HEAD: INVOLUCRE BRACTS & BURSTING PAPPUS SILK CROWN
  renderMainThistleHead();

  // 4. GOLDFINCH: ANATOMICAL DYE-BATH FOUNDATION & PLUMAGE TRACTS
  renderGoldfinchUnderlayers();
  renderGoldfinchTail();
  renderGoldfinchBodyAndMantle();
  renderGoldfinchWing();
  renderGoldfinchHeadAndBeak();
  renderGoldfinchLegsAndClaws();

  // 5. FOREGROUND THISTLE SPINES & SEED PLUCKED IN BEAK (FINAL WAX RESERVES)
  renderForegroundDetails();

  noLoop();
}

// ============================================================================
// 1. LACQUERED EGGSHELL GROUND & PYSANKY BORDER WHISPERS
// ============================================================================
function renderLacqueredGround() {
  // Deep Prussian-black ovoid dye layers to evoke a curved, glossy dark eggshell
  const cx = 560, cy = 580;
  const radii = [580, 490, 400, 310, 230];
  const cols = [PAL.blueBlack, "#09172B", "#0D203A", "#102747", "#0C1D36"];
  const alphas = [180, 90, 65, 50, 40];

  for (let i = 0; i < radii.length; i++) {
    let pts = [];
    let r = radii[i];
    for (let a = 0; a < 360; a += 15) {
      // Egg-shaped ovoid distortion
      let eggFactor = 1 + 0.08 * sin(a);
      let px = cx + cos(a) * r * 0.92 * eggFactor;
      let py = cy + sin(a) * r * 1.08;
      pts.push([px, py]);
    }
    drawDyePolygon(pts, cols[i], alphas[i]);
  }

  // Subtle concentric lacquer contour lines & surface craze in deep indigo
  for (let ring = 0; ring < 38; ring++) {
    let r = 220 + ring * 18;
    let startA = random(360);
    let span = random(45, 130);
    let pts = [];
    for (let a = startA; a <= startA + span; a += 8) {
      let eggF = 1 + 0.07 * sin(a);
      let px = cx + cos(a) * r * 0.94 * eggF;
      let py = cy + sin(a) * r * 1.06;
      if (px > 35 && px < 1165 && py > 35 && py < 1165) {
        pts.push([px, py]);
      }
    }
    if (pts.length >= 3) {
      waxSpline(pts, ring % 3 === 0 ? PAL.indigoMid : PAL.indigoDark, 0.55, 0.5, "kistka_hair");
    }
  }

  // Glossy curved eggshell specular reflection arc in upper-left quadrant
  for (let i = 0; i < 42; i++) {
    let t = i / 41;
    let r = lerp(420, 485, t);
    let a1 = lerp(195, 212, sin(t * 180));
    let a2 = lerp(248, 232, sin(t * 180));
    let pts = [];
    for (let a = a1; a <= a2; a += 4) {
      let px = cx + cos(a) * r * 0.92 + random(-1.5, 1.5);
      let py = cy + sin(a) * r * 1.06 + random(-1.5, 1.5);
      pts.push([px, py]);
    }
    let col = i % 4 === 0 ? PAL.whiteIce : (i % 2 === 0 ? PAL.indigoGlint : PAL.indigoMid);
    waxSpline(pts, col, map(sin(t * 180), 0, 1, 0.25, 0.65), 0.4, "kistka_hair");
  }

  // Pysanky Kistka Marginal Framing Lines & Corner Star-Thistle Motifs
  const m = 34;
  const m2 = 46;
  // Outer double kistka border in deep Prussian blue & cochineal/marigold micro-beads
  waxLine(m, m, 1200 - m, m, PAL.indigoMid, 0.9);
  waxLine(1200 - m, m, 1200 - m, 1200 - m, PAL.indigoMid, 0.9);
  waxLine(1200 - m, 1200 - m, m, 1200 - m, PAL.indigoMid, 0.9);
  waxLine(m, 1200 - m, m, m, PAL.indigoMid, 0.9);

  waxLine(m2, m2, 1200 - m2, m2, PAL.cochinealDark, 0.65);
  waxLine(1200 - m2, m2, 1200 - m2, 1200 - m2, PAL.cochinealDark, 0.65);
  waxLine(1200 - m2, 1200 - m2, m2, 1200 - m2, PAL.cochinealDark, 0.65);
  waxLine(m2, 1200 - m2, m2, m2, PAL.cochinealDark, 0.65);

  // Tiny pysanky zig-zag (kryvulka) & beaded dots along the inner frame channel
  for (let s = 80; s < 1120; s += 24) {
    // Top & bottom
    waxLine(s, m, s + 12, m2, PAL.indigoGlint, 0.5);
    waxLine(s + 12, m2, s + 24, m, PAL.indigoGlint, 0.5);
    waxLine(s, 1200 - m, s + 12, 1200 - m2, PAL.indigoGlint, 0.5);
    waxLine(s + 12, 1200 - m2, s + 24, 1200 - m, PAL.indigoGlint, 0.5);
    // Left & right
    waxLine(m, s, m2, s + 12, PAL.indigoGlint, 0.5);
    waxLine(m2, s + 12, m, s + 24, PAL.indigoGlint, 0.5);
    waxLine(1200 - m, s, 1200 - m2, s + 12, PAL.indigoGlint, 0.5);
    waxLine(1200 - m2, s + 12, 1200 - m, s + 24, PAL.indigoGlint, 0.5);

    if (s % 48 === 8) {
      waxDrop(s + 12, m + 4, 90, 4, PAL.marigoldMid, 0.55);
      waxDrop(s + 12, 1200 - m - 4, -90, 4, PAL.marigoldMid, 0.55);
      waxDrop(m + 4, s + 12, 0, 4, PAL.marigoldMid, 0.55);
      waxDrop(1200 - m - 4, s + 12, 180, 4, PAL.marigoldMid, 0.55);
    }
  }

  // Four corner Pysanky 8-pointed rosette whispers (strict dye-bath order)
  const corners = [[66, 66], [1134, 66], [1134, 1134], [66, 1134]];
  for (let [kx, ky] of corners) {
    for (let a = 0; a < 360; a += 45) {
      let r1 = (a % 90 === 0) ? 22 : 15;
      waxDrop(kx + cos(a) * 4, ky + sin(a) * 4, a, r1, PAL.cochinealMid, 0.65);
      waxDrop(kx + cos(a) * 5, ky + sin(a) * 5, a, r1 * 0.75, PAL.marigoldMid, 0.55);
      waxDrop(kx + cos(a) * 6, ky + sin(a) * 6, a, r1 * 0.45, PAL.lemonBright, 0.45);
    }
    useKistka("kistka_bead", PAL.whiteEgg, 0.8);
    brush.circle(kx, ky, 3.5);
  }
}

// ============================================================================
// 2. DRIED THISTLE STEM, SPINY LEAVES & SECONDARY BUD
// ============================================================================
function renderThistleStemAndLeaves() {
  // Main woody ridged stem from bottom-left (270, 1166) up to receptacle base (455, 650)
  const stemCenter = [
    [275, 1164],
    [325, 1030],
    [378, 900],
    [422, 775],
    [455, 645]
  ];

  // Under-dye base for stem
  let stemPoly = [
    [255, 1164], [308, 1030], [362, 900], [408, 775], [442, 645],
    [470, 645], [438, 775], [395, 900], [344, 1030], [295, 1164]
  ];
  drawDyePolygon(stemPoly, PAL.blueBlack, 240);

  // Longitudinal stem vascular ridges in dye-bath sequence: cochineal -> marigold -> lemon -> white
  for (let offset = -16; offset <= 16; offset += 2.2) {
    let norm = offset / 16; // -1 to 1
    let ridgePts = [];
    for (let i = 0; i < stemCenter.length; i++) {
      let [sx, sy] = stemCenter[i];
      let wScale = map(i, 0, stemCenter.length - 1, 1.15, 0.78);
      ridgePts.push([sx + offset * wScale + sin(i * 55) * 1.5, sy]);
    }
    let col = PAL.indigoMid;
    let w = 0.65;
    if (abs(norm + 0.35) < 0.18) {
      col = PAL.whiteEgg;
      w = 0.8;
    } else if (abs(norm + 0.25) < 0.35) {
      col = PAL.lemonMid;
      w = 0.7;
    } else if (norm < 0.2) {
      col = PAL.marigoldMid;
      w = 0.7;
    } else if (norm < 0.65) {
      col = PAL.cochinealMid;
      w = 0.65;
    }
    waxSpline(ridgePts, col, w, 0.45, "kistka");
  }

  // Stem spiny wings (cauline ridges with sharp radiating needle spines)
  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    let sx = bezierPoint(275, 340, 410, 455, t);
    let sy = bezierPoint(1160, 990, 810, 650, t);
    let side = (i % 2 === 0) ? -1 : 1;
    let bx = sx + side * lerp(18, 12, t);
    let by = sy;
    let spineLen = random(18, 42);
    let ang = side === -1 ? random(145, 215) : random(-35, 35);

    // Bract lobe at spine base
    waxDrop(bx, by, ang, spineLen * 0.55, PAL.cochinealMid, 0.85);
    waxDrop(bx, by, ang, spineLen * 0.75, PAL.marigoldMid, 0.7);
    // Needle spine in lemon & paper white
    waxLine(bx, by, bx + cos(ang) * spineLen, by + sin(ang) * spineLen, PAL.lemonBright, 0.65, true);
    waxLine(bx, by, bx + cos(ang) * (spineLen * 1.05), by + sin(ang) * (spineLen * 1.05), PAL.whitePure, 0.45);
  }

  // Spiky Desiccated Thistle Leaves
  drawSpinyThistleLeaf(335, 1005, -155, 210, 1);
  drawSpinyThistleLeaf(392, 875, -18, 225, -1);
  drawSpinyThistleLeaf(432, 745, -148, 155, 1);
  drawSpinyThistleLeaf(300, 1095, -22, 185, -1);

  // Secondary smaller dried thistle bud on a side branch at (235, 725)
  const branchPts = [[365, 920], [310, 855], [268, 790], [242, 735]];
  for (let off = -6; off <= 6; off += 2) {
    let pts = branchPts.map(p => [p[0] + off, p[1]]);
    let col = off < -2 ? PAL.lemonMid : (off < 2 ? PAL.marigoldMid : PAL.cochinealMid);
    waxSpline(pts, col, 0.65, 0.4, "kistka");
  }
  waxSpline(branchPts.map(p => [p[0] - 3, p[1]]), PAL.whiteEgg, 0.55, 0.4, "kistka_hair");
  drawSecondaryThistleBud(235, 710, -28);
}

function drawSpinyThistleLeaf(x0, y0, baseAngle, length, curlDir) {
  // Construct curved midrib
  let midrib = [];
  let steps = 14;
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = baseAngle + curlDir * sin(t * 200) * 28 + t * curlDir * 18;
    let r = t * length;
    let px = x0 + cos(a) * r;
    let py = y0 + sin(a) * r;
    midrib.push([px, py, a]);
  }

  // Dark dye silhouette under leaf lobes
  let leftEdge = [];
  let rightEdge = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let [px, py, a] = midrib[i];
    let lobeW = sin(t * 180) * 42 * (0.45 + 0.55 * abs(sin(t * 540)));
    leftEdge.push([px + cos(a - 90) * lobeW, py + sin(a - 90) * lobeW]);
    rightEdge.unshift([px + cos(a + 90) * lobeW, py + sin(a + 90) * lobeW]);
  }
  drawDyePolygon(leftEdge.concat(rightEdge), PAL.blueBlack, 235);

  // Leaf veins and spiny pinnatifid lobes in wax-resist order
  for (let i = 1; i < steps; i++) {
    let t = i / steps;
    let [px, py, a] = midrib[i];
    for (let side of [-1, 1]) {
      let lobeAng = a + side * 58 + random(-8, 8);
      let lobeLen = sin(t * 170) * 48 + (i % 2 === 0 ? 18 : -6);
      if (lobeLen < 12) continue;

      let tipX = px + cos(lobeAng) * lobeLen;
      let tipY = py + sin(lobeAng) * lobeLen;

      // Cochineal & marigold dried leaf lamina ribs
      for (let f = -0.35; f <= 0.35; f += 0.14) {
        let fa = lobeAng + f * 35;
        let fl = lobeLen * (1 - abs(f) * 0.65);
        let col = abs(f) > 0.2 ? PAL.cochinealMid : PAL.marigoldMid;
        waxSpline([
          [px, py],
          [px + cos(fa) * fl * 0.5, py + sin(fa) * fl * 0.5],
          [px + cos(fa) * fl, py + sin(fa) * fl]
        ], col, 0.55, 0.35, "kistka_hair");
      }

      // Crisp serrated margin in lemon yellow & long terminal spine in paper white
      let spineTipX = tipX + cos(lobeAng) * 24;
      let spineTipY = tipY + sin(lobeAng) * 24;
      waxLine(px, py, tipX, tipY, PAL.lemonMid, 0.65);
      waxLine(tipX, tipY, spineTipX, spineTipY, PAL.lemonBright, 0.7, true);
      waxLine(tipX, tipY, spineTipX + cos(lobeAng) * 5, spineTipY + sin(lobeAng) * 5, PAL.whitePure, 0.5);

      // Secondary side prickles
      for (let s of [-1, 1]) {
        let sa = lobeAng + s * 38;
        let sx = px + cos(lobeAng) * (lobeLen * 0.62);
        let sy = py + sin(lobeAng) * (lobeLen * 0.62);
        waxLine(sx, sy, sx + cos(sa) * 16, sy + sin(sa) * 16, PAL.lemonMid, 0.5);
        waxLine(sx + cos(sa) * 8, sy + sin(sa) * 8, sx + cos(sa) * 19, sy + sin(sa) * 19, PAL.whiteEgg, 0.4);
      }
    }
  }

  // Prominent midrib (marigold -> lemon -> crisp white central wire)
  let midPts = midrib.map(p => [p[0], p[1]]);
  waxSpline(midPts, PAL.marigoldMid, 1.3, 0.4, "kistka");
  waxSpline(midPts.map(p => [p[0] - 1.2, p[1] - 1.2]), PAL.lemonBright, 0.9, 0.4, "kistka");
  waxSpline(midPts, PAL.whitePure, 0.55, 0.4, "kistka_bead");

  // Terminal leaf spine
  let last = midrib[midrib.length - 1];
  waxLine(last[0], last[1], last[0] + cos(last[2]) * 34, last[1] + sin(last[2]) * 34, PAL.whitePure, 0.65);
}

function drawSecondaryThistleBud(cx, cy, tilt) {
  // Small ovoid spiny involucre with a tight tuft of crimson/white florets
  let budPoly = [];
  for (let a = 0; a < 360; a += 20) {
    let rad = 36 + 6 * sin(a * 2);
    budPoly.push([cx + cos(a) * rad * 0.85, cy + sin(a) * rad * 1.1]);
  }
  drawDyePolygon(budPoly, PAL.blueBlack, 245);

  // Small emerging pappus tuft at top-left of bud
  for (let i = 0; i < 42; i++) {
    let f = map(i, 0, 41, -1, 1);
    let ang = -90 + tilt + f * 32 + random(-4, 4);
    let len = random(28, 56) * (1 - 0.35 * f * f);
    let bx = cx + cos(-90 + tilt) * 24 + cos(ang + 90) * f * 14;
    let by = cy + sin(-90 + tilt) * 24 + sin(ang + 90) * f * 14;
    let col = i % 3 === 0 ? PAL.whitePure : (i % 3 === 1 ? PAL.lemonBright : PAL.cochinealBright);
    waxSpline([
      [bx, by],
      [bx + cos(ang) * len * 0.55, by + sin(ang) * len * 0.55],
      [bx + cos(ang - 12) * len, by + sin(ang - 12) * len]
    ], col, 0.45, 0.45, "kistka_hair");
  }

  // Tiered spiny bracts on bud
  for (let row = 0; row < 5; row++) {
    let yOff = map(row, 0, 4, -22, 26);
    let rowW = sin(map(row, 0, 4, 25, 155)) * 32;
    let count = 4 + (row % 2);
    for (let j = 0; j < count; j++) {
      let u = count === 1 ? 0 : map(j, 0, count - 1, -1, 1);
      let bx = cx + u * rowW + sin(tilt) * yOff;
      let by = cy + cos(tilt) * yOff - u * sin(tilt) * 8;
      let sAng = -90 + tilt + u * 68;
      drawSingleBractScale(bx, by, 14, 18, sAng, 22);
    }
  }
}

// ============================================================================
// 3. MAIN DRIED THISTLE HEAD: INVOLUCRE & PAPPUS SILK CROWN
// ============================================================================
function renderMainThistleHead() {
  const cx = 456, cy = 562;
  const tilt = -11; // Tilted slightly upper-left

  // --- A. BURSTING PAPPUS SILK CROWN (Rendered before upper bracts so collar overlaps base) ---
  const crownX = 442, crownY = 478;

  // Deep dye-bath core of the pappus tuft
  let pappusBasePoly = [];
  for (let a = 0; a < 360; a += 18) {
    let rx = a < 180 ? 95 : 135;
    let ry = a < 180 ? 60 : 125;
    pappusBasePoly.push([crownX - 18 + cos(a) * rx, crownY - 58 + sin(a) * ry]);
  }
  drawDyePolygon(pappusBasePoly, PAL.blueBlack, 210);

  // Layer 1 of Pappus: Dried Tubular Florets at the throat (Cochineal Red & Marigold Orange)
  for (let i = 0; i < 110; i++) {
    let u = random(-1, 1);
    let ang = -90 + tilt + u * 48 + random(-6, 6);
    let fx = crownX + u * 54 + random(-4, 4);
    let fy = crownY + abs(u) * 14 + random(-6, 6);
    let flen = random(38, 82) * (1 - 0.3 * u * u);
    let col = i % 2 === 0 ? PAL.cochinealBright : (i % 3 === 0 ? PAL.cochinealMid : PAL.marigoldMid);
    waxSpline([
      [fx, fy],
      [fx + cos(ang) * flen * 0.5, fy + sin(ang) * flen * 0.5],
      [fx + cos(ang - 8) * flen, fy + sin(ang - 8) * flen]
    ], col, 0.58, 0.45, "kistka");
    // Tiny 5-lobed floret star tip in marigold/lemon
    if (i % 3 === 0) {
      let tx = fx + cos(ang - 8) * flen;
      let ty = fy + sin(ang - 8) * flen;
      waxDrop(tx, ty, ang - 22, 6, PAL.marigoldLight, 0.45);
      waxDrop(tx, ty, ang + 8, 6, PAL.lemonMid, 0.45);
    }
  }

  // Layer 2 of Pappus: Lemon Yellow & Cool Ice-Blue Silk Filaments (Mid-depth wax reserve)
  for (let i = 0; i < 165; i++) {
    let u = map(i, 0, 164, -1.05, 1.05) + random(-0.04, 0.04);
    let bx = crownX + u * 56;
    let by = crownY + u * u * 12 + random(-8, 6);
    let baseAng = -92 + tilt + u * 56;
    let silkLen = random(95, 195) * (1 - 0.28 * u * u);
    let breezeCurve = -16 + u * 18 + random(-10, 10);

    let p1 = [bx, by];
    let p2 = [bx + cos(baseAng) * (silkLen * 0.38), by + sin(baseAng) * (silkLen * 0.38)];
    let p3 = [
      bx + cos(baseAng + breezeCurve * 0.5) * (silkLen * 0.72),
      by + sin(baseAng + breezeCurve * 0.5) * (silkLen * 0.72)
    ];
    let p4 = [
      bx + cos(baseAng + breezeCurve) * silkLen,
      by + sin(baseAng + breezeCurve) * silkLen
    ];

    let col = (i % 3 === 0) ? PAL.lemonBright : (i % 3 === 1 ? PAL.whiteIce : PAL.marigoldLight);
    waxSpline([p1, p2, p3, p4], col, random(0.38, 0.58), 0.55, "kistka_hair");
  }

  // Layer 3 of Pappus: Pure Paper-White & Eggshell-White Plumose Filaments (Earliest Wax Reserve!)
  for (let i = 0; i < 190; i++) {
    let u = map(i, 0, 189, -1.08, 1.02) + random(-0.03, 0.03);
    let bx = crownX + u * 54;
    let by = crownY - 4 + u * u * 14 + random(-10, 8);
    let baseAng = -94 + tilt + u * 62;
    let silkLen = random(110, 215) * (1 - 0.25 * u * u);
    let breeze = -18 + u * 22 + random(-8, 8);

    let p1 = [bx, by];
    let p2 = [bx + cos(baseAng) * (silkLen * 0.35), by + sin(baseAng) * (silkLen * 0.35)];
    let p3 = [
      bx + cos(baseAng + breeze * 0.55) * (silkLen * 0.7),
      by + sin(baseAng + breeze * 0.55) * (silkLen * 0.7)
    ];
    let p4 = [
      bx + cos(baseAng + breeze) * silkLen,
      by + sin(baseAng + breeze) * silkLen
    ];

    let col = (i % 4 === 0) ? PAL.lemonBright : (i % 2 === 0 ? PAL.whitePure : PAL.whiteEgg);
    waxSpline([p1, p2, p3, p4], col, random(0.35, 0.62), 0.55, "kistka_hair");

    // Microscopic feathery plumose side-barbs on selected foreground filaments
    if (i % 5 === 0) {
      for (let m = 0.25; m <= 0.88; m += 0.16) {
        let mx = lerp(p2[0], p4[0], m);
        let my = lerp(p2[1], p4[1], m);
        let barbA = baseAng + breeze * m + (m * 100 % 2 === 0 ? 38 : -38);
        waxLine(mx, my, mx + cos(barbA) * 9, my + sin(barbA) * 9, PAL.whitePure, 0.3);
      }
      // Tiny wax-bead seed/dewdrop glint at tip
      waxDrop(p4[0], p4[1], baseAng + breeze, 4.5, PAL.whitePure, 0.5);
    }
  }

  // Drifting parachute achenes (thistle seeds) floating in upper-left dark lacquer space
  const floatSeeds = [
    [255, 310, -125, 1.0],
    [185, 420, -142, 0.85],
    [325, 220, -108, 0.9],
    [165, 245, -135, 0.75]
  ];
  for (let [sx, sy, sang, sc] of floatSeeds) {
    drawThistleSeedParachute(sx, sy, sang, sc);
  }

  // --- B. SWELLING URN-SHAPED INVOLUCRE (TIERED SPINY PHYLLARIES / BRACTS) ---
  // Dark blue-black dye-bath silhouette for the involucre cup
  let cupPoly = [];
  for (let a = 0; a < 360; a += 12) {
    let radX = 82 * (1 + 0.18 * sin(a));
    let radY = 92;
    let px = cx + cos(a) * radX;
    let py = cy + sin(a) * radY;
    cupPoly.push([px, py]);
  }
  drawDyePolygon(cupPoly, PAL.blueBlack, 250);

  // Render 10 imbricated horizontal tiers of diamond-lanceolate bracts from top collar to base
  const rows = 10;
  for (let r = 0; r < rows; r++) {
    let v = r / (rows - 1); // 0 (top collar) to 1 (stem base)
    let yLocal = lerp(-76, 82, v);
    // Urn profile: pinched at top collar, wide belly in middle, tapering to stem at bottom
    let profileW = sin(lerp(32, 162, v)) * 84;
    if (v < 0.25) profileW = lerp(56, 76, v / 0.25);

    let count = Math.round(lerp(7, 11, sin(v * 180)));
    for (let j = 0; j < count; j++) {
      let u = count === 1 ? 0 : map(j, 0, count - 1, -1, 1);
      // Stagger alternate rows for Fibonacci phyllotaxis
      if (r % 2 === 1) u += (1 / count) * 0.45 * (u > 0 ? -1 : 1);
      u = constrain(u, -1.05, 1.05);

      let xLocal = u * profileW;
      // Rotate by head tilt
      let bx = cx + xLocal * cos(tilt) - yLocal * sin(tilt);
      let by = cy + xLocal * sin(tilt) + yLocal * cos(tilt) + (1 - u * u) * 8;

      // Spine outward angle fans from upward at collar to outward/downward at lower belly
      let spineAng = -90 + tilt + u * lerp(52, 108, v) + (v > 0.65 ? u * 25 : 0);
      let scaleW = lerp(17, 23, sin(v * 180)) * (1 - 0.2 * abs(u));
      let scaleH = lerp(24, 30, sin(v * 180));
      let spineLen = lerp(34, 58, sin(v * 165)) * (0.85 + 0.35 * abs(u));

      drawSingleBractScale(bx, by, scaleW, scaleH, spineAng, spineLen);
    }
  }
}

function drawSingleBractScale(bx, by, w, h, spineAng, spineLen) {
  let perp = spineAng + 90;
  let tipX = bx + cos(spineAng) * h;
  let tipY = by + sin(spineAng) * h;
  let leftX = bx + cos(perp) * (w * 0.5) + cos(spineAng) * (h * 0.25);
  let leftY = by + sin(perp) * (w * 0.5) + sin(spineAng) * (h * 0.25);
  let rightX = bx - cos(perp) * (w * 0.5) + cos(spineAng) * (h * 0.25);
  let rightY = by - sin(perp) * (w * 0.5) + sin(spineAng) * (h * 0.25);
  let baseX = bx - cos(spineAng) * (h * 0.35);
  let baseY = by - sin(spineAng) * (h * 0.35);

  // 1. Dark Blue-Black dye separator (gives crisp imbricated overlap)
  drawDyePolygon([[baseX, baseY], [leftX, leftY], [tipX, tipY], [rightX, rightY]], PAL.blueBlack, 240);

  // 2. Cochineal Red & Marigold lateral bract striae
  for (let s = -0.8; s <= 0.8; s += 0.32) {
    let sx = lerp(bx, s < 0 ? leftX : rightX, abs(s));
    let sy = lerp(by, s < 0 ? leftY : rightY, abs(s));
    let col = abs(s) > 0.5 ? PAL.cochinealMid : PAL.marigoldMid;
    waxLine(sx, sy, tipX, tipY, col, 0.52);
  }

  // 3. Lemon Yellow V-chevron & Marginal Cilia (micro-hairs on bract edge)
  waxLine(leftX, leftY, tipX, tipY, PAL.lemonMid, 0.65);
  waxLine(rightX, rightY, tipX, tipY, PAL.lemonCool, 0.55);

  for (let c = 0.2; c <= 0.85; c += 0.28) {
    let lx = lerp(leftX, tipX, c);
    let ly = lerp(leftY, tipY, c);
    waxLine(lx, ly, lx + cos(spineAng - 45) * 5.5, ly + sin(spineAng - 45) * 5.5, PAL.whiteEgg, 0.32);
    let rx = lerp(rightX, tipX, c);
    let ry = lerp(rightY, tipY, c);
    waxLine(rx, ry, rx + cos(spineAng + 45) * 5.5, ry + sin(spineAng + 45) * 5.5, PAL.lemonMid, 0.32);
  }

  // 4. Long Needle Spine radiating from bract apex (Marigold -> Lemon -> Paper White reserve)
  let curveOffset = (spineAng > -90 ? 7 : -7);
  let midSpineX = tipX + cos(spineAng + curveOffset * 0.5) * (spineLen * 0.55);
  let midSpineY = tipY + sin(spineAng + curveOffset * 0.5) * (spineLen * 0.55);
  let endSpineX = tipX + cos(spineAng + curveOffset) * spineLen;
  let endSpineY = tipY + sin(spineAng + curveOffset) * spineLen;

  waxSpline([[bx, by], [tipX, tipY], [midSpineX, midSpineY]], PAL.marigoldLight, 0.8, 0.35, "kistka");
  waxSpline([[tipX, tipY], [midSpineX, midSpineY], [endSpineX, endSpineY]], PAL.lemonBright, 0.65, 0.35, "kistka_bead");
  waxSpline([[tipX, tipY], [midSpineX, midSpineY], [endSpineX, endSpineY]], PAL.whitePure, 0.42, 0.35, "kistka_hair");
}

function drawThistleSeedParachute(sx, sy, ang, sc) {
  // Tiny ribbed seed achene (marigold + lemon + white glint)
  let seedLen = 13 * sc;
  let baseAx = sx - cos(ang) * seedLen;
  let baseAy = sy - sin(ang) * seedLen;
  waxDrop(baseAx, baseAy, ang, seedLen, PAL.cochinealBright, 0.85 * sc);
  waxDrop(baseAx, baseAy, ang, seedLen * 0.85, PAL.marigoldLight, 0.65 * sc);
  waxLine(baseAx, baseAy, sx, sy, PAL.whitePure, 0.5 * sc);

  // Fan of gossamer white & lemon pappus rays
  for (let i = -9; i <= 9; i++) {
    let rayA = ang + i * 7.5 + random(-2, 2);
    let rLen = (42 - abs(i) * 1.6) * sc;
    let mx = sx + cos(rayA) * (rLen * 0.5);
    let my = sy + sin(rayA) * (rLen * 0.5);
    let ex = sx + cos(rayA - i * 1.8) * rLen;
    let ey = sy + sin(rayA - i * 1.8) * rLen;
    let col = abs(i) % 3 === 0 ? PAL.lemonBright : PAL.whitePure;
    waxSpline([[sx, sy], [mx, my], [ex, ey]], col, 0.38 * sc, 0.45, "kistka_hair");
  }
}

// ============================================================================
// 4. GOLDFINCH: ANATOMICAL DYE-BATH FOUNDATION & PLUMAGE TRACTS
// ============================================================================

// Core hyperreal feather primitive following strict wax-resist dye-bath order
function drawPysankyFeather(x, y, len, wid, ang, curveDeg, colors, opts = {}) {
  let midAng = ang + curveDeg * 0.5;
  let endAng = ang + curveDeg;
  let mx = x + cos(midAng) * (len * 0.52);
  let my = y + sin(midAng) * (len * 0.52);
  let ex = x + cos(endAng) * len;
  let ey = y + sin(endAng) * len;

  // 1. Dark Blue-Black dye-bath silhouette for crisp feather separation
  let pL1 = [x + cos(ang - 90) * wid * 0.32, y + sin(ang - 90) * wid * 0.32];
  let pL2 = [mx + cos(midAng - 90) * wid * 0.52, my + sin(midAng - 90) * wid * 0.52];
  let pTip = [ex + cos(endAng) * 3, ey + sin(endAng) * 3];
  let pR2 = [mx + cos(midAng + 90) * wid * 0.52, my + sin(midAng + 90) * wid * 0.52];
  let pR1 = [x + cos(ang + 90) * wid * 0.32, y + sin(ang + 90) * wid * 0.32];
  drawDyePolygon([pL1, pL2, pTip, pR2, pR1], opts.bgCol || PAL.blueBlack, opts.bgAlpha || 235);

  // 2. Parallel herringbone feather barbs along both webs
  let steps = opts.steps || Math.max(10, Math.round(len / 3.2));
  for (let i = 1; i <= steps; i++) {
    let t = i / steps;
    // Point along curved rachis
    let rx = bezierPoint(x, mx, mx, ex, t);
    let ry = bezierPoint(y, my, my, ey, t);
    let curAng = lerp(ang, endAng, t);
    let localW = wid * sin(constrain(t * 165 + 15, 0, 180)) * 0.55;

    for (let side of [-1, 1]) {
      let sideCol = side === -1 ? (colors.outerWeb || colors.main) : (colors.innerWeb || colors.shadow || colors.main);
      if (t > 0.78 && colors.tip) sideCol = colors.tip;

      let barbAng = curAng + side * lerp(36, 22, t);
      let bLen = localW / sin(32);
      if (bLen < 2) continue;

      let bx = rx + cos(barbAng) * bLen;
      let by = ry + sin(barbAng) * bLen;

      // Primary dye barb
      waxLine(rx, ry, bx, by, sideCol, opts.barbWeight || 0.48);

      // Wax-reserved lighter barb tip or highlight edge
      if (colors.edgeHighlight && (i % 2 === 0 || t > 0.72)) {
        let hx = lerp(rx, bx, 0.58);
        let hy = lerp(ry, by, 0.58);
        waxLine(hx, hy, bx, by, colors.edgeHighlight, (opts.barbWeight || 0.48) * 0.82);
      }
    }
  }

  // 3. White / Lemon Apical Spot (Classic Goldfinch white shield at primary/tertial tips)
  if (opts.apicalSpot) {
    let spotStart = opts.spotStart || 0.82;
    for (let t = spotStart; t <= 1.0; t += 0.025) {
      let rx = bezierPoint(x, mx, mx, ex, t);
      let ry = bezierPoint(y, my, my, ey, t);
      let curAng = lerp(ang, endAng, t);
      let spotW = wid * sin((1 - (t - spotStart) / (1 - spotStart) * 0.45) * 90) * 0.42;
      for (let side of [-1, 1]) {
        let ba = curAng + side * 24;
        waxLine(rx, ry, rx + cos(ba) * spotW, ry + sin(ba) * spotW, PAL.whitePure, 0.58);
      }
    }
  }

  // 4. Crisp Kistka Central Shaft (Rachis)
  waxSpline([[x, y, 1.3], [mx, my, 0.95], [ex, ey, 0.3]], colors.rachis || PAL.whiteEgg, opts.rachisWeight || 0.65, 0.45, "kistka");
}

function renderGoldfinchUnderlayers() {
  // Master silhouette of the goldfinch in deep glossy blue-black dye bath
  const bodySil = [
    [526, 336], [562, 306], [615, 302], [662, 332], [740, 405],
    [810, 505], [860, 620], [935, 765], [845, 745], [785, 755],
    [695, 710], [615, 645], [560, 555], [542, 465], [556, 398], [530, 370]
  ];
  drawDyePolygon(bodySil, PAL.blueBlack, 250);

  // Subtle dye-bath under-glows for the major color zones
  // 1. White Cheek & Belly reserve zone
  drawDyePolygon([[578, 332], [635, 342], [648, 388], [602, 422], [562, 396]], PAL.indigoDark, 180);
  drawDyePolygon([[585, 535], [665, 575], [785, 685], [765, 745], [665, 695], [595, 620]], PAL.indigoDark, 180);

  // 2. Lemon & Marigold Wing-Bar reserve zone
  drawDyePolygon([[650, 475], [765, 505], [840, 610], [725, 625], [655, 540]], PAL.marigoldDeep, 175);

  // 3. Cochineal Red Facial Mask dye bath
  drawDyePolygon([[525, 336], [560, 308], [585, 318], [582, 388], [556, 398], [530, 370]], PAL.cochinealDark, 225);
}

// ============================================================================
// GOLDFINCH TAIL (Forked Rectrices with White Inner Mirrors)
// ============================================================================
function renderGoldfinchTail() {
  // Uppertail & Undertail Coverts (Crisp Eggshell White & Cool Ice-Blue Barbs)
  for (let i = 0; i < 18; i++) {
    let t = i / 17;
    let cx = lerp(795, 855, t) + random(-4, 4);
    let cy = lerp(695, 635, t) + random(-4, 4);
    drawPysankyFeather(cx, cy, 46, 16, 38 - t * 12, 5, {
      outerWeb: PAL.whiteIce,
      innerWeb: PAL.indigoMid,
      edgeHighlight: PAL.whitePure,
      rachis: PAL.whitePure
    }, { steps: 11, barbWeight: 0.45 });
  }

  // 6 Long Forked Tail Rectrices
  const tailFeathers = [
    // [x, y, len, wid, ang, curve, hasMirror]
    [825, 695, 245, 24, 48, 6, true],
    [835, 682, 232, 23, 44, 5, true],
    [842, 670, 212, 22, 40, 3, false],
    [848, 658, 205, 22, 36, 2, false],
    [854, 646, 225, 23, 32, -3, true],
    [860, 635, 242, 24, 28, -5, true]
  ];

  for (let idx = 0; idx < tailFeathers.length; idx++) {
    let [tx, ty, tlen, twid, tang, tcurv, mirror] = tailFeathers[idx];
    drawPysankyFeather(tx, ty, tlen, twid, tang, tcurv, {
      outerWeb: idx === 5 ? PAL.whiteEgg : PAL.indigoMid,
      innerWeb: PAL.blueBlack,
      edgeHighlight: idx === 0 || idx === 5 ? PAL.whitePure : PAL.indigoGlint,
      rachis: PAL.whiteEgg
    }, {
      steps: 42,
      barbWeight: 0.5,
      rachisWeight: 0.75,
      apicalSpot: true,
      spotStart: 0.88
    });

    // White tail mirror (inner-web oval wax reserve characteristic of Carduelis)
    if (mirror) {
      let mx = tx + cos(tang + tcurv * 0.6) * (tlen * 0.68);
      let my = ty + sin(tang + tcurv * 0.6) * (tlen * 0.68);
      for (let b = -14; b <= 14; b += 2.2) {
        let bx = mx + cos(tang) * b;
        let by = my + sin(tang) * b;
        let bl = sqrt(max(0, 196 - b * b)) * 0.75;
        let ba = tang + 32;
        waxLine(bx, by, bx + cos(ba) * bl, by + sin(ba) * bl, PAL.whitePure, 0.48);
      }
    }
  }
}

// ============================================================================
// GOLDFINCH BODY: MANTLE, RUMP, BREAST & FLANKS
// ============================================================================
function renderGoldfinchBodyAndMantle() {
  // 1. RUMP (Crisp Eggshell White & Lemon-White Feather Tract at lower back)
  for (let row = 0; row < 5; row++) {
    for (let j = 0; j < 6; j++) {
      let rx = 775 + row * 14 + j * 6 + random(-2, 2);
      let ry = 555 + row * 16 + j * 9 + random(-2, 2);
      drawPysankyFeather(rx, ry, 34, 15, 42 + j * 2, 4, {
        outerWeb: PAL.whiteEgg,
        innerWeb: PAL.whiteIce,
        edgeHighlight: PAL.whitePure,
        rachis: PAL.whitePure
      }, { steps: 9, barbWeight: 0.45 });
    }
  }

  // 2. MANTLE & SCAPULARS (Rich Cochineal-Russet, Marigold Orange & Cool Slate-Lemon Saddle)
  for (let row = 8; row >= 0; row--) {
    let v = row / 8; // 0 near nape, 1 near lower back
    let colsInRow = 7;
    for (let c = 0; c < colsInRow; c++) {
      let u = c / (colsInRow - 1);
      let fx = lerp(652, 775, v) - u * lerp(22, 48, v) + random(-2, 2);
      let fy = lerp(348, 535, v) + u * lerp(18, 42, v) + random(-2, 2);
      let fang = lerp(36, 52, v) + u * 8;
      let flen = lerp(26, 42, v);
      let fwid = lerp(13, 19, v);

      drawPysankyFeather(fx, fy, flen, fwid, fang, 5, {
        outerWeb: (c + row) % 2 === 0 ? PAL.marigoldMid : PAL.cochinealMid,
        innerWeb: PAL.cochinealDark,
        edgeHighlight: c % 2 === 0 ? PAL.lemonMid : PAL.marigoldLight,
        tip: PAL.marigoldLight,
        rachis: PAL.lemonBright
      }, { steps: 10, barbWeight: 0.48, rachisWeight: 0.55 });
    }
  }

  // 3. BELLY, VENT & FLANKS (Luminous Eggshell White & Cool Ice-Blue Semiplumes)
  for (let row = 9; row >= 0; row--) {
    let v = row / 9; // 0 upper breast, 1 lower belly/vent
    let count = 8;
    for (let c = 0; c < count; c++) {
      let u = c / (count - 1); // 0 ventral edge, 1 toward wing flank
      let bx = lerp(552, 725, v) + u * lerp(65, 85, sin(v * 180)) + random(-2, 2);
      let by = lerp(420, 710, v) - u * lerp(10, 35, v) + random(-2, 2);
      let bang = lerp(58, 38, v) - u * 12;
      let blen = lerp(28, 42, sin(v * 150 + 20));
      let bwid = lerp(14, 20, sin(v * 150 + 20));

      // Upper chest & sides have warm Marigold & Cochineal pectoral wash; center & lower belly are crisp Paper White
      let isPectoral = (v < 0.52 && (u < 0.45 || u > 0.55)) || (u > 0.68 && v < 0.78);
      let outerC = isPectoral ? PAL.marigoldMid : PAL.whiteEgg;
      let innerC = isPectoral ? PAL.cochinealMid : PAL.whiteIce;
      let edgeC = isPectoral ? PAL.lemonBright : PAL.whitePure;

      drawPysankyFeather(bx, by, blen, bwid, bang, 6, {
        outerWeb: outerC,
        innerWeb: innerC,
        edgeHighlight: edgeC,
        rachis: PAL.whitePure
      }, { steps: 10, barbWeight: 0.46, rachisWeight: 0.5 });
    }
  }

  // Extra fine fluffy ventral contour barbs along the breast curve (cutting into the dark lacquer ground)
  for (let i = 0; i < 68; i++) {
    let t = i / 67;
    let vx = bezierPoint(552, 536, 585, 745, t);
    let vy = bezierPoint(408, 520, 645, 735, t);
    let vang = lerp(115, 45, t) + random(-8, 8);
    let vlen = random(14, 26);
    let col = (t > 0.12 && t < 0.42 && i % 2 === 0) ? PAL.marigoldLight : (i % 3 === 0 ? PAL.lemonBright : PAL.whitePure);
    waxSpline([
      [vx, vy],
      [vx + cos(vang) * vlen * 0.5, vy + sin(vang) * vlen * 0.5],
      [vx + cos(vang - 12) * vlen, vy + sin(vang - 12) * vlen]
    ], col, 0.45, 0.45, "kistka_hair");
  }
}

// ============================================================================
// GOLDFINCH WING (Black Coverts, Blazing Lemon/Marigold Bar, White-Tipped Primaries)
// ============================================================================
function renderGoldfinchWing() {
  // 1. TERTIALS & DISTAL PRIMARIES (Drawn first so Greater Coverts & Wing-Bar overlap their bases)
  // 9 Long Primaries sweeping from (710, 560) to (935, 775)
  for (let p = 8; p >= 0; p--) {
    let t = p / 8; // 0 = innermost primary, 1 = outermost longest primary
    let px = lerp(695, 755, t);
    let py = lerp(555, 535, t);
    let plen = lerp(135, 245, pow(t, 0.85));
    let pwid = lerp(21, 18, t);
    let pang = lerp(47, 40, t);

    drawPysankyFeather(px, py, plen, pwid, pang, -3, {
      outerWeb: p < 6 ? PAL.lemonBright : PAL.indigoGlint,
      innerWeb: PAL.blueBlack,
      edgeHighlight: p < 6 ? PAL.whitePure : PAL.lemonBright,
      rachis: PAL.whitePure
    }, {
      steps: 38,
      barbWeight: 0.52,
      rachisWeight: 0.72,
      apicalSpot: true,
      spotStart: lerp(0.82, 0.90, t)
    });
  }

  // 3 Broad Tertial Feathers (Upper inner wing, velvet blue-black with bold white shield tips & marigold edge)
  const tertials = [
    [685, 515, 118, 25, 49],
    [702, 492, 112, 24, 46],
    [718, 468, 98, 22, 43]
  ];
  for (let [tx, ty, tlen, twid, tang] of tertials) {
    drawPysankyFeather(tx, ty, tlen, twid, tang, 4, {
      outerWeb: PAL.indigoMid,
      innerWeb: PAL.blueBlack,
      edgeHighlight: PAL.marigoldLight,
      rachis: PAL.whiteEgg
    }, {
      steps: 24,
      barbWeight: 0.54,
      rachisWeight: 0.7,
      apicalSpot: true,
      spotStart: 0.78
    });
  }

  // 2. THE BLAZING GOLDFINCH WING-BAR (Greater Coverts & Basal Primary Webs)
  // Strict wax-resist showcase: Paper White rachis & barb glints -> Lemon Yellow barbs -> Marigold Orange base/tips
  const wingBarCount = 12;
  for (let w = 0; w < wingBarCount; w++) {
    let t = w / (wingBarCount - 1); // 0 inner covert, 1 outer primary covert
    let wx = lerp(642, 748, t);
    let wy = lerp(492, 518, t) + sin(t * 180) * 10;
    let wlen = lerp(74, 108, sin(t * 140 + 20));
    let wwid = lerp(19, 21, sin(t * 180));
    let wang = lerp(52, 41, t);

    drawPysankyFeather(wx, wy, wlen, wwid, wang, -2, {
      outerWeb: PAL.lemonBright,
      innerWeb: PAL.marigoldMid,
      edgeHighlight: PAL.whitePure,
      tip: PAL.lemonBright,
      rachis: PAL.whitePure
    }, {
      steps: 24,
      barbWeight: 0.58,
      rachisWeight: 0.75,
      apicalSpot: w < 5,
      spotStart: 0.86
    });

    // Extra kistka beaded lemon & white wax highlights along the outer golden web
    let ex = wx + cos(wang) * (wlen * 0.85);
    let ey = wy + sin(wang) * (wlen * 0.85);
    waxLine(wx + 3, wy + 3, ex, ey, PAL.lemonBright, 0.65, true);
    waxDrop(ex, ey, wang, 7, PAL.whitePure, 0.55);
  }

  // 3. MEDIAN & LESSER WING COVERTS (Shoulder patch: Jet Blue-Black with Prussian Blue & Marigold Kistka Edging)
  for (let row = 3; row >= 0; row--) {
    let v = row / 3;
    let count = 6 + row;
    for (let c = 0; c < count; c++) {
      let u = c / (count - 1);
      let cx = lerp(632, 725, u) - (1 - v) * 14 + random(-1.5, 1.5);
      let cy = lerp(418, 455, u) + v * 20 + random(-1.5, 1.5);
      let cang = lerp(54, 42, u);
      let clen = lerp(24, 38, v);
      let cwid = lerp(13, 17, v);

      drawPysankyFeather(cx, cy, clen, cwid, cang, 3, {
        outerWeb: PAL.indigoMid,
        innerWeb: PAL.blueBlack,
        edgeHighlight: row === 3 ? PAL.marigoldLight : PAL.indigoGlint,
        tip: row === 3 ? PAL.lemonMid : PAL.indigoGlint,
        rachis: PAL.whiteIce
      }, { steps: 9, barbWeight: 0.46, rachisWeight: 0.5 });
    }
  }
}

// ============================================================================
// GOLDFINCH HEAD, COCHINEAL MASK, EYE & CONICAL BEAK
// ============================================================================
function renderGoldfinchHeadAndBeak() {
  // 1. BLACK CROWN & NECK COLLAR (Velvet Blue-Black etched with Indigo & White-Ice feather barbs)
  for (let row = 0; row < 5; row++) {
    let v = row / 4;
    for (let i = 0; i < 14; i++) {
      let u = i / 13;
      // Sweeps from top of crown (565, 310) over skull to neck ring (652, 412)
      let kx = bezierPoint(562, 608, 650, 654, u) - v * 9;
      let ky = bezierPoint(310, 304, 332, 412, u) + v * 6;
      let kang = lerp(8, 86, u);
      let klen = lerp(18, 25, sin(u * 180));
      drawPysankyFeather(kx, ky, klen, 10, kang, 4, {
        outerWeb: PAL.indigoMid,
        innerWeb: PAL.blueBlack,
        edgeHighlight: i % 3 === 0 ? PAL.whiteIce : PAL.indigoGlint,
        rachis: PAL.indigoGlint
      }, { steps: 7, barbWeight: 0.42, rachisWeight: 0.45 });
    }
  }

  // Pale whitish-lemon Nuchal Spot at the nape (660, 340)
  for (let i = 0; i < 12; i++) {
    let a = 15 + i * 5;
    waxDrop(654 + cos(a) * 4, 336 + sin(a) * 4, a, 15, i % 2 === 0 ? PAL.whiteEgg : PAL.lemonMid, 0.5);
  }

  // 2. WHITE CHEEK & EAR COVERTS (Radiating tracts of crisp Eggshell-White & Cool Ice-Blue feathers)
  const cheekCenter = [592, 358];
  for (let ring = 4; ring >= 0; ring--) {
    let r = 10 + ring * 9.5;
    for (let a = -25; a <= 135; a += 14) {
      let fx = cheekCenter[0] + cos(a) * r * 1.05;
      let fy = cheekCenter[1] + sin(a) * r * 0.95;
      let fang = a + 22;
      drawPysankyFeather(fx, fy, 19 + ring * 2, 10, fang, 5, {
        outerWeb: PAL.whiteEgg,
        innerWeb: PAL.whiteIce,
        edgeHighlight: PAL.whitePure,
        rachis: PAL.whitePure
      }, { steps: 7, barbWeight: 0.44, rachisWeight: 0.48 });
    }
  }

  // 3. THE COCHINEAL RED FACIAL BLAZE (Forehead, Supraorbital, Cheek & Chin)
  // Built in strict dye-bath order: Cochineal Dark -> Cochineal Bright -> Marigold -> Lemon & White bristle glints
  // Forehead & Crown-front tract (above eye)
  for (let r = 0; r < 4; r++) {
    for (let i = 0; i < 10; i++) {
      let u = i / 9;
      let fx = lerp(526, 580, u) + r * 3;
      let fy = lerp(336, 314, u) + r * 5.5 - sin(u * 180) * 6;
      let fang = lerp(-24, 12, u);
      drawPysankyFeather(fx, fy, 16, 8.5, fang, 3, {
        outerWeb: PAL.cochinealBright,
        innerWeb: PAL.cochinealDark,
        edgeHighlight: (i + r) % 2 === 0 ? PAL.marigoldLight : PAL.cochinealBright,
        tip: (i + r) % 3 === 0 ? PAL.lemonBright : PAL.marigoldLight,
        rachis: PAL.marigoldLight
      }, { steps: 6, barbWeight: 0.45, rachisWeight: 0.45 });
    }
  }

  // Lower Facial Mask: Malar & Chin tract (below eye and bill base)
  for (let r = 0; r < 4; r++) {
    for (let i = 0; i < 10; i++) {
      let u = i / 9;
      let fx = lerp(530, 584, u) + r * 2.5;
      let fy = lerp(368, 362, u) + r * 7.5 + sin(u * 180) * 5;
      let fang = lerp(135, 52, u);
      drawPysankyFeather(fx, fy, 16, 8.5, fang, 4, {
        outerWeb: PAL.cochinealBright,
        innerWeb: PAL.cochinealDark,
        edgeHighlight: (i + r) % 2 === 0 ? PAL.marigoldLight : PAL.cochinealBright,
        tip: (i + r) % 3 === 0 ? PAL.lemonBright : PAL.marigoldLight,
        rachis: PAL.marigoldLight
      }, { steps: 6, barbWeight: 0.45, rachisWeight: 0.45 });
    }
  }

  // Crisp kistka bristle-feathers around bill base & dark blue-black lores
  drawDyePolygon([[525, 344], [556, 340], [556, 355], [527, 360]], PAL.blueBlack, 245);
  for (let i = 0; i < 18; i++) {
    let lx = random(527, 552);
    let ly = random(343, 357);
    waxLine(lx, ly, lx + 7, ly + random(-2, 2), i % 3 === 0 ? PAL.cochinealMid : PAL.indigoMid, 0.38);
  }

  // 4. HYPERREAL EYE AT (560, 346)
  const ex = 560, ey = 346, er = 12.2;
  // Dark orbital ring
  let eyePoly = [];
  for (let a = 0; a < 360; a += 18) {
    eyePoly.push([ex + cos(a) * (er + 3.5), ey + sin(a) * (er + 3.2)]);
  }
  drawDyePolygon(eyePoly, PAL.abyssBlack, 255);

  // Iris: Deep cochineal-umber & Prussian indigo radial striae
  for (let a = 0; a < 360; a += 8) {
    let col = (a > 140 && a < 290) ? PAL.cochinealMid : PAL.indigoMid;
    if (a % 24 === 0) col = PAL.marigoldDeep;
    waxLine(
      ex + cos(a) * (er * 0.42),
      ey + sin(a) * (er * 0.42),
      ex + cos(a) * (er * 0.95),
      ey + sin(a) * (er * 0.95),
      col,
      0.45
    );
  }

  // Jet black pupil
  let pupilPoly = [];
  for (let a = 0; a < 360; a += 20) {
    pupilPoly.push([ex + cos(a) * (er * 0.55), ey + sin(a) * (er * 0.55)]);
  }
  drawDyePolygon(pupilPoly, PAL.abyssBlack, 255);

  // Beaded kistka eyelid ring (tiny wax droplets encircling the eye)
  for (let a = 0; a < 360; a += 16) {
    let rx = ex + cos(a) * (er + 2.2);
    let ry = ey + sin(a) * (er + 1.8);
    let col = (a > 200 && a < 340) ? PAL.marigoldLight : PAL.cochinealBright;
    if (a % 32 === 0) col = PAL.lemonBright;
    waxDrop(rx, ry, a, 3.2, col, 0.45);
  }

  // Razor-sharp Eggshell-White & Lemon Kistka Crescent Catchlight (Top-Left of Cornea)
  for (let r = er * 0.48; r <= er * 0.86; r += 0.9) {
    let pts = [];
    for (let a = 200; a <= 262; a += 8) {
      pts.push([ex + cos(a) * r, ey + sin(a) * r]);
    }
    waxSpline(pts, r > er * 0.75 ? PAL.lemonBright : PAL.whitePure, 0.65, 0.4, "kistka");
  }
  // Secondary lower corneal reflection glint
  waxSpline([
    [ex + cos(35) * (er * 0.72), ey + sin(35) * (er * 0.72)],
    [ex + cos(58) * (er * 0.72), ey + sin(58) * (er * 0.72)],
    [ex + cos(80) * (er * 0.72), ey + sin(80) * (er * 0.72)]
  ], PAL.whiteIce, 0.45, 0.4, "kistka_hair");

  // 5. SHARP CONICAL FINCH BEAK (Ivory-White & Lemon Wax Reserves with Dark Tip)
  // Upper Mandible: tip (462, 368), culmen base (526, 336), commissure base (534, 356)
  // Lower Mandible: tip (464, 371), commissure base (534, 356), gonys base (530, 372)
  drawDyePolygon([[462, 368], [526, 336], [534, 356], [530, 372], [464, 371]], PAL.blueBlack, 250);

  // Upper Mandible layered wax-resist lines (Marigold -> Lemon -> Eggshell White -> Paper White)
  for (let v = 0; v <= 1; v += 0.065) {
    let xStart = lerp(526, 534, v);
    let yStart = lerp(336, 356, v);
    let xMid = lerp(492, 496, v);
    let yMid = lerp(349, 362, v);
    let xTip = 462;
    let yTip = lerp(367, 369.5, v);

    let col = PAL.whiteEgg;
    if (v < 0.22) col = PAL.whitePure;
    else if (v < 0.55) col = PAL.whiteEgg;
    else if (v < 0.78) col = PAL.lemonMid;
    else col = PAL.marigoldMid;

    waxSpline([[xStart, yStart], [xMid, yMid], [xTip, yTip]], col, 0.55, 0.35, "kistka");
  }

  // Lower Mandible layered wax-resist lines
  for (let v = 0; v <= 1; v += 0.08) {
    let xStart = lerp(534, 530, v);
    let yStart = lerp(357, 372, v);
    let xMid = lerp(496, 496, v);
    let yMid = lerp(363, 371.5, v);
    let xTip = 464;
    let yTip = lerp(370, 372, v);

    let col = v < 0.4 ? PAL.marigoldMid : (v < 0.75 ? PAL.lemonMid : PAL.whiteEgg);
    waxSpline([[xStart, yStart], [xMid, yMid], [xTip, yTip]], col, 0.52, 0.35, "kistka");
  }

  // Dark blue-black horn tip & razor-sharp gape line (commissure)
  for (let t = 0; t < 0.28; t += 0.04) {
    let tx = lerp(462, 526, t);
    let ty1 = lerp(368, 336, t);
    let ty2 = lerp(371, 372, t);
    waxLine(462, 368.5, tx, lerp(ty1, ty2, 0.5), PAL.blueBlack, 0.65);
  }
  waxSpline([[462, 368.5], [496, 362.5], [534, 356]], PAL.blueBlack, 0.85, 0.35, "kistka");
  // Specular culmen ridge in pure paper white
  waxSpline([[472, 362], [496, 349], [525, 336.5]], PAL.whitePure, 0.75, 0.35, "kistka_bead");

  // Nostril (naris) & nasal bristles at (518, 344)
  useKistka("kistka", PAL.blueBlack, 1.1);
  brush.line(514, 346, 521, 343);
  for (let b = 0; b < 6; b++) {
    waxLine(524, 340 + b * 1.4, 511, 343 + b * 1.2, b % 2 === 0 ? PAL.lemonBright : PAL.cochinealBright, 0.38);
  }
}

// ============================================================================
// GOLDFINCH LEGS, SCUTELLATE TOES & CURVED CLAWS
// ============================================================================
function renderGoldfinchLegsAndClaws() {
  // Helper to draw a scutellate (scaled) bird toe + curved needle claw
  function drawToeAndClaw(pts, clawAng, clawLen) {
    // Dark dye backing
    waxSpline(pts, PAL.blueBlack, 3.2, 0.4, "kistka");
    waxSpline(pts, PAL.cochinealDark, 2.1, 0.4, "kistka");

    // Overlapping tarsal/digital scutes (scales) in marigold -> lemon -> eggshell white
    let steps = 9;
    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      let t2 = (i + 0.85) / steps;
      let sx = bezierPoint(pts[0][0], pts[1][0], pts[1][0], pts[2][0], t);
      let sy = bezierPoint(pts[0][1], pts[1][1], pts[1][1], pts[2][1], t);
      let ex = bezierPoint(pts[0][0], pts[1][0], pts[1][0], pts[2][0], t2);
      let ey = bezierPoint(pts[0][1], pts[1][1], pts[1][1], pts[2][1], t2);
      waxLine(sx, sy, ex, ey, PAL.marigoldMid, 1.2);
      waxLine(sx, sy - 1.2, ex, ey - 1.2, PAL.lemonBright, 0.75);
      waxDrop(sx, sy - 1.5, atan2(ey - sy, ex - sx), 4.5, PAL.whitePure, 0.55);
    }

    // Curved needle-sharp claw at tip of toe
    let tip = pts[2];
    let cmx = tip[0] + cos(clawAng) * (clawLen * 0.55);
    let cmy = tip[1] + sin(clawAng) * (clawLen * 0.55);
    let cex = tip[0] + cos(clawAng + 28) * clawLen;
    let cey = tip[1] + sin(clawAng + 28) * clawLen;

    waxSpline([tip, [cmx, cmy], [cex, cey]], PAL.blueBlack, 1.8, 0.45, "kistka");
    waxSpline([tip, [cmx, cmy], [cex, cey]], PAL.marigoldLight, 1.1, 0.45, "kistka");
    waxSpline([
      [tip[0], tip[1] - 1],
      [cmx, cmy - 1],
      [cex, cey]
    ], PAL.whitePure, 0.65, 0.45, "kistka_hair");
  }

  // --- UPPER LEG (Left foot gripping upper involucral bracts around (538, 562)) ---
  // Feathered tibia fluff at (592, 565)
  for (let i = 0; i < 14; i++) {
    let a = 135 + i * 6;
    waxDrop(595 + random(-6, 6), 562 + random(-6, 6), a, 22, i % 2 === 0 ? PAL.whiteEgg : PAL.marigoldLight, 0.52);
  }
  // Tarsus from (598, 578) to (544, 562)
  drawToeAndClaw([[598, 578], [570, 572], [544, 562]], 195, 4);
  // Three forward toes + rear hallux clasping bracts
  drawToeAndClaw([[544, 562], [525, 548], [506, 546]], 195, 22);
  drawToeAndClaw([[544, 562], [522, 562], [500, 566]], 185, 24);
  drawToeAndClaw([[544, 562], [525, 575], [508, 584]], 172, 20);
  drawToeAndClaw([[546, 564], [558, 580], [554, 594]], -125, 19);

  // --- LOWER LEG (Right foot clasping lower receptacle/stem at (542, 676)) ---
  // Feathered tibia fluff at (652, 650)
  for (let i = 0; i < 16; i++) {
    let a = 125 + i * 5.5;
    waxDrop(654 + random(-6, 6), 652 + random(-6, 6), a, 24, i % 2 === 0 ? PAL.whitePure : PAL.lemonMid, 0.52);
  }
  // Tarsus from (656, 668) to (546, 676)
  drawToeAndClaw([[656, 668], [602, 675], [546, 676]], 180, 4);
  // Three forward toes + hallux wrapping tightly around stem collar
  drawToeAndClaw([[546, 676], [524, 664], [502, 662]], 192, 22);
  drawToeAndClaw([[546, 676], [520, 678], [496, 682]], 182, 25);
  drawToeAndClaw([[546, 676], [524, 692], [504, 702]], 168, 21);
  drawToeAndClaw([[548, 678], [562, 694], [556, 708]], -130, 19);
}

// ============================================================================
// 5. FOREGROUND THISTLE SPINES & PLUCKED SEED IN BEAK (FINAL WAX RESERVES)
// ============================================================================
function renderForegroundDetails() {
  // Overlapping involucral spines in front of the bird's toes (anchors the bird into the plant!)
  const fgSpines = [
    [515, 556, -24, 38],
    [512, 576, 12, 34],
    [508, 672, -18, 36],
    [510, 692, 18, 32]
  ];
  for (let [sx, sy, sang, slen] of fgSpines) {
    waxLine(sx, sy, sx + cos(sang) * slen, sy + sin(sang) * slen, PAL.marigoldMid, 0.85);
    waxLine(sx, sy, sx + cos(sang) * slen, sy + sin(sang) * slen, PAL.lemonBright, 0.65, true);
    waxLine(sx, sy, sx + cos(sang) * (slen + 4), sy + sin(sang) * (slen + 4), PAL.whitePure, 0.45);
  }

  // Luminous Thistle Seed Achene held directly in the Goldfinch's Beak Tip at (462, 369)!
  const bx = 462, by = 369;
  // Seed body (Marigold + Lemon + Paper White bead)
  waxDrop(bx + 4, by + 1, 155, 16, PAL.cochinealBright, 1.1);
  waxDrop(bx + 3, by + 1, 155, 14, PAL.marigoldLight, 0.9);
  waxDrop(bx + 2, by + 1, 155, 11, PAL.lemonBright, 0.75);
  waxLine(bx + 2, by, bx - 9, by + 5, PAL.whitePure, 0.65);

  // Starburst of gossamer Paper-White & Lemon pappus filaments radiating from the plucked seed
  for (let i = 0; i < 28; i++) {
    let u = map(i, 0, 27, -1, 1);
    let ang = -148 + u * 68 + random(-4, 4);
    let len = random(38, 86) * (1 - 0.25 * u * u);
    let p1 = [bx - 4, by + 2];
    let p2 = [bx - 4 + cos(ang) * (len * 0.48), by + 2 + sin(ang) * (len * 0.48)];
    let p3 = [bx - 4 + cos(ang - 14) * len, by + 2 + sin(ang - 14) * len];
    let col = i % 3 === 0 ? PAL.lemonBright : (i % 4 === 0 ? PAL.marigoldLight : PAL.whitePure);
    waxSpline([p1, p2, p3], col, random(0.38, 0.58), 0.5, "kistka_hair");
    if (i % 4 === 0) {
      waxDrop(p3[0], p3[1], ang - 14, 4, PAL.whitePure, 0.45);
    }
  }
}

