// ============================================================================
// GEOMETRY, PERSPECTIVE & LIGHTING HELPERS
// ============================================================================

// Low-angle wide perspective: slight vertical convergence toward high zenith (600, -1950)
function roomX(xAtHorizon, y) {
  return 600 + (xAtHorizon - 600) * ((y + 1950) / (810 + 1950));
}

function clamp01(v) {
  return Math.max(0, Math.min(1, v));
}

function lerpHex(c1, c2, t) {
  t = clamp01(t);
  let r1 = parseInt(c1.slice(1, 3), 16), g1 = parseInt(c1.slice(3, 5), 16), b1 = parseInt(c1.slice(5, 7), 16);
  let r2 = parseInt(c2.slice(1, 3), 16), g2 = parseInt(c2.slice(3, 5), 16), b2 = parseInt(c2.slice(5, 7), 16);
  let r = Math.round(r1 + (r2 - r1) * t);
  let g = Math.round(g1 + (g2 - g1) * t);
  let b = Math.round(b1 + (b2 - b1) * t);
  return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
}

// Safe wrapper so stroke state is always valid after fill/wash calls
function restoreDefaultStroke() {
  brush.set("fine_graphite", "#2a1b24", 0.3);
}

function drawWatercolorPoly(pts, col, alpha, bleed = 0.28, tex = 0.45, border = 0.25, dir = "out") {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.beginShape(0.25);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
  restoreDefaultStroke();
}

function drawSharpPoly(pts, col, alpha, curvature = 0.05) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
  restoreDefaultStroke();
}

function makeEllipsePts(cx, cy, rx, ry, n = 14, rotDeg = 0, jitter = 0) {
  let pts = [];
  let cr = Math.cos(rotDeg * Math.PI / 180);
  let sr = Math.sin(rotDeg * Math.PI / 180);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * Math.PI * 2;
    let j = 1 + (jitter > 0 ? (noise(cx * 0.01 + i * 0.7, cy * 0.01) - 0.5) * 2 * jitter : 0);
    let lx = Math.cos(a) * rx * j;
    let ly = Math.sin(a) * ry * j;
    pts.push([cx + lx * cr - ly * sr, cy + lx * sr + ly * cr]);
  }
  return pts;
}

// Combined room illumination field at (x, y)
// Lamp source around (682, 470); Bathroom doorway source around (155, 580) + floor spill
function getRoomLight(x, y) {
  let dxL = (x - 682) / 390;
  let dyL = (y - 510) / 370;
  let lamp = Math.exp(-(dxL * dxL + dyL * dyL) * 1.35);

  let dxD = (x - 155) / 220;
  let dyD = (y - 580) / 340;
  let door = Math.exp(-(dxD * dxD + dyD * dyD) * 1.6) * 0.75;

  // Floor spill from doorway
  let dxS = (x - 210) / 310;
  let dyS = (y - 940) / 180;
  let spill = Math.exp(-(dxS * dxS + dyS * dyS) * 1.5) * 0.55;

  return clamp01(lamp + door * 0.65 + spill * 0.45);
}

// ============================================================================
// MAIN RENDERING PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  restoreDefaultStroke();

  // 1. Warm pastel paper ground (supports luminous transparent watercolor glazes)
  background("#f2dfc9");

  // 2. Base luminous pastel underpainting in the two light pools
  renderUnderpaintingPools();

  // 3. Deep transparent watercolor glazes (amber -> raw sienna -> burnt umber -> brownish-violet murk)
  renderAtmosphericGlazes();

  // 4. Room architecture, wallpaper grain, wainscot & the SHARP LAMPSHADE RING on the wall
  renderRoomArchitectureAndSharpRing();

  // 5. Bathroom doorway & warm pastel orange glow on the left
  renderBathroomDoorway();

  // 6. Midground soft graphite shadow grain & carpet texture
  renderBackgroundGraphiteAndCarpet();

  // 7. Credenza & TV with forensic dead grey CRT screen
  renderCredenzaAndTV();

  // 8. Motel bed & forensic floral polyester bedspread in 3D perspective
  renderBedAndFloralBedspread();

  // 9. Half-unpacked duffel bag on the bedspread inside the pool of light
  renderHalfUnpackedDuffel();

  // 10. Bedside nightstand, forensic glass ashtray & pleated lampshade
  renderNightstandAshtrayAndLamp();

  // 11. Final unifying peripheral murk & soft graphite shadow grain
  renderFinalShadowGrainAndMurk();

  noLoop();
}

