// ============================================================================
// 4. ROOM ARCHITECTURE & THE SHARP LAMPSHADE RING ON THE WALL
// ============================================================================
function renderRoomArchitectureAndSharpRing() {
  // Room corner vertical line at xAtHorizon = 248
  // Ceiling junction: left wall (0, 88) -> corner (roomX(248, 165), 165) -> right (1200, 112)
  // Floor baseboard junction: left wall (0, 912) -> corner (248, 800) -> right (1200, 845)

  // Subtle ceiling shadow plane
  let ceilingPts = [
    [-10, -10], [1210, -10], [1210, 112], [roomX(248, 165), 165], [-10, 88]
  ];
  drawWatercolorPoly(ceilingPts, "#231421", 95, 0.32, 0.55, 0.25);

  // Subtle wallpaper stripes on the main back wall (x_h from 255 to 1200)
  for (let xh = 265; xh <= 1190; xh += 28) {
    let yTop = map(xh, 248, 1200, 165, 112);
    let yBot = map(xh, 248, 1200, 625, 665); // down to chair rail
    let segs = 10;
    for (let s = 0; s < segs; s++) {
      let y1 = lerp(yTop, yBot, s / segs);
      let y2 = lerp(yTop, yBot, (s + 1) / segs);
      let x1 = roomX(xh, y1);
      let x2 = roomX(xh, y2);
      let ym = (y1 + y2) * 0.5;
      let xm = (x1 + x2) * 0.5;
      let L = getRoomLight(xm, ym);
      if (L > 0.16) {
        let col = lerpHex("#4a2b29", "#d69c6a", clamp01((L - 0.15) * 1.3));
        brush.set("fine_graphite", col, 0.22 + L * 0.14);
        brush.line(x1, y1, x2, y2);
        // Tiny faded floral/damask wallpaper fleck in the illuminated zone
        if (L > 0.35 && s % 2 === 0) {
          brush.set("fine_graphite", lerpHex("#8f5636", "#e8b688", L), 0.2);
          brush.line(xm - 3, ym - 2, xm + 3, ym + 2);
          brush.line(xm - 3, ym + 2, xm + 3, ym - 2);
        }
      }
    }
  }

  // --------------------------------------------------------------------------
  // THE SHARP RING ON THE WALL (Thrown by the pleated lampshade's top rim)
  // "with heavy gradients and no hard edges except where the lampshade throws
  //  its sharp ring onto the wall."
  // --------------------------------------------------------------------------
  let ringCx = 682;
  let ringCy = 352;
  let outerRx = 238;
  let outerRy = 148;
  let innerRx = 212;
  let innerRy = 130;

  // Soft warm glow inside the upper light cone before the sharp boundary
  drawWatercolorPoly(makeEllipsePts(ringCx, ringCy - 12, outerRx * 0.88, outerRy * 0.85, 16, -2, 0.03), "#f7c992", 95, 0.22, 0.3, 0.12);
  drawWatercolorPoly(makeEllipsePts(ringCx, ringCy + 6, innerRx * 0.72, innerRy * 0.7, 15, -2, 0.03), "#ffebd0", 110, 0.2, 0.25, 0.1);

  // Build the razor-sharp luminous ring band thrown onto the wall above and around the shade
  // Using precise angular segments for the upper arc (-198 deg to +18 deg)
  let ringBandPts = [];
  let nArc = 44;
  for (let i = 0; i <= nArc; i++) {
    let a = map(i, 0, nArc, -196, 16);
    let x = ringCx + cos(a) * outerRx;
    let y = ringCy + sin(a) * outerRy;
    ringBandPts.push([x, y]);
  }
  for (let i = nArc; i >= 0; i--) {
    let a = map(i, 0, nArc, -196, 16);
    let x = ringCx + cos(a) * innerRx;
    let y = ringCy + sin(a) * innerRy + 4;
    ringBandPts.push([x, y]);
  }
  // Sharp opaque pastel cream-amber wash for the ring itself
  drawSharpPoly(ringBandPts, "#ffeed2", 185, 0.02);

  // Inner bright core of the sharp ring
  let ringCorePts = [];
  for (let i = 0; i <= nArc; i++) {
    let a = map(i, 0, nArc, -192, 12);
    ringCorePts.push([ringCx + cos(a) * (outerRx - 4), ringCy + sin(a) * (outerRy - 3)]);
  }
  for (let i = nArc; i >= 0; i--) {
    let a = map(i, 0, nArc, -192, 12);
    ringCorePts.push([ringCx + cos(a) * (innerRx + 7), ringCy + sin(a) * (innerRy + 5)]);
  }
  drawSharpPoly(ringCorePts, "#fff9ec", 170, 0.02);

  // Crisp optical cut-off shadow edge just outside the ring (where the metal rim blocks the bulb)
  let shadowBandPts = [];
  for (let i = 0; i <= nArc; i++) {
    let a = map(i, 0, nArc, -198, 18);
    shadowBandPts.push([ringCx + cos(a) * (outerRx + 18), ringCy + sin(a) * (outerRy + 14)]);
  }
  for (let i = nArc; i >= 0; i--) {
    let a = map(i, 0, nArc, -198, 18);
    shadowBandPts.push([ringCx + cos(a) * outerRx, ringCy + sin(a) * outerRy]);
  }
  drawSharpPoly(shadowBandPts, "#8a461e", 110, 0.02);

  // Razor-sharp optical edge lines along the ring boundary
  let outerEdgeSpline = [];
  let innerEdgeSpline = [];
  for (let i = 0; i <= 36; i++) {
    let a = map(i, 0, 36, -195, 15);
    let fade = sin(map(i, 0, 36, 12, 168));
    outerEdgeSpline.push([ringCx + cos(a) * outerRx, ringCy + sin(a) * outerRy, 0.5 + fade * 0.7]);
    innerEdgeSpline.push([ringCx + cos(a) * innerRx, ringCy + sin(a) * innerRy + 4, 0.4 + fade * 0.5]);
  }
  brush.set("rotring", "#fffaf0", 0.55);
  brush.spline(outerEdgeSpline, 0.3);
  brush.set("fine_graphite", "#6e3416", 0.42);
  brush.spline(outerEdgeSpline.map(p => [p[0], p[1] - 1.5, p[2]]), 0.3);
  brush.set("rotring", "#f5be7d", 0.4);
  brush.spline(innerEdgeSpline, 0.3);

  // Lower lampshade cut-off arc thrown onto the wall below the shade (y ~ 485..590)
  let lowerCutPts = [];
  for (let i = 0; i <= 30; i++) {
    let t = i / 30;
    let x = lerp(430, 935, t);
    let arch = Math.pow((t - 0.5) * 2, 2);
    let y = 492 + arch * 82;
    lowerCutPts.push([x, y]);
  }
  let lowerGlowPoly = [...lowerCutPts, [950, 665], [415, 650]];
  drawSharpPoly(lowerGlowPoly, "#fad4a2", 95, 0.04);

  brush.set("fine_graphite", "#ffefd4", 0.45);
  brush.spline(lowerCutPts.map(p => [p[0], p[1], 0.7]), 0.25);
  brush.set("fine_graphite", "#7d3d18", 0.35);
  brush.spline(lowerCutPts.map(p => [p[0], p[1] - 2.2, 0.6]), 0.25);

  // Subtle pleated scalloped rays inside the sharp ring (from the 24 shade pleats)
  for (let i = 0; i < 28; i++) {
    let a = map(i, 0, 27, -182, 2);
    let x1 = ringCx + cos(a) * (innerRx - 10);
    let y1 = ringCy + sin(a) * (innerRy - 6);
    let x2 = ringCx + cos(a) * outerRx;
    let y2 = ringCy + sin(a) * outerRy;
    brush.set("fine_graphite", i % 2 === 0 ? "#fffbf2" : "#e39f56", 0.25);
    brush.line(x1, y1, x2, y2);
  }

  // Room corner vertical crease & wainscot chair rail
  brush.set("fine_graphite", "#361e26", 0.42);
  brush.line(roomX(248, 165), 165, 248, 800);
  // Chair rail / paneling molding across back wall
  brush.set("fine_graphite", "#4f2918", 0.45);
  brush.line(roomX(248, 608), 608, 1200, 646);
  brush.set("fine_graphite", "#d49255", 0.28);
  brush.line(roomX(520, 620), 622, 850, 634);
}

