// ============================================================================
// 6. BACKGROUND GRAPHITE GRAIN & CARPET TEXTURE
// ============================================================================
function renderBackgroundGraphiteAndCarpet() {
  // Baseboards along left wall and back wall
  drawSharpPoly([
    [0, 895], [58, 872], [58, 886], [0, 912]
  ], "#29151d", 230, 0.01);
  drawSharpPoly([
    [206, 808], [248, 790], [248, 804], [206, 826]
  ], "#381c1a", 230, 0.01);

  // Carpet pile texture in the orange floor spill and shadowy foreground left
  for (let i = 0; i < 380; i++) {
    let x = random(0, 620);
    let y = random(815, 1195);
    // Keep inside floor region below baseboard
    let minFloorY = x < 248 ? map(x, 0, 248, 912, 800) : map(x, 248, 620, 800, 822);
    if (y < minFloorY) continue;

    // Distance to the diagonal orange doorway beam
    let beamCenter = map(y, 830, 1180, 145, 210);
    let beamWidth = map(y, 830, 1180, 65, 260);
    let inBeam = Math.exp(-Math.pow((x - beamCenter) / beamWidth, 2) * 1.4) * map(y, 825, 1190, 1.0, 0.35);

    let col = lerpHex("#261621", "#f29d5c", clamp01(inBeam));
    if (inBeam > 0.55) col = lerpHex("#f29d5c", "#ffd8b0", (inBeam - 0.55) * 2);
    brush.set("fine_graphite", col, 0.24 + inBeam * 0.18);
    let len = random(8, 22);
    brush.line(x, y, x + len, y + random(-2, 2));
  }

  // Soft graphite shadow grain across upper ceiling and wall murk
  for (let i = 0; i < 240; i++) {
    let x = random(0, 1200);
    let y = random(0, 520);
    let L = getRoomLight(x, y);
    if (L < 0.48) {
      let col = lerpHex("#190f19", "#4f2c24", L * 2);
      brush.set("soft_graphite", col, random(0.45, 0.95));
      let ang = random(-12, 12) + (x < 250 ? 22 : -4);
      let len = random(35, 95);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }
}

