// Surface mapping for the 3D bedspread:
// u in [0, 1]: from headboard (0) toward front-left foot of bed (1)
// v in [0, 1.38]:
//   v in [0, 0.26]: overhanging left quilted skirt (falling toward floor near nightstand/viewer)
//   v in [0.26, 1.0]: top mattress plane stretching to right edge of canvas
//   u > 0.82: front drop curving down toward bottom of canvas
function bedPoint(u, v) {
  let edgeV = 0.26;

  // Left mattress ridge line from headboard (778, 650) to front corner (418, 898)
  let leftX = lerp(778, 418, u);
  let leftY = lerp(650, 898, u) + Math.sin(u * Math.PI) * 8;

  // Right mattress boundary (off right edge of canvas)
  let rightX = lerp(1235, 1245, u);
  let rightY = lerp(698, 1045, u);

  let x, y;
  if (v >= edgeV) {
    // Top plane of the mattress
    let tv = (v - edgeV) / (1.0 - edgeV);
    x = lerp(leftX, rightX, tv);
    y = lerp(leftY, rightY, tv);

    // 3D mattress crown + depression under the duffel bag around (u=0.28, v=0.52)
    let crown = Math.sin(tv * Math.PI) * -14;
    let duffDist2 = Math.pow((u - 0.26) / 0.22, 2) + Math.pow((v - 0.50) / 0.24, 2);
    let depression = Math.exp(-duffDist2) * 18;
    // Radiating fabric fold ripples
    let ripple = Math.sin(u * 19 + v * 14) * 3.5 + Math.cos(u * 9 - v * 22) * 3.0;
    y += crown + depression + ripple;

    // Front mattress overhang curve when u > 0.84
    if (u > 0.84) {
      let dropT = (u - 0.84) / 0.16;
      y += dropT * dropT * 95;
      x -= dropT * 12;
    }
  } else {
    // Left overhanging skirt falling from the mattress ridge (leftX, leftY) to the floor
    let sv = (edgeV - v) / edgeV; // 0 at mattress ridge, 1 at bottom hem
    let dropHeight = lerp(165, 255, u);
    // Heavy vertical pleated folds in the hanging polyester skirt
    let foldWave = Math.sin(u * 26) * 11 * sv + Math.cos(u * 13 + 1.2) * 7 * sv;
    x = leftX - sv * lerp(18, 38, u) + foldWave;
    y = leftY + Math.pow(sv, 0.88) * dropHeight + Math.sin(u * 26) * 6 * sv;
  }
  return [x, y];
}

function renderBedAndFloralBedspread() {
