  // HEADBOARD & PILLOWS (x: 780..1200, y: 535..705)
  // --------------------------------------------------------------------------
  let hbPts = [
    [788, 538], [1215, 578], [1215, 695], [782, 655]
  ];
  drawSharpPoly(hbPts, "#3b1e16", 245, 0.01);
  // Warm lamp glow on left side of headboard
  drawWatercolorPoly([
    [785, 538], [985, 558], [975, 672], [782, 655]
  ], "#8c4a22", 120, 0.28, 0.45, 0.2);

  // Top wood molding on headboard
  brush.set("rotring", "#c98243", 0.45);
  brush.line(788, 538, 1020, 560);
  brush.set("fine_graphite", "#21100e", 0.5);
  brush.line(788, 545, 1210, 585);

