    [792, 618], [905, 615], [965, 636], [925, 668], [786, 652]
  ], "#ffebd2", 175, 0.25, 0.3, 0.1);
  // Pillow creases
  brush.set("fine_graphite", "#8c5432", 0.32);
  brush.spline([[805, 642, 0.5], [875, 648, 0.8], [945, 662, 0.4]], 0.35);
  brush.spline([[835, 626, 0.4], [910, 638, 0.7], [985, 645, 0.4]], 0.35);

  // Pillow 2 (Right pillow, receding into raw sienna and burnt umber shadow)
  let pillow2 = [
    [1025, 634], [1140, 636], [1215, 658], [1215, 708], [1120, 706], [1016, 682]
  ];
  drawSharpPoly(pillow2, "#7d4930", 235, 0.25);
  drawWatercolorPoly(pillow2, "#4f2a1d", 130, 0.3, 0.45, 0.2);

  // --------------------------------------------------------------------------
  // BEDSPREAD BASE TOPOGRAPHY & WATERCOLOR GLAZE FALLOFF
  // --------------------------------------------------------------------------
  // Cast shadow beneath the hanging left skirt onto the motel floor
  let skirtShadow = [];
  for (let i = 0; i <= 14; i++) skirtShadow.push(bedPoint(i / 14, 0.0));
  skirtShadow.push([360, 1185], [735, 860]);
  drawWatercolorPoly(skirtShadow, "#1c0f1b", 195, 0.28, 0.5, 0.25);

  // Full bedspread silhouette polygon
  let spreadOutline = [];
  for (let i = 0; i <= 16; i++) spreadOutline.push(bedPoint(i / 16, 0.0));
  for (let j = 1; j <= 12; j++) spreadOutline.push(bedPoint(1.0, j / 12));
  for (let i = 15; i >= 0; i--) spreadOutline.push(bedPoint(i / 16, 1.0));
  for (let j = 11; j >= 1; j--) spreadOutline.push(bedPoint(0.0, j / 12));

  // Warm midtone base wash for the polyester bedspread
  drawSharpPoly(spreadOutline, "#80523b", 242, 0.05);

  // Layered watercolor lighting zones across the bedspread:
  // 1. Bright pastel peach-cream & dusty rose highlight near the lamp (u: 0..0.52, v: 0.15..0.72)
  let litZone1 = [
    bedPoint(0.0, 0.16), bedPoint(0.0, 0.68), bedPoint(0.28, 0.72),
    bedPoint(0.52, 0.58), bedPoint(0.48, 0.18), bedPoint(0.22, 0.12)
  ];
  drawWatercolorPoly(litZone1, "#f2c6a2", 185, 0.35, 0.35, 0.15);

  let litZoneCore = [
    bedPoint(0.02, 0.22), bedPoint(0.02, 0.52), bedPoint(0.24, 0.56),
    bedPoint(0.36, 0.42), bedPoint(0.28, 0.20)
  ];
  drawWatercolorPoly(litZoneCore, "#ffebd4", 170, 0.32, 0.28, 0.1);

  // 2. Warm raw sienna & golden amber transition across mid-bed
  let midBedZone = [
    bedPoint(0.30, 0.15), bedPoint(0.25, 0.85), bedPoint(0.68, 0.92),
    bedPoint(0.78, 0.45), bedPoint(0.65, 0.08)
  ];
  drawWatercolorPoly(midBedZone, "#b86b35", 110, 0.4, 0.48, 0.2);

  // 3. Burnt umber & brownish-violet murk across the lower-right and lower-left bed corners
  let darkBedRight = [
    bedPoint(0.35, 0.75), bedPoint(0.05, 1.0), bedPoint(1.0, 1.0),
    bedPoint(1.0, 0.52), bedPoint(0.68, 0.62)
  ];
  drawWatercolorPoly(darkBedRight, "#4a2724", 150, 0.42, 0.58, 0.28);

  let violetBedCorner = [
    bedPoint(0.58, 0.72), bedPoint(0.45, 1.0), bedPoint(1.0, 1.0), bedPoint(1.0, 0.62)
  ];
  drawWatercolorPoly(violetBedCorner, "#281625", 165, 0.45, 0.62, 0.32);

  let darkSkirtFoot = [
    bedPoint(0.58, 0.0), bedPoint(0.58, 0.34), bedPoint(1.0, 0.55),
    bedPoint(1.0, 0.0)
  ];
  drawWatercolorPoly(darkSkirtFoot, "#361d24", 150, 0.42, 0.58, 0.28);

  // --------------------------------------------------------------------------
  // 3D DRAPERY FOLDS ON THE HANGING SKIRT & MATTRESS CREASES
  // --------------------------------------------------------------------------
  for (let k = 0; k < 14; k++) {
    let u0 = 0.04 + (k / 14) * 0.9;
    let pTop = bedPoint(u0, 0.25);
    let pMid = bedPoint(u0 + 0.015, 0.12);
    let pBot = bedPoint(u0 + 0.02, 0.01);
    let L = getRoomLight(pMid[0], pMid[1]);

    if (k % 2 === 0) {
      // Shadow trough in the hanging fold
      let troughCol = lerpHex("#21121d", "#7a3e20", L);
      brush.set("soft_graphite", troughCol, 0.75);
      brush.spline([
        [pTop[0], pTop[1], 0.4], [pMid[0], pMid[1], 0.9], [pBot[0], pBot[1], 0.5]
      ], 0.35);
    } else if (L > 0.25) {
      // Synthetic polyester sheen on the fold crest
      let crestCol = lerpHex("#8c5230", "#ffe8cc", clamp01((L - 0.2) * 1.4));
      brush.set("fine_graphite", crestCol, 0.45);
      brush.spline([
        [pTop[0], pTop[1], 0.5], [pMid[0] - 3, pMid[1], 0.85], [pBot[0] - 2, pBot[1], 0.4]
      ], 0.35);
    }
  }

  // Ridge highlight along the mattress edge (v = 0.26) where light rakes across the bend
  let ridgePts = [];
  for (let i = 0; i <= 24; i++) {
    let u = i / 24;
    let p = bedPoint(u, 0.26);
    let L = getRoomLight(p[0], p[1]);
    if (L > 0.28) ridgePts.push([p[0], p[1], L * 0.85]);
  }
  if (ridgePts.length > 2) {
    brush.set("soft_graphite", "#ffebd2", 0.55);
    brush.spline(ridgePts, 0.3);
  }

  // --------------------------------------------------------------------------
  // FORENSIC QUILTED POLYESTER DIAMOND STITCHING
  // --------------------------------------------------------------------------
  let uSteps = 22;
  let vSteps = 18;
  // Diagonal quilting families (u + v = const and u - v = const)
  for (let d = -vSteps; d <= uSteps + vSteps; d += 2) {
    let ptsA = [];
    for (let uIdx = 0; uIdx <= uSteps; uIdx++) {
      let vIdx = d - uIdx;
      if (vIdx >= 0 && vIdx <= vSteps) {
        let u = uIdx / uSteps;
        let v = vIdx / vSteps;
        ptsA.push({ u, v, p: bedPoint(u, v) });
      }
    }
    drawQuiltSeam(ptsA);

    let ptsB = [];
    for (let uIdx = 0; uIdx <= uSteps; uIdx++) {
      let vIdx = uIdx - d + vSteps / 2;
      if (vIdx >= 0 && vIdx <= vSteps) {
        let u = uIdx / uSteps;
        let v = vIdx / vSteps;
        ptsB.push({ u, v, p: bedPoint(u, v) });
      }
    }
    drawQuiltSeam(ptsB);
  }

  // --------------------------------------------------------------------------
  // FORENSIC BOTANICAL FLORAL PATTERN ON THE BEDSPREAD
  // --------------------------------------------------------------------------
  for (let gu = 0; gu < 11; gu++) {
    for (let gv = 0; gv < 10; gv++) {
      let u = (gu + 0.5 + (gv % 2) * 0.25) / 11.2;
      let v = (gv + 0.45) / 10.2;
      if (u > 0.96 || v > 0.96) continue;

      // Skip area directly hidden under the duffel bag body to save budget & keep clean
      if (u > 0.11 && u < 0.39 && v > 0.34 && v < 0.68) continue;

      let center = bedPoint(u, v);
      let pU = bedPoint(u + 0.025, v);
      let pV = bedPoint(u, v + 0.025);

      // Local 3D surface tangent basis vectors (warps flowers accurately over folds!)
      let txU = (pU[0] - center[0]) * 0.72;
      let tyU = (pU[1] - center[1]) * 0.72;
      let txV = (pV[0] - center[0]) * 0.72;
      let tyV = (pV[1] - center[1]) * 0.72;

      let L = getRoomLight(center[0], center[1]);
      renderForensicFloralCluster(center[0], center[1], txU, tyU, txV, tyV, L, gu * 13 + gv * 7);
    }
  }
}

function drawQuiltSeam(seamNodes) {
  if (seamNodes.length < 2) return;
  for (let i = 0; i < seamNodes.length - 1; i++) {
    let n1 = seamNodes[i], n2 = seamNodes[i + 1];
    // Skip under duffel bag core
    if (n1.u > 0.12 && n1.u < 0.38 && n1.v > 0.35 && n1.v < 0.66) continue;

    let xm = (n1.p[0] + n2.p[0]) * 0.5;
    let ym = (n1.p[1] + n2.p[1]) * 0.5;
    let L = getRoomLight(xm, ym);

    let seamCol = lerpHex("#21111c", "#8f4e27", clamp01(L * 1.25));
    brush.set("micro_needle", seamCol, 0.16 + L * 0.12);
    brush.line(n1.p[0], n1.p[1], n2.p[0], n2.p[1]);

    // Synthetic polyester puffed highlight parallel to seam in strong light
    if (L > 0.46) {
      let sheenCol = lerpHex("#d99b66", "#fff2de", clamp01((L - 0.46) * 2.0));
      brush.set("micro_needle", sheenCol, 0.18);
      brush.line(n1.p[0] - 1.4, n1.p[1] - 1.2, n2.p[0] - 1.4, n2.p[1] - 1.2);
    }
  }
}

function renderForensicFloralCluster(cx, cy, ux, uy, vx, vy, L, seed) {
  // Helper to project local (du, dv) in pattern space onto the 3D warped cloth tangent plane
  const proj = (du, dv) => [
    cx + du * ux + dv * vx,
    cy + du * uy + dv * vy
  ];

  // Palette shifts from luminous pastel rose / sage / cream in the light pool
  // to raw sienna, burnt umber, and brownish-violet in the shadow falloff
  let petalBase = lerpHex("#2c1826", "#e38c88", clamp01(L * 1.35));
  if (L > 0.62) petalBase = lerpHex("#e38c88", "#f7beb8", (L - 0.62) * 2.2);

  let petalHi = lerpHex("#3d222f", "#ffe9e2", clamp01(L * 1.4));
  let centerCol = lerpHex("#1f111a", "#e8a848", clamp01(L * 1.35));
  let leafCol = lerpHex("#211521", "#788f7e", clamp01(L * 1.35));
  if (L > 0.65) leafCol = lerpHex("#788f7e", "#9eb5a2", (L - 0.65) * 2.0);
  let stemCol = lerpHex("#190e18", "#5e4636", clamp01(L * 1.3));
  let budCol = lerpHex("#331b26", "#f5cfa0", clamp01(L * 1.35));

  // 1. Meandering botanical stems & leaves
  if (L > 0.14) {
    brush.set("micro_needle", stemCol, 0.18 + L * 0.12);
    let s0 = proj(-0.65, -0.45);
    let s1 = proj(0.0, 0.0);
    let s2 = proj(0.62, 0.42);
    let s3 = proj(-0.35, 0.58);
    brush.spline([[s0[0], s0[1], 0.5], [s1[0], s1[1], 0.8], [s2[0], s2[1], 0.5]], 0.35);
    brush.line(s1[0], s1[1], s3[0], s3[1]);

    // 3 serrated sage leaves per cluster
    let leafDirs = [[-0.55, 0.32], [0.52, -0.38], [0.35, 0.55]];
    for (let ld of leafDirs) {
      let lBase = proj(ld[0] * 0.35, ld[1] * 0.35);
      let lTip = proj(ld[0] * 0.95, ld[1] * 0.95);
      let lLeft = proj(ld[0] * 0.62 - ld[1] * 0.25, ld[1] * 0.62 + ld[0] * 0.25);
      let lRight = proj(ld[0] * 0.62 + ld[1] * 0.25, ld[1] * 0.62 - ld[0] * 0.25);
      drawSharpPoly([lBase, lLeft, lTip, lRight], leafCol, Math.round(135 + L * 85), 0.15);
      if (L > 0.38) {
        brush.set("micro_needle", stemCol, 0.16);
        brush.line(lBase[0], lBase[1], lTip[0], lTip[1]);
      }
    }
  }

  // 2. Primary 5-petal motel rose blossom at (0, 0)
  let nPetals = 5;
  let rot0 = (seed * 37) % 360;
  for (let p = 0; p < nPetals; p++) {
    let a = rot0 + p * (360 / nPetals);
    let a1 = a - 28, a2 = a + 28;
    let p0 = proj(cos(a) * 0.08, sin(a) * 0.08);
    let p1 = proj(cos(a1) * 0.38, sin(a1) * 0.38);
    let p2 = proj(cos(a) * 0.48, sin(a) * 0.48);
    let p3 = proj(cos(a2) * 0.38, sin(a2) * 0.38);
    drawSharpPoly([p0, p1, p2, p3], petalBase, Math.round(150 + L * 85), 0.2);

    // Forensic petal veining and pastel blush edge in the pools of light
    if (L > 0.35) {
      brush.set("micro_needle", petalHi, 0.18 + L * 0.1);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.line(p2[0], p2[1], p3[0], p3[1]);
    }
  }

  // Blossom center & tiny stamen dots
  let cPoly = [];
  for (let k = 0; k < 6; k++) {
    let a = k * 60;
    cPoly.push(proj(cos(a) * 0.13, sin(a) * 0.13));
  }
  drawSharpPoly(cPoly, centerCol, 210, 0.1);
  if (L > 0.42) {
    brush.set("micro_needle", "#3d1d14", 0.22);
    for (let k = 0; k < 5; k++) {
      let a = k * 72 + 15;
      let sp = proj(cos(a) * 0.16, sin(a) * 0.16);
      brush.line(sp[0], sp[1], sp[0] + 1.2, sp[1] + 0.8);
    }
  }

  // 3. Secondary small pastel apricot/cream buds
  if (L > 0.22) {
    let buds = [[-0.58, -0.38], [0.55, 0.36]];
    for (let b of buds) {
      let b0 = proj(b[0] - 0.12, b[1]);
      let b1 = proj(b[0], b[1] - 0.12);
      let b2 = proj(b[0] + 0.12, b[1]);
      let b3 = proj(b[0], b[1] + 0.12);
      drawSharpPoly([b0, b1, b2, b3], budCol, Math.round(145 + L * 85), 0.15);
    }
  }
}

