    [lampCx - 16, 540, 0.6], [lampCx - 22, 568, 1.0], [lampCx - 18, 602, 0.5]
  ], 0.35);

  // 4. Brass lamp neck, socket & harp visible inside the lower opening of the shade (y: 482..516)
  drawSharpPoly([
    [lampCx - 7, 482], [lampCx + 7, 482], [lampCx + 9, 515], [lampCx - 9, 515]
  ], "#e6a856", 245, 0.02);
  // Rotary turn-switch key on the socket
  brush.set("rotring", "#fff3d6", 0.55);
  brush.line(lampCx - 7, 502, lampCx - 19, 504);
  drawSharpPoly(makeEllipsePts(lampCx - 20, 504, 3.8, 2.2, 8), "#ffd896", 245);

  // --------------------------------------------------------------------------
  // FORENSIC PLEATED LAMPSHADE (SEEN FROM LOW ANGLE: y = 374..502)
  // --------------------------------------------------------------------------
  // Because our camera is low (horizon y = 810), we look slightly UP into the bottom
  // opening of the shade (cy = 494, rx = 88, ry = 19)!
  let botCy = 494, botRx = 88, botRy = 19;
  let topCy = 376, topRx = 53, topRy = 9.5;

  // 1. Glowing underside interior of the shade (visible elliptical mouth at y = 494)
  drawSharpPoly(makeEllipsePts(lampCx, botCy, botRx, botRy, 24), "#f5aa56", 248, 0.05);
  drawWatercolorPoly(makeEllipsePts(lampCx, botCy - 2, botRx * 0.78, botRy * 0.75, 18), "#ffe0a8", 210, 0.2, 0.2, 0.05);
  // Blazing tungsten bulb glow at the top center of the underside opening
  drawWatercolorPoly(makeEllipsePts(lampCx, botCy - 5, 34, 10, 14), "#fffdf6", 235, 0.18, 0.15, 0.05);

  // Re-draw top of brass neck overlapping the back half of the shade opening
  drawSharpPoly([
    [lampCx - 6, 485], [lampCx + 6, 485], [lampCx + 8, 512], [lampCx - 8, 512]
  ], "#c97d32", 245, 0.02);
  brush.set("rotring", "#fff5de", 0.45);
  brush.line(lampCx - 5, 486, lampCx - 6, 512);

  // 2. Outer pleated frustum of the shade: 24 radial zig-zag pleats across the front arc
  //    Front half of the shade spans angle a from 0 deg (right) through 90 deg (front) to 180 deg (left)
  //    Wait: since we look UP at the shade, the front lip of the bottom ellipse is the UPPER arc
  //    (sin(a) < 0, i.e., a from -180 to 0) OR the lower arc?
  //    In low-angle perspective (eye at y = 810, shade at y = 494):
  //    The shade is ABOVE eye level! When a horizontal circle is ABOVE eye level,
  //    its NEAR edge (closest to viewer) is the LOWER arc (y = cy + ry, sin(a) > 0, a in [0, 180])?
  //    Wait: think carefully! If you look UP at a ceiling ring or lampshade above your head:
  //    The back rim of the bottom opening is lower in screen Y (closer to horizon y = 810),
  //    and the FRONT lip of the bottom opening arches HIGHER (y = cy - ry, sin(a) < 0)!
  //    YES! Because in perspective, points further away are closer to the horizon (y = 810),
  //    so for an object at y = 494 (above horizon 810), the far edge has LARGER y (closer to 810)
  //    and the near edge has SMALLER y (further above 810)!
  //    Let's verify: the front wall of the shade covers the upper arc of the bottom ellipse
  //    (from a = -185 deg through -90 deg to +5 deg) and rises to the upper arc of the top ellipse!

  let nPleats = 24; // 48 zig-zag vertices (ridge / valley alternation)
  let totalVerts = nPleats * 2;
  let botVerts = [];
  let topVerts = [];

  for (let i = 0; i <= totalVerts; i++) {
    let t = i / totalVerts;
    let a = map(t, 0, 1, -186, 6); // Front-facing half of the shade (near arc is sin(a) <= 0)
    let isOuterRidge = (i % 2 === 0);
    let rModBot = isOuterRidge ? 1.04 : 0.95;
    let rModTop = isOuterRidge ? 1.05 : 0.94;

    let bx = lampCx + cos(a) * botRx * rModBot;
    let by = botCy + sin(a) * botRy * 0.72 * rModBot;

    let tx = lampCx + cos(a) * topRx * rModTop;
    let ty = topCy + sin(a) * topRy * 0.65 * rModTop;

    botVerts.push([bx, by]);
    topVerts.push([tx, ty]);
  }

  // Draw each of the 48 individual pleat facets across the front of the shade
  for (let i = 0; i < totalVerts; i++) {
    let b1 = botVerts[i], b2 = botVerts[i + 1];
    let t1 = topVerts[i], t2 = topVerts[i + 1];

    // Normalized position across the shade from left (-1) to center (0) to right (+1)
    let uCenter = (i / totalVerts) * 2 - 1;
    let centerGlow = Math.exp(-uCenter * uCenter * 1.6);

    // Alternating left-facing and right-facing pleat faces catch different internal translucency
    let isLeftFacet = (i % 2 === 0);
    let col;
    if (isLeftFacet) {
      col = lerpHex("#d4823b", "#ffebd0", clamp01(centerGlow * 0.92 + 0.12));
    } else {
      col = lerpHex("#9e5220", "#f5be7d", clamp01(centerGlow * 0.85));
    }

    drawSharpPoly([t1, t2, b2, b1], col, 248, 0.01);
  }

  // Soft warm translucent bloom over the center of the pleated shade (bulb core glowing through fabric)
  drawWatercolorPoly(makeEllipsePts(lampCx, 438, 48, 36, 14), "#fff3db", 120, 0.28, 0.2, 0.05);

  // Forensic graphite & sienna crease lines along every ridge and valley of the pleats
  for (let i = 0; i <= totalVerts; i++) {
    let b = botVerts[i], t = topVerts[i];
    let isRidge = (i % 2 === 0);
    if (isRidge) {
      brush.set("micro_needle", "#fffaf0", 0.28);
      brush.line(t[0], t[1], b[0], b[1]);
    } else {
      brush.set("micro_needle", "#783b16", 0.25);
      brush.line(t[0], t[1], b[0], b[1]);
    }
  }

  // Corrugated zig-zag bottom and top rims of the pleated shade
  for (let i = 0; i < totalVerts; i++) {
    brush.set("fine_graphite", "#733714", 0.35);
    brush.line(botVerts[i][0], botVerts[i][1], botVerts[i + 1][0], botVerts[i + 1][1]);
    brush.set("rotring", "#fff6e5", 0.38);
    brush.line(topVerts[i][0], topVerts[i][1], topVerts[i + 1][0], topVerts[i + 1][1]);
  }

  // Back lower lip of the shade opening (visible behind the bulb/neck)
  brush.set("fine_graphite", "#8c4619", 0.38);
  brush.arc(lampCx, botCy, botRx, 8, 172);
}

