function renderFinalShadowGrainAndMurk() {
  // Deep peripheral brownish-violet watercolor glazes sinking the four corners into murk
  let cornerGlazes = [
    [[-30, -30], [390, -30], [180, 145], [-30, 390]],
    [[830, -30], [1230, -30], [1230, 370], [1020, 175]],
    [[-30, 1040], [280, 1110], [390, 1230], [-30, 1230]],
    [[910, 1020], [1230, 910], [1230, 1230], [720, 1230]]
  ];
  for (let pts of cornerGlazes) {
    drawWatercolorPoly(pts, "#1a0e1a", 125, 0.45, 0.65, 0.35);
  }

  // Soft graphite hatching carrying the grain through the shadows and mid-falloff zones
  for (let i = 0; i < 420; i++) {
    let x = random(0, 1200);
    let y = random(0, 1200);
    let L = getRoomLight(x, y);

    // Keep out of the brightest pools of light so forensic details stay crystal clear
    if (L > 0.52) continue;

    // Also skip the sharp ring on the wall so its optical edge stays pristine
    let dRing = Math.hypot((x - 682) / 245, (y - 352) / 155);
    if (dRing > 0.82 && dRing < 1.15 && y < 420) continue;

    let shadowDepth = 1.0 - L / 0.52;
    let col = lerpHex("#4f2c24", "#170c17", clamp01(shadowDepth * 1.15));

    if (i % 3 === 0) {
      brush.set("soft_graphite", col, (0.38 + shadowDepth * 0.55));
      let ang = -18 + (noise(x * 0.004, y * 0.004) - 0.5) * 45;
      let len = random(28, 78);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    } else {
      brush.set("2B", col, (0.22 + shadowDepth * 0.28));
      let ang = 25 + (noise(x * 0.006, y * 0.006) - 0.5) * 35;
      let len = random(18, 48);
      brush.line(x, y, x + cos(ang) * len, y + sin(ang) * len);
    }
  }

  // Subtle pigment granulation mist in the heavy shadow transitions
  for (let i = 0; i < 65; i++) {
    let angle = random(0, 360);
    let rad = random(430, 760);
    let x = 600 + cos(angle) * rad;
    let y = 600 + sin(angle) * rad;
    if (x < -20 || x > 1220 || y < -20 || y > 1220) continue;
    let col = rad > 580 ? "#1c0f1c" : "#4a251c";
    brush.set("glaze_mist", col, random(0.6, 1.15));
    brush.line(x, y, x + random(-35, 35), y + random(-35, 35));
  }
}

