// Spectral color control stops: [nm, [r,g,b] midtone, [r,g,b] dark shadow, [r,g,b] bright highlight]
const SPECTRAL_STOPS = [
  [380, [34, 10, 68],   [10, 5, 22],   [165, 138, 225]],
  [402, [86, 24, 158],  [18, 7, 38],   [205, 172, 250]],
  [430, [44, 42, 198],  [10, 12, 48],  [168, 182, 255]],
