  [720, [44, 5, 14],    [12, 3, 7],    [154, 82, 96]]
];

function nmToX(nm) {
  return FX1 + ((nm - NM_MIN) / (NM_MAX - NM_MIN)) * FW;
}

function xToNm(x) {
  return NM_MIN + ((x - FX1) / FW) * (NM_MAX - NM_MIN);
}

function clampVal(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function lerpRGB(c1, c2, t) {
  let k = clampVal(t, 0, 1);
  return [
    Math.round(c1[0] + (c2[0] - c1[0]) * k),
    Math.round(c1[1] + (c2[1] - c1[1]) * k),
    Math.round(c1[2] + (c2[2] - c1[2]) * k)
  ];
}

function rgbHex(rgb) {
  let r = clampVal(Math.round(rgb[0]), 0, 255).toString(16).padStart(2, "0");
  let g = clampVal(Math.round(rgb[1]), 0, 255).toString(16).padStart(2, "0");
  let b = clampVal(Math.round(rgb[2]), 0, 255).toString(16).padStart(2, "0");
  return `#${r}${g}${b}`;
}

function sampleSpectrum(nm) {
  let w = clampVal(nm, NM_MIN, NM_MAX);
  for (let i = 0; i < SPECTRAL_STOPS.length - 1; i++) {
    let s0 = SPECTRAL_STOPS[i];
    let s1 = SPECTRAL_STOPS[i + 1];
    if (w >= s0[0] && w <= s1[0]) {
      let t = (w - s0[0]) / (s1[0] - s0[0]);
      // Smoothstep interpolation for seamless spectral blending
      let st = t * t * (3 - 2 * t);
      return {
        mid: lerpRGB(s0[1], s1[1], st),
        dark: lerpRGB(s0[2], s1[2], st),
        high: lerpRGB(s0[3], s1[3], st)
      };
    }
  }
  let last = SPECTRAL_STOPS[SPECTRAL_STOPS.length - 1];
  return { mid: last[1], dark: last[2], high: last[3] };
}

// Anatomical horizontal curves of the stretched closed eye (u in [0, 1])
function upperFoldY(u) {
  return 452 - 34 * Math.sin(Math.pow(clampVal(u, 0, 1), 0.92) * Math.PI) + 3 * Math.sin(u * Math.PI * 2);
}

function creaseY(u) {
  return 468 - 36 * Math.sin(Math.pow(clampVal(u, 0, 1), 0.92) * Math.PI) + 4 * Math.sin(u * Math.PI * 2);
}

function domeY(u) {
  return 544 - 11 * Math.sin(clampVal(u, 0, 1) * Math.PI);
}

function lashLineY(u) {
  return 618 + 20 * Math.sin(Math.pow(clampVal(u, 0, 1), 0.95) * Math.PI) - 3 * Math.sin(u * Math.PI * 2);
}

function waterlineY(u) {
  let env = Math.sin(clampVal((u - 0.03) / 0.94, 0, 1) * Math.PI);
  return lashLineY(u) + 3.5 + 5.0 * env;
}

function lowerCreaseY(u) {
  return 718 + 18 * Math.sin(clampVal(u, 0, 1) * Math.PI);
}

