function drawString(str, x, y, charW, charH, gap) {
  let cx = x;
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    let paths = GLYPHS[ch];
    if (paths) {
      for (let p = 0; p < paths.length; p++) {
        let pts = paths[p];
        for (let k = 0; k < pts.length - 1; k++) {
          let x1 = cx + pts[k][0] * charW;
          let y1 = y + pts[k][1] * charH;
          let x2 = cx + pts[k + 1][0] * charW;
          let y2 = y + pts[k + 1][1] * charH;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
    cx += charW + gap;
  }
}

