  translate(-width / 2, -height / 2);

  // =========================================================================
  // 1. ARCHIVAL PAPER GROUND & SUBTLE SPECTROMETER PLATE TONE
  // =========================================================================
  brush.noStroke();
  brush.wash("#eef0f4", 120);
  brush.rect(35, 220, 1130, 760, "corner");

  // Dark inner ground behind the spectrometer aperture for high-contrast value depth
  brush.wash("#14131c", 220);
  brush.rect(FX1 + 2, FY1 + 2, FW - 4, FH - 4, "corner");

  // Base porcelain-alabaster skin wash along the upper brow transition and lower cheek zone
  brush.wash("#e3dcd8", 175);
  drawPolygon([
    [FX1 + 2, FY1 + 2],
    [FX2 - 2, FY1 + 2],
    [FX2 - 2, FY1 + 88],
    [FX1 + 2, FY1 + 84]
  ]);
  drawPolygon([
    [FX1 + 2, FY2 - 170],
    [FX2 - 2, FY2 - 170],
    [FX2 - 2, FY2 - 2],
    [FX1 + 2, FY2 - 2]
  ]);

  // =========================================================================
  // 2. CONTINUOUS SPECTRAL EYESHADOW GRADIENT (WATERCOLOR WASHES & BLEEDS)
  // =========================================================================
  const NUM_SLICES = 36;
  const sliceW = FW / NUM_SLICES;

  // Pass 2A: Broad blended spectral watercolor across upper mobile lid & lower lid reflection
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.52, 0.32);

  for (let i = 0; i < NUM_SLICES; i++) {
    let u0 = Math.max(0.002, (i - 0.38) / NUM_SLICES);
    let u1 = Math.min(0.998, (i + 1.38) / NUM_SLICES);
    let uMid = (i + 0.5) / NUM_SLICES;
    let x0 = FX1 + u0 * FW;
    let x1 = FX1 + u1 * FW;
    let xm = (x0 + x1) * 0.5;
    let nm = xToNm(xm);
    let spec = sampleSpectrum(nm);

    // Upper orbital diffusion (blending spectrum softly into cool porcelain skin above crease)
    let orbTint = lerpRGB(spec.mid, [218, 212, 216], 0.48);
    brush.fill(rgbHex(orbTint), 95);
    drawPolygon([
      [x0, FY1 + 4],
      [x1, FY1 + 4],
      [x1, creaseY(u1) + 18],
      [xm, creaseY(uMid) + 22],
      [x0, creaseY(u0) + 18]
    ]);

    // Main mobile eyelid saturated spectral wash (from supratarsal crease down to lash line)
    brush.fill(rgbHex(spec.mid), 165);
    drawPolygon([
      [x0, creaseY(u0) - 8],
      [xm, creaseY(uMid) - 10],
      [x1, creaseY(u1) - 8],
      [x1, lashLineY(u1) + 6],
      [xm, lashLineY(uMid) + 8],
      [x0, lashLineY(u0) + 6]
    ]);

    // Second high-chroma layer concentrating pigment near crease & lower mobile lid
    brush.fill(rgbHex(spec.mid), 130);
    drawPolygon([
      [x0, creaseY(u0) + 4],
      [x1, creaseY(u1) + 4],
      [x1, lashLineY(u1) + 2],
      [x0, lashLineY(u0) + 2]
    ]);

    // Lower eyelid smoked spectral reflection wash (below waterline)
    let lowerTint = lerpRGB(spec.mid, [215, 204, 202], 0.25);
    brush.fill(rgbHex(lowerTint), 125);
    drawPolygon([
      [x0, waterlineY(u0) + 2],
      [xm, waterlineY(uMid) + 2],
      [x1, waterlineY(u1) + 2],
      [x1, lowerCreaseY(u1) + 32],
      [xm, lowerCreaseY(uMid) + 38],
      [x0, lowerCreaseY(u0) + 32]
    ]);

    // Soft infraorbital transition into lower skin
    let cheekTint = lerpRGB(spec.mid, [224, 218, 218], 0.65);
    brush.fill(rgbHex(cheekTint), 85);
    drawPolygon([
      [x0, lowerCreaseY(u0) + 8],
      [x1, lowerCreaseY(u1) + 8],
      [x1, FY2 - 4],
      [x0, FY2 - 4]
    ]);
  }

  // Pass 2B: High-contrast value modeling (deep crease shadow, lash-root shadow, luminous lid dome)
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.45, 0.28);

  for (let i = 0; i < NUM_SLICES; i++) {
    let u0 = Math.max(0.003, (i - 0.25) / NUM_SLICES);
    let u1 = Math.min(0.997, (i + 1.25) / NUM_SLICES);
    let uMid = (i + 0.5) / NUM_SLICES;
    let x0 = FX1 + u0 * FW;
    let x1 = FX1 + u1 * FW;
    let xm = (x0 + x1) * 0.5;
    let spec = sampleSpectrum(xToNm(xm));

    // Luminous 3D spherical eyeball highlight across the center of the mobile lid
    let centerBoost = Math.sin(clampVal(uMid, 0.05, 0.95) * Math.PI);
    let domeCol = lerpRGB(spec.high, [255, 253, 248], 0.35 * centerBoost);
    brush.fill(rgbHex(domeCol), Math.round(95 + 65 * centerBoost));
    drawPolygon([
      [x0, domeY(u0) - 26],
      [xm, domeY(uMid) - 30],
      [x1, domeY(u1) - 26],
      [x1, domeY(u1) + 26],
      [xm, domeY(uMid) + 30],
      [x0, domeY(u0) + 26]
    ]);

    // Deep supratarsal crease trough shadow (creates high-contrast upper slit depth)
    brush.fill(rgbHex(spec.dark), 175);
    drawPolygon([
      [x0, upperFoldY(u0) - 4],
      [xm, upperFoldY(uMid) - 5],
      [x1, upperFoldY(u1) - 4],
      [x1, creaseY(u1) + 14],
      [xm, creaseY(uMid) + 16],
      [x0, creaseY(u0) + 14]
    ]);

    // Deep palpebral fissure & lash-root shadow band
    brush.fill(rgbHex(spec.dark), 205);
    drawPolygon([
      [x0, lashLineY(u0) - 14],
      [xm, lashLineY(uMid) - 16],
      [x1, lashLineY(u1) - 14],
      [x1, waterlineY(u1) - 1],
      [xm, waterlineY(uMid) - 1],
      [x0, waterlineY(u0) - 1]
    ]);
  }

  brush.noFill();

  // =========================================================================
  // 3. ANATOMICAL HIGHLIGHTS: CONVEX DOME, WATERLINE & INNER TEAR DUCT
  // =========================================================================
  // Bright central specular gleam on the mobile lid
  for (let i = 0; i < NUM_SLICES; i++) {
    let u0 = (i + 0.05) / NUM_SLICES;
    let u1 = (i + 0.95) / NUM_SLICES;
    let uMid = (i + 0.5) / NUM_SLICES;
    let x0 = FX1 + u0 * FW;
    let x1 = FX1 + u1 * FW;
    let spec = sampleSpectrum(xToNm((x0 + x1) * 0.5));
    let glintCol = lerpRGB(spec.high, [255, 255, 255], 0.55);
    let alpha = Math.round(65 + 70 * Math.pow(Math.sin(uMid * Math.PI), 1.4));
    brush.wash(rgbHex(glintCol), alpha);
    drawPolygon([
      [x0, domeY(u0) - 11],
      [x1, domeY(u1) - 11],
      [x1, domeY(u1) + 11],
      [x0, domeY(u0) + 11]
    ]);

    // Wet lower eyelid margin (waterline ridge) catching cool pale light below the dark lash line
    let wlCol = lerpRGB(spec.high, [248, 232, 236], 0.72);
    brush.wash(rgbHex(wlCol), Math.round(115 * Math.sin(uMid * Math.PI)));
    drawPolygon([
      [x0, waterlineY(u0) - 2.5],
      [x1, waterlineY(u1) - 2.5],
      [x1, waterlineY(u1) + 3.5],
      [x0, waterlineY(u0) + 3.5]
    ]);
  }

  // Inner Canthus (Medial Tear Duct & Lacrimal Caruncle at left edge, ~385-412 nm)
  brush.wash("#3c1958", 180);
  drawPolygon([
    [FX1 + 14, 604],
    [FX1 + 52, 594],
    [FX1 + 88, 610],
    [FX1 + 86, 628],
    [FX1 + 48, 632],
    [FX1 + 14, 622]
  ]);
  // Glistening violet-rose lacrimal caruncle
  brush.wash("#b97ca8", 165);
  drawPolygon([
    [FX1 + 26, 611],
    [FX1 + 56, 606],
    [FX1 + 74, 616],
    [FX1 + 54, 625],
    [FX1 + 26, 620]
  ]);
  // Plica semilunaris fold
  brush.wash("#e6c8e8", 170);
  drawPolygon([
    [FX1 + 66, 608],
    [FX1 + 80, 612],
    [FX1 + 80, 624],
    [FX1 + 66, 626]
  ]);

  // Outer Canthus (Lateral Commissure pocket at right edge, ~700-720 nm)
  brush.wash("#22040a", 210);
  drawPolygon([
    [FX2 - 96, 610],
    [FX2 - 34, 604],
    [FX2 - 8, 612],
    [FX2 - 34, 626],
    [FX2 - 96, 624]
  ]);

  brush.noWash();

  // =========================================================================
  // 4. FINE PENCIL CONTOUR MODELING OF THE CLOSED EYE
  // =========================================================================
  brush.clip([FX1 + 1, FY1 + 1, FX2 - 1, FY2 - 1]);

  // Horizontal skin micro-shading along the supratarsal fold, crease, and lash sulcus
  const STEPS = 54;
  for (let s = 0; s < STEPS; s++) {
    let u0 = s / STEPS;
    let u1 = (s + 1) / STEPS;
    let uMid = (u0 + u1) * 0.5;
    let x0 = FX1 + u0 * FW;
    let x1 = FX1 + u1 * FW;
    let spec = sampleSpectrum(xToNm((x0 + x1) * 0.5));

    // Dark supratarsal crease core
    brush.set("2B", rgbHex(spec.dark), 1.15);
    brush.line(x0, creaseY(u0), x1, creaseY(u1));
    brush.set("HB", "#0e0d16", 0.75);
    brush.line(x0, creaseY(u0) + 1.8, x1, creaseY(u1) + 1.8);

    // Secondary upper orbital fold
    brush.set("HB", rgbHex(spec.dark), 0.7);
    brush.line(x0, upperFoldY(u0), x1, upperFoldY(u1));

    // Upper fold catchlight ridge
    brush.set("cpencil", rgbHex(lerpRGB(spec.high, [255, 255, 255], 0.45)), 0.65);
    brush.line(x0, upperFoldY(u0) + 3.2, x1, upperFoldY(u1) + 3.2);

    // Closed palpebral slit (where upper & lower lids meet)
    brush.set("charcoal", "#09090f", 1.35);
    brush.line(x0, lashLineY(u0), x1, lashLineY(u1));
    brush.set("rotring", "#050509", 0.95);
    brush.line(x0, lashLineY(u0) + 1.2, x1, lashLineY(u1) + 1.2);

    // Crisp wet highlight along lower waterline margin
    if (uMid > 0.05 && uMid < 0.94) {
      brush.set("cpencil", rgbHex(lerpRGB(spec.high, [255, 252, 252], 0.75)), 0.75);
      brush.line(x0, waterlineY(u0), x1, waterlineY(u1));
    }

    // Subtle lower infraorbital crease
    brush.set("2H", rgbHex(lerpRGB(spec.dark, [90, 78, 86], 0.5)), 0.55);
    brush.line(x0, lowerCreaseY(u0), x1, lowerCreaseY(u1));
  }

  // Wet tear-film pinpoint highlights at the inner corner caruncle
  brush.set("shimmer_glint", "#ffffff", 1.15);
  brush.line(FX1 + 38, 613, FX1 + 48, 612);
  brush.line(FX1 + 69, 614, FX1 + 75, 616);
  brush.circle(FX1 + 32, 616, 1.6, 0.1);
  brush.circle(FX1 + 58, 619, 1.3, 0.1);

  // =========================================================================
  // 5. SKIN PORES & DERMAL MICRO-RELIEF (WATERCOLOUR & FINE PENCIL)
  // =========================================================================
  // Render realistic skin pores across the upper brow transition, inner/outer canthus,
  // and lower eyelid/cheek skin, with adjacent micro-catchlights.
  let porePositions = [];
  for (let i = 0; i < 460; i++) {
    let px = FX1 + 10 + random(FW - 20);
    let u = (px - FX1) / FW;
    let zone = random();
    let py;
    if (zone < 0.28) {
      // Upper orbital skin above crease
      py = FY1 + 6 + random(Math.max(12, upperFoldY(u) - FY1 - 10));
    } else if (zone < 0.82) {
      // Lower eyelid & infraorbital skin below waterline
      py = waterlineY(u) + 14 + random(FY2 - waterlineY(u) - 20);
    } else {
      // Subtle pores through translucent mobile lid near inner & outer corners
      let side = random() < 0.5 ? random(0.02, 0.22) : random(0.78, 0.98);
      px = FX1 + side * FW;
      u = side;
      py = creaseY(u) + 12 + random(lashLineY(u) - creaseY(u) - 24);
    }
    // Avoid placing noisy pores directly on the single stray lash focal area
    if (px > 742 && px < 846 && py > 716 && py < 756) continue;
    porePositions.push({ x: px, y: py, u: u, r: random(0.9, 2.1) });
  }

  // Draw pore shadow dimples in batches
  brush.set("pore_stipple", "#26202c", 0.65);
  for (let i = 0; i < porePositions.length; i++) {
    let p = porePositions[i];
    brush.line(p.x - p.r * 0.7, p.y, p.x + p.r * 0.7, p.y + 0.4);
  }

  // Fine dermal polygon hairlines (Langer's lines) connecting skin pores subtly
  brush.set("micro_pencil", "#483e4c", 0.45);
  for (let i = 0; i < porePositions.length; i += 2) {
    let p = porePositions[i];
    let ang = (p.u - 0.5) * 18;
    let dx = Math.cos((ang * Math.PI) / 180) * 4.5;
    let dy = Math.sin((ang * Math.PI) / 180) * 4.5;
    brush.line(p.x - dx, p.y - dy, p.x + dx, p.y + dy);
  }

  // Pore edge micro-highlights (gives genuine 3D skin pore texture)
  brush.set("shimmer_glint", "#faf6f5", 0.42);
  for (let i = 0; i < porePositions.length; i++) {
    let p = porePositions[i];
    brush.line(p.x - 0.6, p.y + 1.3, p.x + 0.9, p.y + 1.5);
  }

  // =========================================================================
  // 6. VERTICAL FINE CREASES & EYELASHES AS SPECTRAL ABSORPTION LINES
  // =========================================================================
  // Helper to draw a vertical eyelid crease + absorption line at a given x
  function drawAbsorptionCrease(x, weightMult, darknessHex, fullSpan) {
    let u = clampVal((x - FX1) / FW, 0.002, 0.998);
    let yTop = fullSpan ? FY1 + 2 : upperFoldY(u) - random(6, 28);
    let yFold = upperFoldY(u);
    let yCr = creaseY(u);
    let yDome = domeY(u);
    let yLash = lashLineY(u);
    let yBot = fullSpan ? FY2 - 2 : lowerCreaseY(u) + random(10, 65);

    // Subtle organic skin contour inflection (< 0.8px) so it reads as both a
    // ruler-crisp vertical spectrometer line and a real vertical eyelid crease
    let bend = (noise(x * 0.05) - 0.5) * 1.1;

    // 1. Fine skin-fold highlight edge immediately to the left of the vertical crease
    let spec = sampleSpectrum(xToNm(x));
    let edgeHighlight = rgbHex(lerpRGB(spec.high, [255, 255, 255], 0.5));
    brush.set("micro_pencil", edgeHighlight, 0.45 * weightMult);
    brush.line(x - 1.2, yCr + 4, x - 1.2 + bend * 0.4, yLash - 4);

    // 2. Crisp vertical crease line cutting across the spectral mobile lid
    brush.set("crease_etch", darknessHex, weightMult);
    brush.spline([
      [x, yTop, 0.45],
      [x + bend * 0.3, yFold, 0.95],
      [x - bend * 0.4, yCr, 1.25],
      [x + bend * 0.5, yDome, 0.90],
      [x, yLash, 1.30],
      [x + bend * 0.3, yBot, 0.40]
    ], 0.2);
  }

  // Helper to draw a vertical eyelash falling like a dark absorption line
  function drawVerticalLash(x, weightMult, yStartOff, yEnd, upwardReach) {
    let u = clampVal((x - FX1) / FW, 0.005, 0.995);
    let yRoot = lashLineY(u) + yStartOff;
    let jitter = (noise(x * 0.12, yRoot * 0.05) - 0.5) * 1.2;

    // Upward vertical extension across the mobile eyelid (pressed lash / vertical absorption line)
    if (upwardReach > 0) {
      let yUp = Math.max(FY1 + 3, yRoot - upwardReach);
      brush.set("lash_ink", "#0b0b12", weightMult * 0.72);
      brush.spline([
        [x, yRoot, 1.25],
        [x + jitter * 0.4, (yRoot + yUp) * 0.5, 0.85],
        [x + jitter * 0.2, yUp, 0.22]
      ], 0.15);
    }

    // Downward falling vertical eyelash across the lower lid spectrum
    brush.set("lash_ink", "#07070c", weightMult);
    brush.spline([
      [x, yRoot - 2, 1.35],
      [x + jitter * 0.35, yRoot + (yEnd - yRoot) * 0.38, 1.05],
      [x + jitter * 0.6, yRoot + (yEnd - yRoot) * 0.75, 0.65],
      [x + jitter * 0.4, yEnd, 0.15]
    ], 0.15);

    // Dense dark follicle root bulb at the eyelid margin
    brush.set("rotring", "#040408", weightMult * 0.95);
    brush.line(x - 0.3, yRoot - 4, x + 0.3, yRoot + 6);
  }

  // Pass 6A: ~210 fine vertical skin creases & background spectral absorption lines
  for (let i = 0; i < 215; i++) {
    let x = FX1 + 8 + (i / 215) * (FW - 16) + random(-1.6, 1.6);
    let u = (x - FX1) / FW;
    let spec = sampleSpectrum(xToNm(x));
    let darkCol = rgbHex(lerpRGB(spec.dark, [8, 8, 14], 0.65));
    let w = random(0.45, 0.95);
    let full = random() < 0.42;
    drawAbsorptionCrease(x, w, darkCol, full);

    // Extra short vertical tension pleats in the supratarsal crease & lower lid
    if (i % 2 === 0) {
      let xSub = x + random(1.4, 2.8);
      let uSub = clampVal((xSub - FX1) / FW, 0.01, 0.99);
      brush.set("micro_pencil", darkCol, random(0.4, 0.75));
      brush.line(xSub, upperFoldY(uSub) - 12, xSub, creaseY(uSub) + 28);
      brush.line(xSub, lashLineY(uSub) - 18, xSub, waterlineY(uSub) + 26);
    }
  }

  // Pass 6B: ~145 vertical eyelashes (upper + lower lashes) distributed across the eye
  for (let i = 0; i < 145; i++) {
    let u = 0.035 + (i / 145) * 0.93 + random(-0.002, 0.002);
    let x = FX1 + u * FW;
    // Anatomy envelope: lashes are shorter near inner tear duct, fullest across center/outer lid
    let env = Math.pow(Math.sin(clampVal((u - 0.02) / 0.96, 0, 1) * Math.PI), 0.55);
    let weight = (0.55 + random(0.65)) * (0.55 + 0.55 * env);
    let downLen = (55 + random(115)) * (0.45 + 0.65 * env);
    let yEnd = Math.min(FY2 - 3, lashLineY(u) + downLen);
    let upReach = (75 + random(155)) * (0.4 + 0.65 * env);

    drawVerticalLash(x, weight, random(-2, 1.5), yEnd, upReach);

    // Finer vertical lower eyelashes rooted along the lower waterline margin
    if (i % 2 === 0 && u > 0.06 && u < 0.93) {
      let xLow = x + random(1.5, 3.5);
      let uLow = (xLow - FX1) / FW;
      let yW = waterlineY(uLow) + 2;
      let yLowEnd = Math.min(FY2 - 6, yW + (28 + random(68)) * env);
      brush.set("lash_ink", "#12111a", 0.45 + random(0.35));
      brush.line(xLow, yW, xLow, yLowEnd);
    }
  }

  // Pass 6C: Prominent Fraunhofer Absorption Lines (K, H, h, G, e, d, F, c, b, E, D, a, C, B, A)
  // Rendered as bold, unmistakable vertical absorption lines formed by primary lash clusters
  // and deep continuous vertical creases slicing from top to bottom of the spectrum!
  for (let i = 0; i < FRAUNHOFER.length; i++) {
    let f = FRAUNHOFER[i];
    let x = nmToX(f.nm);
    let s = f.strength;

    // Continuous top-to-bottom Fraunhofer absorption line core
    drawAbsorptionCrease(x, 1.15 + s * 0.65, "#06060b", true);
    drawVerticalLash(x, 1.15 + s * 0.75, 0, FY2 - 2, 235);

    // Crisp rotring core for razor-sharp high-contrast absorption line edge
    brush.set("rotring", "#05050a", 0.55 + s * 0.65);
    brush.line(x, FY1 + 2, x, FY2 - 2);

    // If this Fraunhofer feature is a doublet/triplet (e.g. Sodium D1/D2, Mg b, Ca G), render its companion line
    if (f.double > 0) {
      let x2 = x + f.double;
      drawAbsorptionCrease(x2, 0.95 + s * 0.45, "#08080e", true);
      drawVerticalLash(x2, 0.95 + s * 0.55, 0, FY2 - 3, 225);
      brush.set("rotring", "#07070c", 0.45 + s * 0.45);
      brush.line(x2, FY1 + 2, x2, FY2 - 2);
    }
  }

  // =========================================================================
  // 7. TINY SHIMMER PARTICLES (COSMETIC MICA GLINTS)
  // =========================================================================
  // High-contrast pinpoint sparkles across the spectral eyeshadow dome, crease, and inner corner
  let shimmerDarkRims = [];
  let shimmerWhiteDots = [];
  let shimmerTintedDots = [];

  for (let i = 0; i < 390; i++) {
    let u = random(0.02, 0.98);
    let x = FX1 + u * FW;
    // Concentrate shimmer along the convex mobile lid highlight & inner violet/blue corner
    let ySpread = (random() + random() - 1.0) * 95;
    let y = domeY(u) + ySpread;
    if (random() < 0.22) {
      // Lower lid shimmer reflection
      y = waterlineY(u) + 8 + random(72);
    }
    if (y < FY1 + 8 || y > FY2 - 12) continue;
    // Keep the single stray lash zone clean
    if (x > 742 && x < 846 && y > 716 && y < 756) continue;

    let sz = random(0.7, 2.2);
    let isStar = random() < 0.14;
    shimmerDarkRims.push({ x, y, sz });
    if (random() < 0.68) {
      shimmerWhiteDots.push({ x, y, sz, isStar });
    } else {
      shimmerTintedDots.push({ x, y, sz, nm: xToNm(x) });
    }
  }

  // Micro contrast rim behind each shimmer particle so it pops off the watercolor
  brush.set("micro_pencil", "#12101a", 0.55);
  for (let i = 0; i < shimmerDarkRims.length; i++) {
    let p = shimmerDarkRims[i];
    brush.line(p.x + 0.6, p.y + 0.8, p.x + 1.5, p.y + 1.2);
  }

  // Pure white specular shimmer particles
  brush.set("shimmer_glint", "#ffffff", 0.95);
  for (let i = 0; i < shimmerWhiteDots.length; i++) {
    let p = shimmerWhiteDots[i];
    brush.line(p.x - p.sz * 0.6, p.y, p.x + p.sz * 0.6, p.y);
    if (p.isStar) {
      // Crisp 4-point diamond/starburst micro-glint
      brush.line(p.x - p.sz * 1.6, p.y, p.x + p.sz * 1.6, p.y);
      brush.line(p.x, p.y - p.sz * 1.6, p.x, p.y + p.sz * 1.6);
    }
  }

  // Warm gold-champagne & icy cyan tinted mica particles
  brush.set("shimmer_glint", "#fff9d6", 0.85);
  for (let i = 0; i < shimmerTintedDots.length; i++) {
    let p = shimmerTintedDots[i];
    if (p.nm > 520) {
      brush.line(p.x - p.sz * 0.5, p.y - 0.3, p.x + p.sz * 0.5, p.y + 0.3);
    }
  }
  brush.set("shimmer_glint", "#e2f6ff", 0.85);
  for (let i = 0; i < shimmerTintedDots.length; i++) {
    let p = shimmerTintedDots[i];
    if (p.nm <= 520) {
      brush.line(p.x - p.sz * 0.5, p.y - 0.3, p.x + p.sz * 0.5, p.y + 0.3);
    }
  }

  // =========================================================================
  // 8. THE SINGLE STRAY LASH (QUIETLY INTIMATE FOCAL INCIDENT)
  // =========================================================================
  // Resting delicately at an oblique angle across the warm golden-coral lower lid skin
  // (around 598 nm – 628 nm, x = 752..838, y = 724..748) in quiet counterpoint to the vertical lines.
  const strayPts = [
    [752, 747, 1.45], // Bulbous dark follicle root
    [774, 745, 1.15],
    [798, 739, 0.90],
    [820, 731, 0.55],
    [839, 722, 0.12]  // Razor-fine tapered lash tip
  ];

  // 1. Delicate graphite & watercolor cast shadow 2.2px below the stray lash on the skin
  brush.set("pore_stipple", "#4a3230", 0.95);
  brush.spline([
    [753, 749.5, 1.1],
    [775, 747.5, 0.95],
    [799, 741.2, 0.75],
    [821, 733.0, 0.45],
    [840, 723.8, 0.15]
  ], 0.35);

  // 2. Subtle skin contact highlight along the upper edge of the stray lash
  brush.set("shimmer_glint", "#fff6ee", 0.55);
  brush.spline([
    [753, 745.6, 0.8],
    [786, 741.2, 0.9],
    [818, 730.2, 0.4]
  ], 0.35);

  // 3. The stray eyelash shaft itself
  brush.set("lash_ink", "#07060a", 1.28);
  brush.spline(strayPts, 0.35);
  brush.set("rotring", "#040307", 0.85);
  brush.spline(strayPts, 0.35);

  // 4. Tiny root bulb swelling & microscopic cuticle glint at (752, 747)
  brush.set("rotring", "#050408", 1.45);
  brush.line(750.5, 747.3, 754.5, 746.7);
  brush.set("shimmer_glint", "#ffffff", 0.55);
  brush.line(751.5, 746.5, 753.0, 746.3);

  brush.noClip();

  // =========================================================================
  // 9. CLEAN PAPER MARGINS & PRECISION GRAPHITE WAVELENGTH SCALES
  // =========================================================================
  // Mask any soft watercolor bleed outside [FX1, FY1, FX2, FY2] so the frame is surgical
  brush.noStroke();
  brush.wash("#eef0f4", 255);
  brush.rect(20, 220, 1160, FY1 - 220, "corner");
  brush.rect(20, FY2, 1160, 980 - FY2, "corner");
  brush.rect(20, FY1 - 5, FX1 - 20, FH + 10, "corner");
  brush.rect(FX2, FY1 - 5, 1180 - FX2, FH + 10, "corner");
  brush.noWash();

  // Crisp graphite aperture border around the long thin spectrometer frame
  brush.set("rotring", "#161820", 0.75);
  brush.line(FX1, FY1, FX2, FY1);
  brush.line(FX1, FY2, FX2, FY2);
  brush.line(FX1, FY1, FX1, FY2);
  brush.line(FX2, FY1, FX2, FY2);

  // Secondary outer hairline rule (3px offset)
  brush.set("micro_pencil", "#454954", 0.55);
  brush.line(FX1 - 3, FY1 - 3, FX2 + 3, FY1 - 3);
  brush.line(FX1 - 3, FY2 + 3, FX2 + 3, FY2 + 3);
  brush.line(FX1 - 3, FY1 - 3, FX1 - 3, FY2 + 3);
  brush.line(FX2 + 3, FY1 - 3, FX2 + 3, FY2 + 3);

  // Top & Bottom Wavelength Scales (380 nm to 720 nm)
  const topScaleY = FY1 - 3;
  const botScaleY = FY2 + 3;

  // Fine 1 nm & 5 nm subdivisions
  brush.set("micro_pencil", "#525763", 0.52);
  for (let nm = NM_MIN; nm <= NM_MAX; nm += 1) {
    let x = nmToX(nm);
    if (nm % 10 === 0) continue; // drawn in major pass
    let tickLen = (nm % 5 === 0) ? 9.5 : 5.0;
    brush.line(x, topScaleY, x, topScaleY - tickLen);
    brush.line(x, botScaleY, x, botScaleY + tickLen);
  }

  // Medium 10 nm & Major 50 nm ticks + wavelength numerals
  brush.set("micro_pencil", "#22252e", 0.78);
  for (let nm = NM_MIN; nm <= NM_MAX; nm += 10) {
    let x = nmToX(nm);
    let isMajor = (nm % 50 === 0);
    let tickLen = isMajor ? 19.0 : 13.5;

    brush.line(x, topScaleY, x, topScaleY - tickLen);
    brush.line(x, botScaleY, x, botScaleY + tickLen);

    if (isMajor) {
      // Small registration cross on major 50 nm ticks
      brush.line(x - 2.5, topScaleY - tickLen, x + 2.5, topScaleY - tickLen);
      brush.line(x - 2.5, botScaleY + tickLen, x + 2.5, botScaleY + tickLen);

      let label = nm.toString();
      let cw = 7.5;
      let ch = 12.5;
      let gap = 2.8;
      let totalW = label.length * cw + (label.length - 1) * gap;
      drawString(label, x - totalW * 0.5, topScaleY - tickLen - 19, cw, ch, gap);
      drawString(label, x - totalW * 0.5, botScaleY + tickLen + 7, cw, ch, gap);

      if (nm === 700) {
        drawString("nm", x + totalW * 0.5 + 7, topScaleY - tickLen - 19, cw, ch, gap);
        drawString("nm", x + totalW * 0.5 + 7, botScaleY + tickLen + 7, cw, ch, gap);
      }
    }
  }

  // Horizontal scale runner lines connecting the tick marks
  brush.set("micro_pencil", "#686e7c", 0.45);
  brush.line(FX1, topScaleY - 5, FX2, topScaleY - 5);
  brush.line(FX1, topScaleY - 13.5, FX2, topScaleY - 13.5);
  brush.line(FX1, botScaleY + 5, FX2, botScaleY + 5);
  brush.line(FX1, botScaleY + 13.5, FX2, botScaleY + 13.5);

  // Fraunhofer absorption line pointer ticks & letter designations above the top scale
  // and densitometer absorption profile trace at y ~ 288
  const traceBaseY = 282;
  brush.set("micro_pencil", "#7a808e", 0.42);
  brush.line(FX1, traceBaseY, FX2, traceBaseY);

  // Continuous graphite spectral intensity / absorption trace above the scale
  brush.set("micro_pencil", "#2c303b", 0.62);
  let prevX = FX1;
  let prevY = traceBaseY;
  const TRACE_STEPS = 340;
  for (let s = 1; s <= TRACE_STEPS; s++) {
    let x = FX1 + (s / TRACE_STEPS) * FW;
    let nm = xToNm(x);
    let dip = 0;
    for (let j = 0; j < FRAUNHOFER.length; j++) {
      let d = Math.abs(nm - FRAUNHOFER[j].nm);
      if (d < 3.2) {
        dip += FRAUNHOFER[j].strength * 22 * Math.exp(-(d * d) / 0.85);
      }
    }
    let microNoise = (noise(x * 0.18) - 0.5) * 3.5;
    let ty = traceBaseY + dip + microNoise;
    brush.line(prevX, prevY, x, ty);
    prevX = x;
    prevY = ty;
  }

  // Fraunhofer callout leaders & letters
  brush.set("micro_pencil", "#1e2028", 0.72);
  for (let i = 0; i < FRAUNHOFER.length; i++) {
    let f = FRAUNHOFER[i];
    let x = nmToX(f.nm);
    // Avoid label collision between K (393.4) and H (396.8)
    let xOffset = 0;
    if (f.label === "K") xOffset = -4.5;
    if (f.label === "H") xOffset = 4.5;

    brush.line(x, topScaleY - 21, x + xOffset, topScaleY - 36);
    drawString(f.label, x + xOffset - 3.8, topScaleY - 53, 7.6, 11.5, 2.0);

    // Matching bottom absorption tick indicator
    brush.line(x, botScaleY + 21, x, botScaleY + 31);
  }

  // Outer plate corner registration marks (quiet scientific framing)
  brush.set("micro_pencil", "#5a606e", 0.55);
  const corners = [
    [FX1 - 22, 248, 1, 1],
    [FX2 + 22, 248, -1, 1],
    [FX1 - 22, 912, 1, -1],
    [FX2 + 22, 912, -1, -1]
  ];
  for (let i = 0; i < corners.length; i++) {
    let [cx, cy, dx, dy] = corners[i];
    brush.line(cx, cy, cx + dx * 18, cy);
    brush.line(cx, cy, cx, cy + dy * 18);
  }

  noLoop();
}

// Hyperreal Ruby Grapefruit Half as an Art Deco Sunburst Emblem
// Rendered with p5.js 2.x and p5.brush

const CX = 600;
const CY = 565;

// Palette: Warm Lacquer, Metallic Golds, Creamy Pith, Rose Madder, Coral, Ruby & Blush
const PAL = {
  obsidian: "#070506",
  lacquerDark: "#0e090b",
  lacquerWarm: "#170d10",
  lacquerGlow: "#240e13",

  goldShadow: "#6e4b12",
  goldBronze: "#9e711f",
  goldMid: "#cfa338",
  goldBright: "#ebd5a0", // warm metallic highlight
  goldRich: "#e2b949",
  goldSpec: "#fff3bd",

  rindDeep: "#b83222",
  rindCoral: "#e05934",
  rindOrange: "#f08543",
  rindGold: "#f5ad52",

  pithBase: "#fbf1e1",
  pithWarm: "#f2dec4",
  pithShadow: "#dec09e",
  pithBlush: "#f5b8ae",
  pithCoral: "#ed8a80",
  pithBright: "#fffcf7",

  madderAbyss: "#4a0510",
  madderDark: "#6e0a1b",
  madderMid: "#991529",
  madderBright: "#bd1f35",
  rubyMid: "#d42c38",
  coralDeep: "#e34542",
  coralMid: "#ee6052",
  coralLight: "#f57e6e",
  blushMid: "#f8a094",
  blushLight: "#fcc4ba",
  blushPale: "#ffe3dc",

  specPure: "#ffffff",
  specWarm: "#fff5f2"
};

// State management helpers to prevent state leaks
function setWashOnly(col, op = 255) {
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, op);
}

function setFillOnly(col, op = 100, bleed = 0.16, dir = "in", tex = 0.52, border = 0.42) {
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fillBleed(bleed, dir);
  brush.fillTexture(tex, border);
  brush.fill(col, op);
}

function setStrokeOnly(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

// Polar coordinate helpers: phi in degrees clockwise from 12 o'clock (0 = top, 180 = bottom)
// Guarantees strict bilateral symmetry across x = CX
function ptRight(r, phi) {
  return [CX + r * sin(phi), CY - r * cos(phi)];
}

function ptLeft(r, phi) {
  return [CX - r * sin(phi), CY - r * cos(phi)];
}

function mirrorPt(pt) {
  return [2 * CX - pt[0], pt[1]];
}

function mirrorPoly(pts) {
  let out = [];
  for (let i = pts.length - 1; i >= 0; i--) {
    out.push([2 * CX - pts[i][0], pts[i][1]]);
  }
  return out;
}

function drawPoly(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

// Subtle 12-lobed grapefruit contour modulation
function fruitRadius(baseR, phi) {
  return baseR + 2.2 * cos(phi * 12) + 0.8 * cos(phi * 6);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(7391);
  noiseSeed(7391);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.obsidian);

  // 1. Lacquered Black Ground & Subtle Warm Undertone
  drawLacqueredGround();

  // 2. Art Deco Metallic-Gold Sunburst & Cinema-Foyer Frame
  drawArtDecoSunburst();

  // 3. Grapefruit Outer Rind (Flavedo) & Creamy Pith Ring (Albedo)
  drawRindAndPith();

  // 4. Pulp Wedges: Opaque Under-Wash & Layered Watercolor Glazes
  let wedgeData = generateWedgeData();
  drawWedgeGlazes(wedgeData);

  // 5. Hyperreal Individual Juice Vesicles (Symmetrically Paired)
  drawJuiceVesicles(wedgeData);

  // 6. Translucent Radial Membranes & Central Pith Core with Cut Seeds
  drawMembranesAndCore(wedgeData);

  // 7. Wet Specular Glints across Pulp, Membranes & Pith
  drawWetSpeculars(wedgeData);

  // 8. Asymmetric Dripping Juice at Bottom-Right Edge (Breaking the Geometry)
  drawAsymmetricJuiceDrips();

  noLoop();
}

// =============================================================================
// 1. LACQUERED BLACK GROUND
// =============================================================================
function drawLacqueredGround() {
  // Deep warm ambient reflection pooled beneath the fruit
  let auraRadii = [540, 460, 400];
  let auraCols = [PAL.lacquerDark, PAL.lacquerWarm, PAL.lacquerGlow];
  for (let i = 0; i < auraRadii.length; i++) {
    setWashOnly(auraCols[i], 140);
    let pts = [];
    for (let a = 0; a < 360; a += 10) {
      pts.push(ptRight(auraRadii[i], a));
    }
    drawPoly(pts, 0.2);
  }

  // Polished piano-lacquer diagonal surface grain (strictly symmetric chevron sheen)
  setStrokeOnly("marker", "#120c0e", 1.2);
  for (let y = -400; y < 1600; y += 28) {
    let dy = 320;
    brush.line(CX, y, 1200, y + dy);
    brush.line(CX, y, 0, y + dy);
  }

  setStrokeOnly("2B", "#040203", 0.6);
  for (let i = 0; i < 90; i++) {
    let y = random(40, 1160);
    let halfSpan = random(80, 550);
    brush.line(CX - halfSpan, y, CX + halfSpan, y);
  }
}

// =============================================================================
// 2. ART DECO METALLIC-GOLD SUNBURST & FRAME
// =============================================================================
function drawGoldSymmetricLine(p1, p2, tier = 1) {
  let m1 = mirrorPt(p1);
  let m2 = mirrorPt(p2);
  let isAxis = abs(p1[0] - CX) < 0.5 && abs(p2[0] - CX) < 0.5;

  // Under-bronze pass for metallic depth
  if (tier <= 2) {
    setStrokeOnly("marker", PAL.goldBronze, tier === 1 ? 0.55 : 0.35);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    if (!isAxis) brush.line(m1[0], m1[1], m2[0], m2[1]);
  }

  // Crisp gold core pass
  setStrokeOnly("rotring", tier === 1 ? PAL.goldRich : PAL.goldMid, tier === 1 ? 0.55 : 0.38);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
  if (!isAxis) brush.line(m1[0], m1[1], m2[0], m2[1]);

  // Metallic glint pass along a portion of the ray
  if (tier === 1 || (tier === 2 && random() < 0.7)) {
    let tA = 0.15;
    let tB = 0.65;
    let g1 = [lerp(p1[0], p2[0], tA), lerp(p1[1], p2[1], tA)];
    let g2 = [lerp(p1[0], p2[0], tB), lerp(p1[1], p2[1], tB)];
    let gm1 = mirrorPt(g1);
    let gm2 = mirrorPt(g2);
    setStrokeOnly("pen", PAL.goldSpec, 0.32);
    brush.line(g1[0], g1[1], g2[0], g2[1]);
    if (!isAxis) brush.line(gm1[0], gm1[1], gm2[0], gm2[1]);
  }
}

function clipRayToBox(rStart, rEnd, phi, minX, maxX, minY, maxY) {
  let p1 = ptRight(rStart, phi);
  let dx = sin(phi);
  let dy = -cos(phi);
  let tMax = rEnd;

  if (dx > 0.0001) tMax = min(tMax, (maxX - CX) / dx);
  if (dy > 0.0001) tMax = min(tMax, (maxY - CY) / dy);
  if (dy < -0.0001) tMax = min(tMax, (minY - CY) / dy);

  if (tMax <= rStart) return null;
  let p2 = ptRight(tMax, phi);
  return [p1, p2, tMax];
}

function drawArtDecoSunburst() {
  const B_OUT = 44;
  const B_IN = 60;
  const minX = B_IN, maxX = 1200 - B_IN;
  const minY = B_IN, maxY = 1200 - B_IN;

  // Concentric stepped Art Deco rings outside the rind
  let ringRadii = [380, 392, 438, 495, 560];
  for (let idx = 0; idx < ringRadii.length; idx++) {
    let r = ringRadii[idx];
    for (let w = 0; w < 6; w++) {
      let aStart = w * 30 + (idx % 2 === 0 ? 2 : 5);
      let aEnd = (w + 1) * 30 - (idx % 2 === 0 ? 2 : 5);
      // Convert our clockwise-from-top phi to p5 standard arc angles (-90 + phi)
      setStrokeOnly("marker", PAL.goldShadow, 0.45);
      brush.arc(CX, CY, r, -90 + aStart, -90 + aEnd);
      brush.arc(CX, CY, r, -90 - aEnd, -90 - aStart);

      setStrokeOnly("rotring", idx % 2 === 0 ? PAL.goldRich : PAL.goldMid, 0.42);
      brush.arc(CX, CY, r, -90 + aStart, -90 + aEnd);
      brush.arc(CX, CY, r, -90 - aEnd, -90 - aStart);
    }
  }

  // Radiating sunburst rays continuing the 12 segments outward into the black lacquer
  for (let w = 0; w <= 6; w++) {
    let phiMain = w * 30;
    // Main membrane continuation ray
    let segMain = clipRayToBox(362, 900, phiMain, minX, maxX, minY, maxY);
    if (segMain) {
      drawGoldSymmetricLine(segMain[0], segMain[1], 1);
      // Parallel Art Deco flanking hairlines on primary rays
      if (w > 0 && w < 6) {
        let sA = clipRayToBox(380, 780, phiMain - 0.9, minX, maxX, minY, maxY);
        let sB = clipRayToBox(380, 780, phiMain + 0.9, minX, maxX, minY, maxY);
        if (sA) drawGoldSymmetricLine(sA[0], sA[1], 2);
        if (sB) drawGoldSymmetricLine(sB[0], sB[1], 2);
      }
    }

    if (w < 6) {
      // Sub-rays within each 30-degree panel
      for (let sub = 1; sub < 10; sub++) {
        let phiSub = w * 30 + sub * 3;
        let isMid = (sub === 5); // 15-degree bisector
        let r0 = isMid ? 366 : (sub % 2 === 0 ? 380 : 392);
        let r1 = isMid ? 880 : (sub % 2 === 0 ? 670 : 525);
        let seg = clipRayToBox(r0, r1, phiSub, minX, maxX, minY, maxY);
        if (seg) {
          drawGoldSymmetricLine(seg[0], seg[1], isMid ? 1 : (sub % 2 === 0 ? 2 : 3));
        }
      }

      // Stepped Art Deco chevrons & lozenges along the 15-degree bisectors
      let phiBisect = w * 30 + 15;
      let chevRadii = [415, 465, 525];
      for (let cr of chevRadii) {
        let tip = ptRight(cr + 22, phiBisect);
        let wingL = ptRight(cr, phiBisect - 5.5);
        let wingR = ptRight(cr, phiBisect + 5.5);
        drawGoldSymmetricLine(wingL, tip, 2);
        drawGoldSymmetricLine(wingR, tip, 2);
      }

      // Small gold diamond emblem at r = 590 on bisectors that fit inside canvas
      let dCenter = ptRight(585, phiBisect);
      if (dCenter[0] < maxX - 25 && dCenter[1] > minY + 25 && dCenter[1] < maxY - 25) {
        let dIn = ptRight(562, phiBisect);
        let dOut = ptRight(608, phiBisect);
        let dSide1 = ptRight(585, phiBisect - 1.8);
        let dSide2 = ptRight(585, phiBisect + 1.8);
        let dPoly = [dIn, dSide1, dOut, dSide2];
        setWashOnly(PAL.goldRich, 210);
        drawPoly(dPoly);
        drawPoly(mirrorPoly(dPoly));
        drawGoldSymmetricLine(dIn, dSide1, 2);
        drawGoldSymmetricLine(dSide1, dOut, 2);
        drawGoldSymmetricLine(dOut, dSide2, 2);
        drawGoldSymmetricLine(dSide2, dIn, 2);
      }
    }
  }

  // Outer Stepped Art Deco Cinema-Foyer Border
  // Outer rectangle with stepped corners
  let cStep = 85;
  let frameLines = [
    // Top horizontal
    [[CX, B_OUT], [1200 - B_OUT - cStep, B_OUT]],
    [[CX, B_IN], [1200 - B_IN - cStep, B_IN]],
    // Bottom horizontal
    [[CX, 1200 - B_OUT], [1200 - B_OUT - cStep, 1200 - B_OUT]],
    [[CX, 1200 - B_IN], [1200 - B_IN - cStep, 1200 - B_IN]],
    // Right vertical
    [[1200 - B_OUT, B_OUT + cStep], [1200 - B_OUT, 1200 - B_OUT - cStep]],
    [[1200 - B_IN, B_IN + cStep], [1200 - B_IN, 1200 - B_IN - cStep]],
    // Top-right stepped corner
    [[1200 - B_OUT - cStep, B_OUT], [1200 - B_OUT - cStep, B_OUT + 28]],
    [[1200 - B_OUT - cStep, B_OUT + 28], [1200 - B_OUT - 28, B_OUT + 28]],
    [[1200 - B_OUT - 28, B_OUT + 28], [1200 - B_OUT - 28, B_OUT + cStep]],
    [[1200 - B_OUT - 28, B_OUT + cStep], [1200 - B_OUT, B_OUT + cStep]],
    // Inner top-right diagonal bevel
    [[1200 - B_IN - cStep, B_IN], [1200 - B_IN, B_IN + cStep]],
    [[1200 - B_IN - cStep + 14, B_IN], [1200 - B_IN, B_IN + cStep - 14]],
    // Bottom-right stepped corner
    [[1200 - B_OUT - cStep, 1200 - B_OUT], [1200 - B_OUT - cStep, 1200 - B_OUT - 28]],
    [[1200 - B_OUT - cStep, 1200 - B_OUT - 28], [1200 - B_OUT - 28, 1200 - B_OUT - 28]],
    [[1200 - B_OUT - 28, 1200 - B_OUT - 28], [1200 - B_OUT - 28, 1200 - B_OUT - cStep]],
    [[1200 - B_OUT - 28, 1200 - B_OUT - cStep], [1200 - B_OUT, 1200 - B_OUT - cStep]],
    // Inner bottom-right diagonal bevel
    [[1200 - B_IN - cStep, 1200 - B_IN], [1200 - B_IN, 1200 - B_IN - cStep]],
    [[1200 - B_IN - cStep + 14, 1200 - B_IN], [1200 - B_IN, 1200 - B_IN - cStep + 14]]
  ];

  for (let ln of frameLines) {
    drawGoldSymmetricLine(ln[0], ln[1], 1);
  }

  // Corner fan bursts at all 4 corners
  let cornerOrigins = [
    [1200 - B_OUT, B_OUT],
    [1200 - B_OUT, 1200 - B_OUT]
  ];
  for (let idx = 0; idx < cornerOrigins.length; idx++) {
    let co = cornerOrigins[idx];
    let dirY = idx === 0 ? 1 : -1;
    for (let f = 1; f <= 5; f++) {
      let ang = f * 15;
      let len = 115;
      let pEnd = [co[0] - len * cos(ang), co[1] + dirY * len * sin(ang)];
      drawGoldSymmetricLine(co, pEnd, 2);
    }
  }
}

// =============================================================================
// 3. OUTER RIND (FLAVEDO) & CREAMY PITH RING (ALBEDO)
// =============================================================================
function drawRindAndPith() {
  // Subtle dark contact rim shadow under the fruit on the lacquer
  setWashOnly("#030102", 210);
  let shadowPts = [];
  for (let a = 0; a < 360; a += 4) {
    let r = fruitRadius(373, a);
    shadowPts.push([CX + r * sin(a), CY - r * cos(a) + 5]);
  }
  drawPoly(shadowPts);

  // Outer Rind (Flavedo): r = 352..368
  let rindOuterPts = [];
  for (let a = 0; a < 360; a += 3) {
    rindOuterPts.push(ptRight(fruitRadius(368, a), a));
  }
  setWashOnly(PAL.rindCoral, 250);
  drawPoly(rindOuterPts);

  let rindMidPts = [];
  for (let a = 0; a < 360; a += 3) {
    rindMidPts.push(ptRight(fruitRadius(363, a), a));
  }
  setWashOnly(PAL.rindOrange, 220);
  drawPoly(rindMidPts);

  // Watercolor coral-gold glazes on the outer peel rim
  for (let w = 0; w < 6; w++) {
    let a1 = w * 30;
    let a2 = (w + 1) * 30;
    let segPts = [];
    for (let a = a1; a <= a2; a += 5) segPts.push(ptRight(fruitRadius(368, a), a));
    for (let a = a2; a >= a1; a -= 5) segPts.push(ptRight(fruitRadius(352, a), a));

    setFillOnly(w % 2 === 0 ? PAL.rindDeep : PAL.rindGold, 95, 0.15, "in", 0.5, 0.4);
    drawPoly(segPts);
    drawPoly(mirrorPoly(segPts));
  }

  // Creamy Pith Ring (Albedo): r = 298..355
  // Solid opaque cream base wash so the dark background is 100% blocked
  let pithOuterPts = [];
  for (let a = 0; a < 360; a += 3) {
    let wave = 1.4 * sin(a * 18);
    pithOuterPts.push(ptRight(fruitRadius(355 + wave, a), a));
  }
  setWashOnly(PAL.pithBase, 255);
  drawPoly(pithOuterPts);

  // Brighter inner-mid cream wash
  let pithBrightPts = [];
  for (let a = 0; a < 360; a += 3) {
    pithBrightPts.push(ptRight(fruitRadius(346, a), a));
  }
  setWashOnly(PAL.pithBright, 235);
  drawPoly(pithBrightPts);

  // Layered watercolor glazes along the pith: warm parchment outer + blush-rose inner bleed
  for (let w = 0; w < 6; w++) {
    let a1 = w * 30;
    let a2 = (w + 1) * 30;

    // Outer warm parchment glaze near flavedo
    let outerGlaze = [];
    for (let a = a1; a <= a2; a += 5) outerGlaze.push(ptRight(fruitRadius(356, a), a));
    for (let a = a2; a >= a1; a -= 5) outerGlaze.push(ptRight(fruitRadius(336, a), a));
    setFillOnly(PAL.pithWarm, 85, 0.2, "in", 0.45, 0.35);
    drawPoly(outerGlaze);
    drawPoly(mirrorPoly(outerGlaze));

    // Inner blush-coral bleed where ruby juice stains the pith ring
    let innerBleed = [];
    for (let a = a1; a <= a2; a += 3) {
      let cusp = 14 * pow(cos((a - a1) * 6), 4);
      innerBleed.push(ptRight(fruitRadius(316 - cusp * 0.4, a), a));
    }
    for (let a = a2; a >= a1; a -= 3) {
      let cusp = 22 * pow(cos((a - a1) * 6), 6);
      innerBleed.push(ptRight(fruitRadius(296 - cusp, a), a));
    }
    setFillOnly(PAL.pithBlush, 110, 0.24, "out", 0.55, 0.4);
    drawPoly(innerBleed);
    drawPoly(mirrorPoly(innerBleed));
  }

  // Tactile spongy pith texture & flavedo oil glands (strictly symmetric)
  for (let pass = 0; pass < 2; pass++) {
    setStrokeOnly("cpencil", pass === 0 ? PAL.pithShadow : PAL.pithWarm, 0.45);
    for (let i = 0; i < 260; i++) {
      let phi = random(0.5, 179.5);
      let r1 = random(304, 348);
      let r2 = r1 + random(3, 8);
      let p1 = ptRight(fruitRadius(r1, phi), phi);
      let p2 = ptRight(fruitRadius(r2, phi + random(-0.6, 0.6)), phi + random(-0.6, 0.6));
      let m1 = mirrorPt(p1);
      let m2 = mirrorPt(p2);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.line(m1[0], m1[1], m2[0], m2[1]);
    }
  }

  // Oil gland pores along the golden-coral rind rim
  setStrokeOnly("rotring", PAL.rindDeep, 0.5);
  for (let i = 0; i < 180; i++) {
    let phi = random(0.5, 179.5);
    let r = fruitRadius(random(355, 366), phi);
    let p1 = ptRight(r, phi);
    let p2 = [p1[0] + 1.5, p1[1] + 1.5];
    let m1 = mirrorPt(p1);
    let m2 = mirrorPt(p2);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(m1[0], m1[1], m2[0], m2[1]);
  }
}

// =============================================================================
// 4. PULP WEDGES: GEOMETRY & LAYERED WATERCOLOR GLAZES
// =============================================================================
function buildWedgePolygon(w, rIn = 30, rOut = 302, padDeg = 1.35) {
  let a1 = w * 30 + padDeg;
  let a2 = (w + 1) * 30 - padDeg;
  let aMid = (a1 + a2) * 0.5;
  let pts = [];

  // Rounded inner tip
  pts.push(ptRight(rIn + 5, a1 + 2.2));
  pts.push(ptRight(rIn, aMid));
  pts.push(ptRight(rIn + 5, a2 - 2.2));

  // Right radial flank going outward
  for (let r = rIn + 18; r <= rOut - 18; r += 26) {
    let angleTighten = map(r, rIn, rOut, 1.4, 0.0);
    pts.push(ptRight(r, a2 - angleTighten));
  }

  // Outer curved dorsal arc along the pith with rounded corners at septum cusps
  for (let a = a2 - 0.3; a >= a1 + 0.3; a -= 2.5) {
    let edgeDist = min( abs(a - a1), abs(a2 - a) );
    let cornerRound = edgeDist < 4.5 ? map(edgeDist, 0, 4.5, 12, 0) : 0;
    let r = fruitRadius(rOut - cornerRound, a);
    pts.push(ptRight(r, a));
  }

  // Left radial flank returning inward
  for (let r = rOut - 18; r >= rIn + 18; r -= 26) {
    let angleTighten = map(r, rIn, rOut, 1.4, 0.0);
    pts.push(ptRight(r, a1 + angleTighten));
  }

  return pts;
}

function generateWedgeData() {
  let wedges = [];
  for (let w = 0; w < 6; w++) {
    let basePoly = buildWedgePolygon(w, 30, 302, 1.3);
    let innerPoly = buildWedgePolygon(w, 35, 296, 1.8);

    // Precompute hyperreal vesicles inside this wedge
    let vesicles = [];
    let a1 = w * 30 + 1.7;
    let a2 = (w + 1) * 30 - 1.7;
    let aMid = (a1 + a2) * 0.5;

    // 10 radial tiers from inner tip (r=38) to outer pith wall (r=294)
    let rTiers = [36, 56, 78, 102, 128, 155, 184, 214, 245, 273, 295];
    for (let t = 0; t < rTiers.length - 1; t++) {
      let rA = rTiers[t];
      let rB = rTiers[t + 1];
      let rCenter = (rA + rB) * 0.5;
      let rHalfLen = (rB - rA) * 0.54;

      // Number of vesicles across the angular span increases with radius
      let cols = floor(map(rCenter, 40, 285, 2.4, 9.6));
      let anglePadding = map(rCenter, 40, 290, 2.2, 0.5);
      let spanA1 = a1 + anglePadding;
      let spanA2 = a2 - anglePadding;
      let dA = (spanA2 - spanA1) / cols;

      for (let c = 0; c < cols; c++) {
        let phiC = spanA1 + (c + 0.5) * dA + random(-0.18, 0.18) * dA;
        let rC = rCenter + random(-2.2, 2.2);

        // Natural herring-bone / chevron tilt of grapefruit vesicles toward segment axis
        let sideFactor = (phiC - aMid) / ((a2 - a1) * 0.5); // -1 to +1
        let tiltDeg = -sideFactor * map(rCenter, 45, 285, 4, 11);

        let vLen = rHalfLen * random(0.92, 1.12);
        let vWidDeg = dA * random(0.42, 0.50);

        // Construct plump spindle / teardrop vesicle polygon (8 vertices)
        let tipIn = ptRight(rC - vLen, phiC + tiltDeg * 0.25);
        let inFlankL = ptRight(rC - vLen * 0.38, phiC - vWidDeg * 0.72 + tiltDeg * 0.1);
        let midFlankL = ptRight(rC + vLen * 0.12, phiC - vWidDeg);
        let outFlankL = ptRight(rC + vLen * 0.65, phiC - vWidDeg * 0.68 - tiltDeg * 0.1);
        let tipOut = ptRight(min(298, rC + vLen), phiC - tiltDeg * 0.2);
        let outFlankR = ptRight(rC + vLen * 0.65, phiC + vWidDeg * 0.68 - tiltDeg * 0.1);
        let midFlankR = ptRight(rC + vLen * 0.12, phiC + vWidDeg);
        let inFlankR = ptRight(rC - vLen * 0.38, phiC + vWidDeg * 0.72 + tiltDeg * 0.1);

        let vPoly = [tipIn, inFlankL, midFlankL, outFlankL, tipOut, outFlankR, midFlankR, inFlankR];

        // Smaller inner core polygon for translucent vesicle glow
        let corePoly = [
          ptRight(rC - vLen * 0.55, phiC + tiltDeg * 0.15),
          ptRight(rC, phiC - vWidDeg * 0.52),
          ptRight(rC + vLen * 0.58, phiC - tiltDeg * 0.1),
          ptRight(rC, phiC + vWidDeg * 0.52)
        ];

        // Determine color tone based on position in the segment (deep madder crevices, coral belly, blush rim)
        let edgeProx = abs(sideFactor); // 0 at center, 1 at membrane wall
        let radialNorm = (rCenter - 40) / 250; // 0 at core, 1 at pith
        let toneVal = noise(w * 3.1 + t * 0.45, c * 0.55) * 0.55
                    + (1.0 - edgeProx) * 0.28
                    + abs(radialNorm - 0.45) * 0.25;

        let colIdx = constrain(floor(map(toneVal, 0.18, 0.88, 0, 6.99)), 0, 6);

        // Specular highlight geometry on turgid vesicles
        let hasSpec = random() < 0.68;
        let specPoly = null;
        let specDot = null;
        if (hasSpec) {
          let sR1 = rC - vLen * 0.32;
          let sR2 = rC + vLen * 0.28;
          let sPhi = phiC - vWidDeg * 0.28;
          specPoly = [
            ptRight(sR1, sPhi),
            ptRight((sR1 + sR2) * 0.5, sPhi - vWidDeg * 0.22),
            ptRight(sR2, sPhi),
            ptRight((sR1 + sR2) * 0.5, sPhi + vWidDeg * 0.08)
          ];
          specDot = ptRight(sR2 + 3.2, sPhi);
        }

        vesicles.push({
          vPoly,
          corePoly,
          colIdx,
          hasSpec,
          specPoly,
          specDot,
          rCenter,
          phiC,
          edgeProx
        });
      }
    }

    wedges.push({ w, basePoly, innerPoly, vesicles });
  }
  return wedges;
}

function drawWedgeGlazes(wedgeData) {
  // Step 1: Opaque Blush & Coral Base Washes for each wedge (blocks the black canvas)
  setWashOnly(PAL.blushMid, 255);
  for (let wd of wedgeData) {
    drawPoly(wd.basePoly);
    drawPoly(mirrorPoly(wd.basePoly));
  }

  setWashOnly(PAL.coralMid, 235);
  for (let wd of wedgeData) {
    drawPoly(wd.innerPoly);
    drawPoly(mirrorPoly(wd.innerPoly));
  }

  // Step 2: Layered Watercolor Glazes batched by pigment for lush bleeding & granulation
  // Glaze Pass A: Luminous Blush & Coral-Rose near outer arc and inner point
  setFillOnly(PAL.coralLight, 95, 0.22, "in", 0.55, 0.4);
  for (let wd of wedgeData) {
    let outerBand = buildWedgePolygon(wd.w, 205, 300, 1.5);
    drawPoly(outerBand);
    drawPoly(mirrorPoly(outerBand));
  }

  // Glaze Pass B: Rich Coral across the central belly of each wedge
  setFillOnly(PAL.coralDeep, 105, 0.20, "in", 0.58, 0.45);
  for (let wd of wedgeData) {
    let midBand = buildWedgePolygon(wd.w, 65, 255, 2.0);
    drawPoly(midBand);
    drawPoly(mirrorPoly(midBand));
  }

  // Glaze Pass C: Rose Madder in the deeper middle-inner zone and lateral membrane channels
  setFillOnly(PAL.madderBright, 110, 0.18, "in", 0.62, 0.48);
  for (let wd of wedgeData) {
    let deepZone = buildWedgePolygon(wd.w, 42, 205, 1.6);
    drawPoly(deepZone);
    drawPoly(mirrorPoly(deepZone));
  }

  // Glaze Pass D: Deep Alizarin / Rose Madder shadow pools along the two lateral walls of each wedge
  setFillOnly(PAL.madderDark, 105, 0.16, "in", 0.60, 0.50);
  for (let wd of wedgeData) {
    let a1 = wd.w * 30 + 1.4;
    let a2 = (wd.w + 1) * 30 - 1.4;
    let leftFlank = [
      ptRight(38, a1),
      ptRight(290, a1),
      ptRight(285, a1 + 6.5),
      ptRight(150, a1 + 8.5),
      ptRight(45, a1 + 5.0)
    ];
    let rightFlank = [
      ptRight(38, a2),
      ptRight(45, a2 - 5.0),
      ptRight(150, a2 - 8.5),
      ptRight(285, a2 - 6.5),
      ptRight(290, a2)
    ];
    drawPoly(leftFlank);
    drawPoly(mirrorPoly(leftFlank));
    drawPoly(rightFlank);
    drawPoly(mirrorPoly(rightFlank));
  }

  // Glaze Pass E: Translucent Blush-Pink bloom at the outer dorsal cusp
  setFillOnly(PAL.blushLight, 85, 0.25, "out", 0.45, 0.35);
  for (let wd of wedgeData) {
    let dorsalBloom = buildWedgePolygon(wd.w, 255, 301, 3.2);
    drawPoly(dorsalBloom);
    drawPoly(mirrorPoly(dorsalBloom));
  }
}

// =============================================================================
// 5. INDIVIDUAL JUICE VESICLES (HYPERREAL PULP STRUCTURE)
// =============================================================================
function drawJuiceVesicles(wedgeData) {
  const bodyColors = [
    PAL.madderAbyss,
    PAL.madderDark,
    PAL.madderMid,
    PAL.madderBright,
    PAL.rubyMid,
    PAL.coralDeep,
    PAL.coralLight
  ];

  const coreColors = [
    PAL.madderDark,
    PAL.madderMid,
    PAL.rubyMid,
    PAL.coralDeep,
    PAL.coralMid,
    PAL.coralLight,
    PAL.blushMid
  ];

  // Batch vesicles by color index for fast, rich layering
  for (let cIdx = 0; cIdx < bodyColors.length; cIdx++) {
    setWashOnly(bodyColors[cIdx], 220);
    for (let wd of wedgeData) {
      for (let v of wd.vesicles) {
        if (v.colIdx === cIdx) {
          drawPoly(v.vPoly);
          drawPoly(mirrorPoly(v.vPoly));
        }
      }
    }

    // Translucent glowing interior of each vesicle
    setWashOnly(coreColors[cIdx], 195);
    for (let wd of wedgeData) {
      for (let v of wd.vesicles) {
        if (v.colIdx === cIdx) {
          drawPoly(v.corePoly);
          drawPoly(mirrorPoly(v.corePoly));
        }
      }
    }
  }

  // Delicate cellular membrane contours between vesicles (dark madder crevices + blush rims)
  setStrokeOnly("pen", PAL.madderAbyss, 0.32);
  for (let wd of wedgeData) {
    for (let v of wd.vesicles) {
      let p0 = v.vPoly[0];
      let p1 = v.vPoly[1];
      let p2 = v.vPoly[2];
      let p4 = v.vPoly[4];
      brush.line(p0[0], p0[1], p1[0], p1[1]);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      let m0 = mirrorPt(p0), m1 = mirrorPt(p1), m2 = mirrorPt(p2);
      brush.line(m0[0], m0[1], m1[0], m1[1]);
      brush.line(m1[0], m1[1], m2[0], m2[1]);

      if (v.colIdx <= 2) {
        let p6 = v.vPoly[6];
        let m4 = mirrorPt(p4), m6 = mirrorPt(p6);
        brush.line(p4[0], p4[1], p6[0], p6[1]);
        brush.line(m4[0], m4[1], m6[0], m6[1]);
      }
    }
  }

  // Translucent blush-coral highlights on vesicle walls
  setStrokeOnly("cpencil", PAL.blushMid, 0.35);
  for (let wd of wedgeData) {
    for (let v of wd.vesicles) {
      if (v.colIdx >= 3) {
        let p5 = v.vPoly[5];
        let p6 = v.vPoly[6];
        let p7 = v.vPoly[7];
        brush.line(p5[0], p5[1], p6[0], p6[1]);
        brush.line(p6[0], p6[1], p7[0], p7[1]);
        let m5 = mirrorPt(p5), m6 = mirrorPt(p6), m7 = mirrorPt(p7);
        brush.line(m5[0], m5[1], m6[0], m6[1]);
        brush.line(m6[0], m6[1], m7[0], m7[1]);
      }
    }
  }

  // Final unifying watercolor glaze Veil of Rose Madder & Blush over the vesicles
  setFillOnly(PAL.madderMid, 48, 0.25, "in", 0.55, 0.35);
  for (let wd of wedgeData) {
    let veilPoly = buildWedgePolygon(wd.w, 48, 225, 3.0);
    drawPoly(veilPoly);
    drawPoly(mirrorPoly(veilPoly));
  }
}

// =============================================================================
// 6. TRANSLUCENT RADIAL MEMBRANES & CENTRAL CORE WITH CUT SEEDS
// =============================================================================
function drawMembranesAndCore(wedgeData) {
  // Translucent blush-cream membrane glazes overlapping the segment boundaries
  setFillOnly(PAL.pithBlush, 85, 0.15, "out", 0.4, 0.3);
  for (let w = 0; w <= 6; w++) {
    let phi = w * 30;
    let isAxis = (w === 0 || w === 6);
    let memGlaze = [
      ptRight(24, phi - 2.2),
      ptRight(306, phi - 1.6),
      ptRight(314, phi),
      ptRight(306, phi + 1.6),
      ptRight(24, phi + 2.2)
    ];
    drawPoly(memGlaze);
    if (!isAxis) drawPoly(mirrorPoly(memGlaze));
  }

  // Opaque creamy septum cusps where the pith joins each radial membrane
  setWashOnly(PAL.pithBase, 250);
  for (let w = 0; w <= 6; w++) {
    let phi = w * 30;
    let isAxis = (w === 0 || w === 6);
    let cuspPoly = [
      ptRight(312, phi - 5.2),
      ptRight(265, phi - 0.75),
      ptRight(265, phi + 0.75),
      ptRight(312, phi + 5.2)
    ];
    drawPoly(cuspPoly);
    if (!isAxis) drawPoly(mirrorPoly(cuspPoly));
  }

  // Crisp creamy radial membrane walls from central core (r=24) to pith (r=308)
  for (let w = 0; w <= 6; w++) {
    let phi = w * 30;
    let isAxis = (w === 0 || w === 6);

    // Deep madder shadow溝 right alongside the membrane
    setStrokeOnly("pen", PAL.madderAbyss, 0.42);
    let sL1 = ptRight(32, phi - 1.15), sL2 = ptRight(298, phi - 1.15);
    let sR1 = ptRight(32, phi + 1.15), sR2 = ptRight(298, phi + 1.15);
    brush.line(sL1[0], sL1[1], sL2[0], sL2[1]);
    brush.line(sR1[0], sR1[1], sR2[0], sR2[1]);
    if (!isAxis) {
      let msL1 = mirrorPt(sL1), msL2 = mirrorPt(sL2);
      let msR1 = mirrorPt(sR1), msR2 = mirrorPt(sR2);
      brush.line(msL1[0], msL1[1], msL2[0], msL2[1]);
      brush.line(msR1[0], msR1[1], msR2[0], msR2[1]);
    }

    // Warm blush-cream outer membrane sheath
    setStrokeOnly("cpencil", PAL.pithWarm, 0.85);
    let p1 = ptRight(24, phi), p2 = ptRight(310, phi);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    if (!isAxis) {
      let mp1 = mirrorPt(p1), mp2 = mirrorPt(p2);
      brush.line(mp1[0], mp1[1], mp2[0], mp2[1]);
    }

    // Razor-sharp bright ivory membrane core line
    setStrokeOnly("rotring", PAL.pithBright, 0.52);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    if (!isAxis) {
      let mp1 = mirrorPt(p1), mp2 = mirrorPt(p2);
      brush.line(mp1[0], mp1[1], mp2[0], mp2[1]);
    }
  }

  // Central Pith Column (Columella) Star & Hollow Rose Center
  let starPts = [];
  for (let i = 0; i < 24; i++) {
    let a = i * 15;
    let r = (i % 2 === 0) ? 39 : 25;
    starPts.push(ptRight(r, a));
  }
  setWashOnly(PAL.pithBlush, 240);
  drawPoly(starPts);

  let innerStarPts = [];
  for (let i = 0; i < 24; i++) {
    let a = i * 15;
    let r = (i % 2 === 0) ? 34 : 21;
    innerStarPts.push(ptRight(r, a));
  }
  setWashOnly(PAL.pithBase, 255);
  drawPoly(innerStarPts);

  let brightCorePts = [];
  for (let i = 0; i < 24; i++) {
    let a = i * 15;
    let r = (i % 2 === 0) ? 28 : 17;
    brightCorePts.push(ptRight(r, a));
  }
  setWashOnly(PAL.pithBright, 250);
  drawPoly(brightCorePts);

  // Tiny hollow central vascular pit in rose-madder & blush
  let centerPit = [];
  for (let a = 0; a < 360; a += 30) {
    centerPit.push(ptRight(8.5, a));
  }
  setWashOnly(PAL.pithCoral, 230);
  drawPoly(centerPit);

  let innerPit = [];
  for (let a = 0; a < 360; a += 30) {
    innerPit.push(ptRight(4.5, a));
  }
  setWashOnly(PAL.madderDark, 230);
  drawPoly(innerPit);

  // Symmetrically placed cut citrus seeds nestled near the inner core (wedges 1 & 3)
  let seedAngles = [45, 105];
  let seedRadii = [52, 46];
  for (let i = 0; i < seedAngles.length; i++) {
    let sa = seedAngles[i];
    let sr = seedRadii[i];

    // Dark crimson seed socket shadow
    let socketPoly = [
      ptRight(sr - 14, sa),
      ptRight(sr - 2, sa - 5.2),
      ptRight(sr + 15, sa),
      ptRight(sr - 2, sa + 5.2)
    ];
    setWashOnly(PAL.madderAbyss, 235);
    drawPoly(socketPoly);
    drawPoly(mirrorPoly(socketPoly));

    // Creamy ivory seed husk
    let huskPoly = [
      ptRight(sr - 12, sa),
      ptRight(sr - 1, sa - 4.0),
      ptRight(sr + 12, sa),
      ptRight(sr - 1, sa + 4.0)
    ];
    setWashOnly(PAL.pithBright, 255);
    drawPoly(huskPoly);
    drawPoly(mirrorPoly(huskPoly));

    // Warm yellow-cream cut cotyledon interior
    let cotPoly = [
      ptRight(sr - 7, sa),
      ptRight(sr, sa - 2.3),
      ptRight(sr + 8, sa),
      ptRight(sr, sa + 2.3)
    ];
    setWashOnly("#e8cf96", 240);
    drawPoly(cotPoly);
    drawPoly(mirrorPoly(cotPoly));

    // Wet glint on cut seed
    setStrokeOnly("rotring", PAL.specPure, 0.45);
    let sp1 = ptRight(sr - 4, sa - 1.0);
    let sp2 = ptRight(sr + 4, sa - 1.0);
    brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);
    let msp1 = mirrorPt(sp1), msp2 = mirrorPt(sp2);
    brush.line(msp1[0], msp1[1], msp2[0], msp2[1]);
  }
}

// =============================================================================
// 7. WET SPECULAR GLINTS (GLISTENING CITRUS SURFACE)
// =============================================================================
function drawWetSpeculars(wedgeData) {
  // Soft blush-white halo under the brightest speculars
  setWashOnly(PAL.blushPale, 190);
  for (let wd of wedgeData) {
    for (let v of wd.vesicles) {
      if (v.hasSpec && v.specPoly) {
        drawPoly(v.specPoly);
        drawPoly(mirrorPoly(v.specPoly));
      }
    }
  }

  // Crisp pure-white wet meniscus highlights on individual vesicles
  setStrokeOnly("rotring", PAL.specPure, 0.48);
  for (let wd of wedgeData) {
    for (let v of wd.vesicles) {
      if (v.hasSpec && v.specPoly) {
        let p0 = v.specPoly[0];
        let p1 = v.specPoly[1];
        let p2 = v.specPoly[2];
        brush.line(p0[0], p0[1], p1[0], p1[1]);
        brush.line(p1[0], p1[1], p2[0], p2[1]);

        let m0 = mirrorPt(p0), m1 = mirrorPt(p1), m2 = mirrorPt(p2);
        brush.line(m0[0], m0[1], m1[0], m1[1]);
        brush.line(m1[0], m1[1], m2[0], m2[1]);

        // Pinpoint satellite glint
        if (v.specDot) {
          let d = v.specDot;
          let md = mirrorPt(d);
          brush.line(d[0], d[1], d[0] + 1.2, d[1] + 1.2);
          brush.line(md[0], md[1], md[0] - 1.2, md[1] + 1.2);
        }
      }
    }
  }

  // Glistening liquid meniscus threads along the radial membranes and outer pith junction
  setStrokeOnly("rotring", PAL.specPure, 0.55);
  for (let w = 0; w < 6; w++) {
    let a1 = w * 30 + 1.6;
    let a2 = (w + 1) * 30 - 1.6;

    // Broken wet threads along left and right membrane fillets
    for (let r = 52; r < 285; r += 34) {
      let len = random(10, 18);
      let pA = ptRight(r, a1 + 0.4);
      let pB = ptRight(r + len, a1 + 0.4);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
      let mA = mirrorPt(pA), mB = mirrorPt(pB);
      brush.line(mA[0], mA[1], mB[0], mB[1]);

      let pC = ptRight(r + 12, a2 - 0.4);
      let pD = ptRight(r + 12 + len, a2 - 0.4);
      brush.line(pC[0], pC[1], pD[0], pD[1]);
      let mC = mirrorPt(pC), mD = mirrorPt(pD);
      brush.line(mC[0], mC[1], mD[0], mD[1]);
    }

    // Wet arc glints along the outer pulp-pith crease (r ≈ 299)
    for (let a = a1 + 3; a < a2 - 3; a += 5.5) {
      let g1 = ptRight(fruitRadius(298, a), a);
      let g2 = ptRight(fruitRadius(298, a + 2.4), a + 2.4);
      brush.line(g1[0], g1[1], g2[0], g2[1]);
      let mg1 = mirrorPt(g1), mg2 = mirrorPt(g2);
      brush.line(mg1[0], mg1[1], mg2[0], mg2[1]);
    }
  }
}

