function drawSingleJuiceDrip(x, yStart, yEnd, headWidth, dropRadius) {
  // 1. Dark contact shadow on the black lacquer
  let shadowDrop = [];
  for (let a = 0; a < 360; a += 20) {
    let rx = dropRadius * 1.05 * sin(a);
    let ry = dropRadius * 1.25 * cos(a);
    shadowDrop.push([x + 3 + rx, yEnd - dropRadius * 0.4 + 4 - ry]);
  }
  setWashOnly("#020001", 220);
  drawPoly(shadowDrop);

  // 2. Liquid rivulet & pendant teardrop body contour
  let neckY = yEnd - dropRadius * 2.2;
  let streamPoly = [
    [x - headWidth * 0.5, yStart],
    [x - headWidth * 0.22, lerp(yStart, neckY, 0.35)],
    [x - dropRadius * 0.28, neckY],
    [x - dropRadius * 0.85, yEnd - dropRadius * 1.1],
    [x - dropRadius * 1.02, yEnd - dropRadius * 0.35],
    [x - dropRadius * 0.65, yEnd + dropRadius * 0.42],
    [x, yEnd + dropRadius * 0.68],
    [x + dropRadius * 0.65, yEnd + dropRadius * 0.42],
    [x + dropRadius * 1.02, yEnd - dropRadius * 0.35],
    [x + dropRadius * 0.85, yEnd - dropRadius * 1.1],
    [x + dropRadius * 0.28, neckY],
    [x + headWidth * 0.22, lerp(yStart, neckY, 0.35)],
    [x + headWidth * 0.5, yStart]
  ];

  // Deep ruby-madder base wash
  setWashOnly(PAL.madderDark, 235);
  drawPoly(streamPoly, 0.25);

  // Mid-ruby translucent interior
  let innerStream = [
    [x - headWidth * 0.32, yStart + 2],
    [x - dropRadius * 0.18, neckY],
    [x - dropRadius * 0.78, yEnd - dropRadius * 0.35],
    [x, yEnd + dropRadius * 0.55],
    [x + dropRadius * 0.78, yEnd - dropRadius * 0.35],
    [x + dropRadius * 0.18, neckY],
    [x + headWidth * 0.32, yStart + 2]
  ];
  setWashOnly(PAL.madderBright, 220);
  drawPoly(innerStream, 0.25);

  // Luminous coral-ruby caustic glow inside the lower belly of the pendant drop
  let causticPoly = [
    [x - dropRadius * 0.55, yEnd - dropRadius * 0.3],
    [x - dropRadius * 0.68, yEnd + dropRadius * 0.15],
    [x, yEnd + dropRadius * 0.52],
    [x + dropRadius * 0.68, yEnd + dropRadius * 0.15],
    [x + dropRadius * 0.55, yEnd - dropRadius * 0.3],
    [x, yEnd - dropRadius * 0.65]
  ];
  setWashOnly(PAL.coralMid, 230);
  drawPoly(causticPoly, 0.3);

  let hotCaustic = [
    [x - dropRadius * 0.35, yEnd + dropRadius * 0.05],
    [x, yEnd + dropRadius * 0.42],
    [x + dropRadius * 0.42, yEnd + dropRadius * 0.08],
    [x + dropRadius * 0.1, yEnd - dropRadius * 0.22]
  ];
  setWashOnly(PAL.blushMid, 225);
  drawPoly(hotCaustic, 0.2);

  // Watercolor ruby glaze to fuse the drip top seamlessly into the wet rind
  let topGlaze = [
    [x - headWidth * 0.65, yStart - 10],
    [x - dropRadius * 0.4, lerp(yStart, neckY, 0.6)],
    [x + dropRadius * 0.4, lerp(yStart, neckY, 0.6)],
    [x + headWidth * 0.65, yStart - 10]
  ];
  setFillOnly(PAL.rubyMid, 120, 0.22, "out", 0.5, 0.4);
  drawPoly(topGlaze);

  // Crisp pure-white wet specular reflections along the left flank of the rivulet & drop
  setWashOnly(PAL.specPure, 250);
  let dropSpec = [
    [x - dropRadius * 0.58, yEnd - dropRadius * 0.85],
    [x - dropRadius * 0.78, yEnd - dropRadius * 0.35],
    [x - dropRadius * 0.52, yEnd + dropRadius * 0.12],
    [x - dropRadius * 0.42, yEnd - dropRadius * 0.35]
  ];
  drawPoly(dropSpec);

  setStrokeOnly("rotring", PAL.specPure, 0.6);
  brush.line(x - headWidth * 0.15, yStart + 6, x - dropRadius * 0.16, neckY - 4);
  brush.line(x - dropRadius * 0.55, yEnd - dropRadius * 0.85, x - dropRadius * 0.74, yEnd - dropRadius * 0.3);
  brush.line(x - dropRadius * 0.74, yEnd - dropRadius * 0.3, x - dropRadius * 0.48, yEnd + dropRadius * 0.15);

  // Secondary pinpoint glint on lower right rim of drop
  brush.line(x + dropRadius * 0.52, yEnd + dropRadius * 0.18, x + dropRadius * 0.62, yEnd + dropRadius * 0.02);
}

function drawDetachedBead(x, y, r) {
  // Shadow
  let sh = [];
  for (let a = 0; a < 360; a += 30) sh.push([x + 2 + r * sin(a), y + 3 - r * 1.15 * cos(a)]);
  setWashOnly("#020001", 210);
  drawPoly(sh);

  // Ruby body
  let body = [];
  for (let a = 0; a < 360; a += 24) body.push([x + r * sin(a), y - r * 1.15 * cos(a)]);
  setWashOnly(PAL.madderBright, 235);
  drawPoly(body);

  // Coral caustic bottom
  let glow = [];
  for (let a = 90; a <= 270; a += 30) glow.push([x + r * 0.72 * sin(a), y + r * 0.15 - r * 0.72 * cos(a)]);
  setWashOnly(PAL.coralLight, 235);
  drawPoly(glow);

  // Specular dot
  setStrokeOnly("rotring", PAL.specPure, 0.65);
  brush.line(x - r * 0.42, y - r * 0.45, x - r * 0.25, y - r * 0.15);
}

function drawAsymmetricJuiceDrips() {
  // Located on the bottom-right rim of the grapefruit (phi = 132° to 170°),
  // spilling over the creamy pith and coral rind onto the lacquered black ground.
  let aStart = 132;
