  // 1. Translucent Rose-Madder & Coral juice film wetting the pith & rind along this arc
  let wetFilmPoly = [];
  for (let a = aStart; a <= aEnd; a += 3) {
    wetFilmPoly.push(ptRight(fruitRadius(292, a), a));
  }
  for (let a = aEnd; a >= aStart; a -= 3) {
