  let innerWetFilm = [];
  for (let a = aStart + 4; a <= aEnd - 4; a += 3) {
    innerWetFilm.push(ptRight(fruitRadius(312, a), a));
  }
  for (let a = aEnd - 4; a >= aStart + 4; a -= 3) {
    let swell = 18 * pow(sin(map(a, aStart, aEnd, 0, 180)), 2);
    innerWetFilm.push(ptRight(fruitRadius(372 + swell, a), a));
  }
  setFillOnly(PAL.madderBright, 115, 0.22, "in", 0.5, 0.45);
  drawPoly(innerWetFilm);

  // 2. Three distinct vertical juice drips breaking the Art Deco sunburst symmetry
  // Primary long drip at phi ≈ 154° (x ≈ 761, y ≈ 897)
  let pMain = ptRight(fruitRadius(368, 154), 154);
  drawSingleJuiceDrip(pMain[0], pMain[1] - 6, pMain[1] + 178, 34, 15.5);
  drawDetachedBead(pMain[0] + 1, pMain[1] + 212, 6.8);
  drawDetachedBead(pMain[0] + 1.5, pMain[1] + 232, 3.2);

  // Secondary mid-length drip at phi ≈ 140° (x ≈ 835, y ≈ 847)
  let pSec = ptRight(fruitRadius(368, 140), 140);
  drawSingleJuiceDrip(pSec[0], pSec[1] - 8, pSec[1] + 112, 24, 11.5);
  drawDetachedBead(pSec[0], pSec[1] + 138, 4.5);

  // Third short swelling pendant bead at phi ≈ 166° (x ≈ 689, y ≈ 922)
  let pThird = ptRight(fruitRadius(368, 166), 166);
  drawSingleJuiceDrip(pThird[0], pThird[1] - 5, pThird[1] + 54, 26, 10.5);

  // Wet specular meniscus arcs along the dripping rim
  setStrokeOnly("rotring", PAL.specPure, 0.62);
  for (let a = aStart + 3; a < aEnd - 3; a += 4.5) {
    let g1 = ptRight(fruitRadius(367, a), a);
    let g2 = ptRight(fruitRadius(369, a + 2.5), a + 2.5);
    brush.line(g1[0], g1[1], g2[0], g2[1]);
  }
}

