// ============================================================================
// GEOMETRY & POLYGON CLIPPING ENGINE FOR VENEERS
// ============================================================================

function lerpPt(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

function distPt(a, b) {
  return Math.hypot(b[0] - a[0], b[1] - a[1]);
}

function polyCentroid(pts) {
  let sx = 0, sy = 0, a = 0;
  let n = pts.length;
  for (let i = 0; i < n; i++) {
    let p0 = pts[i], p1 = pts[(i + 1) % n];
    let cross = p0[0] * p1[1] - p1[0] * p0[1];
    a += cross;
    sx += (p0[0] + p1[0]) * cross;
    sy += (p0[1] + p1[1]) * cross;
  }
  if (Math.abs(a) < 1e-4) {
    sx = 0; sy = 0;
    for (let p of pts) { sx += p[0]; sy += p[1]; }
    return [sx / n, sy / n];
  }
  a *= 3;
  return [sx / a, sy / a];
}

function polyBounds(pts) {
  let minX = 1e9, minY = 1e9, maxX = -1e9, maxY = -1e9;
  for (let p of pts) {
    if (p[0] < minX) minX = p[0];
    if (p[1] < minY) minY = p[1];
    if (p[0] > maxX) maxX = p[0];
    if (p[1] > maxY) maxY = p[1];
  }
  return { minX, minY, maxX, maxY, w: maxX - minX, h: maxY - minY };
}

function subdividePoly(pts, maxSeg = 9) {
  let out = [];
  let n = pts.length;
  for (let i = 0; i < n; i++) {
    let a = pts[i], b = pts[(i + 1) % n];
    let d = distPt(a, b);
    let steps = Math.max(1, Math.ceil(d / maxSeg));
    for (let s = 0; s < steps; s++) {
      out.push(lerpPt(a, b, s / steps));
    }
  }
  return out;
}

function chaikinClosed(pts, iterations = 2) {
  let curr = pts;
  for (let it = 0; it < iterations; it++) {
    let next = [];
    let n = curr.length;
    for (let i = 0; i < n; i++) {
      let p0 = curr[i], p1 = curr[(i + 1) % n];
      next.push([0.75 * p0[0] + 0.25 * p1[0], 0.75 * p0[1] + 0.25 * p1[1]]);
      next.push([0.25 * p0[0] + 0.75 * p1[0], 0.25 * p0[1] + 0.75 * p1[1]]);
    }
    curr = next;
  }
  return subdividePoly(curr, 9);
}

function evalCatmullChain(ctrlPts, samplesPerSeg = 12) {
  if (ctrlPts.length < 2) return ctrlPts.slice();
  if (ctrlPts.length === 2) {
    let res = [];
    for (let i = 0; i <= samplesPerSeg; i++) res.push(lerpPt(ctrlPts[0], ctrlPts[1], i / samplesPerSeg));
    return res;
  }
  let pts = [ctrlPts[0], ...ctrlPts, ctrlPts[ctrlPts.length - 1]];
  let out = [];
  for (let i = 1; i < pts.length - 2; i++) {
    let p0 = pts[i - 1], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2];
    let count = (i === pts.length - 3) ? samplesPerSeg : samplesPerSeg - 1;
    for (let j = 0; j < count; j++) {
      let t = (i === pts.length - 3) ? j / (samplesPerSeg - 1) : j / samplesPerSeg;
      let t2 = t * t, t3 = t2 * t;
      let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
      let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);
      out.push([x, y]);
    }
  }
  return out;
}

function sampleChainAt(chain, t) {
  if (t <= 0) return chain[0].slice();
  if (t >= 1) return chain[chain.length - 1].slice();
  let idx = t * (chain.length - 1);
  let i0 = Math.floor(idx);
  let f = idx - i0;
  return lerpPt(chain[i0], chain[Math.min(chain.length - 1, i0 + 1)], f);
}

// Build a seamless veneer patch between two shared contour chains cTop and cBot
// for parameter interval [t0, t1], with curved cross-cut seams at t0 and t1
function buildRibbonPatch(cTop, cBot, t0, t1, bowLeft = 0, bowRight = 0, stepsU = 18, stepsV = 10) {
  let pts = [];
  // Top edge: t0 -> t1
  for (let i = 0; i <= stepsU; i++) {
    let t = t0 + (t1 - t0) * (i / stepsU);
    pts.push(sampleChainAt(cTop, t));
  }
  // Right edge: cTop(t1) -> cBot(t1) with optional bow along ribbon tangent
  let pTR = sampleChainAt(cTop, t1);
  let pBR = sampleChainAt(cBot, t1);
  let pTRprev = sampleChainAt(cTop, Math.max(0, t1 - 0.04));
  let pBRprev = sampleChainAt(cBot, Math.max(0, t1 - 0.04));
  let txR = ((pTR[0] - pTRprev[0]) + (pBR[0] - pBRprev[0])) * 0.5;
  let tyR = ((pTR[1] - pTRprev[1]) + (pBR[1] - pBRprev[1])) * 0.5;
  let tLenR = Math.hypot(txR, tyR) || 1;
  txR /= tLenR; tyR /= tLenR;
  let spanR = distPt(pTR, pBR);
  for (let j = 1; j < stepsV; j++) {
    let s = j / stepsV;
    let base = lerpPt(pTR, pBR, s);
    let offset = Math.sin(s * Math.PI) * bowRight * spanR;
    pts.push([base[0] + txR * offset, base[1] + tyR * offset]);
  }
  // Bottom edge: t1 -> t0
  for (let i = stepsU; i >= 0; i--) {
    let t = t0 + (t1 - t0) * (i / stepsU);
    pts.push(sampleChainAt(cBot, t));
  }
  // Left edge: cBot(t0) -> cTop(t0) with matching bowLeft
  let pTL = sampleChainAt(cTop, t0);
  let pBL = sampleChainAt(cBot, t0);
  let pTLnext = sampleChainAt(cTop, Math.min(1, t0 + 0.04));
  let pBLnext = sampleChainAt(cBot, Math.min(1, t0 + 0.04));
  let txL = ((pTLnext[0] - pTL[0]) + (pBLnext[0] - pBL[0])) * 0.5;
  let tyL = ((pTLnext[1] - pTL[1]) + (pBLnext[1] - pBL[1])) * 0.5;
  let tLenL = Math.hypot(txL, tyL) || 1;
  txL /= tLenL; tyL /= tLenL;
  let spanL = distPt(pTL, pBL);
  for (let j = stepsV - 1; j >= 1; j--) {
    let s = j / stepsV;
    let base = lerpPt(pTL, pBL, s);
    let offset = Math.sin(s * Math.PI) * bowLeft * spanL;
    pts.push([base[0] + txL * offset, base[1] + tyL * offset]);
  }
  return subdividePoly(pts, 9);
}

function pointInPoly(pt, poly) {
  let x = pt[0], y = pt[1];
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / ((yj - yi) || 1e-9) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// Clip a polyline strictly inside an arbitrary polygon (convex or concave)
function clipPolylineToPoly(linePts, poly) {
  let segments = [];
  let current = [];
  for (let i = 0; i < linePts.length; i++) {
    let p = linePts[i];
    let inCurr = pointInPoly(p, poly);
    if (i > 0) {
      let prev = linePts[i - 1];
      let inPrev = pointInPoly(prev, poly);
      if (inCurr !== inPrev) {
        let a = inPrev ? prev : p;
        let b = inPrev ? p : prev;
        for (let k = 0; k < 5; k++) {
          let m = lerpPt(a, b, 0.5);
          if (pointInPoly(m, poly)) a = m;
          else b = m;
        }
        let crossPt = lerpPt(a, b, 0.5);
        if (inCurr) {
          current = [crossPt, p];
        } else {
          current.push(crossPt);
          if (current.length >= 2) segments.push(current);
          current = [];
        }
        continue;
      }
    }
    if (inCurr) {
      current.push(p);
    }
  }
  if (current.length >= 2) segments.push(current);
  return segments;
}

// Sutherland-Hodgman half-plane clip in sheared meniscus space for hot-sand scorching
// Keeps points where sheared v >= vMin (and optionally <= vMax)
function clipPolyShearedBand(poly, cx, cy, R, angleDeg, curvature, vMin, vMax = 1e9) {
  let rad = angleDeg * Math.PI / 180;
  let ca = Math.cos(rad), sa = Math.sin(rad);
  let invR = 1 / Math.max(12, R);

  function toSheared(p) {
    let dx = (p[0] - cx) * invR;
    let dy = (p[1] - cy) * invR;
    let u = -dx * sa + dy * ca;
    let v = dx * ca + dy * sa;
    return [u, v + curvature * u * u];
  }

  function fromSheared(uv) {
    let u = uv[0];
    let v = uv[1] - curvature * u * u;
    let dx = (v * ca - u * sa) * R;
    let dy = (v * sa + u * ca) * R;
    return [cx + dx, cy + dy];
  }

  let sPts = poly.map(toSheared);

  function clipHalf(pts, threshold, keepGreater) {
    if (pts.length < 3) return [];
    let out = [];
    for (let i = 0; i < pts.length; i++) {
      let cur = pts[i];
      let prev = pts[(i + pts.length - 1) % pts.length];
      let curIn = keepGreater ? (cur[1] >= threshold) : (cur[1] <= threshold);
      let prevIn = keepGreater ? (prev[1] >= threshold) : (prev[1] <= threshold);
      if (curIn !== prevIn) {
        let t = (threshold - prev[1]) / ((cur[1] - prev[1]) || 1e-9);
        out.push(lerpPt(prev, cur, t));
      }
      if (curIn) out.push(cur);
    }
    return out;
  }

  let clipped = clipHalf(sPts, vMin, true);
  if (vMax < 1e8 && clipped.length >= 3) {
    clipped = clipHalf(clipped, vMax, false);
  }
  if (clipped.length < 3) return [];
  return clipped.map(fromSheared);
}

// Inset polygon toward centroid for soft rim scorching or highlight bevels
function insetPoly(poly, amountPx) {
  let c = polyCentroid(poly);
  let out = [];
  for (let p of poly) {
    let dx = c[0] - p[0], dy = c[1] - p[1];
    let d = Math.hypot(dx, dy) || 1;
    let step = Math.min(d * 0.75, amountPx);
    out.push([p[0] + (dx / d) * step, p[1] + (dy / d) * step]);
  }
  return out;
}

function drawPolyShape(pts, curvature = 0) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function drawOpenPath(pts, brushName, col, weight) {
  if (!pts || pts.length < 2) return;
  brush.set(brushName, col, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
    return;
  }
  // Sample down slightly for brush.spline efficiency while preserving smooth curves
  let sampled = [pts[0]];
  let step = Math.max(1, Math.floor(pts.length / 10));
  for (let i = step; i < pts.length - 1; i += step) {
    sampled.push(pts[i]);
  }
  sampled.push(pts[pts.length - 1]);
  if (sampled.length >= 3) {
    brush.spline(sampled, 0.35);
  } else {
    brush.line(sampled[0][0], sampled[0][1], sampled[1][0], sampled[1][1]);
  }
}

