function renderVeneerPiece(opts) {
  let poly = opts.poly;
  if (!poly || poly.length < 3) return;
  let pal = WOOD_PALETTES[opts.wood] || WOOD_PALETTES.mapleGolden;
  let c = polyCentroid(poly);
  let b = polyBounds(poly);
  let R = Math.max(16, Math.hypot(b.w, b.h) * 0.5);

  let grainAngle = opts.grainAngle ?? 0;
  let scorchAngle = opts.scorchAngle ?? (grainAngle + 90);
  let scorchDepth = opts.scorchDepth ?? 0.45; // 0..1
  let scorchCurve = opts.scorchCurve ?? 0.35;
  let chatoyancePos = opts.chatoyancePos ?? -0.22;

  brush.noField();
  brush.noStroke();
  brush.noHatch();

  // 1. Base Wood Veneer Wash
  brush.wash(pal.base, 245);
  drawPolyShape(poly, 0);

  // Optional watercolor texture pass on major hero pieces
  if (opts.richTexture) {
    brush.fillBleed(0.015, "in");
    brush.fillTexture(0.42, 0.25);
    brush.fill(pal.tone, 65);
    drawPolyShape(poly, 0);
    brush.noFill();
  } else {
    let innerTone = insetPoly(poly, Math.min(8, R * 0.12));
    brush.wash(pal.tone, 70);
    drawPolyShape(innerTone, 0);
  }

  // 2. Chatoyance / Silky Wood Lustre Band (sheared band clip)
  if (opts.chatoyance !== false) {
    let band1 = clipPolyShearedBand(poly, c[0], c[1], R, scorchAngle, -scorchCurve * 0.6, chatoyancePos - 0.30, chatoyancePos + 0.22);
    if (band1.length >= 3) {
      brush.wash(pal.chatoyance, 38);
      drawPolyShape(band1, 0);
    }
    let band2 = clipPolyShearedBand(poly, c[0], c[1], R, scorchAngle, -scorchCurve * 0.6, chatoyancePos - 0.14, chatoyancePos + 0.08);
    if (band2.length >= 3) {
      brush.wash(pal.chatoyance, 45);
      drawPolyShape(band2, 0);
    }
  }

  // 3. Hot-Sand Scorching (Progressive Meniscus Layers)
  if (scorchDepth > 0.02) {
    let startV = 0.85 - scorchDepth * 1.45;
    let steps = [
      { v: startV, col: pal.scorch1, alpha: 34 },
      { v: startV + scorchDepth * 0.22, col: pal.scorch1, alpha: 42 },
      { v: startV + scorchDepth * 0.44, col: pal.scorch2, alpha: 48 },
      { v: startV + scorchDepth * 0.64, col: pal.scorch2, alpha: 54 },
      { v: startV + scorchDepth * 0.82, col: pal.scorch3, alpha: 62 },
      { v: startV + scorchDepth * 0.96, col: pal.scorch3, alpha: 70 }
    ];
    for (let st of steps) {
      let sPoly = clipPolyShearedBand(poly, c[0], c[1], R, scorchAngle, scorchCurve, st.v);
      if (sPoly.length >= 3) {
        brush.wash(st.col, st.alpha);
        drawPolyShape(sPoly, 0);
      }
    }
  }

  // Optional Secondary Edge Scorch (for crevices & multi-sided shadow pockets)
  if (opts.scorchAngle2 !== undefined) {
    let sd2 = opts.scorchDepth2 ?? 0.35;
    let sv2 = 0.85 - sd2 * 1.35;
    let steps2 = [
      { v: sv2, col: pal.scorch1, alpha: 35 },
      { v: sv2 + sd2 * 0.45, col: pal.scorch2, alpha: 48 },
      { v: sv2 + sd2 * 0.80, col: pal.scorch3, alpha: 58 }
    ];
    for (let st of steps2) {
      let sPoly2 = clipPolyShearedBand(poly, c[0], c[1], R, opts.scorchAngle2, 0.3, st.v);
      if (sPoly2.length >= 3) {
        brush.wash(st.col, st.alpha);
        drawPolyShape(sPoly2, 0);
      }
    }
  }

  brush.noWash();

  // 4. Directional Wood Grain Lines Clipped Strictly to Veneer Polygon
  renderWoodGrainInPoly(poly, c, R, pal, grainAngle, scorchAngle, scorchDepth, opts);

  // 5. Sand-Scorch Pore Stipple Near Shadow Edge
  if (scorchDepth > 0.2 && R > 22) {
    let deepScorchPoly = clipPolyShearedBand(poly, c[0], c[1], R, scorchAngle, scorchCurve, 0.85 - scorchDepth * 0.65);
    if (deepScorchPoly.length >= 4) {
      let sc = polyCentroid(deepScorchPoly);
      let nDots = Math.min(10, Math.max(2, Math.floor(R / 16)));
      brush.set("scorchDust", pal.scorch3, 0.55);
      for (let i = 0; i < nDots; i++) {
        let vPt = deepScorchPoly[(i * 3) % deepScorchPoly.length];
        let pA = lerpPt(sc, vPt, 0.35);
        let pB = lerpPt(sc, vPt, 0.78);
        brush.line(pA[0], pA[1], pB[0], pB[1]);
      }
    }
  }
}

function renderWoodGrainInPoly(poly, c, R, pal, grainAngle, scorchAngle, scorchDepth, opts) {
  let gRad = grainAngle * Math.PI / 180;
  let ca = Math.cos(gRad), sa = Math.sin(gRad);
  let pa = -sa, pb = ca; // perpendicular to grain

  let sRad = scorchAngle * Math.PI / 180;
  let sca = Math.cos(sRad), ssa = Math.sin(sRad);

  let spacing = opts.grainSpacing ?? (pal.type === "boxwood" ? 4.2 : pal.type === "sycamore" ? 5.2 : 5.6);
  let numLines = Math.ceil((R * 2.1) / spacing);
  let sampleStep = 7;
  let stepsAlong = Math.ceil((R * 2.2) / sampleStep);

  // Knot / cathedral focal offset inside piece
  let knotU = (opts.knotU ?? 0.15) * R;
  let knotV = (opts.knotV ?? 0.0) * R;
  let phaseSeed = ((c[0] * 0.13 + c[1] * 0.29) % 100);

  for (let i = -numLines; i <= numLines; i++) {
    let vBase = i * spacing;
    let rawLine = [];
    for (let j = 0; j <= stepsAlong; j++) {
      let u = -R * 1.1 + (j / stepsAlong) * (R * 2.2);
      let v = vBase;

      if (pal.type === "maple") {
        // Flowing honey-maple cathedral arches & curly waves
        let uRel = (u - knotU) / R;
        let arch = Math.sin((uRel * 1.6 + phaseSeed) * Math.PI) * 5.5 * Math.cos((vBase / R) * 1.4);
        let curl = Math.sin(u * 0.065 + i * 0.45 + phaseSeed) * 2.4;
        v += arch + curl;
      } else if (pal.type === "walnut") {
        // Bold roasted walnut cathedral figure + burl knot deflection
        let du = u - knotU, dv = vBase - knotV;
        let distK = Math.hypot(du * 0.65, dv * 1.25) + 8;
        let burl = (dv / distK) * 18 * Math.exp(-distK / (R * 0.55));
        let wave = Math.sin(u * 0.045 + i * 0.35 + phaseSeed) * 3.8;
        v += burl + wave;
      } else if (pal.type === "sycamore") {
        // Tight straight-to-gently-curved sycamore grain
        let ripple = Math.sin(u * 0.09 + i * 0.2 + phaseSeed) * 1.3;
        v += ripple;
      } else if (pal.type === "rosewood") {
        // Sinuous spiderwebbing rosewood veins
        let vein = Math.sin(u * 0.055 + i * 0.7 + phaseSeed) * 4.5 + Math.cos(u * 0.11 - i * 0.4) * 2.2;
        v += vein;
      } else if (pal.type === "harewood") {
        // Quarter-sawn twilight harewood
        v += Math.sin(u * 0.03 + i * 0.15 + phaseSeed) * 1.6;
      } else {
        // Boxwood / holly fine grain
        v += Math.sin(u * 0.06 + i * 0.3) * 1.1;
      }

      let x = c[0] + u * ca + v * pa;
      let y = c[1] + u * sa + v * pb;
      rawLine.push([x, y]);
    }

    let clippedSegs = clipPolylineToPoly(rawLine, poly);
    for (let seg of clippedSegs) {
      if (seg.length < 2) continue;
      let mid = seg[Math.floor(seg.length / 2)];
      let sCoord = ((mid[0] - c[0]) * sca + (mid[1] - c[1]) * ssa) / R;
      let isScorched = sCoord > (0.55 - scorchDepth * 0.85);

      // Alternating dark grain, deep cathedral heartwood line, and silky light chatoyance line
      if ((Math.abs(i) % 3) === 0) {
        let col = isScorched ? pal.scorch3 : pal.grainDeep;
        let w = (pal.type === "rosewood" ? 0.65 : pal.type === "walnut" ? 0.52 : 0.38);
        drawOpenPath(seg, "woodgrain", col, w);
      } else if ((Math.abs(i) % 3) === 1) {
        let col = isScorched ? pal.grainDeep : pal.grainDark;
        drawOpenPath(seg, "cpencil", col, 0.34);
      } else if (!isScorched) {
        drawOpenPath(seg, "silkray", pal.grainLight, 0.36);
      }
    }
  }

  // Sycamore Fiddleback Cross-Ripples & Medullary Flecks
  if (pal.type === "sycamore" && R > 28) {
    let rippleStep = 16;
    let nRipples = Math.floor((R * 1.8) / rippleStep);
    for (let k = -nRipples; k <= nRipples; k += 2) {
      let uBase = k * rippleStep;
      let rLine = [];
      for (let s = -4; s <= 4; s++) {
        let v = (s / 4) * R * 0.75;
        let u = uBase + Math.sin(v * 0.08 + k) * 3.5;
        rLine.push([c[0] + u * ca + v * pa, c[1] + u * sa + v * pb]);
      }
      let rSegs = clipPolylineToPoly(rLine, poly);
      for (let seg of rSegs) {
        drawOpenPath(seg, "silkray", pal.grainLight, 0.42);
      }
    }
  }
}

// Draw hair-thin dark marquetry joins & micro-bevel edge glints for a piece
function renderVeneerJoin(poly, kerfWeight = 0.48, bevelGlint = true) {
  if (!poly || poly.length < 3) return;
  brush.noField();
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // 1. Subtle micro-bevel glint on edges facing the upper-left twilight glow (-0.65, -0.76)
  if (bevelGlint) {
    let inset = insetPoly(poly, 1.35);
    let litRun = [];
    for (let i = 0; i < inset.length; i++) {
      let a = inset[i], b = inset[(i + 1) % inset.length];
      let dx = b[0] - a[0], dy = b[1] - a[1];
      let len = Math.hypot(dx, dy) || 1;
      // Outward normal for clockwise/counterclockwise tested against centroid
      let nx = dy / len, ny = -dx / len;
      let dot = nx * (-0.65) + ny * (-0.76);
      if (dot > 0.32) {
        if (litRun.length === 0) litRun.push(a);
        litRun.push(b);
      } else {
        if (litRun.length >= 2) drawOpenPath(litRun, "silkray", "#f5e3c6", 0.30);
        litRun = [];
      }
    }
    if (litRun.length >= 2) drawOpenPath(litRun, "silkray", "#f5e3c6", 0.30);
  }

  // 2. Dark mastic/saw-kerf join around exact perimeter
  let closed = [...poly, poly[0]];
  drawOpenPath(closed, "cpencil", "#29130a", kerfWeight * 0.95);
  drawOpenPath(closed, "kerf", "#110704", kerfWeight);
}

