function drawBookmatchedBackgroundAndBorder(joinQueue) {
  // 4-Way Bookmatched Twilight Harewood Quadrants meeting at (600, 620)
  let cx = 600, cy = 620;
  let L = 64, R = 1136, T = 64, B = 1136;

  // Subdivide each quadrant into 2 diagonal bookmatched veneer strips
  let bgPieces = [
    // Top-Left quadrant (grain angle -32 deg)
    {
      poly: subdividePoly([[L, T], [cx, T], [cx, 330], [L, 470]], 20),
      wood: "harewoodUpper", grainAngle: -32, scorchAngle: -125, scorchDepth: 0.35, grainSpacing: 6.5
    },
    {
      poly: subdividePoly([[L, 470], [cx, 330], [cx, cy], [L, cy]], 20),
      wood: "harewoodUpper", grainAngle: -32, scorchAngle: 110, scorchDepth: 0.30, grainSpacing: 6.5
    },
    // Top-Right quadrant (grain angle +32 deg — bookmatched mirror!)
    {
      poly: subdividePoly([[cx, T], [R, T], [R, 470], [cx, 330]], 20),
      wood: "harewoodUpper", grainAngle: 32, scorchAngle: -55, scorchDepth: 0.38, grainSpacing: 6.5
    },
    {
      poly: subdividePoly([[cx, 330], [R, 470], [R, cy], [cx, cy]], 20),
