  for (let y = sIn; y < 1200 - sIn; y += step) {
    let y2 = Math.min(1200 - sIn, y + step);
    let pLeft = [[sOut, y], [sIn, y], [sIn, y2], [sOut, y2]];
    let pRight = [[1200 - sIn, y], [1200 - sOut, y], [1200 - sOut, y2], [1200 - sIn, y2]];
    renderVeneerPiece({ poly: pLeft, wood: woods[idx % 4], grainAngle: 45, scorchAngle: 135, scorchDepth: 0.3, grainSpacing: 5 });
