  }
  // Corner rosettes in boxwood
  let corners = [
    [[sOut, sOut], [sIn, sOut], [sIn, sIn], [sOut, sIn]],
    [[1200 - sIn, sOut], [1200 - sOut, sOut], [1200 - sOut, sIn], [1200 - sIn, sIn]],
    [[sOut, 1200 - sIn], [sIn, 1200 - sIn], [sIn, 1200 - sOut], [sOut, 1200 - sOut]],
    [[1200 - sIn, 1200 - sIn], [1200 - sOut, 1200 - sIn], [1200 - sOut, 1200 - sOut], [1200 - sIn, 1200 - sOut]]
