    joinQueue.push({ poly: cPoly, weight: 0.45, glint: true });
  }
}

// Generate the chamfered-oval carving platter boundary point at angle theta (degrees)
function platterRingPt(thetaDeg, scaleRx, scaleRy, cx = 600, cy = 678, tiltDeg = -5.5) {
  let rad = thetaDeg * Math.PI / 180;
  let ct = Math.cos(rad), st = Math.sin(rad);
  // Subtle superellipse / sculpted handle fullness at left and right ends
  let handleBulge = 1 + 0.055 * Math.pow(Math.cos(rad), 6) - 0.025 * Math.pow(Math.sin(2 * rad), 2);
  let lx = ct * scaleRx * handleBulge;
  let ly = st * scaleRy * (1 - 0.02 * Math.pow(ct, 4));
  let tRad = tiltDeg * Math.PI / 180;
  let ca = Math.cos(tRad), sa = Math.sin(tRad);
  return [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];
}

function drawCarvingPlatter(joinQueue) {
  let Rx = 492, Ry = 258;

  // 1. Cast Shadow Veneers on the Table Under the Platter (Bog Oak Inlays)
  let shadowSegs = 6;
  for (let i = 0; i < shadowSegs; i++) {
    let a0 = -8 + (196 / shadowSegs) * i;
    let a1 = -8 + (196 / shadowSegs) * (i + 1);
    let sPoly = [];
    for (let s = 0; s <= 8; s++) {
      let a = a0 + (a1 - a0) * (s / 8);
      let p = platterRingPt(a, Rx * 1.0, Ry * 1.0);
      sPoly.push([p[0] + 10, p[1] + 34]);
    }
    for (let s = 8; s >= 0; s--) {
      let a = a0 + (a1 - a0) * (s / 8);
      let p = platterRingPt(a, Rx * 1.04, Ry * 1.09);
      sPoly.push([p[0] + 28, p[1] + 74]);
    }
    let subS = subdividePoly(sPoly, 12);
    renderVeneerPiece({
      poly: subS, wood: "bogOakShadow",
      grainAngle: -12 + i * 5, scorchAngle: -90,
      scorchDepth: 0.65, grainSpacing: 5.5, chatoyance: false
    });
    joinQueue.push({ poly: subS, weight: 0.44, glint: false });
  }

  // 2. Platter 3D Side Skirt / Bevelled Rim (visible around front & sides: -12 deg to 192 deg)
  let skirtFacets = 9;
  for (let i = 0; i < skirtFacets; i++) {
    let a0 = -12 + (204 / skirtFacets) * i;
    let a1 = -12 + (204 / skirtFacets) * (i + 1);
    let fPoly = [];
    for (let s = 0; s <= 7; s++) {
      let a = a0 + (a1 - a0) * (s / 7);
      fPoly.push(platterRingPt(a, Rx, Ry));
    }
    for (let s = 7; s >= 0; s--) {
      let a = a0 + (a1 - a0) * (s / 7);
      let pTop = platterRingPt(a, Rx * 0.992, Ry * 0.992);
      let depthDrop = 22 + 24 * Math.max(0, Math.sin(a * Math.PI / 180));
      fPoly.push([pTop[0] + 2, pTop[1] + depthDrop]);
    }
    let subF = subdividePoly(fPoly, 9);
    let isRightSide = i >= 5;
    renderVeneerPiece({
      poly: subF,
      wood: isRightSide ? "boardRimWalnut" : (i <= 2 ? "sycamoreDusk" : "sycamoreGroove"),
      grainAngle: 82 - i * 3,
      scorchAngle: isRightSide ? 35 : 85,
      scorchDepth: isRightSide ? 0.62 : 0.45,
      grainSpacing: 4.8
    });
    joinQueue.push({ poly: subF, weight: 0.50, glint: true });
  }

  // 3. Top Face Center Platform — 6 Wide Bookmatched Pale Sycamore Planks
  // Clipped inside the inner juice-groove boundary (r = 0.805)
  let innerBoundary = [];
  for (let a = 0; a < 360; a += 3) {
    innerBoundary.push(platterRingPt(a, Rx * 0.805, Ry * 0.805));
  }
  let pb = polyBounds(innerBoundary);
  let pCx = 600, pCy = 678;
  let plankBands = [-1.0, -0.60, -0.22, 0.14, 0.48, 0.78, 1.02];
  let sycWoods = ["sycamoreLight", "sycamoreMid", "sycamoreLight", "sycamoreMid", "sycamoreDusk", "sycamoreMid"];

  for (let i = 0; i < plankBands.length - 1; i++) {
    let plankPoly = clipPolyShearedBand(
      innerBoundary, pCx, pCy, Ry * 0.805,
      84.5, // perpendicular to -5.5 deg board tilt
      0.015 * ((i % 2 === 0) ? 1 : -1),
      plankBands[i], plankBands[i + 1]
    );
    if (plankPoly.length >= 3) {
      let subP = subdividePoly(plankPoly, 10);
      renderVeneerPiece({
        poly: subP,
        wood: sycWoods[i],
        grainAngle: -5.5 + (i % 2 === 0 ? 1.5 : -1.5),
        scorchAngle: 25 + i * 12,
        scorchDepth: (i >= 2 && i <= 4) ? 0.42 : 0.28,
        scorchCurve: 0.22,
        richTexture: true,
        grainSpacing: 5.0
      });
      joinQueue.push({ poly: subP, weight: 0.44, glint: true });
    }
  }

  // 4. Recessed Juice Groove (Carved Trough Ring: r = 0.805 .. 0.905)
  // Divided into 14 curved bevel veneer segments with hot-sand scorching on the inner wall
  let grooveSegs = 14;
  for (let i = 0; i < grooveSegs; i++) {
    let a0 = (360 / grooveSegs) * i;
    let a1 = (360 / grooveSegs) * (i + 1);
    let gPoly = [];
    for (let s = 0; s <= 7; s++) {
      let a = a0 + (a1 - a0) * (s / 7);
      gPoly.push(platterRingPt(a, Rx * 0.805, Ry * 0.805));
    }
    for (let s = 7; s >= 0; s--) {
      let a = a0 + (a1 - a0) * (s / 7);
      gPoly.push(platterRingPt(a, Rx * 0.905, Ry * 0.905));
    }
    let subG = subdividePoly(gPoly, 8);
    let midA = (a0 + a1) * 0.5;
    // Inner slope of top-left groove is in shadow; outer slope of bottom-right is in shadow
    let isUpperHalf = (midA > 175 && midA < 355);
    renderVeneerPiece({
      poly: subG,
      wood: isUpperHalf ? "sycamoreGroove" : "sycamoreDusk",
      grainAngle: midA + 88,
      scorchAngle: isUpperHalf ? (midA + 180) : midA,
      scorchDepth: 0.58,
      scorchCurve: 0.18,
      grainSpacing: 4.5
    });
    joinQueue.push({ poly: subG, weight: 0.46, glint: true });
  }

  // 5. Outer Raised Platter Lip Ring (r = 0.905 .. 1.00)
  // Divided into 12 curved pale sycamore segments with warm end-handle inlays
  let rimSegs = 12;
  for (let i = 0; i < rimSegs; i++) {
    let a0 = (360 / rimSegs) * i - 15;
    let a1 = (360 / rimSegs) * (i + 1) - 15;
    let rPoly = [];
    for (let s = 0; s <= 8; s++) {
      let a = a0 + (a1 - a0) * (s / 8);
      rPoly.push(platterRingPt(a, Rx * 0.905, Ry * 0.905));
    }
    for (let s = 8; s >= 0; s--) {
      let a = a0 + (a1 - a0) * (s / 8);
      rPoly.push(platterRingPt(a, Rx * 1.00, Ry * 1.00));
    }
    let subR = subdividePoly(rPoly, 8);
    let midA = (a0 + a1) * 0.5;
    let isHandleEnd = (i === 0 || i === 6);
    renderVeneerPiece({
      poly: subR,
      wood: isHandleEnd ? "mapleGolden" : (midA > 15 && midA < 165 ? "sycamoreMid" : "sycamoreLight"),
      grainAngle: isHandleEnd ? 85 : -5.5,
      scorchAngle: midA + 40,
      scorchDepth: 0.34,
      scorchCurve: 0.25,
      grainSpacing: 4.8
    });
    joinQueue.push({ poly: subR, weight: 0.48, glint: true });
  }
}

