  // Lemon Creamy Pith Face (Boxwood ellipse)
  let lemonPith = [];
  for (let a = 0; a < 360; a += 15) {
    let ar = (a - 8) * Math.PI / 180;
    lemonPith.push([lCx + Math.cos(ar) * lRx, lCy + Math.sin(ar) * lRy * 0.78]);
  }
  let subPith = chaikinClosed(lemonPith, 1);
  renderVeneerPiece({
    poly: subPith, wood: "boxwoodGarlic",
