    { cx: 496, cy: 706, len: 22, wid: 4.5, ang: 14, wood: "hollyRosemary" },
    { cx: 510, cy: 694, len: 22, wid: 4.5, ang: -32, wood: "hollyRosemary" }
  ];

  for (let hl of herbLeaves) {
    let rad = hl.ang * Math.PI / 180;
    let ca = Math.cos(rad), sa = Math.sin(rad);
    let pts = [
      [hl.cx - hl.len * ca, hl.cy - hl.len * sa],
      [hl.cx - hl.len * 0.25 * ca - hl.wid * sa, hl.cy - hl.len * 0.25 * sa + hl.wid * ca],
      [hl.cx + hl.len * 0.35 * ca - hl.wid * 0.75 * sa, hl.cy + hl.len * 0.35 * sa + hl.wid * 0.75 * ca],
      [hl.cx + hl.len * ca, hl.cy + hl.len * sa],
      [hl.cx + hl.len * 0.35 * ca + hl.wid * 0.75 * sa, hl.cy + hl.len * 0.35 * sa - hl.wid * 0.75 * ca],
      [hl.cx - hl.len * 0.25 * ca + hl.wid * sa, hl.cy - hl.len * 0.25 * sa - hl.wid * ca]
    ];
    let lPoly = chaikinClosed(pts, 1);
    renderVeneerPiece({
      poly: lPoly, wood: hl.wood,
      grainAngle: hl.ang + 25, scorchAngle: hl.ang + 85,
      scorchDepth: 0.50, grainSpacing: 3.5
    });
    joinQueue.push({ poly: lPoly, weight: 0.42, glint: true });

    // Central leaf midrib vein join
    let pA = [hl.cx - hl.len * 0.85 * ca, hl.cy - hl.len * 0.85 * sa];
    let pB = [hl.cx + hl.len * 0.85 * ca, hl.cy + hl.len * 0.85 * sa];
    drawOpenPath([pA, pB], "kerf", "#182114", 0.35);
  }
}

