// ============================================================================
// HELPERS FOR P5.BRUSH SHAPES & HAND-LETTERED GRAPHITE
// ============================================================================

function fillShape(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function makeEllipsePts(cx, cy, rx, ry, rotDeg = 0, n = 20, irreg = 0) {
  let pts = [];
  let c = cos(rotDeg), s = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let radMod = 1 + (irreg > 0 ? (noise(cx * 0.02 + cos(a), cy * 0.02 + sin(a)) - 0.5) * irreg : 0);
    let lx = cos(a) * rx * radMod;
    let ly = sin(a) * ry * radMod;
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function drawGraphiteText(str, x, y, h, rotDeg = 0, align = "center", col = "#2a2f36", weight = 0.32) {
  let textStr = str.toUpperCase();
  let charW = h * 0.66;
  let tracking = h * 0.24;
  let step = charW + tracking;
  let totalW = textStr.length * step - tracking;

  push();
  translate(x, y);
  if (rotDeg !== 0) rotate(rotDeg);

  let startX = 0;
  if (align === "center") startX = -totalW / 2;
  else if (align === "right") startX = -totalW;

  let startY = -h / 2;

  // Faint architectural graphite guideline
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("2H", "#adb4bd", 0.16);
  brush.line(startX - 3, startY + h + 1, startX + totalW + 3, startY + h + 1);

  brush.set("HB", col, weight);
  for (let i = 0; i < textStr.length; i++) {
    let ch = textStr[i];
    let gx = startX + i * step;
    let gy = startY;
    let strokes = GLYPHS[ch];
    if (!strokes) continue;

    for (let s = 0; s < strokes.length; s++) {
      let path = strokes[s];
      for (let k = 0; k < path.length - 1; k++) {
        let x1 = gx + path[k][0] * charW + random(-0.25, 0.25);
        let y1 = gy + path[k][1] * h + random(-0.25, 0.25);
        let x2 = gx + path[k + 1][0] * charW + random(-0.25, 0.25);
        let y2 = gy + path[k + 1][1] * h + random(-0.25, 0.25);
        brush.line(x1, y1, x2, y2);
      }
    }
  }
  pop();
}

