function drawDidacticChartGeometry() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();

  // Concentric reference rings in fine graphite and technical pen
  brush.set("2H", "#9aa2ad", 0.32);
  brush.circle(CX, CY, 536, 0.005); // Outer label boundary
  brush.circle(CX, CY, 488, 0.005); // Swatch outer track
  brush.circle(CX, CY, 422, 0.005); // Swatch inner track
  brush.circle(CX, CY, R_RING, 0.005); // Main produce datum circle

  brush.set("rotring", "#3a404a", 0.38);
  brush.circle(CX, CY, 226, 0.004); // Inner protractor outer ring
  brush.set("2H", "#7d8590", 0.28);
  brush.circle(CX, CY, 214, 0.004); // Inner protractor tick ring
  brush.circle(CX, CY, 146, 0.004); // Hierarchy band inner ring
  brush.set("rotring", "#22262c", 0.42);
  brush.circle(CX, CY, 52, 0.004);  // Central hub ring
  brush.circle(CX, CY, 12, 0.004);  // Bullseye

  // Protractor degree ticks around r = 214..226
  for (let d = 0; d < 360; d += 5) {
    let a = d - 90;
    let isMajor = (d % 30 === 0);
    let isMid = (d % 15 === 0);
    let r1 = isMajor ? 206 : (isMid ? 211 : 216);
    let r2 = 226;
    brush.set("rotring", isMajor ? "#1e2228" : "#6c7480", isMajor ? 0.42 : 0.24);
    brush.line(CX + cos(a) * r1, CY + sin(a) * r1, CX + cos(a) * r2, CY + sin(a) * r2);
  }

  // Inscribed Primary Triad (Equilateral Triangle: 0°, 120°, 240°)
  let rTri = 206;
  brush.set("rotring", "#262b33", 0.5);
  for (let k = 0; k < 3; k++) {
    let a1 = k * 120 - 90;
    let a2 = ((k + 1) % 3) * 120 - 90;
    brush.line(
      CX + cos(a1) * rTri, CY + sin(a1) * rTri,
      CX + cos(a2) * rTri, CY + sin(a2) * rTri
    );
  }

  // Inscribed Secondary Triad (Dashed Inverted Triangle: 60°, 180°, 300°)
  brush.set("rotring", "#4e5663", 0.36);
  for (let k = 0; k < 3; k++) {
    let a1 = k * 120 + 60 - 90;
    let a2 = ((k + 1) % 3) * 120 + 60 - 90;
    let x1 = CX + cos(a1) * rTri, y1 = CY + sin(a1) * rTri;
    let x2 = CX + cos(a2) * rTri, y2 = CY + sin(a2) * rTri;
    drawDashedLine(x1, y1, x2, y2, 34);
  }

  // 6 Fine Ruled Pen Lines connecting opposite complementary pairs across the center
  for (let i = 0; i < 6; i++) {
    let a = i * 30 - 90;
    let isPrimaryOrSecondary = (i % 2 === 0);

    // Full diameter line across the center from r = 428 to opposite r = 428
    brush.set("rotring", isPrimaryOrSecondary ? "#1b1f24" : "#3b424c", isPrimaryOrSecondary ? 0.52 : 0.36);
    let x1 = CX + cos(a) * 428;
    let y1 = CY + sin(a) * 428;
    let x2 = CX - cos(a) * 428;
    let y2 = CY - sin(a) * 428;
    brush.line(x1, y1, x2, y2);

    // Small perpendicular station caliper ticks at r = R_RING and r = 206
    for (let sgn of [-1, 1]) {
      let ca = cos(a) * sgn, sa = sin(a) * sgn;
      let px = CX + ca * 206, py = CY + sa * 206;
      brush.set("rotring", "#1b1f24", 0.42);
      brush.circle(px, py, 3.5, 0.01);

      // Outer leader extension from produce ring to swatch track (r = 398..426)
      let lx1 = CX + ca * 392, ly1 = CY + sa * 392;
      let lx2 = CX + ca * 428, ly2 = CY + sa * 428;
      brush.line(lx1, ly1, lx2, ly2);
    }
  }
}

function drawDashedLine(x1, y1, x2, y2, steps) {
  for (let i = 0; i < steps; i += 2) {
    let t1 = i / steps;
    let t2 = (i + 1) / steps;
    brush.line(lerp(x1, x2, t1), lerp(y1, y2, t1), lerp(x1, x2, t2), lerp(y1, y2, t2));
  }
}

// ============================================================================
// 3. COMPLEMENTARY TINTED CAST SHADOWS
// ============================================================================

function drawAllComplementaryShadows() {
  // Light from NW (-45°), so shadows cast toward SE (+19, +22)
  const sxOff = 19;
  const syOff = 22;

  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  for (let i = 0; i < 12; i++) {
    let item = ITEMS[i];
    let a = item.deg - 90;
    let px = CX + cos(a) * R_RING + sxOff;
    let py = CY + sin(a) * R_RING + syOff;

    let shPtsOuter = getShadowOutlinePts(i, px, py, 1.08);
    let shPtsCore = getShadowOutlinePts(i, px - 5, py - 5, 0.86);
    let shPtsUmbra = getShadowOutlinePts(i, px - 10, py - 10, 0.62);

    // 1. Luminous complementary watercolor bleed halo
    brush.fill(item.shadowLight, 95);
    brush.fillBleed(0.28, "out");
    brush.fillTexture(0.55, 0.35);
    fillShape(shPtsOuter, 0.4);

    // 2. Deep complementary core watercolor shadow
    brush.fill(item.shadowDark, 145);
    brush.fillBleed(0.14, "out");
    brush.fillTexture(0.45, 0.4);
    fillShape(shPtsCore, 0.38);
    brush.noFill();

    // 3. Tight contact umbra right beneath the produce
    brush.wash(item.shadowUmbra, 175);
    fillShape(shPtsUmbra, 0.35);
    brush.noWash();
  }
}

function getShadowOutlinePts(idx, cx, cy, sc) {
  switch (idx) {
    case 0: // Red Chilli (curved pod)
      return makeEllipsePts(cx, cy, 56 * sc, 21 * sc, -32, 18, 0.08);
    case 1: // Persimmon (plump 4-lobed orb)
      return makeEllipsePts(cx, cy, 43 * sc, 41 * sc, 15, 18, 0.1);
    case 2: // Tangerine + leaf
      return makeEllipsePts(cx + 3, cy, 46 * sc, 42 * sc, -18, 18, 0.06);
    case 3: // Apricot
      return makeEllipsePts(cx, cy, 40 * sc, 43 * sc, 22, 18, 0.06);
    case 4: // Banana (crescent)
      return makeEllipsePts(cx + 2, cy + 4, 60 * sc, 26 * sc, -28, 18, 0.1);
    case 5: // Key Lime + wedge
      return makeEllipsePts(cx, cy, 46 * sc, 38 * sc, 28, 18, 0.08);
    case 6: // Cucumber (elongated cylinder)
      return makeEllipsePts(cx, cy, 62 * sc, 23 * sc, -25, 18, 0.06);
    case 7: // Savoy Cabbage (scalloped rosette)
      return makeEllipsePts(cx, cy, 50 * sc, 49 * sc, 0, 20, 0.14);
    case 8: // Red Cabbage (round dense head)
      return makeEllipsePts(cx, cy, 47 * sc, 46 * sc, 10, 18, 0.08);
    case 9: // Aubergine (club-shaped)
      return makeEllipsePts(cx, cy, 55 * sc, 31 * sc, 35, 18, 0.08);
    case 10: // Beetroot + stems
      return makeEllipsePts(cx - 4, cy - 2, 50 * sc, 39 * sc, -35, 18, 0.1);
    case 11: // Radicchio (oval head)
      return makeEllipsePts(cx, cy, 47 * sc, 41 * sc, -20, 18, 0.1);
  }
}

// ============================================================================
// 4. HYPERREALIST WATERCOLOR PRODUCE RENDERERS (12 SPECIMENS)
// ============================================================================

function drawAllProduceItems() {
  const renderers = [
    drawRedChilli,
    drawPersimmon,
    drawTangerine,
    drawApricot,
    drawBanana,
    drawKeyLime,
    drawCucumber,
    drawSavoyCabbage,
    drawRedCabbage,
    drawAubergine,
    drawBeetroot,
    drawRadicchio
  ];

  for (let i = 0; i < 12; i++) {
    let a = ITEMS[i].deg - 90;
    let px = CX + cos(a) * R_RING;
    let py = CY + sin(a) * R_RING;
    push();
    translate(px, py);
    renderers[i]();
    pop();
  }
}

