  fillShape([[-24, -14], [-14, -22], [-4, -20], [-10, -12], [-22, -8]], 0.35);
  fillShape([[-28, -2], [-24, -6], [-20, 2], [-26, 4]], 0.3);

  // Characteristic 4-lobed woody-olive persimmon calyx on top-left
  const lobes = [
    [[-10, -14], [-28, -26], [-34, -18], [-18, -8]],
    [[-10, -14], [-6, -34], [6, -32], [0, -14]],
