// --- 03. TANGERINE (SECONDARY ORANGE, 60°) ---
function drawTangerine() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();

  // Green citrus leaf tucked behind top-right
  const leafPts = [[4, -24], [24, -42], [50, -44], [38, -24], [16, -16]];
  brush.wash("#1f4d1c", 235);
  fillShape(leafPts, 0.35);
  brush.wash("#427d36", 195);
  fillShape([[6, -24], [24, -40], [46, -42], [26, -28]], 0.35);
  brush.noWash();

  // Oblate tangerine body
  let bodyPts = makeEllipsePts(0, 3, 44, 38, -8, 24, 0.04);
  brush.fill("#f06608", 220);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.5, 0.35);
  fillShape(bodyPts, 0.4);

  // Warm golden-orange sunlit cheek
  brush.fill("#ffad29", 185);
  brush.fillBleed(0.14, "in");
  fillShape(makeEllipsePts(-13, -8, 25, 20, -10, 16, 0.04), 0.4);
  brush.noFill();

  // Deep burnt-sienna shaded crescent
  brush.wash("#802802", 205);
  fillShape([
    [-24, 30], [0, 22], [26, 6], [38, -14],
    [43, 6], [32, 28], [8, 39], [-16, 38]
  ], 0.4);
  brush.wash("#4a1400", 175);
  fillShape([[-6, 36], [18, 28], [36, 10], [28, 30], [6, 39]], 0.38);
  brush.noWash();

  // Hyperrealist dimpled citrus rind pores (oil glands)
  for (let i = 0; i < 135; i++) {
    let rx = random(-38, 38);
    let ry = random(-29, 34);
    if ((rx * rx) / (40 * 40) + ((ry - 3) * (ry - 3)) / (34 * 34) < 0.92) {
      let isLit = (rx + ry < -4);
      brush.set("rotring", isLit ? "#c94904" : "#4f1600", 0.28);
      brush.line(rx, ry, rx + 0.9, ry + 0.6);
      if (isLit && random() < 0.55) {
        brush.set("pen", "#fff6d6", 0.35);
        brush.line(rx - 0.8, ry - 0.8, rx - 0.2, ry - 0.4);
      }
    }
  }

  // Radiating puckered folds at stem button (-4, -22)
  brush.set("cpencil", "#8c2d03", 0.45);
  for (let a = 0; a < 360; a += 40) {
    let r1 = 3, r2 = random(9, 15);
    brush.line(-4 + cos(a) * r1, -20 + sin(a) * r1 * 0.6, -4 + cos(a) * r2, -20 + sin(a) * r2 * 0.6);
  }
  brush.noStroke();
  brush.wash("#3b4a1c", 235);
  brush.circle(-4, -20, 4.2, 0.05);
  brush.noWash();

  // Leaf midrib
  brush.set("cpencil", "#88bd68", 0.45);
  brush.spline([[6, -23], [26, -34], [48, -43]], 0.3);
}

