  brush.noMass();

  // Whole lime with mammillate nipple at top-left and bottom-right
  const limePts = [
    [-38, -22], [-28, -26], [-10, -32], [14, -26], [32, -10],
    [40, 8], [38, 18], [28, 22], [8, 28], [-16, 22],
    [-32, 6], [-36, -12]
