  brush.fill("#66b812", 220);
  brush.fillBleed(0.08, "in");
  brush.fillTexture(0.48, 0.35);
  fillShape(limePts, 0.38);

  // Acid yellow-green sunlit dome
  brush.fill("#c4f536", 190);
  brush.fillBleed(0.14, "in");
  fillShape(makeEllipsePts(-10, -10, 22, 16, 28, 16, 0.04), 0.4);
  brush.noFill();

  // Deep forest-viridian shaded underside
  brush.wash("#194505", 210);
  fillShape([
    [-26, 12], [-4, 14], [20, 8], [36, -2],
    [39, 16], [26, 23], [6, 28], [-18, 22]
  ], 0.38);
  brush.wash("#0b2402", 180);
  fillShape([[-14, 21], [8, 22], [28, 16], [10, 28]], 0.35);

  // Stippled lime rind oil glands
  for (let i = 0; i < 95; i++) {
    let rx = random(-30, 32), ry = random(-24, 20);
    if (rx * rx + ry * ry < 900) {
      let isLit = (rx + ry < 0);
