// ============================================================================
// 5. FLAT MARKER SWATCHES BESIDE EACH ITEM (TEST CHART)
// ============================================================================

function drawAllMarkerSwatches() {
  const rSwatch = 454;

  for (let i = 0; i < 12; i++) {
    let item = ITEMS[i];
    let a = item.deg - 90;
    let sx = CX + cos(a) * rSwatch;
    let sy = CY + sin(a) * rSwatch;

    push();
    translate(sx, sy);
    rotate(item.deg); // Tangential orientation around the ring

    // White test-chart card backing with crisp ruled frame
    brush.noStroke();
    brush.noHatch();
    brush.noMass();
    brush.wash("#f7f8fa", 235);
    brush.rect(-46, -15, 92, 30, "corner");

    // 3 Flat Marker Chips: [0] Mass Hue, [1] Luminous Tint, [2] Complementary Shadow
    const chipX = [-43, -11, 21];
    const chipW = [30, 30, 22];

    for (let c = 0; c < 3; c++) {
      let col = item.swatches[c];
      let cx0 = chipX[c];
      let cw = chipW[c];

      // Flat solid wash + horizontal marker strokes for authentic felt-tip flat plane
      brush.noStroke();
      brush.wash(col, 235);
      brush.rect(cx0, -12, cw, 24, "corner");
      brush.noWash();

      brush.set("marker", col, 0.95);
      brush.line(cx0 + 2, -7, cx0 + cw - 2, -7);
      brush.line(cx0 + 2, 0, cx0 + cw - 2, 0);
      brush.line(cx0 + 2, 7, cx0 + cw - 2, 7);
    }

    // Fine ruled technical pen dividers & index border
    brush.noFill();
    brush.noWash();
    brush.set("rotring", "#242930", 0.34);
    brush.rect(-46, -15, 92, 30, "corner");
    brush.line(-12, -15, -12, 15);
    brush.line(20, -15, 20, 15);

    // Small registration dot connecting to inner spoke
    brush.circle(0, 15, 2.5, 0.01);
    pop();
  }
}

// ============================================================================
// 6. HAND-LETTERED GRAPHITE LABELS & DIDACTIC MARGINALIA
// ============================================================================

function drawAllGraphiteLabels() {
  for (let i = 0; i < 12; i++) {
    let item = ITEMS[i];
    let a = item.deg - 90;

    //Flip text upside-down in bottom half (120°..240°) so every label reads comfortably
    let flip = (item.deg > 90 && item.deg < 270);
    let textRot = flip ? item.deg + 180 : item.deg;

    // A. INNER HIERARCHY & DEGREE LABELS (r = 180 and r = 162)
    let rTier = 182;
    let rDeg = 162;
    let tx1 = CX + cos(a) * rTier, ty1 = CY + sin(a) * rTier;
    let tx2 = CX + cos(a) * rDeg, ty2 = CY + sin(a) * rDeg;

    let isPrim = (item.tier === "PRIMARY");
    let isSec = (item.tier === "SECONDARY");
    let tierCol = isPrim ? "#14181d" : (isSec ? "#282e36" : "#454d59");
    let tierW = isPrim ? 0.42 : 0.32;

    drawGraphiteText(item.tier, tx1, ty1, 7.2, textRot, "center", tierCol, tierW);
    drawGraphiteText(nf(item.deg, 3) + "° [" + item.code + "]", tx2, ty2, 6.2, textRot, "center", "#525b66", 0.28);

    // B. OUTER SPECIMEN & CHROMATIC LABELS (r = 504 and r = 521)
    let rName = 504;
    let rHue = 521;
    let nx1 = CX + cos(a) * rName, ny1 = CY + sin(a) * rName;
    let nx2 = CX + cos(a) * rHue, ny2 = CY + sin(a) * rHue;

    drawGraphiteText(item.id + ". " + item.name, nx1, ny1, 8.2, textRot, "center", "#1b2026", 0.38);
    drawGraphiteText(item.hueName + " / " + item.latin, nx2, ny2, 6.2, textRot, "center", "#4a525e", 0.28);
  }

  // Central Hub Label
  drawGraphiteText("HUE", CX, CY - 6, 7.5, 0, "center", "#1e2229", 0.38);
  drawGraphiteText("AXIS", CX, CY + 6, 7.5, 0, "center", "#1e2229", 0.38);

  // --- CORNER DIDACTIC BLOCKS ---
  // Top-Left: Plate Title Block
  drawGraphiteText("PLATE XII — CHROMATIC PRODUCE WHEEL", 68, 86, 11.5, 0, "left", "#161a1f", 0.46);
  drawGraphiteText("DIDACTIC TWELVE-PART HUE RING & COMPLEMENTARY SHADOW STUDY", 68, 106, 7.5, 0, "left", "#3e4652", 0.32);
  drawGraphiteText("SPECIMENS 01-12: C. ANNUUM TO C. INTYBUS", 68, 123, 6.8, 0, "left", "#58616e", 0.28);

  // Top-Right: Hierarchy & Swatch Key
