  drawGraphiteText("P.I-III : PRIMARY TRIAD [000 / 120 / 240 DEG]", 1132, 105, 6.8, 0, "right", "#2b313a", 0.3);
  drawGraphiteText("S.I-III : SECONDARY TRIAD [060 / 180 / 300 DEG]", 1132, 121, 6.8, 0, "right", "#3e4652", 0.28);
  drawGraphiteText("T.I-VI  : TERTIARY INTERMEDIATES [30 DEG STEPS]", 1132, 137, 6.8, 0, "right", "#525b66", 0.28);
  drawGraphiteText("SWATCH : [1] MASS HUE  [2] TINT  [3] COMP. SHADOW", 1132, 153, 6.4, 0, "right", "#525b66", 0.26);

  // Bottom-Left: Optical & Shadow Vector Notes
