    brush.line(cx + 2, vy0 + 14, cx + vw - 2, vy0 + 14);
    brush.set("rotring", "#22262c", 0.35);
    brush.noFill();
    brush.rect(cx, vy0, vw, vh, "corner");
  }
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
