// =========================================================================
// GEOMETRY & COORDINATE HELPERS
// =========================================================================

// Lounger local coordinate system (u = across toward pool, v = down along lounger)
// Aligned parallel to the pool coping edge (tilted ~11.31 deg from vertical)
const L_CX = 335;
const L_CY = 575;
const COS_A = 0.9805807;
const SIN_A = 0.1961161;

function L2W(u, v) {
  return [
    L_CX + u * COS_A - v * SIN_A,
    L_CY + u * SIN_A + v * COS_A
  ];
}

// Project a point (u, v) at height z onto the deck along harsh afternoon sun vector
function shadowPt(u, v, z) {
  let p = L2W(u, v);
  return [p[0] + z * 0.82, p[1] + z * 0.56];
}

// Pool water edge X for any canvas Y (corresponds to u = 215.7)
function poolEdgeX(y) {
  return 650 - (y - 100) * 0.20;
}

// Safe polygon drawing via beginShape/vertex/endShape
function drawPoly(pts, curvature = 0.04, closeShape = true) {
  if (!pts || pts.length < 3) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    let dx = pts[i][0] - prev[0];
    let dy = pts[i][1] - prev[1];
    if (dx * dx + dy * dy > 2.2) {
      clean.push(pts[i]);
    }
  }
  if (closeShape && clean.length >= 3) {
    let first = clean[0];
    let last = clean[clean.length - 1];
    if ((first[0] - last[0]) ** 2 + (first[1] - last[1]) ** 2 < 2.2) {
      clean.pop();
    }
  }
  if (clean.length < 3) return;
  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(closeShape);
}

// Safe spline wrapper
function safeSpline(pts, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    let prev = clean[clean.length - 1];
    if ((pts[i][0] - prev[0]) ** 2 + (pts[i][1] - prev[1]) ** 2 > 2.0) {
      clean.push(pts[i]);
    }
  }
  if (clean.length === 2) {
    brush.line(clean[0][0], clean[0][1], clean[1][0], clean[1][1]);
  } else if (clean.length >= 3) {
    brush.spline(clean, curvature);
  }
}

// Local-space quad helper
function localQuad(u1, v1, u2, v2, steps = 4) {
  let pts = [];
  for (let i = 0; i <= steps; i++) pts.push(L2W(lerp(u1, u2, i / steps), v1));
  for (let i = 1; i <= steps; i++) pts.push(L2W(u2, lerp(v1, v2, i / steps)));
  for (let i = 1; i <= steps; i++) pts.push(L2W(lerp(u2, u1, i / steps), v2));
  for (let i = 1; i < steps; i++) pts.push(L2W(u1, lerp(v2, v1, i / steps)));
  return pts;
}

