function drawCausticNetwork() {
  // Build a jittered triangular lattice in pool-floor space (u = 275..920, v = -540..580)
  // and connect triangle circumcenters/centroids to form a seamless 3-valent cellular web
  let cols = 13;
  let rows = 21;
  let uMin = 270, uMax = 920;
  let vMin = -540, vMax = 580;
  let du = (uMax - uMin) / (cols - 1);
  let dv = (vMax - vMin) / (rows - 1);

  let seeds = [];
  for (let r = 0; r < rows; r++) {
    seeds[r] = [];
    for (let c = 0; c < cols; c++) {
      let stagger = (r % 2 === 1) ? du * 0.48 : 0;
      let su = uMin + c * du + stagger + random(-du * 0.28, du * 0.28);
      let sv = vMin + r * dv + random(-dv * 0.28, dv * 0.28);
      seeds[r][c] = [su, sv];
    }
  }

  // Compute centroids of upper and lower triangles in each grid quad
  let nodes = []; // 2D array [r][2*c + t] -> [u, v]
  for (let r = 0; r < rows - 1; r++) {
    nodes[r] = [];
    for (let c = 0; c < cols - 1; c++) {
      let A = seeds[r][c];
      let B = seeds[r][c + 1];
      let C = seeds[r + 1][c];
      let D = seeds[r + 1][c + 1];
      if (r % 2 === 0) {
        nodes[r][2 * c] = [(A[0] + B[0] + C[0]) / 3, (A[1] + B[1] + C[1]) / 3];
        nodes[r][2 * c + 1] = [(B[0] + D[0] + C[0]) / 3, (B[1] + D[1] + C[1]) / 3];
      } else {
        nodes[r][2 * c] = [(A[0] + D[0] + C[0]) / 3, (A[1] + D[1] + C[1]) / 3];
        nodes[r][2 * c + 1] = [(A[0] + B[0] + D[0]) / 3, (A[1] + B[1] + D[1]) / 3];
      }
    }
  }

  // Collect edges of the trivalent caustic mesh
  let edges = [];
  let junctionPts = [];
  for (let r = 0; r < rows - 1; r++) {
    for (let c = 0; c < cols - 1; c++) {
      let n0 = nodes[r][2 * c];
      let n1 = nodes[r][2 * c + 1];
      junctionPts.push(n0, n1);

      // Internal edge between the two triangles in quad (r, c)
      edges.push([n0, n1, seeds[r][c]]);

      if (r % 2 === 0) {
        if (c + 1 < cols - 1) edges.push([n1, nodes[r][2 * (c + 1)], seeds[r][c + 1]]);
        if (r + 1 < rows - 1) edges.push([n1, nodes[r + 1][2 * c], seeds[r + 1][c]]);
      } else {
        if (c + 1 < cols - 1) edges.push([n1, nodes[r][2 * (c + 1)], seeds[r + 1][c + 1]]);
        if (r + 1 < rows - 1) edges.push([n0, nodes[r + 1][2 * c + 1], seeds[r + 1][c]]);
      }
    }
  }

  // PASS A: Dark teal refracted shadow troughs inside cell centers & offset under filaments
  brush.noStroke();
  brush.fill("#044454", 65);
  brush.fillBleed(0.12);
  brush.fillTexture(0.35, 0.25);
  for (let r = 1; r < rows - 1; r += 2) {
    for (let c = 1; c < cols - 1; c += 2) {
      let ctr = seeds[r][c];
      if (ctr[0] < 295) continue;
      let cellPoly = [];
      for (let a = 0; a < 360; a += 60) {
        let rad = 16 + 4 * sin(a * 2 + r * 30);
        cellPoly.push(L2W(ctr[0] + rad * cos(a), ctr[1] + rad * sin(a)));
      }
      drawPoly(cellPoly, 0.25);
    }
  }

  brush.noFill();
  // Dark refracted shadow band shifted slightly toward (-10, -7) under every caustic arc
  for (let i = 0; i < edges.length; i++) {
    let e = edges[i];
    let p1 = e[0], p2 = e[1], s = e[2];
    if (p1[0] < 282 && p2[0] < 282) continue;
    let mu = (p1[0] + p2[0]) * 0.5 + (s[0] - (p1[0] + p2[0]) * 0.5) * 0.14;
    let mv = (p1[1] + p2[1]) * 0.5 + (s[1] - (p1[1] + p2[1]) * 0.5) * 0.14;

    let w1 = L2W(p1[0] - 9, p1[1] - 6);
    let wm = L2W(mu - 9, mv - 6);
    let w2 = L2W(p2[0] - 9, p2[1] - 6);
    brush.set("cpencil", "#043e4f", 0.85);
    safeSpline([w1, wm, w2], 0.45);
  }

  // PASS B: Secondary fine harmonic caustic mesh (smaller scale ripples)
  for (let i = 0; i < edges.length; i++) {
    let e = edges[i];
    let p1 = e[0], p2 = e[1], s = e[2];
    if (p1[0] < 280 && p2[0] < 280) continue;
    // Offset secondary harmonic wave
    let w1 = L2W(p1[0] + 18, p1[1] - 14);
    let wm = L2W((p1[0] + p2[0]) * 0.5 + 15, (p1[1] + p2[1]) * 0.5 - 11);
    let w2 = L2W(p2[0] + 18, p2[1] - 14);
    brush.set("2H", "#45deed", 0.35);
    safeSpline([w1, wm, w2], 0.4);
  }

  // PASS C: Primary Caustic Web - Soft Electric Aqua Halo + Crisp Pencil Core
  for (let i = 0; i < edges.length; i++) {
    let e = edges[i];
    let p1 = e[0], p2 = e[1], s = e[2];
    let minU = min(p1[0], p2[0]);
    if (minU < 236) continue;

    // Pull midpoint slightly toward cell seed so caustic cells look lens-curved
    let mu = (p1[0] + p2[0]) * 0.5 + (s[0] - (p1[0] + p2[0]) * 0.5) * 0.16;
    let mv = (p1[1] + p2[1]) * 0.5 + (s[1] - (p1[1] + p2[1]) * 0.5) * 0.16;

    // If on the vertical wall (236..286), compress u slightly for steep foreshortening
    let w1 = L2W(p1[0], p1[1]);
    let wm = L2W(mu, mv);
    let w2 = L2W(p2[0], p2[1]);

    // Dimmer inside the wall overhang shadow (u < 328), blazing bright in open sunlight (u >= 328)
    if (minU < 328) {
      brush.set("cpencil", "#289eb0", 0.45);
      safeSpline([w1, wm, w2], 0.45);
      brush.set("2H", "#7ae8f5", 0.25);
      safeSpline([w1, wm, w2], 0.45);
    } else {
      // Soft cyan-white bloom
      brush.set("cpencil", "#76f4ff", 0.9);
      safeSpline([w1, wm, w2], 0.45);
      // Crisp bright white pencil core
      brush.set("2H", "#e8ffff", 0.45);
      safeSpline([w1, wm, w2], 0.45);
      brush.set("rotring", "#ffffff", 0.26);
      safeSpline([w1, wm, w2], 0.45);
    }
  }

  // PASS D: Bright Star-Like Focal Nodes at 3-Way Caustic Junctions
  for (let i = 0; i < junctionPts.length; i++) {
    let jp = junctionPts[i];
    if (jp[0] < 328) continue;
    let wp = L2W(jp[0], jp[1]);
    brush.set("cpencil", "#ffffff", 0.7);
    brush.line(wp[0] - 3.5, wp[1] - 1.5, wp[0] + 3.5, wp[1] + 1.5);
    brush.line(wp[0] - 1.5, wp[1] + 3.5, wp[0] + 1.5, wp[1] - 3.5);
  }
}

