    return (v < -65) ? map(v, -65, -330, 48, 92) : 48;
  }

  // 1. Solid central inky shadow cast by the sleeping man's body, straw hat & swim trunks onto the deck
  brush.fill("#0c1626", 225);
  brush.fillBleed(0.04);
  brush.fillTexture(0.35, 0.35);

  let bodyShadow = [
    shadowPt(-45, -245, 84),
    shadowPt(55, -245, 84),
    shadowPt(96, -155, 72),
    shadowPt(92, -95, 56),
    shadowPt(74, 20, 48),
    shadowPt(72, 175, 48),
    shadowPt(65, 310, 48),
    shadowPt(-58, 310, 48),
    shadowPt(-70, 175, 48),
    shadowPt(-95, -15, 50),
    shadowPt(-90, -110, 56),
    shadowPt(-82, -180, 74)
  ];
  drawPoly(bodyShadow, 0.12);

  // 2. Shadow of the Man's Trailing Left Arm across the Concrete Gap & White Coping Stone
  let armDeckShadow = [
    shadowPt(75, -108, 52),
