    L2W(216, -24),
    L2W(216, -2),
    shadowPt(138, -42, 34),
    shadowPt(72, -68, 50)
  ];
  drawPoly(armDeckShadow, 0.1);

  // 3. Barred Ladder-Like Cast Shadows of the 18 Vinyl Straps & Aluminum Frame Rails
