  // we draw the crisp outer frame shadow rails and the individual strap shadow bars!
  brush.fill("#111e33", 210);
  brush.fillBleed(0.02);

  // Left & Right Frame Rail Shadows
  let leftRailSh = [
    shadowPt(-118, -330, frameZ(-330)),
    shadowPt(-106, -330, frameZ(-330)),
    shadowPt(-106, -65, 48),
    shadowPt(-106, 330, 48),
    shadowPt(-118, 330, 48),
    shadowPt(-118, -65, 48)
  ];
  drawPoly(leftRailSh, 0.02);

  let rightRailSh = [
    shadowPt(106, -330, frameZ(-330)),
    shadowPt(118, -330, frameZ(-330)),
    shadowPt(118, -65, 48),
    shadowPt(118, 330, 48),
    shadowPt(106, 330, 48),
    shadowPt(106, -65, 48)
  ];
  drawPoly(rightRailSh, 0.02);

  // Top & Bottom Crossbar Shadows + Folding Leg Shadows
  drawPoly([
    shadowPt(-118, -330, 92), shadowPt(118, -330, 92),
    shadowPt(118, -318, 90), shadowPt(-118, -318, 90)
  ], 0.01);
  drawPoly([
    shadowPt(-118, 318, 48), shadowPt(118, 318, 48),
    shadowPt(118, 330, 48), shadowPt(-118, 330, 48)
  ], 0.01);

  // Diagonal shadows of the tubular legs from deck contact (z=0) to frame rail (z=48..75)
  for (let vLeg of [-240, 240]) {
    let zTop = frameZ(vLeg);
    drawPoly([
      L2W(108, vLeg), L2W(116, vLeg),
      shadowPt(116, vLeg, zTop), shadowPt(108, vLeg, zTop)
    ], 0.01);
    drawPoly([
      L2W(-116, vLeg), L2W(-108, vLeg),
      shadowPt(-108, vLeg, zTop), shadowPt(-116, vLeg, zTop)
    ], 0.01);
  }

  // Individual Horizontal Strap Shadows on the concrete deck & coping stone
  brush.noFill();
  brush.set("marker", "#0f1c2e", 1.35);
  for (let i = 0; i < 18; i++) {
    let vCenter = -300 + i * 35.3;
    let z = frameZ(vCenter);
    let pL = shadowPt(-112, vCenter, z);
    let pR = shadowPt(112, vCenter, z);
    brush.line(pL[0], pL[1], pR[0], pR[1]);
  }
  // 3 Vertical Keeper Strap Shadows
  for (let uKeep of [-58, 0, 58]) {
    let pTop = shadowPt(uKeep, -324, frameZ(-324));
    let pHinge = shadowPt(uKeep, -65, 48);
    let pBot = shadowPt(uKeep, 324, 48);
    brush.line(pTop[0], pTop[1], pHinge[0], pHinge[1]);
    brush.line(pHinge[0], pHinge[1], pBot[0], pBot[1]);
  }

  // Crisp indigo pencil edge reinforcement on the main cast shadow boundary
  brush.set("cpencil", "#08101c", 0.55);
  safeSpline([...bodyShadow, bodyShadow[0]], 0.2);
}

