// =========================================================================
// 5. MID-CENTURY STRIPED VINYL-STRAP LOUNGER
// =========================================================================

function drawStripedLounger() {
  // 18 Horizontal Vinyl Straps alternating Candy-Apple Red & Sun-Bleached Cream
  // Woven with 3 Vertical Keeper Straps (Cream at u = -58, Red at u = 0, Cream at u = +58)
  let numStraps = 18;
  let strapHalfH = 13.2; // Total strap width ~ 26.4px, leaving ~ 8.5px gap between straps!

  // Batch fills by color for speed and rich Kodachrome glaze saturation
  brush.noStroke();
  brush.noHatch();

  // Pass 1A: Base Watercolor Fills for all EVEN straps (Candy-Apple Red) & Center Vertical Keeper
  brush.fill("#d41720", 230);
  brush.fillBleed(0.03);
  brush.fillTexture(0.45, 0.35);

  for (let i = 0; i < numStraps; i += 2) {
    let vC = -300 + i * 35.3;
    drawPoly(getStrapPolygon(vC, strapHalfH), 0.03);
  }
  // Center vertical Candy-Apple Red keeper strap (u = -12..+12)
  drawPoly(localQuad(-12, -324, 12, 324, 6), 0.02);

  // Pass 1B: Second Deeper Crimson Glaze on Red Straps (for lush slide-film depth)
  brush.fill("#9e0b14", 115);
  brush.fillBleed(0.05);
  brush.fillTexture(0.5, 0.4);
  for (let i = 0; i < numStraps; i += 2) {
    let vC = -300 + i * 35.3;
    // Shade the sides where straps curve down to the frame & under body weight
    drawPoly(localQuad(-112, vC - strapHalfH, -55, vC + strapHalfH, 2), 0.02);
    drawPoly(localQuad(55, vC - strapHalfH, 112, vC + strapHalfH, 2), 0.02);
  }

  // Pass 2A: Base Watercolor Fills for all ODD straps (Sun-Bleached Cream/White) & Side Keepers
  brush.fill("#f5f0e4", 238);
  brush.fillBleed(0.02);
  brush.fillTexture(0.35, 0.25);

  for (let i = 1; i < numStraps; i += 2) {
    let vC = -300 + i * 35.3;
    drawPoly(getStrapPolygon(vC, strapHalfH), 0.03);
  }
  // Left & Right vertical Cream keeper straps (u = -70..-46 and u = +46..+70)
  drawPoly(localQuad(-70, -324, -46, 324, 6), 0.02);
  drawPoly(localQuad(46, -324, 70, 324, 6), 0.02);

  // Pass 2B: Cool Blue-Grey Slide Shadow Glaze on Cream Straps near frame rails
  brush.fill("#b8c5cf", 125);
  brush.fillBleed(0.04);
  for (let i = 1; i < numStraps; i += 2) {
    let vC = -300 + i * 35.3;
    drawPoly(localQuad(-112, vC - strapHalfH, -68, vC + strapHalfH, 2), 0.02);
    drawPoly(localQuad(68, vC - strapHalfH, 112, vC + strapHalfH, 2), 0.02);
  }

  // -----------------------------------------------------------------------
  // Crisp Pencil Detail on the Woven Plastic Straps (Weave Overlaps & Ribs)
  // -----------------------------------------------------------------------
  brush.noFill();
  let keepers = [
    { uMin: -70, uMax: -46, isRed: false },
    { uMin: -12, uMax: 12, isRed: true },
    { uMin: 46, uMax: 70, isRed: false }
  ];

  for (let i = 0; i < numStraps; i++) {
    let vC = -300 + i * 35.3;
    let isRed = (i % 2 === 0);
    let sag = (vC > -160 && vC < 190) ? 4.5 * cos((vC - 15) * 0.9) : 1.0;

    // Top and bottom contour edges of each horizontal strap
    let topEdge = [
      L2W(-112, vC - strapHalfH),
      L2W(0, vC - strapHalfH + sag),
      L2W(112, vC - strapHalfH)
    ];
    let botEdge = [
      L2W(-112, vC + strapHalfH),
      L2W(0, vC + strapHalfH + sag),
      L2W(112, vC + strapHalfH)
    ];

    brush.set("2H", isRed ? "#5e050b" : "#707c87", 0.38);
    safeSpline(topEdge, 0.35);
    safeSpline(botEdge, 0.35);

    // Extruded vinyl strap ribs (3 fine parallel longitudinal tension ridges per strap)
    for (let rOff of [-7, 0, 7]) {
      let ribPts = [
        L2W(-110, vC + rOff),
        L2W(0, vC + rOff + sag),
        L2W(110, vC + rOff)
      ];
      brush.set("2H", isRed ? "#ff6e75" : "#ffffff", 0.25);
      safeSpline(ribPts, 0.35);
    }

    // Over/Under Basketweave Intersections with the 3 Vertical Keeper Straps
    for (let k = 0; k < keepers.length; k++) {
      let kp = keepers[k];
      let keeperOnTop = ((i + k) % 2 === 0);
      let vTop = vC - strapHalfH + sag * (1 - abs(kp.uMin) / 112);
      let vBot = vC + strapHalfH + sag * (1 - abs(kp.uMin) / 112);

      if (keeperOnTop) {
        // Redraw keeper patch on top of horizontal strap + cast micro-shadows on left/right
        brush.noStroke();
        brush.fill(kp.isRed ? "#d41720" : "#f5f0e4", 240);
        drawPoly(localQuad(kp.uMin, vTop - 1, kp.uMax, vBot + 1, 2), 0.01);
        brush.noFill();
        // Vertical edge lines + shadow crease on horizontal strap
        let pL1 = L2W(kp.uMin, vTop), pL2 = L2W(kp.uMin, vBot);
        let pR1 = L2W(kp.uMax, vTop), pR2 = L2W(kp.uMax, vBot);
        brush.set("HB", "#1f1a24", 0.45);
        brush.line(pL1[0], pL1[1], pL2[0], pL2[1]);
        brush.line(pR1[0], pR1[1], pR2[0], pR2[1]);
      } else {
        // Horizontal strap crosses ON TOP of vertical keeper strap
        let pT1 = L2W(kp.uMin - 1, vTop), pT2 = L2W(kp.uMax + 1, vTop);
        let pB1 = L2W(kp.uMin - 1, vBot), pB2 = L2W(kp.uMax + 1, vBot);
        brush.set("HB", "#1f1a24", 0.45);
        brush.line(pT1[0], pT1[1], pT2[0], pT2[1]);
        brush.line(pB1[0], pB1[1], pB2[0], pB2[1]);
      }
    }
  }

  // -----------------------------------------------------------------------
  // Tubular Anodized Aluminum Frame of the Lounger
  // -----------------------------------------------------------------------
  brush.noStroke();
  brush.fill("#d5dee6", 245);
  brush.fillBleed(0.01);
  // Left rail, Right rail, Top bar, Bottom bar
  drawPoly(localQuad(-118, -330, -106, 330, 4), 0.01);
  drawPoly(localQuad(106, -330, 118, 330, 4), 0.01);
  drawPoly(localQuad(-118, -330, 118, -318, 4), 0.01);
  drawPoly(localQuad(-118, 318, 118, 330, 4), 0.01);

  brush.noFill();
  // Crisp metallic tube shading & specular highlights
  for (let uRail of [-112, 112]) {
    let rTop = L2W(uRail - 4, -328), rBot = L2W(uRail - 4, 328);
    brush.set("rotring", "#ffffff", 0.55);
    brush.line(rTop[0], rTop[1], rBot[0], rBot[1]);

    let sTop = L2W(uRail + 4, -328), sBot = L2W(uRail + 4, 328);
    brush.set("2H", "#495866", 0.5);
    brush.line(sTop[0], sTop[1], sBot[0], sBot[1]);

    // Backrest ratchet hinge bracket at v = -65
    let h1 = L2W(uRail - 7, -65), h2 = L2W(uRail + 7, -65);
    brush.set("rotring", "#1e2833", 0.65);
    brush.line(h1[0], h1[1], h2[0], h2[1]);
  }
}

function getStrapPolygon(vC, halfH) {
  let sag = (vC > -160 && vC < 190) ? 4.5 * cos((vC - 15) * 0.9) : 1.0;
  return [
    L2W(-112, vC - halfH),
    L2W(-55, vC - halfH + sag * 0.6),
    L2W(0, vC - halfH + sag),
    L2W(55, vC - halfH + sag * 0.6),
    L2W(112, vC - halfH),
    L2W(112, vC + halfH),
    L2W(55, vC + halfH + sag * 0.6),
    L2W(0, vC + halfH + sag),
    L2W(-55, vC + halfH + sag * 0.6),
    L2W(-112, vC + halfH)
  ];
}

