function drawPeelingSkinAndAnatomy() {
  // 1. Peeling Sunburn Patches on Left Shoulder, Right Shoulder, Chest & Upper Arm
  // Each patch has a raw pink-rose dermis center, a tiny dark micro-shadow rim,
  // and ragged, curled white/cream dead-skin edges!
  let peelPatches = [
    { u: -48, v: -94, rx: 14, ry: 9, ang: -12 },
    { u: -28, v: -78, rx: 9, ry: 6, ang: 18 },
    { u: 44, v: -92, rx: 16, ry: 10, ang: 15 },
    { u: 68, v: -84, rx: 11, ry: 7, ang: 28 },
    { u: 96, v: -78, rx: 12, ry: 6, ang: 22 },
    { u: 12, v: -56, rx: 13, ry: 7, ang: -8 },
    { u: -16, v: -44, rx: 10, ry: 6, ang: 10 },
    { u: 34, v: 205, rx: 9, ry: 12, ang: 4 }
  ];

  for (let p of peelPatches) {
    let rawPts = [];
    let curlPts1 = [];
    let curlPts2 = [];
    for (let a = 0; a < 360; a += 36) {
      let jitter = 0.82 + 0.32 * sin(a * 3 + p.u * 7);
      let du = p.rx * jitter * cos(a);
      let dv = p.ry * jitter * sin(a);
      let ru = du * cos(p.ang) - dv * sin(p.ang);
      let rv = du * sin(p.ang) + dv * cos(p.ang);
      let pt = L2W(p.u + ru, p.v + rv);
      rawPts.push(pt);
      if (a <= 180) curlPts1.push(L2W(p.u + ru * 1.12, p.v + rv * 1.12));
      if (a >= 144) curlPts2.push(L2W(p.u + ru * 1.14, p.v + rv * 1.14));
    }

    // Raw pink-salmon new skin inside peeled blister
    brush.noStroke();
    brush.fill("#f2797e", 210);
    brush.fillBleed(0.02);
    drawPoly(rawPts, 0.2);

    // Micro shadow under curled skin flap
    brush.noFill();
    brush.set("2H", "#7d1914", 0.32);
    safeSpline(curlPts1.map(q => [q[0] + 1.5, q[1] + 1.2]), 0.35);

    // Crisp curled white/cream peeling skin flake edges
    brush.set("rotring", "#fff8f0", 0.36);
    safeSpline(curlPts1, 0.35);
    brush.set("cpencil", "#ffeae0", 0.45);
    safeSpline(curlPts2, 0.35);
  }

  // Tiny sunburn freckles & tiny white peeling specks across shoulders & upper chest
  for (let i = 0; i < 42; i++) {
    let fu = random(-72, 85);
    let fv = random(-105, -25);
    let fp = L2W(fu, fv);
    if (i % 3 === 0) {
      brush.set("rotring", "#fff5eb", 0.32);
      brush.line(fp[0], fp[1], fp[0] + 2.5, fp[1] - 1.2);
    } else {
      brush.set("2H", "#8f2119", 0.28);
      brush.line(fp[0], fp[1], fp[0] + 1.5, fp[1] + 1.0);
    }
  }

  // 2. Crisp Pencil Contours & Anatomical Modeling (Pectorals, Ribs, Collarbones, Fingers, Toes)
  brush.noFill();
  brush.set("HB", "#6e1c16", 0.42);
  safeSpline(getTorsoPts(0, 0), 0.15);
  safeSpline(getLeftLegPts(0, 0), 0.15);
  safeSpline(getRightLegPts(0, 0), 0.15);
  safeSpline(getRightArmPts(0, 0), 0.15);
  safeSpline(getLeftArmPts(0, 0), 0.12);

  // Pectoral lines & sternum groove
  brush.set("cpencil", "#96241d", 0.48);
  safeSpline([L2W(-62, -62), L2W(-35, -44), L2W(-6, -48)], 0.4);
  safeSpline([L2W(62, -62), L2W(35, -44), L2W(6, -48)], 0.4);
  // Sternum & linea alba + navel
  brush.set("2H", "#9e2922", 0.35);
  safeSpline([L2W(0, -82), L2W(0, -42), L2W(1, 28)], 0.3);
  let nav = L2W(1, 38);
  brush.set("HB", "#5e1410", 0.45);
  brush.circle(nav[0], nav[1], 3.2, 0.1);

  // Subtle ribcage & oblique contour hatching on shaded right side of torso
  brush.hatchStyle("2H", "#a32921", 0.28);
  brush.hatch(6, 35, { rand: 0.1 });
  drawPoly([L2W(36, -40), L2W(64, -40), L2W(56, 52), L2W(32, 48)], 0.1);
  brush.noHatch();

  // Individual fingers on right hand (resting on abdomen around u = -28, v = 18)
  brush.set("2H", "#6e1c16", 0.32);
  for (let f = 0; f < 4; f++) {
    let fv = 8 + f * 6.5;
    safeSpline([L2W(-42, fv - 2), L2W(-24, fv), L2W(-14, fv + 2)], 0.3);
  }

  // Individual fingers on trailing left hand (dipping into water u = 225..256)
  for (let f = 0; f < 4; f++) {
    let fv = -37 + f * 5.2;
    let fLen = (f === 1 || f === 2) ? 256 : 249;
    safeSpline([L2W(222, fv), L2W(238, fv + 2), L2W(fLen, fv + 5)], 0.3);
  }
}

function drawStrawHat() {
