  }
  brush.fill("#d91b24", 235);
  drawPoly(redBandPts, 0.2);

  // 4. Pinched Panama/Fedora Straw Crown
  let crownPts = [];
  for (let a = 0; a < 360; a += 20) {
    // Slight front pinch at top (a ~ -90)
    let pinch = (a > 210 && a < 330) ? -5 * sin((a - 210) * 3) : 0;
    crownPts.push(L2W(2 + (44 + pinch) * cos(a), -168 + 48 * sin(a)));
  }
  brush.fill("#f5dfa0", 245);
  brush.fillBleed(0.04);
  brush.fillTexture(0.45, 0.3);
