  drawPoly([
    L2W(-8, -202), L2W(12, -202), L2W(16, -142), L2W(-12, -142)
  ], 0.25);

  // 5. Crisp Pencil Weave Detail on the Straw Hat (Concentric & Radial Straw Fibers)
  brush.noFill();
  for (let rFactor of [0.25, 0.36, 0.46, 0.64, 0.74, 0.84, 0.93, 1.0]) {
    let ring = [];
    for (let a = 0; a <= 360; a += 20) {
      let wave = (rFactor > 0.6) ? 3.5 * sin(a * 3 - 20) * rFactor : 0;
      ring.push(L2W(2 + (94 * rFactor + wave) * cos(a), -168 + (84 * rFactor + wave) * sin(a)));
    }
    brush.set("2H", (rFactor === 1.0) ? "#6b4411" : "#8f6120", (rFactor === 1.0) ? 0.48 : 0.3);
    safeSpline(ring, 0.35);
  }

  // Radial curved straw weave lines across the brim
  for (let a = 0; a < 360; a += 10) {
    let pIn = L2W(2 + 53 * cos(a), -168 + 57 * sin(a));
    let pMid = L2W(2 + 74 * cos(a + 8), -168 + 68 * sin(a + 8));
    let pOut = L2W(2 + 93 * cos(a + 16), -168 + 83 * sin(a + 16));
    brush.set("2H", (a > 160 && a < 330) ? "#fff4cf" : "#7d5116", 0.26);
    safeSpline([pIn, pMid, pOut], 0.4);
  }
}

