// =========================================================================

function drawHandwrittenText(str, startX, startY, sc, col) {
  let glyphs = {
    'A': [[[0, 24], [10, 0], [18, 24]], [[3, 15], [16, 15]]],
    'U': [[[0, 0], [1, 19], [9, 24], [17, 19], [18, 0]]],
    'G': [[[18, 4], [10, 0], [2, 5], [0, 14], [4, 22], [14, 24], [18, 17], [18, 13], [11, 13]]],
    '\'': [[[6, -2], [4, 7]]],
    '6': [[[15, 1], [6, 5], [1, 14], [3, 22], [11, 24], [17, 19], [15, 12], [7, 11], [1, 15]]],
    '9': [[[16, 8], [11, 13], [3, 11], [1, 5], [6, 0], [14, 1], [17, 8], [13, 24]]],
    '-': [[[2, 12], [16, 12]]],
    'P': [[[2, 0], [0, 24]], [[2, 1], [13, 0], [17, 5], [13, 11], [1, 12]]],
    'L': [[[2, 0], [0, 23], [15, 23]]],
    'M': [[[0, 24], [3, 0], [11, 16], [20, 0], [21, 24]]],
    'S': [[[16, 3], [9, 0], [2, 3], [3, 9], [15, 14], [16, 20], [9, 24], [1, 21]]],
    'R': [[[2, 0], [0, 24]], [[2, 1], [13, 0], [17, 5], [12, 11], [1, 12]], [[9, 11], [17, 24]]],
    'I': [[[2, 0], [12, 0]], [[7, 0], [5, 24]], [[0, 24], [11, 24]]],
    'N': [[[0, 24], [2, 0], [16, 24], [18, 0]]],
    '1': [[[3, 5], [9, 0], [7, 24]], [[1, 24], [13, 24]]],
    '4': [[[14, 0], [0, 16], [18, 16]], [[14, 0], [12, 24]]]
  };

  let cx = startX;
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    if (ch === ' ') {
      cx += 18 * sc;
      continue;
    }
    let strokes = glyphs[ch];
    if (strokes) {
      for (let s of strokes) {
        let pts = s.map(p => [
          cx + (p[0] - p[1] * 0.14) * sc + random(-0.4, 0.4),
          startY + p[1] * sc + random(-0.4, 0.4)
        ]);
        // Main graphite stroke + faint secondary pencil pass for authentic texture
        brush.set("HB", col, 0.42);
        safeSpline(pts, 0.35);
        brush.set("2H", col, 0.25);
        safeSpline(pts.map(q => [q[0] + 0.5, q[1] + 0.3]), 0.35);
      }
    }
    cx += 24 * sc;
  }
}

