let lemons = [];
let juiceDrops = [];
let fallenSeeds = [];

class StitchBatcher {
  constructor() {
    this.buckets = new Map();
  }

  add(layer, brushName, colorHex, weight, x1, y1, x2, y2) {
    if (x1 < -20 || x1 > 1220 || y1 < -20 || y1 > 1220) return;
    let w = Math.max(0.2, Math.round(weight * 20) / 20);
    let key = `${layer}|${brushName}|${colorHex}|${w}`;
    let b = this.buckets.get(key);
    if (!b) {
      b = { layer, brushName, colorHex, weight: w, lines: [] };
      this.buckets.set(key, b);
    }
    b.lines.push(x1, y1, x2, y2);
  }

  // Helper to lay down a series of kantha dashes along a polyline of points [[x,y], ...]
  addPathStitches(pts, styleFn, stepOpts = {}) {
    if (pts.length < 2) return;
    let dashLen = stepOpts.dashLen || 7.5;
    let gapLen = stepOpts.gapLen || 4.2;
    let jitter = stepOpts.jitter !== undefined ? stepOpts.jitter : 0.35;

    // Accumulate arc-length along polyline
    let dists = [0];
    let totalLen = 0;
    for (let i = 1; i < pts.length; i++) {
      let d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
      totalLen += d;
      dists.push(totalLen);
    }
    if (totalLen < 2.5) return;

    let cursor = (stepOpts.phase || 0) * (dashLen + gapLen);
    let segIdx = 0;

    const sampleAt = (s) => {
      while (segIdx < dists.length - 2 && dists[segIdx + 1] < s) segIdx++;
      let d0 = dists[segIdx];
      let d1 = dists[segIdx + 1];
      let t = d1 > d0 ? (s - d0) / (d1 - d0) : 0;
      t = Math.max(0, Math.min(1, t));
      let p0 = pts[segIdx];
      let p1 = pts[segIdx + 1];
      return [
        p0[0] + (p1[0] - p0[0]) * t,
        p0[1] + (p1[1] - p0[1]) * t,
        p1[0] - p0[0],
        p1[1] - p0[1]
      ];
    };

    while (cursor < totalLen - 1.5) {
      let midS = Math.min(totalLen, cursor + dashLen * 0.5);
      let pMid = sampleAt(midS);
      let uParam = midS / totalLen;
      let st = styleFn(pMid[0], pMid[1], uParam);

      if (!st || st.skip) {
        cursor += (st && st.stepOverride) ? st.stepOverride : (dashLen + gapLen) * 0.7;
        continue;
      }

      let curDash = st.dashLen || dashLen;
      let curGap = st.gapLen || gapLen;
      let s0 = cursor;
      let s1 = Math.min(totalLen, cursor + curDash);

      if (s1 - s0 >= 1.8) {
        let pA = sampleAt(s0);
        let pB = sampleAt(s1);
        let nx = -pMid[3], ny = pMid[2];
        let nLen = Math.hypot(nx, ny) || 1;
        nx /= nLen; ny /= nLen;
        let off = (random(-1, 1) * jitter);

        this.add(
          st.layer,
          st.brush || "pen",
          st.color,
          st.weight || 0.55,
          pA[0] + nx * off,
          pA[1] + ny * off,
          pB[0] + nx * off,
          pB[1] + ny * off
        );
      }

      cursor += curDash + curGap * random(0.88, 1.12);
    }
  }

  render() {
    let sorted = Array.from(this.buckets.values()).sort((a, b) => a.layer - b.layer);
    for (let b of sorted) {
      brush.set(b.brushName, b.colorHex, b.weight);
      let lines = b.lines;
      for (let i = 0; i < lines.length; i += 4) {
        brush.line(lines[i], lines[i + 1], lines[i + 2], lines[i + 3]);
      }
    }
  }
}

