function createLemon(cfg) {
  let rad = (cfg.rotDeg * Math.PI) / 180;
  let cosA = Math.cos(rad), sinA = Math.sin(rad);

  // Generate segment angles with slight natural organic irregularity
  let segAngles = [0];
  let totalWeight = 0;
  let weights = [];
  for (let i = 0; i < cfg.numSegs; i++) {
    let w = 1 + 0.14 * Math.sin(i * 2.1 + cfg.id * 1.7) + random(-0.06, 0.06);
    weights.push(w);
    totalWeight += w;
  }
  let acc = 0;
  for (let i = 0; i < cfg.numSegs; i++) {
    acc += (weights[i] / totalWeight) * Math.PI * 2;
    segAngles.push(acc);
  }

  // Generate packed juice vesicles inside each segment for high-contrast wet realism
  let segments = [];
  for (let k = 0; k < cfg.numSegs; k++) {
    let a0 = segAngles[k];
    let a1 = segAngles[k + 1];
    let vesicles = [];
    let rows = 6;
    for (let rIdx = 0; rIdx < rows; rIdx++) {
      let rho = 0.18 + (rIdx / (rows - 1)) * 0.68;
      let cols = Math.max(2, Math.floor(2 + rho * 5.5));
      for (let cIdx = 0; cIdx < cols; cIdx++) {
        let t = (cIdx + 0.5 + (rIdx % 2) * 0.22 - 0.11) / cols;
        t = Math.max(0.08, Math.min(0.92, t));
        vesicles.push({
          rho: rho + random(-0.03, 0.03),
          t: t,
          drho: 0.095 + random(-0.015, 0.02),
          dt: (0.14 / (0.35 + rho * 0.65)) * random(0.85, 1.15),
          gloss: random(0.4, 1.0),
          depthBias: random(-0.15, 0.2)
        });
      }
    }

    let hasSeed = cfg.seedSegs.includes(k);
    let seed = hasSeed
      ? {
          rho: 0.27 + random(-0.02, 0.03),
          t: 0.5 + random(-0.06, 0.06),
          rx: 15,
          ry: 8.5
        }
      : null;

    segments.push({ a0, a1, vesicles, seed, index: k });
  }

  // Precompute 3D rind dome cross-section slices s in [0, 1]
  let slices = [];
  let numSlices = 42;
  for (let i = 0; i <= numSlices; i++) {
    let s = i / numSlices;
    // Ellipsoidal dome profile with terminal lemon nipple (mamilla)
    let mainProfile = Math.cos(s * Math.PI * 0.5);
    let nippleBump = Math.exp(-Math.pow((s - 0.91) / 0.09, 2)) * 0.14 * (1 - s * 0.3);
    let scaleR = Math.max(0.04, Math.pow(mainProfile, 0.78) + nippleBump);

    let shiftCurve = Math.pow(s, 0.92) + (s > 0.8 ? Math.pow((s - 0.8) / 0.2, 1.6) * 0.16 : 0);
    let sx = cfg.cx + cfg.domeDx * shiftCurve;
    let sy = cfg.cy + cfg.domeDy * shiftCurve;

    slices.push({
      s,
      cx: sx,
      cy: sy,
      rx: cfg.rx * scaleR,
      ry: cfg.ry * scaleR
    });
  }

  return {
    ...cfg,
    rad,
    cosA,
    sinA,
    segAngles,
    segments,
    slices
  };
}

// Convert world (x, y) to local normalized coordinates (u, v) on a slice ellipse
function toLocalEllipse(x, y, cx, cy, rx, ry, cosA, sinA, id = 0) {
  let dx = x - cx;
  let dy = y - cy;
  let lx = dx * cosA + dy * sinA;
  let ly = -dx * sinA + dy * cosA;
  let ang = Math.atan2(ly / ry, lx / rx);
  // Subtle organic citrus lobing
  let lobe = 1 + 0.011 * Math.cos(10 * ang + id) + 0.016 * Math.cos(2 * ang - 0.5);
  let u = lx / (rx * lobe);
  let v = ly / (ry * lobe);
  return { u, v, r: Math.hypot(u, v), ang, lx, ly };
}

// Point on a slice ellipse at parameter angle phi (radians)
function pointOnLemonSlice(lem, slice, phi) {
  let lobe = 1 + 0.011 * Math.cos(lem.numSegs * phi + lem.id) + 0.016 * Math.cos(2 * phi - 0.5);
  let lx = slice.rx * lobe * Math.cos(phi);
  let ly = slice.ry * lobe * Math.sin(phi);
  let wx = slice.cx + lx * lem.cosA - ly * lem.sinA;
  let wy = slice.cy + lx * lem.sinA + ly * lem.cosA;
  return [wx, wy];
}

// Test if world point (x, y) lies inside a lemon's full silhouette (cut face + rind dome)
function getLemonHit(x, y) {
  for (let i = lemons.length - 1; i >= 0; i--) {
    let lem = lemons[i];
    // Quick bounding box check
    if (
      x < lem.cx - 290 || x > lem.cx + 290 ||
      y < lem.cy - 240 || y > lem.cy + 270
    ) continue;

    // Check cut face (slice 0)
    let loc0 = toLocalEllipse(x, y, lem.cx, lem.cy, lem.rx, lem.ry, lem.cosA, lem.sinA, lem.id);
    if (loc0.r <= 1.01) {
      return { lemon: lem, part: "cut", r: loc0.r, ang: loc0.ang, s: 0 };
    }

    // Check rind dome slices
    for (let j = 1; j < lem.slices.length; j += 2) {
      let sl = lem.slices[j];
      let locS = toLocalEllipse(x, y, sl.cx, sl.cy, sl.rx, sl.ry, lem.cosA, lem.sinA, lem.id);
      if (locS.r <= 1.02) {
        return { lemon: lem, part: "rind", r: locS.r, ang: locS.ang, s: sl.s };
      }
    }
  }
  return null;
}

// Minimum distance from (x, y) to any lemon silhouette for cloth fold depressions & quilting halos
function minDistToLemon(x, y) {
  let bestDist = 9999;
  let nearestLem = null;
  for (let lem of lemons) {
    for (let j = 0; j < lem.slices.length; j += 3) {
      let sl = lem.slices[j];
      let dx = x - sl.cx, dy = y - sl.cy;
      let lx = dx * lem.cosA + dy * lem.sinA;
      let ly = -dx * lem.sinA + dy * lem.cosA;
      let normR = Math.hypot(lx / sl.rx, ly / sl.ry);
      let approxPxDist = (normR - 1.0) * Math.min(sl.rx, sl.ry);
      if (approxPxDist < bestDist) {
        bestDist = approxPxDist;
        nearestLem = lem;
      }
    }
  }
  return { dist: bestDist, lemon: nearestLem };
}

// Crumpled cotton cloth 2.5D heightfield
function clothHeight(x, y) {
  let nx = x / 1200;
  let ny = y / 1200;

  // Major sculptural folds draping across the cloth
  let f1 = Math.exp(-Math.pow((ny - (0.28 + 0.36 * nx + 0.04 * Math.sin(nx * 5))) / 0.075, 2)) * 34;
  let f2 = Math.exp(-Math.pow((ny - (0.64 + 0.22 * nx - 0.05 * Math.cos(nx * 4.2))) / 0.085, 2)) * 38;
  let f3 = Math.exp(-Math.pow((nx - (0.48 + 0.14 * ny + 0.03 * Math.sin(ny * 6))) / 0.068, 2)) * 28;
  let f4 = Math.exp(-Math.pow((ny - (0.14 + 0.24 * (1 - nx))) / 0.07, 2)) * 24;
  let f5 = Math.exp(-Math.pow((ny - (0.88 - 0.12 * nx + 0.03 * Math.sin(nx * 7))) / 0.065, 2)) * 26;

  // Secondary crinkles & natural cotton drape ripples
  let ripple =
    Math.sin(nx * 14 + ny * 9 + 1.2) * 6.5 +
    Math.cos(nx * 23 - ny * 16) * 3.8 +
    (noise(nx * 3.5, ny * 3.5) - 0.5) * 26;

  // Weight depression under each lemon
  let depression = 0;
  for (let lem of lemons) {
    let d = Math.hypot((x - (lem.cx + lem.domeDx * 0.35)) / (lem.rx * 1.35), (y - (lem.cy + lem.domeDy * 0.35)) / (lem.ry * 1.35));
    if (d < 1.8) {
      depression -= Math.exp(-d * d * 1.6) * 28;
      // Soft bunched rim of cloth pushed up just outside the lemon's footprint
      depression += Math.exp(-Math.pow((d - 1.08) / 0.24, 2)) * 14;
    }
  }

  return f1 + f2 + f3 + f4 + f5 + ripple + depression;
}

// Compute cloth normal, lighting, cast shadow, and translucent citrus caustic
function evaluateClothLighting(x, y) {
  let eps = 4.0;
  let h0 = clothHeight(x, y);
  let hx = (clothHeight(x + eps, y) - clothHeight(x - eps, y)) / (2 * eps);
  let hy = (clothHeight(x, y + eps) - clothHeight(x, y - eps)) / (2 * eps);

  let nx = -hx * 1.35;
  let ny = -hy * 1.35;
  let nz = 1.0;
  let nLen = Math.hypot(nx, ny, nz);
  nx /= nLen; ny /= nLen; nz /= nLen;

  let ndotl = Math.max(0, nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z);

  // Cast shadow & translucent golden caustic from the three 3D lemon halves
  let shadowStrength = 0;
  let contactStrength = 0;
  let causticStrength = 0;
  let yellowBounce = 0;

  for (let lem of lemons) {
    // Contact shadow right under the base of the rind dome & lower cut rim
    let baseCx = lem.cx + lem.domeDx * 0.42;
    let baseCy = lem.cy + lem.domeDy * 0.48 + 18;
    let cdx = x - baseCx, cdy = y - baseCy;
    let clx = cdx * lem.cosA + cdy * lem.sinA;
    let cly = -cdx * lem.sinA + cdy * lem.cosA;
    let cDist = Math.hypot(clx / (lem.rx * 1.02), cly / (lem.ry * 0.95));
    if (cDist < 1.35) {
      let cVal = Math.exp(-Math.pow(Math.max(0, cDist - 0.72) / 0.26, 2));
      contactStrength = Math.max(contactStrength, cVal);
    }

    // Extended cast shadow toward bottom-right (opposite LIGHT)
    let shCx = lem.cx + lem.domeDx * 0.45 + 118;
    let shCy = lem.cy + lem.domeDy * 0.45 + 98;
    let sdx = x - shCx, sdy = y - shCy;
    let slx = sdx * lem.cosA + sdy * lem.sinA;
    let sly = -sdx * lem.sinA + sdy * lem.cosA;
    let sDist = Math.hypot(slx / (lem.rx * 1.28), sly / (lem.ry * 1.15));
    if (sDist < 1.25) {
      let sVal = Math.pow(Math.max(0, 1 - sDist * 0.85), 1.5);
      shadowStrength = Math.max(shadowStrength, sVal);

      // Refracted golden caustic inside the cast shadow of the translucent cut pulp
      let caustDist = Math.hypot((slx + 28) / (lem.rx * 0.62), (sly + 18) / (lem.ry * 0.52));
      if (caustDist < 1.0) {
        causticStrength = Math.max(causticStrength, Math.pow(1 - caustDist, 1.8) * 0.85);
      }
    }

    // Warm yellow bounce light on cloth slopes facing the sunlit lemon
    let bDist = Math.hypot(x - lem.cx, y - lem.cy) / (lem.rx * 1.9);
    if (bDist < 1.5 && bDist > 0.7) {
      yellowBounce = Math.max(yellowBounce, (1.5 - bDist) * 0.45);
    }
  }

  return {
    h: h0,
    hx, hy,
    ndotl,
    shadow: Math.min(1, shadowStrength * 0.85 + contactStrength * 0.95),
    contact: contactStrength,
    caustic: causticStrength,
    bounce: yellowBounce
  };
}

// Draw faint watercolor underpainting on the pale unbleached-cotton ground
function drawWatercolorUnderpainting() {
  brush.noStroke();

  // 1. Subtle warm cotton & cool fold washes on the ground
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.45, 0.25);

  // Cool indigo-slate washes in the cloth fold valleys & cast shadows
  brush.fill(PALETTE.indigoPale, 26);
  for (let lem of lemons) {
    let shX = lem.cx + lem.domeDx * 0.45 + 95;
    let shY = lem.cy + lem.domeDy * 0.45 + 82;
    drawSmoothEllipseWash(shX, shY, lem.rx * 1.18, lem.ry * 0.95, lem.rotDeg);
  }
  // Major diagonal cloth fold shadow wash
  drawSmoothEllipseWash(540, 520, 340, 95, 22);
  drawSmoothEllipseWash(860, 740, 290, 85, -18);
  drawSmoothEllipseWash(240, 290, 240, 70, 15);

  // Deep indigo + madder washes in the contact shadow under each lemon
  brush.fill(PALETTE.indigoDeep, 48);
  for (let lem of lemons) {
    let bx = lem.cx + lem.domeDx * 0.5 + 32;
    let by = lem.cy + lem.domeDy * 0.55 + 36;
    drawSmoothEllipseWash(bx, by, lem.rx * 0.92, lem.ry * 0.68, lem.rotDeg);
  }

  // Translucent golden-saffron caustic wash inside the cast shadows
  brush.fill(PALETTE.saffronGold, 44);
  for (let lem of lemons) {
    let cx = lem.cx + lem.domeDx * 0.4 + 82;
    let cy = lem.cy + lem.domeDy * 0.4 + 68;
    drawSmoothEllipseWash(cx, cy, lem.rx * 0.55, lem.ry * 0.42, lem.rotDeg);
  }

  // 2. Watercolor underpainting on the 3D lemon rind domes
  brush.fillBleed(0.18, "out");
  brush.fill(PALETTE.cadmiumLemon, 62);
  for (let lem of lemons) {
    let sl = lem.slices[18];
    drawSmoothEllipseWash(sl.cx, sl.cy, sl.rx * 0.96, sl.ry * 0.96, lem.rotDeg);
  }

  brush.fill(PALETTE.saffronVivid, 55);
  for (let lem of lemons) {
    let sl = lem.slices[26];
    drawSmoothEllipseWash(sl.cx + 12, sl.cy + 14, sl.rx * 0.88, sl.ry * 0.86, lem.rotDeg);
  }

  // 3. Watercolor tint on the cut citrus faces (golden lemon & madder depth in pulp)
  brush.fillBleed(0.14, "in");
  brush.fill(PALETTE.lemonPale, 58);
  for (let lem of lemons) {
    drawSmoothEllipseWash(lem.cx, lem.cy, lem.rx * 0.84, lem.ry * 0.84, lem.rotDeg);
  }

  brush.fill(PALETTE.saffronGold, 50);
  for (let lem of lemons) {
    drawSmoothEllipseWash(lem.cx - 8, lem.cy - 6, lem.rx * 0.68, lem.ry * 0.68, lem.rotDeg);
  }

  brush.fill(PALETTE.madderPink, 34);
  for (let lem of lemons) {
    drawSmoothEllipseWash(lem.cx - 14, lem.cy - 12, lem.rx * 0.48, lem.ry * 0.48, lem.rotDeg);
  }

  brush.noFill();
}

function drawSmoothEllipseWash(cx, cy, rx, ry, rotDeg) {
  let rad = (rotDeg * Math.PI) / 180;
  let c = Math.cos(rad), s = Math.sin(rad);
  let steps = 20;
  brush.beginShape(0.35);
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * Math.PI * 2;
    let lx = rx * Math.cos(a);
    let ly = ry * Math.sin(a);
    brush.vertex(cx + lx * c - ly * s, cy + lx * s + ly * c);
  }
  brush.endShape(true);
}

// LAYER 0: Subtle unbleached-cotton weave texture in the background
function generateCottonWeave(batcher) {
  for (let y = 24; y < 1180; y += 16) {
    let pts = [];
    for (let x = 20; x <= 1180; x += 28) {
      let h = clothHeight(x, y);
      pts.push([x, y - h * 0.32]);
    }
    batcher.addPathStitches(
      pts,
      (x, y) => {
        if (getLemonHit(x, y)) return { skip: true, stepOverride: 18 };
        return {
          layer: 0,
          brush: "cpencil",
          color: random() < 0.5 ? PALETTE.cottonWeave : PALETTE.cottonMid,
          weight: 0.28,
          dashLen: 5.5,
          gapLen: 8.5
        };
      },
      { dashLen: 5.5, gapLen: 8.5, jitter: 0.2, phase: random() }
    );
  }
}

// LAYERS 1 & 2: Rippling parallel kantha running-stitch rows across the crumpled cotton cloth
function generateClothKanthaStitches(batcher) {
  let baseAngleRad = (-11 * Math.PI) / 180;
  let cosB = Math.cos(baseAngleRad), sinB = Math.sin(baseAngleRad);
  let nxB = -sinB, nyB = cosB;

  // Primary & secondary (half-step) quilting rows across the cloth
  let rowSpacing = 3.8; // Half-step spacing; lit areas skip odd rows so shadow density doubles!
  let rowIdx = 0;

  for (let offset = -240; offset <= 1380; offset += rowSpacing) {
    rowIdx++;
    let isHalfRow = (rowIdx % 2 === 1);
    let pts = [];

    for (let t = -160; t <= 1360; t += 11) {
      let bx = 600 + (t - 600) * cosB + (offset - 600) * nxB;
      let by = 600 + (t - 600) * sinB + (offset - 600) * nyB;
      if (bx < 14 || bx > 1186 || by < 14 || by > 1186) continue;

      let h = clothHeight(bx, by);
      // Displace stitch row along the 3D fold contour
      let wx = bx - nxB * h * 0.78;
      let wy = by - nyB * h * 0.78;

      // Subtle deflection around the immediate base of each lemon
      let mDist = minDistToLemon(wx, wy);
      if (mDist.dist > -2 && mDist.dist < 34 && mDist.lemon) {
        let push = Math.exp(-Math.max(0, mDist.dist) / 14) * 8.5;
        let dx = wx - mDist.lemon.cx;
        let dy = wy - mDist.lemon.cy;
        let dLen = Math.hypot(dx, dy) || 1;
        wx += (dx / dLen) * push;
        wy += (dy / dLen) * push;
      }

      pts.push([wx, wy]);
    }

    // Check if this row belongs to the traditional woven kantha selvedge stripe band
    let isMadderStripe =
      (offset > 145 && offset < 178) ||
      (offset > 192 && offset < 206) ||
      (offset > 995 && offset < 1028);
    let isIndigoStripe =
      (offset >= 178 && offset <= 192) ||
      (offset >= 1028 && offset <= 1044);

    batcher.addPathStitches(
      pts,
      (x, y) => {
        if (getLemonHit(x, y)) return { skip: true, stepOverride: 12 };

        // Skip around loose juice drops & fallen seeds
        for (let d of juiceDrops) {
          if (Math.hypot((x - d.x) / (d.rx + 2), (y - d.y) / (d.ry + 2)) < 1.0) {
            return { skip: true, stepOverride: 7 };
          }
        }
        for (let sd of fallenSeeds) {
          if (Math.hypot((x - sd.x) / (sd.rx + 2), (y - sd.y) / (sd.ry + 2)) < 1.0) {
            return { skip: true, stepOverride: 7 };
          }
        }

        let info = evaluateClothLighting(x, y);
        let shade = (1 - info.ndotl) * 0.68 + info.shadow * 0.85;

        // In bright lit cloth planes, skip half-rows so stitch density breathes naturally
        if (isHalfRow && shade < 0.42 && info.caustic < 0.2 && !isMadderStripe && !isIndigoStripe) {
          return { skip: true, stepOverride: 13 };
        }

        let col = PALETTE.cottonShadow;
        let weight = 0.46;
        let dash = 7.5;
        let gap = 4.6;
        let layer = isHalfRow ? 2 : 1;

        if (info.contact > 0.52) {
          // Deepest contact shadow directly under the lemons
          let r = random();
          col = r < 0.62 ? PALETTE.indigoAbyss : (r < 0.85 ? PALETTE.indigoDeep : PALETTE.madderDark);
          weight = 0.76;
          dash = 6.5;
          gap = 2.4;
        } else if (info.caustic > 0.28 && info.shadow > 0.3) {
          // Luminous golden-saffron & cadmium caustic core inside the cast shadow
          let r = random();
          if (info.caustic > 0.55) {
            col = r < 0.5 ? PALETTE.cadmiumLemon : (r < 0.82 ? PALETTE.saffronGold : PALETTE.saffronVivid);
          } else {
            col = r < 0.45 ? PALETTE.saffronVivid : (r < 0.78 ? PALETTE.madderPink : PALETTE.indigoMid);
          }
          weight = 0.58;
          dash = 6.8;
          gap = 3.2;
        } else if (shade > 0.78) {
          // Deep cast shadow umbra & steep fold crevices
          let r = random();
          col = r < 0.48 ? PALETTE.indigoDeep : (r < 0.74 ? PALETTE.indigoMid : (r < 0.9 ? PALETTE.madderRich : PALETTE.greenDeep));
          weight = 0.68;
          dash = 7.0;
          gap = 2.9;
        } else if (shade > 0.50) {
          // Mid-shadow cloth folds
          let r = random();
          if (isMadderStripe) col = r < 0.7 ? PALETTE.madderRich : PALETTE.indigoMid;
          else if (isIndigoStripe) col = PALETTE.indigoDeep;
          else col = r < 0.45 ? PALETTE.indigoSlate : (r < 0.78 ? PALETTE.madderPink : PALETTE.indigoMid);
          weight = 0.55;
          dash = 7.4;
          gap = 3.6;
        } else if (shade > 0.28) {
          // Soft half-tone ripples on the cotton cloth
          let r = random();
          if (isMadderStripe) col = PALETTE.madderPink;
          else if (isIndigoStripe) col = PALETTE.indigoSlate;
          else if (info.bounce > 0.2 && r < 0.38) col = PALETTE.saffronGold;
          else col = r < 0.44 ? PALETTE.indigoPale : (r < 0.78 ? PALETTE.madderSoft : PALETTE.cottonShadow);
          weight = 0.46;
          dash = 7.8;
          gap = 4.5;
        } else {
          // Sunlit crests of the crumpled cotton cloth
          let r = random();
          if (isMadderStripe) col = PALETTE.madderSoft;
          else if (isIndigoStripe) col = PALETTE.indigoPale;
          else if (info.bounce > 0.22 && r < 0.35) col = PALETTE.lemonPale;
          else col = r < 0.45 ? PALETTE.cottonLight : (r < 0.8 ? PALETTE.madderBlush : PALETTE.cottonShadow);
          weight = 0.38;
          dash = 8.2;
          gap = 6.2;
        }

        return {
          layer,
          brush: "kantha",
          color: col,
          weight,
          dashLen: dash,
          gapLen: gap
        };
      },
      { dashLen: 7.5, gapLen: 4.5, jitter: 0.35, phase: (rowIdx * 0.37) % 1 }
    );
  }

  // Contour-hugging kantha quilting rings right around the base of each lemon in the cloth
  for (let lem of lemons) {
    for (let ring = 1; ring <= 4; ring++) {
      let pts = [];
      let sl = lem.slices[16];
      let expand = 1.03 + ring * 0.042;
      for (let deg = -35; deg <= 195; deg += 4) {
        let phi = (deg * Math.PI) / 180;
        let lx = sl.rx * expand * Math.cos(phi);
        let ly = sl.ry * expand * Math.sin(phi);
        let wx = sl.cx + lx * lem.cosA - ly * lem.sinA + 8;
        let wy = sl.cy + lx * lem.sinA + ly * lem.cosA + 10;
        if (!getLemonHit(wx, wy)) pts.push([wx, wy]);
      }
      batcher.addPathStitches(
        pts,
        (x, y) => {
          let info = evaluateClothLighting(x, y);
          let col = ring <= 2 ? PALETTE.indigoAbyss : (info.caustic > 0.3 ? PALETTE.saffronVivid : PALETTE.indigoDeep);
          return {
            layer: 2,
            brush: "kantha",
            color: col,
            weight: 0.68 - ring * 0.06,
            dashLen: 6.2,
            gapLen: 2.8
          };
        },
        { dashLen: 6.2, gapLen: 2.8, jitter: 0.3, phase: ring * 0.25 }
      );
    }
  }
}

// LAYERS 3 & 4: 3D Rind Dome & Nipple Apex Stitches (Latitudinal Rings + Oil-Gland Dimple Nuances)
function generateLemonRindStitches(batcher, lem) {
  let domeAngle = Math.atan2(lem.domeDy, lem.domeDx);

  // 1. Latitudinal contour rings wrapping around the 3D lemon dome (s from 0.02 to 0.99)
  let totalRings = 58;
  for (let rIdx = 1; rIdx <= totalRings; rIdx++) {
    let s = rIdx / totalRings;
    let isSubRing = (rIdx % 2 === 1);

    // Interpolate slice parameters
    let mainProfile = Math.cos(s * Math.PI * 0.5);
    let nippleBump = Math.exp(-Math.pow((s - 0.91) / 0.09, 2)) * 0.14 * (1 - s * 0.3);
    let scaleR = Math.max(0.03, Math.pow(mainProfile, 0.78) + nippleBump);
    let shiftCurve = Math.pow(s, 0.92) + (s > 0.8 ? Math.pow((s - 0.8) / 0.2, 1.6) * 0.16 : 0);

    let sl = {
      s,
      cx: lem.cx + lem.domeDx * shiftCurve,
      cy: lem.cy + lem.domeDy * shiftCurve,
      rx: lem.rx * scaleR,
      ry: lem.ry * scaleR
    };

    // Sample points around the slice ellipse that lie OUTSIDE the front cut face (s=0)
    let pts = [];
    let angleSteps = Math.max(28, Math.floor(96 * scaleR));
    for (let i = 0; i <= angleSteps; i++) {
      let phi = domeAngle - lem.rad - Math.PI * 0.92 + (i / angleSteps) * Math.PI * 1.84;
      let p = pointOnLemonSlice(lem, sl, phi);
      let loc0 = toLocalEllipse(p[0], p[1], lem.cx, lem.cy, lem.rx * 0.992, lem.ry * 0.992, lem.cosA, lem.sinA, lem.id);
      if (loc0.r >= 1.0) {
        pts.push([p[0], p[1], phi]);
      } else if (pts.length > 2) {
        flushRindArc(batcher, lem, pts, s, isSubRing, rIdx);
        pts = [];
      } else {
        pts = [];
      }
    }
    if (pts.length > 2) {
      flushRindArc(batcher, lem, pts, s, isSubRing, rIdx);
    }
  }

  // 2. Longitudinal meridian stitch arcs near the nipple apex & core shadow for extra 3D curvature
  for (let m = 0; m < 26; m++) {
    let phi = domeAngle - lem.rad - Math.PI * 0.58 + (m / 25) * Math.PI * 1.16;
    let pts = [];
    for (let i = 2; i < lem.slices.length; i += 2) {
      let sl = lem.slices[i];
      let p = pointOnLemonSlice(lem, sl, phi);
      let loc0 = toLocalEllipse(p[0], p[1], lem.cx, lem.cy, lem.rx * 0.995, lem.ry * 0.995, lem.cosA, lem.sinA, lem.id);
      if (loc0.r >= 1.0) pts.push(p);
    }
    if (pts.length > 3) {
      batcher.addPathStitches(
        pts,
        (x, y, u) => {
          let style = evaluateRindPointStyle(lem, x, y, u * 0.8 + 0.15, true);
          if (!style || style.skip) return { skip: true };
          style.layer = 4;
          style.dashLen = 5.0;
          style.gapLen = 4.2;
          return style;
        },
        { dashLen: 5.0, gapLen: 4.2, jitter: 0.3, phase: (m * 0.29) % 1 }
      );
    }
  }
}

function flushRindArc(batcher, lem, pts, s, isSubRing, rIdx) {
  batcher.addPathStitches(
    pts,
    (x, y) => evaluateRindPointStyle(lem, x, y, s, isSubRing),
    { dashLen: 6.2, gapLen: 3.4, jitter: 0.28, phase: (rIdx * 0.41) % 1 }
  );
}

function evaluateRindPointStyle(lem, x, y, s, isSubRing) {
  // Approximate 3D surface normal on the lemon dome
  let domeMidX = lem.cx + lem.domeDx * 0.45;
  let domeMidY = lem.cy + lem.domeDy * 0.45;
  let nx = (x - domeMidX) / (lem.rx * 1.05);
  let ny = (y - domeMidY) / (lem.ry * 1.05);
  let r2 = nx * nx + ny * ny;
  let nz = Math.sqrt(Math.max(0.05, 1.15 - Math.min(1.1, r2 * 0.75)));

  // Perturb normal with high-frequency citrus oil-gland pore dimples
  let pore = Math.sin(x * 0.38) * Math.cos(y * 0.38) + (noise(x * 0.09, y * 0.09) - 0.5) * 1.6;
  nx += pore * 0.14;
  ny += pore * 0.14;
  let nLen = Math.hypot(nx, ny, nz) || 1;
  nx /= nLen; ny /= nLen; nz /= nLen;

  let ndotl = nx * LIGHT.x + ny * LIGHT.y + nz * LIGHT.z;

  // Rim bounce light along the bottom-right edge of the rind from the pale cotton cloth
  let isLowerRim = (nx * 0.55 + ny * 0.65 > 0.42) && s > 0.32;
  let bounce = isLowerRim ? Math.max(0, (nx * 0.55 + ny * 0.65 - 0.42) * 1.3) : 0;

  // Green zest nuance near the nipple apex (s > 0.78) and calyx end
  let greenFactor = s > 0.76 ? Math.pow((s - 0.76) / 0.24, 1.3) : 0;

  // Skip sub-rings on bright sunlit skin so density builds form in the shadows
  if (isSubRing && ndotl > 0.32 && greenFactor < 0.3 && pore < 0.45) {
    return { skip: true, stepOverride: 10 };
  }

  let col = PALETTE.cadmiumLemon;
  let weight = 0.56;
  let dash = 6.2;
  let gap = 3.4;
  let layer = isSubRing ? 4 : 3;

  if (ndotl > 0.52) {
    // Bright sunlit rind with glistening oil-gland highlights
    if (pore > 0.42) {
      col = PALETTE.pithCream;
      weight = 0.62;
    } else if (greenFactor > 0.4 && random() < 0.55) {
      col = PALETTE.greenZest;
    } else {
      col = random() < 0.55 ? PALETTE.cadmiumLemon : PALETTE.lemonPale;
    }
    dash = 6.4;
    gap = 3.8;
  } else if (ndotl > 0.18) {
    // Rich golden citrus midtone
    let r = random();
    if (greenFactor > 0.35 && r < 0.5) {
      col = r < 0.25 ? PALETTE.greenLeaf : PALETTE.greenZest;
    } else if (pore < -0.3) {
      col = PALETTE.saffronVivid;
    } else {
      col = r < 0.52 ? PALETTE.cadmiumRich : (r < 0.85 ? PALETTE.cadmiumLemon : PALETTE.saffronGold);
    }
    weight = 0.58;
    dash = 6.2;
    gap = 3.2;
  } else if (ndotl > -0.14) {
    // Turning into core shadow: saffron, leaf green & faded madder pink
    let r = random();
    if (greenFactor > 0.25 && r < 0.45) {
      col = r < 0.22 ? PALETTE.greenRich : PALETTE.greenLeaf;
    } else {
      col = r < 0.45 ? PALETTE.saffronVivid : (r < 0.76 ? PALETTE.saffronDeep : PALETTE.madderPink);
    }
    weight = 0.64;
    dash = 5.8;
    gap = 2.7;
  } else {
    // Deep core shadow on the belly of the rind + warm cloth bounce light at the bottom edge
    if (bounce > 0.22 && random() < 0.62) {
      col = random() < 0.55 ? PALETTE.saffronGold : PALETTE.madderSoft;
      weight = 0.58;
    } else {
      let r = random();
      if (greenFactor > 0.2 && r < 0.38) {
        col = PALETTE.greenDeep;
      } else {
        col = r < 0.38 ? PALETTE.indigoDeep : (r < 0.68 ? PALETTE.madderRich : (r < 0.88 ? PALETTE.saffronUmber : PALETTE.indigoAbyss));
      }
      weight = 0.72;
    }
    dash = 5.5;
    gap = 2.3;
  }

  return {
    layer,
    brush: "kantha",
    color: col,
    weight,
    dashLen: dash,
    gapLen: gap
  };
}

// LAYERS 5 to 10: Cut Face Anatomy (Outer Zest, Spongy Pith, Concentric Pulp Arcs, Radial Septa, Seeds & Wet Specular Glints)
function generateLemonCutFaceStitches(batcher, lem) {
  let sl0 = lem.slices[0];

  // 1. LAYER 5: Outer Flavedo (Zest Rim, r in [0.955, 1.0]) & Spongy Albedo (Pith Ring, r in [0.855, 0.955])
  let rimRadii = [0.995, 0.972, 0.945, 0.918, 0.892, 0.868];
  for (let idx = 0; idx < rimRadii.length; idx++) {
    let rNorm = rimRadii[idx];
    let isZest = rNorm >= 0.955;
    let pts = [];
    let steps = 96;
    for (let i = 0; i <= steps; i++) {
      let phi = (i / steps) * Math.PI * 2;
      let p = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * rNorm, ry: lem.ry * rNorm }, phi);
      pts.push(p);
    }

    batcher.addPathStitches(
      pts,
      (x, y, u) => {
        let ang = u * Math.PI * 2 + lem.rad;
        let lightSide = Math.cos(ang) * LIGHT.x + Math.sin(ang) * LIGHT.y; // > 0 on upper-left
        let col, weight;

        if (isZest) {
          if (lightSide > 0.15) {
            col = random() < 0.6 ? PALETTE.cadmiumLemon : PALETTE.saffronGold;
            weight = 0.62;
          } else if (lightSide > -0.25) {
            col = random() < 0.45 ? PALETTE.saffronVivid : (random() < 0.5 ? PALETTE.greenLeaf : PALETTE.cadmiumRich);
            weight = 0.65;
          } else {
            col = random() < 0.45 ? PALETTE.greenRich : (random() < 0.5 ? PALETTE.saffronDeep : PALETTE.indigoDeep);
            weight = 0.70;
          }
        } else {
          // Spongy white albedo pith ring
          if (lightSide > 0.0) {
            col = random() < 0.65 ? PALETTE.pithCream : (random() < 0.6 ? PALETTE.lemonPale : PALETTE.madderBlush);
            weight = 0.48;
          } else {
            col = random() < 0.45 ? PALETTE.madderBlush : (random() < 0.55 ? PALETTE.cottonMid : PALETTE.indigoPale);
            weight = 0.50;
          }
        }

        return {
          layer: 5,
          brush: "kantha",
          color: col,
          weight,
          dashLen: isZest ? 6.0 : 5.5,
          gapLen: isZest ? 2.8 : 3.8
        };
      },
      { dashLen: 5.8, gapLen: 3.4, jitter: 0.25, phase: idx * 0.31 }
    );
  }

  // 2. LAYERS 6 & 7: Concentric Arcs across each of the Pulp Segments (Carpels)
  for (let seg of lem.segments) {
    generateSegmentPulpArcs(batcher, lem, seg);
  }

  // 3. LAYER 8: Radial Lines along each Segment Wall (Septa) + Triangular Outer Pith Gussets + Central Core
  for (let seg of lem.segments) {
    let aWall = seg.a0;
    // Draw 3 tightly spaced radial kantha rows along each fibrous membrane wall
    let wallOffsets = [-0.011, 0, 0.011];
    for (let wIdx = 0; wIdx < wallOffsets.length; wIdx++) {
      let da = wallOffsets[wIdx];
      let pts = [];
      let rStart = 0.11;
      let rEnd = 0.885;
      for (let step = 0; step <= 18; step++) {
        let r = rStart + (step / 18) * (rEnd - rStart);
        // Slight organic S-curve in the radial membrane
        let bend = Math.sin(r * Math.PI) * 0.018 * Math.cos(seg.index * 1.9);
        let phi = aWall + da / Math.max(0.25, r) + bend;
        let p = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * r, ry: lem.ry * r }, phi);
        pts.push(p);
      }

      batcher.addPathStitches(
        pts,
        (x, y, u) => {
          let isCenterLine = (wIdx === 1);
          let col = isCenterLine
            ? (random() < 0.78 ? PALETTE.pithCream : PALETTE.specularWhite)
            : (random() < 0.55 ? PALETTE.lemonPale : PALETTE.madderBlush);
          return {
            layer: 8,
            brush: "kantha",
            color: col,
            weight: isCenterLine ? 0.62 : 0.44,
            dashLen: 5.2,
            gapLen: 2.4
          };
        },
        { dashLen: 5.2, gapLen: 2.4, jitter: 0.18, phase: wIdx * 0.33 }
      );
    }

    // Triangular pith gusset stitches where the septum wall flares into the outer pith ring
    for (let g = 1; g <= 3; g++) {
      let rG = 0.81 + g * 0.022;
      let span = (0.045 - g * 0.008);
      let gPts = [];
      for (let s = -3; s <= 3; s++) {
        let phi = aWall + (s / 3) * span;
        gPts.push(pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * rG, ry: lem.ry * rG }, phi));
      }
      batcher.addPathStitches(
        gPts,
        () => ({
          layer: 8,
          brush: "kantha",
          color: random() < 0.7 ? PALETTE.pithCream : PALETTE.madderBlush,
          weight: 0.48,
          dashLen: 4.2,
          gapLen: 2.2
        }),
        { dashLen: 4.2, gapLen: 2.2, jitter: 0.15 }
      );
    }
  }

  // Central Columella (Spongy Pith Core, r in [0.02, 0.145])
  let coreRings = [0.14, 0.105, 0.07, 0.035];
  for (let cIdx = 0; cIdx < coreRings.length; cIdx++) {
    let rC = coreRings[cIdx];
    let pts = [];
    let steps = Math.max(12, Math.floor(36 * (rC / 0.14)));
    for (let i = 0; i <= steps; i++) {
      let phi = (i / steps) * Math.PI * 2;
      let starMod = 1 + 0.12 * Math.cos(lem.numSegs * phi);
      pts.push(pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * rC * starMod, ry: lem.ry * rC * starMod }, phi));
    }
    batcher.addPathStitches(
      pts,
      () => {
        let col = cIdx < 2
          ? (random() < 0.7 ? PALETTE.pithCream : PALETTE.madderBlush)
          : (random() < 0.45 ? PALETTE.saffronGold : (random() < 0.5 ? PALETTE.greenLeaf : PALETTE.madderPink));
        return {
          layer: 8,
          brush: "kantha",
          color: col,
          weight: 0.52,
          dashLen: 4.0,
          gapLen: 2.2
        };
      },
      { dashLen: 4.0, gapLen: 2.2, jitter: 0.2 }
    );
  }

  // 4. LAYER 9: Cut & Whole Lemon Seeds nestled in the pulp
  for (let seg of lem.segments) {
    if (seg.seed) {
      drawLemonSeedInSegment(batcher, lem, seg);
    }
  }

  // 5. LAYER 10: Glistening Wet Juice Bead Specular Highlights & Frayed Pith Fibres
  generateGlisteningPulpHighlights(batcher, lem);
}

// Helper: Generate the dense concentric arcs across a single citrus segment wedge
function generateSegmentPulpArcs(batcher, lem, seg) {
  let dAlpha = seg.a1 - seg.a0;
  let midWorldAng = (seg.a0 + seg.a1) * 0.5 + lem.rad;
  let segDirX = Math.cos(midWorldAng), segDirY = Math.sin(midWorldAng);

  // Whether this segment is on the upper-left (rim-shadowed inside wall) or lower-right (transmitted glow)
  let dotLight = segDirX * LIGHT.x + segDirY * LIGHT.y;

  let numArcs = 34; // Dense concentric rows so form & vesicles resolve with high contrast
  for (let aIdx = 0; aIdx <= numArcs; aIdx++) {
    let rho = aIdx / numArcs; // 0 = inner core tip, 1 = outer pith arch
    let isSubArc = (aIdx % 2 === 1);

    let pts = [];
    let arcSteps = Math.max(8, Math.floor(8 + rho * 20));
    let padT = 0.045 + (1 - rho) * 0.05;

    for (let s = 0; s <= arcSteps; s++) {
      let t = padT + (s / arcSteps) * (1 - 2 * padT);
      let sinT = Math.sin(Math.PI * t);

      // Anatomically accurate rounded inner tip and rounded outer carpel corners
      let rMin = 0.145 + 0.065 * (1 - Math.pow(Math.max(0.001, sinT), 0.48));
      let rMax = 0.852 - 0.088 * (1 - Math.pow(Math.max(0.001, sinT), 0.42));
      let r = rMin + rho * (rMax - rMin);

      let bend = Math.sin(r * Math.PI) * 0.018 * Math.cos(seg.index * 1.9);
      let phi = seg.a0 + t * dAlpha + bend;
      let p = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * r, ry: lem.ry * r }, phi);
      pts.push([p[0], p[1], rho, t]);
    }

    batcher.addPathStitches(
      pts,
      (x, y, uParam) => {
        let t = padT + uParam * (1 - 2 * padT);

        // If this segment has a seed, skip pulp arcs inside the seed body
        if (seg.seed) {
          let sDist = Math.hypot((rho - seg.seed.rho) / 0.13, (t - seg.seed.t) / 0.24);
          if (sDist < 0.88) return { skip: true, stepOverride: 5 };
        }

        // Evaluate 3D depth & vesicle illumination inside the segment pocket
        let edgeDist = Math.min(t, 1 - t, rho * 0.85, (1 - rho) * 1.1);
        let pocketRecess = Math.exp(-edgeDist / 0.11); // Dark moist recess along membranes & outer pith

        // Rim shadow cast by the opaque white septum wall onto the recessed translucent pulp
        let wallShadow = (dotLight > -0.1 && t < 0.26) ? Math.exp(-t / 0.14) * 0.55 : 0;

        // Evaluate nearest juice vesicle (saccule)
        let bestVesDist = 999;
        let vesRidge = 0;
        let vesTrough = 0;
        for (let v of seg.vesicles) {
          let dr = (rho - v.rho) / v.drho;
          let dt = (t - v.t) / v.dt;
          let d = Math.hypot(dr, dt);
          if (d < bestVesDist) {
            bestVesDist = d;
            // Upper-left slope of vesicle catches specular light; border is dark translucent trough
            let slopeLight = (-dr * 0.55 - dt * 0.45);
            vesRidge = d < 0.72 ? (1 - d / 0.72) * (0.6 + slopeLight * 0.5) * v.gloss : 0;
            vesTrough = (d >= 0.72 && d < 1.18) ? 1.0 : 0;
          }
        }

        // Seed pocket shadow right around a seed
        let seedShadow = 0;
        if (seg.seed) {
          let sDist = Math.hypot((rho - seg.seed.rho) / 0.13, (t - seg.seed.t) / 0.24);
          if (sDist >= 0.88 && sDist < 1.35) seedShadow = 0.75;
        }

        let darkness =
          pocketRecess * 0.65 +
          wallShadow +
          vesTrough * 0.42 +
          seedShadow -
          vesRidge * 0.55 -
          (dotLight < 0 ? 0.18 : 0); // Subsurface transmitted glow on lower-right segments

        // Skip odd sub-arcs in bright glowing mid-pulp so dark recesses & troughs pack denser stitches
        if (isSubArc && darkness < 0.35 && vesRidge < 0.48) {
          return { skip: true, stepOverride: 6.5 };
        }

        let col = PALETTE.saffronGold;
        let weight = 0.54;
        let dash = 5.0;
        let gap = 2.6;
        let layer = isSubArc ? 7 : 6;

        if (darkness > 0.78) {
          // Deepest moist pulp crevices: high-contrast abyssal indigo, dark madder crimson & burnt saffron
          let r = random();
          col = r < 0.42 ? PALETTE.indigoDeep : (r < 0.78 ? PALETTE.madderDark : PALETTE.saffronUmber);
          weight = 0.68;
          dash = 4.6;
          gap = 1.9;
        } else if (darkness > 0.48) {
          // Rich translucent amber & madder troughs between juice vesicles
          let r = random();
          col = r < 0.42 ? PALETTE.saffronDeep : (r < 0.75 ? PALETTE.madderRich : PALETTE.saffronUmber);
          weight = 0.60;
          dash = 4.8;
          gap = 2.2;
        } else if (darkness > 0.22) {
          // Vibrant golden saffron & madder-blush citrus pulp
          let r = random();
          col = r < 0.48 ? PALETTE.saffronVivid : (r < 0.82 ? PALETTE.saffronGold : PALETTE.madderPink);
          weight = 0.54;
          dash = 5.2;
          gap = 2.6;
        } else if (vesRidge > 0.45) {
          // Glistening sunlit juice vesicle crown
          col = random() < 0.52 ? PALETTE.lemonPale : (random() < 0.6 ? PALETTE.cadmiumLemon : PALETTE.pithCream);
          weight = 0.58;
          dash = 4.8;
          gap = 2.4;
        } else {
          // Radiant cadmium lemon subsurface glow
          col = random() < 0.58 ? PALETTE.cadmiumLemon : PALETTE.cadmiumRich;
          weight = 0.52;
          dash = 5.2;
          gap = 2.8;
        }

        return {
          layer,
          brush: "kantha",
          color: col,
          weight,
          dashLen: dash,
          gapLen: gap
        };
      },
      { dashLen: 5.0, gapLen: 2.5, jitter: 0.22, phase: (aIdx * 0.39 + seg.index * 0.17) % 1 }
    );
  }
}

// Draw a plump teardrop lemon seed nestled inside a segment pocket
function drawLemonSeedInSegment(batcher, lem, seg) {
  let dAlpha = seg.a1 - seg.a0;
  let rhoC = seg.seed.rho;
  let tC = seg.seed.t;
  let rC = 0.15 + rhoC * 0.68;
  let phiC = seg.a0 + tC * dAlpha;
  let center = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * rC, ry: lem.ry * rC }, phiC);

  let seedAng = phiC + lem.rad;
  let cosS = Math.cos(seedAng), sinS = Math.sin(seedAng);

  // Concentric teardrop rings from outer dark pocket rim to ivory seed crest
  let scales = [1.18, 0.98, 0.76, 0.52, 0.28];
  for (let sIdx = 0; sIdx < scales.length; sIdx++) {
    let sc = scales[sIdx];
    let pts = [];
    let steps = 18;
    for (let i = 0; i <= steps; i++) {
      let a = (i / steps) * Math.PI * 2;
      // Teardrop pinch toward the inner core (cos(a) < 0)
      let pinch = Math.cos(a) < 0 ? 1 + 0.28 * Math.pow(-Math.cos(a), 1.5) : 1;
      let lx = seg.seed.rx * sc * Math.cos(a) * pinch;
      let ly = seg.seed.ry * sc * Math.sin(a) * (1 - 0.18 * Math.max(0, -Math.cos(a)));
      pts.push([
        center[0] + lx * cosS - ly * sinS,
        center[1] + lx * sinS + ly * cosS,
        a
      ]);
    }

    batcher.addPathStitches(
      pts,
      (x, y, u) => {
        if (sIdx === 0) {
          // Dark moist pocket rim around seed
          return {
            layer: 9,
            brush: "kantha",
            color: random() < 0.55 ? PALETTE.indigoAbyss : PALETTE.madderDark,
            weight: 0.65,
            dashLen: 4.0,
            gapLen: 2.0
          };
        }
        let isTip = Math.abs(u - 0.5) < 0.14;
        let col = isTip && sIdx === 1
          ? PALETTE.greenLeaf
          : (sIdx >= 3 ? PALETTE.specularWhite : (random() < 0.65 ? PALETTE.pithCream : PALETTE.lemonPale));
        return {
          layer: 9,
          brush: "kantha",
          color: col,
          weight: sIdx >= 3 ? 0.60 : 0.50,
          dashLen: 3.8,
          gapLen: 1.8
        };
      },
      { dashLen: 3.8, gapLen: 1.8, jitter: 0.12 }
    );
  }
}

// LAYER 10: Razor-sharp wet specular juice bead glints & delicate pith fibres
function generateGlisteningPulpHighlights(batcher, lem) {
  for (let seg of lem.segments) {
    let dAlpha = seg.a1 - seg.a0;

    // 1. Wet specular bead glints on the brightest vesicles of each segment
    for (let v of seg.vesicles) {
      if (v.gloss < 0.62) continue;
      if (seg.seed && Math.hypot((v.rho - seg.seed.rho) / 0.15, (v.t - seg.seed.t) / 0.26) < 1.1) continue;

      let sinT = Math.sin(Math.PI * v.t);
      let rMin = 0.145 + 0.065 * (1 - Math.pow(Math.max(0.001, sinT), 0.48));
      let rMax = 0.852 - 0.088 * (1 - Math.pow(Math.max(0.001, sinT), 0.42));
      let r = rMin + v.rho * (rMax - rMin);
      let phi = seg.a0 + v.t * dAlpha;

      // Tiny curved specular bead highlight + dark micro-rim right underneath
      let spanA = 0.038 / Math.max(0.25, r);
      let p1 = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * r, ry: lem.ry * r }, phi - spanA * 0.5);
      let p2 = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * (r + 0.008), ry: lem.ry * (r + 0.008) }, phi + spanA * 0.5);

      // Dark amber/indigo micro-contrast dash immediately adjacent to the white glint
      let pDark1 = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * (r - 0.015), ry: lem.ry * (r - 0.015) }, phi - spanA * 0.45);
      let pDark2 = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * (r - 0.008), ry: lem.ry * (r - 0.008) }, phi + spanA * 0.45);

      batcher.add(
        9,
        "kantha",
        random() < 0.5 ? PALETTE.madderDark : PALETTE.saffronUmber,
        0.62,
        pDark1[0], pDark1[1], pDark2[0], pDark2[1]
      );

      // Pure white / cream wet specular dash
      batcher.add(
        10,
        "kantha",
        v.gloss > 0.78 ? PALETTE.specularWhite : PALETTE.pithCream,
        0.68,
        p1[0], p1[1], p2[0], p2[1]
      );
    }

    // 2. Delicate frayed pith fibres extending from the septum walls & outer pith over the dark pulp recess
    for (let f = 0; f < 14; f++) {
      let r = 0.18 + (f / 13) * 0.65;
      let side = (f % 2 === 0) ? 0 : 1;
      let basePhi = side === 0 ? seg.a0 + 0.012 : seg.a1 - 0.012;
      let dir = side === 0 ? 1 : -1;

      let pStart = pointOnLemonSlice(lem, { cx: lem.cx, cy: lem.cy, rx: lem.rx * r, ry: lem.ry * r }, basePhi);
      let pEnd = pointOnLemonSlice(
        lem,
        { cx: lem.cx, cy: lem.cy, rx: lem.rx * (r + random(-0.018, 0.018)), ry: lem.ry * (r + random(-0.018, 0.018)) },
        basePhi + dir * (0.025 + random(0.015)) / Math.max(0.3, r)
      );

      batcher.add(
        10,
        "kantha",
        random() < 0.7 ? PALETTE.pithCream : PALETTE.lemonPale,
        0.44,
        pStart[0], pStart[1], pEnd[0], pEnd[1]
      );
    }
  }
}

// LAYER 9 & 10: Loose glistening juice droplets & fallen seed on the cotton cloth
function generateClothIncidents(batcher) {
  // 1. Juice droplets & loose vesicles on the cloth
  for (let d of juiceDrops) {
    let rad = (d.rot * Math.PI) / 180;
    let c = Math.cos(rad), s = Math.sin(rad);

    // Tiny dark indigo/madder cast shadow on the bottom-right of each droplet
    let shPts = [];
    for (let deg = -20; deg <= 140; deg += 20) {
      let a = (deg * Math.PI) / 180;
      let lx = (d.rx + 2.5) * Math.cos(a) + 3.5;
      let ly = (d.ry + 2.0) * Math.sin(a) + 3.0;
      shPts.push([d.x + lx * c - ly * s, d.y + lx * s + ly * c]);
    }
    batcher.addPathStitches(
      shPts,
      () => ({
        layer: 9,
        brush: "kantha",
        color: PALETTE.indigoAbyss,
        weight: 0.65,
        dashLen: 3.8,
        gapLen: 1.8
      }),
      { dashLen: 3.8, gapLen: 1.8, jitter: 0.1 }
    );

    // Concentric rings inside the juice bead (saffron/cadmium body + bright white top-left glint)
    let rings = [1.0, 0.68, 0.36];
    for (let rIdx = 0; rIdx < rings.length; rIdx++) {
      let sc = rings[rIdx];
      let pts = [];
      for (let i = 0; i <= 14; i++) {
        let a = (i / 14) * Math.PI * 2;
        let lx = d.rx * sc * Math.cos(a);
        let ly = d.ry * sc * Math.sin(a);
        pts.push([d.x + lx * c - ly * s, d.y + lx * s + ly * c]);
      }
      batcher.addPathStitches(
        pts,
        (x, y, u) => {
          let isLitCrest = u > 0.52 && u < 0.88;
          let col = rIdx === 2 && isLitCrest
            ? PALETTE.specularWhite
            : (isLitCrest ? PALETTE.cadmiumLemon : (rIdx === 0 ? PALETTE.saffronDeep : PALETTE.saffronGold));
          return {
            layer: rIdx === 2 ? 10 : 9,
            brush: "kantha",
            color: col,
            weight: 0.56,
            dashLen: 3.6,
            gapLen: 1.6
          };
        },
        { dashLen: 3.6, gapLen: 1.6, jitter: 0.1 }
      );
    }

    // Crisp specular white stitch on the upper-left crown of the juice bead
    batcher.add(
      10,
      "kantha",
      PALETTE.specularWhite,
      0.72,
      d.x - d.rx * 0.45,
      d.y - d.ry * 0.35,
      d.x + d.rx * 0.15,
      d.y - d.ry * 0.52
    );
  }

  // 2. Plump fallen seed resting on the cloth
  for (let sd of fallenSeeds) {
    let rad = (sd.rot * Math.PI) / 180;
    let c = Math.cos(rad), s = Math.sin(rad);

    // Dark contact shadow beneath the fallen seed
    for (let k = 0; k < 2; k++) {
      let shPts = [];
      for (let deg = -10; deg <= 155; deg += 18) {
        let a = (deg * Math.PI) / 180;
        let lx = (sd.rx + 2 + k * 2.5) * Math.cos(a) + 4;
        let ly = (sd.ry + 1.5 + k * 2) * Math.sin(a) + 3.5;
        shPts.push([sd.x + lx * c - ly * s, sd.y + lx * s + ly * c]);
      }
      batcher.addPathStitches(
        shPts,
        () => ({
          layer: 9,
          brush: "kantha",
          color: k === 0 ? PALETTE.indigoAbyss : PALETTE.madderDark,
          weight: 0.65,
          dashLen: 4.0,
          gapLen: 1.8
        }),
        { dashLen: 4.0, gapLen: 1.8, jitter: 0.1 }
      );
    }

    // Concentric teardrop rings of the fallen seed
    let scales = [1.0, 0.74, 0.48, 0.24];
    for (let sIdx = 0; sIdx < scales.length; sIdx++) {
      let sc = scales[sIdx];
      let pts = [];
      for (let i = 0; i <= 16; i++) {
        let a = (i / 16) * Math.PI * 2;
        let pinch = Math.cos(a) < 0 ? 1 + 0.28 * Math.pow(-Math.cos(a), 1.5) : 1;
        let lx = sd.rx * sc * Math.cos(a) * pinch;
        let ly = sd.ry * sc * Math.sin(a) * (1 - 0.18 * Math.max(0, -Math.cos(a)));
        pts.push([sd.x + lx * c - ly * s, sd.y + lx * s + ly * c]);
      }
      batcher.addPathStitches(
        pts,
        (x, y, u) => {
          let col = sIdx === 0
            ? (u < 0.45 ? PALETTE.saffronDeep : PALETTE.madderSoft)
            : (sIdx >= 2 ? PALETTE.pithCream : PALETTE.lemonPale);
          return {
            layer: 9,
            brush: "kantha",
            color: col,
            weight: 0.56,
            dashLen: 3.8,
            gapLen: 1.7
          };
        },
        { dashLen: 3.8, gapLen: 1.7, jitter: 0.12 }
      );
    }

    // Wet specular highlight dash on the fallen seed
    batcher.add(
      10,
      "kantha",
      PALETTE.specularWhite,
      0.68,
      sd.x - 4,
      sd.y - 3,
      sd.x + 3,
      sd.y - 1
    );
  }
}

function draw() {
  translate(-width / 2, -height / 2);

  // Pale unbleached-cotton ground
  background(PALETTE.ground);

  // 1. Faint watercolor underpainting (batched by color for organic bleed & luminosity)
  drawWatercolorUnderpainting();

  // 2. Build all kantha running-stitch layers in back-to-front order
  let batcher = new StitchBatcher();

  generateCottonWeave(batcher);
  generateClothKanthaStitches(batcher);

  for (let lem of lemons) {
    generateLemonRindStitches(batcher, lem);
    generateLemonCutFaceStitches(batcher, lem);
  }

  generateClothIncidents(batcher);

  // 3. Render all batched kantha stitch dashes
  batcher.render();

  noLoop();
}

