// ============================================================================
// SAFE P5.BRUSH WRAPPERS (Guarantees brush.set() before any stroke operation)
// ============================================================================

function fillPoly(pts, col, opacity = 120, bleed = 0.2, tex = 0.5, border = 0.45, curv = 0.12) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function washPoly(pts, col, opacity = 120, curv = 0) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, opacity);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function strokeLine(x1, y1, x2, y2, bName, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(bName, col, weight);
  brush.line(x1, y1, x2, y2);
}

function strokeSpline(pts, bName, col, weight = 1, curv = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(bName, col, weight);
  brush.spline(pts, curv);
}

function strokePoly(pts, bName, col, weight = 1, close = true, curv = 0.08) {
  if (!pts || pts.length < 2) return;
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(bName, col, weight);
  brush.beginShape(curv);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(close);
}

// ============================================================================
// GEOMETRY HELPERS
// ============================================================================

function makeEllipsePts(cx, cy, rx, ry, rotDeg, n = 32, noiseAmp = 0) {
  let pts = [];
  let ca = cos(rotDeg), sa = sin(rotDeg);
  for (let i = 0; i < n; i++) {
    let a = (i / n) * 360;
    let nv = noiseAmp > 0 ? (noise(cx * 0.01 + cos(a) * 1.3, cy * 0.01 + sin(a) * 1.3) - 0.5) * 2 * noiseAmp : 0;
    let lx = (rx + nv) * cos(a);
    let ly = (ry + nv) * sin(a);
    pts.push([cx + lx * ca - ly * sa, cy + lx * sa + ly * ca]);
  }
  return pts;
}

function rotPt(x, y, cx, cy, deg) {
  let ca = cos(deg), sa = sin(deg);
  let dx = x - cx, dy = y - cy;
  return [cx + dx * ca - dy * sa, cy + dx * sa + dy * ca];
}

// ============================================================================
// 1. COTTON GROUND & KALAMKARI BORDER
// ============================================================================

function drawCottonGroundAndBorder() {
  background(PAL.ecruBase);

  // Uneven hand-mordanted myrobalan & cool indigo-alum cloth washes
  fillPoly(makeEllipsePts(600, 600, 620, 620, 0, 28, 35), PAL.ecruWarm, 65, 0.45, 0.65, 0.3);
  fillPoly(makeEllipsePts(260, 240, 380, 290, -20, 24, 30), PAL.ecruCool, 75, 0.48, 0.6, 0.35);
  fillPoly(makeEllipsePts(960, 280, 340, 310, 15, 24, 30), PAL.indigoPale, 42, 0.5, 0.65, 0.4);
  fillPoly(makeEllipsePts(240, 960, 360, 280, 25, 24, 30), PAL.indigoPale, 48, 0.5, 0.65, 0.4);
  fillPoly(makeEllipsePts(940, 950, 390, 320, -18, 24, 30), PAL.ecruWarm, 70, 0.45, 0.6, 0.35);

  // Subtle ambient indigo halo behind the still life
  fillPoly(makeEllipsePts(590, 610, 490, 410, -14, 32, 25), PAL.indigoPale, 55, 0.45, 0.6, 0.45);

  // Hand-spun cotton warp & weft threads across the ground
  for (let y = 18; y < 1185; y += 11) {
    let jitter = (noise(y * 0.05) - 0.5) * 3;
    let col = y % 22 === 0 ? PAL.cottonThreadDark : PAL.cottonThreadLight;
    strokeLine(15, y + jitter, 1185, y - jitter, "cotton_weave", col, 0.85);
  }
  for (let x = 18; x < 1185; x += 13) {
    let jitter = (noise(x * 0.05 + 50) - 0.5) * 3;
    let col = x % 26 === 0 ? PAL.cottonThreadDark : PAL.cottonThreadLight;
    strokeLine(x + jitter, 15, x - jitter, 1185, "cotton_weave", col, 0.75);
  }

  // Traditional Kalamkari double-ruled dye border with madder & indigo band
  let m1 = 34, m2 = 54, m3 = 62;
  // Madder red outer border wash strips
  washPoly([[m1, m1], [1200 - m1, m1], [1200 - m1, m2], [m1, m2]], PAL.madderRed, 115);
  washPoly([[m1, 1200 - m2], [1200 - m1, 1200 - m2], [1200 - m1, 1200 - m1], [m1, 1200 - m1]], PAL.madderRed, 115);
  washPoly([[m1, m2], [m2, m2], [m2, 1200 - m2], [m1, 1200 - m2]], PAL.madderRed, 115);
  washPoly([[1200 - m2, m2], [1200 - m1, m2], [1200 - m1, 1200 - m2], [1200 - m2, 1200 - m2]], PAL.madderRed, 115);

  // Narrow indigo inner border wash
  washPoly([[m2, m2], [1200 - m2, m2], [1200 - m2, m3], [m2, m3]], PAL.indigoDeep, 95);
  washPoly([[m2, 1200 - m3], [1200 - m2, 1200 - m3], [1200 - m2, 1200 - m2], [m2, 1200 - m2]], PAL.indigoDeep, 95);
  washPoly([[m2, m3], [m3, m3], [m3, 1200 - m3], [m2, 1200 - m3]], PAL.indigoDeep, 95);
  washPoly([[1200 - m3, m3], [1200 - m2, m3], [1200 - m2, 1200 - m3], [1200 - m3, 1200 - m3]], PAL.indigoDeep, 95);

  // Iron-black kalam border rulings
  let rects = [m1, m2, m3];
  for (let r of rects) {
    strokeLine(r, r, 1200 - r, r, "kalam", PAL.kalamBlack, 0.95);
    strokeLine(1200 - r, r, 1200 - r, 1200 - r, "kalam", PAL.kalamBlack, 0.95);
    strokeLine(1200 - r, 1200 - r, r, 1200 - r, "kalam", PAL.kalamBlack, 0.95);
    strokeLine(r, 1200 - r, r, r, "kalam", PAL.kalamBlack, 0.95);
  }

  // Stylized Kalamkari geometric diamond & dot repeat inside the madder border band
  let midB = (m1 + m2) * 0.5;
  for (let pos = 76; pos <= 1124; pos += 28) {
    // Top & bottom
    for (let by of [midB, 1200 - midB]) {
      let dPts = [[pos - 7, by], [pos, by - 5], [pos + 7, by], [pos, by + 5]];
      washPoly(dPts, PAL.ecruLight, 175);
      strokePoly(dPts, "kalam_fine", PAL.kalamBlack, 0.7, true, 0.05);
    }
    // Left & right
    for (let bx of [midB, 1200 - midB]) {
      let dPts = [[bx, pos - 7], [bx - 5, pos], [bx, pos + 7], [bx + 5, pos]];
      washPoly(dPts, PAL.ecruLight, 175);
      strokePoly(dPts, "kalam_fine", PAL.kalamBlack, 0.7, true, 0.05);
    }
  }
}

// ============================================================================
// 2. WOVEN MAT (CHATAI) IN MADDER RED, ALIZARIN & INDIGO
// ============================================================================

function drawWovenMat() {
  let mcx = 605, mcy = 675;
  let mAngle = -16;
  let halfU = 455, halfV = 365;
  let stripW = 22;

  function matPt(u, v) {
    // Subtle organic wave in the hand-woven reed mat
    let waveU = sin(v * 0.7 + u * 0.2) * 3.5;
    let waveV = cos(u * 0.6 - v * 0.3) * 3.5;
    return rotPt(mcx + u + waveU, mcy + v + waveV, mcx, mcy, mAngle);
  }

  // Deep cool indigo cast shadow under the mat edges on the ecru cotton
  let shadowCorners = [];
  for (let i = 0; i <= 12; i++) shadowCorners.push(matPt(-halfU + (i / 12) * 2 * halfU + 18, -halfV + 22));
  for (let i = 0; i <= 12; i++) shadowCorners.push(matPt(halfU + 22, -halfV + (i / 12) * 2 * halfV + 24));
  for (let i = 12; i >= 0; i--) shadowCorners.push(matPt(-halfU + (i / 12) * 2 * halfU + 20, halfV + 28));
  for (let i = 12; i >= 0; i--) shadowCorners.push(matPt(-halfU + 16, -halfV + (i / 12) * 2 * halfV + 24));
  fillPoly(shadowCorners, PAL.indigoDeep, 105, 0.38, 0.65, 0.55, 0.08);
  fillPoly(shadowCorners, PAL.indigoDark, 75, 0.25, 0.55, 0.5, 0.08);

  // Mat base polygon & translucent natural-dye madder/alizarin/indigo bands
  let matOutline = [
    matPt(-halfU, -halfV),
    matPt(halfU, -halfV),
    matPt(halfU, halfV),
    matPt(-halfU, halfV)
  ];
  fillPoly(matOutline, PAL.reedRaw, 180, 0.22, 0.55, 0.45, 0.05);
  fillPoly(matOutline, PAL.alizarinLight, 110, 0.28, 0.6, 0.5, 0.05);

  // Broad madder red & indigo dyed woven bands (authentic watercolor bleed)
  let bandDefs = [
    { v0: -365, v1: -255, col: PAL.madderRed, op: 135 },
    { v0: -255, v1: -190, col: PAL.indigoDeep, op: 130 },
    { v0: -190, v1: -40, col: PAL.alizarinCrimson, op: 130 },
    { v0: -40, v1: 25, col: PAL.indigoDeep, op: 125 },
    { v0: 25, v1: 185, col: PAL.madderRed, op: 140 },
    { v0: 185, v1: 250, col: PAL.indigoDeep, op: 135 },
    { v0: 250, v1: 365, col: PAL.alizarinCrimson, op: 140 }
  ];
  for (let b of bandDefs) {
    let bPts = [
      matPt(-halfU, b.v0),
      matPt(halfU, b.v0),
      matPt(halfU, b.v1),
      matPt(-halfU, b.v1)
    ];
    fillPoly(bPts, b.col, b.op, 0.24, 0.58, 0.48, 0.05);
  }

  // Individual 2/2 twill woven reed cells
  let nU = Math.floor((2 * halfU) / stripW);
  let nV = Math.floor((2 * halfV) / stripW);

  for (let iu = 0; iu < nU; iu++) {
    let u0 = -halfU + iu * stripW;
    let u1 = u0 + stripW;
    let uMid = (u0 + u1) * 0.5;

    for (let iv = 0; iv < nV; iv++) {
      let v0 = -halfV + iv * stripW;
      let v1 = v0 + stripW;
      let vMid = (v0 + v1) * 0.5;

      let pCenter = matPt(uMid, vMid);
      let px = pCenter[0], py = pCenter[1];

      // Skip deep interior cells completely buried under the opaque jackfruit core
      let dA = sq((px - 420) / 185) + sq((py - 430) / 125);
      let dB = sq((px - 730) / 215) + sq((py - 560) / 155);
      let dC = sq((px - 360) / 145) + sq((py - 760) / 100);
      if (dA < 0.72 || dB < 0.72 || dC < 0.68) continue;

      // 2/2 herringbone twill parity: does U-strip or V-strip ride on top?
      let uOnTop = ((iu + iv) % 4 < 2);

      // Determine strip dye color
      let cellCol;
      if (uOnTop) {
        if (iu % 7 === 0 || iu % 7 === 1) cellCol = PAL.madderRed;
        else if (iu % 7 === 4) cellCol = PAL.indigoDeep;
        else if (iu % 7 === 2 || iu % 7 === 6) cellCol = PAL.reedRaw;
        else cellCol = PAL.alizarinCrimson;
      } else {
        if (iv % 6 === 0 || iv % 6 === 1) cellCol = PAL.alizarinCrimson;
        else if (iv % 6 === 3) cellCol = PAL.indigoDeep;
        else if (iv % 6 === 4) cellCol = PAL.reedRaw;
        else cellCol = PAL.madderRed;
      }

      // Shadow modulation near the jackfruit heap
      let nearFruit = (dA < 1.35 || dB < 1.35 || dC < 1.35);

      let c00 = matPt(u0 + 0.8, v0 + 0.8);
      let c10 = matPt(u1 - 0.8, v0 + 0.8);
      let c11 = matPt(u1 - 0.8, v1 - 0.8);
      let c01 = matPt(u0 + 0.8, v1 - 0.8);

      washPoly([c00, c10, c11, c01], cellCol, nearFruit ? 145 : 110);
      if (nearFruit) {
        washPoly([c00, c10, c11, c01], PAL.indigoDark, 90);
      }

      // Fine longitudinal reed fibers inside the strip cell + kalam overlap edges
      if (uOnTop) {
        // Strip runs along U
        for (let f = 0.28; f <= 0.74; f += 0.23) {
          let p1 = matPt(u0 + 1, v0 + f * stripW);
          let p2 = matPt(u1 - 1, v0 + f * stripW);
          strokeLine(p1[0], p1[1], p2[0], p2[1], "kalam_fine", PAL.kalamBrown, 0.42);
        }
        // Long edges along U
        strokeLine(c00[0], c00[1], c10[0], c10[1], "kalam_fine", PAL.kalamBlack, 0.72);
        strokeLine(c01[0], c01[1], c11[0], c11[1], "kalam_fine", PAL.kalamBlack, 0.72);
      } else {
        // Strip runs along V
        for (let f = 0.28; f <= 0.74; f += 0.23) {
          let p1 = matPt(u0 + f * stripW, v0 + 1);
          let p2 = matPt(u0 + f * stripW, v1 - 1);
          strokeLine(p1[0], p1[1], p2[0], p2[1], "kalam_fine", PAL.kalamBrown, 0.42);
        }
        // Long edges along V
        strokeLine(c00[0], c00[1], c01[0], c01[1], "kalam_fine", PAL.kalamBlack, 0.72);
        strokeLine(c10[0], c10[1], c11[0], c11[1], "kalam_fine", PAL.kalamBlack, 0.72);
      }
    }
  }

  // Woven selvedge loops & frayed reed fringes along the 4 edges of the mat
  for (let iu = 0; iu < nU; iu++) {
    let uMid = -halfU + (iu + 0.5) * stripW;
    // Top and bottom selvedge knuckles
    for (let side of [-1, 1]) {
      let vEdge = side * halfV;
      let p0 = matPt(uMid - 8, vEdge);
      let p1 = matPt(uMid, vEdge + side * 12);
      let p2 = matPt(uMid + 8, vEdge);
      let loopCol = iu % 2 === 0 ? PAL.madderRed : PAL.reedRaw;
      washPoly([p0, p1, p2], loopCol, 165);
      strokeSpline([p0, p1, p2], "kalam", PAL.kalamBlack, 0.85, 0.6);
    }
  }

  for (let iv = 0; iv < nV; iv++) {
    let vMid = -halfV + (iv + 0.5) * stripW;
    // Left and right frayed reed fringes bound with indigo cord
    for (let side of [-1, 1]) {
      let uEdge = side * halfU;
      let pBase1 = matPt(uEdge, vMid - 7);
      let pBase2 = matPt(uEdge, vMid + 7);
      let pTip1 = matPt(uEdge + side * random(18, 30), vMid - 5 + random(-4, 4));
      let pTip2 = matPt(uEdge + side * random(18, 30), vMid + 5 + random(-4, 4));
      let fCol = iv % 3 === 0 ? PAL.indigoDeep : (iv % 2 === 0 ? PAL.alizarinCrimson : PAL.reedRaw);
      washPoly([pBase1, pTip1, pTip2, pBase2], fCol, 160);
      strokeLine(pBase1[0], pBase1[1], pTip1[0], pTip1[1], "kalam_fine", PAL.kalamBlack, 0.75);
      strokeLine(pBase2[0], pBase2[1], pTip2[0], pTip2[1], "kalam_fine", PAL.kalamBlack, 0.75);
    }
  }

  // Deep layered indigo cast shadows directly under the jackfruit pieces on the mat
  let castShadows = [
    { cx: 430, cy: 465, rx: 255, ry: 185, rot: -22, op: 145 },
    { cx: 755, cy: 605, rx: 300, ry: 225, rot: 16, op: 160 },
    { cx: 375, cy: 795, rx: 215, ry: 155, rot: -32, op: 155 },
    { cx: 535, cy: 675, rx: 160, ry: 130, rot: -10, op: 185 }, // Deep cleft between pieces
    { cx: 835, cy: 905, rx: 175, ry: 95, rot: -12, op: 140 }   // Foreground loose bulbs shadow
  ];
  for (let s of castShadows) {
    let sPts = makeEllipsePts(s.cx, s.cy, s.rx, s.ry, s.rot, 28, 18);
    fillPoly(sPts, PAL.indigoDeep, s.op, 0.32, 0.65, 0.55, 0.15);
    let innerPts = makeEllipsePts(s.cx + 8, s.cy + 10, s.rx * 0.78, s.ry * 0.78, s.rot, 24, 12);
    fillPoly(innerPts, PAL.indigoDark, s.op * 0.85, 0.22, 0.55, 0.5, 0.15);
  }
}

// ============================================================================
// 3. 3D GEOMETRIC KNOBBED RIND (MYROBALAN OLIVE & VERDIGRIS CONICAL TUBERCLES)
// ============================================================================

function drawSpikyRindField(cx, cy, rx, ry, rotDeg, uMin, uMax, vMin, vMax, coneScale = 1.0) {
  let ca = cos(rotDeg), sa = sin(rotDeg);
  let step = 21 * coneScale;

  // Collect tubercles so we can sort back-to-front (smaller nz drawn first, higher nz or lower y drawn cleanly)
  let knobs = [];

  for (let ly = vMin * ry; ly <= vMax * ry; ly += step * 0.86) {
    let rowIdx = Math.round((ly - vMin * ry) / (step * 0.86));
    let xOffset = (rowIdx % 2 === 0) ? 0 : step * 0.5;

    for (let lx = uMin * rx + xOffset; lx <= uMax * rx; lx += step) {
      let nu = lx / rx;
      let nv = ly / ry;
      let r2 = nu * nu + nv * nv;
      if (r2 > 1.04) continue;

      // Jitter in local ellipsoid space
      let jx = (noise(cx + lx * 0.08, cy + ly * 0.08) - 0.5) * step * 0.38;
      let jy = (noise(cx + lx * 0.08 + 99, cy + ly * 0.08 + 99) - 0.5) * step * 0.38;
      let ux = (lx + jx) / rx;
      let vy = (ly + jy) / ry;
      let radSq = ux * ux + vy * vy;
      if (radSq > 1.02) continue;

      let nz = sqrt(max(0.02, 1.0 - min(0.98, radSq)));

      // World position of tubercle base center
      let wx = cx + (lx + jx) * ca - (ly + jy) * sa;
      let wy = cy + (lx + jx) * sa + (ly + jy) * ca;

      // World 3D normal (nx, ny, nz)
      let nx = ux * ca - vy * sa;
      let ny = ux * sa + vy * ca;

      // Conical apex projects outward along the 3D normal
      let coneH = (13.5 + 5.5 * (1.0 - nz)) * coneScale;
      let ax = wx + nx * coneH;
      let ay = wy + ny * coneH;

      // Hexagonal base vertices foreshortened along the normal direction
      let baseR = step * 0.58;
      let tangAngle = atan2(ny, nx);
      let ct = cos(tangAngle), st = sin(tangAngle);
      let foreshorten = 0.42 + 0.58 * nz;

      let hex = [];
      for (let k = 0; k < 6; k++) {
        let ang = k * 60 + (noise(wx * 0.05, wy * 0.05, k) - 0.5) * 18;
        let dR = baseR * (0.88 + 0.24 * noise(wx * 0.1 + k, wy * 0.1));
        let du = cos(ang) * dR * foreshorten;
        let dv = sin(ang) * dR;
        hex.push([
          wx + du * ct - dv * st,
          wy + du * st + dv * ct
        ]);
      }

      knobs.push({ wx, wy, ax, ay, nx, ny, nz, hex });
    }
  }

  // Sort from outer silhouette (low nz) toward front-center (high nz)
  knobs.sort((a, b) => (a.nz + a.wy * 0.0005) - (b.nz + b.wy * 0.0005));

  // Light direction from upper-left
  let lxDir = -0.62, lyDir = -0.64, lzDir = 0.45;

  for (let kb of knobs) {
    let { wx, wy, ax, ay, nx, ny, nz, hex } = kb;

    // Overall illumination of this tubercle on the lobe
    let domeDot = nx * lxDir + ny * lyDir + nz * lzDir;

    // Draw the 6 triangular facets of the hexagonal cone
    for (let k = 0; k < 6; k++) {
      let v1 = hex[k];
      let v2 = hex[(k + 1) % 6];
      let fmx = (v1[0] + v2[0]) * 0.5 - ax;
      let fmy = (v1[1] + v2[1]) * 0.5 - ay;
      let fLen = sqrt(fmx * fmx + fmy * fmy) + 0.001;
      let fnx = fmx / fLen, fny = fmy / fLen;

      let facetLight = domeDot * 0.55 + (fnx * lxDir + fny * lyDir) * 0.65;

      let fCol, fOp;
      if (facetLight > 0.32) {
        fCol = PAL.oliveSun;
        fOp = 155;
      } else if (facetLight > 0.05) {
        fCol = PAL.oliveLight;
        fOp = 150;
      } else if (facetLight > -0.22) {
        fCol = PAL.oliveMid;
        fOp = 155;
      } else if (facetLight > -0.48) {
        fCol = PAL.oliveCool;
        fOp = 165;
      } else {
        fCol = PAL.oliveDeep;
        fOp = 180;
      }

      washPoly([ [ax, ay], v1, v2 ], fCol, fOp);

      // Fine slope hatch lines on shaded facets
      if (facetLight < -0.15) {
        let hm1 = [ (ax + v1[0] + v2[0]) / 3, (ay + v1[1] + v2[1]) / 3 ];
        let hm2 = [ (v1[0] + v2[0]) * 0.5, (v1[1] + v2[1]) * 0.5 ];
        strokeLine(hm1[0], hm1[1], hm2[0], hm2[1], "kalam_fine", PAL.kalamBlack, 0.45);
      }
    }

    // Bamboo pen (kalam) polygonal furrow and cone ridge lines
    for (let k = 0; k < 6; k++) {
      let v1 = hex[k];
      let v2 = hex[(k + 1) % 6];
      // Base polygonal crease
      if (k === 1 || k === 2 || k === 3 || kb.nz < 0.45) {
        strokeLine(v1[0], v1[1], v2[0], v2[1], "kalam_fine", PAL.kalamBlack, 0.65);
      }
      // Ridge lines from base corners to conical apex
      if (k % 2 === 0) {
        strokeLine(v1[0], v1[1], ax, ay, "kalam_fine", PAL.kalamBlack, 0.58);
      }
    }

    // Tiny sunlit highlight dot near apex on lit side, and dark thorny hook at tip
    if (domeDot > 0.05) {
      washPoly([
        [ax - 2.2, ay - 2.2],
        [ax + 0.5, ay - 2.8],
        [ax - 0.8, ay + 0.5]
      ], PAL.ecruLight, 170);
    }
    // Thorny dark tip of tubercle
    let hookX = ax + nx * 2.4;
    let hookY = ay + ny * 2.4 + 1.2;
    strokeLine(ax - ny * 1.3, ay + nx * 1.3, hookX, hookY, "kalam", PAL.kalamBlack, 0.95);
  }
}

// ============================================================================
// 4. HYPERREAL GLOSSY TURMERIC JACKFRUIT BULB (ARIL) & SEED GENERATOR
// ============================================================================

function drawJackfruitBulb(cfg) {
  let {
    cx, cy, len, wid, angle,
    bend = 0.14,
    isOpen = false,
    hasSeed = false,
    seedHalf = false
  } = cfg;

  let ca = cos(angle), sa = sin(angle);
  function toWorld(lx, ly) {
    return [cx + lx * ca - ly * sa, cy + lx * sa + ly * ca];
  }

  // Parametric pod contour in local space: lx in [-len/2, +len/2]
  let nSteps = 16;
  let upperCurve = [];
  let lowerCurve = [];
  let spineCurve = [];

  for (let i = 0; i <= nSteps; i++) {
    let t = (i / nSteps) * 2 - 1; // -1 (proximal core end) to +1 (distal plump end)
    let lx = t * (len * 0.5);
    let spineY = -bend * len * (1 - t * t) * 0.45;
    // Plump teardrop-kidney width profile with subtle fleshy pinching
    let env = sqrt(max(0, 1 - t * t)) * (1 + 0.22 * t + 0.07 * sin(t * 180));
    let halfW = wid * 0.5 * env;

    spineCurve.push(toWorld(lx, spineY));
    upperCurve.push(toWorld(lx, spineY - halfW));
    lowerCurve.push(toWorld(lx, spineY + halfW));
  }

  let fullOutline = [...upperCurve, ...lowerCurve.slice().reverse()];

  // 1. Deep crevice undercut shadow (indigo + amber-madder)
  let shadowPts = fullOutline.map(p => [p[0] + 4.5, p[1] + 5.5]);
  fillPoly(shadowPts, PAL.indigoDeep, 95, 0.18, 0.5, 0.45, 0.12);
  fillPoly(shadowPts, PAL.turmericAmber, 90, 0.14, 0.5, 0.45, 0.12);

  // 2. Layer 1 Natural Dye: Luminous pale lemon-turmeric base wash
  fillPoly(fullOutline, PAL.turmericLemon, 195, 0.14, 0.45, 0.4, 0.15);

  // 3. Layer 2 Natural Dye: Primary bright turmeric yellow (covers 82% of bulb)
  let midOutline = [];
  for (let i = 0; i <= nSteps; i++) {
    let t = (i / nSteps) * 2 - 1;
    let lx = t * (len * 0.48);
    let spineY = -bend * len * (1 - t * t) * 0.45;
    let env = sqrt(max(0, 1 - t * t)) * (1 + 0.22 * t);
    let halfW = wid * 0.5 * env;
    midOutline.push(toWorld(lx, spineY - halfW * 0.72));
  }
  for (let i = nSteps; i >= 0; i--) {
    midOutline.push(lowerCurve[i]);
  }
  fillPoly(midOutline, PAL.turmericBright, 160, 0.18, 0.52, 0.48, 0.15);

  // 4. Layer 3 Natural Dye: Rich golden saffron-turmeric on lower/shaded flank & lobe creases
  let shadeOutline = [];
  for (let i = 0; i <= nSteps; i++) {
    let t = (i / nSteps) * 2 - 1;
    let lx = t * (len * 0.47);
    let spineY = -bend * len * (1 - t * t) * 0.45;
    let env = sqrt(max(0, 1 - t * t)) * (1 + 0.22 * t);
    let halfW = wid * 0.5 * env;
    // Dip up into the middle lobe crease
    let creaseDip = sin((t + 0.3) * 160) * halfW * 0.25;
    shadeOutline.push(toWorld(lx, spineY - halfW * 0.08 + creaseDip));
  }
  for (let i = nSteps; i >= 0; i--) {
    shadeOutline.push(lowerCurve[i]);
  }
  fillPoly(shadeOutline, PAL.turmericGold, 155, 0.16, 0.55, 0.5, 0.15);

  // 5. Layer 4 Natural Dye: Deep amber & cool olive-indigo reflected shadow along bottom rim
  let deepRim = [];
  for (let i = 1; i < nSteps; i++) {
    let t = (i / nSteps) * 2 - 1;
    let lx = t * (len * 0.45);
    let spineY = -bend * len * (1 - t * t) * 0.45;
    let env = sqrt(max(0, 1 - t * t)) * (1 + 0.22 * t);
    let halfW = wid * 0.5 * env;
    deepRim.push(toWorld(lx, spineY + halfW * 0.42));
  }
  for (let i = nSteps - 1; i >= 1; i--) {
    deepRim.push(lowerCurve[i]);
  }
  washPoly(deepRim, PAL.turmericAmber, 130, 0.1);
  washPoly(deepRim, PAL.turmericCoolShade, 85, 0.1);

  // 6. Longitudinal fleshy lobe creases & glossy unpainted ecru specular highlights
  let crease1 = [];
  let crease2 = [];
  let gloss1 = [];
  let gloss2 = [];

  for (let i = 2; i <= nSteps - 2; i++) {
    let t = (i / nSteps) * 2 - 1;
    let lx = t * (len * 0.44);
    let spineY = -bend * len * (1 - t * t) * 0.45;
    let env = sqrt(max(0, 1 - t * t)) * (1 + 0.2 * t);
    let halfW = wid * 0.5 * env;

    crease1.push(toWorld(lx, spineY - halfW * 0.18));
    crease2.push(toWorld(lx, spineY + halfW * 0.24));

    if (i >= 3 && i <= nSteps - 3) {
      gloss1.push(toWorld(lx, spineY - halfW * 0.56));
      gloss2.push(toWorld(lx, spineY - halfW * 0.36));
    }
  }

  // Crisp glossy specular highlight strip (unpainted warm cotton + wet sheen)
  if (!isOpen) {
    let glossPoly = [...gloss1, ...gloss2.slice().reverse()];
    washPoly(glossPoly, PAL.glossWhite, 220, 0.12);
    strokeSpline(gloss1, "latex_brush", PAL.latexBright, 0.95, 0.5);
    // Secondary smaller specular bead on lower lobe
    let gBead = [
      toWorld(len * 0.1, -bend * len * 0.4 + wid * 0.04),
      toWorld(len * 0.24, -bend * len * 0.35 + wid * 0.05),
      toWorld(len * 0.18, -bend * len * 0.35 + wid * 0.14)
    ];
    washPoly(gBead, PAL.glossWhite, 195, 0.1);

    // Delicate saffron-brown & iron-black kalam crease lines
    strokeSpline(crease1, "kalam_fine", PAL.turmericAmber, 0.85, 0.5);
    strokeSpline(crease1.slice(2, -2), "kalam_fine", PAL.kalamBrown, 0.55, 0.5);
    strokeSpline(crease2, "kalam_fine", PAL.turmericAmber, 0.75, 0.5);
  } else {
    // SPLIT / HALF-OPENED BULB REVEALING JUICY FLESH WALL & GLOSSY SEED
    let cavUpper = [], cavLower = [];
    for (let i = 3; i <= nSteps - 2; i++) {
      let t = (i / nSteps) * 2 - 1;
      let lx = t * (len * 0.38);
      let spineY = -bend * len * (1 - t * t) * 0.45;
      let env = sqrt(max(0, 1 - t * t));
      let halfW = wid * 0.32 * env;
      cavUpper.push(toWorld(lx, spineY - halfW));
      cavLower.push(toWorld(lx, spineY + halfW));
    }
    let cavPoly = [...cavUpper, ...cavLower.slice().reverse()];
    // Inner flesh cavity shadow
    fillPoly(cavPoly, PAL.turmericAmber, 165, 0.12, 0.45, 0.45, 0.12);
    // Cut golden flesh rim highlight
    strokeSpline(cavUpper, "latex_brush", PAL.turmericLemon, 1.15, 0.5);
    strokeSpline(cavUpper, "kalam_fine", PAL.kalamBlack, 0.68, 0.5);
    strokeSpline(cavLower, "kalam_fine", PAL.kalamBlack, 0.78, 0.5);

    if (hasSeed) {
      let sc = toWorld(len * 0.04, -bend * len * 0.38);
      drawJackfruitSeed(sc[0], sc[1], len * 0.27, wid * 0.24, angle + 6, seedHalf);
    }
  }

  // 7. Fine cross-contour tonal hatching at proximal core attachment & shaded belly
  for (let i = 2; i <= nSteps - 2; i += 2) {
    let pBot = lowerCurve[i];
    let pMid = crease2[Math.min(crease2.length - 1, Math.max(0, i - 2))];
    let mx = (pBot[0] * 0.65 + pMid[0] * 0.35);
    let my = (pBot[1] * 0.65 + pMid[1] * 0.35);
    strokeLine(pBot[0], pBot[1], mx, my, "kalam_fine", PAL.kalamBrown, 0.45);
  }

  // 8. Confident, swelling bamboo-pen (Kalam) iron-black outlines
  // Lit upper contour (nimble, slightly lighter)
  strokeSpline(upperCurve, "kalam", PAL.kalamBlack, 0.82, 0.45);
  // Shaded lower contour (bold, swelling iron-black)
  strokeSpline(lowerCurve, "kalam_bold", PAL.kalamBlack, 0.95, 0.45);
}

function drawJackfruitSeed(sx, sy, rx, ry, rotDeg, isHalved = false) {
  // Deep socket shadow
  let shPts = makeEllipsePts(sx + 3, sy + 4, rx * 1.08, ry * 1.08, rotDeg, 20, 1.5);
  washPoly(shPts, PAL.seedDark, 185, 0.1);

  let seedPts = makeEllipsePts(sx, sy, rx, ry, rotDeg, 22, 1.2);

  if (!isHalved) {
    // Whole glossy mahogany-plum seed
    fillPoly(seedPts, PAL.seedRose, 190, 0.12, 0.45, 0.4, 0.12);
    let darkSide = makeEllipsePts(sx + 2, sy + 3, rx * 0.85, ry * 0.82, rotDeg, 20, 1.0);
    fillPoly(darkSide, PAL.seedMahogany, 175, 0.14, 0.5, 0.45, 0.12);
    let deepRim = makeEllipsePts(sx + 4, sy + 5, rx * 0.65, ry * 0.6, rotDeg, 18, 0.8);
    washPoly(deepRim, PAL.seedDark, 160, 0.1);

    // Glossy white crescent reflection on upper-left of seed
    let ca = cos(rotDeg), sa = sin(rotDeg);
    let hPts = [];
    for (let a = -155; a <= -35; a += 20) {
      let lx = rx * 0.62 * cos(a);
      let ly = ry * 0.58 * sin(a);
      hPts.push([sx + lx * ca - ly * sa, sy + lx * sa + ly * ca]);
    }
    strokeSpline(hPts, "latex_brush", PAL.glossWhite, 1.05, 0.5);

    // Delicate longitudinal seed-coat striations
    for (let s = -0.45; s <= 0.45; s += 0.3) {
      let stPts = [];
      for (let t = -0.75; t <= 0.75; t += 0.35) {
        let lx = t * rx * 0.85;
        let ly = s * ry * sqrt(max(0, 1 - t * t));
        stPts.push([sx + lx * ca - ly * sa, sy + lx * sa + ly * ca]);
      }
      strokeSpline(stPts, "kalam_fine", PAL.seedDark, 0.45, 0.5);
    }
  } else {
    // Sliced seed showing pale ivory cotyledon interior
    fillPoly(seedPts, PAL.seedMahogany, 195, 0.1, 0.4, 0.4, 0.12);
    let innerPts = makeEllipsePts(sx, sy, rx * 0.82, ry * 0.78, rotDeg, 20, 1.0);
    fillPoly(innerPts, PAL.seedCotyledon, 220, 0.08, 0.35, 0.35, 0.12);
    // Embryo division line in center of cotyledon
    let ca = cos(rotDeg), sa = sin(rotDeg);
    strokeLine(
      sx - rx * 0.6 * ca, sy - rx * 0.6 * sa,
      sx + rx * 0.6 * ca, sy + rx * 0.6 * sa,
      "kalam_fine", PAL.kalamBrown, 0.6
    );
  }

  strokePoly(seedPts, "kalam", PAL.kalamBlack, 0.88, true, 0.1);
}

// ============================================================================
// 5. FIBROUS PERIANTH RIBBONS (CHAPA) & CENTRAL CORE (RACHIS)
// ============================================================================

function drawPerianthRibbon(x1, y1, x2, y2, w = 7, bend = 14) {
  let mx = (x1 + x2) * 0.5 + bend;
  let my = (y1 + y2) * 0.5 - bend * 0.6;
  let dx = x2 - x1, dy = y2 - y1;
  let len = sqrt(dx * dx + dy * dy) + 0.001;
  let nx = -dy / len * (w * 0.5);
  let ny = dx / len * (w * 0.5);

  let side1 = [
    [x1 + nx * 0.4, y1 + ny * 0.4],
    [mx + nx, my + ny],
    [x2 + nx * 0.3, y2 + ny * 0.3]
  ];
  let side2 = [
    [x2 - nx * 0.3, y2 - ny * 0.3],
    [mx - nx, my - ny],
    [x1 - nx * 0.4, y1 - ny * 0.4]
  ];
  let ribPoly = [...side1, ...side2];
  washPoly(ribPoly, PAL.coreCream, 185, 0.15);
  washPoly(side2, PAL.coreOchre, 130, 0.15);
  strokeSpline(side1, "kalam_fine", PAL.kalamBrown, 0.55, 0.5);
  strokeSpline(side2, "kalam_fine", PAL.kalamBlack, 0.65, 0.5);
}

