function drawPieceB_HeroSplitHalf() {
  let cx = 740, cy = 555, rx = 278, ry = 208, rot = 16;

  // 1. Outer spiky rind base wash & 3D conical tubercle crown around perimeter
  let outerPts = makeEllipsePts(cx, cy, rx * 1.04, ry * 1.04, rot, 36, 12);
  fillPoly(outerPts, PAL.oliveMid, 185, 0.22, 0.58, 0.5, 0.12);
  fillPoly(outerPts, PAL.oliveDeep, 115, 0.25, 0.6, 0.5, 0.12);

  // Draw the outer rim of 3D conical spikes (only where r^2 > 0.68 so center stays fast)
  let ca = cos(rot), sa = sin(rot);
  let step = 22;
  for (let a = 0; a < 360; a += 6.5) {
    for (let rRatio of [0.98, 0.90]) {
      let lx = rx * rRatio * cos(a);
      let ly = ry * rRatio * sin(a);
      let wx = cx + lx * ca - ly * sa;
      let wy = cy + lx * sa + ly * ca;
      let nx = cos(a) * ca - sin(a) * sa;
      let ny = cos(a) * sa + sin(a) * ca;
      let coneH = rRatio > 0.94 ? 21 : 14;
      let ax = wx + nx * coneH;
      let ay = wy + ny * coneH;
      let tx = -ny * 11, ty = nx * 11;

      let v1 = [wx - tx, wy - ty];
      let v2 = [wx + tx, wy + ty];
      let vMid = [wx - nx * 6, wy - ny * 6];

      let light = nx * (-0.6) + ny * (-0.65);
      let col1 = light > 0 ? PAL.oliveSun : PAL.oliveMid;
      let col2 = light > 0 ? PAL.oliveMid : PAL.oliveDeep;

      washPoly([[ax, ay], v1, vMid], col1, 175);
      washPoly([[ax, ay], vMid, v2], col2, 185);
      strokeLine(v1[0], v1[1], ax, ay, "kalam", PAL.kalamBlack, 0.8);
      strokeLine(v2[0], v2[1], ax, ay, "kalam", PAL.kalamBlack, 0.85);
      strokeLine(vMid[0], vMid[1], ax, ay, "kalam_fine", PAL.kalamBlack, 0.6);
    }
  }

  // 2. Cut Rind Wall (Mesocarp Ring) inside the spiky crown
  let mesoOuter = makeEllipsePts(cx, cy, rx * 0.89, ry * 0.88, rot, 36, 7);
  let mesoInner = makeEllipsePts(cx, cy, rx * 0.77, ry * 0.75, rot, 36, 8);
  fillPoly(mesoOuter, PAL.rindPith, 215, 0.14, 0.48, 0.42, 0.12);
  // Cool olive-slate shading along lower-right cut rind wall
  let mesoShade = makeEllipsePts(cx + 16, cy + 18, rx * 0.84, ry * 0.82, rot, 32, 6);
  fillPoly(mesoShade, PAL.rindPithShade, 115, 0.18, 0.5, 0.45, 0.12);

  // 3. Deep interior cavity washed with cool indigo & deep amber-madder
  fillPoly(mesoInner, PAL.indigoDeep, 175, 0.2, 0.55, 0.5, 0.12);
  fillPoly(mesoInner, PAL.turmericAmber, 125, 0.18, 0.55, 0.5, 0.12);

  // Vascular stipples and radial bundle ticks on the cut rind wall
  for (let i = 0; i < mesoOuter.length; i++) {
    let pOut = mesoOuter[i];
    let pIn = mesoInner[i];
    let mx = (pOut[0] + pIn[0]) * 0.5;
    let my = (pOut[1] + pIn[1]) * 0.5;
    strokeLine(pOut[0], pOut[1], mx, my, "kalam_fine", PAL.oliveCool, 0.52);
    if (i % 2 === 0) {
      strokeLine(mx, my, mx + 2, my + 2, "kalam", PAL.kalamBrown, 0.75);
    }
  }
  strokePoly(mesoOuter, "kalam_bold", PAL.kalamBlack, 0.95, true, 0.12);
  strokePoly(mesoInner, "kalam", PAL.kalamBlack, 0.82, true, 0.12);

  // 4. Background layer of fibrous perianth ribbons (chapa) radiating from core
  for (let a = 0; a < 360; a += 14) {
    let r1 = 35, r2 = 175;
    let lx1 = r1 * cos(a) * 1.2, ly1 = r1 * sin(a) * 0.8;
    let lx2 = r2 * cos(a + random(-8, 8)) * 1.15, ly2 = r2 * sin(a + random(-8, 8)) * 0.85;
    let p1 = [cx + lx1 * ca - ly1 * sa, cy + lx1 * sa + ly1 * ca];
    let p2 = [cx + lx2 * ca - ly2 * sa, cy + lx2 * sa + ly2 * ca];
    drawPerianthRibbon(p1[0], p1[1], p2[0], p2[1], 6.5, random(-14, 14));
  }

  // 5. Outer ring of plump turmeric-yellow bulbs (16 bulbs arranged radially around cavity)
  let outerBulbs = [
    { dx: -155, dy: -65, len: 108, wid: 54, ang: -155, bend: 0.14, open: false },
    { dx: -110, dy: -108, len: 104, wid: 52, ang: -125, bend: -0.12, open: false },
    { dx: -45, dy: -125, len: 102, wid: 54, ang: -95, bend: 0.15, open: true, seed: true },
    { dx: 25, dy: -125, len: 105, wid: 52, ang: -72, bend: -0.14, open: false },
    { dx: 95, dy: -108, len: 108, wid: 54, ang: -45, bend: 0.12, open: false },
    { dx: 150, dy: -68, len: 110, wid: 56, ang: -18, bend: 0.16, open: true, seed: true },
    { dx: 175, dy: -8, len: 112, wid: 56, ang: 10, bend: -0.14, open: false },
    { dx: 162, dy: 55, len: 110, wid: 54, ang: 35, bend: 0.15, open: false },
    { dx: 118, dy: 102, len: 106, wid: 54, ang: 62, bend: -0.12, open: true, seed: true, half: true },
    { dx: 52, dy: 125, len: 104, wid: 52, ang: 85, bend: 0.14, open: false },
    { dx: -18, dy: 128, len: 106, wid: 54, ang: 108, bend: -0.15, open: false },
    { dx: -85, dy: 112, len: 108, wid: 56, ang: 132, bend: 0.12, open: true, seed: true },
    { dx: -142, dy: 72, len: 110, wid: 54, ang: 158, bend: -0.14, open: false },
    { dx: -172, dy: 10, len: 108, wid: 56, ang: 178, bend: 0.15, open: false }
  ];

  for (let b of outerBulbs) {
    let wp = [cx + b.dx * ca - b.dy * sa, cy + b.dx * sa + b.dy * ca];
    drawJackfruitBulb({
      cx: wp[0], cy: wp[1],
      len: b.len, wid: b.wid,
      angle: b.ang + rot,
      bend: b.bend,
      isOpen: b.open,
      hasSeed: b.seed,
      seedHalf: b.half
    });
  }

  // 6. Central Fibrous Core (Rachis) running down the longitudinal axis of Piece B
  let coreUpper = [], coreLower = [];
  for (let i = 0; i <= 14; i++) {
    let t = (i / 14) * 2 - 1; // -1 to +1
    let lx = t * 145;
    let curveY = sin(t * 95) * 14;
    // Club-shaped core: wider toward middle-right
    let halfW = (28 + 11 * sin((t + 0.4) * 110)) * sqrt(max(0.15, 1 - 0.55 * t * t));
    coreUpper.push([cx + lx * ca - (curveY - halfW) * sa, cy + lx * sa + (curveY - halfW) * ca]);
    coreLower.push([cx + lx * ca - (curveY + halfW) * sa, cy + lx * sa + (curveY + halfW) * ca]);
  }
  let corePoly = [...coreUpper, ...coreLower.slice().reverse()];
  fillPoly(corePoly, PAL.coreCream, 215, 0.14, 0.48, 0.42, 0.12);
  let coreShade = [...coreUpper.map((p, idx) => [
    (p[0] + coreLower[idx][0]) * 0.5,
    (p[1] + coreLower[idx][1]) * 0.5
  ]), ...coreLower.slice().reverse()];
  fillPoly(coreShade, PAL.coreOchre, 150, 0.15, 0.5, 0.45, 0.12);
  fillPoly(coreShade, PAL.coreCool, 85, 0.18, 0.5, 0.45, 0.12);

  // Core cross-contour lines & vascular pits
  for (let i = 1; i < coreUpper.length - 1; i++) {
    let pU = coreUpper[i], pL = coreLower[i];
    let pm = [(pU[0] + pL[0]) * 0.5 + 3, (pU[1] + pL[1]) * 0.5 + 4];
    strokeSpline([pU, pm, pL], "kalam_fine", PAL.kalamBrown, 0.52, 0.5);
    // Tiny vascular pores on cut rachis
    strokeLine(pm[0] - 4, pm[1] - 2, pm[0] - 2, pm[1] - 1, "kalam", PAL.kalamBrown, 0.7);
    strokeLine(pm[0] + 5, pm[1] + 3, pm[0] + 7, pm[1] + 4, "kalam", PAL.kalamBrown, 0.7);
  }
  strokeSpline(coreUpper, "kalam", PAL.kalamBlack, 0.85, 0.45);
  strokeSpline(coreLower, "kalam_bold", PAL.kalamBlack, 0.95, 0.45);

  // 7. Inner / Upper tier of plump golden-turmeric bulbs overlapping the core edge
  let innerBulbs = [
    { dx: -95, dy: -45, len: 96, wid: 50, ang: -140, bend: 0.15, open: false },
    { dx: -32, dy: -58, len: 94, wid: 48, ang: -105, bend: -0.12, open: false },
    { dx: 35, dy: -56, len: 98, wid: 52, ang: -65, bend: 0.16, open: true, seed: true },
    { dx: 98, dy: -38, len: 95, wid: 48, ang: -28, bend: -0.14, open: false },
    { dx: 105, dy: 32, len: 98, wid: 50, ang: 25, bend: 0.14, open: false },
    { dx: 42, dy: 55, len: 100, wid: 52, ang: 72, bend: -0.16, open: false },
    { dx: -28, dy: 58, len: 96, wid: 50, ang: 112, bend: 0.14, open: true, seed: true },
    { dx: -92, dy: 42, len: 94, wid: 48, ang: 148, bend: -0.12, open: false },
    // Hero top-center bulbs piling high
    { dx: -55, dy: -5, len: 92, wid: 50, ang: -165, bend: 0.18, open: false },
    { dx: 12, dy: 4, len: 95, wid: 52, ang: -15, bend: -0.16, open: false },
    { dx: 72, dy: -2, len: 90, wid: 48, ang: 8, bend: 0.14, open: false }
  ];

  // Stray perianth ribbons weaving over the bulbs
  drawPerianthRibbon(cx - 80, cy - 35, cx - 140, cy - 95, 6, 12);
  drawPerianthRibbon(cx + 45, cy - 25, cx + 115, cy - 88, 6, -14);
  drawPerianthRibbon(cx + 20, cy + 35, cx + 85, cy + 105, 6.5, 15);
  drawPerianthRibbon(cx - 55, cy + 30, cx - 125, cy + 95, 6, -12);

  for (let b of innerBulbs) {
    let wp = [cx + b.dx * ca - b.dy * sa, cy + b.dx * sa + b.dy * ca];
    drawJackfruitBulb({
      cx: wp[0], cy: wp[1],
      len: b.len, wid: b.wid,
      angle: b.ang + rot,
      bend: b.bend,
      isOpen: b.open,
      hasSeed: b.seed
    });
  }
}

