// ============================================================================
// 7. STICKY LATEX THREADS & MILKY SAP DROPLETS (HYPERREAL FOCAL DETAIL)
// ============================================================================

function drawStickyLatexThreads() {
  // Primary catenary latex threads stretching across the cleft between Piece C & Piece B,
  // plus threads bridging between Piece A & Piece B
  let bridges = [];

  // Cleft between Piece C (front-left wedge) and Piece B (center-right half)
  for (let i = 0; i < 26; i++) {
    let t = i / 25;
    let x1 = lerp(295, 515, t) + random(-10, 10);
    let y1 = lerp(685, 625, t) + random(-10, 10);
    let x2 = lerp(495, 665, t) + random(-12, 12);
    let y2 = lerp(525, 665, t) + random(-12, 12);
    bridges.push({ x1, y1, x2, y2, sag: random(6, 22), thick: random(0.75, 1.35) });
  }

  // Cleft between Piece A (upper-left) and Piece B (center-right)
  for (let i = 0; i < 12; i++) {
    let t = i / 11;
    let x1 = lerp(485, 565, t) + random(-8, 8);
    let y1 = lerp(335, 505, t) + random(-8, 8);
    let x2 = lerp(555, 635, t) + random(-8, 8);
    let y2 = lerp(375, 535, t) + random(-8, 8);
    bridges.push({ x1, y1, x2, y2, sag: random(5, 16), thick: random(0.7, 1.2) });
  }

  // Short sticky threads across the cut central core of Piece B
  for (let i = 0; i < 8; i++) {
    let x1 = 635 + i * 24 + random(-6, 6);
    let y1 = 495 + i * 11 + random(-6, 6);
    let x2 = x1 + random(22, 48);
    let y2 = y1 + random(28, 55);
    bridges.push({ x1, y1, x2, y2, sag: random(4, 11), thick: random(0.7, 1.1) });
  }

  // Store midpoints so we can connect secondary Y-branching viscous filaments
  let midPoints = [];

  for (let br of bridges) {
    let { x1, y1, x2, y2, sag, thick } = br;
    let mx = (x1 + x2) * 0.5 + sag * 0.35;
    let my = (y1 + y2) * 0.5 + sag;
    let q1x = lerp(x1, mx, 0.5), q1y = lerp(y1, my, 0.5) + sag * 0.25;
    let q2x = lerp(mx, x2, 0.5), q2y = lerp(my, y2, 0.5) + sag * 0.25;

    let path = [[x1, y1], [q1x, q1y], [mx, my], [q2x, q2y], [x2, y2]];
    midPoints.push({ q1: [q1x, q1y], mid: [mx, my], q2: [q2x, q2y] });

    // 1. Subtle indigo cast shadow slightly below the taut thread
    let shPath = path.map(p => [p[0] + 2, p[1] + 3]);
    strokeSpline(shPath, "kalam_fine", PAL.indigoDark, 0.55 * thick, 0.5);

    // 2. Webbed triangular meniscus feet where sticky sap pulls at the flesh
    let dx = x2 - x1, dy = y2 - y1;
    let dLen = sqrt(dx * dx + dy * dy) + 0.001;
    let nx = -dy / dLen * 5.5 * thick;
    let ny = dx / dLen * 5.5 * thick;
    let foot1 = [[x1 + nx, y1 + ny], [lerp(x1, q1x, 0.35), lerp(y1, q1y, 0.35)], [x1 - nx, y1 - ny]];
    let foot2 = [[x2 + nx, y2 + ny], [lerp(x2, q2x, 0.35), lerp(y2, q2y, 0.35)], [x2 - nx, y2 - ny]];
    washPoly(foot1, PAL.latexBright, 215);
    washPoly(foot2, PAL.latexBright, 215);

    // 3. Cool milky-blue under-stroke & bright ecru-white core filament
    strokeSpline(path, "latex_brush", PAL.latexMilk, 1.15 * thick, 0.5);
    strokeSpline(path, "latex_brush", PAL.latexBright, 0.82 * thick, 0.5);

    // 4. Fine Kalamkari iron-black double-contour along the thicker meniscus ends
    strokeSpline([foot1[0], foot1[1]], "kalam_fine", PAL.kalamBlack, 0.42, 0.4);
    strokeSpline([foot2[0], foot2[1]], "kalam_fine", PAL.kalamBlack, 0.42, 0.4);
    if (thick > 0.95) {
      let offPath = path.map(p => [p[0] + 0.9, p[1] + 1.1]);
      strokeSpline(offPath, "kalam_fine", PAL.indigoDeep, 0.4, 0.5);
    }

    // 5. Glistening spherical/teardrop latex beads clinging to the filament
    for (let bPt of [[q1x, q1y], [mx, my], [q2x, q2y]]) {
      if (random() < 0.62) {
        let brx = random(2.5, 4.8) * thick;
        let bry = brx * 0.78;
        let bPoly = makeEllipsePts(bPt[0], bPt[1], brx, bry, -25, 10, 0);
        washPoly(bPoly, PAL.latexBright, 240);
        strokePoly(bPoly, "kalam_fine", PAL.kalamBlack, 0.45, true, 0.1);
      }
    }
  }

  // Secondary branching cross-threads forming viscous Y-junctions
  for (let i = 0; i < midPoints.length - 1; i++) {
    if (random() < 0.68) {
      let pA = midPoints[i].q1;
      let pB = midPoints[i + 1].mid;
      let d = dist(pA[0], pA[1], pB[0], pB[1]);
      if (d < 65) {
        let m = [(pA[0] + pB[0]) * 0.5 + 2, (pA[1] + pB[1]) * 0.5 + 4];
        strokeSpline([pA, m, pB], "latex_brush", PAL.latexBright, 0.65, 0.45);
        strokeSpline([pA, m, pB], "kalam_fine", PAL.indigoDeep, 0.35, 0.45);
      }
    }
  }

  // Milky white latex droplets oozing directly on the cut core & rind walls
  let sapDrops = [
    [665, 515, 7], [705, 538, 8], [748, 562, 6.5], [785, 580, 7.5],
    [625, 488, 6], [565, 415, 6.5], [545, 465, 7], [385, 682, 7.5],
    [428, 655, 6.5], [335, 718, 6], [835, 615, 7], [690, 685, 6.5]
  ];
  for (let d of sapDrops) {
    let dPts = makeEllipsePts(d[0], d[1], d[2], d[2] * 0.75, -15, 12, 0.5);
    let shPts = makeEllipsePts(d[0] + 1.5, d[1] + 2.2, d[2], d[2] * 0.75, -15, 12, 0.5);
    washPoly(shPts, PAL.indigoDeep, 130);
    washPoly(dPts, PAL.latexMilk, 225);
    washPoly(makeEllipsePts(d[0] - 1, d[1] - 1, d[2] * 0.65, d[2] * 0.48, -15, 10, 0), PAL.latexBright, 245);
    strokePoly(dPts, "kalam_fine", PAL.kalamBlack, 0.58, true, 0.1);
  }
}

