// ============================================================================
// GEOMETRY & DRAWING HELPERS
// ============================================================================

function polyShape(pts, curvature = 0.28) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

function ellipsePoints(cx, cy, rx, ry, rotDeg, num = 28, nAmp = 0) {
  let pts = [];
  let c = cos(rotDeg), s = sin(rotDeg);
  for (let i = 0; i < num; i++) {
    let a = (i / num) * 360;
    let nr = nAmp > 0 ? (noise(cx * 0.01 + cos(a), cy * 0.01 + sin(a)) - 0.5) * nAmp : 0;
    let lx = (rx + nr) * cos(a);
    let ly = (ry + nr) * sin(a);
    pts.push([cx + lx * c - ly * s, cy + lx * s + ly * c]);
  }
  return pts;
}

function evalBezier(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let tt = t * t, uu = u * u;
  let uuu = uu * u, ttt = tt * t;
  return [
    uuu * p0[0] + 3 * uu * t * p1[0] + 3 * u * tt * p2[0] + ttt * p3[0],
    uuu * p0[1] + 3 * uu * t * p1[1] + 3 * u * tt * p2[1] + ttt * p3[1]
  ];
}

function evalBezierTangent(p0, p1, p2, p3, t) {
  let u = 1 - t;
  let dx = 3 * u * u * (p1[0] - p0[0]) + 6 * u * t * (p2[0] - p1[0]) + 3 * t * t * (p3[0] - p2[0]);
  let dy = 3 * u * u * (p1[1] - p0[1]) + 6 * u * t * (p2[1] - p1[1]) + 3 * t * t * (p3[1] - p2[1]);
  let m = sqrt(dx * dx + dy * dy) || 1;
  return [dx / m, dy / m];
}

function sampleBezierSpline(p0, p1, p2, p3, steps = 12, jitter = 0, pressures = null) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let p = evalBezier(p0, p1, p2, p3, t);
    let jx = jitter ? random(-jitter, jitter) : 0;
    let jy = jitter ? random(-jitter, jitter) : 0;
    let pr = pressures ? lerp(pressures[0], pressures[1], sin(t * 180)) : 1.0;
    pts.push([p[0] + jx, p[1] + jy, pr]);
  }
  return pts;
}

// ============================================================================
// 1. BARE FLOOR & DIRECTIONAL CAST SHADOWS
// ============================================================================

function renderBareFloor() {
  brush.noStroke();

  // Warm directional light from upper-left to deep umber lower-right
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.85, 0.35);

  // Upper-left bright dry plaster/clay floor wash
  brush.fill(PAL.floorLight, 150);
  polyShape([[-40, -40], [950, -40], [620, 620], [-40, 880]], 0.2);
  polyShape([[-40, -40], [720, -40], [450, 480], [-40, 650]], 0.2);

  // Lower-right shadow falloff across the bare floor
  brush.fill(PAL.floorDark, 130);
  polyShape([[450, 480], [1240, 120], [1240, 1240], [80, 1240]], 0.2);

  brush.fill(PAL.floorDeep, 145);
  polyShape([[680, 620], [1240, 380], [1240, 1240], [320, 1240]], 0.2);

  // Corners grounding
  brush.fill(PAL.rawUmber, 110);
  polyShape([[820, 780], [1240, 580], [1240, 1240], [520, 1240]], 0.2);
  brush.noFill();

  // Dry swept floor hatching & stone-dust striations (slightly oblique floor plane)
  brush.hatchStyle("charcoal", PAL.floorDark, 0.9);
  brush.hatch(18, -14, { rand: 0.18, gradient: 0.4 });
  brush.noStroke();
  polyShape([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], 0.05);
  brush.noHatch();

  // Subtle chalky floor highlights in top-left light zone
  brush.hatchStyle("cpencil", PAL.chalkSlip, 0.85);
  brush.hatch(14, -14, { rand: 0.15, gradient: 0.55 });
  polyShape([[0, 0], [780, 0], [480, 520], [0, 720]], 0.1);
  brush.noHatch();

  // Faint bare floor hairline joint lines (architectural grounding seen from above)
  brush.set("2H", PAL.rawUmber, 0.65);
  for (let yBase of [210, 680, 1090]) {
    let pts = [];
    for (let x = 0; x <= 1200; x += 80) {
      let y = yBase - (x - 600) * 0.18 + (noise(x * 0.01, yBase) - 0.5) * 6;
      pts.push([x, y, random(0.3, 0.8)]);
    }
    brush.spline(pts, 0.3);
  }

  // Powdery floor dust stipple
  for (let i = 0; i < 160; i++) {
    let x = random(width), y = random(height);
    let col = (x + y < 1100) ? PAL.paleSlip : PAL.rawUmber;
    brush.set("kiln_dust", col, random(0.6, 1.5));
    brush.line(x, y, x + random(-35, 35), y + random(-15, 15));
  }
}

function renderCastShadows() {
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.8, 0.4);

  // Far soft penumbra cast to bottom-right (+65, +75 from body center)
  brush.fill(PAL.floorDeep, 155);
  polyShape(ellipsePoints(665, 675, 435, 360, -8, 36, 18), 0.35);

  // Mid cast shadow
  brush.fill(PAL.darkUmber, 185);
  polyShape(ellipsePoints(640, 650, 410, 335, -6, 36, 14), 0.35);

  // Tighter contact shadow under outer spine, haunch, tail, and head
  brush.fill(PAL.voidUmber, 220);
  polyShape(ellipsePoints(612, 625, 385, 315, -5, 36, 10), 0.35);
  brush.noFill();

  // Dense smudged charcoal mass in the cast shadow core
  brush.mass("charcoal", PAL.darkUmber, { precision: 0.35, strength: 0.75, gradient: 0.4, outline: false });
  polyShape(ellipsePoints(655, 665, 405, 330, -8, 30, 12), 0.3);
  brush.noMass();

  // Soft charcoal cross-hatching feathering the cast shadow edge on the right/bottom
  for (let i = 0; i < 180; i++) {
    let a = random(-35, 145);
    let rx = 385 + random(-25, 65);
    let ry = 315 + random(-25, 65);
    let sx = 620 + rx * cos(a);
    let sy = 630 + ry * sin(a);
    brush.set("charcoal", ( i % 2 === 0 ) ? PAL.darkUmber : PAL.rawUmber, random(0.6, 1.4));
    brush.line(sx, sy, sx + cos(a + random(-20, 20)) * random(25, 65), sy + sin(a + random(-20, 20)) * random(25, 65));
  }
}

// ============================================================================
// 2. CENTRAL HOLLOW & OCCLUSION BASIN
// ============================================================================

function renderCentralHollow() {
  // The negative space inside the curled greyhound where legs, paws, and muzzle meet
  let hollowPts = [
