// 5. HYPERREALISTIC 3D SCULPTURAL MODELLING
// ============================================================================

// Helper to shade a tubular limb segment with cross-contour and longitudinal strokes
function sculptLimbSegment(pStart, pEnd, wStart, wEnd, lightSide = -1, colLit = PAL.paleSlip, colMid = PAL.burntSienna, colDark = PAL.darkUmber) {
  let dx = pEnd[0] - pStart[0];
  let dy = pEnd[1] - pStart[1];
  let len = sqrt(dx * dx + dy * dy) || 1;
  let tx = dx / len, ty = dy / len;
  let nx = -ty * lightSide, ny = tx * lightSide;

  // Base polygon wash
  let poly = [
    [pStart[0] + nx * wStart, pStart[1] + ny * wStart],
    [pEnd[0] + nx * wEnd, pEnd[1] + ny * wEnd],
    [pEnd[0] - nx * wEnd, pEnd[1] - ny * wEnd],
    [pStart[0] - nx * wStart, pStart[1] - ny * wStart]
  ];
  brush.noStroke();
  brush.wash(colMid, 235);
  polyShape(poly, 0.2);
  brush.noWash();

  // Longitudinal cylindrical shading passes
  let bands = 16;
  for (let b = 0; b <= bands; b++) {
    let u = (b / bands) * 2 - 1; // -1 (shadow side) to +1 (lit side)
    let col;
    if (u > 0.45) col = colLit;
    else if (u > 0.05) col = PAL.rawSienna;
    else if (u > -0.4) col = colMid;
    else if (u > -0.75) col = PAL.ironOxide;
    else col = colDark;

    let sx = pStart[0] + nx * wStart * u;
    let sy = pStart[1] + ny * wStart * u;
    let ex = pEnd[0] + nx * wEnd * u;
    let ey = pEnd[1] + ny * wEnd * u;

    brush.set("clay_shader", col, random(0.65, 1.15));
    let midX = (sx + ex) * 0.5 + nx * random(-2, 2);
    let midY = (sy + ey) * 0.5 + ny * random(-2, 2);
    brush.spline([[sx, sy, 0.5], [midX, midY, 1.0], [ex, ey, 0.5]], 0.25);
  }

  // Fine bone/tendon striations along the limb
  let striae = int(len * 0.28);
  for (let i = 0; i < striae; i++) {
    let t = random(0.05, 0.95);
    let u = random(-0.9, 0.9);
    let w = lerp(wStart, wEnd, t);
    let px = lerp(pStart[0], pEnd[0], t) + nx * w * u;
    let py = lerp(pStart[1], pEnd[1], t) + ny * w * u;
    let sLen = random(14, 32);
    let col = u > 0.35 ? PAL.chalkSlip : (u > -0.2 ? PAL.rawSienna : PAL.voidUmber);
    brush.set("sculpt_fine", col, random(0.45, 0.85));
    brush.line(px - tx * sLen * 0.5, py - ty * sLen * 0.5, px + tx * sLen * 0.5, py + ty * sLen * 0.5);
  }
}

// Helper to draw a sculpted greyhound paw with knuckles, claws, and matte paw pads
function sculptPawWithPads(cx, cy, angleDeg, scaleF = 1.0, showPads = true) {
  push();
  translate(cx, cy);
  rotate(angleDeg);

  // 4 arched phalanges (toes)
  let toeOffsets = [
    { dx: -16, dy: -22, rx: 22, ry: 9, rot: -12 },
    { dx: 0,   dy: -9,  rx: 25, ry: 10, rot: -4 },
    { dx: 4,   dy: 6,   rx: 24, ry: 10, rot: 5 },
    { dx: -10, dy: 19,  rx: 20, ry: 8,  rot: 14 }
  ];

  for (let t of toeOffsets) {
    let tx = t.dx * scaleF, ty = t.dy * scaleF;
    let rx = t.rx * scaleF, ry = t.ry * scaleF;

    // Shadow under toe
    brush.noStroke();
    brush.fill(PAL.voidUmber, 210);
    polyShape(ellipsePoints(tx + 3, ty + 4, rx, ry, t.rot, 16, 1), 0.3);

    // Terracotta toe body
    brush.fill(PAL.burntSienna, 225);
    polyShape(ellipsePoints(tx, ty, rx, ry, t.rot, 16, 1), 0.3);
    brush.noFill();

    // Knuckle top highlight in pale slip
    brush.set("clay_shader", PAL.paleSlip, 0.7 * scaleF);
    brush.spline([
      [tx - rx * 0.6, ty - ry * 0.35, 0.4],
      [tx, ty - ry * 0.55, 1.0],
      [tx + rx * 0.55, ty - ry * 0.2, 0.4]
    ], 0.35);

    // Knuckle crease shadow
    brush.set("sculpt_fine", PAL.darkUmber, 0.65 * scaleF);
    brush.spline([
      [tx - rx * 0.5, ty + ry * 0.45, 0.4],
      [tx, ty + ry * 0.65, 1.0],
      [tx + rx * 0.6, ty + ry * 0.3, 0.4]
    ], 0.3);

    // Blunt clay claw at tip
    let cxTip = tx + rx * 0.92;
    let cyTip = ty + ry * 0.1;
    brush.set("sculpt_fine", PAL.darkUmber, 0.9 * scaleF);
    brush.line(cxTip - 4 * scaleF, cyTip - 2 * scaleF, cxTip + 7 * scaleF, cyTip + 2 * scaleF);
    brush.set("sculpt_fine", PAL.chalkSlip, 0.55 * scaleF);
    brush.line(cxTip - 3 * scaleF, cyTip - 3 * scaleF, cxTip + 5 * scaleF, cyTip);
  }

  // Sculpted leathery/earthenware Paw Pads (if turned slightly toward viewer)
  if (showPads) {
    // Central bilobed metacarpal/metatarsal pad
    let mPad = [
      [-34 * scaleF, -8 * scaleF],
      [-18 * scaleF, -16 * scaleF],
      [-8 * scaleF,  -4 * scaleF],
      [-10 * scaleF, 12 * scaleF],
      [-22 * scaleF, 18 * scaleF],
      [-36 * scaleF, 6 * scaleF]
    ];
    brush.noStroke();
    brush.wash(PAL.darkUmber, 245);
    polyShape(mPad, 0.35);
    brush.noWash();

    // Rim light on pad edge catching directional light
    brush.set("sculpt_fine", PAL.rawSienna, 0.65 * scaleF);
    brush.spline([mPad[0], mPad[1], mPad[2]], 0.35);
    brush.set("sculpt_fine", PAL.paleSlip, 0.45 * scaleF);
    brush.line(mPad[0][0], mPad[0][1], mPad[1][0], mPad[1][1]);

    // Deep pad crease
    brush.set("sculpt_fine", PAL.voidUmber, 0.85 * scaleF);
    brush.spline([mPad[2], mPad[3], mPad[4], mPad[5]], 0.35);

    // 4 oval digital pads beneath the toes
    let dPads = [
      { x: 2 * scaleF,  y: -19 * scaleF, rx: 8 * scaleF, ry: 5 * scaleF },
      { x: 16 * scaleF, y: -7 * scaleF,  rx: 9 * scaleF, ry: 5.5 * scaleF },
      { x: 18 * scaleF, y: 7 * scaleF,   rx: 9 * scaleF, ry: 5.5 * scaleF },
      { x: 5 * scaleF,  y: 19 * scaleF,  rx: 8 * scaleF, ry: 4.8 * scaleF }
    ];
    for (let dp of dPads) {
      let pts = ellipsePoints(dp.x, dp.y, dp.rx, dp.ry, 10, 14, 0.5);
      brush.noStroke();
      brush.wash(PAL.darkUmber, 245);
      polyShape(pts, 0.35);
      brush.noWash();

      // Pad texture & subtle top bevel
      brush.set("sculpt_fine", PAL.ironOxide, 0.6 * scaleF);
      brush.arc(dp.x, dp.y, dp.rx * 0.75, 190, 340);
      brush.set("sculpt_fine", PAL.buffClay, 0.45 * scaleF);
      brush.arc(dp.x, dp.y, dp.rx * 0.85, 210, 310);
      brush.set("sculpt_fine", PAL.voidUmber, 0.75 * scaleF);
      brush.arc(dp.x, dp.y, dp.rx * 0.9, 15, 175);
    }
  }

  pop();
}

