function renderRibcageAndThorax() {
  // The greyhound's deep thorax is the centerpiece of the sculpture.
  // We model 10 anatomical ribs arcing from near the thoracic spine down to the sternum/costal arch.
  let ribs = [
    { p0: [430, 325], p1: [425, 395], p2: [410, 470], p3: [395, 525], w: 20, prominence: 0.55 },
    { p0: [468, 295], p1: [468, 378], p2: [452, 465], p3: [435, 545], w: 24, prominence: 0.85 },
    { p0: [508, 272], p1: [515, 362], p2: [500, 462], p3: [478, 555], w: 26, prominence: 1.00 },
    { p0: [548, 256], p1: [562, 350], p2: [548, 458], p3: [522, 558], w: 27, prominence: 1.05 },
    { p0: [590, 248], p1: [610, 342], p2: [596, 450], p3: [568, 550], w: 27, prominence: 1.05 },
    { p0: [632, 246], p1: [656, 338], p2: [642, 440], p3: [612, 532], w: 25, prominence: 0.98 },
    { p0: [674, 250], p1: [700, 336], p2: [684, 425], p3: [652, 502], w: 23, prominence: 0.90 },
    { p0: [715, 258], p1: [740, 335], p2: [722, 408], p3: [688, 468], w: 20, prominence: 0.78 },
    { p0: [754, 270], p1: [775, 335], p2: [755, 392], p3: [722, 438], w: 17, prominence: 0.62 },
    { p0: [788, 286], p1: [804, 338], p2: [785, 378], p3: [755, 412], w: 14, prominence: 0.45 }
  ];

  // Pass 1: Soft sculptural ridges and intercostal furrows along each rib
  for (let rIdx = 0; rIdx < ribs.length; rIdx++) {
    let r = ribs[rIdx];
    let steps = 22;

    // Draw 7 parallel offset splines per rib to build a smooth cylindrical 3D wave
    // Light is from top-left: left/upper bevel of each rib catches light (-n), right/lower bevel drops into shadow (+n)
    let offsets = [
      { frac: -0.58, col: PAL.DarkIntercostal || PAL.ironOxide, wt: 0.75 },
      { frac: -0.35, col: PAL.paleSlip,    wt: 1.15 },
      { frac: -0.15, col: PAL.chalkSlip,   wt: 1.35 },
      { frac:  0.05, col: PAL.rawSienna,   wt: 1.25 },
      { frac:  0.28, col: PAL.burntSienna, wt: 1.20 },
      { frac:  0.48, col: PAL.ironOxide,   wt: 1.15 },
      { frac:  0.68, col: PAL.rawUmber,    wt: 0.95 }
    ];

    for (let o of offsets) {
      let ptsUp = []; // Upper half of rib (brighter)
      let ptsLo = []; // Lower half of rib (transitions into belly shadow)
      for (let i = 0; i <= steps; i++) {
        let t = i / steps;
        let p = evalBezier(r.p0, r.p1, r.p2, r.p3, t);
        let tang = evalBezierTangent(r.p0, r.p1, r.p2, r.p3, t);
        // Normal pointing toward posterior/right (+x)
        let nx = -tang[1], ny = tang[0];
        if (nx < 0) { nx = -nx; ny = -ny; }

        let env = sin(t * 180) * r.prominence;
        let offDist = o.frac * r.w * (0.65 + 0.35 * env);
        let px = p[0] + nx * offDist;
        let py = p[1] + ny * offDist;
        let pr = (0.25 + 0.95 * env) * r.prominence;

        if (t <= 0.65) ptsUp.push([px, py, pr]);
        if (t >= 0.45) ptsLo.push([px, py, pr]);
      }

      brush.set("clay_shader", o.col, o.wt * r.prominence);
      brush.spline(ptsUp, 0.35);

      // Darken color on the lower belly curve of the rib
      let loCol = o.col;
      if (o.col === PAL.chalkSlip) loCol = PAL.buffClay;
      else if (o.col === PAL.paleSlip) loCol = PAL.rawSienna;
      else if (o.col === PAL.rawSienna) loCol = PAL.burntSienna;
      else if (o.col === PAL.burntSienna) loCol = PAL.ironOxide;
      else loCol = PAL.darkUmber;

      brush.set("clay_shader", loCol, o.wt * r.prominence * 0.9);
      brush.spline(ptsLo, 0.35);
    }

    // Pass 2: Fine cross-contour clay-modelling & short coat strokes bridging across the rib
    for (let i = 2; i < steps - 1; i++) {
      let t = i / steps;
      let p = evalBezier(r.p0, r.p1, r.p2, r.p3, t);
      let tang = evalBezierTangent(r.p0, r.p1, r.p2, r.p3, t);
      let nx = -tang[1], ny = tang[0];
      if (nx < 0) { nx = -nx; ny = -ny; }

      // Lit bevel strokes (upper-left side of rib ridge)
      if (t < 0.72) {
        let col = (t < 0.45 && random() < 0.6) ? PAL.chalkSlip : PAL.paleSlip;
        brush.set("sculpt_fine", col, random(0.55, 0.95) * r.prominence);
        let sx = p[0] - nx * r.w * 0.42;
        let sy = p[1] - ny * r.w * 0.42;
        let ex = p[0] + nx * r.w * 0.05 + tang[0] * 8;
        let ey = p[1] + ny * r.w * 0.05 + tang[1] * 8;
        brush.line(sx, sy, ex, ey);
      }

      // Shadow furrow strokes (posterior/right side of rib ridge)
      let sCol = (t > 0.55) ? PAL.darkUmber : PAL.ironOxide;
      brush.set("sculpt_fine", sCol, random(0.6, 1.0) * r.prominence);
      let sx2 = p[0] + nx * r.w * 0.15;
      let sy2 = p[1] + ny * r.w * 0.15;
      let ex2 = p[0] + nx * r.w * 0.72 + tang[0] * 10;
      let ey2 = p[1] + ny * r.w * 0.72 + tang[1] * 10;
      brush.line(sx2, sy2, ex2, ey2);
    }
  }

  // Costal arch ridge (the sweeping cartilaginous rim along the bottom of the ribcage into the waist tuck-up)
  let costalArch = sampleBezierSpline([435, 562], [555, 565], [645, 515], [718, 438], 18, 1.2, [0.5, 1.2]);
  brush.set("clay_shader", PAL.rawUmber, 1.35);
  brush.spline(costalArch, 0.35);

  let costalHighlight = sampleBezierSpline([440, 548], [555, 548], [640, 498], [712, 425], 18, 1.0, [0.4, 1.0]);
  brush.set("clay_shader", PAL.rawSienna, 0.95);
  brush.spline(costalHighlight, 0.35);

  // Deep abdominal tuck-up hollow (between last rib at x=720 and hip/thigh at x=775)
  for (let i = 0; i < 45; i++) {
    let t = i / 45;
    let x = lerp(695, 775, t) + random(-8, 8);
    let y = lerp(445, 365, t) + random(-12, 12);
