function renderPelvisAndHaunch() {
  // 1. Iliac Crest (the two prominent pelvic hook bones of a greyhound at (835, 325) and (865, 355))
  for (let bump of [
    { x: 830, y: 322, r: 22 },
    { x: 868, y: 356, r: 20 }
  ]) {
    brush.set("clay_shader", PAL.chalkSlip, 1.15);
    brush.arc(bump.x - 4, bump.y - 4, bump.r, 175, 325);
    brush.set("clay_shader", PAL.paleSlip, 1.25);
    brush.arc(bump.x, bump.y, bump.r * 0.7, 165, 340);
    brush.set("clay_shader", PAL.ironOxide, 1.15);
    brush.arc(bump.x + 4, bump.y + 4, bump.r, 10, 155);
  }

  // 2. Greater Trochanter of the femur at (892, 465) and Ischial Tuberosity (pin bone) at (958, 485)
  brush.set("clay_shader", PAL.paleSlip, 1.1);
  brush.arc(888, 462, 24, 165, 315);
  brush.set("clay_shader", PAL.darkUmber, 1.1);
  brush.arc(895, 468, 24, 5, 145);

  // 3. Sweeping 3D muscular dome of the Haunch (Quadriceps & Biceps Femoris)
  // Curves from pelvis (850, 350) out through (940, 520) down to stifle (800, 690) and hock (942, 792)
  let numBands = 28;
  for (let i = 0; i <= numBands; i++) {
    let u = i / numBands; // 0 = anterior/inner thigh (lit upper-left), 1 = posterior/outer haunch (shadowed lower-right)
    let p0 = [lerp(765, 895, u), lerp(415, 350, u)];
    let p1 = [lerp(765, 975, u), lerp(515, 485, u)];
    let p2 = [lerp(775, 982, u), lerp(615, 635, u)];
    let p3 = [lerp(800, 945, u), lerp(692, 792, u)];

    let col;
    if (u < 0.18) col = PAL.rawSienna;
    else if (u < 0.38) col = PAL.paleSlip;
    else if (u < 0.55) col = PAL.rawSienna;
    else if (u < 0.72) col = PAL.burntSienna;
    else if (u < 0.86) col = PAL.ironOxide;
    else col = PAL.darkUmber;

    let pts = sampleBezierSpline(p0, p1, p2, p3, 16, 1.2, [0.4, 1.15]);
    brush.set("clay_shader", col, random(0.9, 1.35));
    brush.spline(pts, 0.35);
  }

  // Deep anatomical intermuscular groove between quadriceps and biceps femoris
  let thighGroove = sampleBezierSpline([865, 425], [848, 515], [828, 605], [805, 685], 16, 0.6, [0.4, 1.2]);
  brush.set("sculpt_fine", PAL.ironOxide, 1.1);
  brush.spline(thighGroove, 0.35);

  let thighGrooveLit = sampleBezierSpline([873, 428], [856, 518], [836, 608], [812, 686], 16, 0.6, [0.4, 1.1]);
  brush.set("sculpt_fine", PAL.paleSlip, 0.85);
  brush.spline(thighGrooveLit, 0.35);

  // Hundreds of fine directional short-coat / clay-comb strokes curving around the muscular haunch
  for (let i = 0; i < 220; i++) {
    let u = random();
    let t = random();
    let p0 = [lerp(765, 895, u), lerp(415, 350, u)];
    let p1 = [lerp(765, 975, u), lerp(515, 485, u)];
    let p2 = [lerp(775, 982, u), lerp(615, 635, u)];
    let p3 = [lerp(800, 945, u), lerp(692, 792, u)];
    let pos = evalBezier(p0, p1, p2, p3, t);
    let tang = evalBezierTangent(p0, p1, p2, p3, t);

    let col;
    if (u < 0.42 && t < 0.55) col = (random() < 0.45) ? PAL.chalkSlip : PAL.paleSlip;
    else if (u < 0.65 && t < 0.7) col = PAL.rawSienna;
    else if (u < 0.82) col = PAL.ironOxide;
    else col = PAL.voidUmber;

    let sLen = random(16, 36);
    brush.set("sculpt_fine", col, random(0.45, 0.85));
    brush.line(pos[0] - tang[0] * sLen * 0.4, pos[1] - tang[1] * sLen * 0.4, pos[0] + tang[0] * sLen * 0.6, pos[1] + tang[1] * sLen * 0.6);
  }
}

function renderSpineVertebrae() {
  // The prominent dorsal ridge of the greyhound's spine curving from withers (360, 355) over the thoracic/lumbar arch to sacrum (885, 375)
  let p0 = [345, 385], p1 = [485, 215], p2 = [735, 205], p3 = [895, 385];

  // Outer dorsal rim highlight (catching top-left grazing light)
  let dorsalLit = sampleBezierSpline([342, 380], [482, 210], [735, 200], [895, 380], 28, 0.6, [0.5, 1.2]);
  brush.set("clay_shader", PAL.chalkSlip, 1.15);
  brush.spline(dorsalLit, 0.35);

  // Subtle para-spinal furrow just inside the spine ridge
  let dorsalFurrow = sampleBezierSpline([355, 396], [492, 232], [732, 222], [882, 395], 28, 0.8, [0.5, 1.1]);
  brush.set("clay_shader", PAL.burntSienna, 1.05);
  brush.spline(dorsalFurrow, 0.35);

  // 20 individual vertebral spinous processes (knobby earthenware bumps along the spine)
  let numVert = 20;
  for (let i = 0; i < numVert; i++) {
    let t = map(i, 0, numVert - 1, 0.06, 0.95);
    let pos = evalBezier(p0, p1, p2, p3, t);
    let tang = evalBezierTangent(p0, p1, p2, p3, t);
    let nx = -tang[1], ny = tang[0];

    // Lumbar vertebrae (t = 0.55..0.85) are especially prominent in a greyhound
    let sz = (t > 0.5 && t < 0.85) ? 11.5 : 8.5;

    // Shadow on posterior-lower side of vertebral bump
    brush.set("sculpt_fine", PAL.ironOxide, 0.95);
    brush.spline([
      [pos[0] + nx * 3, pos[1] + ny * 3, 0.4],
      [pos[0] + tang[0] * sz + nx * 6, pos[1] + tang[1] * sz + ny * 6, 1.0],
      [pos[0] + tang[0] * sz * 1.4 - nx * 4, pos[1] + tang[1] * sz * 1.4 - ny * 4, 0.4]
    ], 0.35);

    // Chalky slip highlight on anterior-upper side of vertebral bump
    brush.set("sculpt_fine", PAL.chalkSlip, 0.95);
    brush.spline([
      [pos[0] - tang[0] * sz * 0.9 - nx * 3, pos[1] - tang[1] * sz * 0.9 - ny * 3, 0.4],
      [pos[0] - tang[0] * sz * 0.2 + nx * 4, pos[1] - tang[1] * sz * 0.2 + ny * 4, 1.1],
      [pos[0] + tang[0] * sz * 0.5, pos[1] + tang[1] * sz * 0.5, 0.4]
    ], 0.35);
  }
}

