function renderWhipTail() {
  // The long, slender whip tail of the greyhound:
  // Emerges from croup (952, 465), wraps outside the haunch (996, 615) -> (965, 815) -> sweeps along bottom (775, 922) -> (585, 918) -> curls tip (495, 882) -> (462, 838) right against the nose!
  let segA = [[952, 465], [998, 560], [1002, 710], [952, 835]];
  let segB = [[952, 835], [885, 928], [665, 942], [498, 885]];
  let segC = [[498, 885], [468, 868], [458, 845], [472, 828]];

  let allTailPts = [];
  for (let i = 0; i <= 24; i++) {
    let t = i / 24;
    let p = evalBezier(segA[0], segA[1], segA[2], segA[3], t);
    let tang = evalBezierTangent(segA[0], segA[1], segA[2], segA[3], t);
    let r = lerp(15, 10.5, t);
    allTailPts.push({ p, tang, r });
  }
  for (let i = 1; i <= 26; i++) {
    let t = i / 26;
    let p = evalBezier(segB[0], segB[1], segB[2], segB[3], t);
    let tang = evalBezierTangent(segB[0], segB[1], segB[2], segB[3], t);
    let r = lerp(10.5, 6.0, t);
    allTailPts.push({ p, tang, r });
  }
  for (let i = 1; i <= 10; i++) {
    let t = i / 10;
    let p = evalBezier(segC[0], segC[1], segC[2], segC[3], t);
    let tang = evalBezierTangent(segC[0], segC[1], segC[2], segC[3], t);
    let r = lerp(6.0, 3.2, t);
    allTailPts.push({ p, tang, r });
  }

  // Draw tail cross-contour rings & longitudinal shading
  for (let u of [-0.85, -0.5, -0.15, 0.2, 0.55, 0.85]) {
    let spinePts = [];
    for (let node of allTailPts) {
      // Normal pointing toward top-left light source (-0.7, -0.7)
      let nx = -node.tang[1], ny = node.tang[0];
      let px = node.p[0] + nx * node.r * u;
      let py = node.p[1] + ny * node.r * u;
      spinePts.push([px, py, 0.9]);
    }
    let col;
    if (u > 0.45) col = PAL.paleSlip;
    else if (u > 0.05) col = PAL.rawSienna;
    else if (u > -0.35) col = PAL.burntSienna;
    else if (u > -0.7) col = PAL.ironOxide;
    else col = PAL.voidUmber;

    brush.set("clay_shader", col, 0.85);
    brush.spline(spinePts, 0.3);
  }

  // Subtle tail vertebral ring segments (every 3rd node)
  for (let i = 2; i < allTailPts.length - 2; i += 3) {
    let nd = allTailPts[i];
    let nx = -nd.tang[1], ny = nd.tang[0];
    brush.set("sculpt_fine", PAL.darkUmber, 0.65);
    brush.line(nd.p[0] - nx * nd.r * 0.8, nd.p[1] - ny * nd.r * 0.8, nd.p[0] + nx * nd.r * 0.4, nd.p[1] + ny * nd.r * 0.4);
    brush.set("sculpt_fine", PAL.chalkSlip, 0.55);
    brush.line(nd.p[0] + nx * nd.r * 0.2, nd.p[1] + ny * nd.r * 0.2, nd.p[0] + nx * nd.r * 0.85, nd.p[1] + ny * nd.r * 0.85);
  }
}

