// ============================================================================
// 6. POWDERY SLIP TEXTURE, SHORT COAT STRIATIONS & HAIRLINE FIRING CRACKS
// ============================================================================

function renderSurfaceGranulationAndFur() {
  // 1. Powdery kiln-dust & dry slip granulation across the entire earthenware body
  let bodyZones = [
    { cx: 560, cy: 360, rx: 210, ry: 120, count: 240, lit: true },  // Ribcage & back
    { cx: 865, cy: 535, rx: 105, ry: 175, count: 160, lit: false }, // Haunch & pelvis
    { cx: 295, cy: 565, rx: 65,  ry: 125, count: 110, lit: true },  // Neck & shoulder
    { cx: 375, cy: 785, rx: 105, ry: 65,  count: 90,  lit: true }   // Head & muzzle
  ];

  for (let z of bodyZones) {
    for (let i = 0; i < z.count; i++) {
      let a = random(360);
      let r = sqrt(random()) * 0.92;
      let px = z.cx + cos(a) * z.rx * r;
      let py = z.cy + sin(a) * z.ry * r;

      // Determine local directional light value (top-left is brightest)
      let lightScore = (650 - px) * 0.6 + (620 - py) * 0.8 + random(-90, 90);
      let col;
      if (lightScore > 180) col = PAL.chalkSlip;
      else if (lightScore > 70) col = PAL.paleSlip;
      else if (lightScore > -40) col = PAL.rawSienna;
      else if (lightScore > -150) col = PAL.burntSienna;
      else col = PAL.ironOxide;

      brush.set("kiln_dust", col, random(0.45, 1.15));
      brush.line(px, py, px + random(-14, 14), py + random(-14, 14));
    }
  }

  // 2. Hyper-fine short coat / clay-burnishing striations following the dorsal-to-ventral flow
  for (let i = 0; i < 420; i++) {
    let t = random(0.05, 0.95);
    let spineP = evalBezier([340, 395], [485, 225], [735, 215], [895, 395], t);
    let tang = evalBezierTangent([340, 395], [485, 225], [735, 215], [895, 395], t);
    // Normal pointing down into the ribcage/flank
    let nx = -tang[1], ny = tang[0];
    if (ny < 0) { nx = -nx; ny = -ny; }

    let depth = random(5, 230) * (t < 0.72 ? 1.0 : 0.65);
    let px = spineP[0] + nx * depth + random(-10, 10);
    let py = spineP[1] + ny * depth + random(-10, 10);

    // Coat hairs flow backward along the spine at top, curving downward across the ribs
    let flowAng = atan2(tang[1] * 0.65 + ny * 0.55, tang[0] * 0.65 + nx * 0.55) + random(-10, 10);
    let sLen = random(12, 26);

    let col;
    if (depth < 55 && t < 0.75) col = (random() < 0.55) ? PAL.chalkSlip : PAL.paleSlip;
    else if (depth < 125) col = (random() < 0.5) ? PAL.rawSienna : PAL.terraMid;
    else if (depth < 185) col = PAL.burntSienna;
    else col = PAL.darkUmber;

    brush.set("sculpt_fine", col, random(0.35, 0.7));
    brush.line(px, py, px + cos(flowAng) * sLen, py + sin(flowAng) * sLen);
  }
}

// Helper to draw a realistic hairline kiln firing crack with a dark fissure and slip-white lower-right rim
function drawKilnCrack(startPt, initAngle, totalSteps, stepLen = 9, canBranch = true) {
  let ptsDark = [];
  let ptsLight = [];
  let cx = startPt[0], cy = startPt[1];
  let ang = initAngle;

  for (let i = 0; i <= totalSteps; i++) {
    let pr = sin((i / totalSteps) * 180);
    ptsDark.push([cx, cy, 0.25 + 0.85 * pr]);
    // Offset by +1.4 px toward bottom-right so the lower-right lip catches the top-left directional light!
    ptsLight.push([cx + 1.4, cy + 1.4, 0.2 + 0.75 * pr]);

    // Slightly jittery ceramic fracture walk
    ang += random(-24, 24);
    cx += cos(ang) * stepLen;
    cy += sin(ang) * stepLen;

    // Occasional micro-branching
    if (canBranch && i > 3 && i < totalSteps - 3 && random() < 0.22) {
      let bAng = ang + (random() < 0.5 ? 42 : -42) + random(-10, 10);
      drawKilnCrack([cx, cy], bAng, int(totalSteps * 0.48), stepLen * 0.8, false);
    }
  }

  // 1. Soft iron-oxide stain along the crack
  brush.set("sculpt_fine", PAL.ironOxide, 0.45);
  brush.spline(ptsDark, 0.2);

  // 2. Razor-sharp dark umber fissure core
  brush.set("crack_needle", PAL.voidUmber, 0.85);
  brush.spline(ptsDark, 0.15);

  // 3. Chalky slip-white micro-highlight on the lower-right fracture lip
  brush.set("crack_needle", PAL.chalkSlip, 0.65);
  brush.spline(ptsLight, 0.15);
}

