let balloons = [];
let lampPos;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(8472);
  noiseSeed(8472);

  // Register custom hyperrealism brushes tuned for 1200x1200 canvas
  brush.add("soft_charcoal", {
    type: "default",
    weight: 14,
    scatter: 0.85,
    sharpness: 0.12,
    grain: 38,
    opacity: 42,
    spacing: 0.35,
    pressure: [0.2, 1.0, 0.2],
    rotate: "natural",
    noise: 0.6
  });

  brush.add("smudge_tone", {
    type: "default",
    weight: 22,
    scatter: 1.1,
    sharpness: 0.06,
    grain: 22,
    opacity: 26,
    spacing: 0.4,
    pressure: [0.15, 0.95, 0.15],
    rotate: "natural",
    noise: 0.35
  });

  brush.add("fine_graphite", {
    type: "default",
    weight: 1.6,
    scatter: 0.22,
    sharpness: 0.65,
    grain: 45,
    opacity: 68,
    spacing: 0.22,
