  });

  // Unseen lamp below and slightly toward the lower-right
  lampPos = { x: 760, y: 830, z: -640 };

  generateMammatusBalloons();
}

function generateMammatusBalloons() {
  balloons = [];

  // Seed initial packed centers covering canvas + bleed margin
  let candidates = [];
  let idx = 0;
  for (let gx = -90; gx <= 1290; gx += 165) {
    for (let gy = -90; gy <= 1290; gy += 165) {
      let jx = gx + random(-52, 52);
      let jy = gy + random(-52, 52);
      let distCenter = dist(jx, jy, 620, 620);
      // Mix of large heavy lobes and smaller wedged balloons
      let baseR = map(noise(jx * 0.003, jy * 0.003), 0, 1, 88, 178);
      if (random() < 0.28) baseR *= random(1.08, 1.22);
      if (random() < 0.22) baseR *= random(0.76, 0.88);
      candidates.push({
        id: idx++,
        x: jx,
        y: jy,
        r: baseR,
        zHang: 0,
        paletteType: floor(random(3)) // 0: stormy slate, 1: bruised mauve, 2: dusty plum
      });
    }
  }

  // Iterative packing relaxation so lobes press together tightly like mammatus clouds
  for (let iter = 0; iter < 24; iter++) {
    for (let i = 0; i < candidates.length; i++) {
      let fx = 0;
      let fy = 0;
      let a = candidates[i];
      for (let j = 0; j < candidates.length; j++) {
        if (i === j) continue;
        let b = candidates[j];
        let dx = a.x - b.x;
        let dy = a.y - b.y;
        let d = sqrt(dx * dx + dy * dy) + 0.001;
        let targetD = (a.r + b.r) * 0.76;
        if (d < targetD) {
          let push = (targetD - d) * 0.28;
          fx += (dx / d) * push;
          fy += (dy / d) * push;
        } else if (d < targetD * 1.25) {
          // Slight attraction to keep the ceiling claustrophobically crowded
          let pull = (d - targetD) * 0.03;
          fx -= (dx / d) * pull;
          fy -= (dy / d) * pull;
        }
      }
      a.x += fx;
      a.y += fy;
    }
  }

  // Filter balloons that are visible on the 1200x1200 canvas
  for (let c of candidates) {
    if (c.x + c.r > -40 && c.x - c.r < 1240 && c.y + c.r > -40 && c.y - c.r < 1240) {
      // Larger balloons and central/lamp-side balloons hang lower in heavy pendulous lobes
      let nVal = noise(c.x * 0.004 + 10, c.y * 0.004 + 10);
      let sizeFactor = constrain(map(c.r, 80, 195, 0.25, 0.95), 0.15, 1.0);
      c.zHang = constrain(sizeFactor * 0.65 + nVal * 0.45 + random(-0.12, 0.12), 0.18, 1.05);
      c.bellyZ = -c.zHang * c.r * 0.92; // Z coordinate of lowest hanging point (negative is closer to viewer)
      c.tiltAngle = random(360);
      c.tiltAmount = random(0.02, 0.065);
      balloons.push(c);
    }
  }

  // Compute deformed contour for each balloon based on mutual compression
  let numAngles = 64;
  for (let i = 0; i < balloons.length; i++) {
    let b = balloons[i];
    let rawRadii = new Array(numAngles);

    // Find net pressure vector from neighbors to slightly displace the knot
    let pressX = 0;
    let pressY = 0;

    for (let k = 0; k < numAngles; k++) {
      let ang = (k / numAngles) * 360;
      let rad = radians(ang);
      let dirX = cos(rad);
      let dirY = sin(rad);

      // Natural slightly pear-shaped / organic radius
      let nR = noise(b.x * 0.01 + dirX * 1.3, b.y * 0.01 + dirY * 1.3);
      let rNat = b.r * (1.0 + b.tiltAmount * cos(ang - b.tiltAngle) + (nR - 0.5) * 0.08);

      // Smooth-min compression against all nearby neighbor balloons
      let kSoft = 0.075; // Softness of triple-junction rounding
      let sumExp = exp(-kSoft * rNat);

      for (let j = 0; j < balloons.length; j++) {
        if (i === j) continue;
        let nb = balloons[j];
        let dx = nb.x - b.x;
        let dy = nb.y - b.y;
        let D = sqrt(dx * dx + dy * dy);
        if (D > (b.r + nb.r) * 1.35) continue;

        let cosAlpha = (dx * dirX + dy * dirY) / D;
        if (cosAlpha > 0.12) {
          // Power diagram bisector shifted by relative vertical hang (lower lobes overlap slightly over higher ones)
          let zShift = (b.zHang - nb.zHang) * 34;
          let dInterface = (D * D + b.r * b.r - nb.r * nb.r) / (2 * D) + zShift;
          dInterface = constrain(dInterface, b.r * 0.38, b.r * 1.15);
          let rPlane = (dInterface - 1.5) / pow(cosAlpha, 0.92);
          sumExp += exp(-kSoft * rPlane);

          if ( k === 0 ) {
            pressX -= (dx / D) * (1.0 / (D + 10));
            pressY -= (dy / D) * (1.0 / (D + 10));
          }
        }
      }

      rawRadii[k] = max(b.r * 0.36, -log(sumExp) / kSoft);
    }

    // Circular Gaussian smoothing so the compressed latex skin is taut and smooth
    b.radii = new Array(numAngles);
    b.contour = new Array(numAngles);
    let kernel = [0.06, 0.15, 0.24, 0.15, 0.06];
    let kSum = 0.66;
    let cx = 0;
    let cy = 0;

    for (let k = 0; k < numAngles; k++) {
      let acc = 0;
      for (let m = -2; m <= 2; m++) {
        let idxWrap = (k + m + numAngles) % numAngles;
        acc += rawRadii[idxWrap] * kernel[m + 2];
      }
      let rSmooth = acc / kSum;
      b.radii[k] = rSmooth;
      let ang = (k / numAngles) * 360;
      let px = b.x + rSmooth * cos(ang);
      let py = b.y + rSmooth * sin(ang);
      b.contour[k] = { x: px, y: py, r: rSmooth, ang: ang };
      cx += px;
      cy += py;
    }

    // Visual centroid of the compressed lobe
    b.cx = cx / numAngles;
    b.cy = cy / numAngles;

    // Knot position: pulled slightly toward the visual nadir, with subtle tilt on edge balloons
    let edgeDist = dist(b.cx, b.cy, 600, 600) / 850;
    let knotShiftR = b.r * random(0.04, 0.18) * (0.5 + 0.7 * edgeDist);
    let knotAng = atan2(pressY + (600 - b.cy) * 0.002, pressX + (600 - b.cx) * 0.002) + random(-35, 35);
    b.knotX = b.cx + cos(knotAng) * knotShiftR;
    b.knotY = b.cy + sin(knotAng) * knotShiftR;
    b.knotOrient = knotAng + random(-40, 40);
    b.hasRibbon = random() < 0.72;
    b.ribbonLong = random() < 0.34;
  }

  // Sort from highest recessed balloons to lowest hanging pendulous lobes
  balloons.sort((a, b) => a.zHang - b.zHang);
}

// Evaluate 3D surface position and unit normal on balloon b at normalized radius u in [0,1] and angle ang
function evalBalloonSurface(b, kIdx, u) {
  let numAngles = b.radii.length;
  let idx0 = (( floor(kIdx) % numAngles ) + numAngles) % numAngles;
  let idx1 = (idx0 + 1) % numAngles;
  let frac = kIdx - floor(kIdx);
  let rMax = lerp(b.radii[idx0], b.radii[idx1], frac);
  let ang = (kIdx / numAngles) * 360;

  let c = cos(ang);
  let s = sin(ang);
  let px = lerp(b.cx, b.x + rMax * c, u);
  let py = lerp(b.cy, b.y + rMax * s, u);

  // Heavy pendulous mammatus dome profile
  let uClamped = constrain(u, 0, 0.999);
  let profile = pow(1.0 - pow(uClamped, 2.15), 0.58);
  let pz = b.bellyZ * profile;

  // Normal vector pointing outward/downward toward viewer (-Z)
  let dzdu = pow(uClamped, 1.15) / max(0.14, pow(1.0 - pow(uClamped, 2.15), 0.42));
  let nx = c * dzdu * 0.88;
  let ny = s * dzdu * 0.88;
  let nz = -1.0;
  let nLen = sqrt(nx * nx + ny * ny + nz * nz);

  return {
    x: px,
    y: py,
    z: pz,
    nx: nx / nLen,
    ny: ny / nLen,
    nz: nz / nLen,
    rMax: rMax,
    ang: ang
  };
}

// Compute lamp illumination, inter-balloon cast shadow, and specular latex sheen at surface point pt
function computePointLighting(b, pt, u) {
  let lx = lampPos.x - pt.x;
  let ly = lampPos.y - pt.y;
  let lz = lampPos.z - pt.z;
  let lDist = sqrt(lx * lx + ly * ly + lz * lz);
  lx /= lDist;
  ly /= lDist;
  lz /= lDist;

  // Distance falloff from the unseen lamp
  let atten = constrain(map(lDist, 320, 1380, 1.18, 0.16), 0.12, 1.2);

  // Lambertian + Oren-Nayar broad matte latex diffuse response
  let nDotL = pt.nx * lx + pt.ny * ly + pt.nz * lz;
  let diffuse = pow( max(0, nDotL + 0.14) / 1.14, 1.45 ) * atten;

  // Inter-balloon shadow occlusion: check if lower-hanging neighbors block the ray to lampPos
  let shadow = 1.0;
  for (let j = 0; j < balloons.length; j++) {
    let nb = balloons[j];
    if (nb.id === b.id) continue;
    // Only balloons that hang at least nearly as low can cast significant shadows from below
    if (nb.zHang < b.zHang - 0.08) continue;

    // Project ray at parameter t along path toward lamp
    let dx = nb.cx - pt.x;
    let dy = nb.cy - pt.y;
    let proj2D = dx * lx + dy * ly;
    if (proj2D > 12 && proj2D < 320) {
      let rayX = pt.x + lx * proj2D;
      let rayY = pt.y + ly * proj2D;
      let rayZ = pt.z + lz * proj2D;
      let dToCenter = dist(rayX, rayY, nb.cx, nb.cy);
      let effR = nb.r * 0.86;
      if (dToCenter < effR && rayZ > nb.bellyZ * 0.92) {
        let penumbra = constrain(map(dToCenter, effR * 0.45, effR, 0.12, 1.0), 0.12, 1.0);
        shadow = min(shadow, penumbra);
      }
    }
  }

  // Deep crevice ambient occlusion near the compressed seams (u -> 1)
  let creviceAO = 1.0 - 0.84 * pow(u, 2.8);

  // Half-vector for matte latex sheen (viewer is looking straight up along +Z, so V = (0, 0, -1))
  let hx = lx;
  let hy = ly;
  let hz = lz - 1.0;
  let hLen = sqrt(hx * hx + hy * hy + hz * hz);
  hx /= hLen;
  hy /= hLen;
  hz /= hLen;
  let nDotH = max(0, pt.nx * hx + pt.ny * hy + pt.nz * hz);

  // Broad chalky latex sheen + tighter specular core
  let matteSheen = (0.55 * pow(nDotH, 7.5) + 0.45 * pow(nDotH, 24.0)) * shadow * atten;

  // Faint secondary rim bounce on the opposite curve from neighboring warm lobes
  let rimBounce = pow(constrain(u, 0, 1), 1.8) * (1.0 - pow(u, 6.0)) * max(0, -(pt.nx * lx + pt.ny * ly)) * 0.35;

  return {
    amberLight: diffuse * shadow * creviceAO,
    matteSheen: matteSheen * creviceAO,
    rimBounce: rimBounce,
    creviceAO: creviceAO,
    shadow: shadow
  };
}

function draw() {
  translate(-width / 2, -height / 2);

  // 1. Deep brooding charcoal-slate ceiling abyss
  background("#0b0a0e");
  drawCeilingAbyss();

  // 2. Base washes & watercolor glazes (batched and layered back-to-front)
  for (let i = 0; i < balloons.length; i++) {
    drawBalloonBaseGlazes(balloons[i]);
  }

  // 3. Sculptural charcoal & smudged graphite volumetric modeling + warm amber glazes + latex sheen
  for (let i = 0; i < balloons.length; i++) {
    drawBalloonVolumetricModeling(balloons[i]);
  }

  // 4. Deep pinched seams and triple-junction crevices between pressed lobes
  drawInterstitialCrevices();

  // 5. Wrinkled rubber knots and radial tension puckers
  for (let i = 0; i < balloons.length; i++) {
    drawBalloonKnot(balloons[i]);
  }

  // 6. Precisely rendered fallen crepe-paper streamer wedged and draped across the lobes
  drawFallenStreamer();

  // 7. Curling ribbons dangling down as fine pen lines with warm amber glints
  drawDanglingRibbons();

  // 8. Final atmospheric graphite dust & subtle brooding edge vignette
  drawAtmosphericFinish();

  noLoop();
}

function drawCeilingAbyss() {
  brush.noFill();
  brush.noHatch();
  // Dark textured charcoal tone in the ceiling depths visible through triple junctions
  brush.set("soft_charcoal", "#14131a", 2.2);
  for (let i = 0; i < 65; i++) {
    let x1 = random(-60, 1260);
    let y1 = random(-60, 1260);
    let ang = random(360);
    let len = random(180, 420);
    brush.line(x1, y1, x1 + cos(ang) * len, y1 + sin(ang) * len);
  }
}

function drawBalloonBaseGlazes(b) {
  let numAngles = b.contour.length;
  let step = 2; // 32 vertices per shape for crisp, fast fills

  // 2a. Dark occlusion halo underneath lower-hanging lobes
  if (b.zHang > 0.35) {
    brush.noFill();
    brush.set("soft_charcoal", "#07060a", map(b.zHang, 0.35, 1.05, 1.1, 2.3));
    let haloPts = [];
    for (let k = 0; k < numAngles; k += 2) {
      let c = b.contour[k];
      haloPts.push([b.x + (c.r + 6) * cos(c.ang), b.y + (c.r + 6) * sin(c.ang), 0.7]);
    }
    haloPts.push(haloPts[0]);
    brush.spline(haloPts, 0.5);
  }

  // 2b. Solid dark charcoal-slate base wash so lower lobes occlude upper lobes
  let baseHex = "#18171f";
  if (b.paletteType === 1) baseHex = "#1d1720"; // bruised mauve dark base
  if (b.paletteType === 2) baseHex = "#20181f"; // dusty plum dark base

  brush.noStroke();
  brush.noFill();
  brush.wash(baseHex, 238);
  brush.beginShape(0.45);
  for (let k = 0; k < numAngles; k += step) {
    let c = b.contour[k];
    brush.vertex(c.x, c.y);
  }
  brush.endShape(true);
  brush.noWash();

  // 2c. Glazed watercolor layer: bruised mauve, dusty plum, or stormy slate
  let glazeColors = ["#2e313d", "#433146", "#523a4b"];
  let glazeHex = glazeColors[b.paletteType];
  let centerPt = evalBalloonSurface(b, 0, 0.05);
  let centerLight = computePointLighting(b, centerPt, 0.05);

  brush.fill(glazeHex, 92);
  brush.fillBleed(0.16, "in");
  brush.fillTexture(0.55, 0.32);
  brush.beginShape(0.45);
  for (let k = 0; k < numAngles; k += step) {
    let c = b.contour[k];
    let ux = lerp(b.cx, c.x, 0.92);
    let uy = lerp(b.cy, c.y, 0.92);
    brush.vertex(ux, uy);
  }
  brush.endShape(true);

  // 2d. If the lobe catches significant unseen lamp light, add a warm amber-plum core glaze
  if (centerLight.amberLight > 0.22) {
    let toLampAng = atan2(lampPos.y - b.cy, lampPos.x - b.cx);
    let shiftX = cos(toLampAng) * b.r * 0.16;
    let shiftY = sin(toLampAng) * b.r * 0.16;
    let warmHex = centerLight.amberLight > 0.48 ? "#9e6d39" : "#6b4939";
    let warmAlpha = constrain(map(centerLight.amberLight, 0.22, 0.85, 38, 95), 35, 98);

    brush.fill(warmHex, warmAlpha);
    brush.fillBleed(0.22, "out");
    brush.fillTexture(0.48, 0.2);
    brush.beginShape(0.5);
    for (let k = 0; k < numAngles; k += 4) {
      let c = b.contour[k];
      let radScale = map(cos(c.ang - toLampAng), -1, 1, 0.42, 0.76);
      let wx = b.cx + shiftX + (c.x - b.cx) * radScale;
      let wy = b.cy + shiftY + (c.y - b.cy) * radScale;
      brush.vertex(wx, wy);
    }
    brush.endShape(true);
  }
  brush.noFill();
}

function drawBalloonVolumetricModeling(b) {
  let numAngles = b.radii.length;

  // Palette definitions for monochrome charcoal/graphite + bruised mauve/plum/slate + sickly warm amber
  let darkCharcoal = color("#0d0c11");
  let deepSlate = color("#1c1b24");
  let midToneColors = [
    color("#3a3e4d"), // stormy slate
    color("#4b384e"), // bruised mauve
    color("#5c4355")  // dusty plum
  ];
  let midColor = midToneColors[b.paletteType];
  let paleGraphite = color("#7e7a87");
  let sicklyAmberDark = color("#875c31");
  let sicklyAmberMid = color("#c78d42");
  let sicklyAmberBright = color("#ebb865");
  let latexHighlightWarm = color("#f7d999");
  let latexHighlightCool = color("#a8a2b2");

  // 3a. Concentric form-following charcoal & smudged tonal rings (from outer crevice u=0.96 inward to belly u=0.08)
  let numRings = 16;
  for (let rIdx = 0; rIdx < numRings; rIdx++) {
    let u = map(rIdx, 0, numRings - 1, 0.97, 0.11);

    // Divide each ring into 6 overlapping curved arc segments so color & pressure adapt locally around the bulge
    let numSegs = 6;
    let segSteps = floor(numAngles / numSegs);

    for (let s = 0; s < numSegs; s++) {
      let startK = s * segSteps;
      let midK = (startK + floor(segSteps / 2)) % numAngles;
      let midPt = evalBalloonSurface(b, midK, u);
      let light = computePointLighting(b, midPt, u);

      // Determine stroke color and brush based on 3D lighting at this zone of the lobe
      let segCol;
      let brushName = "smudge_tone";
      let weightMult = 1.0;

      if (u > 0.78) {
        // Deep compressed perimeter crease
        let t = map(u, 0.78, 0.97, 0, 1);
        let baseRim = lerpColor(midColor, darkCharcoal, 0.65 + 0.35 * t);
        if (light.amberLight > 0.25) {
          baseRim = lerpColor(baseRim, sicklyAmberDark, light.amberLight * 0.45 * (1 - t));
        } else if (light.rimBounce > 0.05) {
          baseRim = lerpColor(baseRim, paleGraphite, light.rimBounce * 0.6);
        }
        segCol = baseRim;
        brushName = u > 0.88 ? "soft_charcoal" : "smudge_tone";
        weightMult = map(u, 0.78, 0.97, 0.95, 0.65);
      } else {
        // Mid-belly to lowest curve: blend charcoal/mauve/plum/slate with sickly warm amber lamp light
        let baseTone = lerpColor(deepSlate, midColor, constrain(light.creviceAO * 1.1, 0, 1));
        if (light.shadow < 0.5) {
          baseTone = lerpColor(baseTone, darkCharcoal, (1.0 - light.shadow) * 0.72);
        }

        if (light.amberLight > 0.14) {
          let amberAmt = constrain(map(light.amberLight, 0.14, 0.85, 0.0, 0.95), 0, 0.95);
          let targetAmber = light.amberLight > 0.52
            ? lerpColor(sicklyAmberMid, sicklyAmberBright, map(light.amberLight, 0.52, 0.95, 0, 1))
            : lerpColor(sicklyAmberDark, sicklyAmberMid, map(light.amberLight, 0.14, 0.52, 0, 1));
          segCol = lerpColor(baseTone, targetAmber, amberAmt);
        } else {
          // Cool monochrome graphite/mauve highlight in upper shadowed lobes
          let coolLift = constrain((1.0 - u) * 0.45 * light.shadow, 0, 0.55);
          segCol = lerpColor(baseTone, paleGraphite, coolLift);
        }

        if (light.matteSheen > 0.18) {
          let sheenCol = light.amberLight > 0.25 ? latexHighlightWarm : latexHighlightCool;
          segCol = lerpColor(segCol, sheenCol, constrain(light.matteSheen * 0.65, 0, 0.65));
        }

        brushName = (rIdx % 2 === 0) ? "smudge_tone" : "soft_charcoal";
        weightMult = map(u, 0.11, 0.78, 0.75, 1.05);
      }

      let pts = [];
      for (let step = -1; step <= segSteps + 1; step++) {
        let k = (startK + step + numAngles) % numAngles;
        let pt = evalBalloonSurface(b, k, u);
        // Subtle hand-drawn organic jitter scaled by radius
        let jx = (noise(pt.x * 0.02, pt.y * 0.02, rIdx) - 0.5) * 3.5;
        let jy = (noise(pt.y * 0.02, pt.x * 0.02, rIdx + 10) - 0.5) * 3.5;
        let pPress = (step <= 0 || step >= segSteps) ? 0.25 : 0.9;
        pts.push([pt.x + jx, pt.y + jy, pPress]);
      }

      brush.set(brushName, segCol, weightMult);
      brush.spline(pts, 0.55);
    }
  }

  // 3b. Fine cross-contour graphite hatching (curved 3D meridians & latitude strokes modeling the spherical bulge)
  let numMeridians = 28;
  for (let m = 0; m < numMeridians; m++) {
    let kFloat = (m / numMeridians) * numAngles + random(-0.4, 0.4);
    let samplePt = evalBalloonSurface(b, kFloat, 0.62);
    let sampleLight = computePointLighting(b, samplePt, 0.62);

    // Concentrate dark graphite hatching in the form shadow and transition terminator
    let isShadowSide = sampleLight.amberLight < 0.38;
    let uStart = isShadowSide ? random(0.22, 0.45) : random(0.52, 0.72);
    let uEnd = random(0.92, 0.99);

    let hatchCol = isShadowSide
      ? lerpColor(darkCharcoal, midColor, random(0.15, 0.55))
      : lerpColor(sicklyAmberDark, midColor, random(0.3, 0.7));

    let mPts = [];
    let steps = 6;
    for (let s = 0; s <= steps; s++) {
      let u = lerp(uStart, uEnd, s / steps);
      // Slight spiral twist along meridian for authentic hand-shaded contour feel
      let kCurved = kFloat + (s - steps * 0.5) * 0.38;
      let pt = evalBalloonSurface(b, kCurved, u);
      let press = sin((s / steps) * 180) * 0.85 + 0.15;
      mPts.push([pt.x, pt.y, press]);
    }

    brush.set("fine_graphite", hatchCol, random(0.65, 1.15));
    brush.spline(mPts, 0.5);
  }

  // 3c. Faint matte latex sheen & sickly warm amber glow on the lowest curves
  for (let k = 0; k < numAngles; k += 2) {
    let uTest = random(0.18, 0.62);
    let pt = evalBalloonSurface(b, k, uTest);
    let light = computePointLighting(b, pt, uTest);

    if (light.amberLight > 0.34 || light.matteSheen > 0.22) {
      let sheenColor = light.amberLight > 0.34
        ? lerpColor(sicklyAmberMid, latexHighlightWarm, constrain(light.matteSheen * 1.2, 0.15, 0.9))
        : lerpColor(midColor, latexHighlightCool, constrain(light.matteSheen * 1.1, 0.2, 0.85));

      // Short cross-contour arc following the crown of the bulge
      let arcPts = [];
      for (let dk = -2; dk <= 2; dk++) {
        let pArc = evalBalloonSurface(b, k + dk * 1.1, uTest + dk * 0.015);
        arcPts.push([pArc.x, pArc.y, 1.0 - abs(dk) * 0.32]);
      }
      brush.set("latex_sheen", sheenColor, map(light.amberLight + light.matteSheen, 0.2, 1.4, 0.6, 1.35));
      brush.spline(arcPts, 0.55);

      // Delicate 2H pencil sheen grain over the highlight
      if (light.matteSheen > 0.32) {
        brush.set("2H", sheenColor, 0.65);
        brush.spline(arcPts, 0.55);
      }
    }
  }
}

function drawInterstitialCrevices() {
  // Accentuating the tight pinched seams and deep dark ceiling voids where balloons press together
  for (let i = 0; i < balloons.length; i++) {
    let b = balloons[i];
    let numAngles = b.contour.length;

    // Trace dark charcoal shadow along the compressed boundary segments
    let segSize = 8;
    for (let startK = 0; startK < numAngles; startK += segSize) {
      let midK = (startK + 4) % numAngles;
      let pt = evalBalloonSurface(b, midK, 0.98);
      let light = computePointLighting(b, pt, 0.98);

      let seamPts = [];
      for (let s = 0; s <= segSize; s++) {
        let c = b.contour[(startK + s) % numAngles];
        seamPts.push([c.x, c.y, sin((s / segSize) * 180) * 0.85 + 0.2]);
      }

      // Deep charcoal seam
      let seamCol = light.amberLight > 0.3 ? "#1c1518" : "#09080c";
      brush.set("soft_charcoal", seamCol, map(1.0 - light.amberLight, 0, 1, 0.55, 1.15));
      brush.spline(seamPts, 0.5);

      // Sharp graphite pinch crease right in the crack
      brush.set("fine_graphite", "#060508", 0.95);
      brush.spline(seamPts, 0.5);
    }
  }
}

function drawBalloonKnot(b) {
  let kx = b.knotX;
  let ky = b.knotY;

  // Skip knots that lie off-canvas
  if (kx < -20 || kx > 1220 || ky < -20 || ky > 1220) return;

  // Evaluate local lighting at the knot
  let kPt = { x: kx, y: ky, z: b.bellyZ * 0.98, nx: 0, ny: 0, nz: -1 };
  let light = computePointLighting(b, kPt, 0.12);
  let toLampAng = atan2(lampPos.y - ky, lampPos.x - kx);

  // 1. Dark recessed pucker collar where the stretched balloon skin gathers into the neck
  let puckerR = b.r * 0.085;
  brush.set("soft_charcoal", "#110e15", 0.72);
  brush.circle(kx, ky, puckerR * 0.9, 0.25);

  // 2. Radial tension wrinkles radiating outward from the tied neck
  let numWrinkles = 18;
  for (let w = 0; w < numWrinkles; w++) {
    let wAng = (w / numWrinkles) * 360 + random(-7, 7);
    let wLen = puckerR * random(1.15, 2.35);
    let rIn = puckerR * random(0.32, 0.55);
    let curveBend = random(-14, 14);

    let x0 = kx + cos(wAng) * rIn;
    let y0 = ky + sin(wAng) * rIn;
    let xMid = kx + cos(wAng + curveBend * 0.5) * ((rIn + wLen) * 0.5);
    let yMid = ky + sin(wAng + curveBend * 0.5) * ((rIn + wLen) * 0.5);
    let x1 = kx + cos(wAng + curveBend) * wLen;
    let y1 = ky + sin(wAng + curveBend) * wLen;

    // Dark wrinkle trough
    brush.set("fine_graphite", "#16131c", random(0.55, 0.95));
    brush.spline([[x0, y0, 0.9], [xMid, yMid, 0.65], [x1, y1, 0.1]], 0.5);

    // Subtle ridge highlight next to the wrinkle if facing the unseen lamp
    if (cos(wAng - toLampAng + 55) > 0.25 && light.amberLight > 0.2) {
      let hiCol = light.amberLight > 0.45 ? "#d89f52" : "#78646e";
      let offAng = wAng + 6;
      brush.set("2H", hiCol, 0.45);
      brush.line(
        kx + cos(offAng) * (rIn * 1.1),
        ky + sin(offAng) * (rIn * 1.1),
        kx + cos(offAng + curveBend * 0.6) * (wLen * 0.78),
        ky + sin(offAng + curveBend * 0.6) * (wLen * 0.78)
      );
    }
  }

  // 3. The flared rubber nozzle lip sticking out from one side of the knot
  let lipAng = b.knotOrient;
  let lipDist = puckerR * 0.95;
  let lx = kx + cos(lipAng) * lipDist;
  let ly = ky + sin(lipAng) * lipDist;
  let perpAng = lipAng + 90;
  let lipW = puckerR * 0.58;

  // Dark nozzle throat shadow
  brush.set("fine_graphite", "#09070c", 1.3);
  brush.spline([
    [kx + cos(lipAng - 25) * puckerR * 0.35, ky + sin(lipAng - 25) * puckerR * 0.35, 0.6],
    [lx + cos(perpAng) * lipW, ly + sin(perpAng) * lipW, 1.0],
    [lx + cos(lipAng) * (puckerR * 0.28), ly + sin(lipAng) * (puckerR * 0.28), 0.9],
    [lx - cos(perpAng) * lipW, ly - sin(perpAng) * lipW, 1.0],
    [kx + cos(lipAng + 25) * puckerR * 0.35, ky + sin(lipAng + 25) * puckerR * 0.35, 0.6]
  ], 0.55);

  // Rolled rubber rim on the nozzle lip catching warm amber or pale slate light
  let rimCol = light.amberLight > 0.25
    ? lerpColor(color("#9c6d3a"), color("#f0be6f"), constrain(light.amberLight, 0, 1))
    : "#6e6875";
  brush.set("fine_graphite", rimCol, 0.95);
  brush.spline([
    [lx + cos(perpAng) * lipW, ly + sin(perpAng) * lipW, 0.4],
    [lx + cos(lipAng) * (puckerR * 0.32), ly + sin(lipAng) * (puckerR * 0.32), 1.0],
    [lx - cos(perpAng) * lipW, ly - sin(perpAng) * lipW, 0.4]
  ], 0.6);

  // 4. The tight twisted knot torus itself
  let knotCoreCol = light.amberLight > 0.28 ? "#4a3228" : "#221c26";
  brush.set("fine_graphite", "#08060b", 1.5);
  brush.circle(kx, ky, puckerR * 0.48, 0.3);

  brush.set("fine_graphite", knotCoreCol, 1.25);
  brush.arc(kx, ky, puckerR * 0.38, toLampAng - 85, toLampAng + 85);

  // Crisp highlight on the lamp-facing twist of the knot
  let knotHiCol = light.amberLight > 0.22
    ? lerpColor(color("#b57e3d"), color("#fae09e"), constrain(light.amberLight * 1.1, 0, 1))
    : "#8d8696";
  brush.set("ribbon_pen", knotHiCol, 0.85);
  brush.arc(
    kx + cos(toLampAng) * 1.8,
    ky + sin(toLampAng) * 1.8,
    puckerR * 0.35,
    toLampAng - 62,
    toLampAng + 62
  );
}

function drawFallenStreamer() {
  // A twisted, crinkled crepe-paper streamer wedged high in an upper-left crevice,
  // draping across the pendulous bellies and dangling into the warm amber lamp light on the lower right.
  let anchors = [
    { x: 195, y: 155 }, // Tucked deep into an upper-left crevice
    { x: 265, y: 270 },
    { x: 375, y: 390 },
    { x: 485, y: 535 }, // Slack catenary belly
    { x: 635, y: 610 }, // Caught against a central hanging balloon lobe
    { x: 775, y: 665 },
    { x: 885, y: 785 }, // Dropping through the warm amber lamp zone
    { x: 955, y: 920 },
    { x: 1005, y: 1045 } // Torn dangling end
  ];

  // Interpolate smooth spine points
  let spine = [];
  let totalSamples = 210;
  for (let i = 0; i <= totalSamples; i++) {
    let t = (i / totalSamples) * (anchors.length - 1);
    let idx = min(floor(t), anchors.length - 2);
    let f = t - idx;

    let p0 = anchors[max(0, idx - 1)];
    let p1 = anchors[idx];
    let p2 = anchors[idx + 1];
    let p3 = anchors[min(anchors.length - 1, idx + 2)];

    // Catmull-Rom spline interpolation
    let f2 = f * f;
    let f3 = f2 * f;
    let x = 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * f + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * f2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * f3);
    let y = 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * f + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * y_f2(f2) + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * f3);

    // Subtle crepe flutter
    let flutter = (noise(i * 0.06, 99) - 0.5) * 8.0;
    spine.push({ x: x + flutter, y: y - flutter * 0.6, s: i / totalSamples });
  }

  // Compute tangents, normals, twist angle, and left/right edges
  let maxHalfW = 17.5;
  for (let i = 0; i < spine.length; i++) {
    let prev = spine[max(0, i - 1)];
    let next = spine[min(spine.length - 1, i + 1)];
    let tx = next.x - prev.x;
    let ty = next.y - prev.y;
    let tLen = sqrt(tx * tx + ty * ty) + 0.001;
    tx /= tLen;
    ty /= tLen;
    let nx = -ty;
    let ny = tx;

    // The streamer twists 3.5 times along its draped length
    let twistDeg = spine[i].s * 640 + 28 * sin(spine[i].s * 360);
    let twistProj = cos(twistDeg);

    // Taper width where tucked into the crevice at s=0
    let endTaper = constrain(map(spine[i].s, 0, 0.06, 0.15, 1.0), 0.15, 1.0);
    let halfW = (maxHalfW * twistProj) * endTaper;
    if (abs(halfW) < 1.6) halfW = (halfW >= 0 ? 1.6 : -1.6);

    spine[i].tx = tx;
    spine[i].ty = ty;
    spine[i].nx = nx;
    spine[i].ny = ny;
    spine[i].twistDeg = twistDeg;
    spine[i].halfW = halfW;
    spine[i].lx = spine[i].x + nx * halfW;
    spine[i].ly = spine[i].y + ny * halfW;
    spine[i].rx = spine[i].x - nx * halfW;
    spine[i].ry = spine[i].y - ny * halfW;
  }

  // 1. Soft cast shadow of the streamer onto the balloon bellies directly above/behind it
  for (let i = 4; i < spine.length - 6; i += 6) {
    let shPts = [];
    for (let k = 0; k <= 6; k++) {
      let sp = spine[min(spine.length - 1, i + k)];
      // Shadow shifts away from the lamp
      let dx = sp.x - lampPos.x;
      let dy = sp.y - lampPos.y;
      let d = sqrt(dx * dx + dy * dy) + 1;
      let shOff = map(sp.s, 0, 1, 5, 18);
      shPts.push([sp.x + (dx / d) * shOff, sp.y + (dy / d) * shOff, 0.75]);
    }
    brush.set("soft_charcoal", "#0b090f", 0.95);
    brush.spline(shPts, 0.5);
  }

  // 2. Render streamer body and fine transverse crepe-paper crinkles
  let darkPlumPaper = color("#241d29");
  let midMauvePaper = color("#594657");
  let warmAmberPaper = color("#d49848");
  let brightAmberEdge = color("#f7d283");

  for (let i = 0; i < spine.length - 1; i++) {
    let p = spine[i];
    let pNext = spine[i + 1];

    // Illumination of this paper facet based on distance to lamp and 3D twist normal
    let dLamp = dist(p.x, p.y, lampPos.x, lampPos.y);
    let lampProx = constrain(map(dLamp, 120, 950, 1.0, 0.08), 0.05, 1.0);
    let faceTilt = 0.5 + 0.5 * sin(p.twistDeg + 35);
    let litFactor = lampProx * (0.35 + 0.65 * faceTilt);

    // Crepe ridge modulation (characteristic tiny transverse pleats of crepe paper)
    let crinkle = sin(i * 52) * 0.14 + (noise(i * 0.45, 7) - 0.5) * 0.18;
    let totalLit = constrain(litFactor + crinkle, 0.05, 1.0);

    let paperCol;
    if (totalLit < 0.45) {
      paperCol = lerpColor(darkPlumPaper, midMauvePaper, map(totalLit, 0.05, 0.45, 0, 1));
    } else {
      paperCol = lerpColor(midMauvePaper, warmAmberPaper, map(totalLit, 0.45, 0.85, 0, 1));
      if (totalLit > 0.82) {
        paperCol = lerpColor(paperCol, brightAmberEdge, map(totalLit, 0.82, 1.0, 0, 0.85));
      }
    }

    // Transverse crepe strokes filling the ribbon width with opaque paper texture
    brush.set("fine_graphite", paperCol, 1.55);
    brush.line(p.lx, p.ly, p.rx, p.ry);

    // Secondary crisp crinkle shadow/highlight line every 2nd step
    if (i % 2 === 0) {
      let ridgeCol = crinkle > 0
        ? lerpColor(paperCol, brightAmberEdge, 0.42 * lampProx)
        : lerpColor(paperCol, color("#120e16"), 0.55);
      let midX = (p.lx + p.rx) * 0.5 + p.tx * 0.8;
      let midY = (p.ly + p.ry) * 0.5 + p.ty * 0.8;
      brush.set("ribbon_pen", ridgeCol, 0.65);
      brush.spline([[p.lx, p.ly, 0.5], [midX, midY, 0.95], [p.rx, p.ry, 0.5]], 0.4);
    }

    // Crisp paper edge thickness catching the warm lamp light on the lower/lamp-facing border
    let edgeColL = lampProx > 0.35 ? lerpColor(midMauvePaper, brightAmberEdge, lampProx * 0.9) : "#756b7d";
    let edgeColR = "#17131c";
    brush.set("ribbon_pen", edgeColL, 0.78);
    brush.line(p.lx, p.ly, pNext.lx, pNext.ly);
    brush.set("ribbon_pen", edgeColR, 0.72);
    brush.line(p.rx, p.ry, pNext.rx, pNext.ry);
  }

  // 3. Torn, jagged fibrous crepe paper end at the bottom of the streamer
  let tail = spine[spine.length - 1];
  for (let f = -1.0; f <= 1.0; f += 0.16) {
    let bx = tail.x + tail.nx * tail.halfW * f;
    let by = tail.y + tail.ny * tail.halfW * f;
    let tearLen = random(5, 18) * (1.0 - 0.4 * abs(f));
    let ex = bx + tail.tx * tearLen + random(-2, 2);
    let ey = by + tail.ty * tearLen + random(-2, 2);
    brush.set("fine_graphite", f > -0.2 ? "#e8b668" : "#6e5549", 0.75);
    brush.line(bx, by, ex, ey);
  }
}

function drawDanglingRibbons() {
  // Curling plastic party ribbons dangling down from the balloon knots as fine pen lines
  for (let i = 0; i < balloons.length; i++) {
    let b = balloons[i];
    if (!b.hasRibbon) continue;
    if (b.knotX < 20 || b.knotX > 1180 || b.knotY < 20 || b.knotY > 1180) continue;

    // Determine ribbon length & foreshortened drift direction
    let numSteps = b.ribbonLong ? floor(random(95, 145)) : floor(random(42, 82));
    // Slight perspective drift away from zenith + downward pull
    let driftAng = atan2(b.knotY - 480, b.knotX - 580) + random(-55, 55);
    let stepDist = b.ribbonLong ? random(2.1, 3.1) : random(1.4, 2.2);

    // Helical curl parameters
    let curlFreq = random(8.5, 14.5);
    let curlRadius = b.ribbonLong ? random(14, 28) : random(8, 17);
    let phase = random(360);
    lethandedness = random() < 0.5 ? 1 : -1;

    let rPts1 = []; // Edge 1 of the thin plastic ribbon
    let rPts2 = []; // Edge 2 of the thin plastic ribbon
    let rLit = [];  // Local illumination along the ribbon

    let curX = b.knotX;
    let curY = b.knotY;

    for (let s = 0; s <= numSteps; s++) {
      let t = s / numSteps;
      // Ramp up curl amplitude away from the knot
      let env = constrain(t * 3.5, 0, 1) * (1.0 - 0.15 * t);
      let theta = phase + handedness * s * curlFreq;

      // Advance drift spine with gentle low-frequency air current wave
      let airWave = (noise(b.id * 10 + t * 2.2, 42) - 0.5) * 55;
      curX += cos(driftAng + airWave) * stepDist;
      curY += sin(driftAng + airWave) * stepDist;

      // Foreshortened helical loop offset
      let loopX = cos(theta) * curlRadius * env;
      let loopY = sin(theta) * curlRadius * 0.62 * env;

      let px = curX + loopX;
      let py = curY + loopY;

      // Ribbon width varies between 0.4 px (razor edge-on) and 3.6 px (flat twist facing viewer)
      let ribbonTwist = sin(theta * 0.85 + 40);
      let halfW = (0.35 + 1.55 * abs(ribbonTwist)) * (0.75 + 0.45 * t);
      let normAng = theta + 90;

      rPts1.push({ x: px + cos(normAng) * halfW, y: py + sin(normAng) * halfW });
      rPts2.push({ x: px - cos(normAng) * halfW, y: py - sin(normAng) * halfW });

      // Calculate whether this loop segment catches a glint from the unseen warm amber lamp
      let dLamp = dist(px, py, lampPos.x, lampPos.y);
      let toLamp = atan2(lampPos.y - py, lampPos.x - px);
      let specAlign = pow(max(0, cos(normAng - toLamp)), 4.0);
      let lampGlint = constrain(map(dLamp, 140, 920, 1.0, 0.1), 0.05, 1.0) * (0.25 + 0.75 * specAlign);
      rLit.push({ glint: lampGlint, twist: abs(ribbonTwist), zDepth: b.zHang + t * 0.25 });
    }

    // Draw the ribbon in short curved segments so ink darkness and warm amber specular glints shift along the curls
    let chunk = 6;
    for (let s = 0; s < numSteps - 1; s += chunk) {
      let endS = min(numSteps, s + chunk);
      let midS = floor((s + endS) * 0.5);
      let info = rLit[midS];

      let seg1 = [];
      let seg2 = [];
      for (let k = s; k <= endS; k++) {
        let press = (k === 0 || k === numSteps) ? 0.4 : 0.95;
        seg1.push([rPts1[k].x, rPts1[k].y, press]);
        seg2.push([rPts2[k].x, rPts2[k].y, press]);
      }

      // Dark ink / graphite edge of the ribbon
      let darkInk = info.glint > 0.45 ? "#291e1a" : "#0b090f";
      brush.set("ribbon_pen", darkInk, 0.88);
      brush.spline(seg2, 0.5);

      // Opposite edge & face: either dark plum-charcoal or catching a sharp warm amber glint
      if (info.glint > 0.34) {
        let glintCol = lerpColor(color("#a87439"), color("#fce29f"), constrain((info.glint - 0.34) * 1.6, 0, 1));
        brush.set("ribbon_pen", glintCol, 0.92);
        brush.spline(seg1, 0.5);
      } else {
        let midRibbonCol = info.twist > 0.55 ? "#4a3e4d" : "#18151f";
        brush.set("ribbon_pen", midRibbonCol, 0.78);
        brush.spline(seg1, 0.5);
      }
    }
  }
}

