// Hyperreal Screen-Printed Motorcycle Helmet — Tight Three-Quarter View
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

const PALETTE = {
  paper: "#EFE8D8",       // Raw bone printmaking stock
  paperBright: "#FAF6EE", // Opaque bone-white highlight screen
  paperTone: "#E3DAC6",   // Subtle warm paper under-block
  slateLight: "#7B90A0",  // Screen 1: Light slate blue-grey
  slateDark: "#324759",   // Screen 2: Deep slate blue
