  orangeDark: "#B82300",  // Ink-trap overprint (orange + slate/black)
  black: "#171412"        // Screen 4: Warm carbon black
};

// Screen misregistration offsets (in pixels)
const REG = {
  bone:   { x: -5, y:  4 },
  slateL: { x: -7, y: -5 },
  slateD: { x:  6, y: -4 },
