};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(4279);
  noiseSeed(4279);

  // Required brush scaling for 1200x1200 canvas
  brush.scaleBrushes(3);

  // Custom screenprint squeegee / flat marker brush
  brush.add("screen_flat", {
    type: "marker",
    weight: 6,
    scatter: 0.06,
    opacity: 215,
    spacing: 0.25,
    pressure: [0.95, 1.0, 0.95],
    rotate: "natural",
    markerTip: false,
    noise: 0.15
  });

  // Custom coarse serigraph halftone spray brush
  brush.add("halftone_grit", {
    type: "spray",
    weight: 5.5,
    scatter: 2.6,
    opacity: 195,
    spacing: 0.35,
    pressure: [0.6, 1.15, 0.5],
    rotate: "random",
    noise: 0.8
  });

  // Custom fine grit stipple brush
  brush.add("fine_grit", {
    type: "spray",
    weight: 2.8,
    scatter: 3.4,
    opacity: 165,
    spacing: 0.45,
    pressure: [0.4, 1.0, 0.4],
    rotate: "random",
    noise: 1.0
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paper);
  brush.noField();

  // 1. Printmaking sheet background & registration marks
  drawPrintSheetAndMarks();

  // 2. Cast shadow plane on the ground
  drawCastShadow();

  // 3. Base helmet shell screens (Bone, Light Slate, Deep Slate, Fluorescent Orange)
  drawHelmetBaseScreens();

  // 4. Spray grit halftone transitions across shell dome & jaw
  drawShellHalftoneGradients();

  // 5. Multi-screen racing stripes & graphic blocks (Fluorescent Orange)
  drawOrangeRacingGraphics();

  // 6. Stickers & technical decals on the shell
  drawHelmetStickers();

  // 7. Smoked visor & hyperreal desert highway + telephone poles reflection
  drawSmokedVisorAndReflection();

  // 8. Mechanical hardware: Rubber eyeport gasket, pivot assembly, vents, neck roll
  drawMechanicalHardwareAndTrim();

  // 9. Hyperreal scuffs, asphalt rash, paint chips & misregistered highlights
  drawHyperrealScuffsAndWear();

  noLoop();
}

