function shiftPts(pts, dx, dy) {
  return pts.map(p => [p[0] + dx, p[1] + dy]);
}

function drawPolyLayer(pts, reg, washCol, washOp, hatchCfg, strokeCfg) {
  let shifted = shiftPts(pts, reg.x, reg.y);
  let poly = new brush.Polygon(shifted);

  if (washCol && washOp > 0) {
    poly.wash(washCol, washOp);
  }
  if (hatchCfg) {
    brush.hatchStyle(hatchCfg.brush || "screen_flat", hatchCfg.color || washCol, hatchCfg.weight || 0.7);
    poly.hatch(hatchCfg.dist || 7, hatchCfg.angle || 35, {
      rand: hatchCfg.rand !== undefined ? hatchCfg.rand : 0.02,
      continuous: hatchCfg.continuous || false,
      gradient: hatchCfg.gradient || 0
    });
    brush.noHatch();
  }
  if (strokeCfg) {
    poly.draw(strokeCfg.brush || "rotring", strokeCfg.color || PALETTE.black, strokeCfg.weight || 0.45);
  }
}

