// Visor aperture mathematical bounds (inside the rubber gasket, outside the pivot washer)
function visorTopY(x) {
  let t = constrain((x - 170) / (715 - 170), 0, 1);
  // Smooth arch peaking near x = 350
  return 442 - 22 * sin(t * 155) + 102 * pow(t, 2.15);
}

function visorBotY(x) {
  let t = constrain((x - 170) / (715 - 170), 0, 1);
  // Sweeping cheek curve dipping near x = 440, rising into pivot
  return 652 + 36 * sin(t * 145) - 34 * pow(t, 2.4);
}

function visorLeftX(y) {
  // Curved front profile of the bubble/shield on the left
  let ny = constrain((y - 438) / (664 - 438), 0, 1);
  return 198 - 28 * sin(ny * 180);
}

function inVisor(x, y) {
  if (y < 415 || y > 700) return false;
  let lx = visorLeftX(y);
  if (x < lx || x > 718) return false;
  if (y < visorTopY(x) || y > visorBotY(x)) return false;
  // Exclude circular pivot washer on the right temple (cx: 736, cy: 575, r: 54)
  let dx = x - 736;
  let dy = y - 575;
  if (dx * dx + dy * dy < 54 * 54) return false;
  return true;
}

