function drawShellHalftoneGradients() {
  // 4A. Transition 1: Light Slate -> Bare Bone Highlight across forehead & crown
  const browCurveA = [
    [225, 385], [310, 350], [435, 318], [575, 275], [695, 215], [765, 170]
