  sprayBetweenCurves(browCurveA, browCurveB, PALETTE.slateLight, REG.slateL, 180, 1.05, 0.25);

  // Fine graphic halftone hatch lines bridging the highlight edge
  brush.set("rotring", PALETTE.slateLight, 0.35);
  for (let i = 0; i < 68; i++) {
    let t = i / 67;
    let pA = samplePolyline(browCurveA, t);
