    let reach = random(0.25, 0.85);
    let mx = lerp(pA[0], pB[0], reach) + REG.slateL.x;
    let my = lerp(pA[1], pB[1], reach) + REG.slateL.y;
    brush.line(pA[0] + REG.slateL.x, pA[1] + REG.slateL.y, mx, my);
  }

  // 4B. Transition 2: Deep Slate -> Light Slate across mid-dome and cheek
  const midCurveA = [
    [545, 345], [660, 280], [775, 215], [710, 468], [762, 560],
    [735, 668], [645, 760], [525, 830], [385, 868]
  ];
  const midCurveB = [
    [435, 315], [565, 250], [705, 185], [595, 415], [685, 515],
    [645, 645], [535, 725], [415, 765], [275, 795]
  ];
  sprayBetweenCurves(midCurveA, midCurveB, PALETTE.slateDark, REG.slateD, 240, 1.25, 0.3);

  // 4C. Transition 3: Warm Black -> Deep Slate coarse shadow grit along back & jaw
  const darkCurveA = [
    [880, 245], [945, 345], [988, 485], [985, 635], [942, 765],
    [855, 865], [725, 928], [555, 958], [385, 948]
  ];
  const darkCurveB = [
    [765, 225], [835, 325], [885, 465], [885, 610], [835, 725],
    [745, 815], [615, 875], [465, 895], [315, 885]
  ];
  sprayBetweenCurves(darkCurveA, darkCurveB, PALETTE.black, REG.black, 280, 1.45, 0.35);

  // Extra coarse serigraph halftone cross-ticks in deep shadow transition
  brush.set("rotring", PALETTE.black, 0.45);
  for (let i = 0; i < 95; i++) {
    let t = i / 94;
    let pA = samplePolyline(darkCurveA, t);
    let pB = samplePolyline(darkCurveB, t);
    let amt = pow(random(0, 1), 1.5);
    let x = lerp(pA[0], pB[0], amt);
    let y = lerp(pA[1], pB[1], amt);
    let len = map(amt, 0, 1, 22, 5);
    brush.line(x - len, y + len * 0.4, x + len, y - len * 0.4);
