function samplePolyline(pts, t) {
  let n = pts.length - 1;
  let idx = constrain(floor(t * n), 0, n - 1);
  let f = (t * n) - idx;
  return [
    lerp(pts[idx][0], pts[idx + 1][0], f),
    lerp(pts[idx][1], pts[idx + 1][1], f)
  ];
}

function sprayBetweenCurves(curveDense, curveSparse, col, reg, steps, maxW, minW) {
  for (let i = 0; i < steps; i++) {
    let t = random(0, 1);
    // Bias distribution toward dense shadow edge (u near 0), fading to bare paper near u = 1
    let u = pow(random(0, 1), 1.65);
    let pA = samplePolyline(curveDense, t);
    let pB = samplePolyline(curveSparse, t);
    let x = lerp(pA[0], pB[0], u) + reg.x + random(-8, 8);
    let y = lerp(pA[1], pB[1], u) + reg.y + random(-8, 8);
    let w = lerp(maxW, minW, u);
    let bName = u < 0.55 ? "halftone_grit" : "fine_grit";
    brush.set(bName, col, w);
    let strokeLen = lerp(24, 6, u);
    let ang = atan2(pB[1] - pA[1], pB[0] - pA[0]) + 90 + random(-20, 20);
    brush.line(
      x - cos(ang) * strokeLen * 0.5,
      y - sin(ang) * strokeLen * 0.5,
      x + cos(ang) * strokeLen * 0.5,
      y + sin(ang) * strokeLen * 0.5
    );
  }
}

