// ============================================================================
// 7. SMOKED VISOR & HYPERREAL DESERT HIGHWAY + TELEPHONE POLES REFLECTION
// ============================================================================

function drawSmokedVisorAndReflection() {
  // Build exact polygon of the visor aperture
  let visorAperturePts = [];
  for (let x = 185; x <= 695; x += 12) {
    visorAperturePts.push([x, visorTopY(x)]);
  }
  // Curve around the left side of the pivot washer (cx: 736, cy: 575, r: 54)
  for (let a = 218; a >= 142; a -= 8) {
    visorAperturePts.push([736 + cos(a) * 54, 575 + sin(a) * 54]);
  }
  for (let x = 695; x >= 185; x -= 12) {
    visorAperturePts.push([x, visorBotY(x)]);
  }
  // Left nose curve of visor
  for (let y = 648; y >= 445; y -= 12) {
    visorAperturePts.push([visorLeftX(y), y]);
  }

  // Horizon function inside visor (bows upward in center due to spherical shield curvature)
  function horizonY(x) {
    let t = constrain((x - 170) / (710 - 170), 0, 1);
    return 572 - 24 * sin(t * 180) + 6 * t;
  }

  // --------------------------------------------------------------------------
  // 7A. SMOKED VISOR SKY GRADIENT LAYERS (Top to Horizon)
  // --------------------------------------------------------------------------
  // Base smoked slate-blue wash across entire visor
  drawPolyLayer(visorAperturePts, { x: 0, y: 0 }, PALETTE.slateDark, 235, null, null);

  // Upper sky deep smoked Warm Black band (top 40% of visor)
  let upperSkyPts = [];
  for (let x = 180; x <= 695; x += 14) {
    upperSkyPts.push([x, visorTopY(x)]);
  }
  for (let x = 695; x >= 180; x -= 14) {
    upperSkyPts.push([x, horizonY(x) - 52]);
  }
  drawPolyLayer(upperSkyPts, REG.black, PALETTE.black, 240, {
    brush: "screen_flat", color: PALETTE.black, weight: 0.75, dist: 6, angle: -8
  }, null);

  // Mid-sky Light Slate band (above the sunset glow)
  let midSkyPts = [];
  for (let x = 172; x <= 690; x += 14) {
    midSkyPts.push([x, horizonY(x) - 46]);
  }
  for (let x = 690; x >= 172; x -= 14) {
    midSkyPts.push([x, horizonY(x) - 18]);
  }
  drawPolyLayer(midSkyPts, REG.slateL, PALETTE.slateLight, 225, null, null);

  // Bright Bone horizon glow strip right above the desert mesas
  let boneGlowPts = [];
  for (let x = 172; x <= 685; x += 14) {
    boneGlowPts.push([x, horizonY(x) - 24]);
  }
  for (let x = 685; x >= 172; x -= 14) {
    boneGlowPts.push([x, horizonY(x) - 4]);
  }
  drawPolyLayer(boneGlowPts, REG.bone, PALETTE.paperBright, 245, null, null);

  // Blazing Fluorescent Orange sunset horizon band (misregistered!)
  let orangeHorizonPts = [];
  for (let x = 172; x <= 685; x += 14) {
    orangeHorizonPts.push([x, horizonY(x) - 14]);
  }
  for (let x = 685; x >= 172; x -= 14) {
    orangeHorizonPts.push([x, horizonY(x) + 8]);
  }
  drawPolyLayer(orangeHorizonPts, { x: 5, y: 3 }, PALETTE.orange, 242, null, null);

  // Halftone spray grit bridging the smoked black upper sky into the slate & orange horizon
  for (let i = 0; i < 220; i++) {
    let rx = random(175, 685);
    let hy = horizonY(rx);
    let ry = hy - random(18, 72);
    if (inVisor(rx, ry)) {
      let col = ry < hy - 42 ? PALETTE.black : (ry < hy - 26 ? PALETTE.slateLight : PALETTE.orange);
      brush.set("fine_grit", col, random(0.4, 0.95));
      brush.line(rx - 10, ry, rx + 10, ry);
    }
  }

  // --------------------------------------------------------------------------
  // 7B. DESERT MESAS / BUTTES ALONG THE HORIZON
  // --------------------------------------------------------------------------
  // Mesa 1 (Left horizon range)
  let mesa1 = [
    [176, horizonY(176) + 2],
    [186, horizonY(186) - 22], [202, horizonY(202) - 24], [208, horizonY(208) - 34],
    [238, horizonY(238) - 35], [246, horizonY(246) - 18], [262, horizonY(262) - 18],
    [275, horizonY(275) + 2]
  ];
  // Mesa 2 (Iconic steep desert butte just left of highway vanishing point)
  let mesa2 = [
    [286, horizonY(286) + 2],
    [298, horizonY(298) - 16], [304, horizonY(304) - 42], [326, horizonY(326) - 43],
    [332, horizonY(332) - 22], [344, horizonY(344) - 22], [352, horizonY(352) + 2]
  ];
  // Mesa 3 (Long low tableland right of vanishing point)
  let mesa3 = [
    [392, horizonY(392) + 2],
    [405, horizonY(405) - 18], [462, horizonY(462) - 20], [472, horizonY(472) - 28],
    [518, horizonY(518) - 27], [534, horizonY(534) - 12], [568, horizonY(568) + 2]
  ];

  // Misregistered fluorescent orange rim-light behind mesas
  drawPolyLayer(mesa1, { x: 3, y: -3 }, PALETTE.orange, 235, null, null);
  drawPolyLayer(mesa2, { x: 3, y: -3 }, PALETTE.orange, 235, null, null);
  drawPolyLayer(mesa3, { x: 3, y: -3 }, PALETTE.orange, 235, null, null);

  // Warm black silhouettes of the mesas
  drawPolyLayer(mesa1, REG.black, PALETTE.black, 248, null, null);
  drawPolyLayer(mesa2, REG.black, PALETTE.black, 248, null, null);
  drawPolyLayer(mesa3, REG.black, PALETTE.black, 248, null, null);

  // --------------------------------------------------------------------------
  // 7C. DESERT FLOOR & PERSPECTIVE HIGHWAY
  // --------------------------------------------------------------------------
  const vpX = 362;
  const vpY = horizonY(vpX); // ~ 549

  // Desert flats below horizon (Light Slate & Deep Slate with horizontal scrub texture)
  let desertFlatsPts = [];
  for (let x = 175; x <= 685; x += 14) {
    desertFlatsPts.push([x, horizonY(x) + 1]);
  }
  for (let x = 685; x >= 185; x -= 14) {
    desertFlatsPts.push([x, visorBotY(x)]);
  }
  drawPolyLayer(desertFlatsPts, { x: 0, y: 0 }, PALETTE.slateDark, 242, {
    brush: "screen_flat", color: PALETTE.slateLight, weight: 0.55, dist: 7, angle: 4
  }, null);

  // Desert scrub & sand shadow streaks radiating from horizon
  for (let i = 0; i < 140; i++) {
    let rx = random(180, 680);
    let hy = horizonY(rx);
    let ry = random(hy + 4, visorBotY(rx) - 4);
    if (inVisor(rx, ry)) {
      let col = random() < 0.45 ? PALETTE.black : (random() < 0.7 ? PALETTE.slateLight : PALETTE.orange);
      brush.set("rotring", col, random(0.25, 0.55));
      let len = map(ry, hy, 685, 4, 26);
      brush.line(rx - len * 0.5, ry, rx + len * 0.5, ry + random(-1.5, 1.5));
    }
  }

  // Highway Asphalt Trapezoid (sweeping from vanishing point to lower visor rim)
  let roadPts = [
    [vpX - 3, vpY],
    [vpX + 4, vpY],
    [455, 608],
    [572, 680],
    [440, 686],
    [305, 678],
    [208, 658],
    [288, 600]
  ];
  drawPolyLayer(roadPts, REG.black, PALETTE.black, 248, {
    brush: "screen_flat", color: PALETTE.black, weight: 0.7, dist: 5, angle: 18
  }, null);

  // Asphalt reflection sheen streaks inside highway
  brush.set("rotring", PALETTE.slateDark, 0.4);
  for (let i = 0; i < 36; i++) {
    let u = random(0.12, 0.96);
    let spread = random(-0.42, 0.42);
    let x1 = vpX + spread * u * 185;
    let y1 = lerp(vpY, 680, u);
    let x2 = vpX + spread * (u + 0.08) * 185;
    let y2 = lerp(vpY, 680, min(1, u + 0.08));
    if (inVisor(x1, y1) && inVisor(x2, y2)) {
      brush.line(x1, y1, x2, y2);
    }
  }

  // Highway Shoulder Lines (Bone White, perspective-tapered)
  const leftShoulder = [[vpX - 3, vpY + 2], [292, 600], [212, 656]];
  const rightShoulder = [[vpX + 4, vpY + 2], [450, 608], [565, 678]];

  // Misregistered slate-light shadow under shoulder lines
  brush.set("rotring", PALETTE.slateLight, 0.65);
  brush.spline(shiftPts(leftShoulder, -3, 2), 0.3);
  brush.spline(shiftPts(rightShoulder, -3, 2), 0.3);

  // Crisp Bone-White shoulder lines
  brush.set("rotring", PALETTE.paperBright, 0.65);
  brush.spline(leftShoulder, 0.3);
  brush.spline(rightShoulder, 0.3);

  // Highway Dashed Center Line (Fluorescent Orange + Bone paper under-sliver)
  const dashIntervals = [
    [0.05, 0.09],
    [0.13, 0.19],
    [0.24, 0.33],
    [0.40, 0.52],
    [0.60, 0.76],
    [0.84, 0.99]
  ];
  for (let d of dashIntervals) {
    let t1 = d[0], t2 = d[1];
    // Slight curve along the convex shield
    let x1 = lerp(vpX, 384, t1) - 6 * sin(t1 * 180);
    let y1 = lerp(vpY, 682, t1);
    let x2 = lerp(vpX, 384, t2) - 6 * sin(t2 * 180);
    let y2 = lerp(vpY, 682, t2);
    let w1 = lerp(0.6, 5.5, t1);
    let w2 = lerp(0.6, 5.5, t2);

    let dashPoly = [
      [x1 - w1, y1], [x1 + w1, y1],
      [x2 + w2, y2], [x2 - w2, y2]
    ];
    // Bone paper knock-out under dash
    drawPolyLayer(dashPoly, { x: -2.5, y: -1.5 }, PALETTE.paperBright, 248, null, null);
    // Fluorescent orange screen dash
    drawPolyLayer(dashPoly, { x: 1.5, y: 1.0 }, PALETTE.orange, 250, null, {
      brush: "rotring", color: PALETTE.orange, weight: 0.35
    });
  }

  // --------------------------------------------------------------------------
  // 7D. PERSPECTIVE TELEPHONE POLES & CATENARY WIRES
  // Marching along the right side of the desert highway into the vanishing point
  // --------------------------------------------------------------------------
  const poleParams = [0.05, 0.11, 0.20, 0.33, 0.51, 0.76, 0.98];
  let crossbarTips = []; // Store insulator positions for catenary wire stringing

  for (let idx = 0; idx < poleParams.length; idx++) {
    let p = poleParams[idx];
    // Ground base of pole along right side of highway
    let bx = lerp(vpX + 9, 672, p);
    let by = lerp(vpY + 1, 636, p);

    // Top of pole reaching up into the smoked sky (curved slightly by visor dome)
    let poleH = lerp(14, 168, pow(p, 0.88));
    let curveLean = lerp(1, 14, p); // Visor spherical warp leans top slightly left
    let tx = bx - curveLean;
    let ty = by - poleH;

    // Clamp top inside visor
    let minTopY = visorTopY(tx) + 4;
    let clampedTy = max(ty, minTopY);

    let wBase = lerp(0.25, 1.45, p);

    // 1. Misregistered Fluorescent Orange sunset highlight along left edge of pole
    brush.set("rotring", PALETTE.orange, wBase * 0.85);
    brush.line(bx - 2.2, by, tx - 2.2, clampedTy);

    // 2. Warm Black main wooden pole shaft
    brush.set("rotring", PALETTE.black, wBase);
    brush.line(bx, by, tx, clampedTy);
    if (p > 0.3) {
      brush.line(bx + 1.4, by, tx + 1.0, clampedTy);
    }

    // Crossbar 1 (Upper crossbar)
    let cb1Y = ty + poleH * 0.11;
    let cb1X = lerp(tx, bx, 0.11);
    let halfSpan1 = lerp(3.5, 34, p);
    let tiltY1 = halfSpan1 * 0.16; // Perspective tilt of crossbar

    let c1Left = [cb1X - halfSpan1, cb1Y + tiltY1];
    let c1Right = [cb1X + halfSpan1, cb1Y - tiltY1];

    if (inVisor(cb1X, cb1Y)) {
      // Orange highlight on top of crossbar
      brush.set("rotring", PALETTE.orange, wBase * 0.65);
      brush.line(c1Left[0], c1Left[1] - 1.6, c1Right[0], c1Right[1] - 1.6);

      // Black crossbar
      brush.set("rotring", PALETTE.black, wBase * 0.85);
      brush.line(c1Left[0], c1Left[1], c1Right[0], c1Right[1]);

      // Diagonal V-braces on closer poles
      if (p > 0.22) {
        let braceBaseX = lerp(tx, bx, 0.21);
        let braceBaseY = ty + poleH * 0.21;
        brush.set("rotring", PALETTE.black, wBase * 0.45);
        brush.line(braceBaseX, braceBaseY, cb1X - halfSpan1 * 0.48, cb1Y + tiltY1 * 0.48);
        brush.line(braceBaseX, braceBaseY, cb1X + halfSpan1 * 0.48, cb1Y - tiltY1 * 0.48);
      }

      // Insulator pins on Crossbar 1 (4 pins across)
      let pinH = lerp(1.2, 5.5, p);
      let pins = [];
      for (let k = 0; k < 4; k++) {
        let f = map(k, 0, 3, -0.88, 0.88);
        let px = cb1X + f * halfSpan1;
        let py = cb1Y - f * tiltY1;
        if (inVisor(px, py - pinH)) {
          brush.set("rotring", PALETTE.black, wBase * 0.55);
          brush.line(px, py, px, py - pinH);
          // Tiny glass insulator glint
          if (p > 0.25) {
            brush.set("rotring", PALETTE.paperBright, wBase * 0.45);
            brush.line(px - 0.8, py - pinH, px + 0.8, py - pinH);
          }
        }
        pins.push([px, py - pinH]);
      }
      crossbarTips.push({ p: p, pins: pins });
    }

    // Crossbar 2 (Lower crossbar on mid/foreground poles)
    if (p > 0.16) {
      let cb2Y = ty + poleH * 0.23;
      let cb2X = lerp(tx, bx, 0.23);
      let halfSpan2 = lerp(2.5, 26, p);
      let tiltY2 = halfSpan2 * 0.16;
      if (inVisor(cb2X, cb2Y)) {
        brush.set("rotring", PALETTE.orange, wBase * 0.55);
        brush.line(cb2X - halfSpan2, cb2Y + tiltY2 - 1.4, cb2X + halfSpan2, cb2Y - tiltY2 - 1.4);
        brush.set("rotring", PALETTE.black, wBase * 0.75);
        brush.line(cb2X - halfSpan2, cb2Y + tiltY2, cb2X + halfSpan2, cb2Y - tiltY2);
      }
    }
  }

  // Stringing Catenary Overhead Wires between poles
  for (let wIdx = 0; wIdx < 4; wIdx++) {
    for (let i = 0; i < crossbarTips.length - 1; i++) {
      let pA = crossbarTips[i].pins[wIdx];
      let pB = crossbarTips[i + 1].pins[wIdx];
      let sag = lerp(1.5, 14, crossbarTips[i + 1].p);

      // Build catenary curve points
      let wirePts = [];
      for (let s = 0; s <= 8; s++) {
        let u = s / 8;
        let wx = lerp(pA[0], pB[0], u);
        let wy = lerp(pA[1], pB[1], u) + sin(u * 180) * sag;
        if (inVisor(wx, wy)) {
          wirePts.push([wx, wy]);
        }
      }

      if (wirePts.length >= 2) {
        // Sunset wire glint (Fluorescent Orange / Bone) on select spans
        if ((i + wIdx) % 2 === 0) {
          brush.set("rotring", i < 3 ? PALETTE.orange : PALETTE.paperBright, 0.28);
          brush.spline(shiftPts(wirePts, 0, -1.2), 0.4);
        }
        // Crisp black wire
        brush.set("rotring", PALETTE.black, lerp(0.22, 0.42, crossbarTips[i].p));
        brush.spline(wirePts, 0.4);
      }
    }
  }

  // --------------------------------------------------------------------------
  // 7E. VISOR POLYCARBONATE SURFACE GLARE BANDS & SHIELD OPTICS
  // Overlaid across the upper brow of the visor to sell the curved smoked glass
  // --------------------------------------------------------------------------
  let glareBand1 = [
    [205, 456], [285, 440], [395, 438], [505, 456],
    [492, 476], [388, 458], [282, 460], [198, 478]
  ];
