function drawScuffCluster(cx, cy, spanW, spanH, angleDeg, count) {
  let ca = cos(angleDeg);
  let sa = sin(angleDeg);

  // 1. Irregular jagged paint-chip islands exposing raw bone fiberglass underneath
  for (let i = 0; i < 6; i++) {
    let ox = random(-spanW * 0.35, spanW * 0.35);
    let oy = random(-spanH * 0.35, spanH * 0.35);
    let sx = cx + ox * ca - oy * sa;
    let sy = cy + ox * sa + oy * ca;
    let len = random(18, 48);
    let wid = random(3.5, 8.5);

    let chipPts = [
      [sx - len * 0.5 * ca, sy - len * 0.5 * sa],
      [sx - wid * sa, sy + wid * ca],
      [sx + len * 0.5 * ca, sy + len * 0.5 * sa],
      [sx + wid * 0.7 * sa, sy - wid * 0.7 * ca]
    ];
    // Slate primer edge halo
    drawPolyLayer(chipPts, { x: -2, y: -2 }, PALETTE.slateLight, 230, null, null);
    // Bright bone fiberglass core
    drawPolyLayer(chipPts, { x: 0, y: 0 }, PALETTE.paperBright, 250, null, {
      brush: "rotring", color: PALETTE.black, weight: 0.3
    });
  }

  // 2. Directional high-friction parallel abrasion scratches (Bone, Slate, Black rubber transfer)
  for (let i = 0; i < count; i++) {
    let u = random(-0.5, 0.5) * spanW;
    let v = random(-0.5, 0.5) * spanH;
    let x1 = cx + u * ca - v * sa;
    let y1 = cy + u * sa + v * ca;
    let scLen = random(14, 58);
    let jitterAng = angleDeg + random(-5, 5);
    let x2 = x1 + cos(jitterAng) * scLen;
    let y2 = y1 + sin(jitterAng) * scLen;

    // Alternating bone scratch gouges and black rubber transfer smears
    if (i % 2 === 0) {
      brush.set("rotring", PALETTE.paperBright, random(0.35, 0.75));
      brush.line(x1, y1, x2, y2);
    } else {
      brush.set(i % 4 === 1 ? "charcoal" : "rotring", PALETTE.black, random(0.35, 0.7));
      brush.line(x1, y1, x2, y2);
    }
  }
}

// Hyperreal Thermal Imaging: Open Industrial Dryer & Tumbling Towels
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

const THERMAL_STOPS = [
  { t: 0.00, r: 5,   g: 4,   b: 14  }, // #05040e Abyssal Indigo-Black
  { t: 0.08, r: 11,  g: 8,   b: 33  }, // #0b0821 Deepest Indigo
  { t: 0.17, r: 24,  g: 15,  b: 61  }, // #180f3d Cold Steel Indigo
  { t: 0.27, r: 46,  g: 17,  b: 86  }, // #2e1156 Dark Thermal Violet
  { t: 0.37, r: 79,  g: 19,  b: 104 }, // #4f1368 Rich Violet
  { t: 0.47, r: 126, g: 20,  b: 102 }, // #7e1466 Deep Magenta-Plum
  { t: 0.57, r: 181, g: 23,  b: 87  }, // #b51757 Vibrant Magenta
  { t: 0.67, r: 224, g: 35,  b: 56  }, // #e02338 Crimson Scarlet
  { t: 0.77, r: 246, g: 79,  b: 24  }, // #f64f18 Blazing Red-Orange
  { t: 0.85, r: 255, g: 138, b: 8   }, // #ff8a08 Luminous Orange-Amber
  { t: 0.92, r: 255, g: 206, b: 38  }, // #ffce26 Incandescent Gold-Yellow
  { t: 0.97, r: 255, g: 241, b: 138 }, // #fff18a Brilliant Pale Yellow
  { t: 1.00, r: 255, g: 253, b: 242 }  // #fffdf2 Near-White Thermal Core
];

function thermalRGB(t) {
  let c = constrain(t, 0, 1);
  for (let i = 0; i < THERMAL_STOPS.length - 1; i++) {
    let a = THERMAL_STOPS[i];
    let b = THERMAL_STOPS[i + 1];
    if (c >= a.t && c <= b.t) {
      let f = (c - a.t) / (b.t - a.t);
      f = f * f * (3 - 2 * f);
      return [
        Math.round(lerp(a.r, b.r, f)),
        Math.round(lerp(a.g, b.g, f)),
        Math.round(lerp(a.b, b.b, f))
      ];
    }
  }
  let last = THERMAL_STOPS[THERMAL_STOPS.length - 1];
  return [last.r, last.g, last.b];
}

function thermalHex(t) {
  let [r, g, b] = thermalRGB(t);
  return (
    "#" +
    r.toString(16).padStart(2, "0") +
    g.toString(16).padStart(2, "0") +
    b.toString(16).padStart(2, "0")
  );
}

// Geometry helpers
function evalBezier(p0, p1, p2, p3, u) {
  let it = 1 - u;
  let b0 = it * it * it;
  let b1 = 3 * it * it * u;
  let b2 = 3 * it * u * u;
  let b3 = u * u * u;
  return [
    b0 * p0[0] + b1 * p1[0] + b2 * p2[0] + b3 * p3[0],
    b0 * p0[1] + b1 * p1[1] + b2 * p2[1] + b3 * p3[1]
  ];
}

function sampleSplinePts(ctrlPts, steps) {
  let out = [];
  if (ctrlPts.length === 4) {
    for (let i = 0; i <= steps; i++) {
      out.push(evalBezier(ctrlPts[0], ctrlPts[1], ctrlPts[2], ctrlPts[3], i / steps));
    }
    return out;
  }
  for (let i = 0; i <= steps; i++) {
    let u = (i / steps) * (ctrlPts.length - 1);
    let idx = Math.min( Math.floor(u), ctrlPts.length - 2 );
    let f = u - idx;
    let p0 = ctrlPts[Math.max(0, idx - 1)];
    let p1 = ctrlPts[idx];
    let p2 = ctrlPts[idx + 1];
    let p3 = ctrlPts[Math.min(ctrlPts.length - 1, idx + 2)];
    let f2 = f * f;
    let f3 = f2 * f;
    let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * f + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3);
    let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * f + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3);
    out.push([x, y]);
  }
  return out;
}

// Safe p5.brush wrappers
function washPoly(pts, hexCol, alphaVal = 230, curvature = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(hexCol, alphaVal);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function washRect(x, y, w, h, hexCol, alphaVal = 240) {
  washPoly([[x, y], [x + w, y], [x + w, y + h], [x, y + h]], hexCol, alphaVal, 0);
}

function strokePoly(pts, brushName, hexCol, weight = 1, closed = true, curvature = 0.1) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noFill();
  brush.noHatch();
  brush.set(brushName, hexCol, weight);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

function strokeCurve(pts, brushName, hexCol, weight = 1, curvature = 0.5) {
  if (!pts || pts.length < 2) return;
  brush.noWash();
  brush.noFill();
  brush.noHatch();
  brush.set(brushName, hexCol, weight);
  if (pts.length === 2) {
    brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
  } else {
    brush.spline(pts, curvature);
  }
}

