    scatter: 0.38,
    sharpness: 0.62,
    grain: 0.85,
    opacity: 110,
    spacing: 0.18,
    pressure: [0.3, 1.35, 0.3],
    noise: 0.85
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(thermalHex(0.01));

  // 1. Cold Laundromat Architecture & Adjoining Dryer Units
  drawLaundromatBackground();

  // 2. Tiled Floor with Radiant Infrared Heat Reflection Pool
  drawThermalFloor();

  // 3. Main Industrial Dryer Cabinet, Control Fascia & Lower Exhaust Vent
  drawDryerCabinet();

  // 4. Deep Cylindrical Drum Interior: Thermal Core, Baffles & 700+ Perforations
  drawPerforatedDrumCore();

  // 5. Outer Drum Gasket & Cold-to-Hot Metal Bezel Ring
  drawDrumBezel();

  // 6. Swung-Open Industrial Glass/Steel Door (Left Side with IR Reflection)
  drawOpenDryerDoor();

  // 7. Tumbling Cascade of Hot Terry-Cloth Towels (Core to Floor)
  drawTumblingTowels();

  // 8. Convective Heat Plume, Stray Hot Lint & Radiant Halo
  drawAtmosphericHeatDetails();

  // 9. Clinical Thermal Camera HUD: Corner Scale Bar & Crosshair Overlay
  drawThermalHUD();

  noLoop();
}

// ============================================================================
// 1. LAUNDROMAT BACKGROUND & ADJOINING UNITS
// ============================================================================
function drawLaundromatBackground() {
  // Base cold wall & recesses
  washRect(0, 0, 1200, 900, thermalHex(0.02), 255);

  // Upper bulkhead with warm exhaust pipe signature behind wall
  washRect(0, 0, 1200, 62, thermalHex(0.05), 240);
  for (let i = 0; i < 16; i++) {
    let y = map(i, 0, 15, 8, 56);
    let t = 0.08 + 0.14 * sin(map(i, 0, 15, 0, 180));
    strokeCurve([[80, y], [450, y - 6], [820, y - 2], [1160, y + 4]], "thermalBloom", thermalHex(t), 1.4);
  }

  // Left adjoining dryer edge (x: 0..148)
  washRect(0, 58, 148, 840, thermalHex(0.04), 250);
  // Subtle ambient heat on left unit's right flank from the open door
  for (let i = 0; i < 14; i++) {
    let x = map(i, 0, 13, 40, 145);
    let t = map(i, 0, 13, 0.03, 0.16);
    strokeCurve([[x, 180], [x, 480], [x, 780]], "thermalBloom", thermalHex(t), 1.1);
  }

  // Right adjoining dryer unit (x: 968..1200)
  washRect(968, 58, 232, 840, thermalHex(0.05), 250);
  washRect(972, 62, 228, 112, thermalHex(0.08), 235);

  // Side glow on the neighboring dryer's left panel from our hot drum & towels
  for (let i = 0; i < 22; i++) {
    let x = map(i, 0, 21, 972, 1170);
    let falloff = pow(1 - i / 21, 1.8);
    let tMid = 0.05 + 0.28 * falloff;
    let tBot = 0.05 + 0.36 * falloff;
    strokeCurve([[x, 260], [x, 520], [x, 700]], "thermalBloom", thermalHex(tMid), 1.2);
    strokeCurve([[x, 680], [x, 800], [x, 895]], "thermalBloom", thermalHex(tBot), 1.3);
  }

  // Neighboring dryer's closed circular door bezel peeking in at right edge (cx = 1275, cy = 478)
  let nbPts = [];
  for (let a = 115; a <= 245; a += 5) {
    nbPts.push([1275 + 285 * cos(a), 478 + 285 * sin(a)]);
  }
  strokeCurve(nbPts, "heavyMarker", thermalHex(0.19), 1.1);
  let nbPtsInner = [];
  for (let a = 118; a <= 242; a += 5) {
    nbPtsInner.push([1275 + 252 * cos(a), 478 + 252 * sin(a)]);
  }
  strokeCurve(nbPtsInner, "crispMarker", thermalHex(0.28), 0.9);
}

// ============================================================================
// 2. TILED FLOOR & RADIANT INFRARED REFLECTION POOL
// ============================================================================
function drawThermalFloor() {
  // Base cold floor slab
  washRect(0, 888, 1200, 312, thermalHex(0.03), 255);

  // Concentric radiant heat pool on the floor directly beneath and in front of the spilled towels
  let poolCx = 585;
  let poolCy = 985;
  for (let r = 460; r >= 30; r -= 14) {
    let norm = 1 - r / 460;
    let t = 0.04 + 0.64 * pow(norm, 2.1);
    let rx = r * 1.18;
    let ry = r * 0.42;
    let ell = [];
    for (let a = 0; a < 360; a += 12) {
      let px = poolCx + rx * cos(a);
      let py = poolCy + ry * sin(a);
      py = max(890, py);
      ell.push([px, py]);
    }
    washPoly(ell, thermalHex(t), 45, 0.2);
  }

  // Vertical infrared specular streaks on glossy floor tiles reflecting the drum core
  for (let x = 250; x <= 930; x += 14) {
    let dx = abs(x - 585) / 350;
    if (dx < 1) {
      let coreFactor = pow(1 - dx, 2.2);
      let yStart = 920 + random(-10, 15);
      let yEnd = 1185;
      for (let s = 0; s < 7; s++) {
        let f1 = s / 7;
        let f2 = (s + 1) / 7;
        let yy1 = lerp(yStart, yEnd, f1);
        let yy2 = lerp(yStart, yEnd, f2);
        let localT = (0.10 + 0.62 * coreFactor) * (1 - 0.68 * f1);
        strokeCurve([[x, yy1], [x + random(-2, 2), yy2]], "fineSpray", thermalHex(localT), 1.15);
      }
    }
  }

  // Perspective tile grid (cool dark grout seams cutting crisply across the warm reflection)
  let vpX = 575;
  let vpY = 440;
  let tileRowsY = [892, 916, 945, 980, 1022, 1074, 1136, 1200];

  // Horizontal tile grout lines
  for (let r = 0; r < tileRowsY.length; r++) {
    let y = tileRowsY[r];
    // Draw segmented horizontal line so grout is slightly cooler than local floor heat
    for (let x = 0; x < 1200; x += 40) {
      let xm = x + 20;
      let distToHeat = hypot((xm - 585) / 1.2, (y - 990) * 2.2);
      let tGrout = constrain(0.36 - distToHeat / 950, 0.02, 0.34);
      strokeCurve([[x, y], [x + 40, y]], "crispMarker", thermalHex(tGrout), 0.55);
    }
  }

  // Perspective radial grout lines
  for (let i = -11; i <= 11; i++) {
    let xBot = 585 + i * 96;
    let tRatio = (892 - vpY) / (1200 - vpY);
    let xTop = lerp(vpX, xBot, tRatio);
    let steps = 8;
    for (let s = 0; s < steps; s++) {
      let u1 = s / steps;
      let u2 = (s + 1) / steps;
      let x1 = lerp(xTop, xBot, u1);
      let y1 = lerp(892, 1200, u1);
      let x2 = lerp(xTop, xBot, u2);
      let y2 = lerp(892, 1200, u2);
      let distToHeat = hypot((x1 - 585) / 1.2, (y1 - 990) * 2.2);
      let tGrout = constrain(0.34 - distToHeat / 950, 0.02, 0.32);
      strokeCurve([[x1, y1], [x2, y2]], "crispMarker", thermalHex(tGrout), 0.5);
    }
  }

  // Specular thermal tile-edge highlights near the hot towel heap
  for (let r = 2; r < tileRowsY.length - 1; r++) {
    let y = tileRowsY[r] + 2.5;
    for (let x = 300; x <= 880; x += 48) {
      let d = hypot((x - 585) / 1.15, (y - 995) * 2.1);
      if (d < 320) {
        let tHi = map(d, 0, 320, 0.62, 0.14);
        strokeCurve([[x, y], [x + 34, y]], "rotring", thermalHex(tHi), 0.55);
      }
    }
  }
}

// ============================================================================
// 3. MAIN INDUSTRIAL DRYER CABINET & CONTROL PANEL
// ============================================================================
function drawDryerCabinet() {
  // Main cabinet body (x: 148..968, y: 58..892)
  washRect(148, 58, 820, 834, thermalHex(0.08), 255);

  // Radial heat conduction across the steel front panel surrounding the drum (cx = 575, cy = 475)
  let cx = 575, cy = 475;
  for (let r = 430; r >= 295; r -= 12) {
    let norm = map(r, 430, 295, 0, 1);
    // Upper panel above the drum is warmer due to rising convective plume
    for (let a = 0; a < 360; a += 18) {
      let aNext = a + 18;
      let plumeBoost = (a >= 210 && a <= 330) ? 0.14 * sin(map(a, 210, 330, 0, 180)) : 0;
      let t = 0.09 + 0.28 * pow(norm, 1.5) + plumeBoost * norm;
      let x1 = constrain(cx + r * cos(a), 154, 962);
      let y1 = constrain(cy + r * sin(a), 178, 785);
      let x2 = constrain(cx + r * cos(aNext), 154, 962);
      let y2 = constrain(cy + r * sin(aNext), 178, 785);
      strokeCurve([[x1, y1], [x2, y2]], "thermalBloom", thermalHex(t), 1.3);
    }
  }

  // Upper Control Panel Fascia (x: 148..968, y: 58..174)
  washRect(148, 58, 820, 116, thermalHex(0.09), 250);
  // Crisp structural seams with marker
  strokeCurve([[148, 58], [968, 58]], "heavyMarker", thermalHex(0.03), 1.1);
  strokeCurve([[148, 174], [968, 174]], "heavyMarker", thermalHex(0.04), 1.2);
  strokeCurve([[148, 178], [968, 178]], "crispMarker", thermalHex(0.24), 0.7);
  strokeCurve([[148, 58], [148, 892]], "heavyMarker", thermalHex(0.02), 1.4);
  strokeCurve([[968, 58], [968, 892]], "heavyMarker", thermalHex(0.02), 1.4);

  // Left control bay: recessed brand badge & instruction plate
  washRect(180, 78, 210, 74, thermalHex(0.12), 235);
  strokePoly([[180, 78], [390, 78], [390, 152], [180, 152]], "crispMarker", thermalHex(0.20), 0.65, true, 0);
  for (let ly = 94; ly <= 138; ly += 11) {
    strokeCurve([[196, ly], [365 - (ly % 3) * 25, ly]], "rotring", thermalHex(0.22), 0.55);
  }

  // Center control bay: Temperature selector buttons & warm internal power transformer
  washRect(425, 74, 330, 82, thermalHex(0.13), 240);
  // Warm transformer bloom behind the digital controller
  for (let r = 70; r >= 10; r -= 10) {
    let t = map(r, 70, 10, 0.16, 0.58);
    let pts = [];
    for (let a = 0; a < 360; a += 30) {
      pts.push([545 + r * 1.3 * cos(a), 115 + r * 0.55 * sin(a)]);
