  }
  strokePoly([[425, 74], [755, 74], [755, 156], [425, 156]], "crispMarker", thermalHex(0.26), 0.7, true, 0);

  // 4 Temperature Push-Buttons (Leftmost "HIGH HEAT" is active and warm!)
