    let bx = 448 + b * 54;
    let by = 92;
    let isHotBtn = (b === 0);
    let tBtn = isHotBtn ? 0.72 : 0.20;
    washRect(bx, by, 40, 46, thermalHex(tBtn), 235);
    strokePoly([[bx, by], [bx + 40, by], [bx + 40, by + 46], [bx, by + 46]], "crispMarker", thermalHex(isHotBtn ? 0.90 : 0.32), 0.6, true, 0);
    if (isHotBtn) {
      // Glowing LED indicator on High Heat button
      washRect(bx + 10, by + 8, 20, 8, thermalHex(0.96), 250);
    }
  }

  // Digital countdown LED window on control panel
  washRect(672, 90, 64, 48, thermalHex(0.32), 245);
  strokePoly([[672, 90], [736, 90], [736, 138], [672, 138]], "crispMarker", thermalHex(0.55), 0.65, true, 0);
  drawVecText("00", 686, 104, 20, thermalHex(0.84), 0.95);

  // Right control bay: Coin mechanism / Card drop housing
  washRect(790, 70, 145, 88, thermalHex(0.11), 245);
  strokePoly([[790, 70], [935, 70], [935, 158], [790, 158]], "crispMarker", thermalHex(0.24), 0.7, true, 0);
  // Warm coin solenoid spot
  strokeCurve([[855, 105], [875, 105]], "thermalBloom", thermalHex(0.46), 0.9);
  washRect(825, 92, 16, 42, thermalHex(0.04), 250); // coin slot

  // Lower Kickplate & Exhaust Blower Access Panel (x: 148..968, y: 782..892)
  washRect(148, 782, 820, 110, thermalHex(0.10), 250);
  strokeCurve([[148, 782], [968, 782]], "heavyMarker", thermalHex(0.03), 1.1);
  strokeCurve([[148, 786], [968, 786]], "crispMarker", thermalHex(0.32), 0.75);

  // Hot exhaust duct glow behind lower-left louvers
  for (let r = 110; r >= 15; r -= 14) {
