      strokeCurve([[vx, vy], [vx + 72, vy]], "crispMarker", thermalHex(tSlot), 0.75);
      strokeCurve([[vx, vy + 3], [vx + 72, vy + 3]], "rotring", thermalHex(0.04), 0.6);
