// ============================================================================
// 4. DEEP PERFORATED DRUM INTERIOR (THE HOT CORE)
// ============================================================================
function drawPerforatedDrumCore() {
  let frontCx = 575, frontCy = 475, frontR = 260;
  let backCx = 612,  backCy = 442,  backR = 156;

  // Clip / fill base circular opening
  let openCircle = [];
  for (let a = 0; a < 360; a += 6) {
    openCircle.push([frontCx + frontR * cos(a), frontCy + frontR * sin(a)]);
  }
  washPoly(openCircle, thermalHex(0.68), 255, 0.1);

  // Cylindrical frustum rings from front (s=0) to back plate (s=1)
  let numRings = 24;
  for (let i = 0; i <= numRings; i++) {
    let s = i / numRings;
    let r = lerp(frontR, backR, s);
    let cx = lerp(frontCx, backCx, s);
    let cy = lerp(frontCy, backCy, s);

    // Draw angular segments around the cylinder wall so upper-right/back is blazing white-yellow
    let segs = 24;
    for (let j = 0; j < segs; j++) {
      let a1 = (j / segs) * 360;
      let a2 = ((j + 1) / segs) * 360;
      let aMid = (a1 + a2) * 0.5;
      // Heat peaks toward upper-right-rear (-45 deg) and deep s
      let dirHeat = 0.5 + 0.5 * cos(aMid + 38);
      let t = 0.54 + 0.34 * pow(s, 0.75) + 0.14 * dirHeat * (0.4 + 0.6 * s);
      t = constrain(t, 0.50, 0.99);
      let x1 = cx + r * cos(a1);
      let y1 = cy + r * sin(a1);
      let x2 = cx + r * cos(a2);
      let y2 = cy + r * sin(a2);
      strokeCurve([[x1, y1], [x2, y2]], "thermalBloom", thermalHex(t), 1.35);
    }
  }

  // Circular Back Wall Plate (backCx, backCy, backR)
  for (let r = backR; r >= 12; r -= 10) {
    let norm = 1 - r / backR;
    // Slightly offset toward upper-right where hot air burner diffuser enters
    let bx = lerp(backCx, backCx + 24, norm * 0.65);
    let by = lerp(backCy, backCy - 22, norm * 0.65);
    let t = constrain(0.84 + 0.16 * pow(norm, 0.7), 0.82, 1.00);
    let ringPts = [];
    for (let a = 0; a < 360; a += 12) {
      ringPts.push([bx + r * cos(a), by + r * sin(a)]);
    }
    washPoly(ringPts, thermalHex(t), 185, 0.15);
  }

  // Intense white-yellow burner plenum bloom in upper-right quadrant of back wall
  for (let k = 0; k < 18; k++) {
    let ang = random(-115, 25);
    let rad = random(15, backR * 0.85);
    let px = backCx + rad * cos(ang);
    let py = backCy + rad * sin(ang);
    strokeCurve([[px - 18, py - 10], [px + 18, py + 10]], "thermalBloom", thermalHex(0.99), 1.4);
  }

  // Stamped structural ribs (3 radial spokes) & central conical boss on the back plate
  let bossPts = [];
  for (let a = 0; a < 360; a += 18) {
    bossPts.push([backCx + 32 * cos(a), backCy + 32 * sin(a)]);
  }
  washPoly(bossPts, thermalHex(0.95), 230, 0.15);
  strokePoly(bossPts, "crispMarker", thermalHex(0.76), 0.65, true, 0.15);

  let innerCapPts = [];
  for (let a = 0; a < 360; a += 24) {
    innerCapPts.push([backCx + 13 * cos(a), backCy + 13 * sin(a)]);
  }
  washPoly(innerCapPts, thermalHex(0.80), 240, 0.15);
  strokePoly(innerCapPts, "rotring", thermalHex(1.00), 0.7, true, 0.15);

  // Back Plate Perforations (7 concentric rings of holes, skipping the 3 solid structural spokes & towel-covered bottom)
  let spokeAngles = [-90, 30, 150];
  for (let ring = 1; ring <= 7; ring++) {
    let rr = 38 + ring * 15.5;
    let numHoles = Math.floor((TWO_PI * rr) / 11.5);
    for (let h = 0; h < numHoles; h++) {
      let a = (h / numHoles) * 360 - 180;
      // Lower portion of back plate is behind tumbling towels (skip below +55 deg to +155 deg)
      if (a > 52 && a < 158) continue;

      // Skip along the 3 solid stamped spokes
      let onSpoke = false;
      for (let sp of spokeAngles) {
        let diff = abs(((a - sp + 540) % 360) - 180);
        if (diff < 11) onSpoke = true;
      }
      if (onSpoke) continue;

      let hx = backCx + rr * cos(a);
      let hy = backCy + rr * sin(a);

      // In the upper-right burner inlet zone (-105 to +15 deg), the plenum behind the holes is BLAZING 1.00 white-yellow!
      // Elsewhere on the back plate, the holes show a darker orange/scarlet shadow cavity behind the glowing plate.
      let inBurnerPlenum = (a >= -110 && a <= 18);
      let holeT = inBurnerPlenum ? 1.00 : constrain(0.66 + 0.12 * cos(a + 35), 0.58, 0.78);
      let rimT  = inBurnerPlenum ? 0.88 : 0.97;

      brush.set("crispMarker", thermalHex(holeT), 0.78);
      brush.line(hx - 1.6, hy - 0.8, hx + 1.6, hy + 0.8);
      brush.set("rotring", thermalHex(rimT), 0.55);
      brush.line(hx - 1.5, hy + 1.4, hx + 1.5, hy + 1.4);
    }
  }

  // Back plate circumference seam
  let backSeam = [];
  for (let a = -175; a <= 55; a += 6) {
    backSeam.push([backCx + backR * cos(a), backCy + backR * sin(a)]);
  }
  strokeCurve(backSeam, "crispMarker", thermalHex(0.72), 0.8);

  // Cylindrical Side-Wall Perforations (15 axial depth rows x circumferential grid)
  for (let row = 1; row <= 15; row++) {
    let s = map(row, 1, 15, 0.07, 0.94);
    let r = lerp(frontR, backR, s);
    let cx = lerp(frontCx, backCx, s);
    let cy = lerp(frontCy, backCy, s);

    // Step around visible upper/left/right cylinder walls (-175 deg to +38 deg)
    let angleStep = 5.5;
    for (let a = -174; a <= 38; a += angleStep) {
      // Skip where the 3 drum baffles sit (-132 deg, -24 deg, +95 deg)
      if (abs(a - (-132)) < 9 || abs(a - (-24)) < 9) continue;
      // Stagger alternate rows
      let aa = a + (row % 2) * (angleStep * 0.5);
      let hx = cx + r * cos(aa);
      let hy = cy + r * sin(aa);

      // Tangent direction along the cylinder circumference for foreshortened elliptical hole
      let tx = -sin(aa);
      let ty = cos(aa);
      // Axial direction along cylinder depth
      let ax = (backCx - frontCx) + (backR - frontR) * cos(aa);
      let ay = (backCy - frontCy) + (backR - frontR) * sin(aa);
      let alen = hypot(ax, ay) || 1;
      ax /= alen;
      ay /= alen;

      let holeLen = lerp(3.2, 1.8, s);
      let dirHeat = 0.5 + 0.5 * cos(aa + 38);
      let wallT = 0.54 + 0.34 * pow(s, 0.75) + 0.14 * dirHeat * (0.4 + 0.6 * s);

      // Perforation interior is cooler dark magenta/scarlet near front, glowing hot near rear burner
      let holeT = (s > 0.68 && aa > -105 && aa < 10)
        ? 1.00
        : constrain(wallT - 0.22, 0.34, 0.78);
      let rimHighlightT = constrain(wallT + 0.11, 0.68, 1.00);

      brush.set("crispMarker", thermalHex(holeT), lerp(0.85, 0.52, s));
      brush.line(
        hx - ax * holeLen * 0.5 - tx * 0.9,
        hy - ay * holeLen * 0.5 - ty * 0.9,
        hx + ax * holeLen * 0.5 + tx * 0.9,
        hy + ay * holeLen * 0.5 + ty * 0.9
      );

      // Specular thermal lip on the front-facing edge of each perforation
      brush.set("rotring", thermalHex(rimHighlightT), 0.48);
      brush.line(
        hx - ax * holeLen * 0.5 + tx * 1.3,
        hy - ay * holeLen * 0.5 + ty * 1.3,
        hx + ax * holeLen * 0.35 + tx * 1.3,
        hy + ay * holeLen * 0.35 + ty * 1.3
      );
    }
  }

  // 3D Triangular Drum Baffles / Tumbling Fins inside the cylinder
  drawDrumBaffle(frontCx, frontCy, frontR, backCx, backCy, backR, -132, 34, false);
  drawDrumBaffle(frontCx, frontCy, frontR, backCx, backCy, backR, -24,  36, true);
}

function drawDrumBaffle(frontCx, frontCy, frontR, backCx, backCy, backR, angleDeg, heightPx, isHotSide) {
  let s0 = 0.06, s1 = 0.95;
  let r0 = lerp(frontR, backR, s0), r1 = lerp(frontR, backR, s1);
  let cx0 = lerp(frontCx, backCx, s0), cy0 = lerp(frontCy, backCy, s0);
  let cx1 = lerp(frontCx, backCx, s1), cy1 = lerp(frontCy, backCy, s1);

  let aL = angleDeg - 8;
  let aR = angleDeg + 8;

  // Base points on cylinder wall
  let p0L = [cx0 + r0 * cos(aL), cy0 + r0 * sin(aL)];
  let p1L = [cx1 + r1 * cos(aL), cy1 + r1 * sin(aL)];
  let p0R = [cx0 + r0 * cos(aR), cy0 + r0 * sin(aR)];
  let p1R = [cx1 + r1 * cos(aR), cy1 + r1 * sin(aR)];

  // Apex ridge projecting inward toward drum axis
  let h0 = heightPx;
  let h1 = heightPx * 0.62;
  let apex0 = [cx0 + (r0 - h0) * cos(angleDeg), cy0 + (r0 - h0) * sin(angleDeg)];
  let apex1 = [cx1 + (r1 - h1) * cos(angleDeg), cy1 + (r1 - h1) * sin(angleDeg)];

  // Two faces of the triangular fin
  let faceA = [p0L, p1L, apex1, apex0];
  let faceB = [apex0, apex1, p1R, p0R];
  let frontCap = [p0L, apex0, p0R];

  let tFaceA = isHotSide ? 0.90 : 0.72;
  let tFaceB = isHotSide ? 0.78 : 0.88;

  washPoly(faceA, thermalHex(tFaceA), 235, 0.05);
  washPoly(faceB, thermalHex(tFaceB), 235, 0.05);
  washPoly(frontCap, thermalHex(0.56), 245, 0.05);

  // Smooth thermal gradient along fin length
  for (let k = 0; k <= 10; k++) {
    let u = k / 10;
    let ax = lerp(apex0[0], apex1[0], u);
    let ay = lerp(apex0[1], apex1[1], u);
    let bx = lerp(p0L[0], p1L[0], u);
    let by = lerp(p0L[1], p1L[1], u);
    let t = lerp(tFaceA - 0.14, min(0.99, tFaceA + 0.08), u);
    strokeCurve([[ax, ay], [bx, by]], "fineSpray", thermalHex(t), 0.9);
  }

  // Crisp marker edges along the fin crest and base
  strokeCurve([p0L, p1L], "crispMarker", thermalHex(0.52), 0.75);
  strokeCurve([p0R, p1R], "crispMarker", thermalHex(0.55), 0.75);
  strokeCurve([apex0, apex1], "crispMarker", thermalHex(0.97), 0.95);
  strokePoly(frontCap, "crispMarker", thermalHex(0.42), 0.8, true, 0.05);
}

// ============================================================================
// 5. DRUM BEZEL & COLD-TO-HOT METAL BOUNDARY
// ============================================================================
function drawDrumBezel() {
  let cx = 575, cy = 475;
  let rInner = 258;
  let rMid   = 278;
  let rOuter = 304;

  // Draw the annular steel & rubber door bezel in angular segments
  // Only draw from -195 deg around the top/right to +55 deg in full, and the bottom lip under the towels as base
  let segs = 72;
  for (let i = 0; i < segs; i++) {
    let a1 = (i / segs) * 360;
    let a2 = ((i + 1) / segs) * 360;
    let aMid = (a1 + a2) * 0.5;

    // Outer metal flange is cool indigo-violet (0.18..0.34), warming at the top due to rising heat
    let topWarmth = (aMid >= 210 && aMid <= 330) ? 0.15 * sin(map(aMid, 210, 330, 0, 180)) : 0;
    let tOuter = 0.18 + topWarmth;
    let tInner = 0.44 + topWarmth * 1.2;

    let quadOuter = [
      [cx + rMid * cos(a1), cy + rMid * sin(a1)],
      [cx + rOuter * cos(a1), cy + rOuter * sin(a1)],
      [cx + rOuter * cos(a2), cy + rOuter * sin(a2)],
      [cx + rMid * cos(a2), cy + rMid * sin(a2)]
    ];
    washPoly(quadOuter, thermalHex(tOuter), 245, 0);

    let quadInner = [
      [cx + rInner * cos(a1), cy + rInner * sin(a1)],
      [cx + rMid * cos(a1), cy + rMid * sin(a1)],
      [cx + rMid * cos(a2), cy + rMid * sin(a2)],
      [cx + rInner * cos(a2), cy + rInner * sin(a2)]
    ];
    washPoly(quadInner, thermalHex(tInner), 245, 0);
  }

  // Crisp marker rings defining the exact machined metal steps of the drum opening
  for (let ringR of [rOuter, rOuter - 5, rMid, rInner]) {
    let pts = [];
    for (let a = 0; a <= 360; a += 5) {
      pts.push([cx + ringR * cos(a), cy + ringR * sin(a)]);
    }
    let tRim = (ringR === rInner) ? 0.66 : (ringR === rMid ? 0.34 : 0.12);
    let wRim = (ringR === rInner || ringR === rOuter) ? 1.05 : 0.75;
    strokeCurve(pts, "crispMarker", thermalHex(tRim), wRim);
  }

  // Bolt rivets around the outer bezel flange
  for (let a = 15; a < 360; a += 30) {
    let bx = cx + (rOuter - 11) * cos(a);
    let by = cy + (rOuter - 11) * sin(a);
    brush.set("crispMarker", thermalHex(0.08), 0.9);
    brush.line(bx - 2, by - 2, bx + 2, by + 2);
    brush.set("rotring", thermalHex(0.36), 0.6);
    brush.line(bx - 2, by + 2, bx + 2, by + 2);
  }
}

