  }

  // Foreshortened elliptical outer cast-metal door frame (centered at 166, 478)
  let dCx = 166, dCy = 478;
  let outerRx = 112, outerRy = 248;
  let innerRx = 78,  innerRy = 192;

  // Outer door thickness rim (left edge at x - 16)
