// ============================================================================
// 7. TUMBLING CASCADE OF HOT TERRY-CLOTH TOWELS
// ============================================================================
// Builds a hyperreal folded towel lobe between two guide curves with:
// 1. Base thermal wash
// 2. Smooth spray thermal bloom (hotter deep valleys, cooler outer ridges)
// 3. Crisp marker boundaries where hot cotton meets cold metal or overlaps
// 4. Optional woven dobby border band
// 5. Dense cross-contour terry loops
function renderTowelFoldLobe(cfg) {
  let stepsU = cfg.stepsU || 26;
  let curveA = sampleSplinePts(cfg.topCurve, stepsU);
  let curveB = sampleSplinePts(cfg.botCurve, stepsU);

  // Polygon perimeter
  let polyPts = [];
  for (let i = 0; i <= stepsU; i++) polyPts.push(curveA[i]);
  for (let i = stepsU; i >= 0; i--) polyPts.push(curveB[i]);

  // 1. Base wash
  let avgT = (cfg.tStart + cfg.tEnd) * 0.5;
  washPoly(polyPts, thermalHex(avgT), 245, 0.12);

  // 2. Smooth longitudinal spray ribbons across the fold width (v from 0 to 1)
  let stripsV = cfg.stripsV || 11;
  for (let j = 0; j <= stripsV; j++) {
    let v = j / stripsV;
    // Fold profile: v=0 and v=1 are deep tucked crevices (HOTTER), v=0.5 is exposed outer ridge (COOLER)
    // Unless invertCrevice is set
    let arch = sin(v * 180); // 0 at edges, 1 at center crown
    let vMod = cfg.hotCrevice
      ? lerp(0.11, -0.09, arch)
      : lerp(-0.10, 0.12, arch);

    // Sub-divide longitudinally into 3 segments so temperature shifts smoothly along u
    for (let seg = 0; seg < 3; seg++) {
      let iStart = Math.floor((seg / 3) * stepsU);
      let iEnd   = Math.floor(((seg + 1) / 3) * stepsU);
      let segPts = [];
      let uMid = ((iStart + iEnd) * 0.5) / stepsU;

      for (let i = iStart; i <= iEnd; i++) {
        let u = i / stepsU;
        let x = lerp(curveA[i][0], curveB[i][0], v);
        let y = lerp(curveA[i][1], curveB[i][1], v);
        // Add subtle organic cloth ripple
        let ripple = (noise(x * 0.015, y * 0.015, cfg.seed || 1) - 0.5) * 8 * arch;
        segPts.push([x + ripple * 0.4, y + ripple]);
      }

      let tLocal = lerp(cfg.tStart, cfg.tEnd, uMid) + vMod + (cfg.edgeBias ? (0.5 - v) * cfg.edgeBias : 0);
      tLocal = constrain(tLocal, 0.16, 1.00);
      let bName = (j === 0 || j === stripsV) ? "fineSpray" : "thermalBloom";
      strokeCurve(segPts, bName, thermalHex(tLocal), cfg.sprayWeight || 1.15);
    }
  }

  // 3. Extra incandescent crevice glow along the deep fold valley
  if (cfg.creviceSide === "top" || cfg.creviceSide === "both") {
    let cPts = [];
    for (let i = 1; i < stepsU; i++) {
      cPts.push([
        lerp(curveA[i][0], curveB[i][0], 0.08),
        lerp(curveA[i][1], curveB[i][1], 0.08)
      ]);
    }
    let tCrev = constrain(max(cfg.tStart, cfg.tEnd) + 0.12, 0.35, 1.00);
    strokeCurve(cPts, "fineSpray", thermalHex(tCrev), 1.1);
  }
  if (cfg.creviceSide === "bot" || cfg.creviceSide === "both") {
    let cPts = [];
    for (let i = 1; i < stepsU; i++) {
      cPts.push([
        lerp(curveA[i][0], curveB[i][0], 0.92),
        lerp(curveA[i][1], curveB[i][1], 0.92)
      ]);
    }
    let tCrev = constrain((cfg.tStart + cfg.tEnd) * 0.5 + 0.12, 0.30, 1.00);
    strokeCurve(cPts, "fineSpray", thermalHex(tCrev), 1.1);
  }

  // 4. Optional Woven Dobby Border Band (classic flat ribbed band parallel to towel edge)
  if (cfg.dobbyBand) {
    let vBand1 = cfg.dobbyV || 0.72;
    let vBand2 = vBand1 + 0.11;
    let bandPts1 = [], bandPts2 = [], bandMid = [];
    for (let i = 0; i <= stepsU; i++) {
      bandPts1.push([lerp(curveA[i][0], curveB[i][0], vBand1), lerp(curveA[i][1], curveB[i][1], vBand1)]);
      bandPts2.push([lerp(curveA[i][0], curveB[i][0], vBand2), lerp(curveA[i][1], curveB[i][1], vBand2)]);
      bandMid.push([lerp(curveA[i][0], curveB[i][0], (vBand1 + vBand2) * 0.5), lerp(curveA[i][1], curveB[i][1], (vBand1 + vBand2) * 0.5)]);
    }
    let tBand = constrain((cfg.tStart + cfg.tEnd) * 0.5 - 0.06, 0.20, 0.94);
    let tSeam = constrain((cfg.tStart + cfg.tEnd) * 0.5 + 0.09, 0.30, 0.99);
    strokeCurve(bandMid, "crispMarker", thermalHex(tBand), 1.35);
    strokeCurve(bandPts1, "rotring", thermalHex(tSeam), 0.7);
    strokeCurve(bandPts2, "rotring", thermalHex(tSeam), 0.7);

    // Fine ribbed weave ticks across the dobby border
    for (let i = 1; i < stepsU; i++) {
      let u = i / stepsU;
      let tTick = constrain(lerp(cfg.tStart, cfg.tEnd, u) + 0.04, 0.24, 0.98);
      brush.set("cpencil", thermalHex(tTick), 0.65);
      brush.line(bandPts1[i][0], bandPts1[i][1], bandPts2[i][0], bandPts2[i][1]);
    }
  }

  // 5. Crisp Marker Boundaries where hot cotton meets cold metal or shadows another fold
  if (cfg.markerTop !== undefined) {
    strokeCurve(curveA, "crispMarker", thermalHex(cfg.markerTop), cfg.markerWeight || 0.95);
  }
  if (cfg.markerBot !== undefined) {
    strokeCurve(curveB, "crispMarker", thermalHex(cfg.markerBot), cfg.markerWeight || 0.95);
  }

  // 6. Hyperreal Terry-Cloth Loops across the 3D surface of the lobe
  let loopRows = cfg.loopRows || 7;
  let loopCols = cfg.loopCols || 24;
  for (let r = 0; r <= loopRows; r++) {
    let v = map(r, 0, loopRows, 0.06, 0.94);
    // Skip terry loops directly inside the flat woven dobby border
    if (cfg.dobbyBand && v >= (cfg.dobbyV || 0.72) && v <= (cfg.dobbyV || 0.72) + 0.11) continue;

    let arch = sin(v * 180);
    let vMod = cfg.hotCrevice ? lerp(0.10, -0.08, arch) : lerp(-0.09, 0.10, arch);

    for (let c = 0; c < loopCols; c++) {
      let u = (c + random(0.15, 0.85)) / loopCols;
      let idx = constrain(Math.floor(u * stepsU), 0, stepsU - 1);
      let f = u * stepsU - idx;

      let ax = lerp(curveA[idx][0], curveA[idx + 1][0], f);
      let ay = lerp(curveA[idx][1], curveA[idx + 1][1], f);
      let bx = lerp(curveB[idx][0], curveB[idx + 1][0], f);
      let by = lerp(curveB[idx][1], curveB[idx + 1][1], f);

      let px = lerp(ax, bx, v);
      let py = lerp(ay, by, v);

      // Local surface tangent & cross-contour vectors
      let tx = curveA[idx + 1][0] - curveA[idx][0];
      let ty = curveA[idx + 1][1] - curveA[idx][1];
      let tLen = hypot(tx, ty) || 1;
      tx /= tLen; ty /= tLen;

      let nx = bx - ax;
      let ny = by - ay;
      let nLen = hypot(nx, ny) || 1;
      nx /= nLen; ny /= nLen;

      let baseT = lerp(cfg.tStart, cfg.tEnd, u) + vMod + (cfg.edgeBias ? (0.5 - v) * cfg.edgeBias : 0);
      // Alternating raised cooler loop tip and warm glowing pile base
      let isWarmLoop = ((r + c) % 2 === 0);
      let loopT = constrain(baseT + (isWarmLoop ? 0.085 : -0.075) + random(-0.03, 0.03), 0.16, 1.00);

      let loopR = random(2.4, 4.4);
      let p1 = [px - tx * loopR, py - ty * loopR];
      let p2 = [px + nx * loopR * 0.85 + random(-1, 1), py + ny * loopR * 0.85 + random(-1, 1)];
      let p3 = [px + tx * loopR, py + ty * loopR];

      strokeCurve([p1, p2, p3], "terryLoop", thermalHex(loopT), random(0.65, 1.05), 0.7);
    }
  }

  // Protruding nubby terry loops along the silhouette edge
  let edgeCurve = cfg.nubbyBot ? curveB : curveA;
  let edgeTBase = cfg.nubbyBot ? (cfg.markerBot || avgT) : (cfg.markerTop || avgT);
  for (let i = 1; i < stepsU; i += 1) {
    if (random() < 0.75) {
      let p = edgeCurve[i];
      let ang = random(0, 360);
      let rad = random(2.2, 4.2);
      let tNub = constrain(edgeTBase + random(-0.05, 0.09), 0.22, 0.99);
      strokeCurve(
        [
          [p[0] - rad * cos(ang), p[1] - rad * sin(ang)],
          [p[0] + rad * sin(ang), p[1] - rad * cos(ang)],
          [p[0] + rad * cos(ang), p[1] + rad * sin(ang)]
        ],
        "terryLoop",
        thermalHex(tNub),
        0.8,
        0.75
      );
    }
  }
}

