function drawThermalHUD() {
  // Top-Right Corner HUD Layout
  let barX = 1116;
  let barY = 92;
  let barW = 22;
  let barH = 248;

  // Dark clinical backing plate for readability
  washRect(1002, 54, 162, 326, thermalHex(0.02), 185);
  strokePoly([[1002, 54], [1164, 54], [1164, 380], [1002, 380]], "rotring", thermalHex(0.28), 0.55, true, 0);

  // Smooth 50-step false-color temperature scale bar
  let steps = 50;
  let stepH = barH / steps;
  for (let i = 0; i < steps; i++) {
    let t = 1 - i / (steps - 1);
    let sy = barY + i * stepH;
    washRect(barX, sy, barW, stepH + 0.8, thermalHex(t), 255);
  }

  // Crisp technical frame & tick marks around scale bar
  strokePoly(
    [[barX, barY], [barX + barW, barY], [barX + barW, barY + barH], [barX, barY + barH]],
    "rotring",
    thermalHex(0.92),
    0.65,
