// Point-in-polygon test
function inPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi + 0.0001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

// Helper to draw a closed or open shape from point array
function drawShapePts(pts, closed = true, curvature = 0.25) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(closed);
}

// Helper to offset points
function offsetPts(pts, dx, dy) {
  return pts.map(p => [p[0] + dx, p[1] + dy]);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(4219);
  noiseSeed(8813);

  // Custom lithographic grease crayon brush (gritty stone tooth)
  brush.add("litho_crayon", {
    type: "default",
    weight: 1.8,
    scatter: 1.55,
    sharpness: 0.22,
    grain: 22,
    opacity: 82,
    spacing: 0.35,
    pressure: [0.4, 1.2, 0.3],
    noise: 0.9
  });

  // Custom reticulated tusche vein brush
  brush.add("tusche_vein", {
    type: "default",
    weight: 0.95,
    scatter: 0.35,
    sharpness: 0.68,
    grain: 10,
    opacity: 145,
    spacing: 0.22,
    pressure: [0.3, 1.35, 0.25],
    noise: 0.8
  });

  // Custom lithographer's steel scraper blade for highlights
  brush.add("scraper", {
    type: "custom",
    weight: 1.35,
    scatter: 0.08,
    opacity: 225,
    spacing: 0.16,
    pressure: [0.15, 1.3, 0.1],
    tip: (_m) => {
      _m.rotate(20);
      _m.rect(-2.2, -0.35, 4.4, 0.7);
    },
    rotate: "natural",
    markerTip: false,
    noise: 0.4
  });

  // Custom vector field following the sag and crease flow of the leather boot
  brush.addField("boot_flow", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = (col / field.length) * 1200;
        let y = (row / field[0].length) * 1200;
        let angle = -22;
        if (x < 380) {
          // Toe dome wraps radially
          angle = atan2(y - 720, x - 260) + 85;
        } else if (x < 620) {
          // Instep creases sweep steeply down toward welt
          angle = 68 + 18 * sin((x - 380) * 0.8) + 12 * noise(x * 0.01, y * 0.01);
        } else {
          // Shaft folds sag diagonally toward collar
          angle = -32 + 24 * sin((x + y) * 0.35) + 15 * (noise(x * 0.008, y * 0.008) - 0.5);
        }
        field[col][row] = angle;
      }
    }
    return field;
  });
}

