function renderPaperAndStoneGround() {
  brush.noStroke();

  // Warm mottled rag paper tone inside the stone boundary
  brush.fill(PAPER_DIRTY, 42);
  brush.fillTexture(0.65, 0.35);
  brush.fillBleed(0.15, "out");
  let stoneEdge = [
    [58, 82], [610, 74], [1142, 86],
    [1148, 600], [1138, 1118],
    [600, 1126], [62, 1114], [52, 600]
  ];
  drawShapePts(stoneEdge, true, 0.08);
  brush.noFill();

  // Subtle limestone edge emboss / bevel line
  brush.set("2H", "#c9bba0", 0.7);
  drawShapePts(stoneEdge, true, 0.08);
  brush.set("2H", "#faf4e6", 0.9);
  drawShapePts(offsetPts(stoneEdge, -3, -3), true, 0.08);

  // Lithographer's registration T-marks (Key Stone vs Olive Stone off-register)
  // Olive registration mark (shifted by OX*0.4, OY*0.4 at margins)
  brush.set("rotring", OLIVE_DARK, 0.65);
  brush.line(600 + 6, 38 - 5, 600 + 6, 62 - 5);
  brush.line(586 + 6, 50 - 5, 614 + 6, 50 - 5);
  brush.line(600 + 6, 1142 - 5, 600 + 6, 1166 - 5);
  brush.line(586 + 6, 1154 - 5, 614 + 6, 1154 - 5);
  brush.line(26 + 6, 600 - 5, 48 + 6, 600 - 5);
  brush.line(37 + 6, 586 - 5, 37 + 6, 614 - 5);

  // Key Stone registration mark
  brush.set("rotring", BLACK_MID, 0.65);
  brush.line(600, 38, 600, 62);
  brush.line(586, 50, 614, 50);
  brush.line(600, 1142, 600, 1166);
  brush.line(586, 1154, 614, 1154);
  brush.line(26, 600, 48, 600);
  brush.line(37, 586, 37, 614);
}

