// =============================================================================
// 4. KEY STONE PASS B: RETICULATED TUSCHE ("LIZARD-SKIN" CRACKLE & POOLING)
// =============================================================================
function renderReticulatedTuscheNetwork() {
  // Generate seed points across the leather upper for cellular tusche reticulation
  let seeds = [];
  for (let x = 128; x <= 1045; x += 24) {
    for (let y = 235; y <= 860; y += 22) {
      let jx = x + random(-9, 9);
      let jy = y + random(-8, 8);
      if (!inPoly(jx, jy, BOOT_UPPER_PTS)) continue;

      // Exclude the bright scraped toe dome and main buckle interior from heavy tusche cells
      let distToeHighlight = dist(jx, jy, 235, 615);
      if (distToeHighlight < 58) continue;
      if (jx > 520 && jx < 625 && jy > 605 && jy < 695) continue;
      // Exclude dark interior opening (already solid velvet black)
      if (jx > 965 && jy > 250 && jy < 580) continue;

      // Determine local cell scale & orientation based on leather zone
      let rx = random(8, 15);
      let ry = random(6, 12);
      let rot = -20;
      let darkness = noise(jx * 0.009, jy * 0.009);

      if (jx < 365) {
        // Toe cap: compact polygonal crackle cells wrapping the dome
        rx = random(7, 13);
        ry = random(6, 11);
        rot = atan2(jy - 700, jx - 250) + 90;
      } else if (jx < 610) {
        // Vamp & ankle: elongated lizard-skin scales stretched along crease valleys
        rx = random(10, 19);
        ry = random(5.5, 9.5);
        rot = 62 + 15 * sin((jx - 370) * 0.7);
        darkness += 0.18;
      } else {
        // Shaft: larger reticulated tusche puddles along sagging leather folds
        rx = random(12, 22);
        ry = random(7, 13);
        rot = -32 + 20 * sin((jx + jy) * 0.4);
      }

      // Build an irregular 7-sided lizard-skin polygon cell
      let cellPts = [];
      let sides = 7;
      for (let k = 0; k < sides; k++) {
        let a = (k / sides) * 360 + random(-14, 14);
        let rMod = random(0.72, 1.18);
        let lx = cos(a) * rx * rMod;
        let ly = sin(a) * ry * rMod;
        let gx = jx + lx * cos(rot) - ly * sin(rot);
        let gy = jy + lx * sin(rot) + ly * cos(rot);
        cellPts.push([gx, gy]);
      }

      seeds.push({ x: jx, y: jy, pts: cellPts, darkness, rot });
    }
  }

  // Batch-fill the reticulated tusche cells in 2 tonal tiers for performance & depth
  brush.noStroke();

  // Tier 1: Mid-dark reticulated tusche scales with heavy tide-ring borders
  brush.fill(BLACK_MID, 110);
  brush.fillTexture(0.95, 0.92); // High border intensity creates pooled tusche rims!
  brush.fillBleed(0.04, "in");
  for (let s of seeds) {
    if (s.darkness <= 0.56) {
      drawShapePts(s.pts, true, 0.18);
    }
  }

  // Tier 2: Deep lamp-black pooled tusche scales in the crease troughs and lower flank
  brush.fill(BLACK_DEEP, 145);
  brush.fillTexture(0.95, 0.95);
  brush.fillBleed(0.05, "in");
  for (let s of seeds) {
    if (s.darkness > 0.56 || s.y > 720) {
      drawShapePts(s.pts, true, 0.18);
    }
  }
  brush.noFill();

  // Draw the crackled tusche tide-line veins around every cell ("lizard-skin" web)
  for (let i = 0; i < seeds.length; i++) {
    let s = seeds[i];
    if (i % 2 === 0) {
      brush.set("tusche_vein", BLACK_DEEP, random(0.45, 0.85));
    } else {
      brush.set("rotring", BLACK_WARM, random(0.55, 0.95));
    }
    drawShapePts(s.pts, true, 0.15);

    // Tiny reticulation bridge cracks connecting neighboring cells
    if (random() < 0.45) {
      let p0 = s.pts[0];
      let a = s.rot + random(-40, 40);
      brush.line(p0[0], p0[1], p0[0] + cos(a) * 10, p0[1] + sin(a) * 10);
    }
  }

  // Also add reticulated tusche puddles in the cast shadow on the limestone floor
  brush.noStroke();
  brush.fill(BLACK_WARM, 95);
  brush.fillTexture(0.92, 0.9);
  brush.fillBleed(0.08, "out");
  for (let i = 0; i < 38; i++) {
    let sx = random(135, 930);
    let sy = random(860, 975);
    if (sx > 820 && sy < 900) sy -= 70;
    let r = random(10, 28);
    let cPts = [];
    for (let k = 0; k < 6; k++) {
      let ang = k * 60 + random(-15, 15);
      cPts.push([sx + cos(ang) * r * 1.5, sy + sin(ang) * r * 0.55]);
    }
    drawShapePts(cPts, true, 0.25);
  }
  brush.noFill();
}

