// =============================================================================
// 6. KEY STONE PASS D: GRAINY LITHO CRAYON PASSAGES (LIMESTONE TOOTH)
// =============================================================================
function renderGrainyCrayonPassages() {
  // Activate our custom vector field to guide contour-following litho crayon strokes
  brush.field("boot_flow");

  // Pass 1: Broad grainy litho-crayon strokes across the leather body
  for (let i = 0; i < 420; i++) {
    let x = random(122, 1055);
    let y = random(235, 860);
    if (!inPoly(x, y, BOOT_UPPER_PTS)) continue;

    // Keep the scraped toe highlight clean of heavy dark crayon
    let dToe = dist(x, y, 232, 612);
    if (dToe < 52) continue;

    let n = noise(x * 0.007, y * 0.007);
    let isShadowZone = (y > 700) || (x > 375 && x < 580 && y > 560) || (n > 0.54);

    if (isShadowZone) {
      brush.set("litho_crayon", BLACK_DEEP, random(0.8, 1.65));
      brush.flowLine(x, y, random(28, 68), random(-15, 15));
    } else {
      brush.set("cpencil", BLACK_MID, random(0.7, 1.35));
      brush.flowLine(x, y, random(22, 52), random(-10, 10));
    }
  }

  brush.noField();

  // Pass 2: Cross-contour litho crayon modeling around the bulbous 3D Toe Box
  for (let i = 0; i < 135; i++) {
    let ang = random(105, 345);
    let r1 = random(52, 138);
    let r2 = r1 + random(18, 42);
    let cx = 242, cy = 628;
    let x1 = cx + cos(ang) * r1 * 1.12;
    let y1 = cy + sin(ang) * r1 * 0.88;
    let x2 = cx + cos(ang + random(-18, 18)) * r2 * 1.12;
    let y2 = cy + sin(ang + random(-18, 18)) * r2 * 0.88;

    if (inPoly(x1, y1, BOOT_UPPER_PTS) && inPoly(x2, y2, BOOT_UPPER_PTS)) {
      if (y1 > 685 || x1 > 310 || x1 < 165) {
        brush.set("litho_crayon", BLACK_DEEP, random(0.75, 1.5));
      } else {
        brush.set("2B", BLACK_MID, random(0.6, 1.1));
      }
      brush.line(x1, y1, x2, y2);
    }
  }

  // Pass 3: Heavy charcoal & litho-crayon tooth along the cast shadow and lower boot
  for (let i = 0; i < 190; i++) {
    let sx = random(95, 980);
    let sy = random(790, 985);
    if (sx > 830 && sy < 860) sy -= 95;
    let len = random(35, 95);
    let ang = -8 + random(-12, 12);
    if (sx > 780) ang = -36 + random(-12, 12);

    brush.set(i % 2 === 0 ? "litho_crayon" : "charcoal", BLACK_DEEP, random(0.9, 1.9));
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // Pass 4: Fine tusche spatter / stone-grain stipple around the sole, heel & shadow
  brush.set("spray", BLACK_DEEP, 1.1);
  for (let i = 0; i < 55; i++) {
    let rx = random(110, 960);
    let ry = random(740, 965);
    brush.line(rx, ry, rx + random(-18, 18), ry + random(-8, 8));
  }

  // Master Key-Stone Silhouette Contour (heavy, gritty, broken litho line)
  brush.set("litho_crayon", BLACK_DEEP, 2.1);
  drawShapePts(BOOT_UPPER_PTS, false, 0.25);
  brush.set("rotring", BLACK_DEEP, 1.15);
  drawShapePts(BOOT_UPPER_PTS, false, 0.25);
}

