// 7. KEY STONE PASS E: GOODYEAR WELT, STITCHING, LUG SOLE & STACKED HEEL
// =============================================================================
function renderWeltSoleAndHeel() {
  // --- A. GOODYEAR WELT SHELF & HEAVY WAXED STITCHES ---
  let weltUpper = [
    [130, 775], [195, 812], [300, 848], [420, 868], [535, 862], [645, 862], [730, 825], [815, 795]
