  // Structural lines of the welt and leather midsole
  brush.set("rotring", BLACK_DEEP, 1.4);
  brush.spline(weltUpper, 0.2);
  brush.spline(weltLower, 0.2);
  brush.spline(midsoleLower, 0.2);

  // 38 Heavy Goodyear Welt Stitches along the welt shelf (with awl holes + dirty thread loops)
  let stitchSamples = 38;
  for (let i = 0; i < stitchSamples; i++) {
    let t1 = i / stitchSamples;
