    brush.set("rotring", BLACK_DEEP, 1.5);
    brush.line(p1[0], p1[1] + 5, p1[0] + 1, p1[1] + 8);

    // Waxed thread stitch in scraped paper-white / olive-buff
    brush.set("scraper", i % 3 === 0 ? PAPER_BRIGHT : "#d8ccb0", 1.15);
    brush.line(p1[0] + 1, p1[1] + 6, p2[0] - 1, p2[1] + 6);
