  // --- B. CHUNKY VIBRAM-STYLE LUGGED RUBBER OUTSOLE (Forepart) ---
  let lugTop = [[130, 806], [190, 844], [296, 880], [416, 900], [525, 892]];
  let lugBot = [[134, 818], [182, 856], [258, 892], [348, 914], [440, 916], [525, 898]];

  // Draw 10 heavy 3D rubber lug teeth along the forepart sole edge
  let numLugs = 10;
  for (let i = 0; i < numLugs; i++) {
    let tA = i / numLugs;
    let tB = (i + 0.68) / numLugs;
    let tC = (i + 1.0) / numLugs;

    let topA = samplePolyline(lugTop, tA);
    let topB = samplePolyline(lugTop, tB);
    let topC = samplePolyline(lugTop, tC);
    let botA = samplePolyline(lugBot, tA);
    let botB = samplePolyline(lugBot, tB);

    // Protruding lug tooth polygon
    let tooth = [
      [topA[0], topA[1]],
      [botA[0] - 2, botA[1] + 8],
      [botB[0] - 1, botB[1] + 9],
      [topB[0], topB[1]]
    ];
    brush.noStroke();
    brush.wash(BLACK_DEEP, 235);
    drawShapePts(tooth, true, 0.05);
    brush.noWash();

    // Recessed notch between lugs (shows deep shadow & subtle scraped edge)
    brush.set("rotring", BLACK_DEEP, 1.3);
    drawShapePts(tooth, true, 0.05);
    brush.set("cpencil", "#bfb293", 0.75);
    brush.line(botA[0] - 1, botA[1] + 7, botB[0] - 1, botB[1] + 8);
    brush.line(topB[0], topB[1] + 2, topC[0], topC[1] + 2);
  }

  // --- C. STACKED LEATHER LOGGER/ENGINEER HEEL (5 Laminated Lifts + Rubber Cap) ---
  // Heel bounds: Top (644, 892)..(820, 824), Bottom (655, 956)..(820, 932)
  let heelLayers = 6;
  for (let l = 0; l <= heelLayers; l++) {
    let f = l / heelLayers;
    let lx1 = lerp(644, 655, f);
    let ly1 = lerp(892, 956, f);
    let lx2 = lerp(734, 740, f);
    let ly2 = lerp(854, 952, f);
    let lx3 = lerp(820, 820, f);
    let ly3 = lerp(824, 932, f);

    // Layer seam line
    brush.set("rotring", BLACK_DEEP, 1.35);
    brush.spline([[lx1, ly1], [lx2, ly2], [lx3, ly3]], 0.2);

    // Scraped light catch along each stacked leather lift seam
    if (l > 0 && l < heelLayers) {
      brush.set("cpencil", "#d0c3a4", 0.8);
      brush.spline([[lx1 + 2, ly1 - 1], [lx2, ly2 - 1], [lx3 - 3, ly3 - 1]], 0.2);
    }

    // Vertical compressed leather grain striations inside each heel lift
    if (l < heelLayers) {
      brush.set("rotring", BLACK_DEEP, 0.85);
      for (let s = 0.06; s <= 0.94; s += 0.06) {
        let ux = lerp(lx1, lx3, s);
        let uy = lerp(ly1, ly3, s) + sin(s * 180) * 6;
        brush.line(ux, uy, ux + 1, uy + 11);
      }
    }
  }

  // Heel breast (front vertical face of the heel under the arch)
  let heelBreast = [
    [644, 892], [655, 956], [628, 942], [620, 886]
  ];
  brush.noStroke();
  brush.wash(BLACK_DEEP, 245);
  drawShapePts(heelBreast, true, 0.05);
  brush.noWash();

  // Heavy lug teeth on the bottom rubber heel cap
  for (let k = 0; k < 5; k++) {
    let hx1 = lerp(656, 802, k / 5);
    let hy1 = lerp(956, 934, k / 5);
    let hx2 = lerp(656, 802, (k + 0.65) / 5);
    let hy2 = lerp(956, 934, (k + 0.65) / 5);
    brush.set("litho_crayon", BLACK_DEEP, 2.0);
    brush.line(hx1, hy1 + 5, hx2, hy2 + 5);
    brush.set("scraper", "#d8ccb0", 0.9);
    brush.line(hx1 + 2, hy1 + 2, hx2 - 2, hy2 + 2);
  }
}

