// =============================================================================
// UTILITY: SAMPLE POINT ALONG A POLYLINE AT NORMALIZED PARAMETER t in [0, 1]
// =============================================================================
function samplePolyline(pts, t) {
  t = constrain(t, 0, 1);
  let totalSegs = pts.length - 1;
  let scaled = t * totalSegs;
  let idx = min(floor(scaled), totalSegs - 1);
  let frac = scaled - idx;
  return [
    lerp(pts[idx][0], pts[idx + 1][0], frac),
    lerp(pts[idx][1], pts[idx + 1][1], frac)
  ];
}

