  buildDewBeads();

  // 2. Render multi-layered transparent watercolour glazes (batched by color)
  renderUnderGlazeWashes();
  renderChamberWatercolorBatches();

  // 3. Render savoyed hairpin pleats & recessed micro-cavities inside chambers
  renderHairpinFoldsAndCrevices();

  // 4. Render pulsing watercolour bevels along lamellae & branching crystal seams
  renderPulsingBandGlazes();
  renderBranchingCrystalVeins();

  // 5. Render the dense, folded core
  renderDenseFoldedCore();

  // 6. Render crisp graphite linework (2H, HB, 2B) holding every lamella & vein
  renderCrispGraphiteLamellae();

  // 7. Render wet cut-face micro-striations & faint dew beads on outer leaves
  renderWetCutSheenDetails();
  renderOuterDewBeads();

  noLoop();
}

// ============================================================================
// GEOMETRY & ANATOMY GENERATION
// ============================================================================

function buildVeinNetwork() {
  veinBranches = [];
  // 6 primary crystal-seam trunks radiating & curving from the core
  let baseAngles = [16, 74, 136, 198, 256, 316];

  for (let v = 0; v < 6; v++) {
    let startAngle = baseAngles[v] + random(-5, 5);
    let trunkPts = [];
    let curAngle = startAngle;

    for (let r = 52; r <= 910; r += 16) {
      let n = noise(v * 10 + r * 0.004, 1.7) - 0.5;
      curAngle += n * 3.2 + sin(r * 0.6 + v * 60) * 0.45;
      let w = map(r, 52, 880, 17.5, 4.5, true);
      if (r > 90 && r < 280) {
        w *= 1.22; // Swollen vascular trunk in inner-mid zone
      }
      let x = cx + r * cos(curAngle);
      let y = cy + r * sin(curAngle);
      trunkPts.push({ x, y, r, angle: curAngle, w });
    }
    veinBranches.push({ tier: 1, pts: trunkPts });

    // Spawn 2 secondary branches per primary trunk
    let forkIndices = [
      floor( random(7, 11) ),
      floor( random(15, 21) )
    ];
    for (let f = 0; f < 2; f++) {
      let idx = forkIndices[f];
      let origin = trunkPts[idx];
      let side = (f === 0 ? 1 : -1) * (v % 2 === 0 ? 1 : -1);
      let brAngle = origin.angle + side * random(19, 28);
      let secPts = [];
      let startW = origin.w * 0.72;

      for (let r = origin.r; r <= 870; r += 16) {
        let t = (r - origin.r) / (870 - origin.r);
        let n = noise(v * 20 + f * 7 + r * 0.005, 4.3) - 0.5;
        brAngle += n * 3.6 + side * (1 - t) * 0.65;
        let w = startW * pow(1 - t * 0.82, 1.35);
        let x = cx + r * cos(brAngle);
        let y = cy + r * sin(brAngle);
        secPts.push({ x, y, r, angle: brAngle, w });
      }
      veinBranches.push({ tier: 2, pts: secPts });

      // Spawn a tertiary crystal seamlet from the secondary branch
      let tertIdx = floor(random(5, min(11, secPts.length - 4)));
      if (secPts[tertIdx]) {
        let tOrigin = secPts[tertIdx];
        let tSide = -side;
        let tAngle = tOrigin.angle + tSide * random(15, 23);
        let tertPts = [];
        let tStartW = tOrigin.w * 0.68;
        let maxR = min(890, tOrigin.r + random(240, 380));

        for (let r = tOrigin.r; r <= maxR; r += 16) {
          let tt = (r - tOrigin.r) / (maxR - tOrigin.r);
          tAngle += (noise(v * 33 + r * 0.007, f * 13) - 0.5) * 4.0;
          let w = max(2.2, tStartW * (1 - tt * 0.85));
          let x = cx + r * cos(tAngle);
          let y = cy + r * sin(tAngle);
          tertPts.push({ x, y, r, angle: tAngle, w });
        }
        veinBranches.push({ tier: 3, pts: tertPts });
      }
    }
  }
}

// Fast lookup of distance from (x, y) to nearest crystal-seam vein edge
function getVeinProximity(x, y, r) {
  let minClearance = 9999;
  let nearestVein = null;

  for (let b = 0; b < veinBranches.length; b++) {
    let br = veinBranches[b];
    let pts = br.pts;
    if (r < pts[0].r - 20 || r > pts[pts.length - 1].r + 20) continue;

    // Approximate index by radius step (16px)
    let approxIdx = floor((r - pts[0].r) / 16);
    let i0 = max(0, approxIdx - 2);
    let i1 = min(pts.length - 1, approxIdx + 2);

    for (let i = i0; i <= i1; i++) {
      let p = pts[i];
      let d = dist(x, y, p.x, p.y);
      let clearance = d - p.w * 0.55;
      if (clearance < minClearance) {
        minClearance = clearance;
        nearestVein = { branch: br, pt: p, d, clearance };
      }
    }
  }
  return { minClearance, nearestVein };
}

function buildConcentricShells() {
  rings = [];
  chamberSectors = [];

  // Initialize inner boundary around the dense core
  let curR = new Array(N_THETA);
  for (let i = 0; i < N_THETA; i++) {
    let th = i * 2;
    let lobe5 = 5.5 * cos(th * 5 + 25) + 3.5 * sin(th * 3 - 40);
    let n = (noise(cos(th) * 1.4 + 5, sin(th) * 1.4 + 5) - 0.5) * 14;
    curR[i] = 66 + lobe5 + n;
  }

  for (let k = 0; k < N_RINGS; k++) {
    let rIn = new Array(N_THETA);
    let rOut = new Array(N_THETA);
    let isMidrib = new Array(N_THETA).fill(false);

    // Phyllotactic leaf centers for this ring (golden angle 137.508 deg)
    let numArcs = k < 5 ? 1 : (k < 15 ? 2 : 3);
    let arcCenters = [];
    for (let m = 0; m < numArcs; m++) {
      arcCenters.push((k * 137.508 + m * (360 / numArcs)) % 360);
    }

    // Ring color harmony (pulsing mineral bands)
    let harmony = getRingHarmony(k);

    for (let i = 0; i < N_THETA; i++) {
      let th = i * 2;
      rIn[i] = curR[i];

      // Determine midrib swelling along phyllotactic leaf arcs
      let maxSwell = 0;
      for (let m = 0; m < arcCenters.length; m++) {
        let dAng = abs(((th - arcCenters[m] + 540) % 360) - 180);
        let span = k < 6 ? 48 : (k < 16 ? 38 : 30);
        if (dAng < span) {
          let s = pow(cos((dAng / span) * 90), 2.2);
          if (s > maxSwell) maxSwell = s;
        }
      }

      let baseBlade = 6.2 + k * 0.15 + 1.8 * sin(th * (10 + (k % 5) * 2) + k * 37);
      let midribExtra = maxSwell * (11.5 + k * 0.52);
      if (maxSwell > 0.35) isMidrib[i] = true;

      let lamellaW = baseBlade + midribExtra;
      rOut[i] = rIn[i] + lamellaW;
    }

    // Compute chamber gap to next ring
    let nextR = new Array(N_THETA);
    for (let i = 0; i < N_THETA; i++) {
      let th = i * 2;
      let rAvg = rOut[i];
      let x = cx + rAvg * cos(th);
      let y = cy + rAvg * sin(th);

      // Check proximity to branching crystal-seam veins (geode suture pinch)
      let vp = getVeinProximity(x, y, rAvg);
      let veinPinch = 0;
      if (vp.minClearance < 26) {
        let tPinch = constrain(1 - vp.minClearance / 26, 0, 1);
        veinPinch = -tPinch * (3.5 + k * 0.18);
      }

      // Chamber opens into folded pockets between midribs, tightens behind midribs
      let wave = 0.5 + 0.5 * sin(th * (5 + (k % 4)) + k * 53);
      let n = noise(cos(th) * 2.0 + k * 0.35, sin(th) * 2.0 + k * 0.35);
      let gap = (8.5 + k * 0.52) * (0.45 + 0.65 * wave * n);
      if (isMidrib[i]) gap *= 0.62;

      nextR[i] = max(rOut[i] + 3.8, rOut[i] + gap + veinPinch);
    }

    // Gentle angular smoothing on nextR so shells propagate like natural agate/leaves
    for (let pass = 0; pass < 2; pass++) {
      let temp = new Array(N_THETA);
      for (let i = 0; i < N_THETA; i++) {
        let im1 = (i - 1 + N_THETA) % N_THETA;
        let ip1 = (i + 1) % N_THETA;
        temp[i] = 0.22 * nextR[im1] + 0.56 * nextR[i] + 0.22 * nextR[ip1];
        temp[i] = max(rOut[i] + 3.5, temp[i]);
      }
      nextR = temp;
    }

    rings.push({
      k,
      rIn,
      rOut,
      nextR,
      isMidrib,
      arcCenters,
      harmony
    });

    curR = nextR;
  }

  // Partition each ring's chamber into contiguous sectors split by the crystal-seam veins
  for (let k = 0; k < N_RINGS - 1; k++) {
    let ring = rings[k];
    let inVein = new Array(N_THETA);

    for (let i = 0; i < N_THETA; i++) {
      let th = i * 2;
      let rMid = 0.5 * (ring.rOut[i] + ring.nextR[i]);
      let x = cx + rMid * cos(th);
      let y = cy + rMid * sin(th);
      let vp = getVeinProximity(x, y, rMid);
      inVein[i] = vp.minClearance < 1.2;
    }

    // Extract contiguous non-vein angular segments (max 14 steps = 28 degrees per polygon)
    let i = 0;
    while (i < N_THETA) {
      if (inVein[i]) {
        i++;
        continue;
      }
      let startI = i;
      while (i < N_THETA && !inVein[i] && (i - startI) < 13) {
        i++;
      }
      let endI = i - 1;
      if (endI - startI >= 2) {
        chamberSectors.push({
          k,
          startI,
          endI,
          harmony: ring.harmony
        });
      }
    }
  }
}

function getRingHarmony(k) {
  // Outer rind (deep violet-black & mineral earth-aubergine)
  if (k >= 22) {
    return {
      zone: "rind",
      underCol: k % 2 === 0 ? PALETTE.earthCaput : PALETTE.ameDeep,
      midCol: k % 2 === 0 ? PALETTE.rindPlum : PALETTE.magDeep,
      deepCol: k >= 25 ? PALETTE.rindBlack : PALETTE.rindDark,
      bevelCol: k % 3 === 0 ? PALETTE.earthTaupe : PALETTE.ameMid,
      skinCol: PALETTE.rindPlum
    };
  }
  // Middle pulsing bands (magenta, amethyst, milky lavender, muted earth)
  let band = k % 5;
  if (band === 0) {
    return {
      zone: "magenta",
      underCol: PALETTE.lavMilky,
      midCol: PALETTE.magBright,
      deepCol: PALETTE.magDeep,
      bevelCol: PALETTE.lavPale,
      skinCol: PALETTE.magMid
    };
  } else if (band === 1) {
    return {
      zone: "amethyst",
      underCol: PALETTE.lavCool,
      midCol: PALETTE.ameMid,
      deepCol: PALETTE.rindDark,
      bevelCol: PALETTE.lavMilky,
      skinCol: PALETTE.ameDeep
    };
  } else if (band === 2) {
    return {
      zone: "lavender",
      underCol: PALETTE.lavPale,
      midCol: PALETTE.lavCool,
      deepCol: PALETTE.ameDeep,
      bevelCol: PALETTE.paperBright,
      skinCol: PALETTE.magBright
    };
  } else if (band === 3) {
    return {
      zone: "earth_magenta",
      underCol: PALETTE.earthBone,
      midCol: PALETTE.earthUmber,
      deepCol: PALETTE.earthCaput,
      bevelCol: PALETTE.earthTaupe,
      skinCol: PALETTE.magMid
    };
  } else {
    return {
      zone: "deep_amethyst",
      underCol: PALETTE.earthTaupe,
      midCol: PALETTE.ameLight,
      deepCol: PALETTE.rindPlum,
      bevelCol: PALETTE.lavMilky,
      skinCol: PALETTE.ameMid
    };
  }
}

function buildCoreAnatomy() {
  coreFolds = [];
  // 18 tightly convoluted embryonic leaf folds & pith islands inside r < 66
  let ringsCore = [
    { r: 14, count: 3, thick: 5.5 },
    { r: 29, count: 5, thick: 6.8 },
    { r: 46, count: 6, thick: 7.5 },
    { r: 60, count: 6, thick: 8.2 }
  ];

  for (let c = 0; c < ringsCore.length; c++) {
    let rc = ringsCore[c];
    for (let j = 0; j < rc.count; j++) {
      let a0 = j * (360 / rc.count) + c * 37 + random(-8, 8);
      let span = (360 / rc.count) * 0.76;
      let ptsInner = [];
      let ptsOuter = [];
      let ptsSpine = [];

      for (let s = 0; s <= 10; s++) {
        let t = s / 10;
        let a = a0 - span * 0.5 + span * t;
        let taper = sin(t * 180);
        let wave = 3.2 * sin(t * 360 + j * 55 + c * 90);
        let rMid = rc.r + wave;
        let halfW = rc.thick * 0.5 * (0.25 + 0.75 * taper);

        ptsInner.push([cx + (rMid - halfW) * cos(a), cy + (rMid - halfW) * sin(a)]);
        ptsOuter.push([cx + (rMid + halfW) * cos(a), cy + (rMid + halfW) * sin(a)]);
        ptsSpine.push([cx + rMid * cos(a), cy + rMid * sin(a)]);
      }

      coreFolds.push({
        tier: c,
        ptsInner,
        ptsOuter,
        ptsSpine
      });
    }
  }
}

function buildDewBeads() {
  dewBeads = [];
  // Faint dew of moisture beads along the outer leaves (r between 430 and 790)
  let numClusters = 15;
  for (let c = 0; c < numClusters; c++) {
    let baseAng = c * (360 / numClusters) + random(-10, 10);
    let baseR = random(450, 760);

    // Main bead in cluster
    let mainRad = random(5.5, 11.5);
    addDewBeadIfValid(baseR, baseAng, mainRad);

    // 1 to 3 smaller satellite moisture beads nearby along the leaf contour
    let numSat = floor(random(1, 4));
    for (let s = 0; s < numSat; s++) {
      let satAng = baseAng + (s === 0 ? 1 : -1) * random(1.8, 5.5);
      let satR = baseR + random(-22, 22);
      let satRad = random(2.4, 5.2);
      addDewBeadIfValid(satR, satAng, satRad);
    }
  }
}

function addDewBeadIfValid(r, ang, rad) {
  let x = cx + r * cos(ang);
  let y = cy + r * sin(ang);
  if (x > 55 && x < 1145 && y > 55 && y < 1145) {
    dewBeads.push({ x, y, r: rad, ang });
  }
}

// ============================================================================
// WATERCOLOUR GLAZE RENDERING (BATCHED FOR PERFORMANCE & LUSH BLEED)
// ============================================================================

function drawSafePolygon(pts, curvature = 0.25) {
  if (!pts || pts.length < 4) return;
  let clean = [pts[0]];
  for (let i = 1; i < pts.length; i++) {
    if (dist(pts[i][0], pts[i][1], clean[clean.length - 1][0], clean[clean.length - 1][1]) > 2.0) {
      clean.push(pts[i]);
    }
  }
  if (clean.length < 4) return;

  brush.beginShape(curvature);
  for (let i = 0; i < clean.length; i++) {
    brush.vertex(clean[i][0], clean[i][1]);
  }
  brush.endShape(true);
}

function getSectorPolygonPoints(sec, insetRatio = 0.0) {
  let ring = rings[sec.k];
  let pts = [];

  for (let i = sec.startI; i <= sec.endI; i++) {
    let th = i * 2;
    let r1 = ring.rOut[i];
    let r2 = ring.nextR[i];
    let r = lerp(r1, r2, insetRatio);
    pts.push([cx + r * cos(th), cy + r * sin(th)]);
  }
  for (let i = sec.endI; i >= sec.startI; i--) {
    let th = i * 2;
    let r1 = ring.rOut[i];
    let r2 = ring.nextR[i];
    let r = lerp(r2, r1, insetRatio);
    pts.push([cx + r * cos(th), cy + r * sin(th)]);
  }
  return pts;
}

function renderUnderGlazeWashes() {
  brush.noStroke();
  brush.fillBleed(0.24, "out");
  brush.fillTexture(0.58, 0.35);

  // Batch 1: Milky Lavender & Mineral Earth broad atmospheric glazes on outer-mid zones
  // Leaving the wet-sheen diagonal & crystal veins untouched as bare paper
  let lavZones = [];
  let earthZones = [];

  for (let k = 2; k < N_RINGS - 1; k += 2) {
    let ring = rings[k];
    for (let s = 0; s < 6; s++) {
      let startI = (s * 30 + k * 7) % N_THETA;
      let span = 12;
      let pts = [];
      for (let d = 0; d <= span; d += 2) {
        let idx = (startI + d) % N_THETA;
        let th = idx * 2;
        let r = ring.rIn[idx] + 2;
        pts.push([cx + r * cos(th), cy + r * sin(th)]);
      }
      for (let d = span; d >= 0; d -= 2) {
        let idx = (startI + d) % N_THETA;
        let th = idx * 2;
        let r = ring.nextR[idx] - 2;
        pts.push([cx + r * cos(th), cy + r * sin(th)]);
      }
      if ((k + s) % 3 === 0) {
        earthZones.push(pts);
      } else {
        lavZones.push(pts);
      }
    }
  }

  brush.fill(PALETTE.lavMilky, 42);
  for (let i = 0; i < lavZones.length; i++) {
    drawSafePolygon(lavZones[i], 0.3);
  }

  brush.fill(PALETTE.earthTaupe, 40);
  for (let i = 0; i < earthZones.length; i++) {
    drawSafePolygon(earthZones[i], 0.3);
  }
  brush.noFill();
}

function renderChamberWatercolorBatches() {
  // Group chamber sectors by color batch to keep watercolor fill count ~260 polygons total
  let batches = {
    lavCool: { col: PALETTE.lavCool, alpha: 62, bleed: 0.18, polys: [] },
    earthUmber: { col: PALETTE.earthUmber, alpha: 66, bleed: 0.18, polys: [] },
    earthCaput: { col: PALETTE.earthCaput, alpha: 76, bleed: 0.16, polys: [] },
    ameMid: { col: PALETTE.ameMid, alpha: 74, bleed: 0.18, polys: [] },
    ameDeep: { col: PALETTE.ameDeep, alpha: 84, bleed: 0.15, polys: [] },
    magBright: { col: PALETTE.magBright, alpha: 76, bleed: 0.2, polys: [] },
    magDeep: { col: PALETTE.magDeep, alpha: 86, bleed: 0.16, polys: [] },
    rindPlum: { col: PALETTE.rindPlum, alpha: 92, bleed: 0.15, polys: [] },
    rindDark: { col: PALETTE.rindDark, alpha: 102, bleed: 0.14, polys: [] },
    rindBlack: { col: PALETTE.rindBlack, alpha: 118, bleed: 0.12, polys: [] }
  };

  for (let idx = 0; idx < chamberSectors.length; idx++) {
    let sec = chamberSectors[idx];
    let poly = getSectorPolygonPoints(sec, 0.04);
    let z = sec.harmony.zone;

    // Assign to primary mid-glaze batch
    if (z === "rind") {
      if (sec.k >= 26) {
        batches.rindBlack.polys.push(poly);
      } else if (sec.k % 2 === 0) {
        batches.rindDark.polys.push(poly);
      } else {
        batches.rindPlum.polys.push(poly);
      }
    } else if (z === "magenta") {
      if (idx % 2 === 0) batches.magBright.polys.push(poly);
      else batches.magDeep.polys.push(poly);
    } else if (z === "amethyst") {
      if (idx % 2 === 0) batches.ameMid.polys.push(poly);
      else batches.ameDeep.polys.push(poly);
    } else if (z === "lavender") {
      if (idx % 3 === 0) batches.lavCool.polys.push(poly);
      else batches.ameMid.polys.push(poly);
    } else if (z === "earth_magenta") {
      if (idx % 2 === 0) batches.earthUmber.polys.push(poly);
      else batches.earthCaput.polys.push(poly);
    } else {
      if (idx % 2 === 0) batches.ameDeep.polys.push(poly);
      else batches.rindPlum.polys.push(poly);
    }
  }

  // Execute batched watercolor fills
  brush.noStroke();
  brush.fillTexture(0.62, 0.44);

  let keys = Object.keys(batches);
  for (let b = 0; b < keys.length; b++) {
    let batch = batches[keys[b]];
    if (batch.polys.length === 0) continue;
    brush.fillBleed(batch.bleed, "out");
    brush.fill(batch.col, batch.alpha);
    // Sub-sample if needed to stay well within render budget while keeping full coverage
    for (let p = 0; p < batch.polys.length; p++) {
      drawSafePolygon(batch.polys[p], 0.22);
    }
  }
  brush.noFill();
}

// ============================================================================
// SAVOYED HAIRPIN PLEATS & RECESSED CAVITIES INSIDE CHAMBERS
// ============================================================================

function renderHairpinFoldsAndCrevices() {
  // Inside every chamber sector, a serpentine / hairpin folded sub-lamella weaves
  // back and forth, with deep violet-black & magenta pockets in its alternating hollows
  // and a reserved bare-paper / pale-lavender cut ridge!

  for (let idx = 0; idx < chamberSectors.length; idx++) {
    let sec = chamberSectors[idx];
    let ring = rings[sec.k];
    let span = sec.endI - sec.startI;
    if (span < 3) continue;

    let freq = 28 + (sec.k % 5) * 6;
    let phase = sec.k * 47 + sec.startI * 13;

    // 1. Paint deep recessed crevice pockets in alternating hollows of the fold
    let deepCol = sec.k >= 21 ? PALETTE.rindBlack : (sec.k % 2 === 0 ? PALETTE.rindDark : PALETTE.magDeep);
    brush.noStroke();
    brush.wash(deepCol, sec.k >= 21 ? 165 : 135);

    let step = 2;
    for (let i = sec.startI; i < sec.endI - 1; i += step) {
      let iNext = min(sec.endI, i + step);
      let th1 = i * 2;
      let th2 = iNext * 2;
      let gap1 = ring.nextR[i] - ring.rOut[i];
      let gap2 = ring.nextR[iNext] - ring.rOut[iNext];
      if (gap1 < 7 && gap2 < 7) continue;

      let s1 = sin(th1 * freq * 0.25 + phase);
      let s2 = sin(th2 * freq * 0.25 + phase);
      let rMid1 = 0.5 * (ring.rOut[i] + ring.nextR[i]) + s1 * gap1 * 0.22;
      let rMid2 = 0.5 * (ring.rOut[iNext] + ring.nextR[iNext]) + s2 * gap2 * 0.22;
      let foldW = clampVal(gap1 * 0.28, 3.2, 8.5);

      if (s1 >= 0) {
        // Inner pocket between rOut and the raised fold
        let pPocket = [
          [cx + (ring.rOut[i] + 1) * cos(th1), cy + (ring.rOut[i] + 1) * sin(th1)],
          [cx + (ring.rOut[iNext] + 1) * cos(th2), cy + (ring.rOut[iNext] + 1) * sin(th2)],
          [cx + (rMid2 - foldW * 0.45) * cos(th2), cy + (rMid2 - foldW * 0.45) * sin(th2)],
          [cx + (rMid1 - foldW * 0.45) * cos(th1), cy + (rMid1 - foldW * 0.45) * sin(th1)]
        ];
        drawSafePolygon(pPocket, 0.15);
      } else {
        // Outer pocket between the dipped fold and nextR
        let pPocket = [
          [cx + (rMid1 + foldW * 0.45) * cos(th1), cy + (rMid1 + foldW * 0.45) * sin(th1)],
          [cx + (rMid2 + foldW * 0.45) * cos(th2), cy + (rMid2 + foldW * 0.45) * sin(th2)],
          [cx + (ring.nextR[iNext] - 1) * cos(th2), cy + (ring.nextR[iNext] - 1) * sin(th2)],
          [cx + (ring.nextR[i] - 1) * cos(th1), cy + (ring.nextR[i] - 1) * sin(th1)]
        ];
        drawSafePolygon(pPocket, 0.15);
      }
    }
    brush.noWash();

    // 2. Reserve bare-paper / pale milky-lavender ridge along the meandering sub-lamella
    let foldRibbonPts = [];
    for (let i = sec.startI; i <= sec.endI; i++) {
      let th = i * 2;
      let gap = ring.nextR[i] - ring.rOut[i];
      if (gap < 9.5) continue;
      let s = sin(th * freq * 0.25 + phase);
      let rFold = 0.5 * (ring.rOut[i] + ring.nextR[i]) + s * gap * 0.22;
      foldRibbonPts.push([
        cx + rFold * cos(th),
        cy + rFold * sin(th),
        map(gap, 9.5, 32, 0.45, 1.15, true)
      ]);
    }

    if (foldRibbonPts.length >= 3) {
      // Crisp pale cut face of the meandering inner fold
      let ridgeCol = sec.k >= 23 ? PALETTE.lavCool : (sec.k % 3 === 0 ? PALETTE.lavPale : PALETTE.paper);
      brush.set("glaze_fine", ridgeCol, sec.k >= 23 ? 0.85 : 1.15);
      brush.spline(foldRibbonPts, 0.45);
    }
  }
}

// ============================================================================
// PULSING WATERCOLOUR BANDS & BRANCHING CRYSTAL-SEAM VEINS
// ============================================================================

function renderPulsingBandGlazes() {
  // Sweep translucent watercolour glazes along the margins of each lamella,
  // leaving the central spine of each lamella & midrib as reserved bare paper!
  for (let k = 0; k < N_RINGS; k++) {
    let ring = rings[k];
    let h = ring.harmony;

    // Break each ring into 4 arcs to vary glaze pressure & reserve wet sheen zones
    for (let a = 0; a < 4; a++) {
      let i0 = a * 45;
      let i1 = (a + 1) * 45;

      let bevelPts = [];
      let skinInPts = [];
      let skinOutPts = [];
      let crevicePts = [];

      for (let i = i0; i <= i1; i += 2) {
        let idx = i % N_THETA;
        let th = idx * 2;

        // Wet sheen diagonal (upper-left to lower-right catches strongest bare-paper reserve)
        let sheenFactor = 0.5 + 0.5 * cos((th - 135) * 2);
        let rIn = ring.rIn[idx];
        let rOut = ring.rOut[idx];
        let w = rOut - rIn;

        // Inner bevel (milky lavender or muted earth tone)
        let rBevel = rIn + w * 0.26;
        bevelPts.push([
          cx + rBevel * cos(th),
          cy + rBevel * sin(th),
          (1.1 - 0.45 * sheenFactor) * map(w, 6, 36, 0.5, 1.3, true)
        ]);

        // Inner & outer anthocyanin skin (magenta / amethyst)
        skinInPts.push([
          cx + (rIn + 1.2) * cos(th),
          cy + (rIn + 1.2) * sin(th),
          0.7 + 0.4 * sin(th * 6 + k * 20)
        ]);
        skinOutPts.push([
          cx + (rOut - 1.2) * cos(th),
          cy + (rOut - 1.2) * sin(th),
          0.7 + 0.4 * cos(th * 6 + k * 20)
        ]);

        // Deep crevice trough line
        let rCrev = 0.5 * (rOut + ring.nextR[idx]);
        crevicePts.push([
          cx + rCrev * cos(th),
          cy + rCrev * sin(th),
          0.65 + 0.45 * (1 - sheenFactor)
        ]);
      }

      // 1. Soft bevel glaze (milky lavender / earth bone / taupe)
      brush.set("glaze_soft", h.bevelCol, k >= 22 ? 0.9 : 0.7);
      brush.spline(bevelPts, 0.35);

      // 2. Pulsing magenta / amethyst skin glazes along both walls of the cut lamella
      brush.set("glaze_fine", h.skinCol, 0.85);
      brush.spline(skinInPts, 0.35);
      brush.set("glaze_fine", h.midCol, 0.8);
      brush.spline(skinOutPts, 0.35);

      // 3. Deep violet-black / dark plum crevice shadow in the recessed trough
      if (k < N_RINGS - 1) {
        brush.set("crevice_ink", h.deepCol, k >= 20 ? 1.25 : 0.9);
        brush.spline(crevicePts, 0.35);
      }
    }
  }

  // Subtle mineral granulation mist across the outer rind & deep amethyst zones
  for (let k = 16; k < N_RINGS; k += 3) {
    let ring = rings[k];
    let mistCol = k >= 23 ? PALETTE.rindDark : (k % 2 === 0 ? PALETTE.ameDeep : PALETTE.earthCaput);
    brush.set("mineral_mist", mistCol, 1.1);
    for (let i = 0; i < N_THETA; i += 12) {
      let th = i * 2;
      let r = ring.rOut[i];
      let x1 = cx + r * cos(th);
      let y1 = cy + r * sin(th);
      let x2 = cx + (r + 18) * cos(th + 8);
      let y2 = cy + (r + 18) * sin(th + 8);
      brush.line(x1, y1, x2, y2);
    }
  }
}

function renderBranchingCrystalVeins() {
  // Render the branching crystal-seam veins:
  // 1. Outer bleeding halo of magenta & amethyst where the vein meets the leaf chambers
  // 2. Milky-lavender & mineral-earth bevel along one wall
  // 3. Crisp bare-paper reserved spine down the middle of every crystal seam!

  for (let b = 0; b < veinBranches.length; b++) {
    let br = veinBranches[b];
    let pts = br.pts;
    if (pts.length < 3) continue;

    let leftHalo = [];
    let rightHalo = [];
    let bevelLine = [];
    let leftWall = [];
    let rightWall = [];
    let centerPoly = [];

    for (let i = 0; i < pts.length; i++) {
      let p = pts[i];
      // Normal vector perpendicular to radial/vein direction
      let nx = -sin(p.angle);
      let ny = cos(p.angle);
      let hw = p.w * 0.5;
      let press = map(p.w, 2.5, 20, 0.35, 1.25, true);

      leftHalo.push([p.x + nx * (hw + 2.2), p.y + ny * (hw + 2.2), press]);
      rightHalo.push([p.x - nx * (hw + 2.2), p.y - ny * (hw + 2.2), press]);
      bevelLine.push([p.x + nx * (hw * 0.55), p.y + ny * (hw * 0.55), press * 0.85]);

      leftWall.push([p.x + nx * hw, p.y + ny * hw, press * 0.9]);
      rightWall.push([p.x - nx * hw, p.y - ny * hw, press * 0.9]);
    }

    // Build clean bare-paper reserve polygon for primary & secondary crystal seams
    for (let i = 0; i < pts.length; i++) {
      let p = pts[i];
      let nx = -sin(p.angle);
      let ny = cos(p.angle);
      let hw = max(1.2, p.w * 0.44);
      centerPoly.push([p.x + nx * hw, p.y + ny * hw]);
    }
    for (let i = pts.length - 1; i >= 0; i--) {
      let p = pts[i];
      let nx = -sin(p.angle);
      let ny = cos(p.angle);
      let hw = max(1.2, p.w * 0.44);
      centerPoly.push([p.x - nx * hw, p.y - ny * hw]);
    }

    // Bare paper wet cut face of the crystal seam
    brush.noStroke();
    brush.wash(PALETTE.paper, 238);
    drawSafePolygon(centerPoly, 0.2);
    brush.noWash();

    // Bleeding magenta & amethyst outer skin along the crystal seam
    let haloCol1 = b % 2 === 0 ? PALETTE.magMid : PALETTE.ameMid;
    let haloCol2 = b % 2 === 0 ? PALETTE.ameDeep : PALETTE.magBright;
    brush.set("glaze_fine", haloCol1, br.tier === 1 ? 0.95 : 0.65);
    brush.spline(leftHalo, 0.35);
    brush.set("glaze_fine", haloCol2, br.tier === 1 ? 0.9 : 0.6);
    brush.spline(rightHalo, 0.35);

    // Milky lavender / mineral earth inner bevel inside the crystal seam
    let bevCol = br.tier === 1 ? PALETTE.earthBone : PALETTE.lavPale;
    brush.set("glaze_fine", bevCol, br.tier === 1 ? 0.75 : 0.45);
    brush.spline(bevelLine, 0.35);

    // Store wall polylines on branch for the crisp graphite pass
    br.leftWall = leftWall;
    br.rightWall = rightWall;
  }
}

// ============================================================================
// DENSE, FOLDED CORE RENDERING
// ============================================================================

function renderDenseFoldedCore() {
  // 1. Outer vascular bundle ring of the core (muted mineral earth & milky lavender)
  let coreRingPts = [];
  for (let i = 0; i < 36; i++) {
    let a = i * 10;
    let r = 62 + 4 * cos(a * 5 + 25) + 2.5 * sin(a * 3);
    coreRingPts.push([cx + r * cos(a), cy + r * sin(a)]);
  }
  brush.noStroke();
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.55, 0.4);
  brush.fill(PALETTE.earthBone, 65);
  drawSafePolygon(coreRingPts, 0.3);
  brush.noFill();

  // 2. Dark amethyst & magenta micro-crevices between the tightly folded core leaves
  for (let i = 0; i < coreFolds.length; i++) {
    let cf = coreFolds[i];
    let shadowCol = i % 2 === 0 ? PALETTE.ameDeep : PALETTE.magDeep;
    brush.set("crevice_ink", shadowCol, 0.85);
    brush.spline(cf.ptsOuter, 0.4);
  }

  // 3. Reserved bare-paper cut faces of the convoluted core folds
  for (let i = 0; i < coreFolds.length; i++) {
    let cf = coreFolds[i];
    let poly = cf.ptsInner.concat(cf.ptsOuter.slice().reverse());
    brush.noStroke();
    brush.wash(PALETTE.paper, 240);
    drawSafePolygon(poly, 0.25);
    brush.noWash();

    // Subtle milky lavender / mineral ochre bevel on each embryonic fold
    let tint = i % 3 === 0 ? PALETTE.earthBone : PALETTE.lavPale;
    brush.set("glaze_fine", tint, 0.55);
    brush.spline(cf.ptsInner, 0.4);
  }

  // 4. Vascular bundle dots (xylem/phloem ring at r ≈ 48..58)
  brush.set("2H", PALETTE.earthUmber, 0.75);
  for (let i = 0; i < 42; i++) {
    let a = i * (360 / 42) + random(-2, 2);
    let r = random(47, 59);
    let vx = cx + r * cos(a);
    let vy = cy + r * sin(a);
    brush.circle(vx, vy, random(1.1, 2.3), 0.25);
  }
}

// ============================================================================
// CRISP GRAPHITE LINEWORK HOLDING EACH LAMELLA & VEIN
// ============================================================================

function renderCrispGraphiteLamellae() {
  // "A crisp graphite line holds each lamella."
  // Trace both inner and outer cut walls of every lamella shell, every meandering
  // hairpin sub-lamella, every branching crystal-seam vein, and every core fold!

  // 1. Concentric lamellae & swollen crescentic midrib walls
  for (let k = 0; k < N_RINGS; k++) {
    let ring = rings[k];
    // Segment into 6 arcs around the head for natural hand-drawn pencil pressure
    for (let s = 0; s < 6; s++) {
      let iStart = s * 30;
      let iEnd = (s + 1) * 30;

      let innerWall = [];
      let outerWall = [];

      for (let i = iStart; i <= iEnd; i++) {
        let idx = i % N_THETA;
        let th = idx * 2;
        let rIn = ring.rIn[idx];
        let rOut = ring.rOut[idx];

        let pIn = 0.65 + 0.45 * sin(th * 4 + k * 19);
        let pOut = 0.75 + 0.45 * cos(th * 4 + k * 31);
        if (ring.isMidrib[idx]) {
          pIn *= 1.2;
          pOut *= 1.25;
        }

        innerWall.push([cx + rIn * cos(th), cy + rIn * sin(th), pIn]);
        outerWall.push([cx + rOut * cos(th), cy + rOut * sin(th), pOut]);
      }

      // Crisp 2H / HB graphite contour on inner wall
      brush.set("graphite_sharp", k % 2 === 0 ? PALETTE.graphHB : PALETTE.graph2H, 0.9);
      brush.spline(innerWall, 0.35);

      // Slightly bolder HB / 2B graphite contour on outer wall (shadow side of crevice)
      brush.set("HB", k >= 20 ? PALETTE.graph2B : PALETTE.graphHB, k >= 20 ? 0.72 : 0.58);
      brush.spline(outerWall, 0.35);
    }

    // Internal vascular bundle dots & fine 2H cross-contours inside swollen midribs
    brush.set("2H", PALETTE.graph2H, 0.45);
    for (let i = 0; i < N_THETA; i += 2) {
      if (!ring.isMidrib[i]) continue;
      let th = i * 2;
      let rIn = ring.rIn[i];
      let rOut = ring.rOut[i];
      let w = rOut - rIn;
      if (w > 15 && i % 4 === 0) {
        let rMid = 0.5 * (rIn + rOut);
        let vx = cx + rMid * cos(th);
        let vy = cy + rMid * sin(th);
        brush.circle(vx, vy, clampVal(w * 0.08, 1.0, 2.2), 0.2);
      }
    }
  }

  // 2. Crisp graphite contours holding every meandering hairpin fold inside the chambers
  for (let idx = 0; idx < chamberSectors.length; idx++) {
    let sec = chamberSectors[idx];
    let ring = rings[sec.k];
    let freq = 28 + (sec.k % 5) * 6;
    let phase = sec.k * 47 + sec.startI * 13;

    let wall1 = [];
    let wall2 = [];

    for (let i = sec.startI; i <= sec.endI; i++) {
      let th = i * 2;
      let gap = ring.nextR[i] - ring.rOut[i];
      if (gap < 8.5) continue;

      let s = sin(th * freq * 0.25 + phase);
      let rMid = 0.5 * (ring.rOut[i] + ring.nextR[i]) + s * gap * 0.22;
      let hw = clampVal(gap * 0.14, 1.6, 4.0);

      wall1.push([cx + (rMid - hw) * cos(th), cy + (rMid - hw) * sin(th), 0.75]);
      wall2.push([cx + (rMid + hw) * cos(th), cy + (rMid + hw) * sin(th), 0.85]);
    }

    if (wall1.length >= 3) {
      brush.set("graphite_sharp", PALETTE.graph2H, 0.78);
      brush.spline(wall1, 0.45);
      brush.set("graphite_sharp", PALETTE.graphHB, 0.85);
      brush.spline(wall2, 0.45);
    }
  }

  // 3. Crisp graphite walls & longitudinal crystal striations along branching veins
  for (let b = 0; b < veinBranches.length; b++) {
    let br = veinBranches[b];
    if (!br.leftWall || br.leftWall.length < 3) continue;

    let wMult = br.tier === 1 ? 1.05 : (br.tier === 2 ? 0.85 : 0.68);
    brush.set("graphite_sharp", PALETTE.graphHB, wMult);
    brush.spline(br.leftWall, 0.35);
    brush.set("graphite_sharp", PALETTE.graph2H, wMult * 0.92);
    brush.spline(br.rightWall, 0.35);

    // Fine internal crystal-seam striations inside tier 1 & 2 veins
    if (br.tier <= 2) {
      let stria = [];
      for (let i = 0; i < br.pts.length; i += 2) {
        let p = br.pts[i];
        let nx = -sin(p.angle);
        let ny = cos(p.angle);
        stria.push([p.x + nx * (p.w * 0.12), p.y + ny * (p.w * 0.12), 0.55]);
      }
      if (stria.length >= 3) {
        brush.set("2H", PALETTE.graph2H, 0.38);
        brush.spline(stria, 0.3);
      }
    }
  }

  // 4. Crisp graphite linework holding each embryonic fold in the central core
  for (let i = 0; i < coreFolds.length; i++) {
    let cf = coreFolds[i];
    brush.set("graphite_sharp", PALETTE.graphHB, 0.88);
    brush.spline(cf.ptsInner, 0.4);
    brush.set("graphite_sharp", PALETTE.graph2B, 0.92);
    brush.spline(cf.ptsOuter, 0.4);
  }
}

// ============================================================================
// WET CUT FACE SHEEN & OUTER MOISTURE DEW BEADS
// ============================================================================

function renderWetCutSheenDetails() {
  // Subtle diagonal knife-cut micro-striations in whisper-light 2H graphite across
  // the reserved bare-paper zones, enhancing the flat, wet, freshly-sliced illusion
  brush.set("2H", PALETTE.lavCool, 0.32);
  for (let s = 0; s < 95; s++) {
    let r = random(45, 760);
    let ang = random(360);
    let x = cx + r * cos(ang);
    let y = cy + r * sin(ang);
    let len = random(18, 52);
    // Knife slice direction (~ -32 degrees)
    let dx = len * cos(-32);
    let dy = len * sin(-32);
    brush.line(x - dx * 0.5, y - dy * 0.5, x + dx * 0.5, y + dy * 0.5);
  }
}

function renderOuterDewBeads() {
  // "A faint dew of moisture beads along the outer leaves."
  // Each droplet features:
  // 1. Cast shadow crescent on bottom-right (away from upper-left light)
  // 2. Dark refracted upper-left inner rim
  // 3. Luminous magenta/lavender caustic belly on lower-right
  // 4. Crisp 2H graphite meniscus contour
  // 5. Reserved bare-paper pinpoint specular highlight on upper-left!

  for (let i = 0; i < dewBeads.length; i++) {
    let d = dewBeads[i];
    let x = d.x;
    let y = d.y;
    let r = d.r;

    // 1. Cast shadow on bottom-right
    let shPts = [];
    for (let a = -35; a <= 125; a += 20) {
      let rad = r * (1.05 + 0.32 * sin(a - 45));
      shPts.push([x + r * 0.24 + rad * cos(a), y + r * 0.24 + rad * sin(a)]);
    }
    for (let a = 125; a >= -35; a -= 20) {
      shPts.push([x + r * 0.85 * cos(a), y + r * 0.85 * sin(a)]);
    }
    brush.noStroke();
    brush.wash(PALETTE.rindBlack, 145);
    drawSafePolygon(shPts, 0.25);

    // 2. Refracted interior body (translucent amethyst/magenta glow)
    let bodyPts = [];
    for (let a = 0; a < 360; a += 30) {
      let stretch = 1.0 + 0.08 * cos((a - d.ang) * 2);
      bodyPts.push([x + r * stretch * cos(a), y + r * stretch * sin(a)]);
    }
    brush.wash(PALETTE.ameDeep, 95);
    drawSafePolygon(bodyPts, 0.35);

    // 3. Lower-right caustic refraction crescent (glowing magenta -> milky lavender)
    let causticPts = [];
    for (let a = -20; a <= 110; a += 22) {
      causticPts.push([x + r * 0.82 * cos(a), y + r * 0.82 * sin(a)]);
    }
    for (let a = 110; a >= -20; a -= 22) {
      causticPts.push([x + r * 0.35 * cos(a), y + r * 0.35 * sin(a)]);
    }
    brush.wash(i % 2 === 0 ? PALETTE.magBright : PALETTE.lavMilky, 155);
    drawSafePolygon(causticPts, 0.25);

    // 4. Crisp reserved bare-paper specular highlight (upper-left of droplet)
    let hlX = x - r * 0.34;
    let hlY = y - r * 0.34;
    let hlR = max(1.3, r * 0.32);
    let hlPts = [];
    for (let a = 0; a < 360; a += 45) {
      let rx = hlR * (1.15 - 0.2 * sin(a));
      let ry = hlR * (0.85 + 0.15 * cos(a));
      hlPts.push([hlX + rx * cos(a - 40), hlY + ry * sin(a - 40)]);
    }
    brush.wash(PALETTE.paperBright, 252);
    drawSafePolygon(hlPts, 0.2);

    // Secondary micro-reflection pinpoint on opposite lower-right edge
    if (r > 5.0) {
      let secPts = [];
      let sx = x + r * 0.48;
      let sy = y + r * 0.48;
      for (let a = 0; a < 360; a += 60) {
        secPts.push([sx + 1.2 * cos(a), sy + 1.2 * sin(a)]);
      }
      brush.wash(PALETTE.lavPale, 220);
      drawSafePolygon(secPts, 0.15);
    }
    brush.noWash();

    // 5. Delicate 2H / HB graphite meniscus ring holding the water bead
    brush.set("graphite_sharp", PALETTE.graphHB, 0.65);
    brush.circle(x, y, r, 0.08);
  }
}

function clampVal(v, lo, hi) {
  return max(lo, min(hi, v));
}

