function draw() {
  translate(-width / 2, -height / 2);

  // 1. Warm grey toned paper ground with subtle tooth, stains, and graphite dust
  drawWarmGreyPaper();

  // 2. Top-left scientific header & biomechanical axial torsion diagram
  drawHeaderAndTorsionDiagram();

  // 3. Top-right magnified detail plate (2.2x Head, Flattened Ears & Startled Eyes)
  drawMagnifiedHeadPlate(790, 38, 362, 152);

  // 4. The 5 Old Chronophotographic Plates & Smudged Ruled Measurement Grids
  const fy = 205, fh = 690, fw = 212;
  for (let i = 0; i < 5; i++) {
    let fx = 48 + i * 224;
    drawOldPlateAndGrid(fx, fy, fw, fh, POSES[i], i);
  }

  // 5. Parabolic exposure trajectories & faint ghosting trails bridging between frames
  drawExposureGhostTrails(fy, fh, fw);

  // 6. The 5 Hyperreal Twisting Striped Cats (frame by frame, upside-down to feet-first)
  for (let i = 0; i < 5; i++) {
    drawHyperrealCat(POSES[i], i);
  }

  // 7. Foreground plate-edge emulsion overlaps, measurement callouts, and frame clamps
  for (let i = 0; i < 5; i++) {
    let fx = 48 + i * 224;
    drawPlateForegroundAccents(fx, fy, fw, fh, POSES[i], i);
  }

  // 8. Lower chronograph tuning-fork wave strip & angular velocity graph
  drawChronographStrip(48, 914, 1104, 114);

  // 9. Bottom margin: Densitometric value scale, scientific notes & 2.8x Magnified Splayed Paw Study
  drawBottomMarginStudies();

  noLoop();
}

