function drawWarmGreyPaper() {
  background(PALETTE.paperBase);

  // Broad warm and cool paper tone variations
  brush.noStroke();
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.55, 0.2);

  brush.fill(PALETTE.paperWarm, 45);
  brush.rect(60, 50, 1080, 1100, "corner");

  brush.fill(PALETTE.paperCool, 38);
  brush.rect(30, 180, 1140, 740, "corner");

  // Aged border darkening around edges of the 1200x1200 sheet
  brush.fill(PALETTE.paperDark, 42);
  brush.rect(0, 0, 1200, 32, "corner");
  brush.rect(0, 1168, 1200, 32, "corner");
  brush.rect(0, 0, 32, 1200, "corner");
  brush.rect(1168, 0, 32, 1200, "corner");
  brush.noFill();

  // Horizontal laid-paper grain lines across the warm grey sheet
  brush.hatchStyle("2H", PALETTE.paperCool, 0.25);
  brush.hatch(9, 0, { rand: 0.08 });
  brush.noStroke();
  brush.rect(18, 18, 1164, 1164, "corner");
  brush.noHatch();

  // Subtle diagonal graphite dust and artist studio smudges in margins
  brush.set("stump_smudge", PALETTE.paperDark, 1.2);
  for (let i = 0; i < 36; i++) {
    let sx = random(30, 1170);
    let sy = random() < 0.5 ? random(20, 200) : random(900, 1180);
    brush.line(sx, sy, sx + random(-60, 60), sy + random(-18, 18));
  }

  // Outer ruled draughtsman sheet border
  brush.set("2H", PALETTE.graphite2B, 0.45);
  brush.line(24, 24, 1176, 24);
  brush.line(1176, 24, 1176, 1176);
  brush.line(1176, 1176, 24, 1176);
  brush.line(24, 1176, 24, 24);

  brush.set("2H", PALETTE.graphiteHB, 0.25);
  brush.line(30, 30, 1170, 30);
  brush.line(1170, 30, 1170, 1170);
  brush.line(1170, 1170, 30, 1170);
  brush.line(30, 1170, 30, 30);
}

