// 2. HEADER & BIOMECHANICAL AXIAL TORSION DIAGRAM
// ============================================================================
function drawHeaderAndTorsionDiagram() {
  // Title inscriptions
  drawGlyphText("PL. XIV - CHRONOPHOTOGRAPHIE : CHUTE DU CHAT (MAREY 1894)", 48, 44, 11, PALETTE.graphite6B, 0.38);
  drawGlyphText("SEQUENCE HORIZONTALE A 1/25 SEC - ROTATION AXIALE DE 180° SANS APPUI", 48, 63, 7.5, PALETTE.graphite2B, 0.28);

  // Ruled divider line
  brush.set("2H", PALETTE.graphite2B, 0.35);
  brush.line(48, 78, 768, 78);
  brush.set("2H", PALETTE.silverLight, 0.25);
  brush.line(48, 80, 768, 80);

  // Sub-box for kinematic torsion cross-sections aligned with the 5 frames
  drawGlyphText("SCHEMA DU COUPLE DE TORSION (CYLINDRES ANTERIEUR A ET POSTERIEur B)", 48, 88, 6.5, PALETTE.graphite2B, 0.24);

  // Horizontal axis line for the 5 torsion diagrams
  let axisY = 142;
  brush.set("2H", PALETTE.graphiteHB, 0.28);
  brush.line(56, axisY, 760, axisY);

  const diagLabels = ["180°", "110°", "65°", "18°", "0°"];
  for (let i = 0; i < 5; i++) {
    let dx = 115 + i * 142;
    let p = POSES[i];

    // Crosshair
    brush.set("2H", PALETTE.graphiteHB, 0.22);
    brush.line(dx, axisY - 36, dx, axisY + 36);

    // Posterior cylinder ellipse (dashed/shaded)
    brush.set("2H", PALETTE.graphite2B, 0.32);
    brush.circle(dx - 12, axisY, 22, 0.08);
    let postAng = p.torsionPost - 90;
    let px1 = dx - 12 + cos(postAng) * 26;
    let py1 = axisY + sin(postAng) * 26;
    let px2 = dx - 12 + cos(postAng + 42) * 26;
    let py2 = axisY + sin(postAng + 42) * 26;
    brush.set("HB", PALETTE.graphite2B, 0.45);
    brush.line(dx - 12, axisY, px1, py1);
    brush.line(dx - 12, axisY, px2, py2);

    // Anterior cylinder ellipse (highlighted)
    brush.set("2B", PALETTE.graphite6B, 0.45);
    brush.circle(dx + 12, axisY, 20, 0.06);
    let antAng = p.torsionAnt - 90;
    let ax1 = dx + 12 + cos(antAng - 20) * 28;
    let ay1 = axisY + sin(antAng - 20) * 28;
    let ax2 = dx + 12 + cos(antAng + 20) * 28;
    let ay2 = axisY + sin(antAng + 20) * 28;
    brush.set("2B", PALETTE.graphite6B, 0.55);
    brush.line(dx + 12, axisY, ax1, ay1);
    brush.line(dx + 12, axisY, ax2, ay2);
    brush.set("chalk_white", PALETTE.chalkWhite, 0.5);
    brush.circle(dx + 12, axisY, 4, 0.05);

    // Rotation torsion arc arrow
    if (i < 4) {
      brush.set("graphite_needle", PALETTE.graphite4B, 0.4);
      brush.arc(dx + 12, axisY, 31, -90, -10);
    }

    drawGlyphText("FIG." + p.id + " (" + diagLabels[i] + ")", dx - 28, axisY + 38, 5.8, PALETTE.graphite4B, 0.22);
  }
}

// ============================================================================
// 3. TOP-RIGHT MAGNIFIED DETAIL PLATE (2.2x HEAD, FLATTENED EARS, EYES)
// ============================================================================
function drawMagnifiedHeadPlate(x, y, w, h) {
  // Irregular dark glass plate ground
  let pts = buildIrregularRect(x, y, w, h, 3.5, 7);
  brush.noStroke();
  brush.wash(PALETTE.plateDeep, 225);
  drawPolyShape(pts);
  brush.noWash();

  brush.fill(PALETTE.plateMid, 110);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.5, 0.35);
  brush.rect(x + 6, y + 6, w - 12, h - 12, "corner");
  brush.noFill();

  // Fine 5mm measurement grid inside the detail plate
  for (let gx = x + 12; gx < x + w - 8; gx += 16) {
    let isMaj = ((gx - (x + 12)) % 64 === 0);
    brush.set("2H", isMaj ? PALETTE.gridMajor : PALETTE.gridMinor, isMaj ? 0.3 : 0.18);
    brush.line(gx, y + 6, gx, y + h - 6);
  }
  for (let gy = y + 12; gy < y + h - 8; gy += 16) {
    let isMaj = ((gy - (y + 12)) % 64 === 0);
    brush.set("2H", isMaj ? PALETTE.gridMajor : PALETTE.gridMinor, isMaj ? 0.3 : 0.18);
    brush.line(x + 6, gy, x + w - 6, gy);
  }

  // Smudge over the grid behind the magnified head
  brush.set("stump_smudge", PALETTE.plateSmudge, 1.8);
  for (let i = 0; i < 14; i++) {
    brush.line(x + 80 + random(-30, 30), y + 30 + i * 7, x + w - 50 + random(-30, 30), y + 35 + i * 7);
  }

  // Render magnified hyperreal cat head (scale = 2.05) centered at (x + 185, y + 86)
  drawCatHeadDetailed(x + 185, y + 88, 51, -3, [0, 3.5], 1.28, true);

  // Irregular plate border strokes
  drawIrregularBorder(pts, PALETTE.graphite6B, PALETTE.silverLight);

  // Plate label
  drawGlyphText("DETAIL A : TETE ET OREILLES APLATIES (ECHELLE 2:1)", x + 10, y + 10, 6.2, PALETTE.silverLight, 0.24);
  drawGlyphText("REFLEXE VESTIBULAIRE - FIXATION OCULAIRE", x + 10, y + h - 14, 5.5, PALETTE.gridMajor, 0.2);
}

// ============================================================================
// 4. OLD PLATES & SMUDGED RULED MEASUREMENT GRIDS
// ============================================================================
function drawOldPlateAndGrid(fx, fy, fw, fh, pose, idx) {
  // Drop shadow on the warm grey paper under the glass plate edge
  brush.noStroke();
  brush.wash(PALETTE.paperDark, 85);
  brush.rect(fx + 4, fy + 5, fw, fh, "corner");
  brush.noWash();

  // Irregular plate polygon
  let platePts = buildIrregularRect(fx, fy, fw, fh, 3.8, 14);

  // Deep charcoal/silver-gelatin dark plate ground (high contrast against striped cat!)
  brush.noStroke();
  brush.wash(PALETTE.plateDeep, 232);
  drawPolyShape(platePts);
  brush.noWash();

  // Subtle silvery-grey chemical developer unevenness & tortillon smudges
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.6, 0.3);
  brush.fill(PALETTE.plateLight, 85);
  brush.circle(fx + fw * 0.5, pose.cy, fw * 0.46, 0.2);
  brush.fill(PALETTE.plateMid, 95);
  brush.rect(fx + 10, fy + 14, fw - 20, fh - 28, "corner");
  brush.noFill();

  // Vertical & horizontal ruled measurement grid (24px = 2cm minor, 120px = 10cm major)
  let gridStep = 24;
  for (let gx = fx + 14; gx <= fx + fw - 10; gx += gridStep) {
    let colIdx = Math.round((gx - (fx + 14)) / gridStep);
    let isMajor = (colIdx % 4 === 0);
    let col = isMajor ? PALETTE.gridMajor : PALETTE.gridMinor;
    let wt = isMajor ? 0.32 : 0.19;

    // Draw in segments so some segments are smudged/faint
    for (let gy = fy + 10; gy < fy + fh - 16; gy += 48) {
      let gy2 = min(fy + fh - 10, gy + 48);
      let dToCat = dist(gx, (gy + gy2) * 0.5, pose.fcx, pose.cy);
      let smudgeFactor = dToCat < 120 ? 0.65 : 1.0;
      brush.set("2H", col, wt * smudgeFactor);
      brush.line(gx + random(-0.4, 0.4), gy, gx + random(-0.4, 0.4), gy2);
    }
  }

  for (let gy = fy + 20; gy <= fy + fh - 12; gy += gridStep) {
    let rowIdx = Math.round((gy - (fy + 20)) / gridStep);
    let isMajor = (rowIdx % 5 === 0);
    let col = isMajor ? PALETTE.gridMajor : PALETTE.gridMinor;
    let wt = isMajor ? 0.34 : 0.19;

    for (let gx = fx + 8; gx < fx + fw - 12; gx += 44) {
      let gx2 = min(fx + fw - 8, gx + 44);
      brush.set("2H", col, wt);
      brush.line(gx, gy + random(-0.4, 0.4), gx2, gy + random(-0.4, 0.4));
    }

    // Metric scale numerals on major horizontal lines
    if (isMajor && (idx === 0 || idx === 4)) {
      let cmVal = rowIdx * 4;
      let tx = idx === 0 ? fx + 8 : fx + fw - 30;
      drawGlyphText(String(cmVal), tx, gy - 8, 5.5, PALETTE.gridBright, 0.22);
    }
  }

  // Graphite tortillon smudges across the ruled grid
  brush.set("stump_smudge", PALETTE.plateSmudge, 1.6);
  for (let s = 0; s < 18; s++) {
    let sx = fx + random(18, fw - 18);
    let sy = fy + random(30, fh - 30);
    let ang = random(-25, 25);
    let len = random(25, 65);
    brush.line(sx, sy, sx + cos(ang) * len, sy + sin(ang) * len);
  }

  // Vertical plumbline of the drop axis (Axe de Chute)
  brush.set("2H", PALETTE.silverMid, 0.26);
  for (let py = fy + 28; py < fy + fh - 35; py += 16) {
    brush.line(pose.fcx, py, pose.fcx, py + 9);
  }

  // Reception floor datum line near bottom of every frame (y = fy + 648 = 853)
  let floorY = fy + 648;
  brush.set("HB", PALETTE.silverLight, 0.42);
  brush.line(fx + 8, floorY, fx + fw - 8, floorY);
  brush.set("2H", PALETTE.gridMajor, 0.24);
  for (let hx = fx + 12; hx < fx + fw - 10; hx += 10) {
    brush.line(hx, floorY, hx - 6, floorY + 10);
  }

  // Release mechanism clamp indicator at the top of Frame I
  if (idx === 0) {
    drawReleaseApparatus(pose.fcx, fy + 26);
  }

  // Irregular old plate edge border, peeled emulsion corners, and silvering
  drawIrregularBorder(platePts, PALETTE.graphite6B, PALETTE.silverMid);
  drawPlateCornerDamage(fx, fy, fw, fh);
}

function drawReleaseApparatus(cx, topY) {
  // Electromagnetic / mechanical release jaws at top of Frame 1 from which cat was just dropped
  brush.set("2B", PALETTE.silverLight, 0.45);
  brush.line(cx - 48, topY, cx - 58, topY + 28);
  brush.line(cx - 58, topY + 28, cx - 38, topY + 42);
  brush.line(cx + 48, topY, cx + 58, topY + 28);
  brush.line(cx + 58, topY + 28, cx + 38, topY + 42);
  brush.set("2H", PALETTE.gridBright, 0.25);
  brush.line(cx - 70, topY, cx + 70, topY);
  drawGlyphText("DECLENCHEMENT T=0", cx - 44, topY + 4, 5.2, PALETTE.silverLight, 0.2);
}

// ============================================================================
// 5. FAINT GHOSTING TRAILS & PARABOLIC EXPOSURE BRIDGES BETWEEN FRAMES
// ============================================================================
function drawExposureGhostTrails(fy, fh, fw) {
  // 5A. Intra-frame vertical shutter ghosts (faint upper echo of the falling cat in each frame)
  for (let i = 0; i < 5; i++) {
    let p = POSES[i];
    drawCatGhostSilhouette(p, p.fcx, p.cy - 34, -10, 0.22);
    if (i > 0) {
      drawCatGhostSilhouette(p, p.fcx - 18, p.cy - 58, -18, 0.14);
    }
  }

  // 5B. Inter-frame horizontal/parabolic ghost bridges crossing right across the plate borders!
  for (let i = 0; i < 4; i++) {
    let p1 = POSES[i];
    let p2 = POSES[i + 1];

    // Interpolated mid-exposure pose bridging across the frame gap
    let midX = (p1.fcx + p2.fcx) * 0.5;
    let midY = (p1.cy + p2.cy) * 0.5 - 6;
    drawInterFrameGhostBridge(p1, p2, midX, midY);

    // Sweeping parabolic exposure streams connecting head, spine, paws, and tail across frames
    let tracks = [
      { a: [p1.fcx + p1.head[0], p1.cy + p1.head[1]], b: [p2.fcx + p2.head[0], p2.cy + p2.head[1]], w: 0.35, col: PALETTE.silverLight },
      { a: [p1.fcx + p1.midSpine[0], p1.cy + p1.midSpine[1]], b: [p2.fcx + p2.midSpine[0], p2.cy + p2.midSpine[1]], w: 0.42, col: PALETTE.silverMid },
      { a: [p1.fcx + p1.pelvis[0], p1.cy + p1.pelvis[1]], b: [p2.fcx + p2.pelvis[0], p2.cy + p2.pelvis[1]], w: 0.3, col: PALETTE.gridBright },
      { a: [p1.fcx + p1.nearFore.joints[3][0], p1.cy + p1.nearFore.joints[3][1]], b: [p2.fcx + p2.nearFore.joints[3][0], p2.cy + p2.nearFore.joints[3][1]], w: 0.28, col: PALETTE.silverLight },
      { a: [p1.fcx + p1.nearHind.joints[3][0], p1.cy + p1.nearHind.joints[3][1]], b: [p2.fcx + p2.nearHind.joints[3][0], p2.cy + p2.nearHind.joints[3][1]], w: 0.28, col: PALETTE.silverLight },
      { a: [p1.fcx + p1.tail[3][0], p1.cy + p1.tail[3][1]], b: [p2.fcx + p2.tail[3][0], p2.cy + p2.tail[3][1]], w: 0.25, col: PALETTE.gridMajor }
    ];

    for (let tr of tracks) {
      let mx = (tr.a[0] + tr.b[0]) * 0.5;
      let my = (tr.a[1] + tr.b[1]) * 0.5 + random(-14, 14);

      // Soft smudged exposure trail
      brush.set("stump_smudge", PALETTE.silverMid, 0.9);
      brush.spline([tr.a, [mx, my], tr.b], 0.45);

      // Crisp ghost trajectory filament
      brush.set("2H", tr.col, tr.w);
      brush.spline([tr.a, [mx, my - 3], tr.b], 0.45);

      // Secondary ghost echo line
      brush.set("2H", PALETTE.gridMinor, tr.w * 0.7);
      brush.spline([[tr.a[0], tr.a[1] - 8], [mx, my - 11], [tr.b[0], tr.b[1] - 8]], 0.45);
    }
  }
}

function drawCatGhostSilhouette(pose, gx, gy, rotDeg, strength) {
  push();
  translate(gx, gy);
  rotate(rotDeg);

  let p0 = [pose.pelvis[0], pose.pelvis[1]];
  let p1 = [pose.midSpine[0], pose.midSpine[1]];
  let p2 = [pose.chest[0], pose.chest[1]];
  let hd = [pose.head[0], pose.head[1]];

  // Translucent ghost wash
  brush.noStroke();
  brush.wash(PALETTE.silverMid, Math.round(strength * 95));
  brush.circle(p0[0], p0[1], pose.pelvis[2] * 0.9, 0.15);
  brush.circle(p1[0], p1[1], pose.midSpine[2] * 0.9, 0.15);
  brush.circle(p2[0], p2[1], pose.chest[2] * 0.9, 0.15);
  brush.circle(hd[0], hd[1], pose.head[2] * 0.85, 0.15);
  brush.noWash();

  // Ghostly spine, tail, and limb streaks
  brush.set("2H", PALETTE.silverLight, 0.24);
  brush.spline([p0, p1, p2, hd], 0.5);

  let tPts = pose.tail.map(pt => [pt[0], pt[1]]);
  brush.spline([p0, ...tPts], 0.5);

  // Ghostly fur motion arcs around body
  for (let k = 0; k < 14; k++) {
    let t = k / 13;
    let sx = lerp(p0[0], hd[0], t) + random(-15, 15);
    let sy = lerp(p0[1], hd[1], t) + random(-22, 22);
    brush.set("2H", PALETTE.gridBright, 0.18);
    brush.line(sx, sy, sx + random(-8, 8), sy - random(14, 28));
  }

  pop();
}

function drawInterFrameGhostBridge(p1, p2, mx, my) {
  // Faint double-exposure echo situated right across the border between Frame i and Frame i+1
  let pel = [(p1.pelvis[0] + p2.pelvis[0]) * 0.5, (p1.pelvis[1] + p2.pelvis[1]) * 0.5];
  let mid = [(p1.midSpine[0] + p2.midSpine[0]) * 0.5, (p1.midSpine[1] + p2.midSpine[1]) * 0.5];
  let chs = [(p1.chest[0] + p2.chest[0]) * 0.5, (p1.chest[1] + p2.chest[1]) * 0.5];
  let hd  = [(p1.head[0] + p2.head[0]) * 0.5, (p1.head[1] + p2.head[1]) * 0.5];

  push();
  translate(mx, my);

  brush.noStroke();
  brush.wash(PALETTE.silverLight, 24);
  brush.circle(mid[0], mid[1], 24, 0.25);
  brush.circle(chs[0], chs[1], 26, 0.25);
  brush.circle(hd[0], hd[1], 20, 0.25);
  brush.noWash();

  // Ghostly hatched silhouette contour
  brush.set("2H", PALETTE.silverLight, 0.22);
  brush.spline([
    [pel[0] - 18, pel[1]],
    [mid[0], mid[1] - 18],
    [chs[0], chs[1] - 18],
    [hd[0] + 18, hd[1]]
  ], 0.5);
  brush.spline([
    [pel[0] - 14, pel[1] + 16],
    [mid[0], mid[1] + 16],
    [chs[0], chs[1] + 18],
    [hd[0] + 12, hd[1] + 14]
  ], 0.5);

  // Faint tabby ghost stripes in the exposure trail
  for (let s = 0; s < 7; s++) {
    let f = s / 6;
    let gx = lerp(pel[0], chs[0], f);
    let gy = lerp(pel[1], chs[1], f);
    brush.set("2H", PALETTE.gridBright, 0.2);
    brush.line(gx - 4, gy - 14, gx + 4, gy + 14);
  }

  pop();
}

// ============================================================================
// 6. HYPERREAL TWISTING STRIPED CAT ENGINE
// ============================================================================
function drawHyperrealCat(pose, idx) {
  push();
  translate(pose.fcx, pose.cy);

  // 1. Far-side limbs (drawn behind the torso in darker atmospheric graphite)
  drawArticulatedLimb(pose.farHind, true, true, pose.torsionPost);
  drawArticulatedLimb(pose.farFore, true, false, pose.torsionAnt);

  // 2. Muscular ringed tabby tail with separated flying guard hairs
  drawTabbyTail(pose.pelvis, pose.tail);

  // 3. Twisting feline torso: 3D cylinder shading, axial torsion fold, mackerel tabby stripes, separated fur
  drawTwistingTorso(pose, idx);

  // 4. Near-side limbs (drawn in front of torso with high-contrast silvery highlights & splayed toes)
  drawArticulatedLimb(pose.nearHind, false, true, pose.torsionPost);
  drawArticulatedLimb(pose.nearFore, false, false, pose.torsionAnt);

  // 5. Head, flattened airplane ears, startled binocular eyes, and wind-swept whiskers
  drawCatHeadDetailed(
    pose.head[0],
    pose.head[1],
    pose.head[2],
    pose.headAngle,
    pose.eyeLook,
    pose.earSpread,
    false
  );

  // 6. Scientific center-of-gravity marker (+ G) and torsion vector overlaid on the body
  drawBiomechanicalOverlay(pose, idx);

  pop();
}

function drawTwistingTorso(pose, idx) {
  let p0 = [pose.pelvis[0], pose.pelvis[1]];
  let r0 = pose.pelvis[2];
  let p1 = [pose.midSpine[0], pose.midSpine[1]];
  let r1 = pose.midSpine[2];
  let p2 = [pose.chest[0], pose.chest[1]];
  let r2 = pose.chest[2];

  // Sample smooth spine centerline and local radii
  let steps = 18;
  let upperEdge = [];
  let lowerEdge = [];
  let centerPts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    // Quadratic Bezier interpolation through p0, p1 (weighted), p2
    let ctrlX = 2 * p1[0] - 0.5 * (p0[0] + p2[0]);
    let ctrlY = 2 * p1[1] - 0.5 * (p0[1] + p2[1]);
    let u = 1 - t;
    let cx = u * u * p0[0] + 2 * u * t * ctrlX + t * t * p2[0];
    let cy = u * u * p0[1] + 2 * u * t * ctrlY + t * t * p2[1];

    // Tangent vector
    let tx = 2 * u * (ctrlX - p0[0]) + 2 * t * (p2[0] - ctrlX);
    let ty = 2 * u * (ctrlY - p0[1]) + 2 * t * (p2[1] - ctrlY);
    let len = max(0.001, sqrt(tx * tx + ty * ty));
    let nx = -ty / len;
    let ny = tx / len;

    // Pinch slightly at the waist during the intense twist in frames II & III
    let waistPinch = (idx === 1 || idx === 2) ? (1 - 0.16 * sin(t * 180)) : 1.0;
    let rad = (u * u * r0 + 2 * u * t * r1 + t * t * r2) * waistPinch;

    centerPts.push({ x: cx, y: cy, nx: nx, ny: ny, r: rad, t: t });
    upperEdge.push([cx + nx * rad, cy + ny * rad]);
    lowerEdge.push([cx - nx * rad, cy - ny * rad]);
  }

  let torsoPoly = [...upperEdge, ...lowerEdge.slice().reverse()];

  // Base warm-grey/silver body wash
  brush.noStroke();
  brush.wash(PALETTE.graphiteHB, 215);
  drawPolyShape(torsoPoly);
  brush.noWash();

  // Deep shadow core on lower/turned side of the cylinder
  let shadowPoly = [];
  for (let c of centerPts) {
    shadowPoly.push([c.x - c.nx * c.r * 0.1, c.y - c.ny * c.r * 0.1]);
  }
  for (let i = centerPts.length - 1; i >= 0; i--) {
    let c = centerPts[i];
    shadowPoly.push([c.x - c.nx * c.r * 0.98, c.y - c.ny * c.r * 0.98]);
  }
  brush.noStroke();
  brush.wash(PALETTE.graphite4B, 175);
  drawPolyShape(shadowPoly);
  brush.noWash();

  // High-contrast silvery highlight band along the upper lit convexity
  let litPoly = [];
  for (let c of centerPts) {
    litPoly.push([c.x + c.nx * c.r * 0.85, c.y + c.ny * c.r * 0.85]);
  }
  for (let i = centerPts.length - 1; i >= 0; i--) {
    let c = centerPts[i];
    litPoly.push([c.x + c.nx * c.r * 0.18, c.y + c.ny * c.r * 0.18]);
  }
  brush.noStroke();
  brush.wash(PALETTE.silverLight, 155);
  drawPolyShape(litPoly);
  brush.noWash();

  // Fine directional fur hatching across the torso volume
  for (let i = 0; i < centerPts.length - 1; i++) {
    let c = centerPts[i];
    for (let f = -0.85; f <= 0.85; f += 0.24) {
      let fx = c.x + c.nx * c.r * f;
      let fy = c.y + c.ny * c.r * f;
      let isLit = f > 0.15;
      let col = isLit ? (f > 0.5 ? PALETTE.chalkWhite : PALETTE.silverLight) : (f < -0.45 ? PALETTE.graphite6B : PALETTE.graphite2B);
      brush.set("graphite_needle", col, isLit ? 0.45 : 0.38);
      brush.line(fx, fy, fx - 9 + random(-2, 2), fy + f * 5 + random(-2, 2));
    }
  }

  // Diagonal torsion crease & skin fold in the middle of the body (especially dramatic in frames I, II, III)
  if (idx <= 3) {
    let mc = centerPts[9];
    brush.set("graphite_soft", PALETTE.graphite6B, 0.55);
    brush.spline([
      [mc.x - 14, mc.y + mc.ny * mc.r * 0.9],
      [mc.x + 2, mc.y],
      [mc.x + 16, mc.y - mc.ny * mc.r * 0.9]
    ], 0.45);
    brush.set("chalk_white", PALETTE.chalkWhite, 0.45);
    brush.spline([
      [mc.x - 10, mc.y + mc.ny * mc.r * 0.85],
      [mc.x + 6, mc.y],
      [mc.x + 20, mc.y - mc.ny * mc.r * 0.82]
    ], 0.45);
  }

  // Mackerel Tabby Stripes wrapping around the twisting 3D cylinder!
  let numStripes = 13;
  for (let s = 1; s < numStripes; s++) {
    let idxPt = Math.floor(map(s, 0, numStripes, 1, centerPts.length - 2));
    let c = centerPts[idxPt];

    // Curvature of stripe reverses between posterior and anterior halves during twist!
    let twistBow = (s < numStripes * 0.5)
      ? map(pose.torsionPost, 0, 180, -10, 14)
      : map(pose.torsionAnt, 0, 180, -10, 14);

    let dorsalEdge = (pose.spineFlip >= 0) ? 0.95 : -0.95;
    let ventralEdge = (pose.spineFlip >= 0) ? -0.78 : 0.78;

    let stStart = [c.x + c.nx * c.r * dorsalEdge, c.y + c.ny * c.r * dorsalEdge];
    let stMid = [c.x + c.nx * c.r * (dorsalEdge * 0.15) + twistBow, c.y + c.ny * c.r * (dorsalEdge * 0.15)];
    let stEnd = [c.x + c.nx * c.r * ventralEdge + twistBow * 0.4, c.y + c.ny * c.r * ventralEdge];

    // Dark charcoal tabby stripe core + jagged fur-lock edges
    brush.set("graphite_soft", PALETTE.graphite6B, 0.62);
    brush.spline([stStart, stMid, stEnd], 0.5);

    brush.set("graphite_needle", PALETTE.graphite6B, 0.48);
    brush.spline([
      [stStart[0] + 2, stStart[1]],
      [stMid[0] + 2.5, stMid[1]],
      [stEnd[0] + 1.5, stEnd[1]]
    ], 0.5);

    // Adjacent silver guard hairs overlapping the dark stripe for hyperreal fur depth
    brush.set("chalk_white", PALETTE.silverLight, 0.35);
    brush.line(stMid[0] + 4, stMid[1] - 3, stMid[0] - 2, stMid[1] + 2);
  }

  // Dark dorsal spine stripe running along the back
  let dorsalPts = centerPts.map(c => {
    let side = pose.spineFlip >= 0 ? 0.88 : -0.88;
    return [c.x + c.nx * c.r * side, c.y + c.ny * c.r * side];
  });
  brush.set("graphite_soft", PALETTE.graphite6B, 0.68);
  brush.spline(dorsalPts, 0.5);

  // Separated fur tufts along both upper and lower body contours (flared by air resistance!)
  drawSeparatedFurContour(upperEdge, 1, true, 13);
  drawSeparatedFurContour(lowerEdge, -1, false, 15);
}

function drawSeparatedFurContour(edgePts, sideSign, isLitSide, tuftLen) {
  for (let i = 0; i < edgePts.length - 1; i++) {
    let pA = edgePts[i];
    let pB = edgePts[i + 1];
    let dx = pB[0] - pA[0];
    let dy = pB[1] - pA[1];
    let segLen = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = (-dy / segLen) * sideSign;
    let ny = (dx / segLen) * sideSign;

    // 3 separated hair clumps per segment
    for (let k = 0; k < 3; k++) {
      let f = (k + 0.5) / 3;
      let bx = lerp(pA[0], pB[0], f);
      let by = lerp(pA[1], pB[1], f);

      // Upward airflow bends outer fur tips slightly upward (negative y) and backward
      let tipX = bx + nx * tuftLen + (-dx / segLen) * 5 + random(-2, 2);
      let tipY = by + ny * tuftLen - 3.5 + random(-2, 2);

      // Dark V-shaped cleft between separated fur clumps
      brush.set("graphite_needle", PALETTE.graphite6B, 0.48);
      brush.line(bx - dx * 0.15, by - dy * 0.15, bx + nx * (tuftLen * 0.55), by + ny * (tuftLen * 0.55));

      // Mid-tone fur lock
      brush.set("graphite_needle", isLitSide ? PALETTE.silverLight : PALETTE.graphite2B, 0.42);
      brush.line(bx, by, tipX, tipY);

      // High-contrast silvery-white guard hairs spiking out beyond the coat
      if (isLitSide || k === 1) {
        brush.set("chalk_white", isLitSide ? PALETTE.chalkPure : PALETTE.silverLight, isLitSide ? 0.46 : 0.3);
        brush.line(bx + dx * 0.1, by + dy * 0.1, tipX + nx * 3.5, tipY - 1.5);
      }
    }
  }
}

function drawTabbyTail(pelvis, tailPts) {
  let allPts = [[pelvis[0] - 12, pelvis[1]], ...tailPts];
  let steps = 16;
  let leftE = [], rightE = [], cList = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let pt = evalCubicChain(allPts, t);
    let ptNext = evalCubicChain(allPts, min(1, t + 0.04));
    let dx = ptNext[0] - pt[0];
    let dy = ptNext[1] - pt[1];
    let len = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / len;
    let ny = dx / len;
    let rad = lerp(11.5, 5.5, t) * (1 + 0.15 * sin(t * 180)); // bushy mid-tail

    cList.push({ x: pt[0], y: pt[1], nx, ny, r: rad, t });
    leftE.push([pt[0] + nx * rad, pt[1] + ny * rad]);
    rightE.push([pt[0] - nx * rad, pt[1] - ny * rad]);
  }

  let tailPoly = [...leftE, ...rightE.slice().reverse()];
  brush.noStroke();
  brush.wash(PALETTE.graphite2B, 215);
  drawPolyShape(tailPoly);
  brush.noWash();

  // 8 dark charcoal tabby rings + solid black tail tip
  for (let i = 1; i < cList.length; i++) {
    let c = cList[i];
    let isRing = (i % 2 === 0) || (i >= cList.length - 3);
    if (isRing) {
      brush.set("graphite_soft", PALETTE.graphite6B, 0.62);
      brush.line(c.x - c.nx * c.r, c.y - c.ny * c.r, c.x + c.nx * c.r, c.y + c.ny * c.r);
    } else {
      brush.set("chalk_white", PALETTE.silverLight, 0.42);
      brush.line(c.x, c.y, c.x + c.nx * c.r * 0.9, c.y + c.ny * c.r * 0.9);
    }

    // Separated bristling tail hairs on both sides
    brush.set("graphite_needle", isRing ? PALETTE.graphite6B : PALETTE.silverLight, 0.38);
    brush.line(c.x + c.nx * c.r * 0.6, c.y + c.ny * c.r * 0.6, c.x + c.nx * (c.r + 8), c.y + c.ny * (c.r + 8) - 2);
    brush.line(c.x - c.nx * c.r * 0.6, c.y - c.ny * c.r * 0.6, c.x - c.nx * (c.r + 7), c.y - c.ny * (c.r + 7) - 2);
  }
}

function drawArticulatedLimb(limb, isFar, isHind, torsionAngle) {
  let j = limb.joints;
  let widths = isHind ? [18, 13.5, 7.5, 8.5] : [15.5, 11.5, 7.2, 8.2];

  let leftSide = [];
  let rightSide = [];
  for (let i = 0; i < j.length; i++) {
    let p = j[i];
    let pNext = i < j.length - 1 ? j[i + 1] : j[i];
    let pPrev = i > 0 ? j[i - 1] : j[i];
    let dx = pNext[0] - pPrev[0];
    let dy = pNext[1] - pPrev[1];
    let len = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / len;
    let ny = dx / len;
    let w = widths[i];
    leftSide.push([p[0] + nx * w, p[1] + ny * w]);
    rightSide.push([p[0] - nx * w, p[1] - ny * w]);
  }

  let limbPoly = [...leftSide, ...rightSide.slice().reverse()];

  // Base graphite shading (far limbs darker so they sit behind torso, near limbs brighter)
  brush.noStroke();
  brush.wash(isFar ? PALETTE.graphite4B : PALETTE.graphiteHB, 225);
  drawPolyShape(limbPoly);
  brush.noWash();

  // Lit rim highlight on near limbs
  if (!isFar) {
    brush.set("chalk_white", PALETTE.silverLight, 0.55);
    brush.spline(leftSide, 0.45);
    brush.set("chalk_white", PALETTE.chalkWhite, 0.38);
    brush.spline(leftSide.slice(0, 3), 0.45);
  }

  // Dark shadow edge
  brush.set("graphite_soft", PALETTE.graphite6B, 0.5);
  brush.spline(rightSide, 0.45);

  // Tabby leg-bracelet stripes wrapping around the limb segments
  for (let seg = 0; seg < 2; seg++) {
    for (let s = 0.25; s <= 0.78; s += 0.26) {
      let lx = lerp(leftSide[seg][0], leftSide[seg + 1][0], s);
      let ly = lerp(leftSide[seg][1], leftSide[seg + 1][1], s);
      let rx = lerp(rightSide[seg][0], rightSide[seg + 1][0], s);
      let ry = lerp(rightSide[seg][1], rightSide[seg + 1][1], s);
      let mx = (lx + rx) * 0.5;
      let my = (ly + ry) * 0.5 + 3;

      brush.set("graphite_soft", PALETTE.graphite6B, 0.52);
      brush.spline([[lx, ly], [mx, my], [rx, ry]], 0.45);
    }
  }

  // Separated fur feathering along the trailing edge of the limb
  for (let seg = 0; seg < 2; seg++) {
    for (let f = 0; f < 4; f++) {
      let t = f / 4;
      let bx = lerp(leftSide[seg][0], leftSide[seg + 1][0], t);
      let by = lerp(leftSide[seg][1], leftSide[seg + 1][1], t);
      brush.set("graphite_needle", isFar ? PALETTE.graphite2B : PALETTE.chalkWhite, 0.36);
      brush.line(bx, by, bx - 7, by - 4);
    }
  }

  // Splayed Paw with individual spread toes, webbing, pads, and extended claws!
  drawSplayedPaw(j[3][0], j[3][1], limb.splay, isFar, isHind, 1.0);
}

function drawSplayedPaw(px, py, splayAngle, isFar, isHind, scaleMul) {
  let numToes = isHind ? 4 : 5; // 4 main digits + medial dewclaw on front paws
  let spreadAngles = isHind
    ? [-34, -11, 11, 34]
    : [-38, -15, 7, 29, 52];
  let toeLengths = isHind
    ? [16, 19.5, 19.5, 16]
    : [15.5, 19, 19.5, 16.5, 11.5];

  let toeTips = [];
  for (let i = 0; i < numToes; i++) {
    let ang = splayAngle + spreadAngles[i];
    let len = toeLengths[i] * scaleMul;
    toeTips.push({
      ang: ang,
      len: len,
      x: px + cos(ang) * len,
      y: py + sin(ang) * len,
      midX: px + cos(ang) * (len * 0.55),
      midY: py + sin(ang) * (len * 0.55)
    });
  }

  // 1. Stretched interdigital webbing between splayed toes
  for (let i = 0; i < numToes - 1; i++) {
    let tA = toeTips[i];
    let tB = toeTips[i + 1];
    let webPoly = [
      [px, py],
      [tA.midX, tA.midY],
      [(tA.midX + tB.midX) * 0.5, (tA.midY + tB.midY) * 0.5],
      [tB.midX, tB.midY]
    ];
    brush.noStroke();
    brush.wash(PALETTE.graphite4B, 195);
    drawPolyShape(webPoly);
    brush.noWash();
  }

  // 2. Central metacarpal/metatarsal pad shadow
  brush.noStroke();
  brush.wash(PALETTE.graphite6B, 210);
  brush.circle(px, py, 5.5 * scaleMul, 0.15);
  brush.noWash();

  // 3. Individual splayed digits, interdigital fur spikes, digital pads & unsheathed claws
  for (let i = 0; i < numToes; i++) {
    let t = toeTips[i];
    let perpX = -sin(t.ang) * 2.4 * scaleMul;
    let perpY = cos(t.ang) * 2.4 * scaleMul;

    // Shadow side of toe
    brush.set("graphite_soft", PALETTE.graphite6B, 0.5 * scaleMul);
    brush.line(px - perpX, py - perpY, t.x - perpX * 0.6, t.y - perpY * 0.6);

    // Core & lit side of toe
    brush.set("graphite_needle", isFar ? PALETTE.silverMid : PALETTE.silverLight, 0.55 * scaleMul);
    brush.line(px, py, t.x, t.y);
    if (!isFar) {
      brush.set("chalk_white", PALETTE.chalkWhite, 0.45 * scaleMul);
      brush.line(px + perpX * 0.7, py + perpY * 0.7, t.x + perpX * 0.4, t.y + perpY * 0.4);
    }

    // Dark digital pad oval near tip
    brush.set("graphite_soft", PALETTE.graphite6B, 0.48 * scaleMul);
    brush.circle(t.x - cos(t.ang) * 2.5 * scaleMul, t.y - sin(t.ang) * 2.5 * scaleMul, 2.0 * scaleMul, 0.1);

    // Separated tuft hairs shooting out between toes
    brush.set("graphite_needle", PALETTE.silverLight, 0.32 * scaleMul);
    brush.line(t.midX, t.midY, t.midX + perpX * 1.8, t.midY + perpY * 1.8);

    // Unsheathed curved ivory-white claw at the tip of every toe!
    let clawLen = 6.8 * scaleMul;
    let clawBend = t.ang + 14;
    let cx1 = t.x + cos(t.ang) * (clawLen * 0.5);
    let cy1 = t.y + sin(t.ang) * (clawLen * 0.5);
    let cx2 = t.x + cos(clawBend) * clawLen;
    let cy2 = t.y + sin(clawBend) * clawLen;

    // Dark claw underside hook
    brush.set("graphite_needle", PALETTE.graphite6B, 0.42 * scaleMul);
    brush.spline([[t.x, t.y + 0.8 * scaleMul], [cx1, cy1 + 0.8 * scaleMul], [cx2, cy2]], 0.45);

    // Gleaming white chalk dorsal claw ridge
    brush.set("chalk_white", PALETTE.chalkPure, 0.52 * scaleMul);
    brush.spline([[t.x, t.y], [cx1, cy1], [cx2, cy2]], 0.45);
  }
}

function drawCatHeadDetailed(hx, hy, hr, headAngle, eyeLook, earSpread, isMagnified) {
  push();
  translate(hx, hy);
  rotate(headAngle);

  let s = hr / 25.0; // relative scale factor (1.0 on main poses, ~2.04 on magnified inset)

  // 1. Cranial sphere & cheek ruff volume
  let skullPts = [];
  for (let a = 0; a < 360; a += 20) {
    // Cheek ruffs flare out horizontally at a = 0..30 and 150..210
    let cheekFlare = (abs(sin(a)) < 0.45 && sin(a) >= -0.1) ? 1.24 : 1.0;
    let rx = cos(a) * hr * cheekFlare;
    let ry = sin(a) * hr * 0.92;
    skullPts.push([rx, ry]);
  }

  brush.noStroke();
  brush.wash(PALETTE.graphiteHB, 230);
  drawPolyShape(skullPts);
  brush.noWash();

  // Dark graphite shading under chin and sides of cranium
  brush.noStroke();
  brush.wash(PALETTE.graphite4B, 170);
  brush.circle(0, hr * 0.22, hr * 0.85, 0.15);
  brush.noWash();

  // Silvery-white highlight on brow, nose bridge, and muzzle whisker pads
  brush.noStroke();
  brush.wash(PALETTE.silverLight, 165);
  brush.circle(0, -hr * 0.18, hr * 0.65, 0.15);
  brush.circle(-hr * 0.25, hr * 0.26, hr * 0.28, 0.1);
  brush.circle(hr * 0.25, hr * 0.26, hr * 0.28, 0.1);
  brush.noWash();

  // 2. Flattened "Airplane" Ears (pinned hard sideways and back against the skull!)
  for (let side of [-1, 1]) {
    let earBaseTop = [side * hr * 0.52, -hr * 0.68];
    let earBaseBot = [side * hr * 0.88, -hr * 0.18];
    let earTip = [side * hr * (1.68 * earSpread), -hr * 0.42];
    let earDip = [side * hr * (1.22 * earSpread), -hr * 0.62];

    let earPoly = [earBaseTop, earDip, earTip, [side * hr * 1.28, -hr * 0.12], earBaseBot];

    // Dark outer pinna
    brush.noStroke();
    brush.wash(PALETTE.graphite4B, 230);
    drawPolyShape(earPoly);
    brush.noWash();

    // Deep concave inner ear shadow
    let innerPoly = [
      [side * hr * 0.65, -hr * 0.52],
      [side * hr * (1.42 * earSpread), -hr * 0.40],
      [side * hr * 0.92, -hr * 0.20]
    ];
    brush.noStroke();
    brush.wash(PALETTE.graphite6B, 210);
    drawPolyShape(innerPoly);
    brush.noWash();

    // Crisp folded upper helix ridge in silvery chalk
    brush.set("chalk_white", PALETTE.silverLight, 0.48 * sqrt(s));
    brush.spline([earBaseTop, earDip, earTip], 0.45);

    // Lower ear contour
    brush.set("graphite_soft", PALETTE.graphite6B, 0.5 * sqrt(s));
    brush.spline([earBaseBot, [side * hr * 1.28, -hr * 0.12], earTip], 0.45);

    // Silvery inner-ear hair tufts (furnishings) shooting outward from the tragus
    let tuftCount = isMagnified ? 11 : 6;
    for (let t = 0; t < tuftCount; t++) {
      let f = t / (tuftCount - 1);
      let sx = lerp(side * hr * 0.62, side * hr * 0.86, f);
      let sy = lerp(-hr * 0.52, -hr * 0.22, f);
      let ex = sx + side * hr * random(0.42, 0.68);
      let ey = sy + random(-hr * 0.12, hr * 0.08);
      brush.set("chalk_white", t % 2 === 0 ? PALETTE.chalkWhite : PALETTE.silverLight, 0.38 * sqrt(s));
      brush.line(sx, sy, ex, ey);
    }
  }

  // 3. Separated cheek ruff fur locks (spiking outward on left and right cheeks)
  let ruffLocks = isMagnified ? 16 : 9;
  for (let side of [-1, 1]) {
    for (let i = 0; i < ruffLocks; i++) {
      let ang = map(i, 0, ruffLocks - 1, -22, 48);
      let radIn = hr * 0.86;
      let radOut = hr * (1.28 + 0.14 * sin(i * 70));
      let bx = side * cos(ang) * radIn;
      let by = sin(ang) * hr * 0.85;
      let tx = side * cos(ang - 6) * radOut;
      let ty = sin(ang - 6) * hr * 1.05 - 2 * s;

      // Dark V-cleft between separated cheek locks
      brush.set("graphite_needle", PALETTE.graphite6B, 0.48 * sqrt(s));
      brush.line(bx * 0.9, by, (bx + tx) * 0.5, (by + ty) * 0.5 + 2 * s);

      // Silvery-white fur lock
      brush.set("chalk_white", i % 2 === 0 ? PALETTE.chalkPure : PALETTE.silverLight, 0.44 * sqrt(s));
      brush.line(bx, by, tx, ty);
    }
  }

  // 4. Classic Tabby Forehead "M" and Cheek Stripes
  brush.set("graphite_soft", PALETTE.graphite6B, 0.55 * sqrt(s));
  // Forehead M
  brush.spline([
    [-hr * 0.42, -hr * 0.36],
    [-hr * 0.24, -hr * 0.68],
    [0, -hr * 0.40],
    [hr * 0.24, -hr * 0.68],
    [hr * 0.42, -hr * 0.36]
  ], 0.35);
  // Lateral crown stripes
  brush.line(-hr * 0.52, -hr * 0.45, -hr * 0.32, -hr * 0.78);
  brush.line(hr * 0.52, -hr * 0.45, hr * 0.32, -hr * 0.78);

  // Cheek stripes radiating from outer eye corners
  for (let side of [-1, 1]) {
    brush.set("graphite_soft", PALETTE.graphite6B, 0.52 * sqrt(s));
    brush.spline([
      [side * hr * 0.58, -hr * 0.08],
      [side * hr * 0.85, hr * 0.02],
      [side * hr * 1.08, hr * 0.16]
    ], 0.45);
    brush.spline([
      [side * hr * 0.52, hr * 0.12],
      [side * hr * 0.80, hr * 0.24],
      [side * hr * 1.02, hr * 0.38]
    ], 0.45);
  }

  // 5. Wide, Startled, Hyperreal Binocular Eyes
  let eyeX = hr * 0.36;
  let eyeY = -hr * 0.06;
  let eyeR = hr * 0.23;

  for (let side of [-1, 1]) {
    let ex = side * eyeX;
    let ey = eyeY;

    // Pale fur ring (spectacles) around the eye
    brush.set("chalk_white", PALETTE.silverLight, 0.42 * sqrt(s));
    brush.circle(ex, ey, eyeR * 1.18, 0.06);

    // Luminous silvery-white iris fill
    brush.noStroke();
    brush.wash(PALETTE.chalkWhite, 240);
    brush.circle(ex, ey, eyeR, 0.04);
    brush.noWash();

    // Radial iris striations in fine graphite needle
    let irisLines = isMagnified ? 24 : 12;
    for (let k = 0; k < irisLines; k++) {
      let a = k * (360 / irisLines);
      brush.set("graphite_needle", PALETTE.graphiteHB, 0.28 * sqrt(s));
      brush.line(
        ex + cos(a) * eyeR * 0.35,
        ey + sin(a) * eyeR * 0.35,
        ex + cos(a) * eyeR * 0.95,
        ey + sin(a) * eyeR * 0.95
      );
    }

    // Upper eyelid cast shadow across top of iris
    brush.set("graphite_soft", PALETTE.graphite2B, 0.42 * sqrt(s));
    brush.arc(ex, ey, eyeR * 0.85, 195, 345);

    // Jet-black vertical elliptical pupil (focused on the ground below!)
    let px = ex + eyeLook[0] * s;
    let py = ey + eyeLook[1] * s;
    let pupW = eyeR * 0.34;
    let pupH = eyeR * 0.72;
    let pupPoly = [
      [px, py - pupH],
      [px + pupW, py],
      [px, py + pupH],
      [px - pupW, py]
    ];
    brush.noStroke();
    brush.wash(PALETTE.graphite6B, 252);
    drawPolyShape(pupPoly);
    brush.noWash();

    // Crisp jet-black palpebral eye outline & tear duct
    brush.set("graphite_needle", PALETTE.graphite6B, 0.58 * sqrt(s));
    brush.circle(ex, ey, eyeR, 0.04);
    brush.line(ex - side * eyeR, ey + eyeR * 0.15, ex - side * eyeR * 1.18, ey + eyeR * 0.32);

    // Brilliant white chalk specular catchlights!
    brush.noStroke();
    brush.wash(PALETTE.chalkPure, 255);
    brush.circle(ex - eyeR * 0.28, ey - eyeR * 0.32, eyeR * 0.26, 0.02);
    brush.circle(ex + eyeR * 0.26, ey + eyeR * 0.24, eyeR * 0.12, 0.02);
    brush.noWash();

    brush.set("chalk_white", PALETTE.chalkPure, 0.55 * sqrt(s));
    brush.circle(ex - eyeR * 0.28, ey - eyeR * 0.32, eyeR * 0.18, 0.02);
  }

  // 6. Nose Leather, Muzzle Puffs, Parted Mouth & Wind-Swept Whiskers
  let noseY = hr * 0.20;
  let nosePoly = [
    [-hr * 0.15, noseY - hr * 0.06],
    [hr * 0.15, noseY - hr * 0.06],
    [0, noseY + hr * 0.12]
  ];
  brush.noStroke();
  brush.wash(PALETTE.graphite6B, 235);
  drawPolyShape(nosePoly);
  brush.noWash();

  // Top highlight on nose leather
  brush.set("chalk_white", PALETTE.silverLight, 0.4 * sqrt(s));
  brush.line(-hr * 0.11, noseY - hr * 0.05, hr * 0.11, noseY - hr * 0.05);

  // Split philtrum and slightly open startled mouth with tiny white fang tips
  brush.set("graphite_needle", PALETTE.graphite6B, 0.48 * sqrt(s));
  brush.line(0, noseY + hr * 0.12, 0, noseY + hr * 0.26);

  let mouthPoly = [
    [-hr * 0.22, noseY + hr * 0.32],
    [0, noseY + hr * 0.24],
    [hr * 0.22, noseY + hr * 0.32],
    [0, noseY + hr * 0.44]
  ];
  brush.noStroke();
  brush.wash(PALETTE.graphite6B, 230);
  drawPolyShape(mouthPoly);
  brush.noWash();

  // Two tiny white upper canine tips
  brush.set("chalk_white", PALETTE.chalkPure, 0.45 * sqrt(s));
  brush.line(-hr * 0.12, noseY + hr * 0.28, -hr * 0.11, noseY + hr * 0.35);
  brush.line(hr * 0.12, noseY + hr * 0.28, hr * 0.11, noseY + hr * 0.35);

  // Fluffy silvery chin tuft
  for (let c = -3; c <= 3; c++) {
    brush.set("chalk_white", PALETTE.silverLight, 0.36 * sqrt(s));
    brush.line(c * hr * 0.06, hr * 0.65, c * hr * 0.08, hr * 0.82);
  }

  // Whisker follicle dots & long airborne vibrissae swept upward by the drop!
  for (let side of [-1, 1]) {
    for (let w = 0; w < 5; w++) {
      let wx = side * (hr * 0.22 + (w % 2) * hr * 0.12);
      let wy = noseY + hr * 0.08 + w * hr * 0.055;

      // Dark follicle dot
      brush.set("graphite_needle", PALETTE.graphite6B, 0.48 * sqrt(s));
      brush.circle(wx, wy, 0.8 * s, 0.05);

      // Long curving white whisker bent upward by air resistance
      let wLen = hr * (1.65 + (w % 3) * 0.22);
      let wMidX = wx + side * wLen * 0.52;
      let wMidY = wy + (w - 2) * hr * 0.08 - hr * 0.08;
      let wEndX = wx + side * wLen;
      let wEndY = wy + (w - 2.5) * hr * 0.18 - hr * 0.28;

      brush.set("chalk_white", PALETTE.chalkPure, (0.42 - w * 0.04) * sqrt(s));
      brush.spline([[wx, wy], [wMidX, wMidY], [wEndX, wEndY]], 0.45);
    }

    // Superciliary (eyebrow) vibrissae shooting upward
    for (let b = 0; b < 3; b++) {
      let bx = side * (hr * 0.22 + b * hr * 0.08);
      let by = -hr * 0.34;
      brush.set("chalk_white", PALETTE.chalkWhite, 0.34 * sqrt(s));
      brush.spline([
        [bx, by],
        [bx + side * hr * 0.25, by - hr * 0.38],
        [bx + side * hr * 0.52, by - hr * 0.65]
      ], 0.45);
    }
  }

  pop();
}

function drawBiomechanicalOverlay(pose, idx) {
  // Subtle scientific center-of-mass crosshair (+ G) and axial angle arc over the cat
  let gx = pose.midSpine[0];
  let gy = pose.midSpine[1] * 0.5;

  brush.set("graphite_needle", PALETTE.chalkPure, 0.38);
  brush.line(gx - 7, gy, gx + 7, gy);
  brush.line(gx, gy - 7, gx, gy + 7);
  brush.circle(gx, gy, 4.5, 0.05);

  // Gravity vector arrow pointing straight down from G
  brush.set("2H", PALETTE.silverLight, 0.28);
  brush.line(gx, gy + 9, gx, gy + 44);
  brush.line(gx, gy + 44, gx - 3.5, gy + 37);
  brush.line(gx, gy + 44, gx + 3.5, gy + 37);
}

// ============================================================================
// 7. FOREGROUND PLATE ACCENTS & SCIENTIFIC FRAME INSCRIPTIONS
// ============================================================================
function drawPlateForegroundAccents(fx, fy, fw, fh, pose, idx) {
  // Top plate header badge inside each frame
  brush.noStroke();
  brush.wash(PALETTE.plateDeep, 190);
  brush.rect(fx + 10, fy + 8, fw - 20, 22, "corner");
  brush.noWash();

  drawGlyphText("POSE " + pose.id + "  T=" + pose.time, fx + 14, fy + 13, 6.5, PALETTE.chalkWhite, 0.26);
  drawGlyphText(pose.dropCm, fx + fw - 52, fy + 13, 6.2, PALETTE.silverLight, 0.22);

  // Bottom plate footer inscription below reception floor line
  drawGlyphText("ROT. ANT:" + pose.torsionAnt + "°  POST:" + pose.torsionPost + "°", fx + 14, fy + fh - 22, 5.5, PALETTE.silverLight, 0.2);

  // Brass/steel glass-plate holder clips at top-center and bottom-center of each frame
  for (let cy of [fy, fy + fh]) {
    let dir = cy === fy ? 1 : -1;
    brush.noStroke();
    brush.wash(PALETTE.graphite6B, 220);
    brush.rect(fx + fw * 0.5 - 14, cy - 3, 28, 6 * dir, "corner");
    brush.noWash();
    brush.set("chalk_white", PALETTE.silverLight, 0.32);
    brush.line(fx + fw * 0.5 - 14, cy, fx + fw * 0.5 + 14, cy);
  }
}

// ============================================================================
// 8. LOWER CHRONOGRAPH TUNING-FORK WAVE & ANGULAR VELOCITY GRAPH
// ============================================================================
function drawChronographStrip(x, y, w, h) {
  let pts = buildIrregularRect(x, y, w, h, 3.2, 18);
  brush.noStroke();
  brush.wash(PALETTE.plateDeep, 228);
  drawPolyShape(pts);
  brush.noWash();

  // Grid inside chronograph strip
  for (let gx = x + 16; gx < x + w - 10; gx += 28) {
    brush.set("2H", PALETTE.gridMinor, 0.18);
    brush.line(gx, y + 6, gx, y + h - 6);
  }
  for (let gy = y + 18; gy < y + h - 8; gy += 22) {
    brush.set("2H", PALETTE.gridMinor, 0.18);
    brush.line(x + 6, gy, x + w - 6, gy);
  }

  // Vertical synchronization drop-lines from each of the 5 frames into the chronograph
  for (let i = 0; i < 5; i++) {
    let p = POSES[i];
    brush.set("2H", PALETTE.silverMid, 0.32);
    brush.line(p.fcx, y - 19, p.fcx, y + h - 6);
    brush.set("chalk_white", PALETTE.chalkWhite, 0.42);
    brush.circle(p.fcx, y + 32, 3.5, 0.05);
    drawGlyphText("T" + (i + 1) + "=" + p.time, p.fcx - 26, y + h - 16, 5.6, PALETTE.silverLight, 0.22);
  }

  // 50 Hz Smoked-Drum Tuning Fork Sine Wave (Diapason Chronographique)
  let waveY = y + 32;
  let wavePts = [];
  for (let wx = x + 14; wx <= x + w - 14; wx += 5) {
    let wy = waveY + sin((wx - x) * 5.2) * 9.5;
    wavePts.push([wx, wy]);
  }
  brush.set("chalk_white", PALETTE.chalkWhite, 0.45);
  brush.spline(wavePts, 0.5);

  // Kinematic Rotation Curve A: Anterior Body (180 deg -> 0 deg rapid early drop)
  let antCurve = [
    [154, y + 48],
    [266, y + 54],
    [378, y + 72],
    [602, y + 90],
    [826, y + 94],
    [1050, y + 94]
  ];
  brush.set("chalk_white", PALETTE.chalkPure, 0.55);
  brush.spline(antCurve, 0.45);

  // Kinematic Rotation Curve B: Posterior Body (lags behind, then whips down between Frame II & IV)
  let postCurve = [
    [154, y + 48],
    [378, y + 51],
    [490, y + 62],
    [602, y + 74],
    [826, y + 90],
    [1050, y + 94]
  ];
  brush.set("2H", PALETTE.silverLight, 0.42);
  brush.spline(postCurve, 0.45);

  drawIrregularBorder(pts, PALETTE.graphite6B, PALETTE.silverMid);

  drawGlyphText("CHRONOGRAPHE A DIAPASON (50 HZ) & COURBES DE ROTATION ANGULAIRE (A: AVANT, B: ARRIERE)", x + 14, y + 8, 6.0, PALETTE.silverLight, 0.22);
}

// ============================================================================
// 9. BOTTOM MARGIN: VALUE SCALE, NOTES & 2.8x SPLAYED PAW STUDY
// ============================================================================
function drawBottomMarginStudies() {
  // 9A. Left: 9-Step Densitometric Graphite & Chalk Value Scale (High Contrast Reference)
  let sx = 48, sy = 1048, sw = 38, sh = 28;
