// GEOMETRY & STROKE-GLYPH UTILITIES
// ============================================================================
function buildIrregularRect(x, y, w, h, jitter, segsPerSide) {
  let pts = [];
  // Top edge
  for (let i = 0; i < segsPerSide; i++) {
    let t = i / segsPerSide;
    pts.push([lerp(x, x + w, t) + random(-jitter * 0.4, jitter * 0.4), y + random(-jitter, jitter)]);
  }
  // Right edge
  for (let i = 0; i < segsPerSide; i++) {
    let t = i / segsPerSide;
    pts.push([x + w + random(-jitter, jitter), lerp(y, y + h, t) + random(-jitter * 0.4, jitter * 0.4)]);
  }
  // Bottom edge
  for (let i = 0; i < segsPerSide; i++) {
    let t = i / segsPerSide;
    pts.push([lerp(x + w, x, t) + random(-jitter * 0.4, jitter * 0.4), y + h + random(-jitter, jitter)]);
  }
  // Left edge
  for (let i = 0; i < segsPerSide; i++) {
    let t = i / segsPerSide;
    pts.push([x + random(-jitter, jitter), lerp(y + h, y, t) + random(-jitter * 0.4, jitter * 0.4)]);
  }
  return pts;
}

function drawPolyShape(pts) {
  if (!pts || pts.length < 3) return;
  brush.beginShape(0);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(true);
}

function drawIrregularBorder(pts, darkCol, lightCol) {
  // Outer dark plate edge
  brush.set("2B", darkCol, 0.52);
  for (let i = 0; i < pts.length; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    brush.line(a[0], a[1], b[0], b[1]);
  }
  // Inner silvered glass-plate bevel highlight on top and left edges
  brush.set("2H", lightCol, 0.28);
  let half = Math.floor(pts.length * 0.5);
  for (let i = 0; i < half; i++) {
    let a = pts[i];
    let b = pts[(i + 1) % pts.length];
    brush.line(a[0] + 1.8, a[1] + 1.8, b[0] + 1.8, b[1] + 1.8);
  }
}

function drawPlateCornerDamage(fx, fy, fw, fh) {
  // Collodion emulsion peeling & silver nitrate corner vignettes on each old plate
  let corners = [
    [fx, fy, 1, 1],
    [fx + fw, fy, -1, 1],
    [fx + fw, fy + fh, -1, -1],
    [fx, fy + fh, 1, -1]
  ];
  for (let c of corners) {
    let cx = c[0], cy = c[1], dx = c[2], dy = c[3];
    let tri = [
      [cx, cy],
      [cx + dx * random(12, 22), cy],
      [cx, cy + dy * random(12, 22)]
    ];
    brush.noStroke();
    brush.wash(PALETTE.paperDark, 145);
    drawPolyShape(tri);
    brush.noWash();

    brush.set("2H", PALETTE.silverLight, 0.26);
    brush.line(tri[1][0], tri[1][1], tri[2][0], tri[2][1]);
  }
}

function evalCubicChain(pts, t) {
  // Smooth Catmull-Rom / piecewise interpolation along point chain
  let n = pts.length - 1;
  let scaled = constrain(t * n, 0, n - 0.0001);
  let idx = Math.floor(scaled);
  let f = scaled - idx;
  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[min(n, idx + 1)];
  let p3 = pts[min(n, idx + 2)];

  let f2 = f * f;
  let f3 = f2 * f;
  let x = 0.5 * (
    (2 * p1[0]) +
    (-p0[0] + p2[0]) * f +
    (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * f2 +
    (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * f3
  );
  let y = 0.5 * (
    (2 * p1[1]) +
    (-p0[1] + p2[1]) * f +
    (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * f2 +
    (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * f3
  );
  return [x, y];
}

function drawGlyphText(str, x, y, size, col, weight) {
  brush.set("2H", col, weight);
  let cursorX = x;
  let charW = size * 0.66;
  let charH = size;
  let spacing = size * 0.26;

  let upper = str.toUpperCase();
  for (let i = 0; i < upper.length; i++) {
    let ch = upper[i];
    if (ch === " ") {
      cursorX += charW * 0.75;
      continue;
    }
    let strokes = GLYPHS[ch];
    if (strokes) {
      for (let poly of strokes) {
        for (let k = 0; k < poly.length - 1; k++) {
          let x1 = cursorX + poly[k][0] * charW;
          let y1 = y + poly[k][1] * charH;
          let x2 = cursorX + poly[k + 1][0] * charW;
          let y2 = y + poly[k + 1][1] * charH;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
    cursorX += charW + spacing;
  }
}

