// Perspective helper: At height y, returns upward-arching ellipse ry for radius rx
function getArchRY(y, rx) {
  let distFromHorizon = Math.max(12, Y_HORIZON - y);
  return rx * 0.235 * (distFromHorizon / 860);
}

// Point on the front upward-arching rim at height y, radius rx, angle thetaDeg in [0, 180]
// thetaDeg = 0 -> left edge (CX - rx), 90 -> center front (CX, y - ry), 180 -> right edge (CX + rx)
function archPt(y, rx, thetaDeg, ryScale = 1.0) {
  let rad = (thetaDeg * Math.PI) / 180;
  let ry = getArchRY(y, rx) * ryScale;
  return [
    CX - rx * Math.cos(rad),
    y - ry * Math.sin(rad)
  ];
}

// Glass radius profile from bottom (y=1040) to rim (y=215) with architectural setbacks
function getGlassRadius(y) {
  if (y > 965) {
    // Heavy crystal plinth base
    return map(y, 965, 1040, 274, 286);
  } else if (y > 885) {
    // First setback molding tier
    return map(y, 885, 965, 258, 268);
  } else if (y > 515) {
    // Main tall espresso tower shaft (tapers upward)
    return map(y, 515, 885, 232, 254);
  } else if (y > 335) {
    // Pale cream spandrel band (slight architectural projection then taper)
    return map(y, 335, 515, 224, 235);
  } else if (y > 245) {
    // Upper espresso setback frieze
    return map(y, 245, 335, 212, 220);
  } else {
    // Moulded crystal crown rim
    return map(y, 210, 245, 214, 210);
  }
}

// Helper for polygon wash + optional marker hatch + optional outline
function drawPoly(pts, washCol, washOp, hatchCfg = null, strokeCfg = null) {
  let p = new brush.Polygon(pts);
  if (washCol && washOp > 0) {
    p.wash(washCol, washOp);
  }
  if (hatchCfg) {
    brush.hatchStyle(hatchCfg.brush || "marker", hatchCfg.col, hatchCfg.weight || 1);
    p.hatch(hatchCfg.dist, hatchCfg.angle, hatchCfg.opts || { rand: 0.02 });
  }
  if (strokeCfg) {
    p.draw(strokeCfg.brush || "pen", strokeCfg.col, strokeCfg.weight || 1);
  }
}

// Bilateral symmetry wrapper: given pts on left/center, mirrors across CX = 600
function mirrorPts(pts) {
  return pts.map(pt => [2 * CX - pt[0], pt[1]]).reverse();
}

// Draw symmetrical line pair
function symLine(x1, y1, x2, y2) {
  brush.line(x1, y1, x2, y2);
  if (Math.abs(x1 - CX) > 0.5 || Math.abs(x2 - CX) > 0.5) {
    brush.line(2 * CX - x1, y1, 2 * CX - x2, y2);
  }
}

// Draw symmetrical spline pair
function symSpline(pts, curv = 0.5) {
  brush.spline(pts, curv);
  let mPts = pts.map(p => [2 * CX - p[0], p[1], p[2] !== undefined ? p[2] : 1]);
  brush.spline(mPts, curv);
}

// Build polygon for a single flute (index i in 0..N_FLUTES-1) between yTop and yBot
function getFluteQuad(i, yTop, yBot, subU1 = 0, subU2 = 1, rOffsetTop = 0, rOffsetBot = 0) {
  let dTheta = 180 / N_FLUTES;
  let th1 = (i + subU1) * dTheta;
  let th2 = (i + subU2) * dTheta;
  let thMid = 0.5 * (th1 + th2);

  let rTop = getGlassRadius(yTop) + rOffsetTop;
  let rBot = getGlassRadius(yBot) + rOffsetBot;

  let pTL = archPt(yTop, rTop, th1);
  let pTM = archPt(yTop, rTop, thMid);
  let pTR = archPt(yTop, rTop, th2);

  let pBR = archPt(yBot, rBot, th2);
  let pBM = archPt(yBot, rBot, thMid);
  let pBL = archPt(yBot, rBot, th1);

  return [pTL, pTM, pTR, pBR, pBM, pBL];
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
