  });

  brush.add("gold_nib", {
    type: "default",
    weight: 0.65,
    scatter: 0.02,
    sharpness: 0.92,
    grain: 8,
    opacity: 220,
    spacing: 0.25,
    pressure: [0.6, 1.15, 0.5],
    rotate: "natural",
    noise: 0.1
  });
}

