  drawFinalGlamourAccents();

  noLoop();
}

// =============================================================================
// 1. JADE-BLACK NIGHT SKY
// =============================================================================
function drawNightSky() {
  // Base abyssal wash
  drawPoly([[0, 0], [1200, 0], [1200, 1200], [0, 1200]], PAL.skyAbyss, 255);

  // Symmetrical stepped nocturnal jade backlight columns behind the glass tower
  const auraBands = [
    { w: 540, yTop: 0, yBot: 1080, col: PAL.skyDeep, op: 180, hatchDist: 9 },
    { w: 450, yTop: 0, yBot: 1080, col: PAL.skyJadeDark, op: 170, hatchDist: 8 },
    { w: 370, yTop: 15, yBot: 1060, col: PAL.skyJadeMid, op: 150, hatchDist: 7 },
    { w: 300, yTop: 25, yBot: 980, col: PAL.skyJadeGlow, op: 130, hatchDist: 6 },
    { w: 235, yTop: 30, yBot: 580, col: PAL.skyJadeBright, op: 110, hatchDist: 5 },
    { w: 160, yTop: 32, yBot: 360, col: PAL.jadeIce, op: 75, hatchDist: 5 }
  ];

  for (let b of auraBands) {
    let xL = CX - b.w;
    let xR = CX + b.w;
    let pts = [[xL, b.yTop], [xR, b.yTop], [xR * 0.92 + CX * 0.08, b.yBot], [xL * 0.92 + CX * 0.08, b.yBot]];
    drawPoly(pts, b.col, b.op, {
      brush: "chisel",
      col: b.col,
      weight: 1.3,
      dist: b.hatchDist,
      angle: 90,
      opts: { rand: 0.01 }
    });
  }

  // Deep abyssal vignette flutes on far left and right edges (sky pilasters)
  const edgeCols = 10;
  for (let i = 0; i < edgeCols; i++) {
    let x1 = i * 34;
    let x2 = (i + 1) * 34;
    let col = i < 4 ? PAL.skyAbyss : (i < 7 ? PAL.skyDeep : PAL.skyJadeDark);
    let op = map(i, 0, edgeCols - 1, 235, 60);
    drawPoly([[x1, 0], [x2, 0], [x2, 1200], [x1, 1200]], col, op);
    drawPoly([[1200 - x2, 0], [1200 - x1, 0], [1200 - x1, 1200], [1200 - x2, 1200]], col, op);
  }

  // Subtle Art-Deco perspective rays radiating from high behind the ice crown (CX, 160)
  brush.set("rotring", PAL.skyJadeGlow, 0.55);
  for (let a = 12; a <= 78; a += 3) {
    let rad = (a * Math.PI) / 180;
    let r1 = 230;
    let r2 = 820;
    let x1 = CX - Math.cos(rad) * r1;
    let y1 = 210 - Math.sin(rad) * r1 * 0.35;
    let x2 = CX - Math.cos(rad) * r2;
    let y2 = 210 - Math.sin(rad) * r2 * 0.45;
    if (y2 > 0 && y1 > 0) {
      symLine(x1, y1, x2, y2);
    }
  }

  // Fine vertical night-sky architectural striations
  for (let dx = 250; dx <= 585; dx += 14) {
    let col = dx < 360 ? PAL.skyJadeMid : (dx < 470 ? PAL.skyJadeDark : PAL.skyAbyss);
    brush.set("chisel", col, 0.9);
    symLine(CX - dx, 0, CX - dx, 1080);
  }

  // Faint gold architectural framing lines in the deep jade night sky
  brush.set("gold_nib", PAL.goldShadow, 0.55);
  for (let dx of [315, 322, 430, 436, 545, 552]) {
    symLine(CX - dx, 30, CX - dx, 1065);
  }
}

