// 2. DARK JADE & BRASS STEPPED PLINTH AT THE BASE
// =============================================================================
function drawSteppedPlinth() {
  // Dark reflective table surface below horizon
  drawPoly([[0, 1045], [1200, 1045], [1200, 1200], [0, 1200]], PAL.skyAbyss, 250);

  // Stepped octagonal coaster / architectural pedestal under the glass base
  const plinthTiers = [
    { y1: 1035, y2: 1068, rx1: 315, rx2: 335, col: PAL.espBlack, border: PAL.goldDeep },
    { y1: 1068, y2: 1110, rx1: 355, rx2: 385, col: PAL.skyDeep, border: PAL.goldMid },
    { y1: 1110, y2: 1165, rx1: 410, rx2: 455, col: PAL.skyAbyss, border: PAL.goldShadow },
    { y1: 1165, y2: 1200, rx1: 480, rx2: 520, col: PAL.espAbyss, border: PAL.goldDeep }
  ];

  for (let t of plinthTiers) {
    let pts = [];
    for (let th = 0; th <= 180; th += 10) {
      pts.push(archPt(t.y1, t.rx1, th, 0.8));
    }
    for (let th = 180; th >= 0; th -= 10) {
      pts.push(archPt(t.y2, t.rx2, th, 0.8));
    }
    drawPoly(pts, t.col, 240, {
      brush: "chisel",
      col: t.col,
      weight: 1.2,
      dist: 5,
      angle: 0
    });

    // Gold hatching along pedestal step riser
    brush.set("gold_nib", t.border, 0.75);
    for (let th = 6; th <= 88; th += 2.5) {
      let p1 = archPt(t.y1, t.rx1, th, 0.8);
      let p2 = archPt(t.y1 + 10, t.rx1 + 3, th, 0.8);
      symLine(p1[0], p1[1], p2[0], p2[1]);
    }
  }

  // Vertical reflections of the glass flutes down into the polished black-jade plinth
  for (let i = 0; i < N_FLUTES; i++) {
    let thMid = (i + 0.5) * (180 / N_FLUTES);
    let pTop = archPt(1040, 286, thMid);
    let pBot = archPt(1195, 360, thMid);
    let distCenter = Math.abs(i - 7) / 7;
    let refCol = distCenter < 0.4 ? PAL.espRich : (distCenter < 0.75 ? PAL.skyJadeMid : PAL.goldShadow);
    brush.set("chisel", refCol, 1.1);
    brush.line(pTop[0], pTop[1], pBot[0], pBot[1]);
  }
}

// =============================================================================
// 3. BACK-RIM ELLIPSES (Visible at the top rim and internal rings)
// =============================================================================
function drawBackRims() {
  // At y = 225 (top rim), the back half of the ellipse curves downward (y + ry * sin(th))
  let yRim = 222;
  let rxRim = getGlassRadius(yRim);
  let ryRim = getArchRY(yRim, rxRim);

  let rimEllipsePts = [];
  for (let th = 0; th <= 180; th += 5) {
    rimEllipsePts.push(archPt(yRim, rxRim, th));
  }
  for (let th = 180; th >= 0; th -= 5) {
    let rad = (th * Math.PI) / 180;
    rimEllipsePts.push([CX - rxRim * Math.cos(rad), yRim + ryRim * 0.75 * Math.sin(rad)]);
  }
  drawPoly(rimEllipsePts, PAL.espDark, 230, {
    brush: "chisel",
    col: PAL.espMid,
    weight: 1.0,
    dist: 4,
    angle: 0
  });
}

// =============================================================================
// 4. MAIN LAYERED COFFEE & CREAM SPANDREL (Fluted Marker Planes)
// =============================================================================
function drawFlutedTowerBody() {
  // Vertical elevation zones of the liquid & glass body:
  // Zone A: Lower Espresso Shaft (y = 515 to 890)
  // Zone B: Cream Spandrel Band (y = 335 to 515)
  // Zone C: Upper Espresso Setback Frieze (y = 235 to 335)

  // To create hyperrealist cylindrical fluting, each of the 15 flutes is subdivided
  // horizontally into 5 micro-strips (left ridge, left slope, center trough, right slope, right ridge)
  // and vertically into bands for smooth tonal gradation and dense marker texture.

  // --- ZONE A: LOWER ESPRESSO SHAFT (y = 515 to 890) ---
  const espBands = [
    { y1: 515, y2: 595, t: 0.0 },
    { y1: 595, y2: 685, t: 0.3 },
    { y1: 685, y2: 785, t: 0.65 },
    { y1: 785, y2: 890, t: 1.0 }
  ];

  for (let b of espBands) {
    for (let i = 0; i <= 7; i++) {
      // i = 0 is outer edge flute, i = 7 is dead-center flute
      let mirrorIndices = i === 7 ? [7] : [i, 14 - i];

      for (let idx of mirrorIndices) {
        // 3 sub-strips per flute to model concave/convex lens refraction
        const subStrips = [
          { u1: 0.0, u2: 0.26, role: "leftSlope" },
          { u1: 0.26, u2: 0.74, role: "core" },
          { u1: 0.74, u2: 1.0, role: "rightSlope" }
        ];

        for (let s of subStrips) {
          let quad = getFluteQuad(idx, b.y1, b.y2, s.u1, s.u2);
          let col, hatchCol;

          // Center flutes are deepest abyssal espresso; outer flutes glow with roasted amber & jade refraction
          let isOuterSide = (idx < 7 && s.role === "leftSlope") || (idx > 7 && s.role === "rightSlope");
          let isInnerSide = (idx < 7 && s.role === "rightSlope") || (idx > 7 && s.role === "leftSlope");

          if (i === 0) {
            col = isOuterSide ? PAL.skyJadeMid : (s.role === "core" ? PAL.espAmber : PAL.espDark);
            hatchCol = isOuterSide ? PAL.skyJadeBright : PAL.espGlow;
          } else if (i === 1) {
            col = isOuterSide ? PAL.espGlow : (s.role === "core" ? PAL.espRich : PAL.espBlack);
            hatchCol = isOuterSide ? PAL.espBright : PAL.espAmber;
          } else if (i === 2) {
            col = isOuterSide ? PAL.espAmber : (s.role === "core" ? PAL.espMid : PAL.espAbyss);
            hatchCol = isOuterSide ? PAL.espGlow : PAL.espRich;
          } else if (i <= 4) {
            col = s.role === "core" ? (b.t > 0.5 ? PAL.espMid : PAL.espDark) : (isInnerSide ? PAL.espRich : PAL.espAbyss);
            hatchCol = isInnerSide ? PAL.espAmber : PAL.espBlack;
          } else {
            // Central monolithic espresso pilasters (high contrast dark core with crisp amber rim)
            col = s.role === "core" ? PAL.espAbyss : (b.t > 0.6 ? PAL.espMid : PAL.espBlack);
            hatchCol = s.role === "core" ? PAL.espBlack : PAL.espRich;
          }

          drawPoly(quad, col, 245, {
            brush: "chisel",
            col: hatchCol,
            weight: 1.05,
            dist: 4.2,
            angle: 90,
            opts: { rand: 0.01 }
          });
        }
      }
    }
  }

  // Warm roasted-amber internal glow near the bottom of the espresso column (y = 770 to 888)
  for (let i = 1; i <= 6; i++) {
    for (let idx of [i, 14 - i]) {
      let quad = getFluteQuad(idx, 775, 886, 0.3, 0.7);
      let glowCol = i <= 3 ? PAL.espGlow : PAL.espRich;
      drawPoly(quad, glowCol, 120, {
        brush: "marker",
        col: i <= 2 ? PAL.espBright : PAL.espAmber,
        weight: 0.9,
        dist: 5,
        angle: 90
      });
    }
  }

  // --- ZONE B: THE CREAM LAYER — PALE SPANDREL BAND (y = 335 to 515) ---
  const creamBands = [
    { y1: 335, y2: 385, role: "upperSpandrel" },
    { y1: 385, y2: 455, role: "midSpandrel" },
    { y1: 455, y2: 515, role: "lowerSpandrel" }
  ];

  for (let b of creamBands) {
    for (let i = 0; i <= 7; i++) {
      let mirrorIndices = i === 7 ? [7] : [i, 14 - i];
      for (let idx of mirrorIndices) {
        const subStrips = [
          { u1: 0.0, u2: 0.24, role: "left" },
          { u1: 0.24, u2: 0.76, role: "center" },
          { u1: 0.76, u2: 1.0, role: "right" }
        ];

        for (let s of subStrips) {
          let quad = getFluteQuad(idx, b.y1, b.y2, s.u1, s.u2);
          let isOuter = (idx < 7 && s.role === "left") || (idx > 7 && s.role === "right");
          let isInner = (idx < 7 && s.role === "right") || (idx > 7 && s.role === "left");

          let col, hatchCol;
          if (i === 0) {
            col = isOuter ? PAL.skyJadeMid : (s.role === "center" ? PAL.ivoryShadow : PAL.ivoryDeep);
            hatchCol = isOuter ? PAL.jadeIce : PAL.ivoryWarm;
          } else if (i === 1) {
            col = s.role === "center" ? PAL.ivoryWarm : (isOuter ? PAL.ivoryShadow : PAL.ivoryDeep);
            hatchCol = PAL.ivoryCream;
          } else if (i <= 4) {
            col = s.role === "center"
              ? (b.role === "upperSpandrel" ? PAL.ivoryBright : PAL.ivoryCream)
              : (isInner ? PAL.ivoryPure : PAL.ivoryShadow);
            hatchCol = s.role === "center" ? PAL.ivoryPure : PAL.ivoryWarm;
          } else {
            // Central flutes: stark luminous ivory spandrel panels
            col = s.role === "center"
              ? (b.role === "lowerSpandrel" ? PAL.ivoryCream : PAL.ivoryPure)
              : PAL.ivoryWarm;
            hatchCol = s.role === "center" ? PAL.ivoryPure : PAL.ivoryShadow;
          }

          drawPoly(quad, col, 250, {
            brush: "chisel",
            col: hatchCol,
            weight: 1.0,
            dist: 4.0,
            angle: 90,
            opts: { rand: 0.01 }
          });
        }
      }
    }
  }

  // --- ZONE C: UPPER ESPRESSO & CREMA FRIEZE (y = 235 to 335) ---
  for (let i = 0; i <= 7; i++) {
    let mirrorIndices = i === 7 ? [7] : [i, 14 - i];
    for (let idx of mirrorIndices) {
      let quadUpper = getFluteQuad(idx, 235, 285, 0.08, 0.92);
      let quadLower = getFluteQuad(idx, 285, 335, 0.08, 0.92);

      let colU = i === 0 ? PAL.skyJadeDark : (i <= 2 ? PAL.espRich : (i <= 5 ? PAL.espDark : PAL.espBlack));
      let colL = i === 0 ? PAL.skyJadeMid : (i <= 2 ? PAL.espAmber : (i <= 5 ? PAL.espMid : PAL.espDark));

      drawPoly(quadUpper, colU, 245, {
        brush: "chisel",
        col: i <= 2 ? PAL.espGlow : PAL.espMid,
        weight: 1.0,
        dist: 4,
        angle: 90
      });
      drawPoly(quadLower, colL, 245, {
        brush: "chisel",
        col: i <= 3 ? PAL.ivoryDeep : PAL.espRich,
        weight: 1.0,
        dist: 4,
        angle: 90
      });
    }
  }
}

// =============================================================================
// 5. HEAVY CRYSTAL BASE & STEPPED ARCHITECTURAL MOLDINGS
// =============================================================================
function drawCrystalBaseAndMoldings() {
  // The solid fluted glass base (y = 890 to 1040) acts like the rusticated podium of a skyscraper
  const baseTiers = [
    { y1: 888, y2: 925, name: "meniscusRing" },
    { y1: 925, y2: 968, name: "upperCrystal" },
    { y1: 968, y2: 1012, name: "lowerCrystal" },
    { y1: 1012, y2: 1040, name: "footRing" }
  ];

  for (let t of baseTiers) {
    for (let i = 0; i <= 7; i++) {
      let mirrorIndices = i === 7 ? [7] : [i, 14 - i];
      for (let idx of mirrorIndices) {
        let qLeft = getFluteQuad(idx, t.y1, t.y2, 0.0, 0.35);
        let qMid = getFluteQuad(idx, t.y1, t.y2, 0.35, 0.65);
        let qRight = getFluteQuad(idx, t.y1, t.y2, 0.65, 1.0);

        let cMid, cSide;
        if (t.name === "meniscusRing") {
          cMid = i <= 2 ? PAL.skyJadeGlow : (i <= 5 ? PAL.espGlow : PAL.goldMid);
          cSide = PAL.espAbyss;
        } else if (t.name === "upperCrystal") {
          cMid = i === 0 ? PAL.skyJadeBright : (i <= 3 ? PAL.skyJadeDark : PAL.ivoryCream);
          cSide = i <= 2 ? PAL.espDark : PAL.skyDeep;
        } else if (t.name === "lowerCrystal") {
          cMid = i <= 2 ? PAL.skyJadeMid : (i <= 5 ? PAL.espAmber : PAL.espBlack);
          cSide = i <= 3 ? PAL.skyAbyss : PAL.goldDeep;
        } else {
          cMid = i <= 3 ? PAL.skyJadeGlow : PAL.ivoryWarm;
          cSide = PAL.espAbyss;
        }

        drawPoly(qLeft, cSide, 240);
        drawPoly(qMid, cMid, 235, {
          brush: "chisel",
          col: cMid,
          weight: 0.9,
          dist: 3.5,
          angle: 90
        });
        drawPoly(qRight, cSide, 240);
      }
    }
  }

  // Horizontal architectural setback moldings (viewed from below, so they show dark/gold soffit undersides!)
  const setbackRings = [
    { y: 1040, thick: 10, rOut: 289, rIn: 284, col: PAL.espBlack, hi: PAL.goldBright },
    { y: 1012, thick: 8,  rOut: 282, rIn: 277, col: PAL.skyJadeDark, hi: PAL.ivoryWarm },
    { y: 968,  thick: 12, rOut: 275, rIn: 266, col: PAL.espAbyss, hi: PAL.goldLight },
    { y: 925,  thick: 9,  rOut: 264, rIn: 258, col: PAL.skyDeep, hi: PAL.jadePale },
    { y: 888,  thick: 14, rOut: 261, rIn: 252, col: PAL.espDark, hi: PAL.goldBright },
    { y: 515,  thick: 11, rOut: 237, rIn: 231, col: PAL.espMid, hi: PAL.goldLight },
    { y: 335,  thick: 11, rOut: 226, rIn: 219, col: PAL.espDark, hi: PAL.goldBright }
  ];

  for (let ring of setbackRings) {
    let pts = [];
    for (let th = 0; th <= 180; th += 6) {
      pts.push(archPt(ring.y - ring.thick * 0.5, ring.rIn, th));
    }
    for (let th = 180; th >= 0; th -= 6) {
      pts.push(archPt(ring.y + ring.thick * 0.5, ring.rOut, th));
    }
    drawPoly(pts, ring.col, 235);

    // Crisp upward-arching highlight & metallic-gold pen hatching across the setback molding
    brush.set("gold_nib", ring.hi, 0.9);
    for (let th = 4; th <= 88; th += 2) {
      let p1 = archPt(ring.y - ring.thick * 0.45, ring.rIn, th);
      let p2 = archPt(ring.y + ring.thick * 0.45, ring.rOut, th);
      symLine(p1[0], p1[1], p2[0], p2[1]);
    }

    // Continuous arch rim contours
    let upperArch = [];
    let lowerArch = [];
    for (let th = 0; th <= 90; th += 5) {
      upperArch.push(archPt(ring.y - ring.thick * 0.5, ring.rIn, th));
      lowerArch.push(archPt(ring.y + ring.thick * 0.5, ring.rOut, th));
    }
    brush.set("gold_nib", PAL.goldBright, 1.0);
    symSpline(upperArch, 0.5);
    brush.set("rotring", PAL.espAbyss, 0.85);
    symSpline(lowerArch, 0.5);
  }
}

// =============================================================================
// 6. CASCADING CREAM SPANDREL DETAILS & MARBLED FRONTIER
// =============================================================================
function drawCreamSpandrelDetails() {
  // Within each flute (y = 335 to 515), add sculpted vertical spandrel reliefs and
  // symmetrical sinking plumes of cream descending into the espresso column (y = 505 to 670)
  const plumeLengths = [55, 95, 130, 85, 155, 110, 175, 195]; // indexed by flute distance from edge 0..7

  for (let i = 0; i <= 7; i++) {
    let mirrorIndices = i === 7 ? [7] : [i, 14 - i];
    let pLen = plumeLengths[i];

    for (let idx of mirrorIndices) {
      let dTheta = 180 / N_FLUTES;
      let thL = (idx + 0.14) * dTheta;
      let thM = (idx + 0.50) * dTheta;
      let thR = (idx + 0.86) * dTheta;

      // 1. Bright ivory arched crown at top of each spandrel panel (y = 338 to 365)
      let p1 = archPt(340, getGlassRadius(340), thL);
      let p2 = archPt(336, getGlassRadius(336), thM);
      let p3 = archPt(340, getGlassRadius(340), thR);
      let p4 = archPt(370, getGlassRadius(370), thR);
      let p5 = archPt(362, getGlassRadius(362), thM);
      let p6 = archPt(370, getGlassRadius(370), thL);
      let crownCol = i === 0 ? PAL.jadePale : (i <= 2 ? PAL.ivoryWarm : PAL.ivoryPure);
      drawPoly([p1, p2, p3, p4, p5, p6], crownCol, 240);

      // 2. Cascading gothic/art-deco cream stalactite plume below y = 515
      let yStart = 512;
      let yMid = 512 + pLen * 0.55;
      let yTip = 512 + pLen;

      let thInnerL = (idx + 0.25) * dTheta;
      let thInnerR = (idx + 0.75) * dTheta;

      let plumePts = [
        archPt(yStart, getGlassRadius(yStart), thL),
        archPt(yStart - 4, getGlassRadius(yStart), thM),
        archPt(yStart, getGlassRadius(yStart), thR),
        archPt(yMid, getGlassRadius(yMid), thInnerR),
        archPt(yTip, getGlassRadius(yTip), thM),
        archPt(yMid, getGlassRadius(yMid), thInnerL)
      ];

      let plumeWash = i === 0 ? PAL.skyJadeMid : (i <= 2 ? PAL.ivoryShadow : PAL.ivoryCream);
      let plumeHatch = i === 0 ? PAL.jadeIce : (i <= 2 ? PAL.ivoryWarm : PAL.ivoryBright);

      drawPoly(plumePts, plumeWash, 225, {
        brush: "marker",
        col: plumeHatch,
        weight: 0.85,
        dist: 3.5,
        angle: 90
      });

      // Secondary finer cream tendril extending deeper into the espresso
      let yDeepTip = yTip + 48;
      let tendrilPts = [
        archPt(yMid + 10, getGlassRadius(yMid + 10), (idx + 0.36) * dTheta),
        archPt(yTip, getGlassRadius(yTip), (idx + 0.58) * dTheta),
        archPt(yDeepTip, getGlassRadius(yDeepTip), thM),
        archPt(yTip, getGlassRadius(yTip), (idx + 0.42) * dTheta)
      ];
      drawPoly(tendrilPts, i <= 2 ? PAL.espAmber : PAL.ivoryShadow, 195);

      // Crisp gold & warm ivory contour around each cascading cream plume
      brush.set("gold_nib", i <= 1 ? PAL.goldMid : PAL.ivoryPure, 0.75);
      brush.spline([plumePts[0], plumePts[5], plumePts[4]], 0.4);
      brush.spline([plumePts[2], plumePts[3], plumePts[4]], 0.4);

      // 3. Upward espresso dark gothic cusp intruding into the bottom of the cream spandrel
      for (let side of [0.12, 0.88]) {
        let thCusp = (idx + side) * dTheta;
        let cBaseL = archPt(515, getGlassRadius(515), thCusp - 1.1);
        let cBaseR = archPt(515, getGlassRadius(515), thCusp + 1.1);
        let cApex = archPt(455 - (i % 2) * 18, getGlassRadius(455), thCusp);
        drawPoly([cBaseL, cApex, cBaseR], PAL.espDark, 230);
      }
    }
  }
}

// =============================================================================
// 7. SUBMERGED ICE & UPPER RIM CROWN
// =============================================================================
function drawUpperRimAndSubmergedIce() {
  // Submerged ice facets visible behind the upper flutes (y = 240 to 335)
  for (let i = 1; i <= 7; i++) {
    let mirrorIndices = i === 7 ? [7] : [i, 14 - i];
    for (let idx of mirrorIndices) {
      let dTheta = 180 / N_FLUTES;
      let th1 = (idx + 0.15) * dTheta;
      let th2 = (idx + 0.85) * dTheta;
      let thM = (idx + 0.5) * dTheta;

      let yTop = 246 + (i % 2) * 8;
      let yMid = 282 + (i % 3) * 6;
      let yBot = 324 - (i % 2) * 7;

      // Upper crystal facet inside the flute
      let facetU = [
        archPt(yTop, getGlassRadius(yTop), th1),
        archPt(yTop - 5, getGlassRadius(yTop), thM),
        archPt(yTop, getGlassRadius(yTop), th2),
        archPt(yMid, getGlassRadius(yMid), thM)
      ];
      let fCol = i <= 2 ? PAL.skyJadeBright : (i <= 5 ? PAL.ivoryWarm : PAL.goldLight);
      drawPoly(facetU, fCol, 190);

      // Lower crystal facet inside the flute
      let facetL = [
        archPt(yTop, getGlassRadius(yTop), th1),
        archPt(yMid, getGlassRadius(yMid), thM),
        archPt(yBot, getGlassRadius(yBot), th2),
        archPt(yBot + 4, getGlassRadius(yBot), th1)
      ];
      drawPoly(facetL, i <= 3 ? PAL.espAmber : PAL.ivoryShadow, 175);

      // Gold geometric bevel line across the submerged ice
      brush.set("gold_nib", PAL.goldBright, 0.7);
      brush.line(facetU[0][0], facetU[0][1], facetU[3][0], facetU[3][1]);
      brush.line(facetU[2][0], facetU[2][1], facetU[3][0], facetU[3][1]);
    }
  }

  // Moulded double-ring crystal lip at the top of the glass (y = 212 to 245)
  const rimBands = [
    { y1: 234, y2: 246, r1: 212, r2: 215, col: PAL.espAbyss, hatch: PAL.goldDeep },
    { y1: 222, y2: 234, r1: 215, r2: 213, col: PAL.ivoryCream, hatch: PAL.goldBright },
    { y1: 212, y2: 222, r1: 213, r2: 215, col: PAL.skyJadeMid, hatch: PAL.ivoryPure }
  ];

  for (let rb of rimBands) {
    let pts = [];
    for (let th = 0; th <= 180; th += 5) {
      pts.push(archPt(rb.y1, rb.r1, th));
    }
    for (let th = 180; th >= 0; th -= 5) {
      pts.push(archPt(rb.y2, rb.r2, th));
    }
    drawPoly(pts, rb.col, 240, {
      brush: "gold_nib",
      col: rb.hatch,
      weight: 0.75,
      dist: 3.2,
      angle: 90
    });
  }

  // Razor-sharp gold & ivory rim ellipses
  for (let offset of [-1, 2, 11, 22, 32]) {
    let yR = 213 + offset;
    let rR = getGlassRadius(yR);
    let curve = [];
    for (let th = 0; th <= 90; th += 4) {
      curve.push(archPt(yR, rR, th));
    }
    let col = offset === 2 ? PAL.ivoryPure : (offset === 11 ? PAL.goldSpark : PAL.goldBright);
    brush.set("gold_nib", col, offset === 2 ? 1.2 : 0.95);
    symSpline(curve, 0.5);
  }
}

// =============================================================================
// 8. STACKED ICE CUBE SETBACK TERRACES (The Ziggurat Spire, y = 38 to 235)
// =============================================================================
function drawIceSetbackTerraces() {
  // Helper to render a single hyperrealist 3D crystal ice block seen from below
  // Centered at (CX - dx, yTop..yBot) and mirrored if dx > 0
  function drawSymmetricIceBlock(dx, yTop, yBot, halfW, archLift, tierTone) {
    let offsets = dx === 0 ? [0] : [-dx, dx];

    for (let ox of offsets) {
      let cx = CX + ox;
      let xL = cx - halfW;
      let xML = cx - halfW * 0.38;
      let xMR = cx + halfW * 0.38;
      let xR = cx + halfW;

      // Because we view from below, each block's top and bottom edges arch upward,
      // and we see a prominent underside soffit plane!
      let soffitH = Math.max(10, (yBot - yTop) * 0.24);

      let pTL  = [xL + 2,  yTop + archLift * 0.6];
      let pTML = [xML,     yTop];
      let pTMR = [xMR,     yTop];
      let pTR  = [xR - 2,  yTop + archLift * 0.6];

      let pBL  = [xL,      yBot + archLift * 0.5];
      let pBML = [xML,     yBot - archLift * 0.3];
      let pBMR = [xMR,     yBot - archLift * 0.3];
      let pBR  = [xR,      yBot + archLift * 0.5];

      // Underside soffit recessed inner points
      let pSL  = [xL + 7,  yBot + soffitH];
      let pSML = [xML + 2, yBot + soffitH - archLift * 0.25];
      let pSMR = [xMR - 2, yBot + soffitH - archLift * 0.25];
      let pSR  = [xR - 7,  yBot + soffitH];

      let isLeftSide = ox < 0;
      let isRightSide = ox > 0;

      // Determine facet colors for high-contrast crystal refraction
      let colCenter = tierTone === "apex" ? PAL.ivoryPure : (tierTone === "upper" ? PAL.ivoryBright : PAL.ivoryCream);
      let colOuter = PAL.skyJadeBright;
      let colInner = PAL.espAmber;
      let colLeft = isLeftSide ? colOuter : (isRightSide ? colInner : PAL.jadeIce);
      let colRight = isRightSide ? colOuter : (isLeftSide ? colInner : PAL.jadeIce);
      let colSoffit = tierTone === "base" ? PAL.espDark : PAL.skyJadeDark;

      // 1. Left vertical bevel face
      drawPoly([pTL, pTML, pBML, pBL], colLeft, 235, {
        brush: "chisel",
        col: isLeftSide ? PAL.jadePale : PAL.goldMid,
        weight: 0.9,
        dist: 3.5,
        angle: 90
      });

      // 2. Center front main face
      drawPoly([pTML, pTMR, pBMR, pBML], colCenter, 245, {
        brush: "chisel",
        col: PAL.ivoryPure,
        weight: 0.95,
        dist: 3.5,
        angle: 90
      });

      // 3. Right vertical bevel face
      drawPoly([pTMR, pTR, pBR, pBMR], colRight, 235, {
        brush: "chisel",
        col: isRightSide ? PAL.jadePale : PAL.goldMid,
        weight: 0.9,
        dist: 3.5,
        angle: 90
      });

      // 4. Underside soffit shelf (seen from below!)
      drawPoly([pBL, pBML, pBMR, pBR, pSR, pSMR, pSML, pSL], colSoffit, 245, {
        brush: "gold_nib",
        col: PAL.goldMid,
        weight: 0.7,
        dist: 2.8,
        angle: 0
      });

      // 5. Internal crystal refraction shards (espresso & jade veins inside the ice)
      let shard1 = [
        [lerp(xML, xMR, 0.15), lerp(yTop, yBot, 0.18)],
        [lerp(xML, xMR, 0.85), lerp(yTop, yBot, 0.12)],
        [lerp(xML, xMR, 0.55), lerp(yTop, yBot, 0.52)],
        [lerp(xML, xMR, 0.20), lerp(yTop, yBot, 0.45)]
      ];
      drawPoly(shard1, PAL.skyJadeMid, 165);

      let shard2 = [
        [lerp(xML, xMR, 0.22), lerp(yTop, yBot, 0.58)],
        [lerp(xML, xMR, 0.78), lerp(yTop, yBot, 0.50)],
        [lerp(xML, xMR, 0.88), lerp(yTop, yBot, 0.85)],
        [lerp(xML, xMR, 0.12), lerp(yTop, yBot, 0.88)]
      ];
      drawPoly(shard2, tierTone === "base" ? PAL.espRich : PAL.goldDeep, 175);

      // 6. Fine metallic-gold pen hatching along top rim and bottom soffit bevel
      brush.set("gold_nib", PAL.goldBright, 0.85);
      for (let t = 0; t <= 1; t += 0.08) {
        let hx = lerp(xL + 2, xR - 2, t);
        let hy = yTop + Math.abs(t - 0.5) * archLift * 1.1;
        brush.line(hx, hy, hx, hy + 9);

        let bx = lerp(xL, xR, t);
        let by = yBot + (Math.abs(t - 0.5) - 0.25) * archLift * 0.9;
        brush.line(bx, by - 5, bx, by + 5);
      }

      // 7. Crisp architectural ice bevel outlines in bright gold & pure ivory
      brush.set("gold_nib", PAL.goldSpark, 1.05);
      brush.line(pTL[0], pTL[1], pTML[0], pTML[1]);
      brush.line(pTML[0], pTML[1], pTMR[0], pTMR[1]);
      brush.line(pTMR[0], pTMR[1], pTR[0], pTR[1]);

      brush.line(pBL[0], pBL[1], pBML[0], pBML[1]);
      brush.line(pBML[0], pBML[1], pBMR[0], pBMR[1]);
      brush.line(pBMR[0], pBMR[1], pBR[0], pBR[1]);

      // Vertical pilaster arrises of the ice cube
      brush.set("gold_nib", PAL.ivoryPure, 1.1);
      brush.line(pTML[0], pTML[1], pBML[0], pBML[1]);
      brush.line(pTMR[0], pTMR[1], pBMR[0], pBMR[1]);
      brush.set("gold_nib", PAL.goldBright, 0.85);
      brush.line(pTL[0], pTL[1], pBL[0], pBL[1]);
      brush.line(pTR[0], pTR[1], pBR[0], pBR[1]);
    }
  }

  // Render back-to-front / outer-to-inner for true architectural setback ziggurat stacking:
  // Terrace Level 1 (Base above rim, y = 152 to 218)
  drawSymmetricIceBlock(148, 164, 218, 44, 10, "base");
  drawSymmetricIceBlock(78,  154, 214, 48, 12, "base");
  drawSymmetricIceBlock(0,   148, 212, 54, 14, "base");

  // Terrace Level 2 (Second setback tier, y = 104 to 162)
  drawSymmetricIceBlock(102, 114, 162, 36, 9,  "mid");
  drawSymmetricIceBlock(46,  104, 158, 42, 11, "mid");
  drawSymmetricIceBlock(0,   98,  155, 46, 12, "mid");

  // Terrace Level 3 (Third setback tier, y = 64 to 110)
  drawSymmetricIceBlock(52,  72,  112, 30, 8,  "upper");
  drawSymmetricIceBlock(0,   62,  106, 38, 10, "upper");

  // Terrace Level 4 (Crowning keystone spire, y = 34 to 70)
  drawSymmetricIceBlock(0,   34,  70,  25, 8,  "apex");
}

// =============================================================================
// 9. FLUTED PILASTER HIGHLIGHTS & METALLIC-GOLD PEN HATCHING
// =============================================================================
function drawPilasterGoldAndHighlights() {
  let dTheta = 180 / N_FLUTES;

  // Vertical pilaster ridges between adjacent flutes (i = 0 to N_FLUTES)
  for (let i = 0; i <= 7; i++) {
    let th = i * dTheta;

    // Draw continuous vertical ridge lines segmented across the architectural tiers
    const tiers = [
      { y1: 235, y2: 335, w: 1.0, col: PAL.goldBright },
      { y1: 335, y2: 515, w: 1.15, col: PAL.ivoryPure },
      { y1: 515, y2: 888, w: 0.95, col: i <= 2 ? PAL.goldMid : PAL.goldBright },
      { y1: 888, y2: 1040, w: 1.05, col: PAL.goldLight }
    ];

    for (let t of tiers) {
      let pts = [];
      let steps = 8;
      for (let s = 0; s <= steps; s++) {
        let y = lerp(t.y1, t.y2, s / steps);
        pts.push(archPt(y, getGlassRadius(y), th));
      }

      // Dark shadow line immediately adjacent to the glass ridge
      let shadowPts = pts.map(p => [p[0] + 2.2, p[1]]);
      brush.set("rotring", PAL.espAbyss, 0.85);
      symSpline(shadowPts, 0.3);

      // Metallic-gold arris line
      brush.set("gold_nib", t.col, t.w);
      symSpline(pts, 0.3);
    }

    // Fine diagonal metallic-gold pen hatching hugging each vertical pilaster ridge
    if (i >= 1 && i <= 7) {
      brush.set("gold_nib", i <= 3 ? PAL.goldMid : PAL.goldBright, 0.55);
      for (let y = 248; y <= 1025; y += 6.5) {
        // Concentrate gold hatching around rims, spandrel borders, and pilaster capitals
        let nearRim = (y < 275) || (y > 315 && y < 365) || (y > 490 && y < 545) || (y > 860 && y < 935) || (y > 1000);
        if (nearRim || (Math.floor(y / 6.5) % 2 === 0)) {
          let r = getGlassRadius(y);
          let p1 = archPt(y, r, th);
          let p2 = archPt(y + 4, r, th + 2.4);
          symLine(p1[0], p1[1], p2[0], p2[1]);
        }
      }
    }
  }

  // Vertical continuous specular highlight ribbons down the center of key flutes
  for (let i of [1, 3, 5, 7]) {
    let thCenter = (i + 0.5) * dTheta;

    // Cream spandrel vertical specular bar
    let pTopC = archPt(342, getGlassRadius(342), thCenter);
    let pBotC = archPt(506, getGlassRadius(506), thCenter);
    brush.set("chisel", PAL.ivoryPure, i === 7 ? 1.4 : 0.9);
    symLine(pTopC[0], pTopC[1], pBotC[0], pBotC[1]);

    // Espresso shaft vertical specular thread
    let pTopE = archPt(528, getGlassRadius(528), thCenter);
    let pBotE = archPt(878, getGlassRadius(878), thCenter);
    brush.set("gold_nib", i === 1 ? PAL.jadePale : PAL.goldLight, 0.85);
    symLine(pTopE[0], pTopE[1], pBotE[0], pBotE[1]);
  }
}

// =============================================================================
// 10. METICULOUS CONDENSATION STREAKS & BEADS
// =============================================================================
function drawCondensationPilastersAndBeads() {
  let dTheta = 180 / N_FLUTES;

  // Helper to render a single hyperrealist 3D condensation bead (symmetrically mirrored across CX)
  function drawSymmetricBead(x, y, rx, ry, zone) {
    let positions = Math.abs(x - CX) < 2 ? [CX] : [x, 2 * CX - x];

    for (let bx of positions) {
      // 1. Cast shadow immediately above/behind the droplet (since light/view is from below + rim)
      let shPts = [];
      for (let a = 0; a < 360; a += 45) {
        let rad = (a * Math.PI) / 180;
        shPts.push([bx + Math.cos(rad) * rx * 1.05, (y - ry * 0.45) + Math.sin(rad) * ry * 0.95]);
      }
      drawPoly(shPts, PAL.espAbyss, 215);

      // 2. Main droplet body (refracting inverted tone of the zone)
      let bodyPts = [];
      for (let a = 0; a < 360; a += 36) {
        let rad = (a * Math.PI) / 180;
        // Slight teardrop elongation at bottom
        let stretch = Math.sin(rad) > 0 ? 1.18 : 0.92;
        bodyPts.push([bx + Math.cos(rad) * rx, y + Math.sin(rad) * ry * stretch]);
      }
      let bodyCol = zone === "cream"
        ? PAL.ivoryShadow
        : (zone === "edge" ? PAL.skyJadeBright : PAL.espAmber);
      drawPoly(bodyPts, bodyCol, 230);

      // 3. Internal warm/jade lens core in lower half of bead
      let corePts = [];
      for (let a = 0; a < 360; a += 45) {
        let rad = (a * Math.PI) / 180;
        corePts.push([bx + Math.cos(rad) * rx * 0.62, (y + ry * 0.22) + Math.sin(rad) * ry * 0.55]);
      }
      let coreCol = zone === "cream" ? PAL.ivoryPure : (zone === "edge" ? PAL.jadePale : PAL.goldBright);
      drawPoly(corePts, coreCol, 235);

      // 4. Crisp metallic-gold & pure ivory lower crescent meniscus highlight
      brush.set("gold_nib", PAL.goldSpark, 0.9);
      brush.line(bx - rx * 0.65, y + ry * 0.65, bx, y + ry * 0.95);
      brush.line(bx, y + ry * 0.95, bx + rx * 0.65, y + ry * 0.65);

      // Pinpoint upper-center specular spark
      brush.set("gold_nib", PAL.ivoryPure, 1.05);
      brush.line(bx - 0.8, y - ry * 0.25, bx + 0.8, y - ry * 0.25);
    }
  }

  // A. FLUTED VERTICAL CONDENSATION STREAKS (Running like architectural pilasters)
  for (let i = 1; i <= 7; i++) {
    let thStreak = (i + 0.36) * dTheta;
    let streakTop = 252 + (i % 3) * 14;
    let streakBot = 865 - (i % 2) * 28;

    // Draw narrow wet weeping channel down the flute
    let channelPtsL = [];
    let channelPtsR = [];
    for (let y = streakTop; y <= streakBot; y += 22) {
      let r = getGlassRadius(y);
      let wobble = Math.sin(y * 0.045 + i) * 0.45;
      channelPtsL.push(archPt(y, r, thStreak + wobble - 0.45));
      channelPtsR.push(archPt(y, r, thStreak + wobble + 0.45));
    }

    // Dark wet edge of the condensation track
    brush.set("rotring", PAL.espAbyss, 0.75);
    symSpline(channelPtsL, 0.4);

    // Bright gold/ivory wet specular edge of the condensation track
    brush.set("gold_nib", i <= 2 ? PAL.jadePale : PAL.goldLight, 0.75);
    symSpline(channelPtsR, 0.4);

    // Terminal heavy weeping teardrop bead at the bottom of each streak
    let pTerm = archPt(streakBot, getGlassRadius(streakBot), thStreak);
    drawSymmetricBead(pTerm[0], pTerm[1], 4.8, 6.8, i <= 1 ? "edge" : "espresso");
  }

  // B. METICULOUSLY RENDERED CONDENSATION BEADS ALONG EVERY FLUTE PILASTER
  for (let i = 0; i <= 7; i++) {
    let thCenter = (i + 0.5) * dTheta;
    let thLeft = (i + 0.22) * dTheta;
    let thRight = (i + 0.78) * dTheta;

    // Primary architectural bead column down the center of each flute
    for (let y = 248; y <= 955; y += 26) {
      // Deterministic rhythmic spacing & sizing
      let nVal = noise(i * 3.7, y * 0.03);
      let yActual = y + (nVal - 0.5) * 10;
      let rGlass = getGlassRadius(yActual);
      let pt = archPt(yActual, rGlass, thCenter);

      let zone = i === 0 ? "edge" : (yActual >= 335 && yActual <= 515 ? "cream" : "espresso");
      let rx = map(nVal, 0, 1, 2.4, 5.2);
      let ry = rx * map(nVal, 0, 1, 1.1, 1.45);

      drawSymmetricBead(pt[0], pt[1], rx, ry, zone);

      // Flanking micro-beads along the flute edges for hyperrealist density
      if (i >= 1) {
        let yMicro1 = yActual + 11;
        let pM1 = archPt(yMicro1, getGlassRadius(yMicro1), thLeft);
        drawSymmetricBead(pM1[0], pM1[1], 1.8, 2.2, zone);

        let yMicro2 = yActual - 9;
        let pM2 = archPt(yMicro2, getGlassRadius(yMicro2), thRight);
        drawSymmetricBead(pM2[0], pM2[1], 2.0, 2.5, zone);
      }
    }
  }
}

