// 11. FINAL HIGH-CONTRAST SPECULAR SPARKS & ARCHITECTURAL FRAMING
// =============================================================================
function drawFinalGlamourAccents() {
  // Intense ivory & metallic-gold starburst highlights at key architectural vertices
  const starPts = [
    [CX, 34, 16],       // Apex of the crowning ice cube
    [CX - 38, 62, 11],  // Terrace 3 corner
    [CX - 46, 98, 12],  // Terrace 2 corner
    [CX - 54, 148, 13], // Terrace 1 corner
    [CX, 200, 18],      // Center front of top crystal rim arch
    [CX - 115, 207, 12],// Mid-side of top crystal rim arch
    [CX, 323, 15],      // Center front of upper spandrel molding
    [CX, 502, 15],      // Center front of lower spandrel molding
    [CX, 875, 16]       // Center front of crystal base meniscus
  ];

  for (let s of starPts) {
    let sx = s[0];
    let sy = s[1];
    let r = s[2];

    // Vertical & horizontal razor-sharp specular cross
    brush.set("gold_nib", PAL.goldSpark, 1.15);
    symLine(sx, sy - r * 1.4, sx, sy + r * 1.4);
    symLine(sx - r, sy, sx + r, sy);

    // Diagonal gold flare rays
    brush.set("gold_nib", PAL.goldBright, 0.75);
    symLine(sx - r * 0.55, sy - r * 0.55, sx + r * 0.55, sy + r * 0.55);
    symLine(sx - r * 0.55, sy + r * 0.55, sx + r * 0.55, sy - r * 0.55);
  }

  // Outer silhouette razor-sharp gold & jade rim highlight along the entire tower profile
  let leftProfile = [];
  for (let y = 215; y <= 1040; y += 15) {
    leftProfile.push(archPt(y, getGlassRadius(y), 0));
  }
  brush.set("gold_nib", PAL.goldBright, 1.1);
  symSpline(leftProfile, 0.25);

  let innerRimProfile = [];
  for (let y = 215; y <= 1040; y += 15) {
    innerRimProfile.push(archPt(y, getGlassRadius(y) - 3.5, 2));
  }
  brush.set("gold_nib", PAL.jadePale, 0.85);
  symSpline(innerRimProfile, 0.25);
}

