  // -------------------------------------------------------------------------
  drawKitchenUnderpainting();

  // -------------------------------------------------------------------------
  // 2. MELTING SILHOUETTE OF THE CAT (EAR, HEAD, EYE, NECK IN WATERCOLOR)
  // -------------------------------------------------------------------------
  drawMeltingCatBase();

  // -------------------------------------------------------------------------
  // 3. OVERLAPPING WATERCOLOR BOKEH DISCS (APRICOT, SAGE, BUTTER-CREAM, COOL SLATE)
  //    Wet-in-wet blooms with hard dried caustic rims (optical lens aberration)
  // -------------------------------------------------------------------------
  drawBokehField();

  // -------------------------------------------------------------------------
  // 4. OUT-OF-FOCUS EYE GLIMMER & SOFT-TO-SHARP FUR GRADATION
  // -------------------------------------------------------------------------
  drawBlurredEyeAndMidFur();

  // -------------------------------------------------------------------------
  // 5. TACK-SHARP FOCAL PLANE: NASAL BRIDGE, WET NOSE LEATHER & WHISKER PADS
  // -------------------------------------------------------------------------
  drawSharpMuzzleAndNose();

  // -------------------------------------------------------------------------
  // 6. VIBRISSAE (WHISKERS): FROM BLURRED GHOSTS TO TACK-SHARP FOREGROUND ARCS
  // -------------------------------------------------------------------------
  drawWhiskersAndMicroDetails();

  noLoop();
}

// Helper: Draw a filled watercolor polygon from an array of [x, y] points
function fillShapePoints(pts, curvature = 0.35) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

