// =============================================================================
// STAGE 4: OUT-OF-FOCUS EYE GLIMMER & GRADED FUR TRANSITION (WASH -> HAIR)
// =============================================================================
function drawBlurredEyeAndMidFur() {
  brush.noStroke();

  // Out-of-focus feline eye in profile at (830, 622)
  // Soft dark orbital socket & upper lash shadow wash
  brush.fill("#263340", 115);
  brush.fillBleed(0.28, "out");
  brush.fillTexture(0.65, 0.55);
  fillShapePoints([
    [792, 608], [825, 590], [868, 608], [858, 646], [812, 650]
  ], 0.4);

  // Glowing cool sage-celadon & amber-cream corneal dome (blurred)
  brush.fill("#8fb39e", 135);
  brush.fillBleed(0.22, "in");
  brush.fillTexture(0.6, 0.5);
  brush.circle(822, 624, 24, 0.12);

  brush.fill("#d9e0b4", 120);
  brush.fillBleed(0.2, "in");
  brush.circle(816, 626, 16, 0.1);

  // Soft vertical elliptical pupil wash
  brush.fill("#18222c", 140);
  brush.fillBleed(0.2, "out");
  fillShapePoints([
    [814, 606], [822, 616], [820, 638], [811, 632]
  ], 0.35);

  // Blurred window catchlight on the cornea
  brush.fill("#f7fbff", 165);
  brush.fillBleed(0.18, "out");
  brush.circle(809, 614, 9, 0.1);
  brush.fill("#fdf8de", 140);
  brush.circle(814, 618, 6, 0.1);

  // Pale tabby eyeline spectacle wash around the eye
  brush.fill("#e8eef2", 95);
  brush.fillBleed(0.28, "out");
  fillShapePoints([
    [795, 645], [835, 652], [875, 638], [865, 662], [810, 665]
  ], 0.35);

  brush.noFill();

  // -------------------------------------------------------------------------
  // FUR GRADATION ZONE 1: Far Diffuse Strokes (Ear base, Brow, Rear Cheek, Jaw)
  // Using custom "soft_bloom" and "charcoal" so fur dissolves into bokeh
  // -------------------------------------------------------------------------
  const diffuseZones = [
    // Brow and forehead dissolving up-right toward ear
    { cx: 865, cy: 525, rx: 85, ry: 55, ang: -38, len: 34, count: 95, col: "#364554", w: 1.4 },
    { cx: 885, cy: 540, rx: 80, ry: 50, ang: -35, len: 30, count: 80, col: "#d8a480", w: 1.3 },
    // Ear furnishings (butter-cream & apricot fluff melting into bokeh)
    { cx: 985, cy: 365, rx: 55, ry: 75, ang: -145, len: 42, count: 75, col: "#f6ebd0", w: 1.6 },
    { cx: 1025, cy: 320, rx: 45, ry: 65, ang: -130, len: 38, count: 60, col: "#ebad88", w: 1.5 },
    // Rear cheek tabby swirls (cool slate, pewter, and warm buff)
    { cx: 885, cy: 715, rx: 95, ry: 75, ang: 18, len: 36, count: 120, col: "#2e3c4a", w: 1.3 },
    { cx: 865, cy: 695, rx: 85, ry: 65, ang: 14, len: 32, count: 110, col: "#92a3b0", w: 1.2 },
    { cx: 845, cy: 745, rx: 75, ry: 55, ang: 22, len: 28, count: 95, col: "#d59f7c", w: 1.2 },
    // Lower jaw & neck transition
    { cx: 835, cy: 845, rx: 90, ry: 45, ang: 28, len: 34, count: 100, col: "#cdd9e0", w: 1.3 },
    { cx: 785, cy: 835, rx: 65, ry: 35, ang: 25, len: 26, count: 85, col: "#7c909e", w: 1.1 }
  ];

  for (let z of diffuseZones) {
    brush.set("soft_bloom", z.col, z.w);
    for (let i = 0; i < z.count; i++) {
      let a = random(360);
      let r = sqrt(random()) * 1.0;
      let x = z.cx + cos(a) * r * z.rx;
      let y = z.cy + sin(a) * r * z.ry;
      let dir = z.ang + random(-14, 14);
      let l = z.len * random(0.65, 1.25);
      let mx = x + cos(dir) * l * 0.5 + random(-3, 3);
      let my = y + sin(dir) * l * 0.5 + random(-3, 3);
      let ex = x + cos(dir) * l;
      let ey = y + sin(dir) * l;
      brush.spline([[x, y, 0.3], [mx, my, 0.9], [ex, ey, 0.1]], 0.35);
    }
  }

  // -------------------------------------------------------------------------
  // FUR GRADATION ZONE 2: Mid-Focus Fur (Upper Nasal Bridge, Mid-Cheek, Mid-Chin)
  // Grading from soft "2B" / "cpencil" into finer directional hairs
  // -------------------------------------------------------------------------
  // Upper-to-mid nasal bridge (x: 700..810, y: 565..645)
  const bridgeColors = ["#283442", "#465666", "#c9926e", "#dfc0a3", "#8d9eab", "#e6eef2"];
  for (let i = 0; i < 380; i++) {
    let t = random(); // 0 = near stop (blurred), 1 = closer to nose tip (sharper)
    let bx = lerp(805, 685, t);
    let by = lerp(568, 652, t);
    // Spread across the width of the bridge
    let depthOffset = random(0, 1) * lerp(65, 28, t);
    let x = bx + depthOffset * 0.85;
    let y = by + depthOffset * 0.52;

    let col = random(bridgeColors);
    // Dark tabby banding across the bridge
    if (sin(t * 720) > 0.25 && random() < 0.65) {
      col = random() < 0.6 ? "#222c38" : "#3a4959";
    } else if (depthOffset < 6 && random() < 0.55) {
      // Sunlit dorsal ridge highlight hairs
      col = random() < 0.6 ? "#f5f2e4" : "#e3ecf0";
    }

    let bName = t < 0.45 ? "cpencil" : (t < 0.75 ? "2B" : "HB");
    let w = lerp(1.15, 0.48, t) * random(0.8, 1.2);
    let len = lerp(22, 9, t) * random(0.75, 1.2);
    let dir = -35 + depthOffset * 0.35 + random(-8, 8);

    brush.set(bName, col, w);
    let x2 = x + cos(dir) * len;
    let y2 = y + sin(dir) * len;
    brush.line(x, y, x2, y2);
  }

  // Mid-cheek transition zone (x: 725..845, y: 650..795)
  const cheekColors = ["#2c3947", "#4c5d6e", "#8fa0ad", "#d49f7d", "#e8c8ad", "#dce5eb", "#f2f6f8"];
  for (let i = 0; i < 520; i++) {
    let u = random(); // 0 = front of cheek (sharper), 1 = rear of cheek (softer)
    let v = random(); // 0 = upper infraorbital, 1 = lower cheek near mouth corner
    let x = lerp(715, 845, u) + random(-10, 10);
    let y = lerp(655, 795, v) + u * 18;

    let col = random(cheekColors);
    // Subtle dark tabby cheek stripes curving backward
    let stripeWave = sin((y - 660) * 4.2 - u * 90);
    if (stripeWave > 0.35 && random() < 0.65) {
      col = random() < 0.55 ? "#242f3c" : "#3e4e5e";
    } else if (v > 0.65 && random() < 0.6) {
      col = random() < 0.5 ? "#e9f0f4" : "#f5f8fa";
    }

    let bName = u > 0.55 ? "cpencil" : (u > 0.25 ? "2B" : "HB");
    let w = lerp(0.5, 1.25, u) * random(0.85, 1.15);
    let len = lerp(11, 25, u) * random(0.8, 1.2);
    let dir = lerp(-10, 24, v) + u * 12 + random(-9, 9);

    brush.set(bName, col, w);
    let mx = x + cos(dir - 4) * len * 0.5;
    let my = y + sin(dir - 4) * len * 0.5;
    let ex = x + cos(dir) * len;
    let ey = y + sin(dir) * len;
    brush.spline([[x, y, 0.7], [mx, my, 1.0], [ex, ey, 0.2]], 0.3);
  }
}

// =============================================================================
// STAGE 5: TACK-SHARP FOCAL PLANE — NOSE LEATHER, WHISKER PADS & CHIN EDGE
// =============================================================================
function drawSharpMuzzleAndNose() {
  brush.noStroke();

  // -------------------------------------------------------------------------
  // A. THREE-DIMENSIONAL WATERCOLOR MODELING OF THE NOSE & WHISKER PAD
  // -------------------------------------------------------------------------
  // Warm terracotta-rose nose leather (rhinarium) base
  brush.fill("#bf7167", 155);
  brush.fillBleed(0.06, "in");
  brush.fillTexture(0.55, 0.45);
  fillShapePoints([
    [638, 684], [625, 691], [620, 699], [624, 710],
    [635, 721], [645, 731], [662, 718], [668, 698], [654, 687]
  ], 0.25);

  // Deeper coral-umber shadow on lower/interior plane of nose leather
  brush.fill("#8c4843", 140);
  brush.fillBleed(0.05, "in");
  fillShapePoints([
    [624, 706], [636, 721], [645, 731], [662, 718], [665, 704], [642, 702]
  ], 0.25);

  // Dark slate-charcoal pigment rim around the tabby nose leather & nostril wing
  brush.fill("#232b35", 165);
  brush.fillBleed(0.04, "in");
  fillShapePoints([
    [636, 682], [656, 686], [670, 698], [664, 718],
    [656, 714], [661, 699], [650, 690], [634, 687]
  ], 0.25);

  // Deep nostril aperture (nares) shadow
  brush.fill("#12171f", 210);
  brush.fillBleed(0.02, "in");
  fillShapePoints([
    [636, 702], [648, 697], [659, 704], [656, 716], [643, 715], [635, 709]
  ], 0.25);

  // Plump whisker pad sculptural shading:
  // Cool daylight shadow along the lower rounding of the upper lip overhang
  brush.fill("#8296a6", 90);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.5, 0.4);
  fillShapePoints([
    [650, 748], [665, 772], [695, 792], [745, 807],
    [795, 806], [785, 788], [725, 782], [672, 760]
  ], 0.3);

  // Warm butter-cream & apricot subsurface scatter on upper whisker pad swell
  brush.fill("#f7eed2", 110);
  brush.fillBleed(0.1, "in");
  fillShapePoints([
    [658, 718], [715, 712], [755, 728], [745, 762], [672, 752]
  ], 0.35);

  // Dark mouth line & lip cleft shadow tucking under the whisker pad
  brush.fill("#222a34", 160);
  brush.fillBleed(0.05, "in");
  fillShapePoints([
    [662, 772], [692, 791], [735, 805], [788, 809],
    [775, 816], [725, 812], [685, 798], [664, 780]
  ], 0.25);

  brush.noFill();

  // -------------------------------------------------------------------------
  // B. TACK-SHARP SHORT VELVETY FUR ON THE ANTERIOR NASAL BRIDGE
  // -------------------------------------------------------------------------
  for (let i = 0; i < 420; i++) {
    let t = random(); // along the sharp lower bridge (638, 684) to (705, 638)
    let bx = lerp(638, 705, t);
    let by = lerp(684, 638, t);
    let side = random(0, 1) * lerp(22, 34, t);
    let x = bx + side * 0.82;
    let y = by + side * 0.56;

    // Agouti hair color selection
    let col = "#303c4a";
    let r = random();
    if (side < 4.5) {
      // Crisp sunlit profile edge hairs catching cool daylight
      col = r < 0.55 ? "#f8fafb" : (r < 0.8 ? "#e8dec3" : "#6c7d8c");
    } else if (r < 0.32) {
      col = "#1e2630";
    } else if (r < 0.62) {
      col = "#c98f6b";
    } else if (r < 0.85) {
      col = "#8494a1";
    } else {
      col = "#e6edf2";
    }

    let bName = r < 0.4 ? "rotring" : (r < 0.75 ? "2H" : "HB");
    let w = lerp(0.26, 0.48, t) * random(0.8, 1.15);
    let len = lerp(4.5, 10.5, t) * random(0.8, 1.2);
    let dir = -34 + side * 0.45 + random(-6, 6);

    brush.set(bName, col, w);
    brush.line(x, y, x + cos(dir) * len, y + sin(dir) * len);
  }

  // Tiny individual profile guard hairs projecting slightly off the nasal bridge into the bokeh
  for (let i = 0; i < 65; i++) {
    let t = random();
    let x = lerp(640, 725, t);
    let y = lerp(682, 624, t);
    let len = lerp(3.5, 7.5, t) * random(0.8, 1.3);
    let dir = -38 + random(-12, 6);
    brush.set("razor", random() < 0.7 ? "#f7fbff" : "#526270", random(0.22, 0.36));
    brush.line(x, y, x + cos(dir) * len, y + sin(dir) * len);
  }

  // -------------------------------------------------------------------------
  // C. HYPERREAL WET NOSE LEATHER (RHINARIUM) MICRO-PAPILLAE & GLISTENING EDGE
  // -------------------------------------------------------------------------
  // 1. Fine pebbled cobblestone texture (rhinarium papillae) in rotring & 2H
  for (let i = 0; i < 520; i++) {
    let nx = random(620, 668);
    let ny = random(684, 732);

    // Keep inside nose leather polygon bounds
    let dx = (nx - 642) / 24;
    let dy = (ny - 706) / 24;
    if (dx * dx + dy * dy > 1.05) continue;

    // Skip deep inside nostril core
    let ndx = (nx - 648) / 10;
    let ndy = (ny - 707) / 7;
    if (ndx * ndx + ndy * ndy < 0.75) continue;

    // Color of papillae varies from dark slate at border to rose-umber in center
    let distFromTip = dist(nx, ny, 623, 699);
    let col = "#733935";
    if (nx > 654 || ny < 690) {
      col = random() < 0.7 ? "#1d242d" : "#3b353c";
    } else if (distFromTip < 14) {
      col = random() < 0.5 ? "#9c524b" : "#5e302d";
    } else {
      col = random() < 0.5 ? "#87433e" : "#4a2928";
    }

    brush.set(random() < 0.6 ? "rotring" : "2H", col, random(0.18, 0.34));
    let pr = random(0.7, 1.6);
    let ang = random(360);
    brush.line(nx, ny, nx + cos(ang) * pr, ny + sin(ang) * pr);
  }

  // 2. Crisp anatomical definition of the nostril, alar fold, and philtrum cleft
  brush.set("rotring", "#11161d", 0.48);
  // Upper nostril hood curve
  brush.spline([
    [633, 704, 0.4], [642, 697, 1.0], [654, 699, 0.9], [661, 708, 0.5]
  ], 0.35);
  // Nostril lower wet crease & philtrum drop
  brush.spline([
    [635, 708, 0.8], [644, 715, 1.0], [656, 716, 0.6]
  ], 0.3);
  brush.spline([
    [643, 715, 0.7], [644, 728, 1.0], [649, 744, 0.8], [659, 762, 0.4]
  ], 0.3);

  // Anterior profile edge of the nose leather (tack-sharp dark/wet boundary)
  brush.set("rotring", "#2b1d20", 0.42);
  brush.spline([
    [638, 684, 0.5], [625, 691, 0.9], [620, 699, 1.0],
    [624, 710, 0.9], [635, 721, 0.8], [645, 731, 0.7]
  ], 0.35);

  // 3. Glistening Wet Specular Reflections on the Nose Edge, Nostril Rim & Philtrum
  // Cool sky-blue window reflection glaze on the wet curve
  brush.set("whisker_core", "#d6eef8", 0.65);
  brush.spline([
    [624, 692, 0.5], [621, 700, 1.0], [625, 709, 0.8], [634, 718, 0.4]
  ], 0.35);
  brush.spline([
    [637, 711, 0.4], [645, 714, 1.0], [654, 714, 0.5]
  ], 0.3);

  // Pinpoint pure white wet specular glints (cobblestone moisture beads)
  const wetGlints = [
    [622.5, 694, 621.2, 698.5, 0.65],
    [621.2, 700.5, 622.8, 705.0, 0.7],
    [624.5, 707.5, 627.0, 711.0, 0.55],
    [629.0, 713.5, 632.5, 716.8, 0.5],
    [635.5, 719.0, 639.0, 722.5, 0.45],
    // Wet lower rim of the nostril
    [638.0, 711.2, 643.5, 713.5, 0.65],
    [645.5, 713.8, 650.5, 714.0, 0.6],
    [652.5, 713.5, 655.5, 712.2, 0.45],
    // Wet philtrum edge glints
    [643.2, 722.0, 644.0, 727.5, 0.55],
    [644.8, 730.0, 646.5, 736.0, 0.5],
    [647.5, 739.0, 650.0, 744.5, 0.45],
    // Upper nose dome moisture catchlights
    [627.0, 691.5, 630.5, 689.5, 0.5],
    [632.5, 695.0, 635.0, 693.5, 0.42],
    [629.5, 701.0, 632.0, 700.0, 0.45]
  ];
  for (let g of wetGlints) {
    brush.set("whisker_core", "#ffffff", g[4]);
    brush.line(g[0], g[1], g[2], g[3]);
    brush.set("razor", "#ffffff", g[4] * 0.9);
    brush.line(g[0], g[1], g[2], g[3]);
  }

  // Micro wet stipple highlights across the damp nose tip
  for (let i = 0; i < 65; i++) {
    let gx = random(621, 648);
    let gy = random(689, 726);
    if (dist(gx, gy, 626, 703) > 20) continue;
    brush.set("razor", random() < 0.75 ? "#ffffff" : "#e3f4fc", random(0.22, 0.42));
    brush.line(gx, gy, gx + random(0.6, 1.6), gy + random(0.4, 1.4));
  }

  // -------------------------------------------------------------------------
  // D. THE WHISKER PADS (MYSTACIAL PADS): FOLLICLE ROWS & VELVETY MICRO-HAIRS
  // -------------------------------------------------------------------------
  // Define the 4 anatomical mystacial follicle rows: [x, y, sharpness (0..1), size]
  const follicles = [
    // Row 1 (dorsal row under infraorbital line)
    [676, 715, 0.95, 5.5], [702, 718, 0.90, 6.0], [732, 722, 0.72, 6.5], [762, 727, 0.45, 7.0],
    // Row 2 (upper-middle row)
    [666, 734, 1.00, 6.2], [694, 739, 0.96, 7.2], [726, 744, 0.82, 7.8], [760, 749, 0.55, 8.2], [794, 753, 0.30, 8.5],
    // Row 3 (plumpest primary whisker row)
    [664, 755, 1.00, 6.8], [692, 762, 0.98, 8.0], [724, 768, 0.86, 8.5], [758, 773, 0.60, 8.8], [792, 776, 0.35, 9.0],
    // Row 4 (ventral lip-margin row)
    [675, 775, 0.96, 5.8], [704, 784, 0.90, 6.8], [738, 791, 0.75, 7.2], [772, 795, 0.48, 7.5]
  ];

  // 1. First pass: dense short velvety fur covering the plump whisker pad
  // Hairs flow around the cushion of the pad from philtrum/nose down and back
  for (let i = 0; i < 1150; i++) {
    let u = random(); // anterior (0) to posterior (1)
    let v = random(); // upper pad (0) to lower lip margin (1)

    let x = lerp(646, 795, u) + sin(v * 180) * 8;
    let yTop = lerp(702, 725, u);
    let yBot = lerp(742, 808, pow(u, 0.75));
    let y = lerp(yTop, yBot, v);

    // Focus sharpness falls off smoothly as u increases past 0.55
    let sharp = constrain(map(u, 0.0, 0.95, 1.0, 0.15), 0.15, 1.0);

    // Determine hair direction wrapping around the 3D fullness of the mystacial pad
    let baseDir = lerp(12, 32, u) + lerp(-15, 28, v) + random(-7, 7);
    let len = lerp(4.5, 13.5, u) * lerp(0.7, 1.15, v) * random(0.8, 1.2);

    // Color based on 3D lighting on the pad (warm ivory top, cool slate-white bottom, apricot near nose)
    let col = "#f4f7f9";
    let r = random();
    if (u < 0.22 && v < 0.45 && r < 0.45) {
      col = "#dfb292"; // warm rufous-apricot tint near the nose leather
    } else if (v > 0.72) {
      col = r < 0.5 ? "#7a8d9c" : (r < 0.8 ? "#b6c5d0" : "#445464"); // cool lip roll shadow
    } else if (v < 0.25 && u > 0.25) {
      col = r < 0.45 ? "#cfa280" : (r < 0.75 ? "#8b9ba8" : "#f2efe2");
    } else {
      col = r < 0.45 ? "#ffffff" : (r < 0.75 ? "#f5f0dc" : "#cdd8e0");
    }

    let bName = sharp > 0.75 ? (r < 0.45 ? "razor" : "2H") : (sharp > 0.45 ? "HB" : "cpencil");
    let w = lerp(0.75, 0.24, sharp) * random(0.85, 1.15);

    brush.set(bName, col, w);
    let x2 = x + cos(baseDir) * len;
    let y2 = y + sin(baseDir) * len;
    brush.line(x, y, x2, y2);
  }

  // 2. Render the dark tabby mystacial follicle spots & follicle pits
  for (let f of follicles) {
    let fx = f[0];
    let fy = f[1];
    let sharp = f[2];
    let sz = f[3];

    // Dark tabby pigment hairs forming the spot around each follicle
    let hairCount = floor(lerp(18, 42, sharp));
    for (let j = 0; j < hairCount; j++) {
      let ang = random(-35, 55);
      let rad = random(0, sz);
      let hx = fx + cos(ang * 2.5) * rad * 1.15;
      let hy = fy + sin(ang * 2.5) * rad * 0.68;
      let hLen = random(3.5, 8.5) * lerp(1.3, 0.85, sharp);
      let hDir = 16 + (hy - fy) * 3.5 + random(-10, 10);

      let col = random() < 0.6 ? "#1b222b" : (random() < 0.5 ? "#323e4d" : "#5c4238");
      let bName = sharp > 0.7 ? "rotring" : (sharp > 0.45 ? "HB" : "2B");
      let w = lerp(0.68, 0.26, sharp) * random(0.8, 1.2);

      brush.set(bName, col, w);
      brush.line(hx, hy, hx + cos(hDir) * hLen, hy + sin(hDir) * hLen);
    }

    // Crisp micro-hairs parting around the follicle collar on sharp foreground spots
    if (sharp > 0.65) {
      // Deep root dimple shadow
      brush.set("rotring", "#0e1319", 0.42 * sharp);
      brush.line(fx - 1.5, fy, fx + 2.5, fy + 1.0);
      brush.line(fx - 0.5, fy - 1.0, fx + 2.0, fy + 0.5);

      // Luminous white/cream guard hairs ringing the follicle cushion
      for (let k = 0; k < 14; k++) {
        let cAng = random(-70, 80);
        let cx = fx - 2 + cos(cAng) * (sz * 0.65);
        let cy = fy + sin(cAng) * (sz * 0.55);
        let cDir = 14 + sin(cAng) * 22;
        let cLen = random(4, 8);
        brush.set("razor", random() < 0.7 ? "#ffffff" : "#e8eff4", 0.25 * sharp);
        brush.line(cx, cy, cx + cos(cDir) * cLen, cy + sin(cDir) * cLen);
      }
    }
  }

  // 3. Lower Lip, Damp Mouth Edge & Anterior Chin (Mentum)
  // Tack-sharp at the front of the chin (x: 666..730), melting posteriorly (x: 730..820)
  for (let i = 0; i < 460; i++) {
    let u = random(); // 0 = anterior chin tip, 1 = posterior jaw
    let v = random(); // 0 = upper lip cleft edge, 1 = lower chin profile

    let x = lerp(666, 815, u) + random(-4, 4);
    let yTop = lerp(775, 808, u);
    let yBot = lerp(816, 868, u);
    let y = lerp(yTop, yBot, v);

    let sharp = constrain(map(u, 0.0, 0.85, 0.98, 0.15), 0.15, 1.0);
    let dir = lerp(42, 24, u) + v * 16 + random(-8, 8);
    let len = lerp(5.0, 16.0, u) * random(0.75, 1.25);

    let col = "#f2f6f9";
    let r = random();
    if (v < 0.18) {
      // Dark damp lip margin & cool shadow under overhanging whisker pad
      col = r < 0.55 ? "#283340" : (r < 0.85 ? "#546675" : "#87635c");
    } else if (v > 0.78) {
      // Luminous rim light along the bottom edge of the chin catching reflected light
      col = r < 0.6 ? "#ffffff" : (r < 0.85 ? "#f7f0d8" : "#b8c8d4");
    } else {
      col = r < 0.5 ? "#e6eef3" : (r < 0.8 ? "#ffffff" : "#9aaab6");
    }

    let bName = sharp > 0.7 ? (r < 0.5 ? "razor" : "2H") : (sharp > 0.4 ? "HB" : "cpencil");
    let w = lerp(0.85, 0.24, sharp) * random(0.8, 1.15);

    brush.set(bName, col, w);
    brush.line(x, y, x + cos(dir) * len, y + sin(dir) * len);
  }

  // Tiny individual sensory hairs & fuzzy silhouette edge along the anterior lip & chin
  for (let i = 0; i < 85; i++) {
    let t = random();
    let isLip = random() < 0.55;
    let x = isLip ? lerp(645, 705, t) : lerp(667, 725, t);
    let y = isLip ? lerp(732, 796, pow(t, 0.8)) : lerp(782, 836, pow(t, 0.85));
    let dir = isLip ? lerp(155, 115, t) + random(-15, 15) : lerp(145, 105, t) + random(-15, 15);
    let len = random(3.0, 7.5) * (1.1 - t * 0.4);
    brush.set("razor", random() < 0.75 ? "#ffffff" : "#cbd7e0", random(0.2, 0.34));
    brush.line(x, y, x + cos(dir) * len, y + sin(dir) * len);
  }
}

// =============================================================================
// STAGE 6: WHISKERS (VIBRISSAE) — BLURRED GHOSTS TO TACK-SHARP HERO ARCS
// =============================================================================
function drawWhiskersAndMicroDetails() {
  // -------------------------------------------------------------------------
  // 1. OUT-OF-FOCUS WHISKERS (Far side of muzzle & rear cheek vibrissae)
  //    Wide, soft, translucent bands that dissolve into the bokeh discs
  // -------------------------------------------------------------------------
  const blurredWhiskers = [
    // Far-side whiskers peeking out from behind the philtrum/upper lip into the left bokeh
    [[648, 745, 0.6], [510, 765, 0.9], [360, 815, 0.8], [210, 895, 0.3]],
    [[654, 762, 0.7], [495, 795, 1.0], [335, 865, 0.8], [175, 965, 0.2]],
    [[662, 776, 0.6], [525, 825, 0.9], [385, 905, 0.7], [245, 1015, 0.2]],
    // Out-of-focus rear cheek whiskers (sweeping down-left across the jaw)
    [[792, 753, 0.5], [650, 785, 0.9], [480, 855, 0.8], [310, 960, 0.2]],
    [[792, 776, 0.6], [665, 820, 1.0], [510, 905, 0.8], [350, 1030, 0.2]],
    [[772, 795, 0.5], [660, 845, 0.9], [535, 935, 0.7], [410, 1055, 0.2]],
    // Out-of-focus superciliary (brow) vibrissae above the blurred eye
    [[802, 578, 0.5], [735, 515, 0.9], [655, 475, 0.6], [575, 455, 0.2]],
    [[818, 582, 0.4], [760, 505, 0.8], [690, 450, 0.5], [615, 420, 0.1]]
  ];

  for (let bw of blurredWhiskers) {
    // Soft double-edged optical aberration ghost
    brush.set("soft_bloom", "#d8e4ec", 1.35);
    brush.spline(bw, 0.45);

    let shifted = bw.map(pt => [pt[0], pt[1] + 2.5, pt[2] * 0.8]);
    brush.set("cpencil", "#7d93a3", 0.75);
    brush.spline(shifted, 0.45);

    brush.set("cpencil", "#fdfbf0", 0.95);
    brush.spline(bw, 0.45);
  }

  // -------------------------------------------------------------------------
  // 2. MID-FOCUS TRANSITIONAL WHISKERS (Emerging from Row 2/3 mid-pad follicles)
  // -------------------------------------------------------------------------
  const midWhiskers = [
    [[760, 749, 0.9], [615, 762, 1.0], [455, 808, 0.85], [285, 888, 0.4], [145, 985, 0.1]],
    [[758, 773, 0.9], [620, 798, 1.0], [465, 862, 0.85], [305, 962, 0.4], [170, 1075, 0.1]],
    [[738, 791, 0.9], [618, 828, 1.0], [485, 902, 0.80], [345, 1005, 0.35], [225, 1115, 0.1]]
  ];

  for (let mw of midWhiskers) {
    let shadowPts = mw.map(pt => [pt[0], pt[1] + 1.4, pt[2] * 0.85]);
    brush.set("HB", "#384858", 0.48);
    brush.spline(shadowPts, 0.42);

    brush.set("whisker_core", "#f4f8fa", 0.62);
    brush.spline(mw, 0.42);
  }

  // -------------------------------------------------------------------------
  // 3. TACK-SHARP FOREGROUND HERO WHISKERS
  //    Emerging from the sharpest anterior mystacial follicles (x: 664..726)
  //    and sweeping across the blurred watercolor bokeh with razor precision
  // -------------------------------------------------------------------------
  const heroWhiskers = [
    // Short crisp anterior upper whisker (Row 1, follicle at 676, 715)
    {
      pts: [[676, 715, 1.0], [605, 712, 0.95], [525, 724, 0.75], [445, 748, 0.4], [385, 775, 0.08]],
      weight: 0.65
    },
    // Long sweeping upper-mid whisker (Row 1, follicle at 702, 718)
    {
      pts: [[702, 718, 1.0], [585, 718, 1.0], [450, 740, 0.9], [310, 785, 0.65], [175, 852, 0.3], [75, 915, 0.05]],
      weight: 0.78
    },
    // Primary focal whisker A (Row 2, follicle at 666, 734)
    {
      pts: [[666, 734, 1.0], [555, 740, 1.0], [425, 768, 0.92], [285, 822, 0.7], [150, 898, 0.35], [45, 975, 0.06]],
      weight: 0.88
    },
    // Primary focal whisker B (Row 2, follicle at 694, 739)
    {
      pts: [[694, 739, 1.0], [560, 750, 1.05], [405, 788, 0.95], [245, 855, 0.75], [95, 948, 0.35], [15, 1015, 0.08]],
      weight: 0.95
    },
    // Primary focal whisker C (Row 2, follicle at 726, 744)
    {
      pts: [[726, 744, 0.95], [585, 762, 1.0], [425, 808, 0.92], [260, 885, 0.7], [110, 985, 0.32], [20, 1060, 0.06]],
      weight: 0.85
    },
    // Primary focal whisker D — thickest lower-pad arch (Row 3, follicle at 664, 755)
    {
      pts: [[664, 755, 1.05], [545, 772, 1.05], [405, 814, 0.95], [255, 884, 0.75], [115, 978, 0.38], [25, 1055, 0.08]],
      weight: 1.02
    },
    // Primary focal whisker E (Row 3, follicle at 692, 762)
    {
      pts: [[692, 762, 1.05], [565, 786, 1.05], [415, 838, 0.95], [260, 918, 0.75], [115, 1022, 0.38], [25, 1105, 0.08]],
      weight: 0.98
    },
    // Primary focal whisker F (Row 3, follicle at 724, 768)
    {
      pts: [[724, 768, 0.95], [595, 798, 1.0], [445, 858, 0.9], [290, 948, 0.68], [145, 1060, 0.32], [55, 1145, 0.06]],
      weight: 0.86
    },
    // Lower lip-margin whisker G (Row 4, follicle at 675, 775)
    {
      pts: [[675, 775, 1.0], [575, 805, 0.95], [455, 862, 0.82], [330, 942, 0.52], [215, 1035, 0.15]],
      weight: 0.76
    },
    // Lower lip-margin whisker H (Row 4, follicle at 704, 784)
    {
      pts: [[704, 784, 0.95], [598, 820, 0.92], [475, 885, 0.78], [345, 978, 0.45], [230, 1080, 0.12]],
      weight: 0.72
    }
  ];

  for (let hw of heroWhiskers) {
    let pts = hw.pts;
    let w = hw.weight;

    // 1. Crisp dark lower/under-shadow edge in rotring for optical pop against light bokeh
    let underShadow = pts.map((p, idx) => [
      p[0],
      p[1] + lerp(0.9, 1.6, idx / pts.length) * w,
      p[2] * 0.9
    ]);
    brush.set("rotring", "#202b38", 0.36 * w);
    brush.spline(underShadow, 0.42);

    // 2. Subtle upper keratin edge line near the root for cylindrical 3D volume
    let upperEdge = pts.slice(0, 4).map(p => [p[0], p[1] - 0.85 * w, p[2] * 0.75]);
    brush.set("2H", "#5a6c7d", 0.25 * w);
    brush.spline(upperEdge, 0.42);

    // 3. Warm butter-cream translucent keratin body of the whisker shaft
    brush.set("whisker_core", "#fdf8e6", 0.85 * w);
    brush.spline(pts, 0.42);

    // 4. Razor-sharp pure white specular core catching the cool window daylight
    brush.set("razor", "#ffffff", 0.42 * w);
    brush.spline(pts, 0.42);

    // 5. Dark pigment root cuff right where the whisker emerges from the follicle pit
    let r0 = pts[0];
    let r1 = pts[1];
    let rootAng = atan2(r1[1] - r0[1], r1[0] - r0[0]);
    brush.set("rotring", "#161d26", 0.45 * w);
    brush.line(
      r0[0], r0[1] - 0.6,
      r0[0] + cos(rootAng) * 9 * w, r0[1] + sin(rootAng) * 9 * w - 0.4
    );
  }

  // -------------------------------------------------------------------------
  // 4. FINAL MICRO-INCIDENTS: FINE CHIN VIBRISSAE & FLOATING DUST MOTES IN SUNLIGHT
  // -------------------------------------------------------------------------
  // Short, delicate tactile hairs curving down from the sharp anterior chin
  const chinVibrissae = [
    [[678, 808, 0.9], [652, 832, 0.8], [622, 862, 0.3]],
    [[688, 818, 0.9], [662, 846, 0.8], [630, 882, 0.25]],
    [[702, 826, 0.8], [678, 858, 0.7], [648, 896, 0.2]],
    [[670, 796, 0.85], [642, 814, 0.75], [612, 838, 0.2]]
  ];
  for (let cv of chinVibrissae) {
    let sh = cv.map(p => [p[0], p[1] + 0.9, p[2] * 0.8]);
    brush.set("2H", "#465868", 0.26);
    brush.spline(sh, 0.38);
    brush.set("razor", "#ffffff", 0.32);
    brush.spline(cv, 0.38);
  }
}
